/* Generated glossary for CDC/SDV lessons — do not edit by hand (source: scratchpad gloss/*.json). */
window.CDC_GLOSSARY = [{"t":"A/B","vi":"Cơ chế hai bản (A và B) chạy luân phiên. Trong bài thường là <b>A/B partition/slot<\/b>: thiết bị có hai vùng cài phần mềm, cập nhật vào vùng đang không chạy; nếu bản mới lỗi thì khởi động lại vào bản cũ.","aka":["A/B slot","A/B slots"],"cs":true},{"t":"A/B partition","vi":"Hai phân vùng phần mềm song song trên bộ nhớ flash: OTA ghi bản mới vào vùng không hoạt động, boot thử, lỗi thì quay về vùng cũ. Đổi lại tốn gần gấp đôi dung lượng flash trên mỗi xe — một quyết định kinh tế ở A.1.","aka":["A/B partitions","A/B partitioning"]},{"t":"AAOS","vi":"Phiên bản Android chạy trực tiếp trên xe (không cần điện thoại) do Google phát triển. Trong bài, AAOS thường chạy phần IVI/giải trí trong một VM/partition của CDC, cạnh QNX/RTOS lo cluster và chức năng cần thời gian thực.","full":"Android Automotive OS","cs":true},{"t":"Android Automotive","vi":"Tên đầy đủ của AAOS: hệ điều hành Android dành cho xe, chạy ngay trên phần cứng của xe với Vehicle HAL để đọc/ghi dữ liệu xe. Trong bài là lựa chọn phổ biến cho IVI trên CDC.","aka":["Android Automotive OS"]},{"t":"Android","vi":"Hệ điều hành mã nguồn mở của Google, nền trên Linux kernel, có hệ sinh thái app lớn. Trong bài, Android xuất hiện chủ yếu dưới dạng Android Automotive (AAOS) chạy IVI trên CDC.","aka":["Android OS"]},{"t":"abstraction","vi":"Sự <b>trừu tượng hóa<\/b>: che chi tiết bên dưới sau một giao diện chung. Trong bài: lớp abstraction giúp thay phần cứng/supplier bên dưới mà phần mềm phía trên không phải sửa (ví dụ HAL).","aka":["abstractions"]},{"t":"abstraction layer","vi":"Lớp trừu tượng: lớp trung gian che chi tiết của phần bên dưới. Trong bài là cách giữ đường lui cho OEM — đổi chip, driver hay supplier mà app phía trên vẫn chạy nguyên.","aka":["abstraction layers"]},{"t":"Hardware Abstraction Layer","vi":"Lớp che chi tiết phần cứng (HAL): phần mềm phía trên gọi một giao diện chung thay vì gọi thẳng driver. Trong bài: Vehicle HAL của Android cho app đọc/ghi dữ liệu xe dưới dạng property.","aka":["hardware abstraction"]},{"t":"acceptance","vi":"Sự <b>chấp nhận<\/b>. Trong bài xuất hiện trong <i>acceptance criteria<\/i> (tiêu chí nghiệm thu) và <i>risk acceptance<\/i> (chấp nhận rủi ro còn lại, phải có người đủ thẩm quyền ký)."},{"t":"acceptance criteria","vi":"Tiêu chí chấp nhận/nghiệm thu: điều kiện đo được để nói một requirement hay feature đã đạt (ví dụ “P95 latency &lt; 100 ms dưới tải”). Không có acceptance criteria thì không test được, chỉ tranh cãi.","aka":["acceptance criterion"]},{"t":"risk acceptance","vi":"Chấp nhận rủi ro: quyết định chính thức để lại một rủi ro chưa xử lý hết (residual risk), có lý do, hạn và người có thẩm quyền ký. Trong bài là một nhánh hợp lệ khi xử lý CVE/defect, không phải “bỏ qua”."},{"t":"access","vi":"Quyền/khả năng <b>truy cập<\/b> vào dữ liệu, tài nguyên hay mã nguồn. Trong bài: source access (được xem mã nguồn của supplier), access control (kiểm soát ai được đọc/ghi), memory access.","aka":["accesses"]},{"t":"access control","vi":"Kiểm soát truy cập: cơ chế quyết định ai/app nào được đọc, ghi hay gọi chức năng gì (permission, phân quyền). Trong bài là control chống lộ dữ liệu và chống gửi lệnh trái phép."},{"t":"action","vi":"<b>Hành động<\/b> cụ thể cần làm. Trong bài: action sau phân tích (đổi forecast/scope/architecture), <i>failure action<\/i> (khi gate fail thì chặn hay quay lại bước nào).","aka":["actions"]},{"t":"failure action","vi":"Hành động khi một quality gate hay kiểm tra bị fail: chặn release, quay lại bước nào, ai xử lý. Mỗi gate trong bài phải ghi rõ failure action để không ai “cho qua” tùy tiện."},{"t":"adapter","vi":"<b>Bộ chuyển đổi<\/b>: lớp code trung gian dịch giữa hai interface khác nhau. Trong bài: viết adapter mới cho từng loại xe để phần API cho app giữ nguyên; adapter/facade trong chiến lược migration strangler.","aka":["adapters"]},{"t":"admission","vi":"Sự <b>cho vào<\/b>/chấp nhận. Trong bài dùng trong <i>admission control<\/i>: chỉ cho workload hoặc feature mới chạy nếu nó nằm trong budget tài nguyên đã duyệt."},{"t":"admission control","vi":"Kiểm soát chấp nhận tải: từ chối cài/khởi chạy workload mới nếu làm vượt budget CPU, GPU, bộ nhớ đã phê duyệt. Trong bài là cách bảo vệ cluster và chức năng critical khi CDC đông việc."},{"t":"ADR","vi":"Biên bản quyết định kiến trúc: ghi context, drivers, alternatives, decision, trade-off, risk, evidence và điều kiện xem lại. Trong bài là sản phẩm chính để bảo vệ và lưu vết quyết định (A.7, B.2).","aka":["ADRs"],"full":"Architecture Decision Record","cs":true},{"t":"Architecture Decision Record","vi":"Tên đầy đủ của ADR: tài liệu ngắn ghi lại một quyết định kiến trúc quan trọng — vì sao chọn, đã cân nhắc gì, chấp nhận rủi ro gì — để người sau hiểu và không tranh luận lại từ đầu.","aka":["Architecture Decision Records","architecture decision"]},{"t":"affected","vi":"<b>Bị ảnh hưởng<\/b>. Trong bài: affected components/variants (thành phần bị một thay đổi chạm tới), affected version, affected population/scope (số xe thực sự chạy bản lỗi)."},{"t":"affected population","vi":"Số xe bị ảnh hưởng bởi một lỗi. Trong A.1 dùng để ước lượng thiệt hại kỳ vọng = affected population × xác suất lỗi × chi phí xử lý trung bình."},{"t":"affected scope","vi":"Phạm vi bị ảnh hưởng: số xe/variant thực sự chạy version có lỗ hổng. Trong A.3, risk exposure ≈ likelihood × impact × affected scope — và SBOM chính xác là thứ cho biết con số này."},{"t":"affinity","vi":"<b>Ràng buộc/ghim<\/b> một tác vụ hay interrupt vào CPU core cụ thể (CPU affinity, IRQ/interrupt affinity). Trong bài dùng để giữ core cho việc real-time và tránh nhiễu giữa các workload."},{"t":"CPU affinity","vi":"Ghim một thread/tác vụ vào một hoặc vài CPU core cụ thể. Trong bài là một công cụ phân phối tài nguyên, giúp tác vụ critical không bị tác vụ khác chen vào core."},{"t":"interrupt affinity","vi":"Chỉ định interrupt (IRQ) của thiết bị nào được xử lý trên core nào. Trong bài: interrupt của device dùng chung có thể làm trễ guest critical nếu không cấu hình affinity cẩn thận.","aka":["IRQ affinity"]},{"t":"age","vi":"<b>Tuổi/độ cũ<\/b> của dữ liệu: thời gian từ khi giá trị được tạo đến khi được dùng. Trong bài: <i>max age<\/i> (dữ liệu cũ tối đa bao lâu vẫn dùng được), <i>frame age<\/i> (độ cũ của frame trên màn hình)."},{"t":"max age","vi":"Độ cũ tối đa cho phép của một dữ liệu (ví dụ tín hiệu tốc độ); quá ngưỡng thì coi là stale, phải xử lý theo policy (báo lỗi, dùng giá trị mặc định an toàn). Là một mục bắt buộc trong interface contract."},{"t":"frame age","vi":"Độ cũ của frame: thời gian từ khi state/input được tạo (ví dụ lúc nhận giá trị tốc độ) đến khi frame chứa nó hiện lên màn hình. Trong C.2, frame age quan trọng hơn fps đối với cluster."},{"t":"agreement","vi":"<b>Thỏa thuận<\/b>/hợp đồng. Trong bài: DIA (development interface agreement – chia trách nhiệm phát triển OEM–supplier), SLA (cam kết thời hạn dịch vụ/vá lỗi), warranty agreement.","aka":["agreements"]},{"t":"Service Level Agreement","vi":"Thỏa thuận mức dịch vụ (SLA): cam kết đo được giữa hai bên, ví dụ supplier phải vá lỗ hổng nghiêm trọng trong bao nhiêu ngày. Trong bài là điều khoản hợp đồng giúp bảo trì dài hạn."},{"t":"allocation","vi":"Sự <b>phân bổ<\/b>. Trong bài: allocation requirement xuống component (requirement nào do khối nào chịu), và phân bổ tài nguyên (CPU, RAM, budget) cho workload — tĩnh hay động.","aka":["allocations"]},{"t":"alternative","vi":"<b>Phương án thay thế<\/b>. Trong ADR và recommendation phải ghi các alternatives đã cân nhắc và vì sao bị loại, để review thấy trade-off và không lặp lại tranh luận cũ.","aka":["alternatives"]},{"t":"analysis","vi":"Sự <b>phân tích<\/b>. Trong bài có nhiều loại: impact analysis, root cause analysis (RCA), sensitivity analysis, static analysis, failure analysis — mỗi loại trả lời một câu hỏi quyết định cụ thể.","aka":["analyses"]},{"t":"impact analysis","vi":"Phân tích tác động: trước khi đổi gì, lần theo trace để biết thay đổi chạm requirement, component, variant, test, evidence nào. Trong bài là bước bắt buộc của change control.","aka":["change impact analysis"]},{"t":"sensitivity analysis","vi":"Phân tích độ nhạy: thay từng giả định (volume, giá chip, số variant…) để xem kết luận thay đổi ra sao, và ở ngưỡng nào thì phương án đảo chiều. Trong A.1 dùng cho quyết định kinh tế."},{"t":"static analysis","vi":"Phân tích tĩnh: công cụ đọc mã nguồn tìm lỗi/vi phạm quy tắc mà không cần chạy chương trình (ví dụ SAST cho lỗi bảo mật). Trong bài là một bước kiểm tra ở giai đoạn implementation."},{"t":"failure analysis","vi":"Phân tích lỗi: tìm hiểu một hỏng hóc xảy ra thế nào, vì sao và lan tới đâu. Trong bài là phần bắt buộc khi đo hiệu năng/hiển thị: không chỉ đo khi chạy đúng mà cả khi có sự cố."},{"t":"analytics","vi":"<b>Phân tích dữ liệu<\/b> (thường quy mô lớn). Trong bài: fleet analytics trên cloud — gom dữ liệu từ nhiều xe để phát hiện lỗi, cải tiến; là workload không critical, thường chạy cloud hoặc bị cắt đầu tiên khi quá tải."},{"t":"fleet analytics","vi":"Phân tích dữ liệu từ cả đội xe (fleet) trên cloud: thống kê lỗi, hành vi sử dụng, hiệu năng để ra quyết định cải tiến. Cần consent, tối thiểu hóa dữ liệu và bảo vệ privacy."},{"t":"API","vi":"Giao diện lập trình: tập hàm/dịch vụ mà một phần mềm công bố cho phần khác gọi. Trong bài, API phải có version, owner và quy tắc tương thích để platform nâng cấp mà app không vỡ.","aka":["APIs"],"full":"Application Programming Interface","cs":true},{"t":"public API","vi":"API công khai cho bên ngoài (ví dụ app bên thứ ba) dùng. Đổi nó rất tốn vì không kiểm soát được hết consumer — trong B.2 là ví dụ quyết định “cửa một chiều”, khó đảo ngược.","aka":["public APIs"]},{"t":"app","vi":"<b>Ứng dụng<\/b> (application). Trong bài: app trên IVI/AAOS (bản đồ, nhạc, app bên thứ ba) hoặc app cluster; nằm ở lớp trên cùng của stack, gọi service/API của platform.","aka":["apps"]},{"t":"app ecosystem","vi":"Hệ sinh thái ứng dụng: kho app, công cụ và nhà phát triển quanh một nền tảng. Trong bài là lý do chọn Android Automotive cho IVI — có sẵn nhiều app — nhưng kéo theo rủi ro bảo mật và tương thích."},{"t":"application","vi":"<b>Ứng dụng<\/b>; cũng là <b>lớp application<\/b> trên cùng của stack, nơi chứa logic tính năng. Ngoài ra “application” còn có nghĩa “áp dụng” (Practical application).","aka":["applications"]},{"t":"Practical application","vi":"Phần “áp dụng thực tế” ở cuối mỗi bài: câu hỏi để bạn đem kiến thức áp vào feature/dự án đang chọn của mình."},{"t":"applied","vi":"<b>Được áp dụng<\/b>/ứng dụng. Trong khóa học chủ yếu thấy trong tên <i>Applied Workshop<\/i> — buổi thực hành áp dụng kiến thức của unit."},{"t":"Applied Workshop","vi":"Buổi thực hành ứng dụng ở cuối mỗi unit, chấm theo rubric của Lesson 2 và Learning Plan: bạn dùng bối cảnh dự án đã chọn để làm bài, rồi trình bày và bảo vệ."},{"t":"approval","vi":"Sự <b>phê duyệt<\/b>. Trong bài: approval để release, approval của business, và <i>type approval<\/i> (phê duyệt kiểu xe của cơ quan quản lý). Approval phải có người đủ thẩm quyền và lưu lại evidence.","aka":["approvals"]},{"t":"type approval","vi":"Phê duyệt kiểu xe: cơ quan quản lý xác nhận một mẫu xe đạt quy định trước khi được bán (homologation), ví dụ UNECE R155/R156 về cybersecurity và software update."},{"t":"approve","vi":"<b>Phê duyệt<\/b>, chấp thuận chính thức. Trong bài: ai approve thay đổi, release hay chấp nhận residual risk phải rõ theo decision rights; thứ được approve phải đúng là thứ được phát hành.","aka":["approved","approves","approving"]},{"t":"approver","vi":"<b>Người phê duyệt<\/b>. Trong bài: mỗi ADR, waiver, decision đều phải có approver đích danh có authority, khác với owner (người chịu trách nhiệm làm).","aka":["approvers"]},{"t":"architect","vi":"<b>Kiến trúc sư<\/b> (phần mềm/hệ thống). Trong khóa học là vai trò Solution Architect (SA): biến nhu cầu và constraint thành giải pháp triển khai được, chốt contract, timing, isolation, evidence.","aka":["architects"]},{"t":"architecture","vi":"<b>Kiến trúc<\/b>: cách chia hệ thống thành thành phần, quan hệ giữa chúng và các quyết định khó đổi về sau. Trong bài gồm E/E architecture của xe, software architecture của CDC và architecture governance.","aka":["architectures"]},{"t":"system architecture","vi":"Kiến trúc hệ thống: phân rã cả hệ (phần cứng + phần mềm + mạng) thành các khối và interface, phân bổ requirement cho từng khối. Là bước giữa system requirement và software design trong V-Model."},{"t":"architecture review","vi":"Buổi rà soát kiến trúc: người có chuyên môn kiểm tra quyết định, trade-off, risk và evidence trước khi chốt. Trong bài, review tốt hỏi cả chi phí vòng đời, không chỉ “chạy được không”.","aka":["architecture reviews"]},{"t":"architecture review board","vi":"Hội đồng duyệt kiến trúc: nhóm có quyền quyết định các thay đổi kiến trúc ảnh hưởng nhiều team/domain. Trong A.7 là cấp escalate khi vấn đề vượt quyền của một team.","aka":["ARB"]},{"t":"architecture governance","vi":"Quản trị kiến trúc: quy tắc ai quyết định gì, review khi nào, ghi lại thế nào (ADR) và theo dõi quyết định qua vòng đời. Trong bài đây là việc kỹ thuật, không phải thủ tục hành chính."},{"t":"architecture debt","vi":"Nợ kiến trúc: các lối tắt ở mức kiến trúc (hai bản service trùng chức năng, interface tạm…) chấp nhận để kịp lịch. Được phép nếu ghi sổ có owner, biết ai trả và trả khi nào (A.7)."},{"t":"area","vi":"<b>Khu vực<\/b>, vùng. Trong bài gặp chủ yếu trong tên <i>Controller Area Network<\/i> (CAN) — mạng truyền tín hiệu giữa các ECU trong xe.","aka":["areas"]},{"t":"Controller Area Network","vi":"Tên đầy đủ của CAN: bus truyền frame ngắn giữa các ECU trong xe, băng thông thấp nhưng tin cậy. Trong bài tín hiệu tốc độ đi từ CAN qua gateway vào CDC."},{"t":"argument","vi":"<b>Lập luận<\/b> có căn cứ. Trong bài: <i>safety/security argument<\/i> — chuỗi lập luận kèm evidence chứng minh hệ thống đủ an toàn/bảo mật; và lập luận khi bảo vệ quyết định trước review.","aka":["arguments"]},{"t":"safety argument","vi":"Lập luận an toàn: chuỗi lý lẽ có evidence chứng minh hệ thống an toàn trong điều kiện xác định. Một thay đổi hay update có thể làm safety argument cũ không còn hợp lệ."},{"t":"artifact","vi":"<b>Sản phẩm công việc<\/b> được quản lý: tài liệu, model, code, test, binary, report… Trong bài, artifact phải có version, owner và gắn baseline thì mới dùng làm evidence được.","aka":["artifacts"]},{"t":"asset","vi":"<b>Tài sản<\/b>. Trong bảo mật (A.3) là thứ cần bảo vệ (dữ liệu, key, lệnh điều khiển); trong quality là thứ dùng lại được (regression test, checklist); trong digital twin là đối tượng thật (xe, ECU).","aka":["assets"]},{"t":"assignment","vi":"<b>Bài tập lớn<\/b> phải nộp của khóa học (Assignment 1, 2…). Mỗi bài đọc ghi rõ phục vụ assignment nào để bạn biết kiến thức sẽ được chấm ở đâu.","aka":["assignments"]},{"t":"assumption","vi":"<b>Giả định<\/b>: điều coi là đúng khi tính toán/quyết định mà chưa chứng minh. Trong bài: ghi rõ assumption (số variant, volume, supplier kịp…) để khi lệch biết phải xem lại quyết định nào.","aka":["assumptions"]},{"t":"assumption of use","vi":"Điều kiện sử dụng mà supplier giả định khi chứng nhận sản phẩm (ví dụ hypervisor). Certificate chỉ còn giá trị nếu bạn dùng đúng các điều kiện này — A.6.","aka":["assumptions of use"]},{"t":"attribute","vi":"<b>Thuộc tính<\/b>. Trong bài hay gặp trong <i>quality attribute<\/i>; cũng là thuộc tính của requirement (owner, version…) hay của dữ liệu.","aka":["attributes"]},{"t":"quality attribute","vi":"Thuộc tính chất lượng: hệ thống phải tốt đến mức nào — latency, availability, safety, security, maintainability… Đây thường là driver chính của quyết định kiến trúc, không phải chức năng.","aka":["quality attributes","quality-attribute"]},{"t":"quality attribute scenario","vi":"Kịch bản chất lượng đo được: stimulus, nguồn, môi trường, phản hồi và thước đo (ví dụ burst tín hiệu tốc độ khi bus tải cao → hiển thị trong X ms). Dùng để so phương án ở B.2.","aka":["quality attribute scenarios","quality-attribute scenario"]},{"t":"audio","vi":"<b>Âm thanh<\/b>. Trong bài: audio stack/driver/HAL của CDC phát nhạc, cuộc gọi và chime cảnh báo; C.3 phân tích audio system architecture, nơi âm cảnh báo phải được ưu tiên hơn giải trí."},{"t":"audit","vi":"<b>Kiểm toán<\/b>/đánh giá độc lập xem quy trình và evidence có đúng thực tế. Trong bài: audit pass nhưng defect vẫn lọt nếu evidence chỉ “điền cho đủ”; <i>audit log<\/i> để truy vết ai làm gì.","aka":["audits"]},{"t":"audit log","vi":"Nhật ký kiểm toán: ghi lại không sửa được ai đã làm hành động gì, lúc nào (ví dụ gửi lệnh mở khóa từ xa). Là control chống Repudiation trong STRIDE.","aka":["audit logs"]},{"t":"authentication","vi":"<b>Xác thực<\/b>: kiểm tra bên gửi/người dùng đúng là ai họ nói. Trong bài là control giảm likelihood tấn công, chặn spoofing — ví dụ chỉ chấp nhận lệnh/dữ liệu từ nguồn đã xác thực."},{"t":"authority","vi":"<b>Thẩm quyền<\/b>: quyền quyết định chính thức (ví dụ release authority, close authority). Cũng có thể chỉ cơ quan quản lý. Trong bài: biết ranh giới authority để biết lúc nào phải escalate.","aka":["authorities"]},{"t":"release authority","vi":"Người/nhóm có thẩm quyền ký cho phát hành một bản phần mềm và chấp nhận residual risk tại gate release."},{"t":"automotive","vi":"Thuộc ngành <b>ô tô<\/b>. Trong bài dùng như tính từ: automotive software, automotive Ethernet, automotive cybersecurity — nhấn mạnh yêu cầu riêng của xe: vòng đời dài, safety, quy định."},{"t":"Automotive Ethernet","vi":"Ethernet dành cho xe (dây và chuẩn chịu được môi trường ô tô), băng thông cao hơn CAN nhiều. Trong bài là backbone cần có cho kiến trúc zonal/central và dữ liệu lớn."},{"t":"AUTOSAR","vi":"Chuẩn kiến trúc phần mềm ô tô do liên minh hãng xe và supplier lập ra. <b>Classic<\/b>: cho ECU nhúng, cấu hình tĩnh lúc build; <b>Adaptive<\/b>: cho central compute, service-oriented, triển khai động.","full":"AUTomotive Open System ARchitecture","cs":true},{"t":"AUTOSAR Adaptive","vi":"Nhánh AUTOSAR cho máy tính hiệu năng cao (domain/central compute): chạy trên OS POSIX, giao tiếp service-oriented (SOME/IP…), cho phép cập nhật và triển khai động."},{"t":"AUTOSAR Classic","vi":"Nhánh AUTOSAR truyền thống cho ECU nhúng: phần mềm cấu hình tĩnh lúc build (BSW, RTE), timing xác định, mạnh về safety và hệ sinh thái supplier lâu năm."},{"t":"availability","vi":"<b>Tính sẵn sàng<\/b>: hệ thống dùng được khi cần (tỷ lệ thời gian hoạt động). Là một quality attribute và là chữ A trong CIA của bảo mật; ví dụ cluster phải hiển thị liên tục."},{"t":"average","vi":"<b>Trung bình<\/b>. Bài nhắc nhiều lần: average latency không chứng minh được deadline — phải xem tail (P99, max) hoặc WCET dưới tải thật."},{"t":"average latency","vi":"Độ trễ trung bình. Con số đẹp lúc idle nhưng che mất các lần trễ dài hiếm gặp; trong bài phải dùng tail latency/worst case dưới tải để kết luận về deadline."},{"t":"backend","vi":"Hệ thống <b>phía máy chủ<\/b> (cloud) phục vụ xe: OTA server, telematics, lưu và xử lý dữ liệu. Trong bài: backend tạo chi phí vận hành liên tục sau SOP và có thể đổi API làm ảnh hưởng xe.","aka":["backends","back-end"]},{"t":"backlog","vi":"<b>Danh sách việc tồn<\/b> chờ làm (debt backlog, backlog cải tiến). Trong C.2, <i>queue backlog<\/i> còn nghĩa là hàng đợi bị ứ đọng do bên xử lý chậm hơn bên đưa vào.","aka":["backlogs"]},{"t":"backpressure","vi":"<b>Áp lực ngược<\/b>: khi hàng đợi đầy, báo/buộc producer chậm lại thay vì bỏ dữ liệu. Là một trong các full policy của buffer (cạnh drop-oldest, drop-newest); chọn theo ý nghĩa của dữ liệu.","aka":["back-pressure"]},{"t":"backward","vi":"<b>Ngược về sau<\/b>. Trong bài gần như luôn đi trong <i>backward compatibility<\/i>: bản mới vẫn làm việc được với bên đang dùng bản cũ."},{"t":"backward compatibility","vi":"Tương thích ngược: bản mới của interface/service vẫn phục vụ đúng consumer cũ (ví dụ thêm field nhưng không đổi field cũ). Trong xe nhiều ECU không cập nhật cùng lúc nên đây là quy tắc bắt buộc.","aka":["backward compatible","backward-compatible","backwards compatibility"]},{"t":"bandwidth","vi":"<b>Băng thông<\/b>: lượng dữ liệu truyền được mỗi giây. Trong bài: băng thông mạng (CAN vs Ethernet), memory/DRAM bandwidth dùng chung giữa CPU, GPU, display — một nguồn contention khó thấy."},{"t":"memory bandwidth","vi":"Băng thông bộ nhớ (DRAM): lượng dữ liệu đọc/ghi RAM mỗi giây. CPU, GPU, display, camera dùng chung nên một bên ngốn nhiều sẽ làm bên khác chậm, dù CPU còn rảnh."},{"t":"base","vi":"<b>Nền<\/b>/cơ sở. Trong bài: <i>trusted base<\/i> (phần phải tin tưởng tuyệt đối, càng nhỏ càng dễ chứng nhận) và <i>time base<\/i> (gốc thời gian chung để so mốc giữa các thiết bị)."},{"t":"time base","vi":"Gốc thời gian chung mà các thiết bị/domain dùng để đóng timestamp. Không có time base chung (hoặc offset đã biết) thì không so được thời điểm event giữa các ECU/VM — C.3, C.4."},{"t":"baseline","vi":"<b>Mốc chuẩn<\/b> đã được chốt: tập artifact có version cụ thể làm điểm tựa để release, so sánh hay quản lý thay đổi. Cũng chỉ số đo gốc (ví dụ latency đã baseline) để so lần đo sau.","aka":["baselines","baselined"]},{"t":"behavior","vi":"<b>Hành vi<\/b>: cách hệ thống phản ứng trong từng tình huống. Trong bài: degraded behavior, failure behavior, offline behavior — phải được định nghĩa rõ, không chỉ hành vi khi mọi thứ bình thường.","aka":["behaviors","behaviour"]},{"t":"degraded behavior","vi":"Hành vi suy giảm có kiểm soát: khi thiếu tài nguyên hoặc thành phần lỗi, hệ thống bỏ bớt tính năng phụ nhưng giữ chức năng quan trọng (ví dụ cluster vẫn hiện tốc độ, cảnh báo).","aka":["degradation behavior"]},{"t":"failure behavior","vi":"Hành vi khi lỗi: hệ thống làm gì khi timeout, mất dữ liệu hay thành phần chết (báo lỗi, giá trị mặc định an toàn, restart…). Là phần bắt buộc của interface contract trong bài."},{"t":"bench","vi":"<b>Bàn thử nghiệm<\/b>: bộ phần cứng trong phòng lab để test (ví dụ HIL bench nối ECU thật với môi trường mô phỏng). Bài lưu ý: pass trên bench chưa chắc pass trên xe thật.","aka":["benches"]},{"t":"benchmark","vi":"<b>Phép đo chuẩn<\/b> hiệu năng theo kịch bản cố định để so sánh (trước/sau thay đổi, giữa các phương án). Trong bài: phải chọn workload, metric, điều kiện trước khi đo, nếu không benchmark dễ gây hiểu sai.","aka":["benchmarks","benchmarking"]},{"t":"bill","vi":"<b>Danh sách/hóa đơn<\/b>. Trong bài chỉ gặp trong Bill of Materials (BOM – danh sách và giá linh kiện mỗi xe) và Software Bill of Materials (SBOM).","aka":["bills"]},{"t":"Bill of Materials","vi":"BOM: danh sách và giá linh kiện trên mỗi chiếc xe. Chi phí BOM nhân theo số xe bán ra, khác với chi phí NRE trả một lần — trọng tâm kinh tế của A.1."},{"t":"Software Bill of Materials","vi":"SBOM: danh sách mọi thành phần phần mềm (kể cả thư viện mã nguồn mở) và version trong một build. Trong A.3 dùng để trả lời nhanh “xe nào bị CVE này ảnh hưởng”."},{"t":"binary","vi":"<b>File chạy đã biên dịch<\/b> (không phải mã nguồn). Trong bài: supplier có thể chỉ giao black-box binary; phải chứng minh binary đang phát hành đúng là thứ đã test (provenance).","aka":["binaries"]},{"t":"bit","vi":"<b>Bit<\/b>: đơn vị nhỏ nhất của dữ liệu số (0 hoặc 1). Trong bài: parser phải biết lấy bit nào trong frame CAN, CRC phát hiện bit hỏng, <i>bit depth<\/i> là số bit mỗi mẫu âm thanh.","aka":["bits"]},{"t":"bit depth","vi":"Số bit dùng cho mỗi mẫu âm thanh PCM (ví dụ 16 hoặc 24 bit); càng cao thì dải động càng lớn. Cùng sample rate và số kênh, nó quyết định kích thước buffer audio trong C.3."},{"t":"blast","vi":"Vụ <b>nổ<\/b>. Trong bài chỉ dùng trong cụm <i>blast radius<\/i> — phạm vi bị ảnh hưởng khi một thành phần hỏng."},{"t":"blast radius","vi":"Bán kính ảnh hưởng: khi một thành phần hỏng (hypervisor, core service, chip trung tâm), bao nhiêu chức năng/xe bị kéo theo. Gom nhiều thứ lên một chỗ thì rẻ hơn nhưng blast radius lớn hơn."},{"t":"block","vi":"Có hai nghĩa: (1) danh từ: <b>khối<\/b> (block diagram – sơ đồ khối); (2) động từ: <b>chặn<\/b>/bắt chờ — ví dụ critical không được block vì chờ non-critical; gate fail thì block release.","aka":["blocks","blocked"]},{"t":"block diagram","vi":"Sơ đồ khối: vẽ các thành phần chính và đường nối giữa chúng. Bài A.4 nhắc một block diagram duy nhất không trả lời được “ai sở hữu”, “chạy ở đâu” — cần nhiều viewpoint.","aka":["block diagrams"]},{"t":"blocking","vi":"<b>Chặn/bắt chờ<\/b>: thao tác khiến thread phải đứng đợi (I/O, lock, gọi đồng bộ). Trong bài, blocking ẩn là nguyên nhân hay gặp của giật hình (jank) và tail latency."},{"t":"board","vi":"Hai nghĩa: (1) <b>bo mạch<\/b> phần cứng (board có SoC, BSP cho board); (2) <b>hội đồng<\/b> (change board, review board – nhóm duyệt thay đổi). Ngoài ra <i>on-board<\/i> là “trên xe”.","aka":["boards"]},{"t":"Board Support Package","vi":"BSP: gói phần mềm nền cho một board cụ thể — bootloader, cấu hình kernel, driver. Do hãng chip/Tier cung cấp; khi BSP hết hỗ trợ thì cả CDC khó bảo trì tiếp."},{"t":"boot","vi":"<b>Khởi động<\/b> hệ thống: từ bật nguồn qua bootloader, OS/VM, driver, service tới khi chức năng sẵn sàng. Trong bài: boot time, secure boot, boot order ảnh hưởng trực tiếp đến kiến trúc.","aka":["boots","booting","booted"]},{"t":"boot time","vi":"Thời gian khởi động: từ bật nguồn đến khi chức năng cụ thể sẵn sàng (ví dụ cluster hiện tốc độ, camera lùi). Requirement boot time chặt có thể buộc đổi boot sequence và cách chia service."},{"t":"cold boot","vi":"Khởi động nguội: bật từ trạng thái tắt hoàn toàn, không có gì trong bộ nhớ/cache. Thường chậm nhất nên phải đo cold boot riêng, không chỉ đo khi hệ thống đã chạy sẵn (warm)."},{"t":"secure boot","vi":"Khởi động an toàn: mỗi tầng kiểm chữ ký số của tầng tiếp theo trước khi chạy (chain of trust), để không nạp được phần mềm bị sửa. Là control bảo mật cơ bản cho CDC."},{"t":"boot flow","vi":"Trình tự khởi động: thứ tự các tầng và service được nạp, cái nào chờ cái nào. Trong bài, chức năng cần sẵn sàng sớm (cluster, camera lùi) phải có “làn sớm” trong boot flow."},{"t":"chain of trust","vi":"Chuỗi tin cậy: mỗi tầng khởi động xác minh chữ ký của tầng sau (ROM → bootloader → OS…), nên chỉ phần mềm hợp lệ mới chạy được. Là nền của secure boot."},{"t":"bootloader","vi":"<b>Trình khởi động<\/b>: chương trình nhỏ chạy đầu tiên khi bật nguồn, nạp OS/hypervisor và (với secure boot) kiểm chữ ký. Thuộc BSP; cũng tham gia chọn slot A/B khi OTA.","aka":["bootloaders","boot loader"]},{"t":"bottleneck","vi":"<b>Nút cổ chai<\/b>: điểm hẹp nhất giới hạn tốc độ cả hệ thống/quy trình. Trong bài: thêm người/máy chỉ hiệu quả khi bottleneck là capacity; HIL bench hay facade cũng có thể thành bottleneck.","aka":["bottlenecks"]},{"t":"boundary","vi":"<b>Ranh giới<\/b>/phạm vi: chỗ phân chia trách nhiệm, quyền tin cậy hay phạm vi tính toán (trust boundary, safety boundary, cost boundary). Trong bài, lỗi và tranh chấp thường nằm ngay ở boundary.","aka":["boundaries"]},{"t":"trust boundary","vi":"Ranh giới tin cậy: chỗ dữ liệu đi từ vùng ít tin cậy sang vùng tin cậy hơn (cloud → telematics, app bên thứ ba → service). Mỗi trust boundary phải có xác thực, kiểm tra dữ liệu và phân quyền.","aka":["trust boundaries"]},{"t":"cost boundary","vi":"Phạm vi chi phí tính vào khi so phương án (có tính maintenance, validation, warranty không). Trong A.1, cost boundary phải giống nhau cho mọi phương án, nếu không là so táo với cam."},{"t":"data boundary","vi":"Ranh giới dữ liệu: quy định dữ liệu nào được phép đưa vào một hệ thống (ở B.4 là công cụ AI) và dữ liệu nào không, cùng môi trường/tenant đã được duyệt."},{"t":"breaking","vi":"<b>Phá vỡ<\/b> (tương thích). Một thay đổi <i>breaking<\/i> làm consumer cũ chạy sai hoặc hỏng; trong bài phải ra version mới chạy song song thay vì sửa đè."},{"t":"breaking change","vi":"Thay đổi phá tương thích: đổi unit, bỏ field, đổi ý nghĩa dữ liệu khiến bên dùng cũ sai. Trong xe nhiều ECU cập nhật lệch nhau nên breaking change phải đi qua version mới và contract test.","aka":["breaking changes"]},{"t":"BSP","vi":"Gói phần mềm nền cho một board: bootloader, cấu hình kernel, driver. Trong bài: BSP gắn chặt với hãng chip; ngày hết hỗ trợ BSP là rủi ro bảo trì và lock-in lớn.","aka":["BSPs"],"full":"Board Support Package","cs":true},{"t":"budget","vi":"<b>Ngân sách<\/b>: (1) tiền; (2) trong kỹ thuật là <b>phần tài nguyên được cấp<\/b> có giới hạn — latency budget, CPU/RAM/GPU budget. Mỗi khối phải nằm trong budget đã duyệt và có số đo chứng minh.","aka":["budgets","budgeting"]},{"t":"latency budget","vi":"Ngân sách độ trễ: tổng độ trễ cho phép end-to-end (ví dụ từ CAN tới màn hình) chia nhỏ cho từng chặng. Mỗi chặng có owner và số đo; vượt ở một chặng thì phải lấy bớt chặng khác.","aka":["latency budgets"]},{"t":"timing budget","vi":"Ngân sách thời gian: phần thời gian mỗi khối/chặng được phép dùng để cả chuỗi kịp deadline. Đó là phân bổ, chưa phải bằng chứng — phải đo trên target dưới tải thật.","aka":["timing budgets","time budget"]},{"t":"resource budget","vi":"Ngân sách tài nguyên: lượng CPU, RAM, memory bandwidth, GPU, storage, network cấp cho từng workload. Phần critical được dành riêng, phần non-critical có trần — trọng tâm A.6 và Assignment 1.","aka":["resource budgets"]},{"t":"maintenance budget","vi":"Ngân sách bảo trì: tiền và người dành cho sửa lỗi, vá bảo mật, cập nhật sau SOP. Một shared service chỉ nên chấp nhận khi đã có owner và maintenance budget."},{"t":"buffer","vi":"<b>Vùng đệm<\/b>: vùng nhớ giữ dữ liệu tạm giữa hai bên chạy lệch tốc độ (frame ảnh, mẫu âm thanh, message). Nhiều buffer thì mượt hơn nhưng trễ hơn. Ở B.3 buffer còn là “khoản dự phòng” cho risk.","aka":["buffers","buffering"]},{"t":"ring buffer","vi":"Bộ đệm vòng: buffer kích thước cố định, ghi đến cuối thì quay lại đầu. Phải định nghĩa khi đầy thì làm gì (drop-oldest, drop-newest, backpressure).","aka":["ring buffers"]},{"t":"buffer overflow","vi":"Tràn bộ đệm: ghi quá kích thước buffer, đè lên vùng nhớ khác — lỗi bảo mật kinh điển kẻ tấn công có thể khai thác để chạy mã độc."},{"t":"bug","vi":"<b>Lỗi phần mềm<\/b>. Trong bài: release note chỉ ghi “bug fixes” là không đủ — OEM cần biết sửa gì, ảnh hưởng requirement/variant nào để quyết định test lại.","aka":["bugs","bug fix","bug fixes"]},{"t":"build","vi":"<b>Bản dựng<\/b> phần mềm từ mã nguồn; cũng là động từ “dựng”. Trong bài, một build cụ thể (có build ID) là thứ được test, ký và phát hành — evidence phải trỏ đúng build.","aka":["builds","built"]},{"t":"build ID","vi":"Mã định danh duy nhất của một bản build. Trong bài, mọi evidence, log, report phải ghi build ID (và variant) để biết đang nói về đúng bản nào.","aka":["build IDs"]},{"t":"reproducible build","vi":"Build tái lập được: cùng source, tool và cấu hình thì dựng lại ra đúng binary như cũ. Cần cho xe sống 10–15 năm: vẫn dựng lại được bản cũ để vá lỗi.","aka":["reproducible builds"]},{"t":"build/test","vi":"Bước <b>build và test<\/b> trong quy trình: dựng bản phần mềm rồi chạy kiểm thử. Trong bài dùng khi nói số tổ hợp phải build/test, độ ổn định build/test."},{"t":"build/variant","vi":"Cặp <b>bản build + variant xe<\/b> mà một evidence/kết quả test áp dụng. Trong bài, mọi report, fix, trace phải ghi rõ build/variant, nếu không evidence không dùng được."},{"t":"burst","vi":"<b>Đợt dồn dập<\/b>: nhiều message/sự kiện đến cùng lúc trong thời gian ngắn. Trong bài, burst tín hiệu là kịch bản test hàng đợi và latency; cần queue có giới hạn.","aka":["bursts","bursty"]},{"t":"bus","vi":"<b>Đường truyền dùng chung<\/b> giữa nhiều thiết bị. Trong bài: bus mạng trong xe (CAN, LIN) và bus bộ nhớ trong SoC — cả hai là tài nguyên chia sẻ gây tranh chấp (contention).","aka":["buses","busses"]},{"t":"bus load","vi":"Tải bus: phần trăm thời gian bus đang bận truyền. Bus load cao làm message chờ lâu hơn (tăng latency) — là một điều kiện môi trường phải đưa vào test."},{"t":"business","vi":"<b>Kinh doanh<\/b>. Trong bài: business case (lý lẽ kinh tế cho một khoản đầu tư), business model, business approval, business rule (luật nghiệp vụ trong logic ứng dụng)."},{"t":"business case","vi":"Lý lẽ kinh tế cho một quyết định: chi phí, lợi ích, rủi ro, thời gian hoàn vốn. Ví dụ dư phần cứng để thêm feature sau SOP cần business case rõ (A.1, A.4)."},{"t":"bypass","vi":"<b>Đi vòng qua<\/b>, lách qua một kiểm soát. Trong bài: bypass gate là cho qua mà không đạt điều kiện; waiver không có hạn sẽ biến thành bypass vĩnh viễn; AI không được tự bypass gate.","aka":["bypassed","bypassing"]},{"t":"byte","vi":"<b>Byte<\/b>: 8 bit, đơn vị đo dữ liệu. Trong bài dùng để tính kích thước frame ảnh (RGBA8888 = 4 byte/pixel), buffer audio, hay chi phí thêm vài byte MAC vào message.","aka":["bytes"]},{"t":"cache","vi":"<b>Bộ nhớ đệm<\/b>: (1) cache CPU dùng chung giữa các core/VM — nguồn nhiễu timing; (2) bản sao dữ liệu lưu gần để đọc nhanh, phải có quy tắc freshness và schema version.","aka":["caches","caching","cached"]},{"t":"calibration","vi":"<b>Hiệu chuẩn<\/b>: tham số tinh chỉnh cho từng xe/variant (nạp ở cuối dây chuyền hoặc qua update). Trong bài, calibration là một phần của configuration phải gắn với build và evidence.","aka":["calibrations"]},{"t":"camera","vi":"<b>Máy quay/cảm biến hình ảnh<\/b> trên xe (camera lùi, surround view). Trong bài: đường đi camera → driver → capture service → compositor → màn hình là ví dụ chuỗi có deadline.","aka":["cameras"]},{"t":"campaign","vi":"<b>Chiến dịch<\/b> có tổ chức: service campaign (gọi xe về xưởng sửa), OTA campaign (đợt cập nhật cho một nhóm xe, có thứ tự, theo dõi và rollback).","aka":["campaigns"]},{"t":"capability","vi":"<b>Năng lực<\/b>/khả năng. Trong bài: hardware capability (phần cứng làm được gì), attacker capability (kẻ tấn công ở đâu, có quyền gì), process capability (năng lực quy trình — ASPICE).","aka":["capabilities"]},{"t":"capture","vi":"<b>Thu nhận<\/b>/ghi lại dữ liệu: capture service lấy frame từ camera, đường capture audio từ micro, bus capture ghi lại traffic CAN kèm timestamp để phân tích.","aka":["captures","captured"]},{"t":"case","vi":"<b>Trường hợp/tình huống<\/b>. Trong bài: case nghiên cứu được “giải phẫu”, <i>use case<\/i>, <i>test case<\/i>, <i>business case<\/i> — mỗi cụm có nghĩa riêng.","aka":["cases"]},{"t":"use case","vi":"Tình huống sử dụng: người dùng/hệ thống làm gì để đạt mục tiêu (ví dụ “phát cảnh báo khi đang gọi điện”). Dùng để suy ra requirement và ưu tiên thuộc tính chất lượng.","aka":["use cases","use-case"]},{"t":"test case","vi":"Ca kiểm thử: một kịch bản test cụ thể với điều kiện, bước làm và kết quả mong đợi, trace ngược về requirement (ví dụ TC-88 kiểm REQ-012).","aka":["test cases"]},{"t":"cause","vi":"<b>Nguyên nhân<\/b>. Trong bài gần như luôn là <i>root cause<\/i> (nguyên nhân gốc) — sửa ở gốc thay vì chỉ xử lý triệu chứng.","aka":["causes","caused"]},{"t":"root cause","vi":"Nguyên nhân gốc: điều mà nếu sửa thì lỗi không tái diễn. Trong bài, root cause được định nghĩa bằng hành động sửa, khác containment (chỉ giảm tác động trước mắt).","aka":["root causes"]},{"t":"Root Cause Analysis","vi":"Phân tích nguyên nhân gốc (RCA): tìm điều thực sự gây ra lỗi bằng bằng chứng, thử các giả thuyết thay vì đoán. Phương pháp RCA được dạy ở B.5."},{"t":"race condition","vi":"Lỗi tranh chấp: kết quả phụ thuộc thứ tự/thời điểm chạy của nhiều thread hay tiến trình, nên lúc đúng lúc sai và khó tái hiện.","aka":["race conditions"]},{"t":"CDC","vi":"Máy tính trung tâm của khoang lái: một SoC chạy cluster, IVI, HUD… thường chia VM/partition. Là hệ thống ví dụ xuyên suốt khóa học.","aka":["CDCs"],"full":"Cockpit Domain Controller","cs":true},{"t":"Cockpit Domain Controller","vi":"Tên đầy đủ của CDC: bộ điều khiển miền khoang lái, gom cluster, IVI, HUD, audio lên một máy tính trung tâm thay vì nhiều ECU riêng."},{"t":"CDC/SDV","vi":"Ghép Cockpit Domain Controller và Software-Defined Vehicle: bối cảnh chung của khóa học — máy tính khoang lái trong một chiếc xe mà tính năng do phần mềm định nghĩa và cập nhật được.","cs":true},{"t":"center","vi":"<b>Trung tâm<\/b>. Trong bài: <i>center display<\/i> (màn hình giữa táp-lô cho IVI), SOC – Security Operations Center (trung tâm giám sát an ninh).","aka":["centre","centers"]},{"t":"center display","vi":"Màn hình trung tâm giữa táp-lô, chạy IVI (bản đồ, media, cài đặt). Trong C.2 ưu tiên mượt hơn cluster, khác cluster vốn ưu tiên độ trễ và độ tin cậy.","aka":["center displays"]},{"t":"Security Operations Center","vi":"SOC: đội/hệ thống giám sát an ninh 24/7, theo dõi dấu hiệu tấn công từ backend và đội xe. Đừng nhầm với SoC (System on Chip)."},{"t":"central","vi":"<b>Trung tâm<\/b>, tập trung. Trong bài: <i>central compute<\/i> — kiến trúc gom nhiều chức năng lên vài máy tính trung tâm thay cho nhiều ECU riêng."},{"t":"central compute","vi":"Máy tính trung tâm hiệu năng cao thay thế nhiều ECU, chạy nhiều OS/service qua hypervisor. Bước tiến từ domain sang zonal + central; lợi về chi phí, update, nhưng blast radius lớn hơn."},{"t":"certificate","vi":"Hai nghĩa: (1) <b>chứng chỉ số<\/b> dùng xác thực/mã hóa, có hạn dùng, phải gia hạn/xoay vòng; (2) <b>giấy chứng nhận<\/b> (ví dụ chứng nhận safety của hypervisor) chỉ hợp lệ trong assumption of use.","aka":["certificates"]},{"t":"certification","vi":"<b>Chứng nhận<\/b>: quy trình đánh giá chính thức rằng sản phẩm đạt chuẩn (safety, security). Trong bài: thay đổi cấu hình/update có thể làm certification cũ mất hiệu lực.","aka":["certifications"]},{"t":"chain","vi":"<b>Chuỗi<\/b>. Trong bài: value chain (chuỗi giá trị OEM–Tier), evidence chain (chuỗi bằng chứng), chain of trust (chuỗi tin cậy khi boot), chuỗi phụ thuộc khi khởi động.","aka":["chains"]},{"t":"value chain","vi":"Chuỗi giá trị: các bên góp phần tạo ra chiếc xe — hãng chip, Tier 2, Tier 1, OEM, nhà máy, đại lý/after-sales — cùng dòng tiền, giá trị và rủi ro chảy giữa họ (A.1)."},{"t":"change","vi":"<b>Thay đổi<\/b>. Trong bài: mọi thay đổi sau baseline phải đi qua change control — có lý do, owner, impact analysis, test lại và phê duyệt.","aka":["changes","changed"]},{"t":"change control","vi":"Kiểm soát thay đổi: quy trình đề xuất, phân tích tác động, phê duyệt và theo dõi mọi thay đổi sau baseline, để không ai sửa “một dòng” mà làm vỡ chỗ khác."},{"t":"change request","vi":"Yêu cầu thay đổi (CR): phiếu ghi lý do, owner, thành phần/variant bị ảnh hưởng, tác động safety/security, effort, test cần chạy lại — đầu vào của change control.","aka":["change requests"]},{"t":"change failure rate","vi":"Tỷ lệ thay đổi gây lỗi sau khi release: bao nhiêu phần trăm thay đổi phải hotfix/rollback. Một metric đo chất lượng quy trình phát hành."},{"t":"check","vi":"<b>Kiểm tra<\/b>. Trong bài: health check (kiểm tra xe còn khỏe sau OTA), plausibility check (giá trị có hợp lý không), integrity check (dữ liệu có bị sửa không), consistency check.","aka":["checks","checked","checking"]},{"t":"health check","vi":"Kiểm tra sức khỏe: sau khi cập nhật/khởi động, xác nhận hệ thống chạy bình thường (service lên, không crash, chỉ số ổn). Trong staged rollout là điều kiện để mở rộng hoặc rollback.","aka":["health checks"]},{"t":"plausibility check","vi":"Kiểm tra tính hợp lý: giá trị nhận được có nằm trong phạm vi và tốc độ thay đổi hợp lý không (ví dụ tốc độ không thể nhảy 0 → 200 km/h trong 10 ms). Dùng khi critical đọc dữ liệu từ phía non-critical.","aka":["plausibility checks"]},{"t":"checklist","vi":"<b>Danh sách kiểm tra<\/b> từng mục. Hữu ích để không bỏ sót (STRIDE, review), nhưng bài cảnh báo: áp cùng một checklist cho mọi thay đổi bất kể risk, hay chỉ tick mà không evidence, là governance hình thức.","aka":["checklists"]},{"t":"chime","vi":"<b>Âm báo<\/b>/chuông cảnh báo trên xe (ví dụ nhắc thắt dây an toàn, cửa mở). Trong khóa học là ví dụ xuyên suốt: chime phải phát đúng lúc, không bị nhạc lấn, và có thể là yêu cầu liên quan safety.","aka":["chimes"]},{"t":"chip","vi":"<b>Vi mạch<\/b>, thường chỉ SoC trung tâm. Trong bài: hãng chip là một mắt xích của value chain; chọn chip kéo theo BSP, hypervisor, vòng đời hỗ trợ và rủi ro thiếu hàng.","aka":["chips"]},{"t":"CI","vi":"Tích hợp liên tục: hệ thống tự động build và test mỗi lần commit để phát hiện lỗi sớm. Lưu ý: ở A.2, CI còn viết tắt cho <i>Configuration Item<\/i> (artifact được quản lý version).","full":"Continuous Integration","cs":true},{"t":"Continuous Integration","vi":"Tích hợp liên tục (CI): mỗi thay đổi code được tự động build và chạy test ngay, để lỗi lộ ra sớm khi còn rẻ để sửa."},{"t":"CI/CD","vi":"Chuỗi tự động từ commit đến build, test, đóng gói và phát hành. Trong bài, quality gate, waiver và staged rollout được gắn vào pipeline CI/CD (B.1, B.4).","full":"Continuous Integration / Continuous Delivery (Deployment)","cs":true},{"t":"configuration item","vi":"Phần tử cấu hình (CI ở A.2): một artifact được quản lý version — code, config, data model, build script, phiên bản compiler/tool — để dựng lại đúng một bản bất kỳ.","aka":["configuration items"]},{"t":"claim","vi":"Hai nghĩa: (1) <b>yêu cầu bồi thường<\/b> (warranty claim, supplier claim); (2) <b>khẳng định<\/b> cần bằng chứng — mỗi quality claim phải có test/evidence bảo vệ.","aka":["claims"]},{"t":"warranty claim","vi":"Yêu cầu bảo hành: khách hàng gặp lỗi trong thời hạn bảo hành, hãng sửa từng xe và chịu chi phí; sau đó có thể đòi lại supplier qua supplier claim.","aka":["warranty claims"]},{"t":"clarity","vi":"<b>Sự rõ ràng<\/b>. Trong rubric chấm: clarity of diagrams/design/argument — sơ đồ, lập luận và câu trả lời phải dễ hiểu, mạch lạc."},{"t":"classification","vi":"<b>Phân loại<\/b>. Trong bài: workload classification (xếp workload theo mức critical để chọn nơi chạy và mức isolation), risk classification (phân luồng nhẹ/mạnh).","aka":["classifications"]},{"t":"clock","vi":"<b>Đồng hồ<\/b> (nguồn thời gian). Trong bài: mỗi chip/thiết bị có clock riêng nên trôi lệch nhau (clock drift); phải biết timestamp do clock nào tạo (clock domain) mới so được.","aka":["clocks"]},{"t":"clock domain","vi":"Miền đồng hồ: tập các mốc thời gian đo bằng cùng một đồng hồ. So timestamp từ hai clock domain khác nhau mà không ánh xạ thì kết luận latency sai (C.3, C.4).","aka":["clock domains"]},{"t":"clock drift","vi":"Trôi đồng hồ: hai đồng hồ chạy lệch tốc độ nhau một chút, sai lệch tích lũy theo thời gian. Trong audio gây trễ dần/vỡ tiếng nếu không đồng bộ hoặc resample."},{"t":"close","vi":"<b>Đóng<\/b> (ticket, defect, finding). Trong bài: chỉ close khi có root cause, fix và evidence — tắt feature (containment) chưa phải lý do để close.","aka":["closed","closing"]},{"t":"closed-loop","vi":"<b>Vòng kín<\/b>: kết quả quay lại điều chỉnh đầu vào. Trong bài: <i>closed-loop quality<\/i> — vòng chỉ khép khi sự cố biến thành asset dùng lại (regression test, gate, design rule)."},{"t":"closed-loop quality","vi":"Chất lượng vòng kín: mỗi sự cố phải để lại một thứ dùng lại được (test, budget, checklist, gate) để lỗi tương tự không lặp lại; chỉ sửa bản build hôm nay là chưa khép vòng."},{"t":"cloud","vi":"<b>Điện toán đám mây<\/b>: máy chủ từ xa phục vụ xe (OTA, telematics, analytics). Quy tắc trong bài: real-time control không phụ thuộc cloud; xe phải chạy được khi mất kết nối."},{"t":"cloud/edge","vi":"Lựa chọn chạy logic/dữ liệu ở <b>cloud<\/b> (máy chủ xa) hay <b>edge<\/b> (trên xe, gần nguồn dữ liệu), theo latency, kết nối, privacy và chi phí. Đào sâu ở B.4."},{"t":"cluster","vi":"<b>Cụm đồng hồ táp-lô<\/b> (instrument cluster): màn hình sau vô-lăng hiện tốc độ, cảnh báo. Trong bài là chức năng critical trên CDC: phải sẵn sàng sớm, ổn định, không bị IVI kéo chậm.","aka":["clusters"]},{"t":"cockpit","vi":"<b>Khoang lái<\/b>: mọi thứ người lái nhìn/chạm — cluster, IVI, HUD, âm thanh. Cockpit domain gom các chức năng này lên một CDC.","aka":["cockpits"]},{"t":"code","vi":"<b>Mã nguồn<\/b> phần mềm; cũng là “mã” định danh (diagnostic trouble code). Trong bài: thay đổi “một dòng code” vẫn có thể cần review mạnh nếu chạm đường safety.","aka":["codes"]},{"t":"code review","vi":"Rà soát mã: người khác đọc thay đổi trước khi merge để tìm lỗi, kiểm tra trace về design/requirement và coding guideline/security checklist.","aka":["code reviews"]},{"t":"Diagnostic Trouble Code","vi":"Mã lỗi chẩn đoán (DTC): mã ECU lưu lại khi phát hiện lỗi, đọc được qua công cụ chẩn đoán hoặc gửi về backend để phát hiện vấn đề sớm.","aka":["trouble code","trouble codes"]},{"t":"coding","vi":"<b>Viết mã<\/b>. Trong bài: secure coding (viết code an toàn), coding guideline (quy tắc viết code). Riêng <i>variant coding<\/i> là cấu hình phần mềm theo biến thể xe ở nhà máy."},{"t":"coding guideline","vi":"Quy tắc viết mã chung (ví dụ MISRA cho C/C++ ô tô) nhằm tránh cấu trúc dễ lỗi; tuân thủ được kiểm bằng static analysis và review.","aka":["coding guidelines"]},{"t":"variant coding","vi":"Cấu hình phần mềm theo biến thể xe (thị trường, trang bị) — thường ghi ở trạm cuối dây chuyền hoặc xưởng dịch vụ."},{"t":"cohort","vi":"<b>Nhóm xe<\/b> nhận cùng một bản cập nhật trong staged rollout. Trong bài: theo dõi từng cohort, chỉ mở rộng sang cohort tiếp khi chỉ số tốt; có lỗi thì dừng/chặn cohort.","aka":["cohorts"]},{"t":"cold","vi":"<b>Nguội<\/b>: trạng thái mới khởi động, chưa có gì nạp sẵn (cold boot, cold start). Thường là trường hợp chậm nhất nên phải đo riêng, khác <i>warm<\/i> (đã chạy sẵn)."},{"t":"command","vi":"<b>Lệnh<\/b> điều khiển gửi tới hệ thống (ví dụ remote unlock, lệnh xuống domain khác). Trong bài: lệnh cần integrity và xác thực, vì inject command giả có thể ảnh hưởng safety.","aka":["commands"]},{"t":"commit","vi":"<b>Lần ghi thay đổi<\/b> vào hệ thống quản lý mã (ví dụ commit a1b2c3). Trong traceability, commit là mắt xích giữa design/requirement và test/build; CI chạy mỗi lần commit.","aka":["commits","committed"]},{"t":"common","vi":"<b>Chung<\/b>, dùng chung. Trong bài: common platform (một nền tảng cho nhiều chương trình xe), common service; cũng thấy trong tên CVSS – Common Vulnerability Scoring System."},{"t":"communication","vi":"<b>Giao tiếp/truyền thông<\/b>: giữa các thành phần (IPC, mạng, pattern request/response, pub/sub) và giữa con người. Trong rubric, “Communication &amp; defense” chấm khả năng trình bày và bảo vệ.","aka":["communications"]},{"t":"inter-process communication","vi":"Giao tiếp giữa các tiến trình (IPC): cách các process/VM trao dữ liệu (shared memory, socket, message). Trong bài, IPC giữa domain cần contract, version và xác thực."},{"t":"compare","vi":"<b>So sánh<\/b>. Là một bước của judgment playbook (Frame → Map → Quantify → Compare → Decide → Learn); trong migration còn có shadow/compare traffic để so hệ mới với hệ cũ.","aka":["compares","compared","comparing"]},{"t":"compatibility","vi":"<b>Tính tương thích<\/b>: các thành phần/version khác nhau vẫn làm việc đúng với nhau. Trong xe nhiều ECU, variant và bản OTA lệch nhau, nên compatibility là chi phí và rủi ro lớn kéo dài."},{"t":"compatibility matrix","vi":"Bảng tương thích: version nào chạy được với version nào (giữa ECU, service, app, variant). Là một trong các thứ kiến trúc phải có để OTA an toàn.","aka":["compatibility matrices"]},{"t":"compatibility rule","vi":"Quy tắc tương thích: được phép thay đổi interface/schema theo cách nào mà không phá consumer cũ (ví dụ chỉ thêm field tùy chọn, không đổi unit).","aka":["compatibility rules"]},{"t":"compatibility test","vi":"Kiểm thử tương thích: chạy bản mới với các version/consumer cũ còn trên xe để xác nhận không vỡ — bắt buộc trước khi phát hành bản vá hay OTA.","aka":["compatibility tests","compatibility testing","compatibility check"]},{"t":"compiler","vi":"<b>Trình biên dịch<\/b>: chuyển mã nguồn thành binary. Trong bài: version compiler là configuration item cần quản lý (đổi compiler có thể đổi binary), và là chi phí license/tool.","aka":["compilers"]},{"t":"component","vi":"<b>Thành phần<\/b> phần mềm/phần cứng có ranh giới và trách nhiệm rõ. Trong bài, requirement được phân bổ xuống component; mỗi component cần owner, interface và version.","aka":["components"]},{"t":"software component","vi":"Thành phần phần mềm: một khối code có interface rõ, được phát triển, test và quản lý version độc lập (ví dụ SWC trong AUTOSAR).","aka":["software components"]},{"t":"component/interface","vi":"Cặp <b>thành phần và giao diện<\/b> của nó — đơn vị mà ownership kỹ thuật và traceability gắn vào (ai quyết định, duy trì, sửa)."},{"t":"compositor","vi":"<b>Bộ ghép hình<\/b>: thành phần gộp nhiều lớp (layer) từ các app/VM thành một khung hình gửi ra màn hình, quyết định z-order. Trong C.2, compositor chờ GPU có thể làm trễ cluster.","aka":["compositors"]},{"t":"compute","vi":"<b>Năng lực tính toán<\/b> (CPU, GPU, NPU) hoặc máy tính làm việc đó. Trong bài: central compute, compute platform; dư compute là quyết định kinh tế, cần business case."},{"t":"compute platform","vi":"Nền tảng tính toán: phần cứng (SoC) cùng OS, middleware chung mà nhiều tính năng chạy trên đó. Trong SDV, compute platform quyết định khả năng mở rộng sau SOP."},{"t":"concept","vi":"<b>Khái niệm/ý tưởng<\/b>; cũng là <b>giai đoạn Concept<\/b> đầu vòng đời (xác định use case, phạm vi). Trong bài còn có safety concept, cybersecurity concept — bản thiết kế cấp cao cho an toàn/bảo mật.","aka":["concepts"]},{"t":"condition","vi":"<b>Điều kiện<\/b>. Trong bài: điều kiện của requirement, entry/exit condition của gate, revisit condition (khi nào xem lại quyết định), race condition (lỗi tranh chấp thời điểm).","aka":["conditions"]},{"t":"configuration","vi":"<b>Cấu hình<\/b>: tham số quyết định phần mềm chạy thế nào trên từng variant (feature flag, calibration, budget…). Trong bài, configuration phải có version, gắn baseline, vì đổi config cũng là thay đổi.","aka":["configurations","config","configs"]},{"t":"configuration management","vi":"Quản lý cấu hình: kiểm soát version của mọi configuration item và baseline, để biết chính xác xe nào đang chạy tổ hợp gì và dựng lại được bản bất kỳ."},{"t":"conflict","vi":"<b>Xung đột<\/b>. Trong bài: requirement conflict (hai yêu cầu đều hợp lệ nhưng va nhau, ví dụ IVI restart nhanh vs cluster hiển thị liên tục) — giải bằng thiết kế, không bằng cãi nhau.","aka":["conflicts"]},{"t":"connectivity","vi":"<b>Khả năng kết nối<\/b> (mạng di động, Wi-Fi, Bluetooth). Trong bài: connectivity mở cửa cho OTA và tấn công từ xa; xe phải chạy được khi mất kết nối."},{"t":"consistency","vi":"<b>Tính nhất quán<\/b>. Trong bài: data consistency, crash consistency (dữ liệu vẫn đúng sau mất điện), consistency check giữa các model/tài liệu."},{"t":"constraint","vi":"<b>Ràng buộc<\/b>: điều kiện bắt buộc không được đánh đổi (safety, quy định, ngân sách, phần cứng có sẵn, lịch SOP). SA biến nhu cầu và constraint thành giải pháp triển khai được.","aka":["constraints"]},{"t":"consumer","vi":"<b>Bên dùng<\/b> dữ liệu/service (ngược với producer – bên tạo). Trong bài: thay đổi interface phải nghĩ tới mọi consumer; consumer-driven contract test kiểm chính điều consumer cần.","aka":["consumers"]},{"t":"containment","vi":"<b>Khoanh vùng/ngăn chặn<\/b>: (1) với sự cố, biện pháp giảm tác động trước mắt (tắt feature, dừng rollout) — chưa phải sửa gốc; (2) fault containment: giữ lỗi không lan sang phần khác."},{"t":"fault containment","vi":"Ngăn lỗi lan: thiết kế để lỗi ở một thành phần/partition không kéo theo phần khác (isolation, timeout, giá trị mặc định an toàn). Trọng tâm của mixed criticality trên CDC."},{"t":"contention","vi":"<b>Tranh chấp tài nguyên<\/b> dùng chung (cache, memory bus, GPU, queue, lock). Trong bài là nguyên nhân chính làm timing không ổn định dù CPU còn rảnh — phải đo dưới tải."},{"t":"context","vi":"<b>Bối cảnh<\/b>: hoàn cảnh, phạm vi, ràng buộc xung quanh một quyết định. Trong bài: phần Context của ADR, system context diagram, và “trade-off theo context” — không có lựa chọn đúng mọi nơi.","aka":["contexts"]},{"t":"continuous","vi":"<b>Liên tục<\/b>. Trong bài: Continuous Integration (CI), continuous improvement (cải tiến liên tục từ dữ liệu fleet), CI/CD."},{"t":"continuous improvement","vi":"Cải tiến liên tục: dữ liệu từ đội xe đi vào backlog, cải tiến rồi phát hành lại; mỗi vòng vẫn phải qua test, gate và rollout có kiểm soát."},{"t":"contract","vi":"Hợp đồng / <b>thỏa thuận ràng buộc<\/b>. Trong bài thường là contract kỹ thuật giữa hai bên của một interface: data, unit, timing, lỗi, version, owner được ghi rõ và kiểm bằng test; đôi khi là hợp đồng thương mại với supplier.","aka":["contracts"]},{"t":"interface contract","vi":"<b>Hợp đồng giao diện<\/b>: tài liệu chốt giữa producer và consumer về dữ liệu (kiểu, unit, range), timing (rate, freshness, timeout), hành vi lỗi, version và owner. Interface chỉ có tên mà không có contract thì không review hay test được.","aka":["interface contracts"]},{"t":"service contract","vi":"Contract của một service: các operation/event, kiểu dữ liệu, versioning, timeout/freshness và hành vi degraded khi provider không sẵn sàng. Là căn cứ để consumer dùng service mà không cần biết bên trong.","aka":["service contracts"]},{"t":"contract test","vi":"<b>Kiểm thử hợp đồng<\/b>: test tự động kiểm rằng producer và consumer vẫn tuân đúng interface contract (field, unit, version, hành vi lỗi). Bắt sớm lỗi “sửa một bên, vỡ bên kia” trước khi tích hợp trên HIL/xe.","aka":["contract tests","contract testing"]},{"t":"control","vi":"Điều khiển / <b>biện pháp kiểm soát<\/b>. Trong bài có nhiều nghĩa: (1) biện pháp bảo vệ chống một threat/risk (security control, risk control); (2) cơ chế quản lý thay đổi (change control); (3) điều khiển thiết bị (control path, vehicle control).","aka":["controls"]},{"t":"compensating control","vi":"<b>Control bù trừ<\/b>: khi không vá được component (không update được, re-validation quá rủi ro), bảo vệ nó từ bên ngoài, ví dụ firewall, chặn port, giới hạn quyền. Cần owner, ngân sách và ngày xem lại.","aka":["compensating controls"]},{"t":"security control","vi":"Biện pháp bảo mật cụ thể (secure boot, ký số, firewall, mã hóa, IDS…) được chọn để chặn một threat đã xác định. Mỗi control phải gắn với threat, có test chứng minh nó hoạt động và có owner.","aka":["security controls"]},{"t":"control path","vi":"<b>Đường điều khiển<\/b>: luồng lệnh (volume, mute, chọn nguồn, bật/tắt) tách biệt với data path mang dữ liệu thật. Trong bài audio, hai đường này có thể hỏng độc lập nên phải đo và debug riêng."},{"t":"controlled","vi":"<b>Có kiểm soát<\/b>: được làm theo quy tắc, có giới hạn, có người chịu trách nhiệm và đo được. Ví dụ controlled AI (AI dùng trong ranh giới quyền hạn rõ), controlled experiment, controlled documentation, migration có kiểm soát."},{"t":"controlled experiment","vi":"<b>Thí nghiệm có kiểm soát<\/b>: chỉ thay đổi một yếu tố, giữ nguyên các yếu tố khác rồi so sánh kết quả. Trong RCA dùng để xác nhận hay bác bỏ giả thuyết nguyên nhân gốc thay vì đoán.","aka":["controlled experiments"]},{"t":"controller","vi":"<b>Bộ điều khiển<\/b>: phần cứng hoặc phần mềm điều khiển một thiết bị/hệ thống. Trong bài gặp ở ECU (Electronic Control Unit), domain/zone controller, CAN controller, network controller hay display controller trên SoC."},{"t":"domain controller","vi":"<b>Bộ điều khiển miền<\/b>: máy tính mạnh gom các chức năng của một domain (cockpit, ADAS, body…) thay cho nhiều ECU nhỏ. CDC (Cockpit Domain Controller) là domain controller của khoang lái: cluster, IVI, HUD.","aka":["domain controllers"]},{"t":"zone controller","vi":"<b>Bộ điều khiển vùng<\/b>: ECU đặt theo vị trí vật lý trong xe, gom tín hiệu/cảm biến của khu vực đó và chuyển lên compute trung tâm qua Ethernet. Ví dụ đọc frame CAN tốc độ rồi phát thành service.","aka":["zone controllers","zonal controller"]},{"t":"copy","vi":"<b>Sao chép<\/b> (dữ liệu). Trong bài: mỗi lần chép buffer qua boundary/IPC tốn CPU và thêm latency; shared memory giảm copy nhưng khó kiểm soát ownership. Ở B.4: “copy” là bê nguyên sang chỗ mới, khác migration có kiểm soát."},{"t":"core","vi":"<b>Lõi<\/b>. Hai nghĩa trong bài: (1) nhân xử lý vật lý của CPU (vCPU được hypervisor đặt lên core nào); (2) phần lõi dùng chung của platform (platform core) mà nhiều chương trình xe tái sử dụng."},{"t":"correlation","vi":"<b>Tương quan / độ khớp<\/b>. Trong bài: (1) correlation giữa mô hình ảo và đo thật, cho biết virtual test đáng tin đến đâu; (2) correlation ID để nối các log, trace thuộc cùng một request hay sự cố."},{"t":"correlation ID","vi":"<b>Mã liên kết<\/b> gắn vào mọi log/trace của cùng một request hay sự kiện, đi xuyên nhiều service, partition, xe và cloud. Nhờ nó có thể ghép lại toàn bộ đường đi khi điều tra crash hoặc latency.","aka":["correlation IDs"]},{"t":"cost","vi":"<b>Chi phí<\/b>. Trong bài là chi phí theo cả vòng đời: phát triển, tích hợp, test, sản xuất (per-unit cost), bảo trì, xử lý lỗi (failure cost) và chuyển đổi supplier (exit cost), không chỉ giá mua ban đầu."},{"t":"count","vi":"<b>Số đếm<\/b>. Ví dụ defect count (số lỗi), crash count (số lần crash), long-frame count (số frame quá hạn). Lưu ý: tối ưu con số đếm mà không gắn quyết định dễ dẫn tới “làm đẹp số liệu”."},{"t":"counter","vi":"<b>Bộ đếm<\/b>: giá trị tăng dần theo sự kiện. Trong bài: counter trong E2E protection (tăng mỗi message để phát hiện mất/lặp/sai thứ tự), counter interrupt/RX của driver để xem phần cứng có còn nhận dữ liệu."},{"t":"coupling","vi":"<b>Độ gắn kết / phụ thuộc chặt<\/b> giữa các phần của hệ thống. Coupling cao thì sửa một chỗ kéo theo sửa nhiều chỗ, tăng chi phí regression và khó thay supplier; pub/sub và interface rõ giúp giảm coupling."},{"t":"coverage","vi":"<b>Độ phủ<\/b>: tỉ lệ phần cần kiểm đã được test kiểm tới. Requirement coverage hỏi requirement nào chưa có test; code coverage hỏi dòng/nhánh code nào chưa chạy. Test nhiều mà không map requirement thì chưa chắc phủ."},{"t":"CPU","vi":"<b>Bộ xử lý trung tâm<\/b>, nơi chạy phần mềm. Trên SoC của CDC, CPU có nhiều core được chia cho các VM/partition; budget CPU, headroom và tranh chấp CPU là yếu tố chính quyết định latency và isolation.","aka":["CPUs"],"full":"Central Processing Unit","cs":true},{"t":"CPU/GPU","vi":"Viết gộp <b>CPU và GPU<\/b> (bộ xử lý trung tâm và bộ xử lý đồ họa), thường nói về tài nguyên tính toán của SoC hoặc tình trạng quá tải tính toán/đồ họa (ví dụ AAOS overload CPU/GPU).","cs":true},{"t":"CPU/RAM","vi":"Viết gộp <b>CPU và RAM<\/b>: năng lực xử lý và bộ nhớ. Trong bài thường đi với headroom (dư địa CPU/RAM) hoặc resource budget phải được duyệt trong business case.","cs":true},{"t":"crash","vi":"<b>Sập / dừng đột ngột<\/b> của một process, app hoặc guest OS do lỗi. Trong bài, crash rate là health metric khi rollout OTA, và crash của một guest không được kéo guest khác sập theo (fault containment).","aka":["crashes","crashed"]},{"t":"crash count","vi":"<b>Số lần crash<\/b> được ghi và gửi về backend (thường qua telemetry sau mỗi lần boot). Dùng để theo dõi sức khỏe fleet và phát hiện bản release gây lỗi."},{"t":"CRC","vi":"<b>Mã kiểm tra vòng<\/b>: giá trị tính từ dữ liệu, dữ liệu đổi thì CRC đổi. Dùng trong frame CAN, E2E protection hay kiểm output hiển thị để phát hiện dữ liệu bị hỏng trên đường truyền hoặc khi lưu.","full":"Cyclic Redundancy Check","cs":true},{"t":"criteria","vi":"<b>Tiêu chí<\/b> (số nhiều của criterion): điều kiện cụ thể, đo được để đánh giá. Ví dụ acceptance criteria, entry/exit criteria của gate, recovery criteria. Tiêu chí mơ hồ thì không ai kiểm được."},{"t":"entry criteria","vi":"<b>Tiêu chí vào<\/b>: điều kiện phải có trước khi bắt đầu một review/gate/giai đoạn (ví dụ tài liệu đã baseline, test đã chạy). Tránh bắt đầu review khi đầu vào chưa đủ."},{"t":"exit criteria","vi":"<b>Tiêu chí ra<\/b>: điều kiện đo được để một gate/giai đoạn được coi là pass và chuyển bước tiếp. Trong migration là điều kiện để kết thúc một giai đoạn hoặc cutover."},{"t":"critical","vi":"<b>Quan trọng / trọng yếu<\/b>: hỏng thì gây hậu quả nặng. Trong bài: safety-critical (liên quan an toàn), cảnh báo critical, đường critical; ngược lại non-critical là phần được phép degrade."},{"t":"safety-critical","vi":"<b>Liên quan an toàn<\/b>: chức năng mà lỗi có thể gây nguy hiểm cho người (cảnh báo phanh, telltale, camera lùi). Cần isolation mạnh, timing dự đoán được và bằng chứng theo ISO 26262."},{"t":"criticality","vi":"<b>Mức độ trọng yếu<\/b> của một workload: lỗi của nó gây hậu quả nghiêm trọng đến đâu (ví dụ ASIL so với QM). Criticality quyết định cần isolation, budget và evidence ở mức nào."},{"t":"mixed criticality","vi":"<b>Hỗn hợp mức trọng yếu<\/b>: chạy workload có criticality khác nhau (cluster an toàn và infotainment) trên cùng SoC. Đòi hỏi hypervisor/partition và bằng chứng FFI để phần ít quan trọng không làm hỏng phần quan trọng.","aka":["mixed-criticality"]},{"t":"cross-domain","vi":"<b>Xuyên miền<\/b>: liên quan nhiều domain hoặc nhiều lĩnh vực cùng lúc. Có thể là dữ liệu đi giữa các domain/partition (cockpit, ADAS, body) hoặc quyết định đụng tới safety, cyber, privacy, chi phí cùng lúc."},{"t":"CVE","vi":"<b>Mã định danh lỗ hổng bảo mật đã công bố<\/b> (dạng CVE-năm-số). Sau SOP, OEM phải theo dõi CVE cho mọi component trong SBOM, triage xem xe nào bị ảnh hưởng và vá qua OTA.","aka":["CVEs"],"full":"Common Vulnerabilities and Exposures","cs":true},{"t":"CVE triage","vi":"<b>Sàng lọc CVE<\/b>: với mỗi lỗ hổng mới, xác định component/version có trong build không, code bị ảnh hưởng có bật và có bị expose không, rồi quyết định patch, backport, control bù trừ hay chấp nhận."},{"t":"cyber","vi":"Viết tắt thông dụng của <b>cybersecurity<\/b> (an ninh mạng). Trong bài thường đứng cạnh safety và quality: safety-cyber-quality impact, team cyber, Cyber Security Management System (CSMS)."},{"t":"cybersecurity","vi":"<b>An ninh mạng<\/b>: bảo vệ xe và hệ thống khỏi tấn công, truy cập trái phép, sửa đổi phần mềm. Với ô tô gắn với ISO/SAE 21434 và UNECE R155; kéo dài suốt vòng đời xe, không kết thúc ở release."},{"t":"dashboard","vi":"<b>Bảng theo dõi<\/b> hiển thị các metric quan trọng (chất lượng, rollout, health). Lưu ý trong bài: dashboard “96% healthy” chưa đủ để quyết định nếu không biết đo gì, trên nhóm xe nào.","aka":["dashboards"]},{"t":"data","vi":"<b>Dữ liệu<\/b>. Trong bài: dữ liệu xe (tốc độ, trạng thái), dữ liệu fleet/telemetry gửi về cloud, dữ liệu đo làm evidence. Data model, data flow, data path và data ownership là các khái niệm kiến trúc quan trọng."},{"t":"data flow","vi":"<b>Luồng dữ liệu<\/b>: dữ liệu đi từ đâu, qua những thành phần/boundary nào, đến đâu. Vẽ data flow giúp threat modeling (tìm entry point) và tìm nơi gây latency hay mất dữ liệu.","aka":["data flows"]},{"t":"data path","vi":"<b>Đường dữ liệu<\/b>: chuỗi thành phần mà dữ liệu thật đi qua (ví dụ audio: source → decode → mixer/DSP → HAL/driver → DAC/amp → loa). Phân biệt với control path mang lệnh điều khiển.","aka":["data paths"]},{"t":"data model","vi":"<b>Mô hình dữ liệu<\/b>: cách định nghĩa các đối tượng dữ liệu, field, kiểu, đơn vị và quan hệ. Data model khác nhau giữa các xe làm tăng chi phí adapter khi tái sử dụng platform.","aka":["data models"]},{"t":"date","vi":"<b>Ngày, mốc thời gian<\/b>. Trong bài: launch date (ngày ra mắt), review date (ngày phải xem lại một quyết định/rủi ro), effective date (ngày tài liệu có hiệu lực).","aka":["dates"]},{"t":"DDS","vi":"<b>Chuẩn middleware publish/subscribe<\/b> lấy dữ liệu làm trung tâm, có QoS (độ tin cậy, deadline, lịch sử). Dùng trong xe và robot cho truyền dữ liệu nhiều producer/consumer, ví dụ stream camera.","full":"Data Distribution Service","cs":true},{"t":"deadline","vi":"<b>Hạn chót<\/b>. Hai nghĩa: (1) hạn kỹ thuật một tác vụ phải xong (deadline miss là lỗi timing trong real-time); (2) hạn chốt công việc/quyết định, như deadline vá CVE hay chốt ADR.","aka":["deadlines"]},{"t":"deadline miss","vi":"<b>Trễ hạn<\/b>: tác vụ real-time không hoàn thành trong thời hạn yêu cầu. Với hard real-time đây là failure nghiêm trọng; thường do tranh chấp CPU, interrupt hoặc WCET tính thiếu.","aka":["deadline misses"]},{"t":"debt","vi":"<b>Nợ<\/b> (nghĩa bóng): phần việc kỹ thuật bị hoãn lại để đi nhanh, càng để lâu “lãi” càng cao. Trong bài: technical debt, security debt, architecture debt; cần owner và trigger để trả."},{"t":"technical debt","vi":"<b>Nợ kỹ thuật<\/b>: giải pháp tạm, code/thiết kế cũ được giữ lại để tiết kiệm trước mắt, làm việc thay đổi sau này tốn kém hơn. Ví dụ tái dùng phần cứng/phần mềm cũ của chương trình trước."},{"t":"security debt","vi":"<b>Nợ bảo mật<\/b>: lỗ hổng, component lỗi thời và việc bảo trì bảo mật chưa xử lý tích tụ lại, càng để lâu càng khó và đắt để vá."},{"t":"debug","vi":"<b>Gỡ lỗi<\/b>: tìm và xác định nguyên nhân lỗi. Trong bài còn có debug port (cổng gỡ lỗi trên phần cứng): tiện cho chẩn đoán nhưng là bề mặt tấn công nên thường phải khóa khi xuất xưởng.","aka":["debugging"]},{"t":"decision","vi":"<b>Quyết định<\/b>. Trong khóa học, quyết định kiến trúc phải có câu hỏi rõ, phương án, tiêu chí, người có quyền quyết (decision owner), lý do và evidence, thường được ghi thành ADR.","aka":["decisions"]},{"t":"decision rights","vi":"<b>Quyền quyết định<\/b>: quy định rõ ai được quyết loại việc gì (chọn kiến trúc, cấp waiver, chấp nhận residual risk, release). Thiếu decision rights thì quyết định bị kéo dài hoặc không ai chịu trách nhiệm."},{"t":"decision owner","vi":"<b>Người sở hữu quyết định<\/b>: người/nhóm có quyền và trách nhiệm chốt một quyết định. Kỹ sư phân tích và đề xuất, decision owner chốt và chịu trách nhiệm hệ quả.","aka":["decision owners","decision ownership"]},{"t":"decode","vi":"<b>Giải mã<\/b>: chuyển dữ liệu nén/mã hóa về dạng dùng được (giải nén video/audio, parse frame CAN thành giá trị). Là một stage trong pipeline có latency riêng cần đo.","aka":["decoding","decoder"]},{"t":"defect","vi":"<b>Lỗi, khiếm khuyết<\/b> của sản phẩm so với yêu cầu. Trong bài: defect management, defect density, defect escape; defect ở bất kỳ tầng nào thì OEM chịu trách nhiệm trước khách hàng trước.","aka":["defects"]},{"t":"defect escape","vi":"<b>Lỗi lọt<\/b>: defect không bị các bước kiểm phát hiện, lọt ra sau release hoặc ra field. Escape rate là chỉ số cho biết quy trình test/review đang bỏ sót bao nhiêu.","aka":["defect escapes"]},{"t":"escape rate","vi":"<b>Tỷ lệ lỗi lọt<\/b> ra sau release so với tổng số lỗi. Là metric phản hồi về hiệu quả của gate, review và test."},{"t":"defect density","vi":"<b>Mật độ lỗi<\/b>: số defect trên một đơn vị kích thước code (ví dụ trên 1.000 dòng). Dùng để so sánh chất lượng giữa các component, nhưng không nên tối ưu số này một cách máy móc."},{"t":"defense","vi":"<b>Phòng thủ / bảo vệ<\/b>. Hai nghĩa: (1) bảo vệ bài trình bày, trả lời chất vấn trước reviewer (Communication &amp; defense trong rubric); (2) phòng thủ bảo mật nhiều lớp (defense in depth)."},{"t":"defense in depth","vi":"<b>Phòng thủ nhiều lớp<\/b>: xếp nhiều control độc lập chồng lên nhau để khi một lớp bị vượt qua thì lớp sau vẫn chặn được hoặc hạn chế thiệt hại (gateway, firewall, secure boot, least privilege, IDS…)."},{"t":"degrade","vi":"<b>Suy giảm có kiểm soát<\/b>: khi tài nguyên thiếu hoặc lỗi, hệ thống giảm chất lượng/tính năng một cách đã thiết kế trước (giảm frame rate, tắt hiệu ứng) thay vì sập. Phần non-critical thường được phép degrade.","aka":["degrades","degradation"]},{"t":"degraded","vi":"<b>Ở trạng thái suy giảm<\/b>: vẫn chạy nhưng giảm chức năng hoặc chất lượng một cách có kiểm soát. Thường đi với degraded mode/behavior/state, ví dụ hiển thị “không có dữ liệu” thay vì giá trị cũ."},{"t":"degraded mode","vi":"<b>Chế độ suy giảm<\/b>: hành vi được định nghĩa trước khi input sai, provider không sẵn sàng hoặc thiếu tài nguyên, giữ phần quan trọng (cảnh báo an toàn) và bỏ phần phụ. Phải ghi trong contract và được test.","aka":["degraded state"]},{"t":"delay","vi":"<b>Độ trễ / sự chậm trễ<\/b>. Kỹ thuật: thời gian dữ liệu nằm chờ (queue delay, group delay trong audio). Dự án: launch delay, tức ra mắt muộn, một khoản chi phí trong business case.","aka":["delays"]},{"t":"deliverable","vi":"<b>Sản phẩm bàn giao<\/b>: kết quả cụ thể phải nộp (tài liệu, sơ đồ, báo cáo RCA, checklist). Trong khóa học là phần bài nộp của mỗi unit/assignment.","aka":["deliverables"]},{"t":"delivery","vi":"<b>Bàn giao, chuyển giao<\/b>. Ví dụ một lần delivery phần mềm của supplier (phải gắn baseline và release note), Continuous Delivery trong CI/CD, hay event delivery semantics trong middleware.","aka":["deliveries"]},{"t":"continuous delivery","vi":"<b>Chuyển giao liên tục<\/b> (chữ CD trong CI/CD): phần mềm luôn được build, test, đóng gói tự động để sẵn sàng phát hành. Với xe, không có nghĩa “CI xanh thì tự OTA”: vẫn cần gate, ký số, staged rollout."},{"t":"dependency","vi":"<b>Sự phụ thuộc<\/b>: thành phần này cần thành phần khác để chạy đúng (thư viện, service, thứ tự khởi động, supplier). Dependency ngầm, chưa ghi lại là nguồn lỗi và rủi ro update lớn nhất.","aka":["dependencies"]},{"t":"deploy","vi":"<b>Triển khai<\/b>: đưa phần mềm đã build lên môi trường chạy thật (xe, ECU, cloud). Trong bài, AI không được tự deploy; deploy state là thông tin cần kiểm khi điều tra lỗi.","aka":["deployed","deploying"]},{"t":"deployment","vi":"<b>Sự triển khai / bố trí<\/b>: phần mềm chạy ở đâu (ECU nào, VM nào, edge hay cloud) và được đưa lên thế nào. Deployment architecture/diagram cho thấy component nằm trên phần cứng nào.","aka":["deployments"]},{"t":"deprecate","vi":"<b>Đánh dấu ngừng dùng<\/b>: thông báo một API/field/version sẽ bị bỏ, giữ song song một thời gian để consumer kịp chuyển, rồi mới xóa. Không xóa đột ngột.","aka":["deprecated","deprecating"]},{"t":"deprecation","vi":"<b>Việc ngừng hỗ trợ có báo trước<\/b>: lộ trình bỏ dần version/API cũ. Deprecation policy quy định thời gian báo trước, số release còn hỗ trợ và cách thông báo cho consumer."},{"t":"depth","vi":"<b>Độ sâu<\/b>. Trong bài: queue depth (số phần tử tối đa/hiện có trong hàng đợi, đầy thì phải có policy) và defense in depth (phòng thủ nhiều lớp)."},{"t":"queue depth","vi":"<b>Độ sâu hàng đợi<\/b>: số phần tử tối đa queue được chứa hoặc số đang chờ. Là metric quan trọng: queue đầy dần báo hiệu consumer chậm, gây latency hoặc mất dữ liệu."},{"t":"design","vi":"<b>Thiết kế<\/b>: cách giải quyết requirement bằng cấu trúc component, interface và quyết định kỹ thuật. Là một bước trong lifecycle; design review kiểm thiết kế trước khi code.","aka":["designs"]},{"t":"design review","vi":"<b>Duyệt thiết kế<\/b>: buổi/quy trình kiểm tra thiết kế với entry/exit criteria, evidence và người có quyền quyết. Rẻ hơn rất nhiều so với phát hiện lỗi thiết kế khi đã tích hợp.","aka":["design reviews"]},{"t":"detection","vi":"<b>Phát hiện<\/b>: nhận ra lỗi, tấn công hay bất thường. Ví dụ IDS (Intrusion Detection System), stale detection (phát hiện dữ liệu cũ), fleet issue detection. Không phát hiện được thì không phản ứng được."},{"t":"dev","vi":"Viết tắt thông dụng của <b>developer / development<\/b>: lập trình viên hoặc giai đoạn phát triển. Ví dụ “Dev nói đã nhanh”, board dev (board dùng để phát triển, khác target thật)."},{"t":"developer","vi":"<b>Lập trình viên<\/b>, người viết code. Trong bài nhấn mạnh: RCA không dừng ở “developer quên…”, mà phải tìm lỗ hổng hệ thống/quy trình cho phép lỗi xảy ra.","aka":["developers"]},{"t":"development","vi":"<b>Phát triển<\/b>: giai đoạn thiết kế, viết code và test trước khi sản xuất. Ví dụ development cost, secure development, development interface agreement (DIA) chia trách nhiệm giữa OEM và supplier."},{"t":"device","vi":"<b>Thiết bị<\/b> phần cứng (camera, GPU, audio codec, network controller…). Trong bài: device ownership trong ảo hóa (VM nào sở hữu thiết bị), device file của driver, hay thiết bị bên ngoài như điện thoại.","aka":["devices"]},{"t":"DevOps","vi":"<b>Development + Operations<\/b>: cách làm gộp phát triển và vận hành, tự động hóa build/test/release (CI/CD), theo dõi hệ thống sau release và phản hồi nhanh. Với xe gồm cả pipeline OTA, gate và rollout."},{"t":"diagnostic","vi":"<b>Chẩn đoán<\/b>: cơ chế phát hiện, ghi và báo lỗi (DTC, log, diagnostic event) để xưởng hoặc backend tìm nguyên nhân. Diagnostics cũng là cổng truy cập (UDS, flashing) nên phải được bảo mật.","aka":["diagnostics"]},{"t":"diagram","vi":"<b>Sơ đồ<\/b>: hình vẽ mô tả kiến trúc (block, layered, deployment, sequence, lifecycle diagram). Sơ đồ tốt phải có interface, boundary và owner, không chỉ là hình minh họa.","aka":["diagrams"]},{"t":"digital","vi":"<b>Số / kỹ thuật số<\/b>. Trong bài: digital twin (bản sao số), digital engineering (làm kỹ thuật dựa trên mô hình và dữ liệu liên kết), digital continuity (thông tin nối liền giữa các tool)."},{"t":"digital twin","vi":"<b>Bản sao số<\/b> của một xe hoặc fleet trên máy tính/cloud, cập nhật bằng dữ liệu thật. Có thể sai do configuration drift hoặc telemetry cũ nên cần data governance.","aka":["digital twins"]},{"t":"digital engineering","vi":"<b>Kỹ thuật số hóa<\/b>: cách làm dựa trên mô hình, dữ liệu và tool liên kết (requirement, design, test nối với nhau) thay cho tài liệu rời. Chủ đề của unit B.1."},{"t":"direct","vi":"<b>Trực tiếp<\/b>. Hay gặp trong tên viết tắt: DMA (Direct Memory Access), DRM (Direct Rendering Manager); hoặc truy cập trực tiếp phần cứng không qua lớp trung gian."},{"t":"discovery","vi":"<b>Khám phá / tìm kiếm<\/b>. Trong bài: service discovery (consumer tự tìm service đang chạy ở đâu qua middleware) và capability discovery (feature hỏi platform xem variant có chức năng nào)."},{"t":"service discovery","vi":"<b>Tìm dịch vụ<\/b>: cơ chế để consumer tìm và kết nối service mà không cần biết trước nó chạy ở ECU/VM nào. Là cái giá phải trả của kiến trúc service-oriented (SOME/IP, DDS)."},{"t":"display","vi":"<b>Màn hình / hiển thị<\/b>. Trong CDC: cluster, màn trung tâm, HUD; đường hiển thị đi qua app, compositor, GPU, display controller tới panel. Display là nơi người dùng thấy lỗi latency hay freeze.","aka":["displays"]},{"t":"distribution","vi":"<b>Phân phối<\/b>. Trong bài chủ yếu trong tên DDS (Data Distribution Service), hoặc phân phối bản cập nhật/dữ liệu tới nhiều xe."},{"t":"DMA","vi":"<b>Truy cập bộ nhớ trực tiếp<\/b>: thiết bị đọc/ghi RAM mà không cần CPU chép từng byte. Nhanh nhưng nếu không giới hạn (bằng IOMMU) thì thiết bị của VM này có thể ghi vào bộ nhớ VM khác.","full":"Direct Memory Access","cs":true},{"t":"document","vi":"<b>Tài liệu<\/b> / ghi thành tài liệu. Trong bài: controlled document có version, approval, owner; document-based (tài liệu rời Word/Excel) đối lập với model-based; behavior “chưa document” là dependency ngầm.","aka":["documents","documented"]},{"t":"domain","vi":"<b>Miền<\/b>. (1) Nhóm chức năng của xe (cockpit, ADAS, body, powertrain) do một domain controller phụ trách; (2) lĩnh vực chuyên môn (safety, cyber); (3) clock domain, validity domain trong ngữ cảnh kỹ thuật.","aka":["domains"]},{"t":"draft","vi":"<b>Bản nháp<\/b> / soạn nháp. Trong bài: AI có thể draft test, ADR, tóm tắt log nhưng kết quả chỉ là nháp, phải được người có trách nhiệm kiểm tra trước khi thành evidence.","aka":["drafts"]},{"t":"drift","vi":"<b>Trôi lệch dần<\/b>: hai thứ lẽ ra phải khớp nhau dần khác đi theo thời gian. Ví dụ version drift (các bên lệch version), configuration drift (xe thật khác twin), kiến trúc thực tế lệch khỏi thiết kế."},{"t":"driver","vi":"Hai nghĩa: (1) <b>trình điều khiển<\/b> phần mềm nói chuyện với phần cứng (CAN driver, GPU driver, BSP); (2) <b>yếu tố quyết định<\/b>, như architecture drivers trong ADR hay cost driver. Đôi khi là tài xế.","aka":["drivers"]},{"t":"drop","vi":"<b>Bỏ / làm rơi<\/b> dữ liệu. Ví dụ message bị drop ở queue đầy, frame drop. Queue phải có policy khi đầy: drop-oldest (bỏ cũ nhất), drop-newest (bỏ mới nhất) hoặc backpressure.","aka":["drops","dropped"]},{"t":"DTC","vi":"<b>Mã lỗi chẩn đoán<\/b> lưu trong ECU khi phát hiện sự cố, đọc được ở xưởng (qua UDS) hoặc gửi về backend. Là một nguồn dữ liệu feedback và evidence khi điều tra lỗi.","aka":["DTCs"],"full":"Diagnostic Trouble Code","cs":true},{"t":"ecosystem","vi":"<b>Hệ sinh thái<\/b>: tập hợp supplier, tool, driver, thư viện, cộng đồng và nhân lực quanh một công nghệ (Linux, Android, QNX). Ecosystem mạnh giảm chi phí tích hợp và rủi ro phụ thuộc.","aka":["ecosystems"]},{"t":"ECU","vi":"<b>Bộ điều khiển điện tử<\/b>: máy tính nhúng điều khiển một chức năng trong xe (phanh, cửa, động cơ). Xe hiện đại gom nhiều ECU vào domain/zonal controller; CDC là một ECU hiệu năng cao.","aka":["ECUs"],"full":"Electronic Control Unit","cs":true},{"t":"electronic","vi":"<b>Điện tử<\/b>. Chủ yếu trong ECU (Electronic Control Unit) và E/E architecture (Electrical/Electronic, kiến trúc điện-điện tử của xe)."},{"t":"edge","vi":"<b>Biên / rìa<\/b>. (1) Edge: xử lý ngay trên xe thay vì gửi lên cloud, ví dụ edge/cloud trade-off; (2) edge case: trường hợp biên, hiếm gặp nhưng phải xử lý đúng."},{"t":"edge case","vi":"<b>Trường hợp biên<\/b>: tình huống ít gặp hoặc ở giới hạn (mất tín hiệu, giá trị cực đại, khởi động lại giữa chừng). Thường là nơi lỗi trốn, cần test riêng.","aka":["edge cases"]},{"t":"edge/cloud","vi":"<b>Edge hay cloud<\/b>: câu hỏi đặt workload/xử lý dữ liệu ngay trên xe (edge) hay trên server (cloud). Edge nhanh, riêng tư, chạy khi mất mạng; cloud mạnh, thấy toàn fleet nhưng tốn băng thông và có độ trễ."},{"t":"effort","vi":"<b>Công sức<\/b>, thường đo bằng người-ngày/người-tháng. Ví dụ validation effort, engineering effort; là đầu vào của estimate và cost/benefit khi quyết định."},{"t":"email","vi":"<b>Thư điện tử<\/b>. Trong bài là ví dụ xấu: evidence hay quyết định nằm trong email cá nhân thì sau này không tìm, không chứng minh được; phải lưu ở hệ thống có kiểm soát."},{"t":"embedded","vi":"<b>Nhúng<\/b>: phần mềm/hệ thống chạy trong thiết bị chuyên dụng (ECU, SoC trong xe) với tài nguyên giới hạn và yêu cầu thời gian thực, khác máy tính đa dụng."},{"t":"end-to-end","vi":"<b>Đầu-cuối<\/b>: tính trọn từ điểm bắt đầu tới điểm kết thúc của cả chuỗi (ví dụ latency từ frame CAN đến pixel trên màn). Số đo từng stage đẹp chưa chắc end-to-end đạt. Viết tắt E2E.","aka":["end to end"]},{"t":"engineering","vi":"<b>Kỹ thuật / công việc kỹ sư<\/b>. Trong bài: engineering economics (kinh tế kỹ thuật), digital engineering, engineering effort; governance phải phục vụ engineering chứ không chỉ là thủ tục."},{"t":"entry","vi":"<b>Lối vào / mục<\/b>. Ví dụ entry criteria (điều kiện vào gate), entry point (điểm dữ liệu đi vào hệ thống trong threat model), hoặc một dòng ghi trong register.","aka":["entries"]},{"t":"entry point","vi":"<b>Điểm vào<\/b>: nơi dữ liệu hoặc kẻ tấn công có thể đi vào hệ thống (USB, Bluetooth, OTA, diagnostic port, cloud). Xác định entry point là bước đầu của threat modeling.","aka":["entry points"]},{"t":"entry/exit","vi":"<b>Vào/ra<\/b>: thường là entry/exit criteria, điều kiện để bắt đầu và để kết thúc (pass) một gate, review hay giai đoạn. Phải đo được và được định nghĩa trước."},{"t":"environment","vi":"<b>Môi trường<\/b>: điều kiện hay nơi phần mềm chạy/test (test environment, HIL, xe thật, cloud). Trong quality scenario, environment là điều kiện vận hành (tải, nhiệt độ, chế độ) khi đo.","aka":["environments"]},{"t":"error","vi":"<b>Lỗi<\/b> trong vận hành (input sai, timeout, mất kết nối). Interface contract phải định nghĩa error behavior/error code; error propagation là lỗi lan truyền qua các lớp.","aka":["errors"]},{"t":"error propagation","vi":"<b>Lan truyền lỗi<\/b>: lỗi ở một lớp/component đi tiếp sang lớp khác. Kiến trúc phải quyết định lỗi được báo lên thế nào, chặn ở đâu, để không sập dây chuyền hay hiển thị sai âm thầm."},{"t":"escalation","vi":"<b>Chuyển cấp xử lý<\/b>: đưa vấn đề/rủi ro lên cấp có quyền quyết cao hơn khi vượt ngưỡng hoặc nhóm không tự giải quyết được. Cần đường escalation và ngưỡng được định nghĩa trước."},{"t":"escape","vi":"<b>Lọt lưới<\/b>: lỗi vượt qua các bước kiểm mà không bị phát hiện, lộ ra sau release hay ở field. Thường gặp trong defect escape, escape rate.","aka":["escapes"]},{"t":"estimate","vi":"<b>Ước tính<\/b> chi phí, công sức, rủi ro. Trong bài: estimate nên ghi dạng khoảng kèm giả định, và tách số đã xác nhận với số chưa biết.","aka":["estimates","estimation"]},{"t":"Ethernet","vi":"<b>Chuẩn mạng có dây<\/b> băng thông cao. Automotive Ethernet là phiên bản cho xe, làm backbone giữa domain/zone controller, mang SOME/IP, DDS, video; thay dần CAN ở các luồng dữ liệu lớn."},{"t":"event","vi":"<b>Sự kiện<\/b>: điều xảy ra tại một thời điểm (message đến, nút bấm, lỗi). Trong service interface, event là thông báo producer đẩy cho consumer; trong đo latency, metric đi từ event này đến event khác.","aka":["events"]},{"t":"evidence","vi":"<b>Bằng chứng<\/b>: kết quả đo, test report, trace, review record… chứng minh một tuyên bố là đúng. Khái niệm trung tâm của khóa học: gate, release, quyết định đều phải dựa trên evidence gắn đúng baseline."},{"t":"evolution","vi":"<b>Sự tiến hóa / thay đổi dần<\/b> theo thời gian. Ví dụ schema evolution (dữ liệu đổi cấu trúc qua các version mà vẫn tương thích), lifecycle evolution của kiến trúc sau SOP."},{"t":"schema evolution","vi":"<b>Tiến hóa schema<\/b>: thay đổi cấu trúc dữ liệu qua các version (thêm/bỏ field) mà bên cũ, bên mới vẫn đọc được. Cần quy tắc: thay đổi nào là breaking, không tái dùng ID field, deprecate trước khi xóa."},{"t":"execution","vi":"<b>Thực thi<\/b>: việc chạy phần mềm. Ví dụ execution platform (nền chạy workload), Execution Management của AUTOSAR Adaptive, WCET (Worst-Case Execution Time)."},{"t":"exit","vi":"<b>Lối ra / rút ra<\/b>. Ví dụ exit criteria (điều kiện để pass gate), exit cost (chi phí rời bỏ một supplier để chuyển sang bên khác), exit condition của một quyết định."},{"t":"exit cost","vi":"<b>Chi phí rút lui<\/b>: chi phí phải trả nếu muốn bỏ supplier/công nghệ hiện tại để chuyển sang lựa chọn khác. Nên được tính vào TCO để thấy rủi ro bị khóa vào supplier."},{"t":"expected","vi":"<b>Kỳ vọng / dự kiến<\/b>. Ví dụ expected result (kết quả đúng mà test so sánh), expected failure cost, expected exposure (thiệt hại kỳ vọng = số xe × xác suất × chi phí)."},{"t":"exposure","vi":"<b>Mức phơi nhiễm rủi ro<\/b>: mức thiệt hại có thể xảy ra, thường ước bằng phạm vi ảnh hưởng × xác suất × chi phí/impact. Cũng có nghĩa là lộ ra ngoài (data exposure, interface bị expose)."},{"t":"fact","vi":"<b>Sự thật đã xác minh<\/b>, khác giả định hay ý kiến. Bài tập yêu cầu tách rõ phần nào là fact, phần nào là giả định, phần nào cần xác minh với dự án.","aka":["facts"]},{"t":"fail","vi":"<b>Hỏng / không đạt<\/b>. Test fail là không đạt tiêu chí; component fail là ngừng hoạt động đúng. Fail-safe: khi lỗi thì chuyển về trạng thái an toàn.","aka":["fails","failed"]},{"t":"fail-safe","vi":"<b>An toàn khi hỏng<\/b>: thiết kế để khi một phần lỗi, hệ thống tự về trạng thái an toàn (ví dụ tắt chức năng phụ nhưng vẫn giữ cảnh báo) thay vì hành xử nguy hiểm."},{"t":"failure","vi":"<b>Sự cố / hỏng hóc<\/b>: hệ thống không thực hiện đúng chức năng. Ví dụ failure cost (chi phí xử lý lỗi: warranty, recall), failure mode, failure injection, change failure rate.","aka":["failures"]},{"t":"failure cost","vi":"<b>Chi phí sự cố<\/b>: tiền phải trả khi lỗi ra tới khách hàng: warranty, service campaign, recall, hỗ trợ khách, điều tra. Thường lớn hơn nhiều so với chi phí phòng ngừa."},{"t":"fallback","vi":"<b>Phương án dự phòng<\/b>: hành vi hoặc nguồn thay thế khi đường chính lỗi (mất kết nối cloud, service không phản hồi). Ví dụ dùng local behavior, hiển thị mặc định an toàn, chuyển sang nguồn dữ liệu khác."},{"t":"fault","vi":"<b>Lỗi gốc / sự cố<\/b> trong một thành phần, có thể dẫn đến failure. Trong bài: fault containment (chặn lỗi lan), fault tolerance (chịu lỗi), fault injection (cố ý gây lỗi để test).","aka":["faults"]},{"t":"fault injection","vi":"<b>Tiêm lỗi<\/b>: cố ý gây lỗi (giết process, làm đầy CPU, mất mạng, hỏng message) để kiểm tra isolation, degraded mode và recovery có hoạt động đúng không."},{"t":"fault tolerance","vi":"<b>Khả năng chịu lỗi<\/b>: hệ thống vẫn tiếp tục hoạt động (đầy đủ hoặc suy giảm) khi một phần bị lỗi, nhờ dự phòng, phát hiện lỗi và recovery."},{"t":"feature","vi":"<b>Tính năng<\/b> mà người dùng nhận thấy (camera lùi, điều hướng, cảnh báo tốc độ). Một feature thường đi xuyên nhiều lớp và nhiều owner; trong SDV feature có thể thêm/bật sau bán qua OTA.","aka":["features"]},{"t":"feature flag","vi":"<b>Công tắc tính năng<\/b>: cấu hình bật/tắt một feature mà không cần cài lại phần mềm, theo nhóm xe, thị trường hay variant. Cho phép rollout dần và tắt nhanh khi có lỗi, nhưng làm tăng số tổ hợp phải test.","aka":["feature flags"]},{"t":"feedback","vi":"<b>Phản hồi<\/b>: thông tin quay ngược về để cải tiến. Ví dụ dữ liệu fleet (telemetry, DTC, crash) về lại team phát triển, hay metric chất lượng giúp chỉnh quy trình."},{"t":"feedback loop","vi":"<b>Vòng phản hồi<\/b>: chu trình đo kết quả rồi dùng nó điều chỉnh hành động tiếp theo (deploy → thu dữ liệu → phân tích → cải tiến). Vòng càng ngắn, lỗi càng được phát hiện và sửa sớm.","aka":["feedback loops"]},{"t":"FFI","vi":"<b>Không bị can nhiễu<\/b>: yêu cầu (theo ISO 26262) chứng minh phần ít quan trọng không làm hỏng phần quan trọng về bộ nhớ, timing, tài nguyên, giao tiếp. Là bằng chứng chính cho mixed criticality trên một SoC.","full":"Freedom From Interference","cs":true},{"t":"Freedom From Interference","vi":"Tên đầy đủ của <b>FFI<\/b>: bằng chứng rằng workload ít quan trọng (infotainment) không can nhiễu workload quan trọng (cluster, cảnh báo) về memory, CPU/timing, I/O, giao tiếp khi chạy chung phần cứng."},{"t":"field","vi":"Hai nghĩa: (1) <b>trường dữ liệu<\/b> trong message/schema (ví dụ thêm field speed_source); (2) <b>thực địa<\/b>: xe đã bán đang chạy ngoài thị trường (field issue, field exposure, dữ liệu từ field).","aka":["fields"]},{"t":"file","vi":"<b>Tệp<\/b> dữ liệu hoặc chương trình. Ví dụ device file của driver, file trong gói update (mỗi file có hash), binary file chỉ nhận bản chạy không có source.","aka":["files"]},{"t":"fix","vi":"<b>Bản sửa / sửa lỗi<\/b>. Ví dụ bug fix, defect fix, security fix. Trong RCA: fix phải ở lớp gốc của vấn đề, không chỉ chữa triệu chứng.","aka":["fixes","fixed"]},{"t":"flag","vi":"<b>Cờ<\/b>: giá trị bật/tắt trong cấu hình hay dữ liệu. Thường gặp là feature flag (bật/tắt tính năng theo nhóm xe, thị trường).","aka":["flags"]},{"t":"flash","vi":"<b>Bộ nhớ flash<\/b>: bộ nhớ lưu trữ không mất khi tắt điện trên ECU. Cũng là động từ: ghi firmware vào ECU (flashing). A/B partition cần thêm flash; ghi quá nhiều làm flash mòn (flash wear)."},{"t":"fleet","vi":"<b>Đội xe<\/b>: toàn bộ xe đã bán/đang vận hành của một model hay OEM. Trong bài: rollout OTA theo % fleet, fleet data, fleet operator; lỗi ở fleet nhân lên theo số xe bị ảnh hưởng.","aka":["fleets"]},{"t":"fleet operator","vi":"<b>Đơn vị vận hành đội xe<\/b> (taxi, logistics, cho thuê): khách hàng mua và vận hành nhiều xe, là nguồn doanh thu, feedback và dữ liệu vận hành.","aka":["fleet operators"]},{"t":"flow","vi":"<b>Luồng / dòng chảy<\/b>. Ví dụ data flow (luồng dữ liệu), feature flow xuyên stack, platform/pipeline flow, cash flow (dòng tiền), risk flow (rủi ro chuyển giữa các bên).","aka":["flows"]},{"t":"cash flow","vi":"<b>Dòng tiền<\/b>: tiền chi ra và thu vào theo thời gian của một dự án. Dùng để tính NPV, IRR, payback khi đánh giá business case."},{"t":"format","vi":"<b>Định dạng<\/b> của dữ liệu (kiểu, cấu trúc, bố cục byte, màu/pixel). Sai format giữa hai bên là nguồn lỗi phổ biến; ví dụ message sai format làm service crash.","aka":["formats"]},{"t":"forward","vi":"<b>Tiến lên / chuyển tiếp<\/b>. Ví dụ forward recovery (sửa bằng bản mới hơn thay vì quay lui), forward compatibility (bản cũ chịu được dữ liệu mới), store-and-forward."},{"t":"forward recovery","vi":"<b>Phục hồi tiến<\/b>: khắc phục lỗi bằng cách phát hành bản sửa mới hơn thay vì rollback, dùng khi không quay lui được (dữ liệu đã đổi format, xe offline không nhận lệnh rollback)."},{"t":"frame","vi":"<b>Khung<\/b>. (1) Một gói dữ liệu trên bus (CAN frame); (2) một khung hình hiển thị (frame rate, frame age); (3) bước Frame (đóng khung câu hỏi) trong judgment playbook.","aka":["frames"]},{"t":"framework","vi":"<b>Khung phần mềm / khung tư duy<\/b>. (1) Lớp phần mềm cung cấp sẵn dịch vụ cho app (Android framework, audio/graphics framework); (2) khung phương pháp để phân tích, đánh giá.","aka":["frameworks"]},{"t":"framing","vi":"<b>Đóng khung vấn đề<\/b>: xác định rõ câu hỏi cần quyết định, phạm vi, ràng buộc, giả định, owner và deadline trước khi phân tích. Framing sai thì phân tích kỹ đến đâu cũng trả lời sai câu."},{"t":"freedom","vi":"<b>Sự tự do / không bị<\/b>. Trong bài xuất hiện trong Freedom From Interference (FFI): không bị phần khác can nhiễu."},{"t":"freeze","vi":"<b>Đóng băng / treo<\/b>. (1) Mốc chốt không thay đổi nữa (hardware freeze); (2) màn hình bị treo (screen freeze); (3) freeze evidence: giữ nguyên log/trace/config làm bằng chứng trước khi điều tra."},{"t":"freshness","vi":"<b>Độ tươi của dữ liệu<\/b>: dữ liệu được tạo cách đây bao lâu và còn dùng được không. Contract phải ghi max age; quá hạn thì coi là stale và hiển thị/hành xử theo degraded mode."},{"t":"full","vi":"<b>Đầy / toàn bộ<\/b>. Ví dụ queue/buffer full (đầy) cần full policy, full-scale (mức tín hiệu audio tối đa), full range (dải màu 0–255)."},{"t":"function","vi":"<b>Chức năng<\/b> mà hệ thống/xe phải thực hiện (hoặc hàm trong code). Kiến trúc xe là cách phân bổ function vào compute, network, ECU. Fitness function: chỉ số kiến trúc đo tự động.","aka":["functions"]},{"t":"functional","vi":"<b>Thuộc về chức năng<\/b>. Functional requirement: hệ thống phải làm gì (khác NFR: làm tốt đến đâu). Functional safety: an toàn chức năng theo ISO 26262."},{"t":"functional safety","vi":"<b>An toàn chức năng<\/b>: đảm bảo hệ thống điện-điện tử không gây nguy hiểm khi có lỗi phần cứng/phần mềm, theo ISO 26262 (dùng ASIL). Phải phối hợp với cybersecurity vì tấn công có thể dẫn tới hazard."},{"t":"functional requirement","vi":"<b>Yêu cầu chức năng<\/b>: mô tả hệ thống phải làm gì (hiển thị tốc độ, phát cảnh báo). Khác NFR (non-functional) mô tả chất lượng: nhanh, ổn định, an toàn đến đâu.","aka":["functional requirements"]},{"t":"gate","vi":"<b>Cổng kiểm soát<\/b>: điểm dừng bắt buộc trong quy trình, chỉ đi tiếp khi đạt tiêu chí đo được, có evidence và người có quyền chốt. Gate thật phải chặn được; gate luôn được waiver thì không phải gate.","aka":["gates"]},{"t":"quality gate","vi":"<b>Cổng chất lượng<\/b>: mốc kiểm tra (G0–G4, release gate) có entry/exit criteria, evidence bắt buộc, owner và hành động khi fail. Chỉ pass khi bằng chứng gắn đúng baseline/build được release.","aka":["quality gates"]},{"t":"gateway","vi":"<b>Cổng nối mạng<\/b>: ECU/thành phần chuyển dữ liệu giữa các mạng hoặc domain (CAN ↔ Ethernet, xe ↔ cloud) và lọc những gì được phép đi qua. Là lớp phòng thủ bảo mật quan trọng.","aka":["gateways"]},{"t":"gear","vi":"<b>Số (hộp số)<\/b> của xe: P, R, N, D… Trong bài là một ví dụ signal xe được hiển thị trên cluster, thường kết hợp với speed và các signal khác."},{"t":"governance","vi":"<b>Quản trị<\/b>: hệ thống quy tắc, vai trò, quyền quyết định và cơ chế kiểm soát (gate, review, change control, waiver) để công việc đi đúng hướng. Trong bài nhấn mạnh governance phải phục vụ engineering."},{"t":"governed","vi":"<b>Được quản trị / có kiểm soát<\/b>. Thường trong governed AI: dùng AI trong quy trình kỹ thuật với quyền hạn, ranh giới dữ liệu, người kiểm và trách nhiệm rõ ràng."},{"t":"governed AI","vi":"<b>AI có quản trị<\/b>: AI được dùng để hỗ trợ (draft test, tóm tắt log) nhưng không giữ quyền approve, waiver hay release; có mức ủy quyền, data boundary, người review và provenance cho đầu ra."},{"t":"GPU","vi":"<b>Bộ xử lý đồ họa<\/b>: phần cứng vẽ hình, render giao diện và tăng tốc tính toán song song. Trong CDC nhiều VM dùng chung GPU, nên chia sẻ/ảo hóa GPU và tranh chấp GPU ảnh hưởng frame time của cluster.","aka":["GPUs"],"full":"Graphics Processing Unit","cs":true},{"t":"graphics","vi":"<b>Đồ họa<\/b>: phần vẽ và hiển thị hình ảnh (render, compositor, GPU, display). Graphics &amp; Display là chủ đề của unit C.2."},{"t":"guest","vi":"<b>Khách<\/b>: hệ điều hành/VM chạy trên hypervisor (guest OS), ví dụ guest Android và guest QNX trên cùng SoC. Guest chỉ thấy tài nguyên ảo do hypervisor cấp.","aka":["guests"]},{"t":"guest OS","vi":"<b>Hệ điều hành khách<\/b>: OS chạy bên trong một VM do hypervisor quản lý (Android Automotive, QNX, Linux). Mỗi guest OS có kernel riêng, tách biệt với guest khác."},{"t":"guideline","vi":"<b>Hướng dẫn / quy tắc<\/b>. Thường là coding guideline (ví dụ MISRA, CERT): bộ quy tắc viết code an toàn, được kiểm bằng code review và static analysis.","aka":["guidelines"]},{"t":"HAL","vi":"<b>Lớp trừu tượng phần cứng<\/b>: lớp phần mềm che chi tiết của từng phần cứng, đưa ra interface chung cho lớp trên. Ví dụ Vehicle HAL, Audio HAL trong Android; giúp đổi phần cứng mà không sửa app.","full":"Hardware Abstraction Layer","cs":true},{"t":"hard","vi":"<b>Cứng / bắt buộc<\/b>. Ví dụ hard real-time (trễ hạn là failure), hard constraint/hard requirement (ràng buộc không được đánh đổi), hard-code (viết cứng giá trị vào code)."},{"t":"hard real-time","vi":"<b>Thời gian thực cứng<\/b>: lỡ deadline là failure nghiêm trọng, không chấp nhận được. Khác soft real-time, nơi trễ chỉ làm giảm chất lượng.","aka":["soft real-time"]},{"t":"hard constraint","vi":"<b>Ràng buộc cứng<\/b>: điều kiện không được đem ra đánh đổi (safety, cybersecurity, tuân thủ quy định, quality gate tối thiểu). ROI cao không bù được cho việc vi phạm ràng buộc cứng.","aka":["hard constraints","hard requirement","hard requirements"]},{"t":"hardware","vi":"<b>Phần cứng<\/b>: chip, board, bộ nhớ, cảm biến, màn hình, dây. Trong bài: quyết định phần cứng (flash, headroom) khó đổi sau SOP; abstraction giúp phần mềm sống lâu hơn phần cứng."},{"t":"hardware-in-the-loop","vi":"<b>Phần cứng trong vòng lặp<\/b> (HIL): bàn test dùng ECU thật, còn phần còn lại của xe được mô phỏng bằng tín hiệu giả lập. Dùng để đo timing, I/O và tích hợp mà mô phỏng thuần không bắt được."},{"t":"headroom","vi":"<b>Dư địa tài nguyên<\/b>: phần năng lực còn trống (CPU, RAM, GPU, băng thông, flash) sau khi trừ tải hiện tại, để thêm feature qua OTA hay chịu tải đỉnh. Phải biện minh bằng roadmap vì headroom tốn tiền mỗi xe."},{"t":"health","vi":"<b>Sức khỏe hệ thống<\/b>: tình trạng hoạt động bình thường hay không. Ví dụ health metric (crash rate, lỗi) khi rollout OTA, health check sau update, health monitoring với watchdog."},{"t":"health metric","vi":"<b>Chỉ số sức khỏe<\/b>: số đo cho biết hệ thống đang ổn hay không (tỉ lệ crash, reset, lỗi, latency). Trong staged rollout, health metric quyết định mở rộng hay dừng/rollback.","aka":["health metrics"]},{"t":"health monitoring","vi":"<b>Giám sát sức khỏe<\/b>: liên tục theo dõi trạng thái service, process, VM (heartbeat, watchdog, metric tài nguyên) để phát hiện treo/lỗi và kích hoạt recovery."},{"t":"HIL","vi":"Kiểm thử với <b>ECU/phần cứng thật<\/b> nối vào môi trường mô phỏng (xe, cảm biến, bus giả lập). Trong bài, HIL là bậc test gần thực tế nhất trước khi lên xe: đo timing end-to-end, hành vi khi mất tín hiệu, những thứ SIL trên PC không chứng minh được.","aka":["HIL bench","HIL test"],"full":"Hardware-in-the-Loop","cs":true},{"t":"history","vi":"Lịch sử, bản ghi những gì đã xảy ra. Trong bài: <i>change history<\/i> (lịch sử sửa đổi của tài liệu/artifact), <i>defect history<\/i> (lịch sử lỗi) — dữ liệu cần giữ lại để truy vết, điều tra RCA và đánh giá supplier.","aka":["histories"]},{"t":"HMI","vi":"Giao diện người–máy: màn hình, nút bấm, âm báo, kim đồng hồ… mà người lái nhìn/nghe/chạm. Trong CDC, HMI quyết định thông tin nào hiện lên cluster/IVI và cách hiển thị khi dữ liệu stale hoặc lỗi (ví dụ hiện \"--\").","full":"Human-Machine Interface","cs":true},{"t":"human-machine interface","vi":"Tên đầy đủ của HMI — giao diện người–máy: phần người lái tương tác trực tiếp (màn hình, nút, âm báo). Với nội dung safety-relevant, HMI phải bảo đảm cảnh báo hiển thị đúng và kịp thời.","aka":["human-machine"]},{"t":"host","vi":"Máy chủ/máy \"chủ nhà\". Trong bài có hai nghĩa: (1) <i>host OS<\/i> — hệ điều hành chạy bên dưới phần mềm ảo hóa Type-2 hoặc container; (2) <i>host test<\/i> — test chạy trên máy phát triển (PC), khác với chạy trên target (phần cứng thật).","aka":["hosts"]},{"t":"host OS","vi":"Hệ điều hành \"chủ\" chạy trực tiếp trên máy, bên trên nó là hypervisor Type-2 hoặc container (chia sẻ kernel của host). Trên xe thường dùng hypervisor Type-1 chạy thẳng trên hardware thay vì dựa vào host OS."},{"t":"HUD","vi":"Màn hình chiếu thông tin (tốc độ, chỉ đường, cảnh báo) lên kính lái hoặc tấm kính trước mặt người lái để không phải cúi nhìn. Là một trong các màn hình mà CDC điều khiển, cùng cluster và IVI.","full":"Head-Up Display","cs":true},{"t":"hybrid","vi":"Lai, kết hợp hai cách. Trong bài: kiến trúc E/E <i>hybrid<\/i> (trộn domain, zonal, centralized), đặt workload <i>hybrid<\/i> (một phần trên xe/edge, một phần trên cloud), quy trình <i>V-Model/agile/hybrid<\/i>."},{"t":"hypervisor","vi":"Lớp phần mềm nằm giữa phần cứng và các hệ điều hành, chia một SoC thành nhiều <b>máy ảo (VM)<\/b> và quản lý CPU, memory, interrupt, device cho từng guest. Trong CDC, hypervisor cho phép cluster (RTOS/QNX) và IVI (Android) chạy cách ly trên cùng chip.","aka":["hypervisors"]},{"t":"hypothesis","vi":"Giả thuyết — một phỏng đoán có thể kiểm chứng. Trong RCA và đo hiệu năng, phải viết hypothesis kèm dự đoán (prediction) <b>trước<\/b> khi thử, rồi dùng phép đo để xác nhận hoặc bác bỏ, thay vì sửa theo cảm tính.","aka":["hypotheses"]},{"t":"hypothesis testing","vi":"Kiểm chứng giả thuyết: nêu nguyên nhân nghi ngờ, dự đoán kết quả nếu nó đúng, rồi thử nghiệm có kiểm soát (đổi một yếu tố mỗi lần) để xác nhận hoặc loại bỏ. Là bước cốt lõi của điều tra lỗi/RCA trong bài."},{"t":"I/O","vi":"Vào/ra: dữ liệu và tín hiệu đi vào/ra hệ thống — cảm biến, cơ cấu chấp hành, storage, mạng. Trong bài: zonal controller gom I/O theo vị trí trên xe; <i>storage I/O<\/i> và tranh chấp I/O giữa các VM là nguồn gây trễ.","full":"Input/Output","cs":true},{"t":"icon","vi":"Biểu tượng hình ảnh nhỏ trên màn hình. Trong bài là ví dụ kinh điển: đổi màu icon trên IVI là thay đổi rủi ro thấp, còn icon cảnh báo trên cluster liên quan safety cần test và review chặt hơn.","aka":["icons"]},{"t":"ID","vi":"Mã định danh duy nhất cho một đối tượng (requirement, test case, tài liệu, build, request). Trong bài, mọi artifact cần ID + version + owner để liên kết truy vết; <i>correlation ID<\/i> nối các log của cùng một request.","aka":["IDs"],"full":"Identifier","cs":true},{"t":"identification","vi":"Sự nhận dạng, xác định danh tính. Trong bài: <i>VIN – Vehicle Identification Number<\/i> (số định danh duy nhất của xe), và việc xác định rõ các điểm đứt (link thủ công, chuyển tool/supplier) trong chuỗi truy vết."},{"t":"identity","vi":"Danh tính, mã định danh của một thứ. Trong bài: mỗi artifact/tài liệu/tín hiệu cần identity (ID duy nhất) để liên kết trong digital thread và kiểm chứng rằng các phép đo đang theo dõi \"cùng một\" signal.","aka":["identities"]},{"t":"image","vi":"Ảnh. Trong phần mềm, <i>software image<\/i> là gói nhị phân hoàn chỉnh được nạp/ghi lên ECU (OS, ứng dụng, cấu hình). OTA ghi image mới; cần A/B slot hoặc resume để xe vẫn boot được nếu đang ghi mà mất điện.","aka":["images"]},{"t":"impact","vi":"Tác động, mức ảnh hưởng. Trong bài: <i>impact<\/i> của một thay đổi (lan tới code, test, OTA, bao nhiêu xe), và trong đánh giá rủi ro risk = likelihood × impact. Mức evidence/review đi theo impact và risk, không theo số dòng code.","aka":["impacts"]},{"t":"implementation","vi":"Sự hiện thực hóa — viết code/cấu hình để biến thiết kế thành phần mềm chạy được. Là một chặng trong lifecycle (Requirement → Design → Implementation → Verification…). <i>Implementation detail<\/i>: chi tiết bên trong mà lớp trên không nên phụ thuộc.","aka":["implementations"]},{"t":"in-vehicle","vi":"Bên trong xe, chạy trên xe (đối lập với cloud/backend). Gặp trong <i>in-vehicle network<\/i> (mạng trong xe: CAN, LIN, Ethernet) và <i>In-Vehicle Infotainment<\/i> (IVI)."},{"t":"in-vehicle infotainment","vi":"Tên đầy đủ của IVI — hệ thống thông tin–giải trí trên xe: bản đồ, media, kết nối điện thoại, app. Thường chạy Android Automotive/Linux trên CDC, cách ly với cluster vì không đòi hỏi mức safety như đồng hồ."},{"t":"in-vehicle network","vi":"Mạng truyền dữ liệu giữa các ECU trong xe: CAN/CAN FD, LIN, FlexRay, Automotive Ethernet (SOME/IP, DDS). Lệnh từ IVI không nên đi thẳng xuống mạng này mà phải qua gateway có kiểm tra quyền.","aka":["in-vehicle networks"]},{"t":"incident","vi":"Sự cố — sự kiện bất thường gây hoặc có thể gây hại (lỗi trên fleet, tấn công bảo mật). Trong bài, xử lý incident cần một <i>incident owner<\/i> điều phối, timeline, evidence và bài học rút ra (post-incident).","aka":["incidents"]},{"t":"infotainment","vi":"Ghép từ information + entertainment: thông tin–giải trí (bản đồ, nhạc, video, điện thoại, app). Trong CDC là phần IVI, ít critical hơn cluster, nên được tách vào partition/VM riêng để lỗi hoặc quá tải không lan sang cluster."},{"t":"injection","vi":"Sự tiêm/đưa vào. Trong bài chủ yếu là <i>fault injection<\/i>: cố tình gây lỗi (kill process, mất mạng, flood traffic) để kiểm chứng isolation và cơ chế phục hồi hoạt động đúng như thiết kế."},{"t":"input","vi":"Đầu vào — dữ liệu/tín hiệu/tài liệu đi vào một hàm, service hay hoạt động. Trong bài: mỗi hoạt động quy trình phải có input và output rõ; mỗi interface phải định nghĩa hành vi khi input sai hoặc thiếu.","aka":["inputs"]},{"t":"input validation","vi":"Kiểm tra dữ liệu đầu vào (định dạng, phạm vi, độ dài, nguồn gốc) trước khi xử lý, để dữ liệu sai hoặc độc hại không gây lỗi hay bị khai thác. Là một control bảo mật cơ bản ở biên của service/interface."},{"t":"inspection","vi":"Kiểm tra/thẩm định. Trong bài: (1) hình thức review chính thức có checklist, vai trò rõ và ghi finding; (2) một trong các cách verification (test / inspection / analysis / demonstration) để chứng minh requirement đạt.","aka":["inspections"]},{"t":"integration","vi":"Tích hợp — ghép các thành phần (phần mềm, phần cứng, của nhiều supplier) lại và cho chạy cùng nhau. Trong lifecycle là giai đoạn lỗi giao diện lộ ra; phát hiện ở integration thì sửa đắt, nên interface phải chốt sớm.","aka":["integrations"]},{"t":"integration test","vi":"Kiểm thử tích hợp: kiểm tra các thành phần đã ghép có làm việc đúng với nhau qua interface (dữ liệu, timing, lỗi) hay không, sau khi từng phần đã pass unit test.","aka":["integration tests","integration testing"]},{"t":"integrity","vi":"Tính toàn vẹn: dữ liệu/phần mềm không bị sửa trái phép hay hỏng. Là một trong ba trụ bảo mật (confidentiality, integrity, availability); OTA cần integrity (ký số, kiểm hash) trước khi cài. Trong ASIL, \"Integrity Level\" là mức yêu cầu an toàn."},{"t":"interface","vi":"Giao diện/điểm tiếp giáp giữa hai thành phần (API, signal, service, bus). Trong bài là khái niệm trung tâm: mỗi interface cần owner, version và contract rõ (dữ liệu, đơn vị, timing, lỗi), vì phần lớn lỗi tích hợp nằm ở ranh giới này.","aka":["interfaces"]},{"t":"interface spec","vi":"Đặc tả interface: tài liệu mô tả chi tiết kỹ thuật của một interface (tín hiệu, kiểu dữ liệu, timing, mã lỗi). Gần nghĩa với interface contract; contract nhấn mạnh thêm owner và cam kết hai bên.","aka":["interface specification"]},{"t":"interference","vi":"Sự can thiệp, ảnh hưởng chéo: phần mềm này làm chậm hoặc hỏng phần mềm kia khi dùng chung CPU, memory, cache, device, DMA, network. Mục tiêu của isolation là chứng minh <b>FFI – Freedom From Interference<\/b> cho phần critical."},{"t":"internal","vi":"Nội bộ, bên trong tổ chức. Trong bài: staged rollout đi từ xe <i>internal<\/i> (xe nội bộ/xe của nhân viên) → pilot → cohort nhỏ → mở rộng; nhóm/kỹ sư nội bộ; IRR (Internal Rate of Return – tỷ suất hoàn vốn nội bộ)."},{"t":"interrupt","vi":"Ngắt — tín hiệu phần cứng báo CPU dừng việc đang làm để xử lý sự kiện (có frame mạng, timer, nút bấm). Hypervisor phải phân phối interrupt cho đúng guest; xử lý ngắt dài hoặc dồn dập gây trễ và jitter.","aka":["interrupts"]},{"t":"IP","vi":"Có hai nghĩa trong bài: (1) <i>Internet Protocol<\/i> — giao thức mạng, như trong SOME/IP (middleware chạy trên Ethernet/IP); (2) <i>Intellectual Property<\/i> — sở hữu trí tuệ, ví dụ \"IP vendor\" bán bản quyền thiết kế chip.","cs":true},{"t":"IPC","vi":"Trao đổi dữ liệu giữa các process/VM chạy riêng (message passing, shared memory, Binder…). Trong CDC, IPC giữa cluster và IVI là đường xuyên qua ranh giới cách ly, nên cần contract, validation và policy khi đầy/chậm.","full":"Inter-Process Communication","cs":true},{"t":"IPC contract","vi":"Contract cho một kênh IPC: định nghĩa dữ liệu, kích thước, tần suất, ai sở hữu buffer, thứ tự, hành vi khi queue đầy hoặc bên kia chết. Giúp hai process/VM không phụ thuộc vào giả định ngầm của nhau.","aka":["IPC contracts"],"cs":true},{"t":"ISO","vi":"Tổ chức Tiêu chuẩn hóa Quốc tế. Trong bài gặp qua các chuẩn ô tô: ISO 26262 (an toàn chức năng), ISO/SAE 21434 (an ninh mạng ô tô).","full":"International Organization for Standardization","cs":true},{"t":"ISO 26262","vi":"Chuẩn quốc tế về <b>an toàn chức năng<\/b> (functional safety) cho hệ thống điện/điện tử trên ô tô; định nghĩa ASIL (A–D), quy trình và work product cần có. Trong bài là nguồn yêu cầu evidence cho phần safety như cluster cảnh báo.","cs":true},{"t":"ISO/SAE 21434","vi":"Chuẩn quốc tế về <b>an ninh mạng (cybersecurity)<\/b> trong vòng đời xe: TARA, yêu cầu bảo mật, giám sát lỗ hổng sau bán. Thường đi cùng quy định UNECE R155 khi chứng minh CSMS.","cs":true},{"t":"isolation","vi":"Sự cách ly: ngăn lỗi, quá tải hoặc tấn công ở một phần lan sang phần khác (về không gian bộ nhớ, thời gian CPU, tài nguyên, giao tiếp). Trong CDC, isolation giữa IVI và cluster phải được <b>chứng minh bằng đo/test<\/b>, không chỉ vẽ trên sơ đồ."},{"t":"issue","vi":"Vấn đề, lỗi, sự cố cần xử lý. Trong bài: <i>fleet issue detection<\/i> (phát hiện sớm lỗi lặp lại trên đội xe), số issue phát sinh do tích hợp công nghệ, issue được ghi và theo dõi tới khi đóng.","aka":["issues"]},{"t":"item","vi":"Mục, hạng mục, đối tượng. Trong bài: <i>evidence item<\/i> (một mẩu bằng chứng), <i>configuration item<\/i> (thành phần được quản lý version), và trong ISO 26262, <i>item<\/i> là hệ thống/chức năng được phân tích an toàn.","aka":["items"]},{"t":"item definition","vi":"Bước đầu của phân tích safety/security (ISO 26262, ISO/SAE 21434): mô tả phạm vi, chức năng, ranh giới và môi trường của hệ thống được phân tích. Danh sách asset/threat phải dựa trên item definition."},{"t":"IVI","vi":"Hệ thống thông tin–giải trí trên xe: bản đồ, media, điện thoại, app (thường chạy Android Automotive). Trong CDC, IVI chạy cạnh cluster trên cùng SoC nhưng trong VM/partition riêng; lỗi hay quá tải của IVI không được làm hỏng cluster.","full":"In-Vehicle Infotainment","cs":true},{"t":"jitter","vi":"Độ dao động thời gian: cùng một việc nhưng lúc nhanh lúc chậm (ví dụ chu kỳ 20 ms nhưng có lần 18, có lần 35 ms). Trong bài, jitter quan trọng không kém latency trung bình vì nó làm kim tốc độ giật và có thể làm lỡ deadline."},{"t":"kernel","vi":"Nhân hệ điều hành — phần lõi quản lý process, memory, scheduling, driver. Container chia sẻ kernel với host nên cách ly yếu hơn VM; ngày hết hỗ trợ của kernel/BSP là rủi ro bảo trì dài hạn cho xe.","aka":["kernels"]},{"t":"key","vi":"Có hai nghĩa: (1) chính, quan trọng — <i>key takeaways<\/i>, key decision; (2) <b>khóa mật mã<\/b> dùng để ký/mã hóa (ví dụ key ký bản update OTA), cần quản lý vòng đời: tạo, lưu an toàn (HSM), xoay vòng, thu hồi.","aka":["keys"]},{"t":"key takeaways","vi":"Những ý chính rút ra, cần nhớ sau khi học. Trong phần reflection, bạn chọn 3–5 ý sẽ thay đổi cách bạn ra quyết định, không phải tóm tắt lại bài.","aka":["key takeaway","takeaways","takeaway"]},{"t":"key management","vi":"Quản lý khóa mật mã: tạo, lưu trữ an toàn, phân phối, xoay vòng (rotate), thu hồi (revoke) key và certificate. Mã hóa vô dụng nếu key bị lộ, nên key management là phần cốt lõi của secure OTA."},{"t":"kickoff","vi":"Buổi/bước khởi động một dự án hay khóa học. Trong khóa này, Kickoff là nơi bạn chọn một bối cảnh dự án (ví dụ vehicle-data service trên CDC) làm sợi chỉ xuyên suốt mọi bài và assignment.","aka":["kick-off"]},{"t":"kill","vi":"Giết, buộc dừng một process/service. Trong bài: <i>OOM kill<\/i> (OS giết process khi hết bộ nhớ), test bằng cách kill producer để xem consumer xử lý thế nào, và <i>kill switch<\/i> để tắt khẩn cấp."},{"t":"kill switch","vi":"Công tắc tắt khẩn cấp: cơ chế cho phép tắt ngay một tính năng/workflow (từ xa hoặc qua cấu hình) khi phát hiện vấn đề, không cần chờ bản release mới. Đi cùng monitoring và rollback."},{"t":"km/h","vi":"Kilomét trên giờ — đơn vị tốc độ xe. Trong bài là ví dụ kinh điển về contract: provider đổi đơn vị từ km/h sang m/s mà không đổi version, khiến cluster hiển thị sai dù code hai bên đều \"đúng\"."},{"t":"lab","vi":"Phòng thí nghiệm/phòng test có bench, HIL, thiết bị đo. Trong bài: chi phí duy trì lab là chi phí cố định; nhiều lỗi không lộ ở lab mà chỉ lộ trên fleet ngoài thực tế, nên lab pass chưa đủ.","aka":["labs"]},{"t":"laptop","vi":"Máy tính xách tay. Trong bài là ví dụ của môi trường phát triển: unit test hay benchmark pass trên laptop <b>không chứng minh<\/b> được kết quả trên target (phần cứng thật của xe).","aka":["laptops"]},{"t":"latency","vi":"Độ trễ: thời gian từ khi có sự kiện/dữ liệu đến khi có phản hồi (ví dụ từ cảm biến tốc độ đến kim trên cluster). Trong bài, latency phải ghi bằng số đo được (P95, max) trên target, dưới tải thực, không chỉ trung bình.","aka":["latencies"]},{"t":"layer","vi":"Lớp, tầng. Trong kiến trúc phần mềm xe, stack chia thành các layer (hardware, BSP/driver, hypervisor, OS, middleware, application); lớp dưới cung cấp dịch vụ cho lớp trên qua interface. <i>Abstraction layer<\/i> cho phép thay phần dưới mà phần trên không đổi.","aka":["layers"]},{"t":"layout","vi":"Bố cục, cách sắp xếp. Trong bài: layout của HMI (vị trí các phần tử trên màn hình), <i>channel layout<\/i> của audio (số kênh, thứ tự kênh), layout của frame/message trên bus.","aka":["layouts"]},{"t":"lead","vi":"Dẫn dắt; người phụ trách. Trong bài: <i>lead architect<\/i>, <i>domain lead<\/i> (người dẫn dắt kỹ thuật một mảng), và <i>lead time<\/i> (thời gian từ lúc bắt đầu/đặt hàng đến khi xong/có hàng).","aka":["leads"]},{"t":"lead time","vi":"Thời gian chờ từ lúc yêu cầu đến lúc hoàn thành: với chip là thời gian đặt hàng đến khi giao; với quy trình là thời gian từ thay đổi đến khi release. Dùng làm metric cải tiến quy trình.","aka":["lead times"]},{"t":"learning","vi":"Việc học. Trong khóa: <i>Learning Plan<\/i> (kế hoạch học của từng unit) và <i>learning reflection<\/i> (phần tự suy ngẫm, ghi lại điều đã học và áp dụng vào dự án của bạn)."},{"t":"learning plan","vi":"Kế hoạch học của khóa: mô tả từng unit học gì, đầu ra (output) cần nộp và liên hệ với assignment. Workshop và reflection của bài làm theo khung Learning Plan."},{"t":"legacy","vi":"Di sản, hệ thống cũ còn đang dùng. Trong bài: ECU/phần mềm legacy được giữ lại khi chuyển sang kiến trúc mới; <i>workaround legacy<\/i> là nợ kỹ thuật; migration phải thay dần hệ legacy mà vẫn phát hành được."},{"t":"lesson","vi":"Bài học. Trong khóa: <i>Lesson 2<\/i> là khung workshop/reflection; trong xử lý sự cố, <i>lesson learned<\/i> là bài học rút ra sau incident để cập nhật quy trình, threat model, test.","aka":["lessons"]},{"t":"lesson learned","vi":"Bài học kinh nghiệm rút ra sau sự cố hoặc dự án: điều gì xảy ra, vì sao, và thay đổi gì (quy trình, test, design) để không lặp lại. Là bước cuối của incident response và RCA/CAPA.","aka":["lessons learned"]},{"t":"level","vi":"Mức, cấp độ. Trong bài: <i>log level<\/i> (mức chi tiết của log: error, warning, info, debug), SLA (Service Level Agreement – cam kết mức dịch vụ), ASIL (mức yêu cầu an toàn), mức áp dụng quy trình.","aka":["levels"]},{"t":"library","vi":"Thư viện phần mềm — code dùng chung do người khác viết (open source hoặc thương mại), ví dụ graphics library. Trong bài: library hết hỗ trợ hoặc có lỗ hổng là rủi ro dài hạn; mọi library phải nằm trong SBOM.","aka":["libraries"]},{"t":"license","vi":"Giấy phép sử dụng phần mềm. Trong bài: chi phí license (per unit – tính theo xe, per seat – theo kỹ sư), nghĩa vụ license của open source, và rủi ro phụ thuộc vendor khi dùng OS/stack thương mại.","aka":["licenses","licence","licensing"]},{"t":"lifecycle","vi":"Vòng đời: các giai đoạn từ khi sinh ra đến khi kết thúc. Trong bài: vòng đời sản phẩm/phần mềm xe (need → requirement → … → maintenance → end of life, kéo dài 10–15 năm), vòng đời key/certificate, lifecycle của service (khởi tạo, chạy, dừng).","aka":["lifecycles","life cycle"]},{"t":"lifecycle cost","vi":"Chi phí vòng đời: tổng chi phí suốt đời sản phẩm, không chỉ phát triển mà cả tích hợp, bảo trì, OTA, vá lỗ hổng, hỗ trợ nhiều năm sau SOP. Dùng để so phương án thay vì chỉ so giá ban đầu.","aka":["lifecycle costs"]},{"t":"likelihood","vi":"Khả năng xảy ra. Trong đánh giá rủi ro, risk = <b>likelihood × impact<\/b>; với security, likelihood gắn với attack feasibility (mức dễ thực hiện tấn công). Mỗi mục trong risk register cần ghi likelihood."},{"t":"limit","vi":"Giới hạn, ngưỡng. Trong bài: <i>rate limit<\/i> (giới hạn số message/lần gọi trong một khoảng thời gian, chống flood/DoS), giới hạn tài nguyên theo VM/container, và giới hạn hiệu lực của model/test.","aka":["limits"]},{"t":"LIN","vi":"Bus mạng chi phí thấp, chậm, dùng cho cảm biến/cơ cấu đơn giản trên xe (gương, cửa sổ, đèn trần), thường làm nhánh phụ của CAN. Cấu hình mô tả trong file LDF.","full":"Local Interconnect Network","cs":true},{"t":"link","vi":"Liên kết. Trong bài chủ yếu là <i>trace link<\/i>: liên kết có ID/version giữa requirement – design – code – test – evidence – release, để truy được impact và bằng chứng. Ngoài ra còn là đường kết nối mạng/bus.","aka":["links"]},{"t":"Linux","vi":"Hệ điều hành mã nguồn mở phổ biến, mạnh về driver, ecosystem và tùy biến. Trong CDC dùng cho infotainment, gateway, service (Android cũng chạy trên Linux kernel); không phải lựa chọn mặc định cho phần cần safety/hard real-time."},{"t":"load","vi":"Tải — mức sử dụng tài nguyên (CPU load 70%, bus load) hoặc khối lượng công việc. Trong bài: latency/jitter phải đo <b>dưới tải<\/b> thực tế; <i>cross-load test<\/i> cho phía non-critical quá tải để kiểm phía critical.","aka":["loads"]},{"t":"local","vi":"Cục bộ, tại chỗ. Trong bài: chức năng chạy <i>local<\/i> trên xe (không phụ thuộc mạng), <i>local behavior/fallback<\/i> khi mất kết nối, và quyết định local (trong phạm vi một team, dễ đảo ngược)."},{"t":"lock","vi":"Khóa. Trong phần mềm: <i>lock<\/i> (mutex) bảo vệ dữ liệu dùng chung — vCPU bị dừng khi đang giữ lock gây trễ dây chuyền. Trong kinh doanh: <i>lock-in<\/i> là bị phụ thuộc vào một vendor/tool.","aka":["locks"]},{"t":"lock-in","vi":"Bị \"khóa\" vào một nhà cung cấp/tool/định dạng: muốn đổi thì rất tốn kém. Trong bài, vendor lock-in là rủi ro vừa về chi phí vừa về khả năng chống chịu; giảm bằng interface chuẩn, abstraction layer, điều khoản hợp đồng.","aka":["vendor lock-in"]},{"t":"log","vi":"Nhật ký: bản ghi sự kiện có timestamp do phần mềm ghi lại. Trong bài, log là evidence và là nguồn chính để điều tra lỗi; cần level, timestamp đồng bộ giữa OS/partition, correlation ID, và policy về retention/privacy.","aka":["logs"]},{"t":"logging","vi":"Việc ghi log. Trong bài là một platform service: logging/tracing phải thống nhất giữa các OS/VM, có giới hạn dung lượng (tránh hết storage, mòn flash) và tôn trọng privacy (không ghi dữ liệu cá nhân thừa)."},{"t":"logic","vi":"Logic, phần quy tắc xử lý của chương trình (khi nào làm gì). Trong bài: <i>logic<\/i> chọn/phát cảnh báo nằm ở central compute; thay đổi logic liên quan safety cần review và test chặt hơn đổi giao diện."},{"t":"long-term","vi":"Dài hạn. Trong bài: <i>long-term maintenance<\/i> (bảo trì dài hạn, xe sống 10–15 năm), <i>long-term support<\/i> (cam kết hỗ trợ dài hạn của OS/kernel/BSP).","aka":["long term"]},{"t":"long-term maintenance","vi":"Bảo trì dài hạn: giữ phần mềm xe an toàn và chạy được trong suốt đời xe — theo dõi lỗ hổng, vá qua OTA, giữ toolchain/build tái tạo được, quản lý chứng chỉ, kể cả khi supplier đổi hay ngừng hỗ trợ."},{"t":"long-term support","vi":"Hỗ trợ dài hạn (LTS): cam kết của nhà cung cấp OS/kernel/BSP tiếp tục phát hành bản vá trong nhiều năm. Khi chọn SoC/OS phải xem ngày hết LTS so với vòng đời xe.","aka":["LTS","long term support"]},{"t":"loop","vi":"Vòng lặp. Trong bài: <i>feedback loop<\/i> (vòng phản hồi: đo metric rồi cải tiến), <i>HIL/SIL – Hardware/Software-in-the-Loop<\/i> (phần cứng/phần mềm nằm trong vòng mô phỏng).","aka":["loops"]},{"t":"loss","vi":"Sự mất. Trong bài: <i>data loss<\/i> (mất dữ liệu chấp nhận được khi lỗi), <i>power loss<\/i> (mất điện đột ngột khi đang ghi), <i>network loss<\/i> (mất mạng) — các tình huống bắt buộc phải test.","aka":["losses"]},{"t":"m/s","vi":"Mét trên giây — đơn vị tốc độ (1 m/s = 3,6 km/h). Trong bài là ví dụ lỗi contract: một team hiểu tín hiệu speed là km/h, team kia hiểu là m/s, dẫn tới hiển thị sai."},{"t":"machine","vi":"Máy. Trong bài: <i>virtual machine<\/i> (VM – máy ảo do hypervisor tạo), <i>state machine<\/i> (máy trạng thái: mô hình các trạng thái và chuyển trạng thái của phần mềm), human-machine interface (HMI).","aka":["machines"]},{"t":"maintainability","vi":"Tính dễ bảo trì: mức dễ sửa lỗi, thay đổi, cập nhật phần mềm về sau. Là một quality attribute/NFR; trong bài cần định lượng được và cân bằng với performance, cost, safety."},{"t":"maintenance","vi":"Bảo trì: sửa lỗi, vá bảo mật, cập nhật sau khi phát hành. Với xe, giai đoạn maintenance kéo dài nhiều năm sau SOP (OTA, vulnerability monitoring), nên chi phí maintenance phải tính ngay từ quyết định kiến trúc."},{"t":"major","vi":"Lớn, chính. Trong bài: <i>major version<\/i> — tăng khi thay đổi không tương thích (ví dụ đổi đơn vị), khác <i>minor<\/i> (thêm field tương thích); <i>finding mức major<\/i> trong review là lỗi nghiêm trọng phải đóng trước gate."},{"t":"management","vi":"Quản lý. Trong bài: configuration management, change/defect management, variant management, key management, resource management (phân chia CPU/memory), Execution Management (AUTOSAR)."},{"t":"manager","vi":"Người quản lý. Trong bài: <i>project manager<\/i> (PM – phạm vi, lịch, nguồn lực), <i>release manager<\/i> (quản lý gate, approval, cohort phát hành), <i>safety manager<\/i> (người chịu trách nhiệm an toàn chức năng).","aka":["managers"]},{"t":"manifest","vi":"Bản kê khai: file liệt kê thành phần và thuộc tính. Trong bài: <i>version manifest<\/i> (version của mọi thành phần trong image), <i>OTA/release manifest<\/i> (mô tả bản update, điều kiện cài) — giúp kiểm tra tương thích trước khi cài.","aka":["manifests"]},{"t":"map","vi":"Bản đồ; ánh xạ. Trong bài: <i>ownership map<\/i>, <i>value-chain map<\/i>, <i>dependency map<\/i> (sơ đồ ai sở hữu/phụ thuộc gì); động từ <i>map<\/i> = ánh xạ, gắn A với B (map requirement sang evidence); và bản đồ dẫn đường trên IVI.","aka":["maps"]},{"t":"mapping","vi":"Ánh xạ, sự gắn tương ứng giữa hai thứ: VSS signal ↔ nguồn tín hiệu thật, workload ↔ OS/VM, tọa độ touch ↔ màn hình, clock giữa các OS. Mapping sai là nguồn lỗi tích hợp phổ biến.","aka":["mappings"]},{"t":"margin","vi":"Biên, phần dư. Trong kỹ thuật: <i>margin<\/i> là phần dự phòng giữ lại trong budget (CPU, memory, timing) để chịu biến động. Trong tài chính: <i>gross margin<\/i> = lợi nhuận gộp / doanh thu.","aka":["margins"]},{"t":"materials","vi":"Vật liệu, linh kiện. Gặp trong <i>BOM – Bill of Materials<\/i> (danh sách và giá linh kiện trên mỗi xe) và <i>SBOM – Software Bill of Materials<\/i> (danh sách mọi thành phần phần mềm trong một bản build)."},{"t":"matrix","vi":"Ma trận, bảng hai chiều. Trong bài: traceability matrix, compatibility matrix (tổ hợp version tương thích), ownership matrix (ai sở hữu phần nào), comparison matrix (so phương án), test/variant matrix.","aka":["matrices"]},{"t":"max","vi":"Viết tắt của maximum — giá trị lớn nhất. Trong bài: <i>max age<\/i> (dữ liệu cũ tối đa bao lâu còn dùng được), <i>max latency<\/i>: số max/P95 phơi ra phần đuôi mà trung bình che mất."},{"t":"MCU","vi":"Vi điều khiển: chip nhỏ gồm CPU, bộ nhớ và ngoại vi, khởi động nhanh, chạy phần mềm real-time/safety. Trong CDC, MCU thường lo phần cần tin cậy (telltale, cảnh báo, quản lý nguồn) bên cạnh SoC lớn.","full":"Microcontroller Unit","cs":true},{"t":"measurement","vi":"Phép đo, việc đo lường. Trong bài, quyết định kiến trúc phải dựa trên <i>measurement<\/i> trên target có thể bác bỏ phương án (falsifiable), và \"measurement\" cũng là một nhóm nguyên nhân lỗi (đo sai).","aka":["measurements"]},{"t":"media","vi":"Phương tiện/nội dung đa phương tiện: nhạc, video, radio, podcast. Trong CDC, media là chức năng của IVI; trình phát media hay là điểm bị tấn công nên phải chạy với quyền thấp, trong sandbox."},{"t":"memory","vi":"Bộ nhớ (RAM, flash). Trong bài: memory là tài nguyên dùng chung phải chia và cách ly giữa VM/process (stage-2 page table, IOMMU); <i>memory bandwidth<\/i>, <i>memory leak<\/i>, OOM là nguồn gây trễ và lỗi."},{"t":"memory leak","vi":"Rò rỉ bộ nhớ: chương trình cấp phát memory mà không trả lại, dùng lâu thì hết RAM và bị OS kill/treo. Trên xe chạy liên tục nhiều giờ, lỗi này thường chỉ lộ khi test dài.","aka":["memory leaks"]},{"t":"memory ordering","vi":"Thứ tự ghi/đọc bộ nhớ được bảo đảm giữa các core/VM. Khi dùng shared memory, nếu không có barrier/đồng bộ đúng, bên đọc có thể thấy dữ liệu nửa cũ nửa mới."},{"t":"mentor","vi":"Người hướng dẫn, kèm cặp. Trong khóa học, mentor là người review bài làm và trả lời các câu hỏi còn mở bạn ghi lại cuối mỗi unit.","aka":["mentors"]},{"t":"merge","vi":"Gộp — đưa thay đổi code từ nhánh làm việc vào nhánh chính. Trong bài: code review diễn ra trước khi merge; CI build và test tự động mỗi khi merge; \"fix đã merge\" chưa có nghĩa là lỗi đã được chứng minh đã sửa.","aka":["merged","merges"]},{"t":"message","vi":"Thông điệp — gói dữ liệu gửi qua bus/mạng/IPC giữa các thành phần. Trong bài: message cần thứ tự (ordering), sequence number, kiểm tra hợp lệ; gửi dồn dập message là kiểu tấn công DoS.","aka":["messages"]},{"t":"metric","vi":"Chỉ số đo lường định lượng (latency P95, tỷ lệ lỗi, crash rate…). Trong bài: requirement/quality scenario phải có metric + threshold; <i>health metric<\/i> dùng để quyết định tiếp tục hay dừng rollout OTA.","aka":["metrics"]},{"t":"microcontroller","vi":"Vi điều khiển (MCU) — chip nhỏ tích hợp CPU, bộ nhớ, ngoại vi; khởi động nhanh, phù hợp tác vụ real-time/safety. Trong AUTOSAR có <i>Microcontroller Abstraction Layer<\/i> (MCAL) là lớp driver sát chip.","aka":["microcontrollers"]},{"t":"middleware","vi":"Phần mềm trung gian nằm giữa OS và ứng dụng, lo chuyển message, tìm dịch vụ (discovery), đóng gói dữ liệu — ví dụ SOME/IP, DDS, Binder. Trong bài, middleware là nền của SOA trên xe và phải có QoS, contract, observability."},{"t":"migration","vi":"Sự chuyển đổi/di chuyển từ hệ/cấu trúc cũ sang mới: kiến trúc E/E, platform, schema dữ liệu trên xe. Trong bài cần <i>migration path/strategy<\/i> rõ (thay dần, chạy song song, rollback) — đổi sau thường rất đắt.","aka":["migrations"]},{"t":"migration strategy","vi":"Chiến lược/lộ trình chuyển đổi: thay dần (strangler), chạy song song (parallel run), hay big-bang; kèm thời điểm, rủi ro, cách rollback. Là một đầu ra quan trọng của SA khi đổi kiến trúc.","aka":["migration plan"]},{"t":"minimization","vi":"Sự tối thiểu hóa. Trong bài là <i>data minimization<\/i>: chỉ thu thập, lưu và gửi dữ liệu thật sự cần thiết (nhất là dữ liệu cá nhân như vị trí, VIN) — nguyên tắc privacy và giảm rủi ro rò rỉ."},{"t":"mismatch","vi":"Sự không khớp. Trong bài: <i>schema mismatch<\/i> (hai bên hiểu cấu trúc dữ liệu khác nhau), board/driver mismatch, version mismatch — loại lỗi tích hợp điển hình, phát hiện bằng contract test.","aka":["mismatches"]},{"t":"miss","vi":"Lỡ, trượt. Trong bài: <i>deadline miss<\/i> (tác vụ không xong kịp hạn), <i>miss vblank<\/i> (lỡ nhịp làm tươi màn hình gây frame drop). Watchdog/health monitor phải phát hiện deadline miss.","aka":["misses","missed"]},{"t":"mitigation","vi":"Biện pháp giảm nhẹ rủi ro: làm giảm likelihood hoặc impact. Trong bài, mỗi risk trong risk register cần mitigation cụ thể, có owner và hạn; phần rủi ro còn lại sau mitigation là residual risk.","aka":["mitigations"]},{"t":"mixed","vi":"Hỗn hợp, trộn lẫn. Trong bài chủ yếu gặp trong <i>mixed criticality<\/i>: chạy chung trên một SoC các phần mềm có mức quan trọng (safety) khác nhau."},{"t":"mode","vi":"Chế độ hoạt động. Trong bài: <i>degraded mode<\/i> (chế độ suy giảm có kiểm soát khi lỗi), <i>fallback mode<\/i>, <i>power mode<\/i> (off/standby/running), <i>failure mode<\/i> (kiểu hỏng) trong phân tích lỗi.","aka":["modes"]},{"t":"model","vi":"Mô hình. Trong bài: <i>threat model<\/i>, <i>data model<\/i> (VSS), <i>V-Model<\/i> (mô hình phát triển), model trong MBSE/mô phỏng, model AI; và <i>model year<\/i> — đời xe theo năm.","aka":["models"]},{"t":"model year","vi":"Đời xe theo năm (MY): phiên bản xe bán ra trong một năm, thường có thay đổi nhỏ. Mỗi model year/facelift có thể thêm variant, làm tăng test matrix và chi phí bảo trì phần mềm."},{"t":"module","vi":"Mô-đun: một khối code/phần cứng tương đối độc lập, có ranh giới rõ. Trong bài: module phần mềm trong chuỗi truy vết; HSM (Hardware Security Module); vấn đề lặp ở nhiều module cho thấy lỗi nằm ở cấu trúc.","aka":["modules"]},{"t":"monitoring","vi":"Giám sát liên tục khi hệ thống đang chạy. Trong bài: <i>vulnerability monitoring<\/i> (theo dõi lỗ hổng mới), <i>health monitor<\/i> (phát hiện task treo), monitoring fleet sau OTA để quyết định tiếp tục hay dừng rollout.","aka":["monitor","monitors"]},{"t":"ms","vi":"Mili giây = 1/1000 giây — đơn vị đo latency, chu kỳ và deadline trong bài (ví dụ \"P95 latency dưới 100 ms\", tín hiệu cập nhật mỗi 20 ms).","full":"millisecond","cs":true},{"t":"native","vi":"Gốc, nguyên bản. Trong bài: chạy <i>native<\/i> (thẳng trên phần cứng/OS, không qua lớp ảo hóa), <i>near-native performance<\/i> của passthrough, và <i>cloud-native<\/i> (thiết kế theo kiểu container/orchestration của cloud)."},{"t":"navigation","vi":"Điều hướng/dẫn đường — app bản đồ chỉ đường trên IVI. Trong bài là ví dụ workload IVI nặng (render bản đồ) có thể ảnh hưởng cluster, và về chính sách ai được đặt popup lên display nào."},{"t":"need","vi":"Nhu cầu. Trong lifecycle, <i>Need<\/i> là chặng đầu: nhu cầu của người dùng/stakeholder trước khi được viết thành requirement đo được (stakeholder need → requirement → design…).","aka":["needs"]},{"t":"net","vi":"Ròng (sau khi đã trừ). Trong bài: <i>NPV – Net Present Value<\/i> (giá trị hiện tại ròng), <i>net benefit<\/i> (lợi ích thực sau khi trừ chi phí kiểm tra, sửa lại)."},{"t":"net benefit","vi":"Lợi ích ròng: phần lợi còn lại sau khi trừ chi phí phát sinh. Trong bài, khi đánh giá AI/tool, net benefit = thời gian tiết kiệm − thời gian review, kiểm tra và sửa lại."},{"t":"network","vi":"Mạng. Trong bài: mạng trong xe (CAN, LIN, Ethernet), kết nối cloud (cellular), <i>network segmentation<\/i> (chia mạng để lỗi/tấn công không lan); network là tài nguyên dùng chung cần chia băng thông và cách ly.","aka":["networks"]},{"t":"node","vi":"Nút: một thiết bị/ECU/điểm trong mạng hoặc sơ đồ. Trong bài: một node là một controller (ví dụ cockpit domain controller), các node nối daisy-chain trên audio bus, node chờ dependency khi startup.","aka":["nodes"]},{"t":"note","vi":"Ghi chú. Trong bài: <i>release note<\/i> (ghi chú phát hành: bản này thay đổi gì, lỗi đã biết), <i>design note<\/i>, ghi chú hướng dẫn — tài liệu mà khi được dựa vào để vận hành thì phải được kiểm soát (controlled).","aka":["notes"]},{"t":"number","vi":"Số. Trong bài: <i>sequence number<\/i> (số thứ tự tăng dần của message để phát hiện mất/lặp/đảo thứ tự), VIN (Vehicle Identification Number – số định danh xe).","aka":["numbers"]},{"t":"observability","vi":"Khả năng quan sát hệ thống đang chạy qua log, metric, trace, diagnostic. Trong bài, observability phải được thiết kế từ đầu (trace point, timestamp đồng bộ, correlation ID) để điều tra lỗi xuyên nhiều lớp/owner."},{"t":"OEM","vi":"Hãng xe — doanh nghiệp thiết kế, sở hữu thương hiệu và bán xe (Toyota, VinFast…), mua hệ thống từ Tier 1/Tier 2. Trong bài, OEM chịu trách nhiệm cuối với xe, quyết định kiến trúc, OTA và chấp nhận rủi ro.","aka":["OEMs"],"full":"Original Equipment Manufacturer","cs":true},{"t":"off","vi":"Tắt. Trong bài: trạng thái nguồn <i>off<\/i> (cùng standby, accessory, running), và thí nghiệm so sánh <i>video off/on<\/i> để xem một yếu tố có gây trễ hay không (thay đổi một yếu tố mỗi lần)."},{"t":"offline","vi":"Ngoại tuyến, không có kết nối mạng. Trong bài: chức năng trên xe phải chạy được khi offline; xe offline không gửi telemetry phải tính là \"chưa xác định\" chứ không phải \"không lỗi\"; <i>offline queue<\/i> phải có giới hạn."},{"t":"OJT","vi":"Đào tạo tại chỗ làm: học bằng cách làm việc thật trong dự án, có người hướng dẫn. Trong khóa, mỗi bài đọc phục vụ Assignment và OJT — áp dụng kiến thức vào bối cảnh dự án bạn đã chọn.","full":"On-the-Job Training","cs":true},{"t":"online","vi":"Trực tuyến, đang có kết nối mạng. Trong bài: tỷ lệ lỗi tính trên số xe đang online có thể đánh giá thấp vấn đề; xe sẽ nhận OTA khi online trở lại."},{"t":"open","vi":"Mở. Trong bài: <i>open source<\/i> (mã nguồn mở), câu hỏi còn mở (open question), finding/issue còn mở (chưa đóng), và các chuẩn mở/cửa mở giữa các guest (IPC)."},{"t":"open source","vi":"Mã nguồn mở (OSS): phần mềm công khai mã nguồn, dùng theo license (Linux, thư viện…). Trong bài, open source được coi như một \"supplied part\": phải có trong SBOM, theo dõi lỗ hổng và tuân thủ nghĩa vụ license.","aka":["open-source"]},{"t":"operating","vi":"Vận hành, hoạt động. Trong bài: <i>operating system<\/i> (hệ điều hành – OS), <i>operating cost<\/i> (chi phí vận hành/duy trì năng lực, không phụ thuộc số xe)."},{"t":"operating system","vi":"Hệ điều hành (OS): phần mềm nền quản lý CPU, bộ nhớ, thiết bị và chạy ứng dụng (Linux, Android, QNX, RTOS). Trên CDC thường có nhiều OS chạy song song trên hypervisor.","aka":["operating systems"]},{"t":"operation","vi":"Vận hành, hoạt động; một thao tác. Trong lifecycle, <i>Operation<\/i> là giai đoạn xe đang được dùng ngoài thực tế; <i>operations<\/i> là bộ phận/hoạt động vận hành (SOC, fleet); trong interface, operation là một hàm/phương thức được gọi.","aka":["operations"]},{"t":"option","vi":"Phương án, lựa chọn. Trong bài: so sánh các Option A/B/C bằng tiêu chí và evidence trước khi quyết; cũng là <i>option<\/i> trang bị (tùy chọn khi mua xe) tạo ra variant.","aka":["options"]},{"t":"oracle","vi":"Trong kiểm thử, <i>test oracle<\/i> là tiêu chí/cách biết kết quả đúng là gì (giá trị mong đợi, quy tắc, ngưỡng). Không có oracle thì test không cho ra pass/fail thật sự.","aka":["oracles","test oracle"]},{"t":"order","vi":"Thứ tự. Trong bài: <i>boot order<\/i> (thứ tự khởi động), <i>shedding order<\/i> (thứ tự cắt bớt việc khi quá tải), <i>z-order<\/i> (lớp nào nằm trên khi ghép hình).","aka":["orders"]},{"t":"ordering","vi":"Bảo đảm thứ tự. Trong bài: thứ tự message trong pub/sub (đến sai thứ tự thì xử lý sao), và <i>memory ordering<\/i> — thứ tự ghi/đọc bộ nhớ được bảo đảm giữa các core khi dùng shared memory."},{"t":"OS","vi":"Hệ điều hành: phần mềm nền quản lý tài nguyên và chạy ứng dụng. Trên CDC thường có nhiều OS — RTOS/QNX cho cluster, Android Automotive/Linux cho IVI — chạy trên hypervisor; chọn OS ảnh hưởng safety, license và bảo trì dài hạn.","aka":["OSes","OSs"],"full":"Operating System","cs":true},{"t":"OS/hypervisor","vi":"Cụm chỉ chung lớp hệ điều hành và hypervisor — phần nền quản lý CPU, memory, interrupt, device. Trong bài: không để mặc định của OS/hypervisor quyết định chia tài nguyên; chọn OS/hypervisor thương mại hay mã nguồn mở là quyết định kiến trúc lớn."},{"t":"OS/VM","vi":"Chỉ chung hệ điều hành hoặc máy ảo đang chạy một workload. Trong bài: ánh xạ workload vào OS/VM nào, nhiều OS/VM dùng chung một GPU, ranh giới giữa các process/OS/VM.","cs":true},{"t":"OTA","vi":"Cập nhật phần mềm cho xe qua mạng không dây, không cần mang xe vào xưởng. Trong CDC, OTA cho phép vá lỗi và thêm tính năng sau khi bán xe, nhưng đòi hỏi ký số, kiểm tra tương thích, staged rollout và đường rollback.","aka":["OTA update","OTA updates"],"full":"Over-The-Air","cs":true},{"t":"OTA campaign","vi":"Một đợt phát hành OTA tới một nhóm xe xác định (cohort), có kế hoạch theo từng giai đoạn, health metric và điều kiện pause/rollback. Khi phát hiện lỗi, việc đầu tiên thường là pause campaign và khoanh cohort đã nhận.","aka":["OTA campaigns"],"cs":true},{"t":"over-the-air","vi":"Tên đầy đủ của OTA — \"qua không trung\": cập nhật phần mềm qua mạng không dây (cellular/Wi-Fi) thay vì nạp tại xưởng. Là cửa để sửa lỗi sau bán nhưng cũng là kênh tấn công mạnh nếu không bảo vệ."},{"t":"outcome","vi":"Kết quả, hệ quả cuối cùng. Trong bài: <i>outcome<\/i> của gate (release / conditional / hold), <i>user outcome<\/i> (giá trị người dùng nhận được), product owner chịu trách nhiệm outcome sản phẩm.","aka":["outcomes"]},{"t":"output","vi":"Đầu ra — kết quả do một hàm, hoạt động hay unit tạo ra. Trong bài: mỗi giai đoạn lifecycle có output (artifact) rõ; đầu ra của mỗi Unit là sản phẩm bạn nộp; so sánh output khi chạy song song hệ cũ/mới.","aka":["outputs"]},{"t":"overhead","vi":"Chi phí phụ: phần tài nguyên/thời gian tiêu tốn thêm không làm ra việc chính. Trong bài: <i>virtualization overhead<\/i> do hypervisor thêm vào; phải đo trên target dưới tải chứ không tin \"vendor nói overhead thấp\"."},{"t":"overload","vi":"Quá tải: yêu cầu vượt khả năng xử lý (CPU, bus, queue). Câu hỏi bắt buộc cho hệ mixed criticality: guest không critical overload thì guest critical có giữ được deadline không? Cần đo bằng test quá tải.","aka":["overloaded","overloads"]},{"t":"req_id","vi":"Tên trường dữ liệu (field) chứa <b>mã định danh requirement<\/b> trong metadata của tool/pipeline. Trong bài là ví dụ: đổi tên req_id thành requirement_id mà không versioning schema làm pipeline của mọi team đứt link truy vết.","aka":["requirement_id"]},{"t":"source_id","vi":"Trường dữ liệu chứa <b>mã định danh nguồn<\/b> tạo ra mẫu dữ liệu (cảm biến/ECU/service nào). Trong SpeedSample, source_id trả lời câu hỏi \"dữ liệu này từ đâu ra\", giúp truy vết và chọn nguồn khi có nhiều nguồn tốc độ."},{"t":"owner","vi":"Người/nhóm <b>chịu trách nhiệm chính<\/b> về một thành phần, interface, quyết định hay rủi ro: có quyền quyết định và phải duy trì, sửa lỗi. Trong bài: mỗi interface, evidence, risk đều phải có owner đích danh, không phải “cả team”.","aka":["owners"]},{"t":"ownership","vi":"Quyền sở hữu và trách nhiệm: <i>ai<\/i> làm, ai quyết định, ai duy trì một phần của hệ thống. Trong CDC/SDV nhiều bên (OEM, Tier 1, vendor) cùng góp code, nên ownership phải được ghi rõ cho từng interface, dữ liệu và chặng — lỗi thường nằm ở chỗ không ai sở hữu."},{"t":"p99/max","vi":"Phân vị 99 và giá trị lớn nhất của một phép đo (thường là latency): 99% mẫu nhỏ hơn P99, max là lần tệ nhất. Trong bài dùng để chứng minh deadline thay cho số trung bình, vì lỗi timing nằm ở “phần đuôi” (tail) chứ không ở average."},{"t":"package","vi":"Gói: một tập hợp được đóng lại để giao/nhận. Trong bài có nhiều nghĩa: gói phần mềm (package trong SBOM, có tên + version), <i>Board Support Package<\/i> (gói driver cho board), và <i>evidence package<\/i> — bộ bằng chứng nộp kèm khi release.","aka":["packages"]},{"t":"parser","vi":"Bộ phân tích cú pháp: đoạn code đọc dữ liệu thô (frame CAN, byte, message) và chuyển thành giá trị có nghĩa (tốc độ, đơn vị, cờ). Trong bài, “sửa parser” là ví dụ thay đổi nhìn nhỏ nhưng lan sang nhiều target, test và evidence.","aka":["parsers","parse","parsing"]},{"t":"part","vi":"Phần, bộ phận. Trong bài: <i>spare part<\/i> (phụ tùng thay thế ở after-sales) và <i>supplied part<\/i> — phần do bên ngoài cung cấp; open source cũng được xem là một supplied part, nên phải được quản lý như phần mua của supplier.","aka":["parts"]},{"t":"partition","vi":"Phân vùng: chia tài nguyên (CPU, RAM, thiết bị) hoặc chức năng thành các vùng tách biệt. Trong CDC, hypervisor chia SoC thành nhiều partition (ví dụ QNX cho cluster, Android cho IVI) để lỗi vùng này không lan sang vùng kia; cũng dùng trong “A/B partition” cho OTA.","aka":["partitions","partitioning","partitioned"]},{"t":"pass","vi":"Đạt/qua: kết quả test, review hoặc audit thỏa tiêu chí. Trong bài nhấn mạnh “test pass” chỉ có giá trị khi gắn với đúng build, variant và ngưỡng đo; pass ở bench không chứng minh được hành vi trên xe dưới tải thật.","aka":["passed","passes"]},{"t":"pass/fail","vi":"Đạt/không đạt: kết quả nhị phân của một phép test hay kiểm tra. Trong bài, mỗi requirement cần <b>ngưỡng pass/fail<\/b> đo được (ví dụ P99 latency ≤ deadline) đặt trước khi chạy test, nếu không thì không thể kết luận."},{"t":"patch","vi":"Bản vá: thay đổi nhỏ để sửa lỗi hoặc lỗ hổng bảo mật trong phần mềm đã phát hành. Trong CDC/SDV, patch thường được giao qua OTA và vẫn phải đi qua change control, regression test và evidence như một release thật.","aka":["patches","patched","patching"]},{"t":"path","vi":"Đường đi: tuyến mà dữ liệu, lệnh hay quy trình đi qua. Trong bài có nhiều dạng: code path (nhánh code thực sự chạy), safety/security path (luồng thay đổi chạm an toàn/bảo mật), migration path (lộ trình chuyển đổi), data/control path trong audio.","aka":["paths"]},{"t":"pattern","vi":"Mẫu thiết kế: cách giải quyết đã được đặt tên cho một loại bài toán lặp lại. Trong bài: pattern giao tiếp (request/response, pub/sub), embedded pattern (ring buffer, double buffer) — chọn pattern theo yêu cầu timing, trạng thái và hàng đợi.","aka":["patterns"]},{"t":"pause","vi":"Tạm dừng. Trong OTA, <b>pause rollout<\/b> là dừng phát hành sang thêm xe mới khi health metric xấu đi, để giới hạn số xe bị ảnh hưởng trong lúc điều tra — khác với rollback (đưa xe về bản cũ).","aka":["paused","pausing"]},{"t":"performance","vi":"Hiệu năng: hệ thống chạy nhanh, mượt và dùng tài nguyên hiệu quả đến mức nào (latency, throughput, frame rate…). Trong bài là một tiêu chí chọn kiến trúc, thường phải đánh đổi với isolation, safety hoặc chi phí; được giới hạn bằng performance budget."},{"t":"period","vi":"Chu kỳ: khoảng thời gian lặp lại đều đặn. Trong bài: chu kỳ gửi/lấy mẫu tín hiệu (sampling period), chu kỳ chạy của task real-time, hay vCPU budget/period — được chạy bao nhiêu ms trong mỗi chu kỳ.","aka":["periods","periodic"]},{"t":"permission","vi":"Quyền hạn: ai/app nào được đọc, ghi hay gọi một chức năng/dữ liệu. Trong CDC, permission được kiểm tại service hoặc OS (ví dụ app IVI chỉ đọc vị trí khi người dùng cấp quyền) và là một phần của interface contract.","aka":["permissions"]},{"t":"persistence","vi":"Tính lưu bền: dữ liệu được ghi lại để còn sau khi tắt máy/reboot. Trong bài, persistence đi kèm câu hỏi schema, migration và rollback: bản mới đã ghi dữ liệu theo định dạng mới thì bản cũ có còn đọc được không."},{"t":"persistent","vi":"Lưu bền, tồn tại lâu dài (qua reboot, qua update). Trong bài hay đi với <i>persistent data<\/i> — dữ liệu lưu trên xe như cấu hình, lịch sử, cache — thứ khiến rollback khó vì binary cũ có thể không hiểu dữ liệu đã migrate."},{"t":"phase","vi":"Giai đoạn/pha. Trong quy trình: một bước của lifecycle hay một đợt migration (wave/phase). Trong audio (C.3) còn có nghĩa vật lý: pha tín hiệu — loa bị ngược phase sẽ làm triệt tiêu âm trầm.","aka":["phases"]},{"t":"phased","vi":"Theo từng giai đoạn. <i>Phased/incremental migration<\/i> là chuyển đổi dần theo feature, variant hoặc dòng xe thay vì “big bang” một lần — giảm rủi ro nhưng phải sống chung hệ cũ và mới một thời gian."},{"t":"pilot","vi":"Thí điểm: chạy thử trên phạm vi nhỏ trước khi mở rộng. Trong OTA, pilot là đợt phát hành cho nhóm xe nhỏ (sau internal, trước cohort lớn); trong migration là chuyển thử một phần ít rủi ro để kiểm cách làm.","aka":["pilots"]},{"t":"pipeline","vi":"Đường ống: chuỗi bước tự động nối tiếp nhau. Trong bài chủ yếu là CI/CD pipeline (build → test → scan → ký → release) có gate kiểm soát; ngoài ra còn data pipeline và pipeline xử lý đồ họa/âm thanh.","aka":["pipelines"]},{"t":"pixel","vi":"Điểm ảnh: phần tử nhỏ nhất trên màn hình. Trong bài, “đến lúc pixel đổi/sáng” là điểm cuối của chuỗi đo latency hiển thị: từ lúc tín hiệu đến xe cho tới khi người lái thật sự thấy giá trị trên panel.","aka":["pixels"]},{"t":"plan","vi":"Kế hoạch. Trong bài là tài liệu nói trước sẽ làm gì và chứng minh thế nào: test plan, evidence plan, rollback plan, retirement plan… Một plan tốt có owner, tiêu chí và điều kiện dừng/quay lui.","aka":["plans","planning"]},{"t":"platform","vi":"Nền tảng: phần hạ tầng dùng chung (compute, OS, middleware, update, diagnostic, CI/CD…) mà nhiều feature hoặc dòng xe xây lên trên. Trong SDV, shared platform giúp reuse nhưng làm tăng blast radius và cần ownership rõ.","aka":["platforms"]},{"t":"plausibility","vi":"Tính hợp lý: giá trị có nằm trong khoảng và quy luật có thể xảy ra không (ví dụ tốc độ không nhảy 0 → 200 km/h trong 10 ms). Plausibility check là cơ chế an toàn để phát hiện dữ liệu sai trước khi dùng."},{"t":"PM","vi":"Viết tắt của <i>Project Manager<\/i> – quản lý dự án: lo phạm vi, lịch, nguồn lực, phối hợp. Trong bài, PM là người hỏi “mất mấy ngày?”, “chốt được không?” — SA phải trả lời bằng ước lượng có giả định và rủi ro.","full":"Project Manager","cs":true},{"t":"point","vi":"Điểm. Trong bài xuất hiện ở: <i>entry point<\/i> (cửa dữ liệu đi vào hệ thống, dùng trong threat model), <i>sensitivity/trade-off point<\/i> (điểm nhạy/điểm đánh đổi trong ATAM), <i>three-point estimate<\/i> (ước lượng ba điểm).","aka":["points"]},{"t":"policy","vi":"Chính sách/luật vận hành được viết ra để hệ thống hoặc tổ chức làm theo. Trong bài: compatibility policy, drop/expiry policy của queue, scheduling policy, OTA policy, audio policy… — quyết định trước “khi xảy ra X thì làm gì”.","aka":["policies"]},{"t":"population","vi":"Quần thể: tập hợp đối tượng đang xét. Trong bài là <i>affected population<\/i> — nhóm xe bị ảnh hưởng (theo build, variant, đợt OTA); cần SBOM và provenance để khoanh đúng population khi có lỗi hay lỗ hổng."},{"t":"port","vi":"Có hai nghĩa: (1) động từ — chuyển phần mềm sang chạy trên phần cứng/OS khác (supplier port sang chip mới); (2) danh từ — cổng kết nối vật lý/logic như USB, debug port, một cửa tấn công cần khóa sau sản xuất.","aka":["ports","porting","ported"]},{"t":"power","vi":"Điện năng/nguồn điện. Trong bài là một ràng buộc kiến trúc cùng với thermal: tiêu thụ điện của SoC, power mode (ngủ/thức/tắt) và sự cố power loss (mất nguồn đột ngột khi đang ghi dữ liệu hay đang cài OTA)."},{"t":"practical","vi":"Thực tế, áp dụng được. Mục “Practical application” cuối mỗi bài là phần áp dụng kiến thức vào feature/dự án thật của người học."},{"t":"prediction","vi":"Dự đoán. Trong RCA và debug, mỗi giả thuyết (hypothesis) phải kèm prediction viết ra <b>trước<\/b> khi đo: “nếu giả thuyết đúng thì phép đo X sẽ cho kết quả Y” — để có thể bác bỏ thay vì chỉ xác nhận điều mình tin.","aka":["predictions"]},{"t":"preempt","vi":"Chiếm quyền chạy: bộ lập lịch ngắt một tác vụ đang chạy để nhường CPU/GPU cho tác vụ ưu tiên cao hơn. Trong bài, thread hoặc vCPU bị preempt (nhất là khi đang giữ lock) là nguồn gây trễ khó thấy.","aka":["preempted","preemption","preemptive"]},{"t":"priority","vi":"Mức ưu tiên: thứ tự được phục vụ khi tranh chấp tài nguyên (CPU, GPU, mạng, audio) hoặc thứ tự xử lý requirement/defect. Trong bài, priority cấu hình sai có thể làm cảnh báo an toàn bị trễ dù OS vẫn tốt.","aka":["priorities","prioritize","prioritization"]},{"t":"privacy","vi":"Quyền riêng tư: bảo vệ dữ liệu cá nhân (vị trí, danh bạ, giọng nói, hồ sơ người dùng). Trong xe kết nối, privacy đòi hỏi thu thập tối thiểu, có đồng ý, giới hạn retention và sanitize log trước khi gửi đi."},{"t":"problem","vi":"Vấn đề/bài toán. Trong bài hay đi với <i>problem framing<\/i> — phát biểu rõ vấn đề: quyết định gì, ràng buộc gì, ai là owner, hạn khi nào — bước đầu của mọi ADR hay báo cáo sự cố.","aka":["problems"]},{"t":"process","vi":"Có hai nghĩa: (1) quy trình làm việc (process governance, change process, ASPICE process); (2) tiến trình trong OS — một chương trình đang chạy với vùng nhớ và quyền riêng (ví dụ process trình phát media chạy quyền thấp trong sandbox).","aka":["processes"]},{"t":"processing","vi":"Xử lý: bước biến đổi dữ liệu. Trong bài: một chặng trong chuỗi Source → Bus → Parser → Processing → HMI, audio processing chain (EQ, mix, echo cancellation), hay GPU (graphics processing unit)."},{"t":"producer","vi":"Bên tạo/phát dữ liệu (ghi, publish) trong một luồng giao tiếp; đối lại là consumer. Trong bài, contract giúp thêm consumer mà không phải sửa producer; producer restart hay chậm không được làm hỏng consumer.","aka":["producers"]},{"t":"producer/consumer","vi":"Cặp bên ghi/bên đọc dữ liệu. Contract giữa producer/consumer phải ghi rõ schema, version, timing, hành vi khi lỗi; giữa hai bên thường có queue hoặc buffer, cần quyết định khi đầy thì bỏ gì."},{"t":"product","vi":"Sản phẩm. Trong bài: product lifecycle (vòng đời sản phẩm từ ý tưởng đến ngừng hỗ trợ), <i>work product<\/i> (sản phẩm công việc như tài liệu, code, test theo ISO 26262), product owner.","aka":["products"]},{"t":"production","vi":"Sản xuất/vận hành thật. Trong ô tô thường đi với SOP (Start of Production) — ngày nhà máy bắt đầu sản xuất hàng loạt; “production” cũng chỉ môi trường chạy thật, khác với lab/test."},{"t":"project","vi":"Dự án. Trong bài, “project context” là bối cảnh dự án thật của người học, dùng để áp dụng bài tập; “project data” là số liệu thực của dự án để kiểm giả định.","aka":["projects"]},{"t":"property","vi":"Thuộc tính. Trong bài có ba nghĩa: thuộc tính bảo mật cần bảo vệ (integrity, confidentiality…), <i>Vehicle HAL property<\/i> — một giá trị xe (tốc độ, số) app Android đọc qua HAL, và <i>Intellectual Property<\/i> (sở hữu trí tuệ).","aka":["properties"]},{"t":"protection","vi":"Bảo vệ: cơ chế ngăn hoặc phát hiện lỗi/tấn công. Trong bài: E2E protection (CRC, counter chống message hỏng/mất), rollback protection (chặn cài lại bản cũ có lỗ hổng), replay protection, memory protection giữa các partition."},{"t":"protocol","vi":"Giao thức: bộ quy tắc hai bên dùng để trao đổi dữ liệu (định dạng, thứ tự, xử lý lỗi), ví dụ CAN, SOME/IP, DDS. Chọn protocol là quyết định khó đảo ngược vì ràng buộc cả supplier và các consumer.","aka":["protocols"]},{"t":"provenance","vi":"Nguồn gốc có bằng chứng: binary được build từ source nào, commit nào, bằng pipeline/toolchain nào, ai ký. Trong bài, provenance giúp tái hiện lỗi, khoanh đúng xe bị ảnh hưởng và chứng minh bản phát hành không bị can thiệp."},{"t":"provider","vi":"Nhà cung cấp/bên cung cấp. Trong bài: cloud/connectivity provider (backend, OTA server), hoặc bên cung cấp dữ liệu/service trong interface (provider đổi km/h sang m/s mà không đổi version là lỗi contract).","aka":["providers"]},{"t":"publish","vi":"Phát/công bố. Trong giao tiếp pub/sub, service <b>publish<\/b> dữ liệu (ví dụ tốc độ xe) để mọi bên đã subscribe nhận được, không cần biết ai đang nghe. Cũng dùng cho việc công bố một release hay một lỗ hổng.","aka":["publishes","published","publishing","publisher"]},{"t":"Q&A","vi":"Questions &amp; Answers – hỏi và đáp. Trong khóa học là phần mentor đặt câu hỏi sau khi người học trình bày bài nộp, để kiểm tra lý lẽ và bằng chứng.","full":"Questions and Answers","cs":true},{"t":"QNX","vi":"Hệ điều hành thời gian thực (RTOS) kiến trúc microkernel của BlackBerry, phổ biến trong ô tô. Trong bài, QNX thường chạy phần safety/cluster trên CDC, cạnh Android Automotive (IVI) trên cùng SoC qua hypervisor.","cs":true},{"t":"QoS","vi":"Quality of Service – mức đảm bảo chất lượng truyền: độ trễ, độ tin cậy, lịch sử, deadline, ưu tiên traffic. Trong DDS/Ethernet trên xe, QoS cấu hình theo topic/luồng để dữ liệu quan trọng không bị nghẽn bởi dữ liệu phụ.","full":"Quality of Service","cs":true},{"t":"quality","vi":"Chất lượng: mức đáp ứng yêu cầu và kỳ vọng. Trong bài có ba nghĩa: chất lượng sản phẩm (quality gate, governance), <i>quality attribute<\/i> (latency, safety, availability…), và trường <i>quality<\/i> của một mẫu dữ liệu (giá trị tin cậy được đến đâu)."},{"t":"question","vi":"Câu hỏi. Trong bài: “open questions”, “unresolved questions” — các câu hỏi còn mở cần ghi rõ để mentor/reviewer trả lời, thay vì dùng thuật ngữ che đi điều chưa chắc.","aka":["questions"]},{"t":"queue","vi":"Hàng đợi: nơi các message/lệnh nằm chờ xử lý theo thứ tự. Trong bài, queue phải có giới hạn (bounded) và policy khi đầy (drop cũ, drop mới, chặn bên ghi); queue đầy hoặc dài là nguồn latency và mất dữ liệu.","aka":["queues","queued","queuing","queueing"]},{"t":"quota","vi":"Hạn mức: giới hạn tài nguyên tối đa một app/nhóm process được dùng (CPU, RAM, storage, băng thông). Trong bài, quota (ví dụ cgroups trên Linux) ngăn phần non-critical chiếm hết tài nguyên dùng chung.","aka":["quotas"]},{"t":"race","vi":"Đua tranh. Trong phần mềm thường là <i>race condition<\/i>: kết quả phụ thuộc thứ tự/thời điểm hai luồng cùng truy cập dữ liệu, gây lỗi ngẫu nhiên khó tái hiện.","aka":["races"]},{"t":"radius","vi":"Bán kính. Trong bài gần như luôn đi trong cụm <i>blast radius<\/i> — phạm vi bị ảnh hưởng khi một thành phần hỏng hoặc một bản cập nhật lỗi."},{"t":"RAM","vi":"Random Access Memory – bộ nhớ làm việc của CPU, mất dữ liệu khi tắt nguồn. Trong bài là tài nguyên phải lập budget và chia giữa các partition/VM; headroom RAM quyết định có thêm được feature qua OTA không.","full":"Random Access Memory","cs":true},{"t":"range","vi":"Khoảng/phạm vi giá trị. Trong interface contract, range là khoảng giá trị hợp lệ (ví dụ tốc độ 0–300 km/h); trong ước lượng là khoảng lạc quan–có khả năng–bi quan thay vì một con số duy nhất.","aka":["ranges"]},{"t":"rate","vi":"Tỷ lệ/tần suất. Trong bài: update rate (bao nhiêu lần/giây), sample rate (audio), discount rate (tài chính), escape rate/reopen rate (metric chất lượng), rate limit (giới hạn số request để chống quá tải/tấn công).","aka":["rates"]},{"t":"raw","vi":"Thô, chưa xử lý. Raw frame/raw signal là dữ liệu đúng như trên bus, chưa giải mã/scale; ví dụ giá trị raw 0x0064 với scale 0.01 mới thành 1.00. Lưu raw vô hạn tốn storage và có thể chạm privacy."},{"t":"RCA","vi":"Root Cause Analysis – phân tích nguyên nhân gốc: điều tra có phương pháp (hypothesis, đo, bác bỏ) để tìm nguyên nhân thật của lỗi chứ không dừng ở triệu chứng, rồi đưa ra hành động sửa và phòng ngừa. Phương pháp chính ở B.5.","aka":["RCAs"],"full":"Root Cause Analysis","cs":true},{"t":"re-validate","vi":"Kiểm chứng lại (re-validation): chạy lại validation/verification sau khi phần mềm, toolchain, OS hay phần cứng thay đổi, vì evidence cũ không tự động còn đúng. Trong xe sống 10–15 năm, chi phí re-validate là phần lớn của bảo trì.","aka":["re-validation","revalidate","revalidation","re-validated"]},{"t":"readiness","vi":"Mức sẵn sàng. Release readiness/integration readiness là trạng thái đã đủ điều kiện (evidence, release note, rollback plan, approval) để qua một gate tiếp theo."},{"t":"real-time","vi":"Thời gian thực: hệ thống đúng không chỉ khi ra kết quả đúng mà còn phải ra <b>đúng hạn<\/b> (deadline). Hard real-time: trễ hạn là lỗi; soft real-time: trễ hạn chỉ làm giảm chất lượng. Cluster, audio cảnh báo là ví dụ trong bài.","aka":["realtime","real time"]},{"t":"reboot","vi":"Khởi động lại toàn bộ hệ thống (hoặc một ECU/VM). Trong bài, reboot là triệu chứng sự cố quan trọng — ví dụ CDC reboot sau rollback OTA, hay reboot loop (khởi động lại liên tục) — và là điểm cần kiểm persistence.","aka":["reboots","rebooted","rebooting"]},{"t":"record","vi":"Bản ghi lưu lại làm bằng chứng. Trong bài: review record, gate record, decision record (ADR), inspection record — tài liệu ghi ai quyết định gì, khi nào, dựa trên evidence nào.","aka":["records","recorded","recording"]},{"t":"recovery","vi":"Phục hồi: đưa hệ thống trở lại trạng thái hoạt động sau lỗi. Trong bài: recovery khi OTA hỏng, recovery time của partition sau crash, forward recovery (sửa tiến lên khi không rollback được), và supplier recovery (đòi bồi thường)."},{"t":"redundancy","vi":"Dư thừa có chủ đích (dự phòng): có thêm thành phần/kênh để hệ thống vẫn chạy khi một phần hỏng. Tăng availability nhưng tốn chi phí, độ phức tạp; phải chứng minh hai nhánh dự phòng thật sự độc lập. Chữ R trong CRC."},{"t":"reference","vi":"Tham chiếu/chuẩn mẫu. Trong bài: <i>reference architecture<\/i> (kiến trúc mẫu để các dự án theo), tài liệu tham khảo, và reference level trong audio (mức âm chuẩn để so).","aka":["references"]},{"t":"reflection","vi":"Suy ngẫm, tự nhìn lại. “Learning reflection” là phần cuối bài để người học viết lại điều đã hiểu, áp dụng vào hệ thống của mình và câu hỏi còn mở.","aka":["reflections"]},{"t":"register","vi":"Có hai nghĩa: (1) sổ đăng ký/danh sách theo dõi — <i>risk register<\/i>, debt register; (2) thanh ghi phần cứng — vùng nhớ nhỏ để điều khiển thiết bị; feature không nên truy cập register trực tiếp mà qua API của platform.","aka":["registers","registered"]},{"t":"regression","vi":"Hồi quy: lỗi mới xuất hiện ở phần trước đây chạy đúng sau một thay đổi. <i>Regression test<\/i> là test lại phần cũ để chắc nó không bị hỏng; chi phí regression tăng theo số variant và mức coupling.","aka":["regressions"]},{"t":"regulation","vi":"Quy định pháp lý bắt buộc (ví dụ UN R155/R156 về cybersecurity và software update). Trong bài là ràng buộc cứng: economics hay trade-off chỉ được chọn trong vùng regulation cho phép.","aka":["regulations","regulatory"]},{"t":"release","vi":"Phát hành: đưa một phiên bản phần mềm đã đủ evidence ra dùng (lên xe, qua OTA). Trong bài, release là một <b>quyết định có người chịu trách nhiệm<\/b> dựa trên baseline, release note, residual risk và rollback plan — không chỉ là “build xanh”.","aka":["releases","released","releasing"]},{"t":"render","vi":"Kết xuất hình: vẽ nội dung (giao diện, bản đồ, kim đồng hồ) thành khung hình để hiển thị. Trong bài, render nặng ở IVI có thể tranh GPU và làm cluster chậm; HMI phải render trong budget latency.","aka":["renders","rendering","rendered","renderer"]},{"t":"report","vi":"Báo cáo. Trong bài: test report (kết quả test), incident/RCA report, báo cáo gửi regulator — là evidence chỉ có giá trị khi gắn đúng build, variant và requirement.","aka":["reports","reporting","reported"]},{"t":"reproducible","vi":"Tái tạo được. <i>Reproducible build<\/i>: build lại từ cùng source và toolchain ra cùng binary; điều kiện để vá lỗi nhiều năm sau SOP. Lỗi reproducible là lỗi tái hiện được theo điều kiện cố định.","aka":["reproduce","reproduction","reproducibility"]},{"t":"req","vi":"Viết tắt của <i>requirement<\/i> (yêu cầu), ví dụ “system req → software req”. Mã như REQ-012, REQ-123 trong bài là ID minh họa của một requirement trong chuỗi traceability.","full":"requirement"},{"t":"request","vi":"Yêu cầu/lời gọi. Trong bài: <i>change request<\/i> (đề nghị thay đổi chính thức qua change control), và kiểu giao tiếp request/response (bên gọi gửi yêu cầu, chờ phản hồi).","aka":["requests","requested"]},{"t":"requirement","vi":"Yêu cầu: phát biểu hệ thống phải làm gì hoặc phải đạt mức nào. Requirement tốt phải rõ, đo được (có ngưỡng), có owner, version và acceptance criteria, và truy vết được tới design, test, release.","aka":["requirements"]},{"t":"research","vi":"Nghiên cứu. Các bài C.2–C.4 là “Research Topic”: tự tìm hiểu sâu một mảng (đồ họa, audio, runtime) và viết research brief có nguồn, giả định, kết luận.","aka":["researched"]},{"t":"reservation","vi":"Đặt trước/dành riêng tài nguyên. CPU/resource reservation là giữ sẵn core, thời gian CPU, RAM hay băng thông cho tác vụ critical để nó không bị workload khác chiếm khi tải nặng.","aka":["reservations","reserved","reserve"]},{"t":"reset","vi":"Đặt lại về trạng thái ban đầu. Có thể là reset phần cứng/ECU (do watchdog, lỗi nguồn) hoặc reset một bộ đếm/trạng thái phần mềm. Reset reason là thông tin chẩn đoán quan trọng gửi qua telemetry.","aka":["resets"]},{"t":"residual","vi":"Còn lại, còn sót. Trong bài chủ yếu trong cụm <i>residual risk<\/i> — rủi ro còn lại sau khi đã áp các control, phải được người có thẩm quyền chấp nhận rõ ràng."},{"t":"resource","vi":"Tài nguyên: CPU, RAM, storage, băng thông mạng, GPU, thiết bị dùng chung. Trong bài, tài nguyên phải có budget, quota hoặc reservation; resource exhaustion (cạn tài nguyên) vừa là lỗi vừa là kiểu tấn công.","aka":["resources"]},{"t":"response","vi":"Phản hồi/ứng phó. Trong bài: response time (thời gian phản hồi), request/response (kiểu giao tiếp), incident response (quy trình ứng phó sự cố bảo mật), defect response (xử lý lỗi sau bán).","aka":["responses"]},{"t":"responsibility","vi":"Trách nhiệm. Trong bài: responsibility map (ai chịu gì giữa OEM/Tier 1/vendor), và ý “Responsibility is designed” — trách nhiệm phải được thiết kế, gán rõ cho từng interface chứ không tự có.","aka":["responsibilities"]},{"t":"restart","vi":"Khởi động lại một app, service hay VM (nhỏ hơn reboot cả hệ thống). Trong bài, IVI được phép restart khi lỗi còn cluster phải hiển thị liên tục; restart che triệu chứng nhưng không phải là RCA.","aka":["restarts","restarted","restarting"]},{"t":"result","vi":"Kết quả. Trong traceability: test result là mắt xích nối test với release; scan result, test result là evidence khách quan khi review.","aka":["results"]},{"t":"retention","vi":"Thời gian lưu giữ: dữ liệu (log, telemetry, ghi âm…) được giữ bao lâu rồi phải xóa. Trong bài, retention là một quyết định privacy và chi phí storage, phải có policy rõ."},{"t":"retry","vi":"Thử lại một thao tác sau khi lỗi. Retry cần giới hạn, backoff (giãn thời gian) và jitter; retry vô tội vạ gây retry storm, che giấu lỗi và làm nó lộ ra muộn ở chỗ khác.","aka":["retries","retrying"]},{"t":"reuse","vi":"Tái sử dụng: dùng lại thành phần, platform, test cho nhiều feature/dòng xe. Reuse giảm chi phí và time-to-market nhưng tăng coupling và blast radius; phải đánh giá cạnh các tiêu chí khác, không chọn vì reuse cao.","aka":["reused","reusable","reusing"]},{"t":"review","vi":"Xem xét, rà soát: người khác kiểm tra một artifact (requirement, thiết kế, code, test) theo checklist để tìm lỗi trước khi đi tiếp. Trong bài, review là một phần của quality gate và phải để lại review record.","aka":["reviews","reviewed","reviewing"]},{"t":"reviewer","vi":"Người review: kiểm tra artifact hoặc bài trình bày và đặt câu hỏi. Reviewer cần đủ năng lực, với artifact rủi ro cao phải độc lập với tác giả; SA nên chuẩn bị sẵn câu trả lời cho reviewer.","aka":["reviewers"]},{"t":"revision","vi":"Bản sửa đổi: một phiên bản cụ thể của artifact, source hay phần cứng (hardware revision). Evidence phải ghi đúng revision để biết nó áp dụng cho bản nào.","aka":["revisions"]},{"t":"revisit","vi":"Xem lại. Trong ADR, <i>revisit trigger/condition<\/i> là điều kiện cụ thể (hết headroom, đổi supplier, đổi regulation…) mà khi xảy ra thì quyết định phải được mở ra xem xét lại.","aka":["revisited"]},{"t":"rights","vi":"Quyền. Trong bài chủ yếu là <i>decision rights<\/i> — ai có quyền quyết định loại việc nào (kiến trúc, release, chấp nhận rủi ro); thường đi cùng RACI.","aka":["right"]},{"t":"ring","vi":"Vòng. Trong bài là <i>ring buffer<\/i> — vùng đệm vòng, ghi và đọc nối tiếp nhau, khi đến cuối thì quay lại đầu; dùng truyền dữ liệu giữa task/ISR, audio.","aka":["rings"]},{"t":"risk","vi":"Rủi ro: khả năng một điều xấu xảy ra kèm mức tác động (likelihood × impact). Trong bài, mọi risk phải có owner, mitigation, hạn và được ghi vào risk register; risk còn lại sau control là residual risk.","aka":["risks"]},{"t":"roadmap","vi":"Lộ trình kế hoạch theo thời gian: feature, phiên bản, hỗ trợ dự kiến. Trong bài, headroom phần cứng chỉ đáng tiền khi được biện minh bằng roadmap feature cụ thể; roadmap của supplier cũng là rủi ro cần xét.","aka":["roadmaps"]},{"t":"role","vi":"Vai trò: tập trách nhiệm và quyền của một người/nhóm. Trong bài: “SA Role” — Solution Architect làm gì, chịu gì, khác PM/product owner/dev ra sao.","aka":["roles"]},{"t":"rollback","vi":"Quay lui: đưa phần mềm về phiên bản cũ khi bản mới lỗi. Trong bài, rollback chỉ khả thi khi binary, dependency và persistent data còn tương thích; phải được diễn tập (rollback test) chứ không mặc định là an toàn.","aka":["rollbacks","roll back","rolled back"]},{"t":"rollout","vi":"Triển khai/phát hành ra diện rộng. Trong OTA, rollout là đưa bản mới tới đội xe, thường làm theo đợt (staged rollout) và theo dõi health metric để quyết định mở rộng, pause hay rollback.","aka":["rollouts","roll out","rolled out"]},{"t":"rollout/rollback","vi":"Cặp hoạt động phát hành và quay lui trong OTA: đưa bản mới ra dần theo đợt và có đường quay về bản cũ khi metric xấu. Chi tiết được dạy ở B.1.","aka":["staged rollout/rollback","OTA rollout/rollback"]},{"t":"root","vi":"Gốc. Trong bài: <i>root cause<\/i> (nguyên nhân gốc) và quyền <i>root<\/i> — quyền quản trị cao nhất trên hệ thống Linux/Android; app lấy được root là leo thang quyền nghiêm trọng."},{"t":"routing","vi":"Định tuyến: quyết định dữ liệu/tín hiệu đi đâu. Trong bài: audio routing (nguồn âm ra loa/vùng nào), interrupt routing (interrupt xử lý ở core nào), routing qua facade trong migration kiểu strangler."},{"t":"RTOS","vi":"Real-Time Operating System – hệ điều hành thời gian thực, bảo đảm tác vụ chạy đúng hạn và đoán trước được (ví dụ QNX). Trên CDC, phần cluster/safety thường chạy trên RTOS trong partition riêng.","aka":["RTOSes"],"full":"Real-Time Operating System","cs":true},{"t":"rule","vi":"Quy tắc/luật. Trong bài: rule triển khai của reference architecture, business rule của feature, rule của virtual switch, compatibility rule, rule chọn phương án — phải được viết ra để kiểm được.","aka":["rules"]},{"t":"run","vi":"Chạy/lượt chạy. Trong bài: simulation run, long-run stress test (chạy dài để lộ lỗi rò rỉ, quá nhiệt), parallel run (chạy hệ mới song song hệ cũ để so sánh trước khi chuyển).","aka":["runs","running"]},{"t":"runtime","vi":"Thời gian chạy/môi trường chạy: (1) lúc phần mềm đang thực thi (khác với lúc build); (2) thành phần quản lý việc chạy app (Android Runtime, AUTOSAR Execution Management, container runtime). C.4 bàn runtime trace end-to-end.","aka":["runtimes"]},{"t":"safety","vi":"An toàn — trong ô tô thường là <i>functional safety<\/i>: tránh rủi ro gây hại cho người do lỗi hệ thống điện/điện tử (theo ISO 26262, mức ASIL). Trong bài, safety là ràng buộc cứng quyết định partition, review độc lập và evidence."},{"t":"safety-relevant","vi":"Liên quan an toàn: chức năng/nội dung mà nếu sai hoặc trễ có thể gây nguy hiểm (ví dụ telltale cảnh báo, chime cảnh báo). Gán nhãn safety-relevant kéo theo yêu cầu kiến trúc, isolation và evidence chặt hơn."},{"t":"safety/cyber","vi":"Viết gộp safety (an toàn chức năng) và cybersecurity (an ninh mạng) — hai mảng rủi ro có owner, tiêu chuẩn và evidence riêng. Ảnh hưởng safety/cyber là lý do để pause rollout ngay, không chờ RCA xong."},{"t":"safety/security","vi":"Viết gộp safety (an toàn chức năng) và security (bảo mật). Trong bài, thay đổi chạm safety/security path cần review độc lập và evidence mạnh hơn; đây cũng là giới hạn cứng mà economics không được vượt."},{"t":"sample","vi":"Mẫu: một giá trị đo tại một thời điểm (mẫu tốc độ, mẫu âm thanh PCM, mẫu latency). Trong bài, mỗi sample cần timestamp, unit, quality để consumer biết nó còn tươi và dùng được không.","aka":["samples","sampling","sampled"]},{"t":"sanitize","vi":"Làm sạch: xóa/che dữ liệu nhạy cảm (VIN, vị trí, secret, dữ liệu khách hàng) khỏi log hay dữ liệu trước khi chia sẻ, ví dụ trước khi đưa cho công cụ AI hay gửi về backend.","aka":["sanitized","sanitization","sanitizing"]},{"t":"SBOM","vi":"Software Bill of Materials – danh sách thành phần phần mềm (package, version, supplier, dependency) của một build/release. Khi có CVE mới, SBOM cho biết chính xác xe/variant nào bị ảnh hưởng.","aka":["SBOMs"],"full":"Software Bill of Materials","cs":true},{"t":"scale","vi":"Có ba nghĩa trong bài: (1) mở rộng quy mô (cloud scale tốt); (2) hệ số quy đổi giá trị raw (raw × scale = giá trị thật — quên scale là lỗi kinh điển); (3) thang điểm khi chấm phương án trong weighted matrix.","aka":["scaling","scaled"]},{"t":"scan","vi":"Quét tự động để tìm vấn đề, ví dụ security scan (lỗ hổng, CVE), license scan. Scan result là một loại evidence trong release; pass scan không có nghĩa là hệ thống an toàn.","aka":["scans","scanning","scanner"]},{"t":"scenario","vi":"Kịch bản/tình huống cụ thể. Trong bài: quality scenario (kịch bản đo được cho một quality attribute), failure scenario, test scenario — giúp biến yêu cầu mơ hồ thành thứ kiểm được.","aka":["scenarios"]},{"t":"schedule","vi":"Lịch/tiến độ dự án (milestone, SOP). Trong bài là một trong các yếu tố phải cân bằng (quality, cost, scope, schedule); thay đổi muộn tác động trực tiếp tới schedule và supplier.","aka":["schedules"]},{"t":"scheduler","vi":"Bộ lập lịch: thành phần OS/hypervisor/GPU quyết định tác vụ nào được chạy, khi nào, bao lâu. Trace scheduler giúp tìm nguyên nhân trễ (preempt, starvation, jitter).","aka":["schedulers"]},{"t":"scheduling","vi":"Lập lịch: cách phân bổ thời gian CPU/GPU giữa các tác vụ (theo priority, chu kỳ, budget). Trong bài, scheduling policy real-time và cấu hình priority quyết định deadline có được đáp ứng không; cũng dùng cho lập lịch HIL."},{"t":"schema","vi":"Lược đồ dữ liệu: định nghĩa cấu trúc, kiểu, đơn vị, ý nghĩa các trường. Trong bài, schema phải có version và quy tắc tương thích; đổi schema persistent data làm rollback khó, sai schema là lỗi thường gặp giữa producer và consumer.","aka":["schemas","schemata"]},{"t":"scope","vi":"Phạm vi: những gì nằm trong/ngoài một công việc, phân tích hay quyết định. Trong bài: project scope, process scope, affected scope (số xe/variant bị ảnh hưởng), scope của test hay migration wave.","aka":["scoped","scoping"]},{"t":"script","vi":"Kịch bản lệnh: đoạn chương trình nhỏ tự động hóa một việc (build script, CI script). Trong bài, script tự viết ngoài golden path dễ tạo artifact thiếu metadata, làm đứt traceability.","aka":["scripts"]},{"t":"SDV","vi":"Software-Defined Vehicle – xe mà chức năng chủ yếu do phần mềm quyết định, có thể cập nhật và thêm tính năng sau khi bán (qua OTA), trên platform và compute tập trung. Là bối cảnh xuyên suốt khóa học.","aka":["SDVs","Software-Defined Vehicle"],"full":"Software-Defined Vehicle","cs":true},{"t":"secret","vi":"Bí mật: dữ liệu như mật khẩu, khóa mã hóa, token. Trong bài, secret không được nằm trong source code hay log, và AI agent không được đụng tới.","aka":["secrets"]},{"t":"secure","vi":"An toàn về bảo mật/được bảo vệ. Trong bài đi với nhiều cụm: secure boot, secure OTA, secure build, secure coding — mỗi cụm là một lớp control trong vòng đời security.","aka":["secured","securely"]},{"t":"security","vi":"Bảo mật (thường là cybersecurity): bảo vệ hệ thống khỏi tấn công có chủ đích. Trong xe, security là vòng lặp suốt đời xe — threat model, control, SBOM/CVE, patch qua OTA — không phải một cổng ở release."},{"t":"semantics","vi":"Ngữ nghĩa: ý nghĩa thật của dữ liệu/hành vi (không chỉ kiểu dữ liệu). Ví dụ “tốc độ hiển thị” khác “tốc độ bánh xe thô”; đổi semantics mà giữ version là phá contract dù code vẫn chạy.","aka":["semantic"]},{"t":"sensor","vi":"Cảm biến: thiết bị đo đại lượng vật lý (tốc độ bánh xe, camera, radar, nhiệt độ) và gửi dữ liệu lên ECU. Trong bài, dữ liệu sensor đi qua nhiều chặng (bus, parser, service, HMI) và mỗi chặng có owner.","aka":["sensors"]},{"t":"quality scenario","vi":"Kịch bản chất lượng: cách viết một quality attribute thành tình huống cụ thể có ngưỡng đo được, để review và test kiến trúc thay vì nói chung chung “phải nhanh, phải an toàn”.","aka":["quality scenarios"]},{"t":"quality governance","vi":"Quản trị chất lượng: bộ tiêu chí, ownership, review, gate và evidence dùng để quyết định artifact có đủ tốt để đi tiếp/release hay không. Trong bài nhấn mạnh governance phải phục vụ engineering, không chỉ là thủ tục."},{"t":"residual risk","vi":"Rủi ro còn lại sau khi đã áp các control/mitigation. Không bao giờ bằng 0, nên phải ghi rõ, đánh giá và được người có thẩm quyền chấp nhận có thời hạn trước khi release.","aka":["residual risks"]},{"t":"risk register","vi":"Sổ đăng ký rủi ro: bảng theo dõi các rủi ro với mô tả, likelihood/impact, owner, mitigation, hạn và trạng thái. Trong bài là một đầu ra bắt buộc (ví dụ maintenance risk register) và phải có ngày xem lại.","aka":["risk registers"]},{"t":"risk acceptor","vi":"Người chấp nhận rủi ro: người có thẩm quyền ký chấp nhận residual risk, thường không phải người viết code hay người chịu áp lực lịch.","aka":["risk acceptors"]},{"t":"risk exposure","vi":"Mức phơi nhiễm rủi ro: ước lượng độ lớn của rủi ro, trong bài là likelihood × impact × affected scope (số xe/variant thực sự chạy bản bị ảnh hưởng)."},{"t":"staged rollout","vi":"Phát hành theo đợt: đưa bản cập nhật tới nhóm xe nhỏ trước (internal → pilot → cohort), theo dõi health metric rồi mới mở rộng — để giới hạn blast radius nếu bản mới có lỗi.","aka":["staged rollouts","staged OTA","staged deployment"]},{"t":"rollback test","vi":"Test quay lui: diễn tập thật việc trở về bản cũ (kể cả với persistent data đã migrate) để chứng minh rollback khả thi trước khi release, không chỉ ghi “có rollback” trên giấy.","aka":["rollback tests"]},{"t":"rollback plan","vi":"Kế hoạch quay lui: mô tả khi nào, ai quyết, và làm cách nào đưa phần mềm về bản cũ nếu bản mới lỗi — một phần bắt buộc của release readiness."},{"t":"anti-rollback","vi":"Chống quay lui: cơ chế chặn cài lại phiên bản cũ có lỗ hổng đã biết (thường dùng số version/counter được bảo vệ). Phải được cân với nhu cầu rollback chức năng khi bản mới lỗi.","aka":["rollback protection"]},{"t":"regression test","vi":"Test hồi quy: chạy lại test của các phần cũ sau một thay đổi để chắc chúng không bị hỏng. Là chi phí chính của mỗi lần patch/OTA, tăng theo số variant.","aka":["regression tests","regression testing"]},{"t":"release note","vi":"Ghi chú phát hành: tài liệu đi kèm một release, mô tả thay đổi, lỗi đã sửa, known issues, phạm vi áp dụng. Release note chỉ ghi “bug fixes” là không đủ để đánh giá tác động.","aka":["release notes"]},{"t":"release baseline","vi":"Đường cơ sở phát hành: tập cấu hình cố định (source, binary, config, tài liệu, version) của một bản release, dùng làm mốc so sánh và tái hiện.","aka":["release baselines"]},{"t":"release readiness","vi":"Mức sẵn sàng phát hành: đã đủ release note, known issues, evidence, rollback/recovery plan và approval để qua gate release chưa."},{"t":"release evidence","vi":"Bằng chứng phát hành: bộ evidence (test report, review record, SBOM, provenance, residual risk được chấp nhận) chứng minh bản này đủ điều kiện release."},{"t":"release manager","vi":"Quản lý phát hành: người điều phối việc chuẩn bị, kiểm tra điều kiện và triển khai release.","aka":["release managers"]},{"t":"resource reservation","vi":"Dành riêng tài nguyên (core, thời gian CPU, RAM, băng thông) cho workload critical để nó không bị workload khác chiếm khi tranh chấp.","aka":["CPU reservation"]},{"t":"resource exhaustion","vi":"Cạn tài nguyên: CPU, RAM, storage hay queue bị dùng hết (do lỗi hoặc bị tấn công), làm service treo hoặc chậm."},{"t":"performance budget","vi":"Ngân sách hiệu năng: giới hạn thời gian/tài nguyên cho từng chặng trong một luồng, sao cho tổng vẫn đạt mục tiêu (ví dụ latency end-to-end)."},{"t":"persistent data","vi":"Dữ liệu lưu bền trên xe (cấu hình, lịch sử, cache, trạng thái) còn tồn tại qua reboot và update. Đổi schema của persistent data là quyết định khó đảo ngược vì làm rollback khó."},{"t":"schema version","vi":"Phiên bản lược đồ dữ liệu, gắn kèm dữ liệu/message để bên đọc biết đang đọc định dạng nào và xử lý tương thích.","aka":["schema_version"]},{"t":"schema mismatch","vi":"Lệch lược đồ: producer và consumer dùng schema khác nhau (khác version, khác unit/scale), dữ liệu bị hiểu sai dù không báo lỗi."},{"t":"revisit trigger","vi":"Điều kiện xem lại: sự kiện cụ thể (đổi supplier, hết headroom, đổi regulation, số đo vượt ngưỡng…) mà khi xảy ra thì quyết định trong ADR phải được đánh giá lại.","aka":["revisit triggers","revisit condition","revisit conditions"]},{"t":"reference architecture","vi":"Kiến trúc tham chiếu: kiến trúc mẫu (các lớp, building block, interface, pattern, rule) mà nhiều dự án/dòng xe dùng làm khuôn để đồng nhất và reuse.","aka":["reference architectures"]},{"t":"secure OTA","vi":"Cập nhật OTA an toàn: gói cập nhật được ký, kiểm tra tính toàn vẹn, chống cài bản cũ, có recovery, và được quản lý theo quy trình software update (SUMS)."},{"t":"secure build","vi":"Build an toàn: pipeline build được kiểm soát quyền, có provenance và ký số, để chứng minh binary đúng là từ source đã review."},{"t":"secure coding","vi":"Lập trình an toàn: viết code theo quy tắc tránh lỗ hổng phổ biến (tràn bộ đệm, kiểm tra đầu vào, xử lý lỗi…)."},{"t":"security scan","vi":"Quét bảo mật: chạy công cụ tìm lỗ hổng/CVE, cấu hình sai trong code hoặc binary; kết quả là một phần evidence của release.","aka":["security scans"]},{"t":"security patch","vi":"Bản vá bảo mật: cập nhật sửa lỗ hổng đã biết; với xe sống nhiều năm, việc nhận security patch từ supplier/upstream là một rủi ro vòng đời.","aka":["security patches"]},{"t":"E2E protection","vi":"End-to-End protection – bảo vệ đầu-cuối: thêm CRC, counter, ID vào message để bên nhận phát hiện message bị hỏng, mất, lặp hoặc sai thứ tự trên đường truyền.","full":"End-to-End protection","cs":true},{"t":"replay protection","vi":"Chống phát lại: ngăn kẻ tấn công ghi lại một message/lệnh hợp lệ rồi gửi lại sau (dùng counter, timestamp, nonce)."},{"t":"pub/sub","vi":"Publish/subscribe – kiểu giao tiếp phát–nhận: producer phát dữ liệu theo topic, mọi consumer đã đăng ký đều nhận, hai bên không cần biết nhau. Hợp cho trạng thái nhiều bên cùng dùng (tốc độ xe).","aka":["publish/subscribe","Publish/subscribe"]},{"t":"request/response","vi":"Kiểu giao tiếp hỏi–đáp: bên gọi gửi yêu cầu và chờ phản hồi (ví dụ lấy VIN, đặt mode). Contract phải ghi timeout và hành vi khi không có phản hồi."},{"t":"real-time operating system","vi":"Hệ điều hành thời gian thực (RTOS): OS bảo đảm tác vụ chạy đúng hạn, độ trễ đoán trước được.","aka":["real-time operating systems"]},{"t":"response time","vi":"Thời gian phản hồi: từ lúc có kích thích/yêu cầu tới lúc hệ thống phản hồi xong; trong bài được đo ở worst-case/P99 dưới tải chéo.","aka":["response times"]},{"t":"recovery time","vi":"Thời gian phục hồi: từ lúc lỗi (crash, reset) tới khi chức năng hoạt động lại; là tiêu chí quan trọng của partition và audio cảnh báo."},{"t":"incident response","vi":"Ứng phó sự cố: quy trình phát hiện, khoanh vùng, xử lý và rút kinh nghiệm khi có sự cố bảo mật hoặc lỗi diện rộng trên đội xe."},{"t":"reboot loop","vi":"Vòng khởi động lại: hệ thống reboot liên tục, không vào được trạng thái chạy ổn định — case sự cố sau OTA được phân tích ở B.5.","aka":["reboot loops"]},{"t":"power loss","vi":"Mất nguồn đột ngột (khi đang ghi dữ liệu, đang cài OTA). Thiết kế persistence và update phải chịu được power loss mà không hỏng dữ liệu."},{"t":"power mode","vi":"Chế độ nguồn của xe/ECU (ngủ, chờ, chạy, tắt); ảnh hưởng tới việc dịch vụ nào được chạy và khi nào được update.","aka":["power modes"]},{"t":"A/B partition","vi":"Hai phân vùng phần mềm A và B: cài bản mới vào vùng không chạy, lỗi thì quay về vùng cũ. Giúp OTA an toàn nhưng tốn thêm flash, phải quyết định từ lúc thiết kế phần cứng.","aka":["A/B partitions"],"cs":true},{"t":"platform team","vi":"Nhóm platform: đội sở hữu và vận hành phần dùng chung (service, pipeline, golden path) cho các feature team; khác với feature team sở hữu chức năng cụ thể.","aka":["platform teams"]},{"t":"golden path","vi":"Con đường chuẩn được khuyến nghị: cách làm mặc định (template, pipeline, tool) do platform team cung cấp; đi ngoài golden path phải có waiver.","aka":["golden paths"]},{"t":"migration path","vi":"Lộ trình chuyển đổi: cách đi từ hệ hiện tại sang hệ đích theo từng bước, phải được tính sẵn từ khi thiết kế."},{"t":"ownership matrix","vi":"Bảng ownership: liệt kê từng thành phần/interface/dữ liệu và ai sở hữu, ai duyệt, ai được hỏi ý kiến.","aka":["ownership map","ownership maps"]},{"t":"review record","vi":"Biên bản review: ghi artifact nào, revision nào, ai review, phát hiện gì, ai sửa, ai đóng — evidence cho quality gate.","aka":["review records"]},{"t":"producer epoch","vi":"Số “đời” của producer, tăng mỗi lần producer restart; consumer dựa vào đó để biết dữ liệu mới thuộc đời mới và reset bộ đếm, tránh dùng stale data.","aka":["producer_epoch"]},{"t":"update rate","vi":"Tần suất cập nhật: bao nhiêu lần/giây một giá trị được gửi mới — một phần của interface contract cùng freshness và timeout.","aka":["update rates"]},{"t":"sample rate","vi":"Tần số lấy mẫu: số mẫu mỗi giây (audio thường 48 kHz). Producer và consumer khác sample rate phải resample, nếu không âm thanh lệch/méo.","aka":["sampling rate"]},{"t":"source revision","vi":"Phiên bản source: commit/revision cụ thể của mã nguồn sinh ra một binary; dùng để lần theo lỗi tới đúng thay đổi."},{"t":"learning reflection","vi":"Phần tự nhìn lại việc học: ghi điều đã hiểu, chỗ còn mơ hồ và cách áp dụng vào hệ thống của mình."},{"t":"research brief","vi":"Bản tóm lược nghiên cứu: tài liệu ngắn trình bày câu hỏi, nguồn, giả định, kết luận và đề xuất cho một Research Topic (C.2–C.4).","aka":["research briefs"]},{"t":"retry storm","vi":"Bão thử lại: nhiều client cùng retry dồn dập khi backend chậm/lỗi, làm tải tăng vọt và hệ thống càng khó phục hồi. Chống bằng backoff, jitter, giới hạn retry, circuit breaker.","aka":["retry storms"]},{"t":"rate limit","vi":"Giới hạn tần suất: chặn số request/message vượt ngưỡng trong một khoảng thời gian, để chống quá tải hoặc tấn công từ chối dịch vụ.","aka":["rate limiting","rate limits"]},{"t":"debug port","vi":"Cổng debug: cổng phần cứng/phần mềm dùng để gỡ lỗi; phải khóa hoặc bảo vệ sau sản xuất vì là cửa tấn công, nhưng khóa thì chẩn đoán ngoài hiện trường khó hơn.","aka":["debug ports"]},{"t":"scheduling policy","vi":"Chính sách lập lịch: luật bộ lập lịch dùng để chọn tác vụ chạy (ví dụ FIFO theo priority cho real-time, chia công bằng cho tác vụ thường).","aka":["scheduling policies"]},{"t":"sample_time","vi":"Trường dữ liệu ghi <b>thời điểm lấy mẫu<\/b> của giá trị (không phải lúc nhận hay lúc hiển thị). Consumer dùng sample_time để biết dữ liệu còn tươi hay đã stale, và đo latency end-to-end."},{"t":"PREEMPT_RT","vi":"Bộ patch của Linux giúp kernel preempt được gần như mọi chỗ, giảm latency để chạy tác vụ real-time. Trong bài: PREEMPT_RT giảm latency nhưng không tự tạo ra bằng chứng WCET.","cs":true},{"t":"bytes_per_pixel","vi":"Số byte dùng để lưu một pixel (ví dụ RGBA8888 là 4 byte). Trong công thức băng thông hiển thị: width × height × bytes_per_pixel × refresh rate cho cận dưới lượng dữ liệu phải đọc/ghi mỗi giây."},{"t":"sequence","vi":"Trình tự, chuỗi bước/sự kiện theo thứ tự. Trong bài: boot/startup sequence (thứ tự khởi động các thành phần), hoặc sequence number gắn vào message để phát hiện mất, lặp hay đảo thứ tự.","aka":["sequences"]},{"t":"sequence number","vi":"Số thứ tự tăng dần gắn vào mỗi message. Consumer dựa vào nó để phát hiện message bị mất, lặp hoặc đến sai thứ tự; thường đi cùng timestamp và producer epoch để nhận ra dữ liệu cũ sau khi producer restart.","aka":["sequence numbers"]},{"t":"boot sequence","vi":"Thứ tự các thành phần được bật và khởi động (bootloader, hypervisor, OS, service, app). Trong CDC, boot sequence quyết định cluster/telltale hiện lên nhanh tới đâu, nên phải chốt sớm khi có yêu cầu thời gian khởi động.","aka":["startup sequence"]},{"t":"serialization","vi":"Tuần tự hóa: đóng gói dữ liệu (struct, object) thành chuỗi byte để gửi qua mạng/IPC rồi giải mã lại ở đầu nhận. Là việc của middleware (SOME/IP, DDS); tốn CPU và copy, nên shared memory/zero-copy được dùng khi cần nhanh.","aka":["serialize","deserialization"]},{"t":"server","vi":"Máy chủ: máy/dịch vụ cung cấp chức năng cho bên khác (client) gọi tới. Trong bài thường là backend của OEM như OTA server, telematics server; server giả mạo backend là ví dụ kinh điển của threat Spoofing.","aka":["servers"]},{"t":"service","vi":"Dịch vụ: một khả năng (capability) được cung cấp qua interface cho bên khác dùng, ví dụ vehicle-data service cung cấp tốc độ. Tùy ngữ cảnh, service còn chỉ khâu hậu mãi (dealer/service network) hoặc tiến trình chạy nền trên OS.","aka":["services"]},{"t":"service-oriented","vi":"Hướng dịch vụ: chức năng được đóng gói thành service có interface; bên dùng tìm và gọi/subscribe qua mạng thay vì nối tín hiệu cứng. Là nền của SOA và SOME/IP trên Automotive Ethernet."},{"t":"Service-Oriented Architecture","vi":"Kiến trúc hướng dịch vụ (SOA): hệ thống chia thành các service có interface chuẩn, tìm thấy nhau qua service discovery. Thêm consumer và deploy linh hoạt hơn, đổi lại cần versioning, QoS, security và quản lý contract."},{"t":"shared","vi":"Dùng chung: một tài nguyên/thành phần được nhiều bên cùng sử dụng (SoC, memory, platform, library). Dùng chung tiết kiệm chi phí nhưng mở rộng blast radius và gây ảnh hưởng chéo, nên cần owner, contract và isolation."},{"t":"shared memory","vi":"Vùng nhớ dùng chung mà nhiều process/VM cùng đọc ghi trực tiếp, không cần copy. Nhanh nhất cho IPC dữ liệu lớn (frame, audio) nhưng <b>không tự an toàn<\/b>: vẫn cần contract, ownership, synchronization và kiểm tra dữ liệu."},{"t":"shared platform","vi":"Nền tảng (OS, middleware, service) dùng chung cho nhiều chương trình xe. Có lợi khi đủ số chương trình cam kết và interface ổn định; cái giá là coupling, blast radius rộng và chi phí governance — bài toán trade-off trung tâm của A.1.","aka":["shared platforms"]},{"t":"shared library","vi":"Thư viện dùng chung mà nhiều app/service cùng nạp. Sửa một lần thì nhiều nơi được hưởng, nhưng lỗi một lần cũng làm hỏng nhiều nơi, nên cần versioning và regression test.","aka":["shared libraries"]},{"t":"shared service","vi":"Một service phục vụ nhiều consumer/feature (ví dụ shared vehicle-data service). Giảm code lặp nhưng thành điểm phụ thuộc chung: lỗi hay thay đổi của nó lan sang mọi bên dùng.","aka":["shared services"]},{"t":"sharing","vi":"Việc chia sẻ/dùng chung tài nguyên. Trong bài: resource sharing (CPU, memory, GPU), device sharing giữa các VM, dynamic sharing theo nhu cầu runtime; chia sẻ càng nhiều càng phải đo interference và có isolation."},{"t":"resource sharing","vi":"Nhiều workload dùng chung CPU, memory, GPU, mạng, storage. Giảm phần cứng và chi phí, đổi lại có tranh chấp tài nguyên (contention) và ảnh hưởng chéo, phải được giới hạn bằng quota/reservation và chứng minh bằng đo."},{"t":"signal","vi":"Tín hiệu: một giá trị dữ liệu của xe (tốc độ, nhiệt độ, trạng thái cửa) được gửi định kỳ trên bus như CAN hoặc qua service. Trong bài, mỗi signal cần contract: tên, unit, range, timestamp, update rate và hành vi khi stale.","aka":["signals"]},{"t":"speed signal","vi":"Tín hiệu tốc độ xe — ví dụ xuyên suốt khóa học: đi từ ECU qua CAN/gateway, vehicle-data service tới cluster. Dùng để minh họa contract, timing, freshness và cách khoanh vùng lỗi hiển thị."},{"t":"SLA","vi":"Cam kết mức dịch vụ trong hợp đồng: thời gian phản hồi, thời hạn vá lỗi/lỗ hổng, mức sẵn sàng. Trong bài, SLA với supplier quyết định OEM có vá kịp CVE và duy trì phần mềm nhiều năm sau SOP hay không.","aka":["SLAs"],"full":"Service Level Agreement","cs":true},{"t":"slide","vi":"Trang trình chiếu (kiểu PowerPoint). Bài nộp thường trình bày thành 8–10 slide hoặc tài liệu tương đương; slide đẹp không thay được dữ liệu và evidence.","aka":["slides"]},{"t":"SoC","vi":"Chip tích hợp CPU, GPU, NPU, bộ xử lý hình ảnh/âm thanh… trên một đế. Là bộ não của CDC: một SoC chạy cả cluster và IVI qua hypervisor, nên chọn SoC quyết định chi phí, headroom và thời gian còn được hỗ trợ.","aka":["SoCs"],"full":"System-on-Chip","cs":true},{"t":"SOC","vi":"Trung tâm giám sát an ninh: đội và hệ thống theo dõi cảnh báo bảo mật liên tục. Với OEM, SOC thu tín hiệu từ backend, IDS trên xe để phát hiện tấn công và kích hoạt incident response. Đừng nhầm với SoC (chip).","full":"Security Operations Center","cs":true},{"t":"software","vi":"Phần mềm. Trong khóa học, phần mềm xe là sản phẩm có vòng đời dài, phải có version, evidence và được cập nhật qua OTA; software ngày càng quyết định tính năng và giá trị của xe (SDV)."},{"t":"software stack","vi":"Các lớp phần mềm xếp chồng từ dưới lên: BSP/driver, hypervisor, OS, middleware, runtime, service, app. A.5 dùng stack để chỉ rõ mỗi lớp lo việc gì và lỗi thuộc lớp nào.","aka":["system software stack"]},{"t":"software update","vi":"Cập nhật phần mềm, qua OTA hoặc tại xưởng. Phải có ký số, kiểm tra tương thích, staged rollout và đường rollback; được quản lý theo hệ thống quản lý cập nhật (SUMS, UNECE R156).","aka":["software updates"]},{"t":"software-defined","vi":"Được định nghĩa bởi phần mềm: chức năng chủ yếu do phần mềm quyết định và có thể thay đổi qua update, thay vì cố định trong phần cứng. Dùng trong cụm Software-Defined Vehicle (SDV)."},{"t":"Software-Defined Vehicle","vi":"Xe định nghĩa bằng phần mềm (SDV): software, data và compute platform tạo ra phần lớn giá trị; tính năng được thêm/sửa sau khi bán qua OTA. SDV dời chi phí sang sau SOP (cloud, bảo trì, support) và đòi kiến trúc tập trung hơn.","aka":["software-defined vehicles"]},{"t":"SOME/IP","vi":"Giao thức middleware hướng dịch vụ trên Automotive Ethernet, được AUTOSAR chuẩn hóa: hỗ trợ request/response, event, service discovery và serialization. Cho phép ECU/SoC trao đổi service thay vì chỉ signal trên CAN.","full":"Scalable service-Oriented MiddlewarE over IP","cs":true},{"t":"SOP","vi":"Ngày nhà máy bắt đầu sản xuất hàng loạt mẫu xe, rất khó dời. Phần mềm phải đủ evidence để release trước SOP; sau SOP còn nhiều năm bảo trì, vá lỗi và OTA.","full":"Start of Production","cs":true},{"t":"Start of Production","vi":"Bắt đầu sản xuất hàng loạt (SOP): mốc nhà máy bắt đầu làm xe bán ra, rất khó dời. Mọi quyết định kiến trúc và evidence phải sẵn sàng trước mốc này; chi phí sửa sau SOP cao hơn nhiều."},{"t":"source","vi":"Nguồn: nơi dữ liệu, mã hay linh kiện đến từ đó. Trong bài: source code (mã nguồn), speed source (nguồn tín hiệu tốc độ), source of truth, open-source, single-source (chỉ một nhà cung cấp).","aka":["sources"]},{"t":"source of truth","vi":"Nguồn sự thật: nơi duy nhất được coi là chính thức cho một dữ liệu. Mỗi nhóm data/field cần một source of truth và owner; bản sao hay digital twin không tự động là source of truth."},{"t":"source code","vi":"Mã nguồn: chương trình do người viết, được build thành binary. Truy được binary đang chạy được build từ source revision nào (provenance) là điều kiện cho RCA và reproducible build."},{"t":"single-source","vi":"Chỉ có một nhà cung cấp làm được linh kiện/phần mềm. OEM mất đòn bẩy giá và gánh rủi ro thiếu hàng, EOL; là rủi ro chuỗi cung ứng phải ghi vào trade-off.","aka":["single source"]},{"t":"spec","vi":"Viết tắt của specification — đặc tả: tài liệu mô tả chính xác một thứ phải làm gì (requirement, interface, hành vi). Trong bài, mọi bên đều đúng spec mà xe vẫn lỗi thường là do interface thiếu contract; verification là kiểm đúng spec.","aka":["specs","specification","specifications"]},{"t":"over-spec","vi":"Chọn phần cứng/tính năng mạnh hơn nhu cầu thực tế. Làm tăng chi phí mỗi xe, nhân với volume nhiều năm thành khoản lớn; headroom chỉ đáng khi có business case (ví dụ roadmap OTA)."},{"t":"speed","vi":"Tốc độ. Trong bài thường là tốc độ xe (vehicle speed) — tín hiệu ví dụ xuyên suốt đi từ CAN tới cluster; đôi khi chỉ tốc độ làm việc (tốc độ vá lỗi, tốc độ ra quyết định)."},{"t":"sprint","vi":"Một chu kỳ làm việc ngắn (thường vài tuần) trong Agile/Scrum. Team có thể làm theo sprint nhưng mỗi requirement vẫn cần design, test và evidence; model/tài liệu không được bảo trì sẽ lệch code sau vài sprint.","aka":["sprints"]},{"t":"stack","vi":"Chồng lớp: tập lớp phần mềm/giao thức xếp chồng, lớp trên dùng lớp dưới (software stack, AUTOSAR stack, Bluetooth stack, graphics stack). Trong A.5, chọn stack là chọn nền tảng cho từng workload.","aka":["stacks"]},{"t":"stage","vi":"Giai đoạn, chặng, tầng trong một chuỗi. Trong bài: stage của pipeline hiển thị/âm thanh (render → composition → display), stage của lifecycle/traceability, hay stage-2 page table của hypervisor. Khoanh lỗi theo stage là kỹ thuật chính ở C.2–C.3.","aka":["stages"]},{"t":"staged","vi":"Theo từng đợt, từng giai đoạn. Hay gặp nhất trong staged rollout / staged OTA: phát hành bản cập nhật dần theo nhóm xe thay vì cho cả fleet cùng lúc."},{"t":"stakeholder","vi":"Bên liên quan: người/nhóm có quyền lợi hoặc chịu ảnh hưởng bởi hệ thống (khách hàng, các team, supplier, safety, cơ quan quản lý). Kiến trúc phải trả lời ai cần gì; review và quyết định cần đúng stakeholder tham gia.","aka":["stakeholders"]},{"t":"stale","vi":"Cũ, quá hạn: dữ liệu đã vượt thời gian tối đa (max age) mà không được cập nhật. Signal phải có trạng thái valid/stale; khi stale thì cluster hiện “--” hoặc cảnh báo, không hiển thị giá trị cũ như giá trị đúng."},{"t":"stale data","vi":"Dữ liệu cũ nhưng vẫn bị dùng như dữ liệu mới, ví dụ sau khi producer treo hoặc restart. Phát hiện bằng timestamp, freshness timeout, sequence number/producer epoch."},{"t":"start","vi":"Bắt đầu, khởi động. Trong bài hay gặp trong SOP (Start of Production) và start/end event — hai mốc dùng để đo latency một cách nhất quán giữa các phương án.","aka":["starts"]},{"t":"startup","vi":"Khởi động: quá trình từ lúc cấp nguồn/bật đến khi hệ thống sẵn sàng. Yêu cầu thời gian startup (ví dụ cluster phải hiện trong vài giây) là NFR có thể buộc đổi boot sequence và cách chia service.","aka":["start-up"]},{"t":"state","vi":"Trạng thái: tình trạng hiện tại của hệ thống, signal hay service (valid/stale, mode của xe, lifecycle). Trong bài, state phải được định nghĩa rõ cùng các transition, kể cả sau reboot và khi lỗi.","aka":["states"]},{"t":"state machine","vi":"Máy trạng thái: mô hình gồm các trạng thái và điều kiện chuyển giữa chúng. Dùng để đặc tả hành vi như Unknown → Valid → Stale của một signal; viết rõ giúp test được mọi transition.","aka":["state machines"]},{"t":"statement","vi":"Câu/tuyên bố chính thức. Trong bài: decision statement của ADR, scope statement của kiến trúc, VEX statement nói một CVE có khai thác được trên sản phẩm hay không.","aka":["statements"]},{"t":"static","vi":"Tĩnh: được cố định trước (lúc thiết kế/build), không đổi khi chạy. Trong bài: static analysis (phân tích code không cần chạy), static partition/cấp phát tĩnh tài nguyên giúp hành vi dự đoán được và dễ lập evidence."},{"t":"status","vi":"Trạng thái/tình trạng hiện thời được báo cáo: defect status, health status của service, status của risk hay của tài liệu (draft, approved, superseded)."},{"t":"stimulus","vi":"Tác nhân kích thích: sự kiện khởi đầu trong một quality attribute scenario (Stimulus → Environment → Response → Metric → Threshold). Ví dụ: tín hiệu cảnh báo phanh đến khi IVI đang tải nặng."},{"t":"storage","vi":"Bộ nhớ lưu trữ lâu dài (flash, eMMC/UFS…). Trong bài: storage dùng chung giữa các VM có thể bị một bên ghi tràn làm chậm bên khác; ghi quá nhiều làm mòn flash; key phải được lưu an toàn."},{"t":"storm","vi":"Bão: lượng message/request bùng nổ cùng lúc làm quá tải hệ thống. Trong bài: message storm, broadcast storm trên mạng, retry storm khi cả fleet cùng gọi lại backend.","aka":["storms"]},{"t":"strategy","vi":"Chiến lược: hướng tiếp cận có chủ đích cho một mục tiêu dài hạn. Trong bài: platform strategy, verification strategy, patch strategy, migration strategy — mỗi cái là một tập quyết định có trade-off cần ghi lại.","aka":["strategies"]},{"t":"stream","vi":"Luồng dữ liệu liên tục (video, audio, camera) chảy từ nguồn tới nơi dùng. Mỗi stream có format, timestamp, owner và policy khi bị một stream khác chen vào (ví dụ chime chen nhạc).","aka":["streams","streaming"]},{"t":"stress","vi":"Áp lực, tải nặng. Trong bài chủ yếu là stress test/stress render: cố tình đẩy tải cao để đo timing thật — số đo lúc idle không chứng minh được deadline."},{"t":"stress test","vi":"Kiểm thử dưới tải nặng hoặc điều kiện xấu có chủ đích (CPU/GPU đầy, flood message) để xem hệ thống có giữ được deadline và isolation không. Evidence timing phải lấy dưới stress, không phải lúc idle.","aka":["stress tests","stress testing"]},{"t":"subscribe","vi":"Đăng ký nhận: consumer báo với producer/middleware rằng muốn nhận một topic/event, từ đó dữ liệu mới được đẩy tới. Là nửa sau của mô hình publish/subscribe (pub/sub).","aka":["subscribes","subscriber","subscribers","resubscribe"]},{"t":"subscription","vi":"Đăng ký sử dụng. Hai nghĩa: (1) thuê bao trả phí định kỳ — tool theo subscription, tính năng xe bán theo gói; (2) đăng ký nhận dữ liệu trong pub/sub — consumer có thể mất subscription khi service restart.","aka":["subscriptions"]},{"t":"supersede","vi":"Thay thế: một ADR/tài liệu mới chính thức thay bản cũ, nhưng bản cũ vẫn được giữ làm lịch sử (trạng thái Superseded). Không sửa đè quyết định cũ để còn biết vì sao đã từng chọn như vậy.","aka":["superseded","supersedes"]},{"t":"supplier","vi":"Nhà cung cấp: công ty bán linh kiện, ECU, phần mềm hay dịch vụ cho OEM (Tier 1, Tier 2…). Ranh giới OEM–supplier là nơi hay rơi trách nhiệm: interface, evidence, vá lỗi và SLA phải được ghi rõ trong hợp đồng.","aka":["suppliers"]},{"t":"support","vi":"Hỗ trợ: (1) cam kết duy trì, vá lỗi cho sản phẩm trong một thời gian (support window, long-term support); (2) khả năng tương thích/hỗ trợ tính năng. Thời gian support của supplier phải phủ được vòng đời xe.","aka":["supported","supports"]},{"t":"support window","vi":"Khoảng thời gian một OS/thư viện/linh kiện còn được nhà cung cấp hỗ trợ và vá lỗi. Nếu ngắn hơn vòng đời xe, OEM phải tính trước: nâng cấp, mua hỗ trợ mở rộng hay tự backport bản vá."},{"t":"symptom","vi":"Triệu chứng: biểu hiện bề ngoài mà người dùng/tester thấy (màn hình giật, chime không kêu), chưa phải nguyên nhân. RCA đi từ symptom, khoanh vùng theo stage, tới root cause có evidence.","aka":["symptoms"]},{"t":"synchronization","vi":"Đồng bộ: làm các bên cùng mốc thời gian hoặc phối hợp thứ tự đọc/ghi. Trong bài: time sync giữa các OS/partition, vsync của màn hình, đồng bộ truy cập shared memory (lock, fence, memory ordering).","aka":["sync","synchronize","synchronized"]},{"t":"time sync","vi":"Đồng bộ thời gian giữa ECU, SoC và các OS/partition để timestamp các bên so sánh được với nhau. Là điều kiện bắt buộc để trace và RCA xuyên lớp.","aka":["time synchronization"]},{"t":"synthetic","vi":"Tổng hợp, nhân tạo: dữ liệu/tín hiệu được tạo ra có chủ đích chứ không lấy từ thực tế. Trong bài: synthetic data để tái hiện lỗi, hoặc ví dụ/schema synthetic dùng để minh họa."},{"t":"system","vi":"Hệ thống: tập thành phần phối hợp để làm một chức năng. Trong bài: system requirement, system test, system architecture — mức cả hệ (xe, CDC), phân biệt với mức software/component.","aka":["systems"]},{"t":"system test","vi":"Kiểm thử ở mức cả hệ thống (thường trên HIL hoặc xe) để xem có đáp ứng system requirement không. Pass system test là verification; chưa chứng minh đúng nhu cầu thật (validation).","aka":["system tests","system testing"]},{"t":"system requirement","vi":"Yêu cầu ở mức hệ thống (xe/ECU): hệ phải làm gì và đạt chất lượng nào. Được chia xuống software requirement và trace tới system test.","aka":["system requirements"]},{"t":"tail","vi":"Đuôi: phần cực trị của phân bố số đo (P99, max), nơi các lần chậm nhất nằm. Deadline phải chứng minh bằng tail hoặc WCET, không bằng giá trị trung bình."},{"t":"tail latency","vi":"Độ trễ ở phần đuôi (P99, max) thay vì trung bình. Khung hình thỉnh thoảng đứng hay cảnh báo hiếm khi trễ không lộ qua average, chỉ thấy khi nhìn tail."},{"t":"target","vi":"Mục tiêu / thiết bị đích. Hai nghĩa: (1) giá trị mục tiêu (target cost, release target); (2) target hardware — phần cứng thật (SoC/ECU) mà phần mềm sẽ chạy; số đo trên target mới là evidence đáng tin.","aka":["targets"]},{"t":"target/variant","vi":"Phần cứng đích và biến thể xe cụ thể. Evidence phải ghi rõ đã chạy trên target/variant nào, vì kết quả trên một biến thể không tự đúng cho biến thể khác."},{"t":"TCO","vi":"Tổng chi phí sở hữu: mọi chi phí trong cả vòng đời (phát triển, mỗi xe, tích hợp, bảo trì, cloud, support sau SOP), không chỉ giá mua. Phương án kiến trúc nên được so sánh theo TCO thay vì giá ban đầu.","full":"Total Cost of Ownership","cs":true},{"t":"team","vi":"Nhóm làm việc. Trong bài, team gắn với ownership: team platform, team app, team safety… Lỗi hay nằm ở ranh giới giữa các team khi interface không có owner.","aka":["teams"]},{"t":"team/supplier","vi":"Viết gọn của “team hoặc supplier” — các bên khác nhau (nội bộ hay nhà cung cấp) cùng góp phần vào hệ thống. Ranh giới giữa họ cần interface contract và owner rõ để tránh “đá bóng” khi có lỗi."},{"t":"technical","vi":"Thuộc về kỹ thuật. Trong bài: technical review, technical risk, technical debt, technical merit (độ hay về kỹ thuật) — phân biệt với tiêu chí kinh doanh, chi phí, lịch."},{"t":"technical review","vi":"Buổi review do nhóm chuyên môn đánh giá giải pháp so với yêu cầu. Khác walkthrough (chia sẻ để hiểu) và inspection (kiểm tra chặt theo checklist).","aka":["technical reviews"]},{"t":"telematics","vi":"Khối kết nối xe với cloud qua mạng di động, phục vụ OTA, theo dõi xe, app điện thoại, gọi khẩn cấp. Là cửa vào từ xa nên là một trust boundary quan trọng về security."},{"t":"telemetry","vi":"Dữ liệu đo từ xa: xe tự gửi số liệu vận hành (version, lỗi, health metric) về backend. Dùng theo dõi OTA rollout và tìm lỗi; xe không gửi telemetry phải được tính là unknown, không phải healthy."},{"t":"telltale","vi":"Đèn báo trên cụm đồng hồ (cluster): biểu tượng cảnh báo như phanh, túi khí, dây an toàn. Telltale liên quan an toàn nên phải hiện đúng và kịp deadline dù IVI/Android đang tải nặng hay bị crash.","aka":["telltales"]},{"t":"template","vi":"Mẫu: khung có sẵn các mục cần điền. Bài nộp trong khóa học dùng template cố định (trade-off, traceability matrix, ADR…) để chấm và so sánh được.","aka":["templates"]},{"t":"temporal","vi":"Thuộc về thời gian. Temporal isolation: bảo đảm domain này không làm domain kia trễ deadline (budget CPU, scheduling); khác spatial isolation (cô lập vùng bộ nhớ, device)."},{"t":"timing isolation","vi":"Cô lập về thời gian: workload này không thể làm workload khác trễ deadline (nhờ CPU reservation, budget, priority, giới hạn contention). Cùng spatial isolation là hai trụ cột của FFI trong mixed-criticality.","aka":["temporal isolation"]},{"t":"test","vi":"Kiểm thử: chạy hệ thống/phần mềm trong điều kiện xác định để so kết quả với kỳ vọng. Test chỉ có giá trị khi trace về requirement, chạy đúng build/target và để lại test report làm evidence.","aka":["tests","testing","tested"]},{"t":"test report","vi":"Báo cáo kết quả test: build/version, môi trường, test case nào pass/fail, dữ liệu đo. Là evidence chính cho gate và release.","aka":["test reports"]},{"t":"test plan","vi":"Kế hoạch test: test gì, ở mức nào (SIL/HIL/xe), điều kiện, tiêu chí pass và ai chạy. Lập trước khi đo để không chọn kết quả có lợi sau khi đã thấy số.","aka":["test plans"]},{"t":"test environment","vi":"Môi trường test: phần cứng, phần mềm, cấu hình và tool dùng để chạy test (SIL, HIL, xe). Phải ghi lại để kết quả lặp lại được và biết evidence áp dụng cho đâu.","aka":["test environments"]},{"t":"unit test","vi":"Kiểm thử đơn vị: test một hàm/module nhỏ tách riêng, thường tự động trong CI. Bắt lỗi logic sớm và rẻ nhưng không chứng minh được timing hay tích hợp.","aka":["unit tests","unit testing"]},{"t":"penetration test","vi":"Kiểm thử xâm nhập: chuyên gia đóng vai attacker tấn công thử hệ thống để tìm lỗ hổng. Pass trước release không có nghĩa an toàn mãi; CVE mới vẫn xuất hiện sau SOP.","aka":["penetration testing","pentest","pen test"]},{"t":"test/evidence","vi":"Viết gọn của “test và evidence”: test đã chạy cùng bằng chứng (report, log, số đo) chứng minh một control hay yêu cầu thật sự hoạt động."},{"t":"thermal","vi":"Nhiệt: liên quan nhiệt độ và tản nhiệt của chip/thiết bị. Khi SoC quá nhiệt nó tự giảm xung, làm timing của mọi workload dùng chung chip xấu đi; vì vậy thermal là một nguồn ảnh hưởng chéo."},{"t":"thread","vi":"Luồng: (1) đơn vị thực thi nhỏ nhất được OS lập lịch trong một process — priority, preemption của thread quyết định latency; (2) digital thread: sợi liên kết dữ liệu xuyên vòng đời (B.1).","aka":["threads"]},{"t":"digital thread","vi":"Sợi chỉ số: chuỗi liên kết có ngữ nghĩa giữa requirement, model, code, build, test và xe đang chạy, cho phép truy vết và impact analysis. Không có link có hướng thì chỉ là “traceability giả”."},{"t":"threat","vi":"Mối đe dọa: cách một attacker có thể gây hại cho asset (giả mạo, sửa dữ liệu, làm tê liệt…). Trong A.3, mỗi threat phải map tới control và evidence; control không gắn threat nào là lãng phí.","aka":["threats"]},{"t":"threat model","vi":"Mô hình mối đe dọa: phân tích có hệ thống bảo vệ gì (asset), trước ai, từ cửa nào (entry point, trust boundary) và threat nào cần control. Thường dùng STRIDE; làm trước release và cập nhật khi hệ thống đổi.","aka":["threat models","threat modeling","threat modelling"]},{"t":"threshold","vi":"Ngưỡng: giá trị đặt trước để quyết định đạt/không đạt hoặc hành động. Trong bài: ngưỡng của quality scenario, ngưỡng lỗi cho release, ngưỡng health metric để mở rộng hay dừng rollout.","aka":["thresholds"]},{"t":"throughput","vi":"Thông lượng: lượng việc/dữ liệu xử lý được trong một khoảng thời gian (frame/s, MB/s). Khác latency: hệ có thể throughput cao nhưng thỉnh thoảng vẫn trễ."},{"t":"ticket","vi":"Phiếu công việc/lỗi trong hệ thống quản lý (kiểu Jira). Mỗi defect, CVE hay quyết định chấp nhận risk phải có ticket có owner; đóng ticket cần evidence, không chỉ vì triệu chứng đã tắt.","aka":["tickets"]},{"t":"tier","vi":"Cấp, bậc. Trong ngành ô tô: Tier 1 là nhà cung cấp trực tiếp cho OEM, Tier 2 cung cấp cho Tier 1. Từ này cũng dùng cho các mức phân loại khác (mức evidence, mức hỗ trợ).","aka":["tiers"]},{"t":"Tier 1","vi":"Nhà cung cấp cấp 1: bán trực tiếp cho OEM hệ thống/ECU hoàn chỉnh (ví dụ CDC), tích hợp phần cứng và phần mềm từ Tier 2. OEM hay Tier 1 sở hữu interface, evidence, OTA là câu hỏi lặp lại trong bài.","aka":["Tier-1"]},{"t":"Tier 2","vi":"Nhà cung cấp cấp 2: cung cấp chip, OS, middleware, BSP… cho Tier 1. Thường không ký trực tiếp với OEM nên vá lỗi và thông tin lỗ hổng phải đi qua Tier 1.","aka":["Tier-2"]},{"t":"time","vi":"Thời gian. Trong bài hay đi trong cụm: boot time, response time, lead time, execution time, time-to-market; đo time luôn phải ghi rõ điểm đầu, điểm cuối và điều kiện tải.","aka":["times"]},{"t":"time-to-market","vi":"Thời gian từ ý tưởng tới khi sản phẩm/tính năng ra thị trường. Platform dùng chung và OTA rút ngắn time-to-market cho tính năng sau, đổi lại tốn đầu tư ban đầu.","aka":["time to market"]},{"t":"execution time","vi":"Thời gian thực thi: CPU chạy một tác vụ mất bao lâu. Phân tích worst-case execution time (WCET) là cơ sở chứng minh deadline cho chức năng safety."},{"t":"time window","vi":"Khoảng thời gian xác định dùng để tính metric hoặc thực hiện một việc (ví dụ tỉ lệ lỗi trong một tuần). Metric không ghi rõ time window thì không so sánh được."},{"t":"timeout","vi":"Hết thời gian chờ: giới hạn mà quá nó thì coi như không có phản hồi/dữ liệu và chuyển sang hành vi lỗi định trước. Contract phải nói timeout bao lâu và consumer làm gì (stale, cảnh báo, diagnostic event).","aka":["timeouts"]},{"t":"timestamp","vi":"Dấu thời gian: thời điểm dữ liệu được lấy mẫu/sinh ra hoặc sự kiện xảy ra, gắn kèm dữ liệu/log. Dùng tính freshness, latency và nối log các lớp; vô dụng nếu đồng hồ các bên không đồng bộ.","aka":["timestamps","time stamp"]},{"t":"timing","vi":"Đặc tính thời gian: latency, jitter, deadline, chu kỳ, thứ tự. Timing là một phần của interface contract và phải đo trên target dưới tải; lỗi timing thường chỉ lộ khi tích hợp."},{"t":"tolerance","vi":"Dung sai / mức chịu được: (1) sai số cho phép giữa số đo và model; (2) risk tolerance — mức rủi ro tổ chức chấp nhận; (3) fault tolerance — khả năng vẫn hoạt động khi có lỗi."},{"t":"tool","vi":"Công cụ (phần mềm hoặc thiết bị) dùng để làm việc: compiler, test tool, diagnostic tool, tool quản lý requirement. Tool dùng trong dự án safety có thể cần tool qualification.","aka":["tools"]},{"t":"tool qualification","vi":"Chứng nhận công cụ: chứng minh một tool (compiler, test tool, code generator) đủ tin cậy để dùng trong dự án safety theo ISO 26262, vì lỗi của tool có thể lọt vào sản phẩm."},{"t":"toolchain","vi":"Chuỗi công cụ để build phần mềm: compiler, linker, SDK, build system. Đổi toolchain có thể buộc re-validate gần như toàn bộ, nên version toolchain là một phần của baseline.","aka":["toolchains"]},{"t":"tooling","vi":"Bộ công cụ hỗ trợ (debug, trace, cấu hình, test) đi kèm một nền tảng; chất lượng tooling ảnh hưởng mạnh tới chi phí tích hợp. Trong chi phí NRE, tooling còn chỉ đồ gá/khuôn cho sản xuất."},{"t":"topic","vi":"Chủ đề. Hai nghĩa: (1) chủ đề/bài học trong khóa học (ví dụ topic 6 = A.4); (2) trong pub/sub, topic là kênh dữ liệu có tên mà producer publish và consumer subscribe.","aka":["topics"]},{"t":"topology","vi":"Cấu trúc liên kết: cách các ECU/compute được bố trí và nối mạng (distributed, domain, zonal + central compute). Topology quyết định wiring, số ECU, latency và blast radius.","aka":["topologies"]},{"t":"trace","vi":"Dấu vết / truy vết: (1) trace link nối requirement với design, code, test; (2) runtime trace ghi sự kiện có timestamp qua các lớp để thấy latency/lỗi nằm ở đâu. Cả hai là evidence, không phải ý kiến.","aka":["traces","tracing","traced"]},{"t":"trace link","vi":"Liên kết truy vết giữa hai artifact (requirement → test, code → requirement). Link phải có hướng và ngữ nghĩa (verifies, implements…) mới dùng được cho impact analysis.","aka":["trace links"]},{"t":"traceability","vi":"Khả năng truy vết: lần được từ requirement tới design, code, test, build, release và xe đang chạy (và ngược lại). Cho phép trả lời nhanh xe nào bị ảnh hưởng, đã test chưa khi có thay đổi hay CVE."},{"t":"traceability matrix","vi":"Bảng truy vết: mỗi dòng là một requirement, các cột là design, code, test, evidence liên quan. Ô trống là gap phải đánh dấu, không được che đi."},{"t":"trade-off","vi":"Đánh đổi: được thứ này thì mất thứ kia (chi phí vs isolation, tốc độ vá vs regression risk). SA không tìm phương án hoàn hảo mà làm rõ trade-off, ghi lý do chọn và điều kiện xem lại.","aka":["trade-offs","tradeoff","tradeoffs"]},{"t":"traffic","vi":"Lưu lượng dữ liệu trên mạng/bus. Trong bài: traffic của các VM dùng chung switch, QoS ưu tiên traffic quan trọng, cutover chuyển traffic/consumer sang hệ mới."},{"t":"transition","vi":"Chuyển đổi: (1) chuyển giữa hai trạng thái trong state machine (Valid → Stale); (2) quá trình chuyển dần từ kiến trúc cũ sang mới (phased transition); (3) chuyển mức âm thanh (transition ramp).","aka":["transitions"]},{"t":"triage","vi":"Phân loại ưu tiên (gốc từ y khoa): xem nhanh một lỗi/CVE để quyết định mức nghiêm trọng, ai xử lý, xử lý khi nào. CVE triage trả lời: có trên xe không, khai thác được không, gấp tới đâu."},{"t":"trigger","vi":"Kích hoạt / điều kiện kích hoạt. Trigger của risk hay debt là dấu hiệu cho biết phải hành động hoặc xem lại (ví dụ latency đo vượt ngưỡng cảnh báo); trong runtime là sự kiện khởi động một xử lý.","aka":["triggers","triggered"]},{"t":"trouble","vi":"Sự cố, trục trặc. Trong bài chủ yếu gặp trong DTC (Diagnostic Trouble Code) — mã lỗi chẩn đoán được ECU lưu lại khi phát hiện lỗi."},{"t":"troubleshooting","vi":"Xử lý sự cố: quy trình tìm và khắc phục lỗi — từ symptom, khoanh vùng, giả thuyết, tái hiện tới root cause và fix. B.5 dạy troubleshooting dựa trên evidence thay vì phỏng đoán."},{"t":"truth","vi":"Sự thật. Trong bài chủ yếu nằm trong cụm source of truth — nguồn chính thức duy nhất của một dữ liệu, nơi mọi bên phải đối chiếu khi các bản sao mâu thuẫn nhau."},{"t":"tuning","vi":"Tinh chỉnh: điều chỉnh tham số để đạt hiệu năng/chất lượng mong muốn (latency tuning, tuning DSP âm thanh). Bài nhấn mạnh có thứ tưởng là tuning (như số buffer) thực ra là quyết định kiến trúc."},{"t":"UI","vi":"Giao diện người dùng: phần màn hình, nút, hình ảnh mà người dùng nhìn và thao tác. Trên CDC, thay đổi UI thuần thường ít rủi ro hơn thay đổi đường safety, nên có thể đi luồng review nhẹ hơn.","full":"User Interface","cs":true},{"t":"uncertainty","vi":"Sự không chắc chắn: phần chưa biết hoặc chưa đo được. Uncertainty phải được ghi ra (assumption, giới hạn, cách xác minh), không được che bằng thuật ngữ hay số liệu tự tin quá mức."},{"t":"unit","vi":"Đơn vị. Các nghĩa trong khóa: (1) Unit = một bài học (Unit A.2); (2) đơn vị đo của signal (km/h, ms) — phải ghi trong contract; (3) module nhỏ nhất trong unit test; (4) per unit = mỗi xe/mỗi sản phẩm.","aka":["units"]},{"t":"unknown","vi":"Chưa biết / chưa xác định. Trong bài là một trạng thái có chủ đích: xe không gửi telemetry là unknown chứ không phải healthy; signal sau reboot bắt đầu ở Unknown đến khi có frame hợp lệ."},{"t":"update","vi":"Cập nhật: thay phần mềm/dữ liệu bằng bản mới. Trong bài chủ yếu là software update qua OTA hoặc tại xưởng; ngoài ra update rate là tần suất một signal được làm mới.","aka":["updates","updated","updating"]},{"t":"delta update","vi":"Cập nhật chỉ gửi phần khác biệt so với bản đang có, giảm dung lượng tải OTA và thời gian cài; đổi lại phải biết chính xác version gốc trên từng xe.","aka":["delta updates"]},{"t":"use","vi":"Dùng, sử dụng. Trong bài hay gặp trong use case và assumption of use (giả định về cách dùng mà supplier đặt ra cho component của họ).","aka":["uses"]},{"t":"user","vi":"Người dùng: tài xế, hành khách hoặc người vận hành tương tác với hệ thống. Trong bài: user value, user outcome là thước đo cuối của feature; dữ liệu người dùng có thể là dữ liệu cá nhân.","aka":["users"]},{"t":"UX","vi":"Trải nghiệm người dùng: cảm nhận tổng thể khi dùng (mượt, nhanh, dễ hiểu). Trên IVI, UX quan trọng nhưng không được làm chậm cảnh báo safety; UX vs safety là trade-off lặp lại trong bài.","full":"User Experience","cs":true},{"t":"V-Model","vi":"Mô hình chữ V: nhánh trái đi xuống từ requirement tới design và code, nhánh phải đi lên qua unit, integration, system test; mỗi tầng bên trái có mức test tương ứng bên phải. Khung lifecycle quen thuộc trong ô tô.","aka":["V model"]},{"t":"valid","vi":"Hợp lệ: dữ liệu đúng định dạng, trong range và còn tươi, đủ tin để dùng. Trong bài là một trạng thái của signal (Valid/Stale/Invalid); chỉ frame hợp lệ mới đưa signal về Valid."},{"t":"validate","vi":"Kiểm chứng: (1) xác nhận đúng nhu cầu thật (validation), re-validate sau thay đổi; (2) kiểm tra dữ liệu đầu vào có hợp lệ không — IPC phải validate input đến từ bên kém tin cậy.","aka":["validated","revalidate"]},{"t":"validation","vi":"Thẩm định: xác nhận sản phẩm đáp ứng đúng nhu cầu thật của người dùng trong điều kiện thật (“làm đúng cái cần làm”). Khác verification (kiểm đúng spec); thường làm trên xe, scenario thật, field trial."},{"t":"validity","vi":"Tính hợp lệ/hiệu lực: dữ liệu có đáng tin để dùng không (quality/validity flag), hoặc evidence/model còn hiệu lực trong phạm vi nào (validity domain) sau khi có thay đổi."},{"t":"value","vi":"Giá trị: (1) giá trị số của dữ liệu — nên gửi value + quality + timestamp; (2) giá trị mang lại cho khách hàng/kinh doanh (customer value, user value).","aka":["values"]},{"t":"variant","vi":"Biến thể: các phiên bản khác nhau của cùng sản phẩm (thị trường, trang bị, phần cứng). Mỗi variant nhân thêm cấu hình phải build, test, trace; quản lý variant là chi phí lớn của phần mềm xe.","aka":["variants"]},{"t":"variant matrix","vi":"Bảng liệt kê các biến thể (phần cứng, thị trường, option) và cấu hình/phần mềm tương ứng; dùng kiểm tra bản cập nhật có tương thích với xe trước khi cài."},{"t":"variant management","vi":"Quản lý biến thể: tổ chức cấu hình, code và test cho nhiều variant mà không nhân bản tràn lan (feature flag, product line, configuration)."},{"t":"vehicle","vi":"Xe, phương tiện. Trong bài thường nằm trong cụm vehicle network, vehicle data, vehicle computer, Software-Defined Vehicle.","aka":["vehicles"]},{"t":"vehicle computer","vi":"Máy tính trung tâm của xe (central compute): SoC mạnh chạy logic feature của nhiều domain, còn zone controller lo I/O. Là xu hướng của kiến trúc zonal/SDV.","aka":["vehicle computers"]},{"t":"vehicle network","vi":"Mạng nội bộ của xe (CAN, LIN, Automotive Ethernet) nối các ECU. Kẻ tấn công chạm được vehicle network là có thể chạm tới lệnh điều khiển xe, nên phải có gateway/segmentation."},{"t":"vehicle-data","vi":"Dữ liệu xe: tốc độ, trạng thái cửa, nhiệt độ, vị trí… lấy từ ECU/sensor. Cần schema, unit, owner, source of truth; có thể chứa dữ liệu cá nhân nên chịu luật bảo vệ dữ liệu.","aka":["vehicle data"]},{"t":"vehicle-data service","vi":"Service ví dụ xuyên suốt khóa học: đọc signal xe từ CAN/gateway, giải mã, gắn timestamp/validity rồi publish cho cluster, app, cloud. Dùng để minh họa ownership, contract, CVE và timing.","aka":["vehicle data service","vehicle-data services"]},{"t":"Vehicle Signal Specification","vi":"Đặc tả tín hiệu xe (VSS) do cộng đồng COVESA phát triển: đặt tên và ý nghĩa chuẩn cho signal theo dạng cây (ví dụ Vehicle.Speed). Giúp chuẩn hóa phần tên và unit, nhưng không thay được contract về timing, owner."},{"t":"vendor","vi":"Hãng/nhà cung cấp sản phẩm (chip vendor, OS vendor, tool vendor), gần nghĩa supplier. Phụ thuộc vendor (lock-in, license, lịch vá lỗi) là một rủi ro phải tính trong trade-off.","aka":["vendors"]},{"t":"verification","vi":"Kiểm định: kiểm sản phẩm có đúng specification không (“làm đúng cách”), bằng review, static analysis, unit/integration/system test. Khác validation (đúng nhu cầu thật)."},{"t":"verify","vi":"Kiểm tra, xác minh có đúng không. Trong bài: verify requirement (phải đo được mới verify được), verify chữ ký số trong secure boot, verify lại sau khi vá.","aka":["verified","verifies"]},{"t":"version","vi":"Phiên bản: một trạng thái cụ thể có định danh của phần mềm, tài liệu, interface hay model. Mọi evidence, lỗi, CVE đều phải gắn version để biết xe nào bị ảnh hưởng.","aka":["versions"]},{"t":"version control","vi":"Quản lý phiên bản (ví dụ Git): lưu lịch sử thay đổi của code/tài liệu — ai đổi gì, khi nào. Là nền cho baseline và reproducible build."},{"t":"version drift","vi":"Lệch version dần: producer, consumer, xe và backend chạy các version khác nhau theo thời gian, đến lúc contract không còn khớp. Rủi ro điển hình của pub/sub và OTA từng phần."},{"t":"versioning","vi":"Đánh version: quy tắc đặt và tăng version cùng chính sách tương thích, để interface/platform nâng cấp độc lập mà bên dùng biết khi nào thay đổi phá vỡ tương thích."},{"t":"video","vi":"Hình ảnh động. Trong bài: video trên IVI (phải tắt khi xe chạy), stream camera, quay video màn hình để đo timing hiển thị; render video là một nguồn tải GPU/memory.","aka":["videos"]},{"t":"view","vi":"Góc nhìn: một cách trình bày kiến trúc cho một câu hỏi/stakeholder cụ thể (logical view, deployment view, runtime view). Trong MBSE, tài liệu là view sinh ra từ model.","aka":["views"]},{"t":"logical view","vi":"Góc nhìn logic: mô tả các capability/service và quan hệ giữa chúng, chưa nói chạy ở đâu. Cùng deployment view là cặp view quan trọng nhất của kiến trúc."},{"t":"deployment view","vi":"Góc nhìn triển khai: mô tả mỗi thành phần chạy trên ECU/VM/container/cloud nào và dùng tài nguyên gì. Trả lời câu hỏi “chạy ở đâu” và là nơi thấy rõ tài nguyên dùng chung, blast radius."},{"t":"runtime view","vi":"Góc nhìn lúc chạy: thứ tự tương tác, pattern (pub/sub, request/response), timing và hành vi khi lỗi giữa các thành phần."},{"t":"VIN","vi":"Số nhận dạng xe (số khung), 17 ký tự, duy nhất cho mỗi xe. Dùng xác định xe trong OTA, bảo hành; VIN gắn với chủ xe nên là dữ liệu cá nhân, phải che khi chia sẻ log.","aka":["VINs"],"full":"Vehicle Identification Number","cs":true},{"t":"VirtIO","vi":"Chuẩn thiết bị ảo: guest OS dùng driver chung để truy cập thiết bị (mạng, đĩa, GPU) do hypervisor/back-end cung cấp thay vì phần cứng thật. Dễ chia sẻ thiết bị giữa VM nhưng thêm latency và cần owner của back-end."},{"t":"virtual","vi":"Ảo: được mô phỏng bằng phần mềm thay vì vật lý. Trong bài: Virtual Machine, virtual ECU, virtual switch, virtual-first (phát triển và test trên môi trường ảo trước khi có phần cứng)."},{"t":"virtual ECU","vi":"ECU ảo: phần mềm ECU chạy trên máy tính/cloud mô phỏng, dùng cho test sớm (SIL) khi chưa có phần cứng. Không chứng minh được timing trên target thật.","aka":["virtual ECUs"]},{"t":"Virtual Machine","vi":"Máy ảo (VM): một môi trường như máy tính độc lập do hypervisor tạo, chạy guest OS riêng — ví dụ Android Automotive và QNX cùng chạy trên một SoC.","aka":["virtual machines"]},{"t":"virtualization","vi":"Ảo hóa: dùng hypervisor chia một phần cứng (SoC) thành nhiều máy ảo/partition chạy OS khác nhau. Trong CDC giúp gộp cluster và IVI lên một chip, đổi lại phải chứng minh isolation và chịu overhead."},{"t":"VM","vi":"Máy ảo: môi trường như máy tính độc lập do hypervisor tạo, chạy guest OS riêng. Trong CDC, VM tách cluster (QNX/RTOS) khỏi IVI (Android) trên cùng SoC; tên như VM-A trong bài chỉ để minh họa.","aka":["VMs"],"full":"Virtual Machine","cs":true},{"t":"volume","vi":"(1) Sản lượng: số xe sản xuất/bán — chênh lệch nhỏ mỗi xe nhân với volume nhiều năm thành số lớn; (2) âm lượng trong audio (volume/mute, speed-dependent volume).","aka":["volumes"]},{"t":"speed-dependent volume","vi":"Âm lượng tự tăng theo tốc độ xe để bù tiếng ồn đường và gió; một ví dụ audio dùng trong phần C. Cần tín hiệu tốc độ đúng và kịp thời, nên là ví dụ nối audio với vehicle data."},{"t":"vulnerability","vi":"Lỗ hổng bảo mật: điểm yếu trong phần mềm/cấu hình mà attacker có thể khai thác, thường được công bố dưới mã CVE. Phải được theo dõi suốt vòng đời xe, không chỉ trước release.","aka":["vulnerabilities"]},{"t":"vulnerability monitoring","vi":"Theo dõi lỗ hổng liên tục: đối chiếu SBOM của mọi release đang chạy trên xe với nguồn CVE và thông báo từ supplier để phát hiện cái nào ảnh hưởng xe."},{"t":"waiver","vi":"Miễn trừ: ngoại lệ chính thức cho phép tạm không đạt một tiêu chí của gate, có lý do, người duyệt, điều kiện và thời hạn. Waiver không có hạn và owner là cách nợ âm thầm tích lũy.","aka":["waivers"]},{"t":"watchdog","vi":"Bộ canh: cơ chế (thường là timer phần cứng) mà phần mềm phải “báo sống” định kỳ; nếu phần mềm treo không báo, watchdog reset/restart hệ thống hoặc thành phần đó.","aka":["watchdogs"]},{"t":"WCET","vi":"Thời gian thực thi xấu nhất của một tác vụ trên phần cứng cụ thể. Là cơ sở chứng minh deadline cho chức năng safety; số đo trung bình hay lúc idle không thay được WCET.","full":"Worst-Case Execution Time","cs":true},{"t":"worst-case execution time","vi":"Thời gian thực thi xấu nhất (WCET) của một tác vụ, xét mọi đường code và điều kiện tải, tranh chấp tài nguyên. Dùng để chứng minh tác vụ luôn kịp deadline."},{"t":"window","vi":"Cửa sổ / khoảng thời gian. Trong bài: support window (thời gian còn được hỗ trợ), time window để tính metric, cutover window (khung giờ chuyển sang hệ mới).","aka":["windows"]},{"t":"wiring","vi":"Dây dẫn, bó dây nối các ECU, sensor. Kiến trúc zonal giảm wiring (nhẹ, rẻ, dễ lắp ráp) nhưng chuyển chi phí và độ phức tạp sang compute và phần mềm."},{"t":"workaround","vi":"Cách xử lý tạm để né lỗi mà chưa sửa nguyên nhân. Hữu ích để kịp mốc nhưng phải ghi thành technical debt có owner, trigger và kế hoạch trả.","aka":["workarounds"]},{"t":"workflow","vi":"Quy trình / luồng công việc: chuỗi bước có thứ tự, ai làm gì (review, duyệt, release). Platform tốt cung cấp workflow chuẩn (golden path) để team đi đúng mà ít tốn công.","aka":["workflows"]},{"t":"workload","vi":"Khối công việc chạy trên hệ thống: một app, service hay OS với nhu cầu CPU/GPU/memory và mức criticality riêng. Phân loại workload (safety, real-time, infotainment) là bước đầu để chọn nền tảng và isolation.","aka":["workloads"]},{"t":"workshop","vi":"(1) Xưởng dịch vụ/đại lý nơi sửa chữa, chẩn đoán, cập nhật phần mềm cho xe; (2) Applied Workshop — phần thực hành trong khóa học, áp kiến thức vào bài tập.","aka":["workshops"]},{"t":"worst-case","vi":"Trường hợp xấu nhất: tình huống tải/thời gian tệ nhất có thể xảy ra. Chứng minh safety dựa trên worst-case chứ không phải trung bình; thiết kế dynamic sharing thường khó chứng minh worst-case hơn.","aka":["worst case"]},{"t":"write","vi":"Ghi: thao tác ghi dữ liệu vào bộ nhớ/storage (ngược với read), ví dụ flood write làm nghẽn storage dùng chung. Cũng dùng theo nghĩa thường là viết (write hypotheses — viết ra giả thuyết).","aka":["writes"]},{"t":"year","vi":"Năm. Trong bài hay gặp trong model year — đời xe theo năm, mốc thường dùng để đổi phần cứng hay lên kế hoạch thay thế.","aka":["years"]},{"t":"zero-copy","vi":"Không sao chép: chuyển “tay cầm” (handle) tới buffer thay vì copy dữ liệu, giảm CPU và latency cho frame/audio. Nhưng zero-copy <b>không miễn<\/b> contract, ownership và synchronization.","aka":["zero copy"]},{"t":"speed_source","vi":"Tên field ví dụ (kiểu tên biến trong code) cho biết tốc độ đến từ nguồn nào (bánh xe, GPS…). Case A.2 dùng việc thêm field này để cho thấy một thay đổi nhỏ trong code vẫn kéo theo contract, consumer, test và evidence."},{"t":"speed_publisher","vi":"Tên module ví dụ (kiểu tên trong code): phần của vehicle-data service publish tín hiệu tốc độ. Dùng trong chuỗi trace mẫu requirement → design → module → test case → baseline."},{"t":"test_cluster","vi":"Tên file Excel minh họa chứa test của cluster. Ví dụ ở B.1 cho thấy link tới cả một file (không tới test case cụ thể, không có version) là traceability giả: không ai biết test nào chứng minh requirement.","aka":["test_cluster.xlsx"]},{"t":"break-even","vi":"Điểm <b>hòa vốn<\/b>: mức (số xe, số chương trình, số năm…) mà tại đó hai phương án có tổng chi phí bằng nhau, hoặc lợi ích vừa bù chi phí. Trong bài: tìm ngưỡng để biết khi nào đầu tư platform chung mới đáng, ví dụ 3.0n = 7.2 + 1.1n.","aka":["breakeven","break even","break-even point"]},{"t":"NRE","vi":"Chi phí phát triển <b>trả một lần<\/b>, không phụ thuộc số xe bán ra: thiết kế, code, prototype, tooling, mua HIL bench. Trong bài, NRE thấp lúc đầu chưa chắc rẻ: phải cộng chi phí per-unit và maintenance theo cả vòng đời (TCO).","aka":["NREs"],"full":"Non-Recurring Engineering","cs":true},{"t":"non-recurring engineering","vi":"Kỹ thuật/chi phí <b>không lặp lại<\/b> (viết tắt NRE): khoản chi một lần cho phát triển ban đầu, khác với chi phí lặp lại theo từng xe hay từng năm.","aka":["non-recurring"]},{"t":"sensitivity","vi":"Độ <b>nhạy<\/b>: kết quả thay đổi bao nhiêu khi một giả định (volume, tỷ lệ reuse, defect probability…) thay đổi. Trong bài, sensitivity cho biết ngưỡng nào làm phương án đảo thứ hạng, tức kết luận còn đứng vững đến đâu."},{"t":"NPV","vi":"<b>Giá trị hiện tại ròng<\/b>: tổng mọi dòng tiền (chi âm, thu/tiết kiệm dương) đã quy về giá trị hôm nay bằng discount rate. NPV dương nghĩa là khoản đầu tư (ví dụ tự động hóa test) đáng làm theo tiêu chuẩn tài chính của tổ chức.","aka":["Net Present Value"],"full":"Net Present Value","cs":true},{"t":"IRR","vi":"<b>Tỷ suất hoàn vốn nội bộ<\/b>: discount rate làm NPV của dự án bằng 0. Trong bài: không dùng IRR một mình khi so các dự án khác quy mô hoặc khác thời gian, vì IRR không cho biết tổng giá trị tạo ra.","aka":["Internal Rate of Return"],"full":"Internal Rate of Return","cs":true},{"t":"payback","vi":"<b>Thời gian hoàn vốn<\/b>: sau bao lâu tiền tiết kiệm/thu về bù đủ khoản đầu tư ban đầu. Trong bài: payback dễ hiểu nhưng bỏ qua dòng tiền sau mốc hoàn vốn và time value of money, nên cần xem thêm NPV/IRR.","aka":["payback period"]},{"t":"economics","vi":"<b>Kinh tế học<\/b> / khía cạnh kinh tế. Trong bài, economics trả lời câu hỏi “có đáng tiền không, chi phí nằm ở đâu theo vòng đời”, bổ sung cho câu hỏi kỹ thuật “chạy được không”."},{"t":"engineering economics","vi":"<b>Kinh tế kỹ thuật<\/b>: dùng con số (chi phí, dòng tiền, TCO, NPV, break-even…) để so sánh các phương án kỹ thuật. Trong bài là bộ công cụ giúp SA biến một tranh luận kiến trúc thành quyết định có căn cứ tài chính."},{"t":"industry","vi":"<b>Ngành<\/b> công nghiệp. Trong bài là ngành ô tô với toàn bộ hệ sinh thái: OEM, Tier 1, Tier 2, vendor phần mềm, nhà máy, after-sales và regulator.","aka":["industries"]},{"t":"automotive industry","vi":"<b>Ngành công nghiệp ô tô<\/b>: không chỉ các hãng xe mà cả chuỗi nhà cung cấp chip, phần mềm, linh kiện, nhà máy, đại lý/dịch vụ và cơ quan quản lý. Bài A.1 vẽ ai sở hữu gì, ai trả tiền và ai chịu rủi ro trong chuỗi này."},{"t":"recommendation","vi":"<b>Đề xuất<\/b> kỹ thuật gửi người duyệt. Trong bài, một recommendation tối thiểu cần: phương án so sánh, giả định, TCO, sensitivity, rủi ro, trade-off chấp nhận, owner và revisit condition.","aka":["recommendations"]},{"t":"recall","vi":"<b>Triệu hồi<\/b> xe: hãng xe gọi các xe bị lỗi (thường liên quan safety/compliance) về sửa, thường có sự giám sát của cơ quan quản lý. Trong bài: chi phí recall gồm sửa chữa, logistics, dealer, điều tra và uy tín; OTA có thể thay một phần recall vật lý.","aka":["recalls"]},{"t":"warranty","vi":"<b>Bảo hành<\/b>: cam kết sửa/thay miễn phí trong một thời hạn. Trong bài, chi phí warranty là một phần của expected failure cost; hãng xe phải trích khoản dự phòng bảo hành và tìm cách thu hồi một phần từ supplier.","aka":["warranties"]},{"t":"warranty reserve","vi":"<b>Khoản dự phòng bảo hành<\/b> trích trước trong báo cáo tài chính để chi cho bảo hành/sửa lỗi dự kiến. Lỗi phần mềm làm tăng khoản này dù chưa chi tiền thật.","aka":["warranty reserve/provision"]},{"t":"warranty investigation","vi":"<b>Điều tra bảo hành<\/b>: phân tích các ca bảo hành để tìm nguyên nhân, khoanh vùng xe bị ảnh hưởng và xác định ai chịu chi phí (OEM hay supplier)."},{"t":"warranty agreement","vi":"<b>Thỏa thuận bảo hành<\/b> giữa OEM và supplier: quy định ai trả chi phí khi linh kiện/phần mềm của supplier gây lỗi, giới hạn trách nhiệm và cách thu hồi tiền.","aka":["warranty agreements"]},{"t":"EOL","vi":"<b>Ngừng vòng đời<\/b>: thời điểm một linh kiện (ví dụ SoC) hoặc phần mềm ngừng được sản xuất/hỗ trợ. Trong bài: SoC báo EOL khi xe vẫn đang bán buộc OEM chuyển nền tảng, tốn chi phí lớn nếu phụ thuộc chặt một supplier.","full":"End of Life","cs":true},{"t":"EOL notice","vi":"<b>Thông báo ngừng sản xuất/hỗ trợ<\/b> mà supplier phải gửi trước một thời hạn. Điều khoản EOL notice sớm trong hợp đồng cho OEM thời gian chuẩn bị phương án thay thế.","cs":true},{"t":"end of life","vi":"<b>Cuối vòng đời<\/b>: giai đoạn sản phẩm/linh kiện ngừng sản xuất hoặc ngừng hỗ trợ. Trong bài là giai đoạn cuối của lifecycle, vẫn phát sinh chi phí (hỗ trợ, thay thế, chuyển đổi).","aka":["end-of-life"]},{"t":"end","vi":"<b>Kết thúc<\/b>, điểm cuối. Trong bài xuất hiện trong End of Life (cuối vòng đời) và end-of-line (trạm cuối dây chuyền sản xuất).","aka":["ends"]},{"t":"life","vi":"<b>Đời, vòng đời<\/b>. Trong bài dùng trong “End of Life” và ý vòng đời dài của xe: chi phí phải tính từ phát triển đến khi ngừng hỗ trợ."},{"t":"variance","vi":"<b>Chênh lệch<\/b> giữa số thực tế (actual) và ngân sách/dự báo (budget/forecast). Trong bài: variance chỉ có ý nghĩa khi tìm ra driver gây chênh (ví dụ thêm một thị trường làm tăng test).","aka":["variances"]},{"t":"variance analysis","vi":"<b>Phân tích chênh lệch<\/b>: tìm nguyên nhân vì sao actual khác budget/forecast và driver nào gây ra, để điều chỉnh dự báo và quyết định kịp thời."},{"t":"regulator","vi":"<b>Cơ quan quản lý<\/b> nhà nước: đặt quy định, phê duyệt cho phép bán xe (homologation) và có thể yêu cầu recall. Trong bài là một bên trong chuỗi giá trị, đặt ràng buộc cứng về safety/security.","aka":["regulators"]},{"t":"homologation","vi":"<b>Phê duyệt chứng nhận<\/b> cho phép một mẫu xe được bán tại một thị trường (gồm type approval và các quy định như UNECE R155/R156). Mốc homologation thường cố định, trượt sẽ gây cost of delay."},{"t":"value-chain","vi":"Thuộc <b>chuỗi giá trị<\/b> (dạng tính từ có gạch nối của value chain): các bên nối tiếp nhau tạo ra sản phẩm, từ chip đến khách hàng.","aka":["value-chains"]},{"t":"value-chain map","vi":"<b>Bản đồ chuỗi giá trị<\/b>: sơ đồ các bên (IP/chip, Tier 2, Tier 1, OEM, cloud/dealer, khách hàng/regulator) cùng ba dòng chảy value, money, risk, owner interface, liability và exit cost. Đây là sản phẩm của Assignment 1.","aka":["value chain map","value-chain maps"]},{"t":"value flow","vi":"<b>Dòng giá trị<\/b>: hướng sản phẩm/dịch vụ được tạo ra và chuyển đi, từ IP/chip → Tier 2 → Tier 1 → OEM → dealer → khách hàng.","aka":["value flows"]},{"t":"money flow","vi":"<b>Dòng tiền<\/b> trong chuỗi giá trị: đi ngược với value flow, từ khách hàng → OEM → Tier 1 → Tier 2, cộng thêm license, cloud fee, service revenue.","aka":["money flows"]},{"t":"risk flow","vi":"<b>Dòng rủi ro<\/b>: lỗi ở bất kỳ tầng nào trong chuỗi cuối cùng đều dồn về OEM (bên chịu trách nhiệm với khách hàng và regulator), rồi OEM mới đòi lại supplier theo hợp đồng.","aka":["risk flows"]},{"t":"three flows","vi":"<b>Ba dòng chảy<\/b> của chuỗi giá trị: value flow, money flow và risk flow. Bài yêu cầu vẽ đủ cả ba để thấy ai làm, ai trả tiền và ai chịu rủi ro."},{"t":"three","vi":"Số <b>ba<\/b>. Trong bài: “three flows” là ba dòng chảy value, money, risk của chuỗi giá trị."},{"t":"money","vi":"<b>Tiền<\/b>. Trong bài: money flow (dòng tiền trong chuỗi giá trị) và time value of money (giá trị thời gian của tiền)."},{"t":"time value of money","vi":"<b>Giá trị thời gian của tiền<\/b>: một đồng hôm nay đáng hơn một đồng sau vài năm vì có thể đem đầu tư/gửi lãi. Đây là lý do NPV chiết khấu dòng tiền tương lai, còn payback đơn giản thì bỏ qua."},{"t":"per-unit","vi":"<b>Tính trên mỗi đơn vị<\/b>, ở đây là mỗi xe. Chi phí per-unit lặp lại theo volume, nên chênh lệch nhỏ mỗi xe nhân với số xe và số năm có thể thành rất lớn.","aka":["per unit"]},{"t":"per-unit cost","vi":"<b>Chi phí trên mỗi xe<\/b>: giá SoC, RAM, màn hình, license theo xe… Ví dụ trong bài: SoC đắt hơn $15/xe × 300.000 xe/năm × 5 năm = $22.5M.","aka":["per-unit costs","per unit cost"]},{"t":"per-unit license","vi":"<b>License tính tiền theo từng xe<\/b> (ví dụ license OS mỗi ECU/xe), là một loại variable cost tăng theo volume.","aka":["per-unit licenses"]},{"t":"seat","vi":"Nghĩa đen là <b>chỗ ngồi<\/b>; trong license phần mềm, “per seat” là tính tiền theo <b>mỗi người dùng<\/b> (mỗi kỹ sư dùng công cụ), khác với per unit (theo mỗi xe).","aka":["seats","per seat"]},{"t":"BOM","vi":"<b>Danh sách và giá linh kiện<\/b> tạo nên một sản phẩm. Trong bài: chi phí BOM tính trên mỗi xe, nên chọn SoC/RAM dư sức (over-spec) làm tăng chi phí lặp lại theo volume.","aka":["Bill of Materials","BOMs"],"full":"Bill of Materials","cs":true},{"t":"forecast","vi":"<b>Dự báo<\/b> chi phí/doanh thu theo thời gian. Trong bài, forecast cần ghi initial investment, revenue/avoided cost, operating cost, maintenance, cost of delay và các kịch bản thấp/cơ sở/cao, và được cập nhật khi có dữ liệu mới.","aka":["forecasts","forecasting"]},{"t":"initial","vi":"<b>Ban đầu<\/b>. Trong bài: initial cost, initial engineering, initial investment — khoản bỏ ra lúc đầu, cần so cùng chi phí cả vòng đời chứ không xét riêng."},{"t":"initial cost","vi":"<b>Chi phí ban đầu<\/b>: tiền bỏ ra để làm/mua lúc đầu. Bài nhấn mạnh không chọn phương án chỉ vì initial cost thấp nhất mà phải xem lifecycle cost (TCO).","aka":["initial costs"]},{"t":"initial engineering","vi":"<b>Chi phí kỹ thuật ban đầu<\/b>: thiết kế, phát triển, prototype trước khi tích hợp — thành phần đầu tiên trong công thức TCO của bài."},{"t":"initial investment","vi":"<b>Khoản đầu tư ban đầu<\/b> (thường là dòng tiền âm tại t = 0) trong forecast/NPV, ví dụ $1.0M đầu tư tự động hóa test."},{"t":"EBITDA","vi":"<b>Lợi nhuận trước lãi vay, thuế, khấu hao và phân bổ<\/b>. Trong bài: EBITDA không đồng nghĩa với cash flow, nên không dùng nó thay dòng tiền khi thẩm định đầu tư.","full":"Earnings Before Interest, Taxes, Depreciation and Amortization","cs":true},{"t":"QCSS","vi":"Bốn yếu tố cần <b>cân bằng<\/b> trong dự án: chất lượng, chi phí, phạm vi, tiến độ. Trong bài: khóa ràng buộc cứng (safety, security, regulation) trước, rồi mới điều chỉnh scope/schedule/cost trong vùng được phép.","full":"Quality, Cost, Scope, Schedule","cs":true},{"t":"ROI","vi":"<b>Lợi nhuận trên vốn đầu tư<\/b>. Trong bài: ROI cao không bao giờ “bù” được việc bỏ qua một yêu cầu safety/security/regulation — economics chỉ chọn trong vùng được phép.","aka":["Return on Investment"],"full":"Return on Investment","cs":true},{"t":"OSS","vi":"<b>Phần mềm mã nguồn mở<\/b>. Trong bài: dùng OSS có thể giảm license và NRE nhưng OEM phải tự vá lỗi/bảo mật nhiều năm, nên chi phí maintenance phải được tính vào TCO.","aka":["Open Source Software"],"full":"Open Source Software","cs":true},{"t":"funding","vi":"<b>Nguồn kinh phí<\/b> được cấp. Trong bài: platform chung chỉ bền khi có owner và funding dài hạn, không phụ thuộc ngân sách của từng chương trình xe."},{"t":"gross","vi":"<b>Gộp<\/b> (chưa trừ các chi phí khác). Trong bài: gross profit (lợi nhuận gộp) và gross margin (tỷ suất lợi nhuận gộp)."},{"t":"gross profit","vi":"<b>Lợi nhuận gộp<\/b> = Revenue − Cost of goods sold (doanh thu trừ giá vốn hàng bán), một trong bốn chỉ số tài chính cơ bản của bài."},{"t":"gross margin","vi":"<b>Tỷ suất lợi nhuận gộp<\/b> = Gross profit / Revenue, tính theo %. Cho biết mỗi đồng doanh thu còn lại bao nhiêu sau giá vốn."},{"t":"profit","vi":"<b>Lợi nhuận<\/b>: phần còn lại sau khi trừ chi phí khỏi doanh thu. Trong bài xuất hiện trong gross profit.","aka":["profits"]},{"t":"revenue","vi":"<b>Doanh thu<\/b>: tiền thu được từ bán sản phẩm/dịch vụ. Trong bài: revenue từ bán xe, license, feature trả phí, service — là một loại lợi ích trong cost/benefit.","aka":["revenues"]},{"t":"service revenue","vi":"<b>Doanh thu dịch vụ<\/b> sau khi bán xe: gói kết nối, tính năng mở qua OTA, bảo dưỡng… Là phần money flow đến từ vận hành chứ không phải từ bán xe."},{"t":"cost of goods sold","vi":"<b>Giá vốn hàng bán<\/b>: chi phí trực tiếp để tạo ra sản phẩm đã bán (linh kiện, sản xuất…). Dùng để tính gross profit.","aka":["COGS"]},{"t":"SG&A","vi":"<b>Chi phí bán hàng, quản lý và hành chính<\/b> — các chi phí vận hành công ty không nằm trong giá vốn. Là một trong bốn chỉ số tài chính cơ bản của bài.","aka":["Selling, General & Administrative"],"full":"Selling, General and Administrative","cs":true},{"t":"selling","vi":"<b>Bán hàng<\/b>. Trong bài là chữ S trong SG&amp;A (Selling, General &amp; Administrative)."},{"t":"general","vi":"<b>Chung<\/b>. Trong bài là chữ G trong SG&amp;A: chi phí quản lý chung của công ty."},{"t":"administrative","vi":"<b>Hành chính<\/b>. Trong bài là chữ A trong SG&amp;A: chi phí hành chính."},{"t":"interest","vi":"<b>Lãi vay<\/b> (trong tài chính). Trong bài là một khoản được loại ra khi tính EBITDA."},{"t":"tax","vi":"<b>Thuế<\/b>. Trong bài là một khoản được loại ra khi tính EBITDA.","aka":["taxes"]},{"t":"depreciation","vi":"<b>Khấu hao<\/b> tài sản hữu hình (máy móc, HIL bench…): phân bổ giá trị tài sản dần theo năm sử dụng. Được loại ra khi tính EBITDA."},{"t":"amortization","vi":"<b>Phân bổ<\/b> giá trị tài sản vô hình (license, bản quyền, phần mềm phát triển…) theo thời gian. Được loại ra khi tính EBITDA.","aka":["amortisation"]},{"t":"financial","vi":"<b>Thuộc tài chính<\/b>. Trong bài: financial policy — quy định tài chính của tổ chức (discount rate, cách thẩm định đầu tư) cần xác minh với dự án."},{"t":"capital","vi":"<b>Vốn<\/b>. Trong bài: capital budgeting — thẩm định các khoản đầu tư dài hạn."},{"t":"capital budgeting","vi":"<b>Thẩm định đầu tư dài hạn<\/b>: đánh giá khoản đầu tư dựa trên dòng tiền theo thời gian, quy mọi khoản về cùng thời điểm (NPV, IRR, payback) thay vì cộng thẳng."},{"t":"discount","vi":"<b>Chiết khấu<\/b>: quy tiền tương lai về giá trị hôm nay. Trong bài: discount rate và lưu ý điểm cắt năm 4 của ví dụ X/Y là số chưa chiết khấu.","aka":["discounted"]},{"t":"discount rate","vi":"<b>Tỷ lệ chiết khấu<\/b> (r): mức lợi nhuận tối thiểu tổ chức đòi hỏi, dùng để quy dòng tiền tương lai về hiện tại khi tính NPV. Con số này do bộ phận tài chính quy định."},{"t":"CF_t","vi":"Ký hiệu <b>dòng tiền (Cash Flow) tại thời điểm t<\/b> trong công thức NPV = Σ CF_t / (1 + r)^t: âm khi chi, dương khi thu hoặc tiết kiệm.","aka":["CF"],"cs":true},{"t":"horizon","vi":"<b>Chân trời<\/b>, ở đây là khoảng thời gian xem xét. Trong bài: time horizon — số năm đưa vào tính toán chi phí/lợi ích.","aka":["horizons"]},{"t":"time horizon","vi":"<b>Khoảng thời gian xem xét<\/b> (số năm) khi so sánh phương án. Chọn time horizon khác nhau có thể đảo thứ hạng phương án, nên phải ghi rõ trong recommendation."},{"t":"return","vi":"<b>Lợi nhuận thu về<\/b> từ khoản đầu tư. Trong bài xuất hiện trong ROI (Return on Investment) và IRR (Internal Rate of Return).","aka":["returns"]},{"t":"investment","vi":"<b>Khoản đầu tư<\/b>: tiền bỏ ra hôm nay để có lợi ích sau này. Trong bài: initial investment, ROI và thẩm định đầu tư (capital budgeting).","aka":["investments"]},{"t":"dealer","vi":"<b>Đại lý<\/b> bán và bảo dưỡng xe. Trong bài, dealer/service network nằm cuối value flow, làm diagnostic, workshop update, xử lý warranty claim và recall.","aka":["dealers"]},{"t":"dealer network","vi":"<b>Mạng lưới đại lý/xưởng dịch vụ<\/b> của hãng xe, nơi xe được chẩn đoán, cập nhật phần mềm, sửa chữa và bảo hành.","aka":["dealer/service network","service network"]},{"t":"after-sales","vi":"<b>Dịch vụ sau bán hàng<\/b>: chẩn đoán, cập nhật phần mềm tại xưởng, phụ tùng, bảo hành. Trong bài là nơi phát sinh chi phí vận hành nhiều năm sau SOP.","aka":["after sales","aftersales"]},{"t":"spare","vi":"<b>Dự phòng, thay thế<\/b>. Trong bài: spare part — phụ tùng thay thế phải cung cấp nhiều năm sau khi ngừng sản xuất xe.","aka":["spares"]},{"t":"spare part","vi":"<b>Phụ tùng thay thế<\/b>. OEM phải duy trì spare part (kể cả ECU và phần mềm tương ứng) suốt giai đoạn service, kéo dài sau khi ngừng sản xuất xe.","aka":["spare parts"]},{"t":"workshop update","vi":"<b>Cập nhật phần mềm tại xưởng<\/b>: xe phải đến đại lý để nạp phần mềm mới. Chi phí cao hơn OTA vì tốn công, thời gian của khách và logistics.","aka":["workshop updates"]},{"t":"fee","vi":"<b>Phí<\/b> phải trả. Trong bài: cloud fee, license fee — các khoản trong money flow, thường lặp lại theo xe hoặc theo mức sử dụng.","aka":["fees"]},{"t":"cloud fee","vi":"<b>Phí dịch vụ cloud<\/b> (lưu trữ, tính toán, truyền dữ liệu) trả cho nhà cung cấp, thường tăng theo số xe kết nối và lượng dữ liệu — là variable cost.","aka":["cloud fees"]},{"t":"milestone","vi":"<b>Mốc<\/b> quan trọng trong kế hoạch dự án (integration, SOP, homologation…). Trong bài: milestone thường cố định theo sản xuất và marketing; trượt milestone tạo cost of delay.","aka":["milestones"]},{"t":"integration milestone","vi":"<b>Mốc tích hợp<\/b>: thời điểm các thành phần phải ghép lại và chạy cùng nhau. Giải pháp tối ưu nhưng không kịp integration milestone vẫn là giải pháp sai về product fit.","aka":["integration milestones"]},{"t":"cost of delay","vi":"<b>Chi phí của việc chậm trễ<\/b>: tiền/lợi ích mất đi khi một mốc (SOP, homologation, launch) bị trượt, ví dụ doanh thu mất, chi phí giữ team lâu hơn. Trong bài là khoản phải đưa vào so sánh phương án."},{"t":"notice","vi":"<b>Thông báo<\/b> chính thức. Trong bài: EOL notice — thông báo trước của supplier khi linh kiện/phần mềm sắp ngừng sản xuất/hỗ trợ.","aka":["notices"]},{"t":"fps","vi":"<b>Số khung hình mỗi giây<\/b>. Trong bài: cluster vẽ kim đồng hồ 120 fps “mượt như điện thoại” — ví dụ về over-spec, hay về kỹ thuật nhưng tăng chi phí mỗi xe.","full":"frames per second"},{"t":"compliance","vi":"<b>Tuân thủ<\/b> quy định, tiêu chuẩn, luật. Trong bài là một tiêu chí của product fit và là ràng buộc cứng không được đánh đổi lấy chi phí."},{"t":"regulatory compliance","vi":"<b>Tuân thủ quy định pháp lý<\/b> (ví dụ UNECE R155/R156, type approval). Là ràng buộc cứng: không thể bị “bù” bởi ROI cao."},{"t":"merit","vi":"<b>Giá trị, ưu điểm<\/b>. Trong bài: technical merit — độ hay về kỹ thuật của giải pháp.","aka":["merits"]},{"t":"technical merit","vi":"<b>Độ hay về kỹ thuật<\/b> của giải pháp (hiệu năng, sự thanh lịch…). Bài nhấn mạnh: giải pháp phải được đánh giá theo product fit, không chỉ technical merit."},{"t":"fit","vi":"<b>Sự phù hợp<\/b>. Trong bài: product fit — mức giải pháp hợp với sản phẩm thật (giá trị khách hàng, chi phí, tiến độ, tuân thủ).","aka":["fits"]},{"t":"product fit","vi":"<b>Mức phù hợp với sản phẩm<\/b>: giải pháp được đánh giá theo customer value, cost, schedule, compliance và maintainability, chứ không chỉ theo độ hay kỹ thuật."},{"t":"customer","vi":"<b>Khách hàng<\/b>: người mua/dùng xe (hoặc fleet operator). Trong bài: customer value và customer support là tiêu chí và chi phí cần tính.","aka":["customers"]},{"t":"customer value","vi":"<b>Giá trị mang lại cho khách hàng<\/b>: lợi ích khách thực sự cảm nhận và sẵn sàng trả tiền. Là tiêu chí đầu tiên của product fit và cơ sở ưu tiên feature khi phải cắt scope."},{"t":"manufacturing","vi":"<b>Sản xuất<\/b> tại nhà máy. Trong bài: manufacturing và end-of-line là nơi nạp phần mềm, calibration, variant coding — mỗi giây thêm ở trạm nhân với volume thành chi phí lớn."},{"t":"end-of-line","vi":"<b>Trạm cuối dây chuyền<\/b> sản xuất: nơi xe được flashing (nạp phần mềm), calibration và variant coding trước khi xuất xưởng. Thời gian và tỷ lệ lỗi ở đây là chi phí production theo từng xe.","aka":["end of line"]},{"t":"flashing","vi":"<b>Nạp phần mềm<\/b> vào bộ nhớ ECU. Trong bài: flashing ở end-of-line tốn thời gian trên mỗi xe; phần mềm lớn hơn có thể làm tăng thời gian trạm và chi phí sản xuất.","aka":["flash time"]},{"t":"yield","vi":"<b>Tỷ lệ đạt<\/b> (sản phẩm qua kiểm tra ngay lần đầu) trong sản xuất. Yield thấp nghĩa là nhiều xe/ECU phải làm lại, tăng production cost."},{"t":"rework","vi":"<b>Làm lại<\/b>: sửa/nạp lại sản phẩm chưa đạt ở nhà máy, hoặc sửa lại công việc đã làm. Trong bài là chi phí sản xuất đi kèm yield thấp."},{"t":"line","vi":"<b>Dây chuyền / dòng<\/b>. Trong bài: end-of-line (cuối dây chuyền sản xuất) và product line (dòng sản phẩm dùng chung platform)."},{"t":"product line","vi":"<b>Dòng sản phẩm<\/b>: chiến lược platform + product line dùng một core chung, tạo các variant bằng configuration thay vì sửa code cho từng xe.","aka":["product lines"]},{"t":"probability","vi":"<b>Xác suất<\/b>. Trong bài: probability of defect trong công thức Expected exposure = affected population × probability of defect × average response cost.","aka":["probabilities"]},{"t":"defect probability","vi":"<b>Xác suất xảy ra lỗi<\/b> trên mỗi xe/linh kiện. Là một giả định đưa vào expected exposure và sensitivity; thường cần dữ liệu defect history để xác minh.","aka":["probability of defect"]},{"t":"expected exposure","vi":"<b>Mức thiệt hại kỳ vọng<\/b> = số xe bị ảnh hưởng × xác suất lỗi × chi phí xử lý trung bình. Dùng để định lượng rủi ro thành tiền khi so sánh phương án."},{"t":"expected failure cost","vi":"<b>Chi phí lỗi kỳ vọng<\/b>: warranty, service campaign, recall, customer support và điều tra supplier dự kiến. Là một thành phần của TCO, không phải chi phí “có thể không xảy ra” rồi bỏ qua.","aka":["expected failure costs"]},{"t":"launch","vi":"<b>Ra mắt<\/b> sản phẩm/xe ra thị trường. Trong bài: launch date (ngày ra mắt) và launch delay (chậm ra mắt) là driver chi phí quan trọng.","aka":["launches"]},{"t":"launch delay","vi":"<b>Chậm ra mắt<\/b>: sản phẩm ra thị trường muộn hơn kế hoạch, gây cost of delay. Là một biến trong sensitivity analysis của bài.","aka":["launch delays"]},{"t":"launch date","vi":"<b>Ngày ra mắt<\/b> xe/feature. Là một driver của budget: dời launch date làm thay đổi chi phí team, test và doanh thu.","aka":["launch dates"]},{"t":"actual","vi":"<b>Số thực tế<\/b> đã chi/đã đạt. Trong bài: variance = actual − budget/forecast, ví dụ budget validation $1.0M nhưng actual giữa dự án đã $1.3M.","aka":["actuals"]},{"t":"total","vi":"<b>Tổng<\/b>. Trong bài: TCO (Total Cost of Ownership) — tổng chi phí sở hữu trong cả vòng đời."},{"t":"investigation","vi":"<b>Điều tra<\/b>, tìm nguyên nhân. Trong bài: warranty investigation, supplier investigation — chi phí điều tra lỗi là một phần của failure response.","aka":["investigations"]},{"t":"capacity","vi":"<b>Năng lực, công suất<\/b> (người, máy, bench). Trong bài: thêm nguồn lực chỉ hiệu quả khi bottleneck là capacity, không phải dependency hay quy trình."},{"t":"codebase","vi":"<b>Bộ mã nguồn<\/b> của một sản phẩm/phần mềm. Trong bài: phương án làm riêng cho mỗi chương trình phải duy trì 3 codebase, nên chi phí vá lỗi/bảo mật nhân ba.","aka":["codebases","code base"]},{"t":"liability","vi":"<b>Trách nhiệm pháp lý/tài chính<\/b> khi có lỗi: ai phải đền, trả chi phí recall, bồi thường. Trong bài: value-chain map phải ghi rõ liability của từng bên theo hợp đồng.","aka":["liabilities"]},{"t":"benefit","vi":"<b>Lợi ích<\/b>. Trong bài: cost/benefit — so chi phí với lợi ích (avoided cost, time-to-market, reuse, quality, revenue).","aka":["benefits"]},{"t":"avoided","vi":"<b>Tránh được<\/b>. Trong bài: avoided cost — chi phí lẽ ra phải trả nhưng tránh được nhờ phương án, được tính là lợi ích.","aka":["avoid"]},{"t":"avoided cost","vi":"<b>Chi phí tránh được<\/b>: ví dụ OTA thay recall vật lý, tự động hóa test giảm công test thủ công. Được tính như dòng tiền dương trong NPV.","aka":["avoided costs"]},{"t":"original equipment manufacturer","vi":"<b>Nhà sản xuất thiết bị gốc<\/b> — tên đầy đủ của OEM, trong ô tô nghĩa là <b>hãng xe<\/b>: sở hữu sản phẩm, tích hợp và chịu trách nhiệm cuối cùng với khách hàng và regulator.","aka":["original equipment manufacturers"]},{"t":"original","vi":"<b>Gốc, nguyên bản<\/b>. Trong bài nằm trong cụm Original Equipment Manufacturer (OEM)."},{"t":"equipment","vi":"<b>Thiết bị<\/b>. Trong bài nằm trong cụm Original Equipment Manufacturer (OEM)."},{"t":"manufacturer","vi":"<b>Nhà sản xuất<\/b>. Trong bài: Original Equipment Manufacturer (OEM) — hãng xe.","aka":["manufacturers"]},{"t":"ABS","vi":"<b>Hệ thống chống bó cứng phanh<\/b>. Trong bài, ECU phanh/ABS là nguồn tín hiệu tốc độ xe đi qua gateway đến cluster.","full":"Anti-lock Braking System","cs":true},{"t":"semiconductor","vi":"<b>Chất bán dẫn<\/b>, thường chỉ chip. Trong bài: Semiconductor/IP vendor là hãng chip ở đầu chuỗi giá trị, quyết định SoC, BSP, lead time và EOL.","aka":["semiconductors"]},{"t":"semiconductor shortage","vi":"<b>Khủng hoảng thiếu chip<\/b> (giai đoạn 2020–2022) khiến nhiều hãng xe phải giảm sản lượng. Là một case của Lesson 1, minh họa rủi ro phụ thuộc một nguồn cung."},{"t":"shortage","vi":"<b>Sự thiếu hụt<\/b> hàng/nguồn cung. Trong bài: semiconductor shortage — thiếu chip làm đình trệ sản xuất xe.","aka":["shortages"]},{"t":"UNECE","vi":"<b>Ủy ban Kinh tế châu Âu của Liên Hợp Quốc<\/b>, nơi ban hành các quy chuẩn kỹ thuật xe được nhiều thị trường áp dụng, như R155 (cybersecurity) và R156 (software update).","full":"United Nations Economic Commission for Europe","cs":true},{"t":"R155","vi":"Quy chuẩn UNECE về <b>an ninh mạng cho xe<\/b>: hãng xe phải có hệ thống quản lý cybersecurity (CSMS) để xe được phê duyệt bán ở thị trường áp dụng.","aka":["UNECE R155"],"full":"UN Regulation No. 155","cs":true},{"t":"R156","vi":"Quy chuẩn UNECE về <b>cập nhật phần mềm cho xe<\/b>: hãng xe phải có hệ thống quản lý software update (SUMS), áp dụng cho cả OTA.","aka":["UNECE R156"],"full":"UN Regulation No. 156","cs":true},{"t":"black-box","vi":"<b>Hộp đen<\/b>: thành phần chỉ biết đầu vào/đầu ra, không thấy bên trong. Trong bài: black-box binary từ supplier làm OEM khó sửa lỗi và khó thay supplier (exit cost cao).","aka":["black box"]},{"t":"black-box binary","vi":"<b>File chạy nhận từ supplier mà không có source code<\/b>. OEM không tự vá được, phụ thuộc supplier cho mọi bản sửa — nguyên nhân thường gặp của lock-in.","aka":["black-box binaries"]},{"t":"binary-only","vi":"<b>Chỉ giao file chạy<\/b>, không giao mã nguồn. Trong bài: hypervisor binary-only làm exit cost cao vì đổi supplier phải re-validate toàn bộ CDC.","aka":["binary only"]},{"t":"second","vi":"<b>Thứ hai<\/b> (hoặc <b>giây<\/b> khi nói thời gian). Trong bài: second source — nguồn cung thứ hai; và “mỗi giây flashing thêm ở trạm” trong sản xuất."},{"t":"second source","vi":"<b>Nguồn cung thứ hai<\/b> cho một linh kiện/thành phần quan trọng, để không bị kẹt khi supplier chính thiếu hàng, tăng giá hoặc báo EOL.","aka":["second sources","second-source"]},{"t":"escrow","vi":"<b>Ký quỹ/ký gửi<\/b>: source code được gửi cho bên thứ ba giữ, chỉ mở cho OEM khi supplier ngừng hỗ trợ hoặc phá sản. Là điều khoản hợp đồng giảm rủi ro phụ thuộc.","aka":["source code escrow"]},{"t":"demo","vi":"<b>Bản trình diễn<\/b> chạy thử. Trong bài: demo chạy đẹp và NRE đúng ngân sách chưa chứng minh phương án tốt nếu chi phí vòng đời chưa được tính.","aka":["demos"]},{"t":"variable","vi":"<b>Biến đổi, thay đổi được<\/b>. Trong bài: variable cost — chi phí tăng theo số xe hoặc mức sử dụng.","aka":["variables"]},{"t":"variable cost","vi":"<b>Chi phí biến đổi<\/b>: tăng theo số xe hoặc mức sử dụng, ví dụ license OS mỗi xe, cloud theo lượng dữ liệu. Khác NRE (trả một lần).","aka":["variable costs"]},{"t":"adaptation","vi":"<b>Điều chỉnh cho phù hợp<\/b>: công sửa phần mềm/platform để chạy được trên một chương trình xe, variant hay phần cứng mới. Là một thành phần trong công thức TCO của bài.","aka":["adaptations"]},{"t":"facelift","vi":"<b>Bản nâng cấp giữa đời<\/b> của một mẫu xe (đổi thiết kế, trang bị) trong giai đoạn sản xuất. Mỗi facelift có thể kéo theo thay đổi phần mềm và test lại.","aka":["facelifts"]},{"t":"trim","vi":"<b>Phiên bản trang bị<\/b> của một mẫu xe (bản tiêu chuẩn, cao cấp…). Mỗi trim là một variant làm tăng test matrix và configuration.","aka":["trims"]},{"t":"trim level","vi":"<b>Cấp phiên bản trang bị<\/b> của xe. Là một nguồn tạo variant, cùng với thị trường, ngôn ngữ, cấu hình phần cứng và powertrain.","aka":["trim levels"]},{"t":"powertrain","vi":"<b>Hệ truyền động<\/b>: động cơ/mô-tơ điện, hộp số và các bộ phận truyền lực. Loại powertrain (xăng, hybrid, điện) là một nguồn tạo variant phần mềm.","aka":["powertrains"]},{"t":"centralized","vi":"<b>Tập trung<\/b>: nhiều chức năng gom vào ít ECU/máy tính mạnh (như CDC). Lựa chọn centralized hay distributed ảnh hưởng wiring, BOM, số supplier và test matrix.","aka":["centralised","centralization"]},{"t":"distributed","vi":"<b>Phân tán<\/b>: chức năng chia ra nhiều ECU riêng. Ngược với centralized; mỗi kiểu có hệ quả chi phí khác nhau về BOM, wiring và tích hợp."},{"t":"provision","vi":"<b>Khoản dự phòng<\/b> trong kế toán: tiền trích trước cho nghĩa vụ dự kiến (ví dụ bảo hành). Trong bài: warranty reserve/provision.","aka":["provisions"]},{"t":"logistics","vi":"<b>Hậu cần<\/b>: vận chuyển, kho bãi, đưa xe/phụ tùng đến xưởng. Trong bài là một phần chi phí recall và campaign ngoài tiền sửa."},{"t":"separate","vi":"<b>Riêng rẽ<\/b>. Trong bài: Separate = 3.0n là chi phí khi mỗi chương trình tự làm riêng, so với Shared = 7.2 + 1.1n khi dùng platform chung.","aka":["separately"]},{"t":"marketing","vi":"<b>Tiếp thị<\/b>: quảng bá và kế hoạch đưa xe ra thị trường. Mốc marketing góp phần làm milestone ra mắt cố định, khó dời."},{"t":"cadence","vi":"<b>Nhịp đều đặn<\/b>. Trong bài: release cadence — nhịp phát hành định kỳ của platform.","aka":["cadences"]},{"t":"release cadence","vi":"<b>Nhịp phát hành<\/b> định kỳ (ví dụ mỗi quý) của platform chung, giúp các chương trình xe biết khi nào nhận tính năng/bản sửa — dấu hiệu platform có owner thực sự."},{"t":"per-program","vi":"<b>Theo từng chương trình xe<\/b>: chiến lược mỗi chương trình làm phần mềm riêng — nhanh lúc đầu nhưng chi phí lặp lại và maintenance phân tán.","aka":["per program"]},{"t":"carry-over","vi":"<b>Chuyển tiếp/dùng lại<\/b> phần mềm, phần cứng từ chương trình xe trước sang chương trình mới. Tiết kiệm lúc đầu nhưng dễ mang theo nợ kỹ thuật và giới hạn cũ.","aka":["carryover","carry over"]},{"t":"platform strategy","vi":"<b>Chiến lược nền tảng<\/b>: chọn per-program, carry-over, common platform hay platform + product line. Quyết định này đặt cấu trúc chi phí cho nhiều chương trình xe.","aka":["platform strategies"]},{"t":"common platform","vi":"<b>Nền tảng chung<\/b> cho nhiều chương trình xe: đầu tư ban đầu cao hơn nhưng giảm chi phí lặp lại; chỉ đáng khi đủ volume, có owner và governance.","aka":["common platforms"]},{"t":"shared core","vi":"<b>Phần lõi dùng chung<\/b> giữa các chương trình/variant; phần khác biệt nằm ở adapter hoặc configuration. Vá lỗi một lần cho mọi chương trình."},{"t":"platform core","vi":"<b>Lõi của platform<\/b>: phần chung mà mọi chương trình dùng, được platform team sở hữu và duy trì."},{"t":"vehicle program","vi":"<b>Chương trình xe<\/b>: dự án phát triển một mẫu xe/dòng xe cụ thể, có ngân sách và lịch SOP riêng. Trong bài, một service cần phục vụ ba vehicle programs.","aka":["vehicle programs"]},{"t":"must-have","vi":"<b>Bắt buộc phải có<\/b>. Trong bài: tách feature must-have tại SOP và feature có thể bổ sung sau qua OTA khi phải cắt scope để giữ mốc.","aka":["must have","must-haves"]},{"t":"theme","vi":"<b>Giao diện chủ đề<\/b> (màu sắc, kiểu hiển thị). Trong bài: tính năng “theme động” không liên quan safety nên có thể hoãn sang bản OTA sau SOP.","aka":["themes"]},{"t":"usage","vi":"<b>Mức sử dụng<\/b>. Trong bài: cloud usage — lượng dùng cloud là một driver của budget và variable cost.","aka":["usage data"]},{"t":"Takata","vi":"<b>Takata<\/b>: nhà cung cấp túi khí Nhật Bản có lỗi túi khí gây vụ recall lớn nhất lịch sử ngành ô tô và dẫn tới phá sản. Là case Lesson 1 về risk flow dồn về OEM và liability."},{"t":"CARIAD","vi":"<b>CARIAD<\/b>: công ty phần mềm của tập đoàn Volkswagen, gặp nhiều chậm trễ khi tự phát triển nền tảng phần mềm chung, làm trễ ra mắt một số mẫu xe. Là case Lesson 1 về cost of delay và rủi ro platform.","cs":true},{"t":"subsystem","vi":"<b>Hệ thống con<\/b>: một phần của hệ thống lớn (ví dụ hộp CDC, hệ phanh). Tier 1 thường cung cấp subsystem hoàn chỉnh cho OEM.","aka":["subsystems"]},{"t":"prototype","vi":"<b>Mẫu thử<\/b>: phiên bản sớm để thử nghiệm ý tưởng/thiết kế. Trong bài, chi phí prototype thuộc NRE.","aka":["prototypes","prototyping"]},{"t":"maintain","vi":"<b>Duy trì, bảo trì<\/b>: tiếp tục sửa lỗi, vá bảo mật, cập nhật. Platform được maintain nhiều năm nên chi phí patch/validation lặp lại phải đưa vào TCO.","aka":["maintained","maintaining","maintains"]},{"t":"data-model","vi":"<b>Mô hình dữ liệu<\/b> (dạng gạch nối của data model). Trong bài: data-model difference — khác biệt mô hình dữ liệu giữa các chương trình làm tăng chi phí adapter.","aka":["data-models"]},{"t":"difference","vi":"<b>Sự khác biệt, chênh lệch<\/b>. Trong bài: data-model difference, hoặc chênh lệch chi phí giữa hai phương án.","aka":["differences"]},{"t":"system-on-chip","vi":"<b>Hệ thống trên một chip<\/b> (viết tắt SoC): một chip tích hợp CPU, GPU, bộ nhớ, giao tiếp… Là bộ não của CDC; giá SoC là chi phí per-unit lớn.","aka":["system on chip"]},{"t":"reduction","vi":"<b>Sự giảm<\/b>. Trong bài: defect reduction — giảm số lỗi, một loại lợi ích cần định lượng.","aka":["reductions"]},{"t":"designed","vi":"<b>Được thiết kế<\/b>. Trong bài: “Responsibility is designed” — trách nhiệm là thứ được thiết kế có chủ đích (ai sở hữu interface nào), không tự nhiên mà có."},{"t":"quantify","vi":"<b>Định lượng<\/b>: biến một nhận định thành con số (chi phí, xác suất, ngưỡng). Là bước thứ ba của nhịp Frame → Map → Quantify → Compare → Decide → Learn.","aka":["quantified","quantifying"]},{"t":"decide","vi":"<b>Quyết định<\/b>. Là bước Decide trong nhịp Frame → Map → Quantify → Compare → Decide → Learn: chọn phương án, ghi trade-off chấp nhận và owner.","aka":["decides","decided"]},{"t":"learn","vi":"<b>Học hỏi, rút kinh nghiệm<\/b>. Là bước cuối Learn của judgment playbook: theo dõi kết quả thật, so với giả định và cập nhật quyết định khi chạm revisit condition.","aka":["learns","learned"]},{"t":"judgment","vi":"<b>Óc phán đoán<\/b>, khả năng ra quyết định khi thông tin chưa đủ. Trong bài: judgment playbook — quy trình sáu bước giúp ra quyết định kiến trúc có căn cứ.","aka":["judgement"]},{"t":"playbook","vi":"<b>Sổ tay quy trình<\/b>: các bước chuẩn để xử lý một loại tình huống. Trong bài: judgment playbook Frame → Map → Quantify → Compare → Decide → Learn.","aka":["playbooks"]},{"t":"judgment playbook","vi":"<b>Quy trình ra quyết định<\/b> của khóa học: Frame (đặt câu hỏi) → Map (vẽ các bên) → Quantify (định lượng) → Compare (so sánh) → Decide (quyết định) → Learn (rút kinh nghiệm)."},{"t":"supplier dependency","vi":"<b>Sự phụ thuộc vào nhà cung cấp<\/b>: OEM không tự sửa/thay được thành phần nếu thiếu supplier đó. Làm tăng rủi ro EOL, giá và exit cost.","aka":["supplier dependencies"]},{"t":"adapter cost","vi":"<b>Chi phí lớp adapter<\/b>: công viết và duy trì phần chuyển đổi giữa core chung và đặc thù từng chương trình/variant. Là biến quan trọng khi so platform chung với làm riêng.","aka":["adapter costs"]},{"t":"test matrix","vi":"<b>Ma trận kiểm thử<\/b>: tổ hợp các variant, thị trường, cấu hình phần cứng cần test. Mỗi variant thêm vào làm test matrix và chi phí validation tăng.","aka":["test matrices"]},{"t":"supplier claim","vi":"<b>Yêu cầu bồi hoàn từ nhà cung cấp<\/b>: OEM đòi supplier trả một phần chi phí bảo hành/recall khi lỗi do supplier gây ra, theo hợp đồng.","aka":["supplier claims"]},{"t":"supplier recovery","vi":"<b>Khoản thu hồi từ nhà cung cấp<\/b>: phần chi phí lỗi OEM lấy lại được từ supplier qua hợp đồng; thường chỉ một phần, phụ thuộc bằng chứng RCA."},{"t":"failure response","vi":"<b>Xử lý khi có lỗi<\/b> trên xe đã bán: RCA, điều tra, khoanh vùng xe bị ảnh hưởng, OTA/campaign/recall. Là một giai đoạn chi phí trong vòng đời.","aka":["defect response"]},{"t":"operating cost","vi":"<b>Chi phí vận hành<\/b> liên tục sau SOP: cloud, server OTA, hỗ trợ khách hàng… Là dòng tiền âm lặp lại trong forecast.","aka":["operating costs"]},{"t":"maintenance cost","vi":"<b>Chi phí bảo trì<\/b>: sửa lỗi, vá lỗ hổng, cập nhật OS/thư viện, ghép BSP mới và test lại trong suốt vòng đời phần mềm.","aka":["maintenance costs"]},{"t":"support cost","vi":"<b>Chi phí hỗ trợ<\/b>: hỗ trợ kỹ thuật cho chương trình xe, khách hàng hoặc xưởng dịch vụ. Là một biến của sensitivity analysis.","aka":["support costs"]},{"t":"production cost","vi":"<b>Chi phí sản xuất<\/b> trên mỗi xe: BOM, lắp ráp, thời gian flashing/calibration/variant coding ở end-of-line, per-unit license và yield/rework.","aka":["production costs"]},{"t":"fixed cost","vi":"<b>Chi phí cố định<\/b>: không đổi theo số xe trong một khoảng (team, công cụ, hạ tầng). Đối lập với variable cost.","aka":["fixed costs"]},{"t":"change impact","vi":"<b>Tác động của thay đổi<\/b>: một quyết định (đổi SoC, OS, partition) kéo theo những chi phí, rủi ro và bên liên quan nào. Bài yêu cầu lần theo từng change impact đến chi phí."},{"t":"engineering effort","vi":"<b>Công sức kỹ thuật<\/b> (số người × thời gian). Là một driver của budget: muốn dự báo chi phí phải ước lượng engineering effort."},{"t":"validation effort","vi":"<b>Công sức kiểm chứng<\/b>: thời gian/người/bench cần để test và chứng minh phần mềm đạt yêu cầu. Thường tăng theo test matrix và là biến của sensitivity."},{"t":"cost driver","vi":"<b>Yếu tố làm chi phí thay đổi<\/b> (số xe, số variant, số lần test, cloud usage…). Budget phải gắn với driver thì mới giải thích được variance.","aka":["cost drivers"]},{"t":"evidence plan","vi":"<b>Kế hoạch bằng chứng<\/b>: cách chứng minh các giả định của recommendation (dữ liệu dự án, đo đạc, PoC) và ai thu thập."},{"t":"business impact","vi":"<b>Tác động kinh doanh<\/b>: hệ quả của một quyết định kỹ thuật lên chi phí, doanh thu, tiến độ ra mắt và uy tín."},{"t":"financial policy","vi":"<b>Chính sách tài chính<\/b> của tổ chức: discount rate, cách tính khấu hao, ngưỡng phê duyệt đầu tư — phải xác minh với dự án thật, không tự giả định."},{"t":"software vendor","vi":"<b>Nhà cung cấp phần mềm<\/b> (OS, hypervisor, middleware, công cụ). Tạo chi phí license per unit/per seat và ảnh hưởng exit cost.","aka":["software vendors","software/tool vendor"]},{"t":"responsibility is designed","vi":"Nguyên tắc “<b>trách nhiệm được thiết kế<\/b>”: phải chủ động phân ai sở hữu interface, rủi ro, chi phí nào ngay từ kiến trúc, thay vì hỏi “lỗi của ai” sau khi sự cố xảy ra."},{"t":"NFR","vi":"Yêu cầu phi chức năng: hệ thống phải làm <b>tốt đến mức nào<\/b> (latency, độ ổn định, khởi động nhanh, an toàn…), khác với yêu cầu chức năng nói hệ thống làm gì. Trong bài, NFR phải viết định lượng, có ngưỡng và cách đo, vì nó là đầu vào trực tiếp của kiến trúc.","aka":["NFRs","F/NFR"],"full":"Non-Functional Requirement","cs":true},{"t":"non-functional requirement","vi":"Yêu cầu phi chức năng (viết tắt NFR): mô tả chất lượng của hành vi như tốc độ phản hồi, độ tin cậy, tài nguyên. Trong bài, NFR để “team tự hiểu” là nguồn gốc tranh cãi dev–tester; phải ghi rõ điều kiện, ngưỡng và cách chấm.","aka":["non-functional requirements"]},{"t":"CR","vi":"Yêu cầu thay đổi chính thức. Trong bài, mọi thay đổi sau baseline phải bắt đầu bằng CR ghi rõ reason, owner, component/variant bị ảnh hưởng, impact safety-cyber-quality, effort, regression test, approval và release target.","aka":["CRs","CR-xxx"],"full":"Change Request","cs":true},{"t":"orphan","vi":"Nghĩa đen: “mồ côi” — không có liên kết với thứ đáng ra phải nối tới. Trong traceability, đó là requirement không có test, hoặc test không gắn với requirement nào; cả hai đều là gap cần đánh dấu."},{"t":"orphan requirement","vi":"Requirement “mồ côi”: không có test case nào kiểm tra nó, tức chưa có cách chấm. Trong traceability matrix, đây là hàng thiếu cột test — dấu hiệu requirement có thể đã lọt khỏi verification.","aka":["orphan requirements"]},{"t":"orphan test","vi":"Test “mồ côi”: test không trace về requirement nào. Có thể là test thừa, test của requirement đã bị xóa, hoặc requirement bị thiếu trong spec; cần làm rõ thay vì cứ để chạy cho đủ số.","aka":["orphan tests"]},{"t":"gap","vi":"Khoảng trống, chỗ hở. Trong bài: chỗ sợi dây trace bị đứt (requirement không có test, test không có requirement, link trỏ version cũ) — phải được phát hiện và đánh dấu, không che đi.","aka":["gaps"]},{"t":"REQ-012","vi":"Mã requirement minh họa trong bài (REQ = requirement, số thứ tự). Mỗi requirement có ID ổn định, duy nhất để trace tới design, code, test. Ví dụ: REQ-012 là chime khi cửa mở và tốc độ &gt; 5 km/h; REQ-002 là NFR latency tốc độ.","aka":["REQ-001","REQ-002","REQ-003"],"cs":true},{"t":"TC-88","vi":"Mã test case minh họa (TC = test case). Trong bài, TC-88/TC-89 kiểm tra chime ở ngưỡng 5 km/h (thành vô hiệu khi ngưỡng đổi), TC-40 đo latency trên HIL. Test case phải trace về requirement và gắn baseline.","aka":["TC-89","TC-40","TC-88/TC-89"],"cs":true},{"t":"DS-4","vi":"Mã mục thiết kế minh họa (DS = design specification/design element). Trong bài, DS-4 là audio policy cho chime, DS-2 là vehicle-data service publish theo sự kiện; là mắt xích giữa requirement và code trong chuỗi trace.","aka":["DS-2"],"cs":true},{"t":"BL-1.8","vi":"Mã baseline minh họa (BL = baseline, số phiên bản). Bài học trong bài: test pass trên BL-1.7 không phải evidence cho bản release BL-1.8 đã đổi audio driver — kết quả test phải gắn đúng baseline sẽ release.","aka":["BL-1.7","BL-2.3","BL-x.y","BL-1.7/BL-1.8"],"cs":true},{"t":"ASPICE","vi":"Mô hình đánh giá <b>năng lực quy trình<\/b> phát triển phần mềm/hệ thống trong ngành ô tô. OEM thường yêu cầu supplier được assess theo ASPICE. Lưu ý: ASPICE chấm cách làm có nhất quán, có kiểm soát không — không chứng nhận sản phẩm hết lỗi.","aka":["SPICE"],"full":"Automotive SPICE (Software Process Improvement and Capability dEtermination)","cs":true},{"t":"process capability","vi":"Năng lực quy trình: tổ chức có làm việc nhất quán, có kế hoạch, có kiểm soát và lặp lại được hay không. Đây là thứ Automotive SPICE đánh giá ở supplier."},{"t":"finding","vi":"Phát hiện (trong review/audit): một vấn đề được ghi lại cần xử lý, thường có mức major/minor. Trong bài, review chỉ có giá trị khi finding được ghi, có owner và được đóng trước gate.","aka":["findings"]},{"t":"severity","vi":"Mức độ nghiêm trọng: <b>hậu quả<\/b> nếu lỗi xảy ra (ví dụ chime cảnh báo không kêu là severity cao). Khác priority — thứ tự xử lý, còn phụ thuộc khả năng xảy ra, phạm vi, workaround và lịch release."},{"t":"correction","vi":"Sửa chữa tận gốc: thay đổi loại bỏ nguyên nhân lỗi (sau khi tìm root cause), khác containment chỉ là biện pháp chặn tạm. Trong bài, defect chỉ đóng khi có correction và regression test chứng minh.","aka":["corrections"]},{"t":"V&V","vi":"Verification và validation: kiểm “làm đúng spec chưa” và “làm đúng thứ người dùng cần chưa”. Trong bài, V&amp;V là giai đoạn và gate (G4) trước release, dùng test report, coverage, scenario test trên HIL/xe.","aka":["verification/validation","Verification/Validation","Verification/validation"],"full":"Verification and Validation","cs":true},{"t":"person-day","vi":"Ngày công: khối lượng việc một người làm trong một ngày. Trong bài, đơn vị ước tính effort cho thay đổi speed_source: code chỉ khoảng 3 person-day, nhưng tính đủ requirement, design, test, evidence thì khoảng 16.","aka":["person-days"]},{"t":"tailoring","vi":"Điều chỉnh “may đo” mức độ quy trình theo rủi ro: thay đổi safety/security path cần review và test mạnh hơn thay đổi UI nhỏ. Tailoring phải có lý do ghi lại, không phải cắt bớt tùy ý.","aka":["tailor","tailored"]},{"t":"EU","vi":"Liên minh châu Âu; trong bài dùng làm tên <b>variant theo thị trường<\/b> (bản xe bán ở châu Âu). Thay đổi phải xét ảnh hưởng tới từng variant như EU và US.","full":"European Union","cs":true},{"t":"US","vi":"Hoa Kỳ; trong bài là tên variant theo thị trường Mỹ (ví dụ có thể hiển thị mph). Impact analysis phải trả lời thay đổi chạm variant EU, US hay cả hai.","full":"United States","cs":true},{"t":"UN R155/R156","vi":"Hai quy định của Liên Hợp Quốc (UNECE WP.29) cho xe: R155 về hệ thống quản lý an ninh mạng, R156 về hệ thống quản lý cập nhật phần mềm (gồm OTA). Trong bài là một nguồn yêu cầu evidence cùng với ASPICE, ISO 26262, ISO/SAE 21434.","aka":["UN R155","UN R156","UN"],"cs":true},{"t":"reason","vi":"Lý do. Trong CR là trường bắt buộc: vì sao cần thay đổi (ví dụ cluster cần biết tốc độ lấy từ nguồn nào), để người duyệt cân nhắc lợi ích với chi phí và rủi ro.","aka":["reasons"]},{"t":"PERT","vi":"Kỹ thuật ước tính ba điểm: E = (O + 4M + P) / 6, độ lệch ≈ (P − O) / 6, với O lạc quan, M có khả năng nhất, P bi quan. Trong bài dùng để ước tính thay đổi speed_source dưới dạng range thay vì một con số.","full":"Program Evaluation and Review Technique","cs":true},{"t":"three-point","vi":"Ước tính ba điểm: cho mỗi phần việc ba giá trị optimistic / most likely / pessimistic rồi tính kỳ vọng (thường bằng công thức PERT). Giúp thể hiện độ bất định thay vì báo một số đơn.","aka":["three-point estimate","three-point estimation"]},{"t":"optimistic","vi":"Lạc quan. Trong ước tính ba điểm là giá trị O — thời gian/effort nếu mọi thứ thuận lợi."},{"t":"likely","vi":"Có khả năng xảy ra nhất. Trong ước tính ba điểm là giá trị M — thời gian/effort trong điều kiện bình thường, được nhân trọng số 4 trong công thức PERT.","aka":["most likely"]},{"t":"pessimistic","vi":"Bi quan. Trong ước tính ba điểm là giá trị P — thời gian/effort nếu gặp trở ngại (supplier chậm, test bench chưa sẵn…); khoảng P − O cho biết độ bất định."},{"t":"backward-compatibility contract test","vi":"Contract test kiểm tra <b>tương thích ngược<\/b>: consumer cũ (ví dụ app IVI chưa cập nhật) vẫn chạy đúng và bỏ qua an toàn field mới. Trong bài là evidence bắt buộc khi thêm field speed_source vào interface.","aka":["backward-compatibility"]},{"t":"SILS","vi":"Test phần mềm chạy trong môi trường mô phỏng trên máy tính, không cần phần cứng thật. Trong bài, SILS rẻ và nhanh, hợp cho logic và regression, nhưng không chứng minh được timing phụ thuộc phần cứng.","full":"Software-in-the-Loop Simulation","cs":true},{"t":"HILS","vi":"Test với ECU/phần cứng thật nối vào môi trường mô phỏng xe (giống HIL). Trong bài, HILS dùng cho claim về timing và hành vi phụ thuộc phần cứng, như latency hiển thị tốc độ.","full":"Hardware-in-the-Loop Simulation","cs":true},{"t":"physical test","vi":"Test trên phần cứng/xe thật trong điều kiện thực. Trong bài, đây là mức đắt nhất, dùng cho gate cuối và validation, sau khi SILS/HILS đã lọc phần lớn lỗi.","aka":["physical"]},{"t":"reopen","vi":"Mở lại: một defect đã đóng nhưng phải mở lại vì sửa chưa đúng hoặc lỗi tái diễn.","aka":["reopened"]},{"t":"reopen rate","vi":"Tỷ lệ defect bị mở lại sau khi đã đóng. Trong bài là leading indicator cho chất lượng sửa lỗi và review: cao nghĩa là correction/regression test chưa đủ chặt."},{"t":"ignition","vi":"Khóa điện/bật máy xe (ignition on). Trong bài là mốc bắt đầu đo NFR: “sau khi bật ignition, cluster phải hiển thị tốc độ trong ≤ 2 s”."},{"t":"work","vi":"Công việc. Trong bài xuất hiện trong <i>work product<\/i> (sản phẩm công việc như tài liệu, kết quả phân tích) và <i>work breakdown<\/i> (chia nhỏ công việc để ước tính)."},{"t":"work product","vi":"Sản phẩm đầu ra của một hoạt động trong quy trình (spec, phân tích, report…). Trong bài: work product theo ISO 26262 / ISO/SAE 21434 là một phần của safety/security evidence trong release package.","aka":["work products"]},{"t":"work breakdown","vi":"Chia nhỏ công việc thành các phần nhỏ để ước tính từng phần rồi cộng lại. Trong bài là một trong ba cách ước tính effort, cùng analogy và three-point.","aka":["breakdown"]},{"t":"building the product right","vi":"“Làm sản phẩm cho đúng” — câu tóm tắt kinh điển của <b>verification<\/b>: kiểm sản phẩm khớp spec, design, interface contract hay chưa."},{"t":"building the right product","vi":"“Làm đúng sản phẩm cần làm” — câu tóm tắt kinh điển của <b>validation<\/b>: spec có thật sự đáp ứng nhu cầu và use case thật của người dùng hay không."},{"t":"documentation","vi":"Tài liệu, việc viết/cập nhật tài liệu. Trong bài, thay đổi như thêm field speed_source phải cập nhật cả trace, documentation và release note — không chỉ sửa code."},{"t":"leading indicator","vi":"Chỉ số dẫn trước: đo sớm, báo hiệu vấn đề <b>trước<\/b> khi lỗi lọt ra xe (ví dụ requirement/test coverage, reopen rate, build/test stability). Trái với chỉ số trễ như escaped defects chỉ biết sau sự cố.","aka":["leading indicators","leading"]},{"t":"indicator","vi":"Chỉ số, chỉ báo. Trong bài, mỗi indicator cần định nghĩa tử số, mẫu số, nguồn dữ liệu, thời điểm đo và quyết định mà nó phục vụ.","aka":["indicators"]},{"t":"escaped defect","vi":"Defect “lọt lưới”: lỗi không bị phát hiện trong quá trình phát triển và test, mà lộ ra sau release (trên xe khách hàng). Là chỉ số trễ; bài khuyên dashboard dựa thêm vào leading indicators.","aka":["escaped defects","escaped"]},{"t":"Val","vi":"Viết tắt của validation trong bảng so sánh (V = verification, Val = validation): kiểm spec có đúng nhu cầu thật, bằng scenario test trên HIL/xe, user/driver study, field trial.","full":"Validation","cs":true},{"t":"waterfall","vi":"Mô hình “thác nước”: làm tuần tự, xong hẳn bước này mới sang bước sau. Bài nhấn mạnh lifecycle và V-Model không bắt buộc waterfall — team vẫn làm iterative/sprint, miễn giữ quan hệ requirement ↔ verification."},{"t":"assess","vi":"Đánh giá (một cách chính thức). Trong bài: OEM yêu cầu supplier được assess theo Automotive SPICE để biết quy trình của họ có nhất quán, có kiểm soát.","aka":["assessed"]},{"t":"walkthrough","vi":"Dạng review mà tác giả dẫn người khác đi qua artifact để họ hiểu và góp ý. Nhẹ hơn inspection; hợp để chia sẻ thiết kế mới, onboarding.","aka":["walkthroughs","walk-through"]},{"t":"peer review","vi":"Review bởi đồng nghiệp cùng cấp: đọc thay đổi trước khi merge. Trong bài áp dụng cho mọi thay đổi code/config; với artifact rủi ro cao cần mức review mạnh hơn.","aka":["peer reviews"]},{"t":"peer","vi":"Đồng nghiệp cùng cấp/cùng chuyên môn. Trong bài xuất hiện trong <i>peer review<\/i> — đồng nghiệp đọc và góp ý thay đổi trước khi merge.","aka":["peers"]},{"t":"ReqIF","vi":"Định dạng chuẩn (dựa trên XML) để trao đổi requirement giữa các tool và công ty. Trong bài, OEM và supplier nên trao đổi bằng ReqIF có cấu trúc, gắn baseline, thay vì PDF/Excel thủ công làm đứt trace.","aka":["Requirements Interchange Format"],"full":"Requirements Interchange Format","cs":true},{"t":"interchange","vi":"Trao đổi qua lại (dữ liệu giữa các hệ thống). Trong bài xuất hiện trong ReqIF – Requirements Interchange Format."},{"t":"DIA","vi":"Thỏa thuận giao diện phát triển giữa OEM và supplier (khái niệm của ISO 26262): ai làm hoạt động nào, giao work product/evidence gì. Trong bài, DIA nên quy định cả trace link, test evidence và format trao đổi.","full":"Development Interface Agreement","cs":true},{"t":"development interface agreement","vi":"Tên đầy đủ của DIA: thỏa thuận phân chia trách nhiệm phát triển giữa OEM và supplier, ghi rõ bên nào giao gì (trace, evidence, format). Chốt từ đầu hợp đồng để trace không đứt ở ranh giới tổ chức."},{"t":"joint change board","vi":"Hội đồng duyệt thay đổi chung giữa OEM và supplier, họp định kỳ để xét CR, phát hiện trace gap và xung đột interface. Trong bài là biện pháp giữ traceability xuyên nhiều supplier.","aka":["change board","joint"]},{"t":"definition","vi":"Định nghĩa, mô tả xác định. Trong bài: <i>item/feature definition<\/i> — mô tả feature/hạng mục là gì, phạm vi và ranh giới, đầu ra của giai đoạn Concept.","aka":["definitions"]},{"t":"feasibility","vi":"Tính khả thi: có làm được với công nghệ, chi phí, thời gian hiện có không. Trong bài là một phần đánh giá sơ bộ ở giai đoạn Concept (cùng safety/security)."},{"t":"retirement","vi":"Ngừng sử dụng/ngừng hỗ trợ một phiên bản phần mềm hay sản phẩm. Trong bài là bước cuối lifecycle (Maintenance/Retirement); cần có retirement plan."},{"t":"tester","vi":"Người kiểm thử. Trong bài: dev nói “đã nhanh”, tester nói “còn chậm” — cả hai đúng theo cách hiểu riêng vì NFR không định lượng.","aka":["testers"]},{"t":"iterative","vi":"Lặp, làm theo từng vòng nhỏ (iteration/sprint) thay vì một lần tuần tự. Bài nhấn mạnh V-Model vẫn dùng được với cách làm iterative."},{"t":"mph","vi":"Dặm/giờ, đơn vị tốc độ dùng ở Mỹ, Anh. Trong bài: hàm chuyển đổi km/h – mph là ví dụ unit test (giá trị biên, giá trị lỗi).","full":"miles per hour"},{"t":"onboarding","vi":"Giúp người mới làm quen với dự án, hệ thống, quy trình. Trong bài, walkthrough là dạng review hữu ích cho onboarding."},{"t":"applicability","vi":"Phạm vi áp dụng. Trong bài: <i>variant applicability<\/i> — release/evidence áp dụng cho những variant nào, là một phần configuration evidence."},{"t":"known issues","vi":"Các lỗi/hạn chế đã biết nhưng chưa sửa tại thời điểm release, được ghi công khai trong release note kèm risk acceptance.","aka":["known issue","known"]},{"t":"representative environment","vi":"Môi trường đại diện cho điều kiện thực tế (HIL, xe thật, scenario sát thực tế). Trong bài, validation phải chạy trong representative environment mới có ý nghĩa.","aka":["representative"]},{"t":"study","vi":"Nghiên cứu, khảo sát. Trong bài: <i>user/driver study<\/i> — quan sát người dùng/tài xế thật dùng feature để validate nhu cầu.","aka":["studies"]},{"t":"field trial","vi":"Chạy thử ngoài thực địa: đưa feature lên xe chạy trong điều kiện thật với nhóm người dùng giới hạn. Là một phương pháp validation trong bài.","aka":["field trials","trial"]},{"t":"mock-up","vi":"Bản dựng giả lập giao diện/hình dạng (chưa có logic thật), dùng để lấy phản hồi sớm. Trong bài đi cùng prototype trong validation sớm.","aka":["mockup","mock-ups"]},{"t":"PDF","vi":"Định dạng tài liệu phổ biến. Trong bài, trao đổi requirement bằng PDF/Excel thủ công là nguyên nhân đứt trace giữa OEM và supplier.","full":"Portable Document Format","cs":true},{"t":"Excel","vi":"Phần mềm bảng tính của Microsoft. Trong bài là ví dụ cách trao đổi requirement thủ công, khó giữ ID, version và trace link so với ReqIF hay tool chuyên dụng."},{"t":"safety-cyber-quality impact","vi":"Ảnh hưởng của thay đổi tới an toàn (safety), an ninh mạng (cybersecurity) và chất lượng. Là trường bắt buộc trong CR để quyết định mức review và test.","aka":["safety-cyber-quality"]},{"t":"reject","vi":"Từ chối. Trong change control là một trong ba quyết định cho CR: approve / reject / defer.","aka":["rejects"]},{"t":"defer","vi":"Hoãn lại sang đợt/release sau. Trong change control là một quyết định hợp lệ cho CR khi lợi ích chưa đáng với rủi ro hiện tại.","aka":["deferred"]},{"t":"market","vi":"Thị trường (khu vực bán xe như EU, US). Trong bài, variant management kiểm soát khác biệt theo market, hardware và option.","aka":["markets"]},{"t":"CAPA","vi":"Hành động khắc phục và phòng ngừa: sửa nguyên nhân gốc của lỗi và ngăn lỗi tương tự lặp lại. Bài chỉ nhắc tới; RCA và CAPA được đào sâu ở B.5.","aka":["CAPAs"],"full":"Corrective and Preventive Action","cs":true},{"t":"analogy","vi":"Phép so sánh tương tự. Trong ước tính: dựa vào effort của việc tương tự đã làm để đoán việc mới."},{"t":"mean time to diagnose","vi":"Thời gian trung bình từ khi phát hiện sự cố đến khi tìm ra nguyên nhân. Trong bài là chỉ số cho biết traceability, log và tool có giúp chẩn đoán nhanh không.","aka":["mean"]},{"t":"diagnose","vi":"Chẩn đoán: tìm ra nguyên nhân của lỗi/sự cố.","aka":["diagnosed"]},{"t":"stability","vi":"Độ ổn định. Trong bài: <i>build/test stability<\/i> — build và test có cho kết quả ổn định, không chập chờn (flaky) không; là leading indicator."},{"t":"numerator","vi":"Tử số. Trong bài, mỗi metric phải nói rõ tử số (ví dụ số defect phát hiện sau release) để không ai hiểu khác."},{"t":"denominator","vi":"Mẫu số. Thiếu mẫu số thì “90% test pass” vô nghĩa vì không biết 90% của bao nhiêu test, test nào."},{"t":"tracker","vi":"Công cụ theo dõi (ví dụ defect tracker/issue tracker như Jira). Trong bài là nguồn dữ liệu cho metric như escape rate.","aka":["trackers"]},{"t":"defect tracker","vi":"Hệ thống ghi và theo dõi defect (trạng thái, severity, owner, version). Trong bài là nguồn dữ liệu chuẩn để tính metric defect."},{"t":"Impl","vi":"Viết tắt của implementation (hiện thực, viết code) trong sơ đồ lifecycle: [Design] → [Impl] → [Integration].","full":"Implementation","cs":true},{"t":"Tesla","vi":"Hãng xe điện Mỹ, nổi tiếng với việc cập nhật phần mềm xe qua OTA thường xuyên. Lesson 1 dùng case Tesla OTA để cho thấy lifecycle không dừng ở release."},{"t":"conditional","vi":"Có điều kiện. Trong bài là một outcome của gate: release có điều kiện (kèm hạn chế, risk acceptance, việc phải xong sau)."},{"t":"hold","vi":"Giữ lại, tạm dừng. Trong bài là outcome của gate: chưa cho đi tiếp/chưa release cho tới khi đủ evidence."},{"t":"status meeting","vi":"Cuộc họp báo cáo tình hình. Bài phân biệt: gate thật có entry criteria, evidence, người quyết có tên và outcome rõ; thiếu những thứ đó chỉ là status meeting.","aka":["meeting","meetings"]},{"t":"upstream","vi":"Dự án gốc mà mã nguồn được lấy về (thường là open source). Khi upstream ngừng hỗ trợ, OEM phải tự theo dõi CVE và vá lỗi cho thư viện đó."},{"t":"supplied part","vi":"Thành phần do bên ngoài cung cấp. Bài coi open source như một supplied part: cũng cần owner, version, SBOM, theo dõi lỗ hổng như phần của supplier.","aka":["supplied"]},{"t":"prevention asset","vi":"“Tài sản phòng ngừa”: bài học từ sự cố được biến thành thứ dùng lại (checklist, test, rule review) để lỗi tương tự không lặp lại — cốt lõi của closed-loop quality.","aka":["prevention"]},{"t":"safety path","vi":"Đường xử lý liên quan an toàn: chuỗi code/dữ liệu mà lỗi có thể gây nguy hiểm (ví dụ chime cảnh báo, hiển thị tốc độ). Trong bài, thay đổi chạm safety path cần review và test mạnh hơn, dù patch nhỏ.","aka":["safety paths"]},{"t":"release evidence package","vi":"Bộ bằng chứng nộp ở gate release: kết quả verification trên đúng baseline, validation, review record, defect status/risk acceptance, SBOM/scan, provenance, rollback plan, approval. Giúp người ký biết đã kiểm gì, trên version nào.","aka":["evidence package","evidence packages"]},{"t":"lifecycle diagram","vi":"Sơ đồ vòng đời: các giai đoạn, gate G0–G4, output và owner mỗi bước, điểm supplier tham gia và vòng change/defect sau release. Là một trong hai đầu ra của unit A.2.","aka":["lifecycle diagrams"]},{"t":"requirement ID","vi":"Mã định danh duy nhất của requirement (ví dụ REQ-012). Trong bài, ID phải ổn định qua OEM và mọi supplier, không đánh số lại, để trace không đứt.","aka":["requirement IDs","Req ID"]},{"t":"release target","vi":"Bản release dự kiến đưa thay đổi vào (ví dụ R2.1). Là trường trong CR giúp lập kế hoạch test và baseline.","aka":["release targets"]},{"t":"evidence link","vi":"Liên kết từ một dòng trace tới bằng chứng thật (test report, review record) gắn baseline. Trong bài, link chỉ để đủ audit mà không trỏ artifact thật là vô dụng.","aka":["evidence links"]},{"t":"defect management","vi":"Quản lý lỗi: ghi nhận, phân loại severity/priority, containment, tìm root cause, correction, regression test và đóng lỗi có evidence."},{"t":"defect record","vi":"Bản ghi một defect. Tối thiểu có severity, priority, cách tái hiện, affected version, containment, root cause, correction, regression test và evidence đóng lỗi.","aka":["defect records"]},{"t":"affected version","vi":"Phiên bản phần mềm bị lỗi ảnh hưởng — trường bắt buộc trong defect record để biết xe nào, baseline nào cần vá.","aka":["affected versions"]},{"t":"test spec","vi":"Đặc tả test: mô tả test kiểm gì, điều kiện, bước và tiêu chí pass. Trong bài là một artifact cũng phải được review.","aka":["test specification","test specs"]},{"t":"stakeholder need","vi":"Nhu cầu thật của các bên liên quan (người lái, OEM, cơ quan quản lý). Ở đỉnh V-Model, validation đối chiếu sản phẩm với stakeholder need.","aka":["stakeholder needs"]},{"t":"stakeholder acceptance","vi":"Sự chấp nhận chính thức của bên liên quan rằng sản phẩm đáp ứng nhu cầu; là một hình thức evidence của validation."},{"t":"scenario test","vi":"Test theo tình huống sử dụng thực tế (ví dụ cửa mở khi xe đang chạy). Trong bài là phương pháp validation trên HIL hoặc xe.","aka":["scenario tests"]},{"t":"safety requirement","vi":"Yêu cầu an toàn (thường suy ra từ phân tích theo ISO 26262). Là artifact rủi ro cao, cần dạng review chặt như inspection.","aka":["safety requirements"]},{"t":"test bench","vi":"Bàn/giàn test: hệ thống phần cứng + mô phỏng để chạy test (ví dụ HIL bench). Trong bài, test bench sẵn sàng là một assumption của ước tính.","aka":["test benches"]},{"t":"verification strategy","vi":"Chiến lược verification: chọn môi trường (SILS/HILS/physical) và phương pháp cho từng claim dựa trên evidence cần có, giới hạn timing và năng lực test."},{"t":"process governance","vi":"Quản trị quy trình: luật chơi về gate, review, evidence, quyền quyết. Bài nhấn mạnh governance phải phục vụ engineering (giảm rủi ro, giúp quyết định), không chỉ tạo thủ tục."},{"t":"build reproducible","vi":"Build tái lập được: dựng lại đúng binary của một baseline cũ (cùng source, toolchain, config). Trong bài là điều kiện để 5 năm sau SOP vẫn vá được BL-2.3."},{"t":"design decision","vi":"Quyết định thiết kế (chọn phương án nào, vì sao). Là output của giai đoạn Design, nên được ghi lại để trace và review.","aka":["design decisions"]},{"t":"code/config","vi":"Code và cấu hình (configuration) — hai thứ cùng quyết định hành vi phần mềm. Trong bài, đổi config cũng là thay đổi: phải qua review, trace tới requirement và test như đổi code (một cột riêng trong traceability matrix).","aka":["code / config"]},{"t":"unit/integration/system test","vi":"Ba mức test của nhánh phải V-Model: unit test (từng hàm/module), integration test (các thành phần ghép với nhau), system test (cả hệ thống so với system requirement). Trong bài là evidence của verification, phải pass trên đúng baseline.","aka":["unit/integration/system"]},{"t":"attacker","vi":"Kẻ tấn công: người/nhóm cố ý khai thác lỗ hổng để gây hại. Trong bài, khi threat modeling phải \"nghĩ như attacker\": họ ở đâu (xa qua internet, gần qua Bluetooth/Wi-Fi, chạm vật lý) và có năng lực gì.","aka":["attackers"]},{"t":"attack","vi":"Cuộc tấn công: hành động cố ý nhằm phá bí mật, toàn vẹn hay tính sẵn sàng của hệ thống. Trong bài dùng trong các cụm attack surface, attack feasibility — luôn xét attack đi vào từ entry point nào.","aka":["attacks"]},{"t":"attack surface","vi":"Bề mặt tấn công: tổng mọi \"cửa\" mà attacker có thể chạm tới — Wi-Fi, Bluetooth, USB, cổng diagnostic, kênh OTA, cloud API. Xe càng nhiều kết nối và app bên thứ ba thì attack surface càng lớn; tắt service/port không dùng là cách giảm nó.","aka":["attack surfaces"]},{"t":"surface","vi":"Bề mặt. Trong bài gần như luôn nằm trong cụm <i>attack surface<\/i> — tập hợp các điểm hệ thống có thể bị tấn công.","aka":["surfaces"]},{"t":"attack feasibility","vi":"Mức khả thi của tấn công: thực hiện tấn công dễ hay khó (cần thiết bị, kiến thức, thời gian, truy cập vật lý…). Trong TARA theo ISO/SAE 21434, risk được xếp hạng theo impact kết hợp attack feasibility."},{"t":"attacker capability","vi":"Năng lực của kẻ tấn công: ở xa qua internet, ở gần xe qua Bluetooth/Wi-Fi, hay có truy cập vật lý; có công cụ, kiến thức gì. Đây là một bước của threat modeling để biết threat nào thực tế.","aka":["attacker capabilities"]},{"t":"abuse case","vi":"Kịch bản lạm dụng: cách một chức năng hợp lệ bị dùng sai có chủ đích (ví dụ dùng remote unlock bằng tài khoản bị chiếm). Đối lập với use case; liệt kê abuse case giúp tìm threat khi threat modeling.","aka":["abuse cases"]},{"t":"abuse","vi":"Lạm dụng, dùng sai mục đích. Trong bài nằm trong cụm <i>abuse case<\/i> — kịch bản dùng sai chức năng có chủ đích để gây hại."},{"t":"hacker","vi":"Tin tặc: người xâm nhập hệ thống máy tính. Trong bài, \"hacker từ xa\" là ví dụ của <b>threat<\/b> (nguồn gây hại), khác với vulnerability (điểm yếu như service mở cổng không xác thực).","aka":["hackers"]},{"t":"TARA","vi":"Phân tích mối đe dọa và đánh giá rủi ro — phương pháp chính thức của automotive cybersecurity (mô tả trong ISO/SAE 21434): xác định asset, threat, đánh giá impact và attack feasibility rồi quyết định xử lý risk. STRIDE chỉ là công cụ hỗ trợ cho TARA.","aka":["Threat Analysis and Risk Assessment"],"full":"Threat Analysis and Risk Assessment","cs":true},{"t":"assessment","vi":"Sự đánh giá. Trong bài: <i>risk assessment<\/i> (đánh giá rủi ro) — chữ \"A\" trong TARA — và đánh giá supplier, đánh giá impact của một CVE.","aka":["assessments"]},{"t":"TARA/register","vi":"TARA và risk register (sổ rủi ro): hai tài liệu sống phải được review lại định kỳ và cập nhật khi có CVE, sự cố hay thay đổi kiến trúc.","aka":["TARA/risk register"]},{"t":"STRIDE","vi":"Checklist 6 nhóm threat (của Microsoft): Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege. Đi qua từng data flow cắt trust boundary với STRIDE giúp không bỏ sót loại tấn công; nó không thay TARA.","cs":true},{"t":"spoofing","vi":"Giả mạo danh tính (chữ S trong STRIDE): kẻ tấn công giả làm một bên đáng tin, ví dụ server giả mạo backend OEM. Control điển hình: authentication, certificate."},{"t":"tampering","vi":"Sửa trái phép dữ liệu/phần mềm (chữ T trong STRIDE), ví dụ sửa software image trước khi cài. Control điển hình: chữ ký số (signature) và integrity check."},{"t":"repudiation","vi":"Chối bỏ hành động (chữ R trong STRIDE): không chứng minh được ai đã làm gì, ví dụ ai đã gửi lệnh mở khóa từ xa. Control điển hình: audit log đáng tin, không sửa được."},{"t":"information disclosure","vi":"Lộ thông tin (chữ I trong STRIDE): dữ liệu đến tay người không được phép, ví dụ lịch sử vị trí lộ trong log. Control điển hình: encryption và access control."},{"t":"information","vi":"Thông tin. Trong bài xuất hiện trong <i>information disclosure<\/i> (lộ thông tin — một nhóm threat của STRIDE)."},{"t":"disclosure","vi":"Sự tiết lộ/công bố. Trong bài: <i>information disclosure<\/i> — dữ liệu bị lộ cho người không được phép (một nhóm của STRIDE)."},{"t":"denial of service","vi":"Từ chối dịch vụ (chữ D trong STRIDE): làm hệ thống gián đoạn, không phục vụ được, ví dụ gửi dồn dập message làm treo service hiển thị. Control điển hình: rate limit, isolation.","aka":["denial-of-service"]},{"t":"denial","vi":"Sự từ chối. Trong bài nằm trong cụm <i>denial of service<\/i> (DoS) — tấn công làm gián đoạn dịch vụ."},{"t":"DoS","vi":"Tấn công từ chối dịch vụ: làm treo hoặc quá tải service để nó không phục vụ được. Trên CDC, DoS vào chức năng hiển thị cảnh báo là vấn đề availability có liên quan safety.","aka":["Denial of Service","denial of service","denial-of-service"],"full":"Denial of Service","cs":true},{"t":"elevation of privilege","vi":"Leo thang quyền (chữ E trong STRIDE): kẻ tấn công có được quyền cao hơn mức cho phép, ví dụ app IVI lấy được quyền root. Control điển hình: authorization, least privilege, sandbox.","aka":["privilege escalation"]},{"t":"elevation","vi":"Sự nâng lên. Trong bài nằm trong <i>elevation of privilege<\/i> — leo thang quyền, một nhóm threat của STRIDE."},{"t":"privilege","vi":"Đặc quyền, quyền hạn mà một process/app/người dùng có trên hệ thống. Trong bài: <i>least privilege<\/i> (chỉ cấp quyền tối thiểu) và <i>elevation of privilege<\/i> (leo thang quyền).","aka":["privileges","privileged"]},{"t":"least privilege","vi":"Nguyên tắc đặc quyền tối thiểu: mỗi process, app, tài khoản chỉ được cấp đúng quyền cần để làm việc của nó. Nếu bị chiếm, thiệt hại bị giới hạn — ví dụ app media trên IVI không có quyền gửi lệnh xuống vehicle network."},{"t":"least","vi":"Ít nhất, tối thiểu. Trong bài chủ yếu trong cụm <i>least privilege<\/i> — chỉ cấp quyền tối thiểu cần thiết."},{"t":"authorization","vi":"Phân quyền: quyết định \"bạn được làm gì\" sau khi đã xác thực \"bạn là ai\" (authentication). Trên xe: authorization theo từng lệnh, ví dụ tài khoản nào được gửi remote unlock cho xe nào.","aka":["authorisation","authorize","authorized","unauthorized"]},{"t":"authorization/least privilege","vi":"Cặp control chống leo thang quyền (Elevation of privilege): kiểm tra quyền cho từng hành động (authorization) và chỉ cấp quyền tối thiểu (least privilege)."},{"t":"authentication/certificate","vi":"Control chống giả mạo (Spoofing): xác thực danh tính bằng certificate (chứng thư số) — ví dụ xe chỉ tin backend trình được certificate hợp lệ."},{"t":"access/authentication","vi":"Kiểm soát truy cập và xác thực cho diagnostic: chỉ tool/người đã được xác thực và có quyền mới được đọc/ghi memory, flash hay mở chức năng đặc biệt (security access).","aka":["security access/authentication"]},{"t":"mutual authentication","vi":"Xác thực hai chiều: cả hai bên (xe và backend) cùng kiểm tra danh tính của nhau, thường bằng certificate. Chống server giả mạo lẫn thiết bị giả gửi dữ liệu lên cloud.","aka":["mutual"]},{"t":"confidentiality","vi":"Tính bí mật (chữ C trong CIA): chỉ người được phép mới đọc được dữ liệu. Trong xe, confidentiality quan trọng với dữ liệu cá nhân và key; còn với lệnh điều khiển thì integrity/availability thường nặng hơn."},{"t":"CIA","vi":"Bộ ba thuộc tính bảo mật cơ bản: confidentiality (bí mật), integrity (toàn vẹn), availability (sẵn sàng). Thứ tự ưu tiên giữa ba thuộc tính phụ thuộc asset và use case; trong xe hay xét thêm authenticity.","aka":["CIA triad"],"full":"Confidentiality, Integrity, Availability","cs":true},{"t":"integrity/availability/confidentiality","vi":"Ba thuộc tính CIA viết theo thứ tự ưu tiên thường gặp cho service điều khiển trên xe: toàn vẹn và sẵn sàng thường nặng hơn bí mật.","aka":["integrity/availability"]},{"t":"authenticity","vi":"Tính xác thực nguồn gốc: chứng minh dữ liệu/phần mềm đúng là do bên đáng tin tạo ra, ví dụ firmware thật sự do OEM phát hành. Trong xe được nhắc riêng như thuộc tính thứ tư bên cạnh CIA."},{"t":"authenticity/signature","vi":"Bước kiểm tra trong chuỗi secure OTA: xe kiểm chữ ký số (signature) của gói update để chắc gói thật sự do OEM phát hành và không bị sửa."},{"t":"safety/availability","vi":"Safety và availability: security control (khóa tài khoản, kiểm chữ ký lâu) có thể làm giảm tính sẵn sàng hoặc tăng latency trên đường safety — xung đột phải cân nhắc khi đặt control."},{"t":"Bluetooth","vi":"Chuẩn kết nối không dây tầm ngắn (điện thoại, tai nghe). Trên CDC/IVI, Bluetooth là một entry point từ gần xe; lỗ hổng trong Bluetooth stack có thể là đường vào vehicle network nếu không có isolation."},{"t":"Bluetooth stack","vi":"Phần mềm hiện thực giao thức Bluetooth trên IVI (thường là thư viện của supplier/open-source). Là ví dụ điển hình trong bài: CVE trong Bluetooth stack chỉ ảnh hưởng variant có bật module đó."},{"t":"Wi-Fi","vi":"Mạng không dây cục bộ. Trên xe, Wi-Fi (hotspot, kết nối xưởng) là một entry point cho attacker ở gần xe, cần authentication và isolation.","aka":["WiFi","wifi"]},{"t":"Bluetooth/Wi-Fi","vi":"Các kênh kết nối tầm gần/vật lý (Bluetooth, Wi-Fi, USB) — entry point cho attacker đứng gần xe hoặc chạm được vào xe.","aka":["Bluetooth/Wi-Fi/USB"]},{"t":"USB","vi":"Cổng kết nối có dây phổ biến (cắm điện thoại, ổ nhớ). Trên xe, cổng USB là entry point vật lý: có thể bị dùng để nạp file độc hoặc flashing nếu không được khóa.","full":"Universal Serial Bus","cs":true},{"t":"USB/debug port","vi":"Cổng USB và cổng debug (JTAG, UART…) trên ECU: entry point vật lý có thể dùng để cài image giả. Ở xe production phải khóa debug interface.","aka":["USB/debug"]},{"t":"GPS","vi":"Hệ thống định vị vệ tinh cho biết vị trí xe. Trong bài, vị trí GPS của người dùng là dữ liệu cá nhân — asset cần bảo vệ confidentiality và privacy.","full":"Global Positioning System","cs":true},{"t":"internet","vi":"Mạng toàn cầu. Trong bài: attacker \"ở xa qua internet\" — loại nguy hiểm nhất vì có thể tấn công nhiều xe cùng lúc qua cloud/telematics."},{"t":"mobile app","vi":"Ứng dụng trên điện thoại của chủ xe (mở khóa từ xa, xem trạng thái xe). Là một entry point: nếu tài khoản app bị chiếm, kẻ gian có thể gửi lệnh hợp lệ tới xe.","aka":["mobile apps"]},{"t":"mobile","vi":"Di động. Trong bài: <i>mobile app<\/i> — ứng dụng điện thoại kết nối cloud để điều khiển/xem xe, một entry point cần authentication và authorization."},{"t":"remote","vi":"Từ xa, không cần có mặt tại xe. Trong bài: remote unlock, remote diagnostic, tấn công remote — kênh từ xa có quy mô ảnh hưởng cả fleet nên cần control mạnh."},{"t":"remote unlock","vi":"Mở khóa xe từ xa qua app/cloud. Ví dụ chính của bài về vehicle command: mã hóa thôi chưa đủ — cần authentication, authorization theo từng lệnh, chống replay và audit log."},{"t":"unlock","vi":"Mở khóa (cửa xe, hoặc mở khóa chức năng). Trong bài chủ yếu là <i>remote unlock<\/i> — lệnh mở khóa từ xa, asset cần bảo vệ integrity và authorization.","aka":["unlocking"]},{"t":"remote diagnostic","vi":"Chẩn đoán xe từ xa qua kết nối mạng thay vì cắm tool ở xưởng. Tiện cho OEM nhưng mở thêm attack surface quyền rất cao, cần security access và phân quyền.","aka":["remote diagnostics"]},{"t":"on-board","vi":"Trên xe, gắn trong xe. Trong bài: cổng diagnostic on-board (cổng OBD dưới táp-lô) — entry point vật lý có quyền cao."},{"t":"workshop tool","vi":"Thiết bị/phần mềm chẩn đoán dùng ở xưởng dịch vụ để đọc lỗi, flash ECU. Là entry point quyền cao; tool bị chiếm có thể downgrade hoặc mở khóa chức năng.","aka":["workshop tools"]},{"t":"downgrade","vi":"Hạ cấp phần mềm về bản cũ. Attacker có thể downgrade về bản có lỗ hổng đã biết; anti-rollback chặn mọi downgrade không được phép, khác với rollback do OEM kiểm soát.","aka":["downgrades","downgraded"]},{"t":"replay","vi":"Tấn công phát lại: bắt được một message hợp lệ (ví dụ lệnh mở khóa) rồi gửi lại sau đó. Chống bằng replay protection: nonce, bộ đếm hoặc timestamp trong message có xác thực.","aka":["replay attack","replays"]},{"t":"IDS","vi":"Hệ thống phát hiện xâm nhập: theo dõi traffic/hành vi trên xe (CAN, Ethernet, process) và cảnh báo khi có dấu hiệu tấn công. Không ngăn được, nhưng giúp \"biết khi có chuyện\" và gửi tín hiệu về SOC.","aka":["Intrusion Detection System"],"full":"Intrusion Detection System","cs":true},{"t":"intrusion","vi":"Sự xâm nhập trái phép vào hệ thống. Trong bài nằm trong cụm IDS — Intrusion Detection System, hệ thống phát hiện xâm nhập.","aka":["intrusions"]},{"t":"monitoring/IDS","vi":"Giám sát và IDS: một compensating control — tăng theo dõi để phát hiện hành vi khai thác đã biết khi chưa vá được lỗ hổng."},{"t":"encryption","vi":"Mã hóa: biến dữ liệu thành dạng không đọc được nếu không có key. Bảo vệ confidentiality; nhưng bài nhấn mạnh mã hóa <b>không thay<\/b> authentication, authorization hay chống replay.","aka":["encrypt","encrypted","encrypting"]},{"t":"encryption/access control","vi":"Cặp control chống lộ dữ liệu (Information disclosure): mã hóa dữ liệu và kiểm soát ai được truy cập."},{"t":"cryptographic","vi":"Thuộc về mật mã học. Trong bài: <i>cryptographic key<\/i> — khóa dùng để mã hóa, ký, xác thực; là asset quan trọng phải bảo vệ (thường trong HSM).","aka":["cryptography","crypto"]},{"t":"signature","vi":"Chữ ký số: dấu mật mã tạo bằng private key, cho phép kiểm tra dữ liệu đúng nguồn và không bị sửa. Trong bài: gói OTA và software image phải có signature, xe kiểm trước khi cài.","aka":["signatures"]},{"t":"signature verification","vi":"Kiểm tra chữ ký số: xe dùng public key tin cậy để xác minh gói update thật sự của OEM và nguyên vẹn. Một bước bắt buộc trong chuỗi secure OTA."},{"t":"signature/integrity check","vi":"Kiểm chữ ký và tính toàn vẹn trước khi cài/chạy — control chống Tampering (sửa software image).","aka":["signature/integrity"]},{"t":"signing","vi":"Ký số: dùng private key tạo chữ ký cho image/gói update. Trong bài: signing key phải được bảo vệ trong HSM — lộ key ký là có thể phát hành update giả cho cả fleet.","aka":["sign","signs"]},{"t":"signing key","vi":"Khóa dùng để ký software/gói update. Là asset giá trị nhất: phải nằm trong HSM hoặc hệ thống tương đương, có quy trình rotate/revoke.","aka":["signing keys"]},{"t":"signed","vi":"Đã được ký số. <i>Signed update<\/i> là gói cập nhật có chữ ký của OEM; xe chỉ cài khi chữ ký hợp lệ — nền tảng của secure OTA.","aka":["signed update","signed updates"]},{"t":"hash","vi":"Giá trị băm: \"dấu vân tay\" ngắn tính từ nội dung file; sửa một bit là hash đổi. Manifest của gói OTA ghi hash từng file để xe kiểm tra tính toàn vẹn.","aka":["hashes"]},{"t":"HSM","vi":"Module phần cứng chuyên lưu và dùng key an toàn: key không bao giờ ra ngoài dạng đọc được. Trong bài, signing key của pipeline build phải nằm trong HSM; trên ECU cũng có HSM cho secure boot.","aka":["Hardware Security Module"],"full":"Hardware Security Module","cs":true},{"t":"key/certificate","vi":"Khóa mật mã và chứng thư số (certificate) — asset quan trọng của xe kết nối. Phải bảo vệ confidentiality/integrity và quản lý suốt vòng đời: tạo, lưu, rotate, revoke.","aka":["key/certificates"]},{"t":"key/certificate lifecycle","vi":"Vòng đời khóa và chứng thư: tạo, lưu an toàn, xoay vòng (rotate), thu hồi (revoke), hết hạn. Xe sống 10–15 năm nên đây là việc của bảo trì dài hạn, không chỉ lúc phát triển."},{"t":"certificate/credential","vi":"Chứng thư số và thông tin xác thực của xe. Khi kết thúc hỗ trợ hoặc thải bỏ xe, phải thu hồi chúng để xe/kẻ khác không dùng được kết nối với backend."},{"t":"credential","vi":"Thông tin xác thực (mật khẩu, token, key, certificate) chứng minh danh tính. Credential bị lộ cho phép kẻ gian giả làm bên hợp lệ — là asset cần bảo vệ.","aka":["credentials"]},{"t":"cert","vi":"Viết tắt thông dụng của certificate — chứng thư số. Trong bài: \"cert hết hạn\" là một rủi ro bảo trì dài hạn, có thể làm kết nối/update thất bại hàng loạt.","aka":["certs"]},{"t":"rotate","vi":"Xoay vòng key: thay key/certificate bằng cái mới theo định kỳ hoặc khi nghi bị lộ. Trong bài là một bước của key/certificate lifecycle và của eradication khi có sự cố.","aka":["rotation","rotated","rotating"]},{"t":"revoke","vi":"Thu hồi: tuyên bố một key/certificate không còn hợp lệ trước hạn (vì bị lộ, xe thải bỏ). Backend có thể revoke certificate để chặn kẻ tấn công trong containment.","aka":["revoked","revocation"]},{"t":"rotate/revoke","vi":"Xoay vòng hoặc thu hồi key/certificate — hai thao tác bảo trì phải làm được suốt 10–15 năm đời xe."},{"t":"segmentation","vi":"Phân đoạn: chia mạng/hệ thống thành vùng tách biệt. Trong bài: <i>network segmentation<\/i> giữ lỗi hay tấn công ở IVI không lan sang vehicle network/cluster."},{"t":"network segmentation","vi":"Phân vùng mạng: chia mạng trong xe thành các domain có mức tin cậy khác nhau, giao tiếp qua gateway có kiểm tra. Giảm lan rộng khi một vùng bị chiếm; là lớp quan trọng của defense in depth."},{"t":"segmentation/isolation","vi":"Phân vùng mạng và cô lập: chia mạng/miền để lỗi hoặc tấn công ở một vùng không lan sang vùng khác.","aka":["network segmentation/isolation"]},{"t":"sandbox","vi":"Hộp cát: môi trường chạy bị giới hạn quyền, app bên trong chỉ thấy/làm được những gì cho phép. Trong bài, app bên thứ ba trên IVI chạy trong sandbox để nếu bị khai thác cũng không chạm vehicle network.","aka":["sandboxes","sandboxed","sandboxing"]},{"t":"sandbox/isolation","vi":"Chạy app trong sandbox và cô lập khỏi phần còn lại — control cho third-party component/app."},{"t":"rate limit/isolation","vi":"Control chống Denial of service: giới hạn tần suất message (rate limit) và cô lập service để quá tải không lan sang chức năng khác.","aka":["limit/isolation"]},{"t":"proxy","vi":"Thành phần trung gian đứng giữa hai bên để chuyển tiếp và kiểm tra message. Trong bài: đặt proxy kiểm tra message trước component cũ là một cách cô lập (compensating control).","aka":["proxies"]},{"t":"allow-list","vi":"Danh sách cho phép: chỉ chấp nhận những gì đã biết là hợp lệ, mọi thứ khác bị chặn. Trong bài là cách lọc ở biên cho component không update được.","aka":["allow list","whitelist"]},{"t":"gateway/firewall","vi":"Gateway (cổng nối các mạng trong xe) và firewall (tường lửa lọc traffic): nơi chặn đường tiếp cận tới component có lỗ hổng như một compensating control."},{"t":"firewall","vi":"Tường lửa: thành phần lọc traffic mạng theo luật cho phép/chặn. Trên xe thường nằm trong gateway để ngăn traffic lạ đi giữa các domain.","aka":["firewalls"]},{"t":"hypervisor/container","vi":"Hai cơ chế cô lập: hypervisor tách các VM, container tách các process/app. Đặt component có lỗ hổng sau lớp này để giới hạn thiệt hại."},{"t":"container","vi":"Gói chạy ứng dụng cô lập cùng thư viện của nó, chia sẻ kernel với hệ điều hành chủ. Trong bài là một lớp isolation cho component/app.","aka":["containers","containerized"]},{"t":"endpoint","vi":"Điểm cuối dịch vụ: một địa chỉ API trên backend mà xe/app gọi tới. Trong incident response, chặn endpoint bị lợi dụng là cách khoanh vùng nhanh từ phía cloud.","aka":["endpoints"]},{"t":"service/port","vi":"Service mạng và cổng (port) nó lắng nghe. Tắt service/port không dùng là cách cơ bản để giảm attack surface.","aka":["service/ports"]},{"t":"debug interface","vi":"Giao diện gỡ lỗi phần cứng/phần mềm (JTAG, UART, shell) dùng trong phát triển. Ở xe production phải khóa hoặc bảo vệ, vì nó cho quyền rất cao.","aka":["debug interfaces"]},{"t":"fuzzing","vi":"Kiểm thử bằng cách gửi dữ liệu ngẫu nhiên/méo mó vào interface để tìm lỗi crash hoặc lỗ hổng. Trong bài dùng cho interface nhận dữ liệu từ bên ngoài (Bluetooth, network, file media).","aka":["fuzz","fuzz testing","fuzzer"]},{"t":"SAST","vi":"Phân tích tĩnh mã nguồn để tìm lỗi bảo mật mà không cần chạy chương trình. Là một khâu của secure development, thường chạy tự động trong pipeline CI.","aka":["Static Application Security Testing"],"full":"Static Application Security Testing","cs":true},{"t":"MISRA/CERT","vi":"Hai bộ quy tắc viết code an toàn: MISRA (cho C/C++ trong ô tô, nhấn mạnh safety) và SEI CERT (secure coding). Chọn tùy ngôn ngữ, dùng làm coding guideline của secure development.","cs":true},{"t":"secure development","vi":"Phát triển an toàn: các thực hành trong lúc viết code — coding guideline (MISRA/CERT), code review có checklist security, SAST, dependency/SBOM scan, fuzzing."},{"t":"secure design","vi":"Thiết kế an toàn: security requirement rút ra từ TARA, trust boundary rõ, giảm attack surface, tách domain, least privilege, fail-safe — quyết định ở mức kiến trúc trước khi code."},{"t":"security by design","vi":"Bảo mật từ thiết kế: xem threat và control ngay từ requirement/architecture, không đợi cuối mới thêm. Lý do: có những control (HSM, segmentation, secure boot) chỉ thêm được khi chọn phần cứng/kiến trúc."},{"t":"secure diagnostics","vi":"Chẩn đoán an toàn: diagnostic có xác thực (security access), phân quyền theo vai trò và log — vì cổng diagnostic cho quyền đọc/ghi memory và flash ECU."},{"t":"dependency/SBOM scan","vi":"Quét các thư viện phụ thuộc dựa trên SBOM để phát hiện component có CVE đã biết — khâu tự động trong pipeline.","aka":["dependency/SBOM"]},{"t":"mechanism","vi":"Cơ chế. Trong bài: <i>safety mechanism<\/i> (fallback mode, diagnostic…) có thể vô tình mở thêm attack surface; và cơ chế update/rollback cần cho bảo trì.","aka":["mechanisms"]},{"t":"safety mechanism","vi":"Cơ chế an toàn chức năng giúp phát hiện/xử lý lỗi (fallback mode, diagnostic, watchdog). Bài lưu ý chúng có thể mở thêm attack surface — cần cyber và safety cùng xét.","aka":["safety mechanisms"]},{"t":"fail safe","vi":"An toàn khi lỗi: khi control hoặc chức năng hỏng thì hệ thống về trạng thái an toàn hoặc degrade có kiểm soát, thay vì làm mất chức năng quan trọng (ví dụ cảnh báo vẫn hiển thị)."},{"t":"safe","vi":"An toàn. Trong bài nằm trong cụm <i>fail safe / fail-safe<\/i> — khi có lỗi thì chuyển về trạng thái an toàn.","aka":["safe state"]},{"t":"hazard","vi":"Mối nguy có thể gây hại cho người (theo functional safety ISO 26262). Trong bài: tấn công mạng có thể kích hoạt hazard, nên team cyber và safety phải trao đổi.","aka":["hazards"]},{"t":"trust","vi":"Tin cậy. Trong bài chủ yếu trong <i>trust boundary<\/i> — ranh giới giữa vùng ít tin cậy và vùng tin cậy hơn, nơi phải kiểm tra xác thực và phân quyền.","aka":["untrusted"]},{"t":"system context","vi":"Bối cảnh hệ thống: sơ đồ hệ thống đang phân tích cùng mọi thứ bên ngoài nó tương tác (cloud, app, người dùng, ECU khác). Là bước đầu của threat modeling để thấy trust boundary và entry point."},{"t":"software image","vi":"Bản phần mềm hoàn chỉnh (file nhị phân) được cài lên ECU. Là asset cần bảo vệ integrity và authenticity: chỉ cài/chạy image có chữ ký hợp lệ.","aka":["software images","firmware/software image"]},{"t":"firmware","vi":"Phần mềm nhúng chạy sát phần cứng của ECU/thiết bị. Trong bài: authenticity — xác minh firmware thật sự do OEM phát hành trước khi cài."},{"t":"firmware/software","vi":"Firmware hoặc software — cách gọi chung phần mềm cài lên ECU; trong bài là \"firmware/software image\", một asset cần integrity và authenticity."},{"t":"command/service","vi":"Lệnh và service điều khiển xe (remote unlock, gửi lệnh xuống domain khác). Asset cần integrity, authorization và availability hơn là confidentiality.","aka":["vehicle command/service"]},{"t":"diagnostic/update","vi":"Service chẩn đoán và cập nhật phần mềm — asset quyền cao; bị lợi dụng có thể mở khóa chức năng hoặc downgrade software.","aka":["diagnostic/update service"]},{"t":"third-party","vi":"Bên thứ ba: không phải OEM tự viết — OSS, SDK, app, binary của supplier. Third-party component kế thừa lỗ hổng mà OEM không viết và phụ thuộc lịch vá của bên khác.","aka":["third party"]},{"t":"third-party component","vi":"Thành phần do bên khác cung cấp (OSS, SDK, app, binary supplier). Cần SBOM, vulnerability monitoring, SLA vá lỗi và sandbox — một trong bốn \"cửa\" chính của xe kết nối.","aka":["third-party components"]},{"t":"SDK","vi":"Bộ công cụ phát triển phần mềm (thư viện, header, tool) do supplier/vendor cung cấp. Là third-party component: có lỗ hổng và hạn hỗ trợ riêng phải theo dõi.","aka":["SDKs"],"full":"Software Development Kit","cs":true},{"t":"advisory","vi":"Bản thông báo bảo mật do dự án OSS, vendor hoặc PSIRT phát hành, mô tả lỗ hổng, phiên bản ảnh hưởng và cách khắc phục. Là nguồn tin đầu vào của vulnerability monitoring.","aka":["advisories","security advisory","security advisories"]},{"t":"PSIRT","vi":"Đội xử lý sự cố bảo mật sản phẩm của một công ty (supplier, chip vendor, OEM): nhận báo lỗ hổng, phân tích và phát hành advisory/bản vá. Thông báo PSIRT của supplier là nguồn tin CVE.","aka":["Product Security Incident Response Team"],"full":"Product Security Incident Response Team","cs":true},{"t":"supplier/chip vendor","vi":"Supplier phần mềm/ECU hoặc hãng chip (SoC). PSIRT của họ thông báo lỗ hổng trong BSP, driver, firmware mà OEM phải theo dõi.","aka":["supplier/chip"]},{"t":"researcher","vi":"Nhà nghiên cứu bảo mật độc lập tìm và báo lỗ hổng. Báo cáo của security researcher là một nguồn tin; OEM cần kênh tiếp nhận và quy trình phản hồi.","aka":["researchers","security researcher","security researchers"]},{"t":"NVD","vi":"Cơ sở dữ liệu lỗ hổng quốc gia của Mỹ (NIST): bổ sung thông tin cho từng CVE như điểm CVSS, phiên bản ảnh hưởng. Là nguồn tin chính để đối chiếu với SBOM.","aka":["National Vulnerability Database"],"full":"National Vulnerability Database","cs":true},{"t":"CVE/NVD","vi":"Nguồn tin lỗ hổng công khai: danh mục CVE và cơ sở dữ liệu NVD — đầu vào của vulnerability monitoring để đối chiếu với SBOM."},{"t":"national","vi":"Quốc gia. Trong bài nằm trong tên NVD — National Vulnerability Database, cơ sở dữ liệu lỗ hổng quốc gia (Mỹ)."},{"t":"database","vi":"Cơ sở dữ liệu. Trong bài: vulnerability database (như NVD) — kho thông tin lỗ hổng đã công bố mà monitoring đối chiếu với SBOM.","aka":["databases","vulnerability database","vulnerability databases"]},{"t":"Common Vulnerabilities and Exposures","vi":"Tên đầy đủ của CVE: hệ thống mã định danh công khai cho lỗ hổng (CVE-năm-số). Mã CVE chỉ cho biết lỗ hổng tồn tại, chưa nói gì về mức ảnh hưởng trên xe của mình."},{"t":"exposures","vi":"Các điểm phơi nhiễm/lộ ra. Trong bài nằm trong tên CVE — Common Vulnerabilities and Exposures."},{"t":"CVSS","vi":"Thang điểm 0–10 mô tả mức nghiêm trọng <b>chung<\/b> của lỗ hổng. Bài nhấn mạnh: CVSS cao chưa chắc nặng trên xe mình — triage phải xét component có trong build không, có expose không, xe nào bị ảnh hưởng.","aka":["Common Vulnerability Scoring System"],"full":"Common Vulnerability Scoring System","cs":true},{"t":"scoring","vi":"Việc chấm điểm. Trong bài nằm trong CVSS — Common Vulnerability Scoring System, hệ thống chấm điểm mức nghiêm trọng lỗ hổng."},{"t":"VEX","vi":"Tuyên bố chuẩn hóa sản phẩm có bị ảnh hưởng bởi một lỗ hổng hay không (ví dụ \"không bị ảnh hưởng vì module không bật\"). Ghi VEX để khỏi triage lại và làm evidence cho audit.","aka":["VEX statement","VEX statements","Vulnerability Exploitability eXchange"],"full":"Vulnerability Exploitability eXchange","cs":true},{"t":"exploitability","vi":"Khả năng bị khai thác: lỗ hổng có thực sự bị tấn công được trong sản phẩm cụ thể không. Trong bài nằm trong tên VEX."},{"t":"exchange","vi":"Trao đổi. Trong bài nằm trong tên VEX — Vulnerability Exploitability eXchange, định dạng trao đổi thông tin về khả năng khai thác lỗ hổng."},{"t":"SBOM/CVE","vi":"Cặp công việc SBOM và quản lý CVE: biết trên xe có gì (SBOM) để biết lỗ hổng mới (CVE) ảnh hưởng release nào — phạm vi topic này sở hữu."},{"t":"Monitor/CVE","vi":"Nhịp đầu của vòng sau release: theo dõi CVE mới và đối chiếu với SBOM của mọi release còn hỗ trợ."},{"t":"vulnerability/threat","vi":"Lỗ hổng và mối đe dọa mới xuất hiện sau SOP — thứ CSMS yêu cầu phải monitoring liên tục."},{"t":"expose","vi":"Phơi ra ngoài, để bên ngoài chạm tới được. Trong triage CVE: interface/code path có lỗ hổng có bị expose tới attacker không — nếu không, rủi ro thực tế thấp.","aka":["exposed","exposes","exposing"]},{"t":"exposure/impact","vi":"Mức phơi nhiễm và mức tác động của lỗ hổng trên xe — hai câu hỏi lọc quyết định CVE đi nhánh ghi nhận, mitigation hay patch."},{"t":"likelihood/exposure","vi":"Khả năng xảy ra và mức phơi nhiễm thực tế trên xe; ví dụ module không bật thì gần như bằng không dù CVSS cao."},{"t":"likelihood/impact","vi":"Khả năng xảy ra và mức tác động — hai yếu tố kết hợp để đánh giá risk; control làm giảm một trong hai."},{"t":"likelihood/impact/affected scope","vi":"Ba yếu tố xếp hạng rủi ro bảo trì: khả năng xảy ra, mức tác động và số xe/variant thực sự bị ảnh hưởng.","aka":["likelihood/impact/affected"]},{"t":"impact/feasibility","vi":"Mức tác động và độ khả thi tấn công — cách TARA xếp hạng threat."},{"t":"code path","vi":"Nhánh mã được thực thi. Trong triage: component có lỗ hổng nhưng code path chứa lỗi không được dùng/bật thì có thể kết luận không bị ảnh hưởng (ghi VEX).","aka":["code paths"]},{"t":"component/version","vi":"Component và phiên bản cụ thể — câu hỏi đầu của triage: đúng component/version bị CVE có thật trong build không?"},{"t":"component/dependency","vi":"Component hoặc thư viện phụ thuộc — cột đầu của maintenance risk register."},{"t":"build/configuration","vi":"Một bản build cụ thể cùng cấu hình (variant) của nó. SBOM phải sinh theo từng build/configuration thì triage mới trả lời chính xác xe nào bị ảnh hưởng."},{"t":"build/release","vi":"Một bản build/phát hành cụ thể — đơn vị mà SBOM mô tả."},{"t":"build/version","vi":"Bản build/phiên bản cụ thể mà SBOM liên kết tới."},{"t":"build/baseline","vi":"Bản build gắn với baseline cấu hình — SUMS cần SBOM theo build/baseline để biết phiên bản software trên từng cấu hình xe."},{"t":"image/build","vi":"Software image/bản build cụ thể — SBOM cho biết image/build nào chứa thư viện bị CVE."},{"t":"release/version","vi":"Bản phát hành/phiên bản cụ thể. Mọi evidence bảo mật (TARA, test report, SBOM, quyết định CVE) phải gắn với release/version cụ thể.","aka":["version/release"]},{"t":"variant/baseline","vi":"Quản lý variant (biến thể cấu hình xe) và baseline (cấu hình đã chốt) — điều kiện để triage CVE không thành đoán mò (xem A.2)."},{"t":"variant/population","vi":"Variant và nhóm xe thực sự chạy nó. Chỉ patch variant/population bị ảnh hưởng thì ít rủi ro và chi phí hơn patch toàn fleet."},{"t":"kernel/BSP","vi":"Kernel hệ điều hành và BSP (Board Support Package) do vendor SoC cung cấp. Hạn hỗ trợ của chúng thường ngắn hơn đời xe — rủi ro bảo trì phải ghi từ lúc chọn SoC."},{"t":"SoC/BSP","vi":"Chip SoC và BSP đi kèm. EOL của SoC/BSP là một mốc phải theo dõi và có quyết định trước."},{"t":"OS/library","vi":"Hệ điều hành hoặc thư viện phần mềm — mỗi cái có support window riêng cần theo dõi."},{"t":"toolchain/compiler","vi":"Bộ công cụ build và trình biên dịch. Component cũ có thể không build được bằng toolchain/compiler mới — cản trở việc vá."},{"t":"backport","vi":"Mang bản vá từ phiên bản mới về áp cho phiên bản cũ đang dùng. Ít thay đổi hơn upgrade nhưng tốn công và càng lệch xa upstream càng khó.","aka":["backports","backported","backporting"]},{"t":"upgrade","vi":"Nâng cấp lên phiên bản mới (của upstream/supplier). Nhận đủ bản vá nhưng thay đổi lớn, cần re-validate và có thể phá compatibility — đối lập với backport.","aka":["upgrades","upgraded"]},{"t":"upgrade/backport/compensating control/accept","vi":"Bốn chiến lược xử lý một rủi ro bảo trì: nâng cấp, backport bản vá, thêm compensating control, hoặc chấp nhận rủi ro có điều kiện.","aka":["upgrade/backport/compensating"]},{"t":"control/accept","vi":"Phần cuối của \"compensating control/accept\": bù trừ bằng control khác hoặc chấp nhận rủi ro có người duyệt, thời hạn."},{"t":"accept","vi":"Chấp nhận. Trong bài: <i>accept risk<\/i> — chấp nhận rủi ro; chỉ hợp lệ khi có người phê duyệt, thời hạn và điều kiện xem lại, nếu không risk bị \"quên\".","aka":["accepting","accept risk"]},{"t":"patch/update","vi":"Vá lỗi/cập nhật phần mềm — một nhịp trong vòng đời bảo mật sau release."},{"t":"patch/mitigation","vi":"Quyết định vá lỗi hoặc dùng biện pháp giảm thiểu khi chưa vá được."},{"t":"mitigation/monitor","vi":"Giảm thiểu rủi ro rồi tiếp tục theo dõi — nhánh xử lý CVE có exposure/impact thấp."},{"t":"Patch/OTA","vi":"Vá lỗi và phát hành bản vá qua OTA (hoặc mitigation) — nhịp xử lý sau triage."},{"t":"Verify/Recovery","vi":"Kiểm tra sau khi vá (test, health check) và khả năng khôi phục nếu hỏng."},{"t":"rollback/recovery","vi":"Quay lại bản cũ đã biết là tốt hoặc khôi phục hệ thống khi cài update thất bại (ví dụ mất điện giữa chừng). Cần được test, không chỉ thiết kế."},{"t":"rollback/anti-rollback","vi":"Rollback (OEM chủ động quay về bản tốt) và anti-rollback (chặn cài lại bản cũ có lỗ hổng): hai cơ chế khác nhau nhưng phải cùng tồn tại."},{"t":"regression/security/compatibility","vi":"Ba loại test sau khi vá: regression (không làm hỏng cái cũ), security (lỗ hổng đã đóng), compatibility (chạy đúng trên các variant).","aka":["regression/security"]},{"t":"regression risk","vi":"Rủi ro bản vá làm hỏng chức năng vốn đang chạy tốt. Lý do không \"vá ngay cho toàn fleet\" mà phải test theo variant và staged rollout."},{"t":"test/analysis","vi":"Kiểm thử hoặc phân tích — cách verification cho mỗi security requirement; kết quả là evidence."},{"t":"build/test/OTA","vi":"Chuỗi việc tốn kém khi vá: build lại, test, phát hành OTA. Triage tốt loại bớt CVE trước khi tốn tiền cho chuỗi này."},{"t":"feature/service","vi":"Tính năng hoặc service chứa lỗ hổng — tắt chúng là cách giảm exposure khi chưa vá được."},{"t":"patch strategy","vi":"Chiến lược vá lỗi: chọn cadence phát hành, chọn LTS từ đầu, kênh vá (OTA hay workshop), phạm vi variant, backport hay upgrade — mỗi lựa chọn đều có đánh đổi.","aka":["patch strategies"]},{"t":"promote","vi":"Nâng lên giai đoạn tiếp. Trong secure OTA: sau staged rollout và health check tốt thì <i>promote<\/i> (mở rộng phát hành cho nhóm xe lớn hơn), xấu thì rollback.","aka":["promoted","promotion"]},{"t":"brick","vi":"\"Biến thành cục gạch\": thiết bị/ECU không khởi động được sau update lỗi. Secure OTA phải có rollback/recovery và test tình huống xấu để tránh brick xe.","aka":["bricked","bricking"]},{"t":"dependency aging","vi":"Sự lão hóa của dependency: component càng cũ càng tách xa upstream, bản vá mới không áp trực tiếp được, toolchain cũ dần. Một quá trình lặng lẽ dẫn tới security debt.","aka":["aging"]},{"t":"aging/EOS/EOL","vi":"Ba mốc rủi ro của dependency theo thời gian: lão hóa, hết hỗ trợ (EOS) và hết vòng đời (EOL)."},{"t":"end-of-support","vi":"Hết hỗ trợ: nhà cung cấp ngừng phát hành bản vá và trả lời câu hỏi. Component vẫn chạy, nhưng từ đây mọi CVE mới là việc của riêng bạn.","aka":["end of support"]},{"t":"EOS","vi":"Mốc hết hỗ trợ của một component/sản phẩm: không còn bản vá từ nhà cung cấp. Phải biết sớm để quyết định trước: upgrade, backport, thay thế hay chấp nhận rủi ro.","full":"End-of-Support","cs":true},{"t":"end-of-support/end-of-life","vi":"Hai mốc hay bị nói lẫn: hết hỗ trợ vá (EOS) và hết vòng đời sản phẩm (EOL). Kế hoạch cho cả hai phải có từ sớm vì xe sống lâu hơn support window.","aka":["EOS/EOL"]},{"t":"support end","vi":"Ngày hết hỗ trợ của một dependency/version — cột trong maintenance risk register để biết mốc EOS/EOL từ sớm."},{"t":"end of cybersecurity support","vi":"Theo ISO/SAE 21434: thời điểm OEM ngừng hỗ trợ bảo mật cho một sản phẩm/xe. Cần kế hoạch: thông báo khách hàng, dịch vụ cloud/OTA nào ngừng, thu hồi certificate, xóa dữ liệu cá nhân."},{"t":"decommissioning","vi":"Ngừng vận hành/thải bỏ sản phẩm (thuật ngữ ISO/SAE 21434). Với xe kết nối: thu hồi certificate/credential, xóa dữ liệu cá nhân, ngừng dịch vụ có kế hoạch.","aka":["decommission"]},{"t":"cloud/OTA","vi":"Dịch vụ cloud và kênh OTA của xe — khi hết hỗ trợ phải nói rõ dịch vụ nào ngừng và xe còn an toàn ra sao khi mất kết nối."},{"t":"cloud/telematics","vi":"Kết nối cloud qua telematics — một trong bốn \"cửa\" của xe kết nối; cho phép tấn công từ xa ở quy mô fleet."},{"t":"maintenance risk register","vi":"Sổ rủi ro bảo trì: bảng theo dõi từng dependency với version, ngày hết hỗ trợ, rủi ro (aging, EOL, CVE, cert hết hạn), chiến lược, owner, deadline và evidence — biến nợ bảo trì thành cam kết có người chịu."},{"t":"deadline/review date","vi":"Hạn chót xử lý và ngày xem lại rủi ro — cột bắt buộc trong maintenance risk register.","aka":["deadline/review"]},{"t":"data minimization","vi":"Tối thiểu hóa dữ liệu: chỉ thu thập và lưu đúng lượng dữ liệu cá nhân cần cho mục đích đã nêu. Nguyên tắc privacy — security tốt vẫn chưa đủ nếu thu thừa dữ liệu.","aka":["data minimisation"]},{"t":"consent","vi":"Sự đồng ý của người dùng trước khi thu thập/chia sẻ dữ liệu cá nhân (ví dụ vị trí). Một yêu cầu privacy, cùng với data minimization và retention.","aka":["consents"]},{"t":"chat","vi":"Kênh trò chuyện nhóm (Slack, Teams…). Bài cảnh báo: CVE chỉ được bàn trong kênh chat thì không có owner và không thành evidence — phải mở ticket triage."},{"t":"runbook","vi":"Sổ tay vận hành: các bước làm sẵn cho một tình huống lặp lại (ai nhận tin, tra SBOM ở đâu, ai quyết định, ghi evidence ở đâu). Trong bài là runbook xử lý CVE.","aka":["runbooks"]},{"t":"eradication","vi":"Loại bỏ nguyên nhân (giai đoạn của incident response sau containment): patch, đổi cấu hình hoặc rotate key để kẻ tấn công không còn đường vào."},{"t":"post-incident","vi":"Sau sự cố: giai đoạn cuối của incident response — cập nhật threat model, SBOM, monitoring và ghi lesson learned để không lặp lại."},{"t":"compromise","vi":"Bị xâm nhập/chiếm quyền. Trong bài: case \"remote vehicle compromise 2015\" — xe bị chiếm điều khiển từ xa, cho thấy kết nối tạo attack surface thật.","aka":["compromised"]},{"t":"selection","vi":"Sự lựa chọn. Trong bài: <i>control selection<\/i> — chọn control gắn đúng threat, nhiều lớp, có verification và owner."},{"t":"R155/CSMS","vi":"Quy định UN R155 gắn với hệ thống quản lý CSMS: quản lý cybersecurity risk trong toàn vòng đời xe.","aka":["UN R155/CSMS"],"cs":true},{"t":"R156/SUMS","vi":"Quy định UN R156 gắn với hệ thống quản lý SUMS: quản lý software update an toàn và có truy nguyên.","aka":["UN R156/SUMS"],"cs":true},{"t":"CSMS","vi":"Hệ thống quản lý cybersecurity của tổ chức (yêu cầu bởi UN R155): quy trình xác định và xử lý risk, quản lý supplier, monitoring sau SOP, xử lý incident — xuyên suốt vòng đời xe.","aka":["Cyber Security Management System"],"full":"Cyber Security Management System","cs":true},{"t":"SUMS","vi":"Hệ thống quản lý cập nhật phần mềm (yêu cầu bởi UN R156): biết phiên bản software trên từng cấu hình xe, đánh giá ảnh hưởng của update, bảo vệ quá trình update và ghi lại để truy nguyên.","aka":["Software Update Management System"],"full":"Software Update Management System","cs":true},{"t":"CSMS/SUMS","vi":"Hai hệ thống quản lý bắt buộc theo UN R155 (CSMS – cybersecurity) và UN R156 (SUMS – software update).","cs":true},{"t":"E/E","vi":"Điện/điện tử — chỉ kiến trúc điện-điện tử của xe (ECU, mạng, gateway, nguồn). Team E/E quyết định chỗ đặt gateway, segmentation, nơi có thể thêm compensating control.","aka":["E/E architecture"],"full":"Electrical/Electronic","cs":true},{"t":"IVI/CDC","vi":"Hệ thống thông tin giải trí (IVI) trên CDC — vùng ít tin cậy hơn, phải có trust boundary với vehicle network qua gateway kiểm tra quyền."},{"t":"requirement/architecture","vi":"Giai đoạn yêu cầu và kiến trúc — nơi security by design bắt đầu xét threat và control."},{"t":"security evidence","vi":"Bằng chứng bảo mật: TARA, test report, SBOM, kết quả scan, quyết định CVE — gắn với release/version cụ thể và lưu theo chính sách retention để chứng minh với audit/cơ quan phê duyệt."},{"t":"cybersecurity case","vi":"Hồ sơ lập luận có bằng chứng rằng sản phẩm đủ an toàn về bảo mật để phát hành (khái niệm của ISO/SAE 21434), tương tự safety case bên functional safety.","aka":["cybersecurity cases"]},{"t":"centralized architecture","vi":"Kiến trúc tập trung: gần như mọi chức năng phần mềm của xe chạy trên central compute (HPC/vehicle computer), phân vùng bằng hypervisor/partition. Là một trong bốn kiểu bố trí (distributed, domain, zonal, centralized) được so sánh trong comparison matrix của bài.","aka":["centralized architectures"]},{"t":"zonal","vi":"Theo vùng. Trong bài, <b>zonal architecture<\/b> chia xe theo <i>vị trí vật lý<\/i> (trước, sau, trái, phải…): mỗi zone controller gom dây và I/O của vùng mình, còn logic chạy trên central compute. Giảm dây điện, BOM và hợp với SOA, nhưng phụ thuộc backbone."},{"t":"zonal architecture","vi":"Kiến trúc theo vùng: zone controller ở từng vùng vật lý của xe đọc cảm biến/điều khiển cơ cấu chấp hành, gửi dữ liệu qua backbone Ethernet lên central compute nơi chạy logic. Thường đi kèm SOA; là hướng phổ biến của SDV.","aka":["zonal architectures"]},{"t":"zone","vi":"Vùng: một khu vực vật lý của xe (ví dụ phía trước bên trái). Trong zonal architecture, mỗi zone có một zone controller lo dây điện, cảm biến và cơ cấu chấp hành của vùng đó, không chứa logic tính năng.","aka":["zones"]},{"t":"viewpoint","vi":"Góc nhìn kiến trúc: một cách mô tả hệ thống trả lời một nhóm câu hỏi của stakeholder (functional, logical, deployment, ownership, lifecycle…). Trong bài, dùng nhiều viewpoint để mô tả cùng một vehicle-data service và để reviewer kiểm được từng mặt.","aka":["viewpoints"]},{"t":"VSS","vi":"Đặc tả chuẩn hóa tên và ý nghĩa signal của xe theo cây phân cấp (ví dụ <i>Vehicle.Speed<\/i>), do COVESA duy trì, độc lập với CAN/Ethernet. Giúp giảm mơ hồ về tên và unit giữa các team, nhưng không thay được interface contract đầy đủ (timing, validity, owner).","full":"Vehicle Signal Specification","cs":true},{"t":"SOA","vi":"Kiến trúc hướng dịch vụ: chức năng được đóng gói thành service có interface/API, version và owner rõ; consumer gọi hoặc subscribe service qua middleware (SOME/IP, DDS…). Trong xe, SOA trên Ethernet cho phép thêm consumer/feature mà không sửa producer.","full":"Service-Oriented Architecture","cs":true},{"t":"distributed ECU","vi":"Kiến trúc ECU phân tán: mỗi chức năng (cửa, đèn, airbag…) có một ECU riêng, thường do một supplier làm trọn. Ranh giới rõ, nhưng xe có hàng chục ECU, nhiều dây, gateway và logic lặp; là điểm xuất phát mà SDV muốn rời đi.","aka":["distributed ECUs"]},{"t":"comparison","vi":"Sự so sánh. Trong bài thường đi trong cụm <b>comparison matrix<\/b>: bảng so sánh các phương án kiến trúc theo cùng một bộ tiêu chí có evidence.","aka":["comparisons"]},{"t":"comparison matrix","vi":"Bảng so sánh: hàng là tiêu chí (số ECU, wiring, BOM, decoupling, OTA, blast radius…), cột là phương án (domain / zonal + central / centralized / hybrid), mỗi ô có ghi chú và evidence. Là phần lõi của Assignment 1 — mục đích không phải chấm điểm mà là làm rõ trade-off.","aka":["comparison matrices"]},{"t":"logical","vi":"Logic, thuộc về mặt chức năng/khái niệm (chưa gắn với phần cứng). Trong bài, <b>logical view<\/b> mô tả service/component/data liên kết với nhau ra sao, tách khỏi deployment view (chạy ở ECU/VM/container/cloud nào)."},{"t":"logical architecture","vi":"Kiến trúc logic: mô tả các component/service và luồng dữ liệu giữa chúng, không quan tâm chạy trên phần cứng nào. Đi cặp với deployment architecture (ánh xạ các phần đó lên ECU, partition, cloud).","aka":["logical/deployment architecture"]},{"t":"virtual-first","vi":"Ưu tiên ảo trước: phát triển và test phần mềm trên virtual ECU, simulation, emulation, digital twin trước khi có phần cứng, chạy tự động trong CI. Phát hiện lỗi sớm và rẻ, nhưng không thay test trên phần cứng khi phụ thuộc sensor noise, timing thật, thermal.","aka":["virtual first"]},{"t":"backbone","vi":"Xương sống: đường truyền chính băng thông cao nối các khối lớn. Trong xe hiện đại, backbone thường là Automotive Ethernet nối zone controller với central compute, chở dữ liệu lớn và SOA; zonal architecture phụ thuộc vào nó.","aka":["backbones"]},{"t":"radar","vi":"Cảm biến dùng sóng vô tuyến đo khoảng cách và vận tốc vật thể quanh xe; dùng cho ADAS (cảnh báo điểm mù, giữ khoảng cách…). Trong bài là ví dụ thêm một radar góc mới và xem mỗi kiểu kiến trúc phải sửa những gì.","aka":["radars"]},{"t":"body","vi":"Thân xe. Trong kiến trúc xe, <b>body domain<\/b> là nhóm chức năng thân xe: cửa, đèn, gương, khóa, gạt mưa, điều hòa cơ bản… Ở domain architecture nó có domain controller riêng.","aka":["body domain"]},{"t":"Vehicle.Speed","vi":"Tên signal tốc độ xe theo cây VSS (dạng đường dẫn Nhánh.Lá). Trong bài là ví dụ cho thấy tên chuẩn chưa đủ: interface contract còn phải chốt km/h hay m/s, thời điểm lấy mẫu, valid/stale, update rate và hành vi khi lỗi."},{"t":"VehicleSpeed","vi":"Tốc độ xe. Trong bài, <i>VehicleSpeed<\/i> là tên service do zone controller/gateway tạo ra từ frame CAN và phát trên Ethernet qua SOME/IP cho cluster, audio và cloud uploader dùng.","aka":["vehicle speed","vehicle-speed"]},{"t":"fan-out","vi":"Tỏa ra: một nguồn dữ liệu phục vụ nhiều consumer. Trong bài, fan-out là lý do chọn pub/sub cho vehicle-data service (một producer tốc độ, nhiều consumer: display, audio, cloud) để giữ coupling thấp.","aka":["fanout","fan out"]},{"t":"modern","vi":"Hiện đại. Trong tên bài <i>Modern Vehicle Architecture<\/i>: kiến trúc điện/điện tử và phần mềm của xe thế hệ mới (zonal, central compute, SOA, OTA) so với kiến trúc ECU phân tán truyền thống."},{"t":"hard-code","vi":"Viết cứng giá trị/điều kiện vào mã nguồn thay vì đọc từ cấu hình hay hỏi platform. Trong bài: feature hard-code theo tên model xe là sai lầm — nên hỏi platform xem capability (ví dụ radar góc) có trên variant này không.","aka":["hard-coded","hardcode","hardcoded"]},{"t":"activation","vi":"Sự kích hoạt, bật lên. Trong bài, <b>feature activation<\/b>: phần cứng và phần mềm đã có sẵn trên xe nhưng feature chỉ được bật bằng software/configuration (feature flag) theo thị trường, gói bán hoặc kết quả rollout.","aka":["activations"]},{"t":"feature activation","vi":"Bật tính năng bằng cấu hình/feature flag, tách khỏi việc cài phần mềm (deploy). Cho phép bán feature on demand, bật dần theo nhóm xe, và tắt nhanh nếu có lỗi mà không cần cài lại."},{"t":"activate","vi":"Kích hoạt, bật. Trong vòng đời SDV (Develop → Validate → Deploy → Activate → Collect → Analyze), Activate là bước bật feature bằng flag/configuration, tách riêng khỏi bước cài software.","aka":["activated"]},{"t":"simulator","vi":"Trình mô phỏng: phần mềm/thiết bị giả lập môi trường thật. Bài ví von virtual-first như tập lái bằng simulator trước khi ra đường: phát hiện nhiều lỗi sớm và rẻ, nhưng không thay được lái xe thật.","aka":["simulators"]},{"t":"simulation","vi":"Mô phỏng: chạy mô hình của xe/môi trường/cảm biến trên máy tính để test phần mềm khi chưa có phần cứng. Là một công cụ của virtual-first, chạy được trong CI.","aka":["simulations"]},{"t":"emulation","vi":"Giả lập: chạy phần mềm đích trên một nền khác bằng cách bắt chước phần cứng/CPU thật (ví dụ chạy firmware ECU trên PC). Cùng với simulation và virtual ECU giúp test sớm theo hướng virtual-first.","aka":["emulator","emulators","emulated","emulate"]},{"t":"rationale","vi":"Lý do, cơ sở của một quyết định. Trong ADR, rationale ghi <i>vì sao<\/i> chọn phương án này (ví dụ chọn pub/sub vì fan-out và coupling thấp), để sau này người khác hiểu và biết khi nào cần xem lại."},{"t":"organization","vi":"Tổ chức (cơ cấu team, vai trò, trách nhiệm). Trong bài: chuyển sang SDV kéo theo đổi organization — từ team theo ECU/supplier sang platform team và feature team; đổi kiến trúc phải đổi tổ chức.","aka":["organizations","organisation"]},{"t":"uploader","vi":"Thành phần tải dữ liệu lên. Trong ví dụ vehicle-data service, <i>cloud uploader<\/i> là consumer chạy trên partition AAOS, lấy tốc độ xe gửi lên cloud để phân tích; cần queue giới hạn và policy drop/expiry khi offline.","aka":["uploaders","cloud uploader"]},{"t":"poll","vi":"Hỏi vòng: consumer chủ động hỏi định kỳ để lấy giá trị mới. Trong bài là một phương án trao dữ liệu so với pub/sub và shared memory; với nhiều consumer (fan-out), poll tạo tải và coupling cao hơn.","aka":["polling","polls","polled"]},{"t":"slow","vi":"Chậm. Trong bài thường gặp trong cụm <b>slow consumer<\/b>: consumer xử lý chậm hơn tốc độ producer gửi.","aka":["slower","slowly"]},{"t":"slow consumer","vi":"Consumer chậm: bên nhận xử lý không kịp tốc độ dữ liệu đến, làm đầy queue hoặc kéo chậm producer. Validation của pub/sub phải test trường hợp này để chắc nó không ảnh hưởng consumer khác.","aka":["slow consumers"]},{"t":"airbag","vi":"Túi khí: hệ thống an toàn bung ra khi va chạm. Là ví dụ chức năng safety-critical, thường giữ ECU/partition riêng vì yêu cầu độc lập an toàn.","aka":["airbags"]},{"t":"scalable","vi":"Có khả năng mở rộng. Bài nhắc: viết quality attribute thành tính từ như \"scalable\" là không đủ — phải viết thành scenario đo được (thêm bao nhiêu consumer/feature, trong bao lâu, sửa bao nhiêu chỗ)."},{"t":"scalability","vi":"Khả năng mở rộng: hệ thống thêm được consumer, feature, variant hay tải mà không phải thiết kế lại. Là một quality attribute dẫn dắt lựa chọn kiến trúc xe (zonal + SOA thường mở rộng tốt hơn)."},{"t":"Scalable service-Oriented MiddlewarE over IP","vi":"Tên đầy đủ của SOME/IP: middleware hướng dịch vụ chạy trên IP (Ethernet) dùng phổ biến trong xe, cung cấp gọi service, sự kiện (event) và service discovery."},{"t":"CAN FD","vi":"Phiên bản nâng cấp của CAN cho phép tốc độ dữ liệu cao hơn và khung dài hơn (đến 64 byte). Trong bài, CAN/CAN FD dùng cho control và I/O, còn dữ liệu lớn đi trên Automotive Ethernet.","aka":["CAN/CAN FD"],"full":"CAN with Flexible Data-rate","cs":true},{"t":"ADAS","vi":"Hệ thống hỗ trợ lái nâng cao: cảnh báo va chạm, giữ làn, phanh khẩn cấp, cruise control thích ứng… dựa trên camera, radar. Trong bài là một domain cần compute lớn và có yêu cầu safety cao.","full":"Advanced Driver Assistance Systems","cs":true},{"t":"advanced","vi":"Nâng cao, tiên tiến. Xuất hiện trong tên đầy đủ của ADAS (Advanced Driver Assistance Systems)."},{"t":"assistance","vi":"Sự hỗ trợ. Xuất hiện trong ADAS (Advanced Driver <i>Assistance<\/i> Systems): hệ thống hỗ trợ người lái, người lái vẫn chịu trách nhiệm điều khiển."},{"t":"updateability","vi":"Khả năng cập nhật: mức dễ dàng cập nhật phần mềm (qua OTA) mà không phải thay phần cứng hay sửa nhiều ECU. Là một tiêu chí so sánh các kiểu kiến trúc; centralized/zonal thường tốt hơn distributed.","aka":["updatability"]},{"t":"decoupling","vi":"Tách rời, giảm phụ thuộc giữa hai phần. Trong bài, <b>hardware/software decoupling<\/b> nghĩa là phần mềm feature không bị trói vào một phần cứng cụ thể, nhờ abstraction, capability discovery và interface ổn định.","aka":["decouple","decoupled"]},{"t":"hardware/software decoupling","vi":"Tách phần mềm khỏi phần cứng: feature dùng capability qua platform/API thay vì gọi thẳng driver hay hard-code theo model xe, nên đổi phần cứng hoặc thêm variant không phải viết lại feature. Là nguyên lý lõi của SDV và một dòng trong comparison matrix.","aka":["hardware-software decoupling"]},{"t":"hardware/software","vi":"Phần cứng/phần mềm (nói chung cả hai, hoặc ranh giới giữa hai). Trong bài thường đi với decoupling: tách vòng đời phần mềm khỏi phần cứng.","aka":["HW/SW"]},{"t":"hook","vi":"Tình huống mở bài (\"móc câu\") để gợi vấn đề. Trong bài, hook là các tình huống ở đầu mỗi mục (ví dụ cluster và audio hiểu \"Speed\" khác nhau) mà phần sau quay lại giải thích.","aka":["hooks"]},{"t":"building block","vi":"Khối xây dựng: thành phần chuẩn dùng lại để ghép thành hệ thống. Trong reference architecture: zone, central compute, partition, platform service, cloud service là các building block mà mọi vehicle program phải dùng theo rule chung.","aka":["building blocks"]},{"t":"building","vi":"Xây dựng. Trong bài chủ yếu gặp trong cụm <i>building block<\/i> (khối thành phần chuẩn để ghép kiến trúc)."},{"t":"program","vi":"Chương trình (dự án phát triển). Trong ngành ô tô, <b>vehicle program<\/b> là toàn bộ dự án phát triển một dòng xe/đời xe đến SOP và sau đó; mỗi program dẫn xuất kiến trúc của mình từ reference architecture.","aka":["programs","programme"]},{"t":"consequences","vi":"Hệ quả. Trong ADR, mục Consequences ghi điều gì xảy ra sau khi chọn phương án: lợi ích, chi phí và trade-off phải chấp nhận."},{"t":"demand","vi":"Nhu cầu. Trong bài gặp trong <b>feature on demand<\/b>: tính năng bán/bật thêm theo yêu cầu sau khi xe đã bán.","aka":["on demand"]},{"t":"feature on demand","vi":"Tính năng theo yêu cầu: phần cứng/phần mềm có sẵn trên xe, khách hàng mua hoặc thuê bao để bật thêm qua OTA/cấu hình. Là mô hình doanh thu sau bán của SDV, nhưng đòi hỏi variant check, test và vận hành backend.","aka":["features on demand","FoD"]},{"t":"pooling","vi":"Gom chung (tài nguyên). <b>Resource pooling<\/b>: nhiều function dùng chung CPU, memory của central compute thay vì mỗi ECU một phần cứng riêng — tiết kiệm và linh hoạt nhưng cần isolation.","aka":["resource pooling","Resource pooling"]},{"t":"location","vi":"Vị trí. Trong bài là ví dụ một service (vị trí GPS của xe) do platform cung cấp; gửi location lên cloud cần consent và chỉ ở mức cần thiết.","aka":["locations"]},{"t":"SUMS/CSMS","vi":"Cặp hệ thống quản lý bắt buộc: SUMS (quản lý cập nhật phần mềm, R156) và CSMS (quản lý an ninh mạng, R155). Trong bài: với SDV, chúng và evidence phải vận hành liên tục nhiều năm sau SOP.","cs":true},{"t":"COVESA","vi":"Liên minh công nghiệp ô tô phát triển chuẩn mở cho xe kết nối; là tổ chức duy trì VSS (Vehicle Signal Specification).","full":"Connected Vehicle Systems Alliance","cs":true},{"t":"HPC","vi":"Máy tính hiệu năng cao trong xe: tên gọi khác của central compute/vehicle computer, chạy nhiều domain trên một SoC qua hypervisor/partition.","full":"High-Performance Computer","cs":true},{"t":"high-performance","vi":"Hiệu năng cao. Trong bài gặp trong HPC (High-Performance Computer) — máy tính trung tâm mạnh của xe."},{"t":"computer","vi":"Máy tính. Trong bài, <b>vehicle computer<\/b> là máy tính trung tâm của xe (central compute/HPC) nơi logic được dời lên trong SDV.","aka":["computers"]},{"t":"MQTT","vi":"Giao thức nhắn tin publish/subscribe nhẹ qua broker, hay dùng cho IoT và kết nối xe–cloud. Trong bài: phía cloud thường dùng MQTT hoặc HTTP/gRPC.","full":"Message Queuing Telemetry Transport","cs":true},{"t":"HTTP/gRPC","vi":"Hai cách gọi API qua mạng: HTTP (giao thức web, thường REST/JSON) và gRPC (gọi hàm từ xa hiệu năng cao của Google, dùng HTTP/2 và Protobuf). Trong bài là lựa chọn giao tiếp phía cloud.","aka":["HTTP / gRPC"],"cs":true},{"t":"time-sensitive","vi":"Nhạy thời gian: lưu lượng cần thời gian truyền xác định, có giới hạn trễ. Trong bài: một số chương trình thêm cơ chế time-sensitive trên Ethernet (họ chuẩn TSN) cho traffic điều khiển.","aka":["time sensitive"]},{"t":"kg","vi":"Ki-lô-gam, đơn vị khối lượng. Bài dùng trong ví von hợp đồng giao hàng: không chỉ ghi \"giao gạo\" mà phải ghi bao nhiêu kg — như interface contract phải ghi unit, range.","full":"kilogram"},{"t":"ambiguity","vi":"Sự mơ hồ, có thể hiểu nhiều cách. Trong bài: VSS giảm ambiguity về tên và unit của signal giữa các team, ví dụ cluster và audio hiểu \"Speed\" khác nhau.","aka":["ambiguous"]},{"t":"query","vi":"Truy vấn, câu hỏi lấy dữ liệu. Trong bài: request/response dùng khi có query hoặc command cần trả lời (ví dụ lấy VIN), còn pub/sub cho dữ liệu phát liên tục.","aka":["queries"]},{"t":"handling","vi":"Sự xử lý. Trong bài, <b>stale handling<\/b> là cách xử lý dữ liệu cũ (quá hạn): đánh dấu, bỏ hoặc dùng giá trị mặc định khi signal không còn được cập nhật đúng hạn.","aka":["stale handling"]},{"t":"deviation","vi":"Sự sai lệch, ngoại lệ so với chuẩn. Trong bài: kiến trúc dự án được dẫn xuất từ reference architecture và mọi deviation (chỗ làm khác chuẩn) phải có ADR giải thích.","aka":["deviations"]},{"t":"cross-cutting concern","vi":"Mối quan tâm xuyên suốt: chức năng ảnh hưởng tới mọi phần của hệ thống, không thuộc riêng feature nào — security, diagnostic, logging, OTA, time sync, power mode. Reference architecture phải quy định chung cho chúng.","aka":["cross-cutting concerns"]},{"t":"cross-cutting","vi":"Xuyên suốt, cắt ngang nhiều phần của hệ thống. Thường đi trong cụm cross-cutting concern."},{"t":"concern","vi":"Mối quan tâm, vấn đề cần lo. Trong kiến trúc, concern là một khía cạnh stakeholder quan tâm (an toàn, chi phí, cập nhật…); mỗi viewpoint trả lời một nhóm concern.","aka":["concerns"]},{"t":"low","vi":"Thấp. Bài nhắc viết quality attribute thành tính từ như \"low latency\" là không đủ — phải ghi con số đo được (ví dụ P95 ≤ bao nhiêu ms trong điều kiện nào)."},{"t":"noise","vi":"Nhiễu: sai lệch ngẫu nhiên trong tín hiệu đo. Trong bài: virtual-first không thay được test phần cứng khi thuộc tính phụ thuộc sensor noise, timing thật hay thermal.","aka":["sensor noise"]},{"t":"dump","vi":"Bản kết xuất. <b>Crash dump<\/b> là ảnh chụp bộ nhớ/trạng thái chương trình lúc bị crash, gửi về để phân tích nguyên nhân. Trong bài: khi rollout 1% thấy crash tăng thì phân tích log/crash dump trước khi rollout lại.","aka":["crash dump","crash dumps","dumps","crash dump/core","dump/core"]},{"t":"ECU-centric","vi":"Lấy ECU làm trung tâm: cách làm cũ, mỗi ECU là một hộp đen do một supplier làm trọn, team tổ chức theo ECU/supplier, phần mềm ít đổi sau SOP. Bài so sánh nó với cách tổ chức theo SDV."},{"t":"safety-related","vi":"Liên quan an toàn: chức năng mà lỗi có thể gây nguy hiểm cho người. Trong bài: update cho safety-related function có thể làm safety argument hoặc homologation mất hiệu lực, cần impact analysis và tách partition safety.","aka":["safety related"]},{"t":"relationship","vi":"Mối quan hệ. Trong bài, <b>supplier relationship<\/b> thay đổi khi sang SDV: từ mua ECU \"hộp đen\" sang mua platform, middleware, IP với interface mở và hợp đồng support dài hạn.","aka":["relationships","supplier relationship"]},{"t":"recommended","vi":"Được đề xuất/khuyến nghị. Trong mẫu ADR của bài, dòng Recommended ghi phương án kiến trúc được chọn (domain | zonal + central | centralized | hybrid) và phần nào chạy ở đâu."},{"t":"revisit when","vi":"\"Xem lại khi\": mục trong ADR ghi điều kiện phải mở lại quyết định (hết headroom, đổi supplier, đổi regulation…), để quyết định không bị coi là vĩnh viễn."},{"t":"develop","vi":"Phát triển. Trong vòng đời SDV của bài: Develop → Validate → Deploy → Activate → Collect data → Analyze → quay lại Develop.","aka":["developed","developing"]},{"t":"collect","vi":"Thu thập. Trong vòng đời SDV: bước Collect data gom telemetry, DTC, log, usage data từ fleet về backend (có consent).","aka":["collected","collecting"]},{"t":"analyze","vi":"Phân tích. Trong vòng đời SDV: bước analyze dùng fleet data, defect, usage để quyết định sửa gì, phát triển gì tiếp theo.","aka":["analyse","analyzed"]},{"t":"at least","vi":"Ít nhất. Trong rubric: ví dụ ADR phải so sánh at least one alternative (ít nhất một phương án khác)."},{"t":"one","vi":"Một (số lượng). Trong rubric: \"at least one\" — ít nhất một (scenario, alternative…)."},{"t":"measurable","vi":"Đo lường được. Trong bài: quality attribute scenario và acceptance criteria phải measurable (có con số, điều kiện) thì mới thiết kế và test được.","aka":["measurably"]},{"t":"rubric","vi":"Bảng tiêu chí chấm điểm, mô tả mỗi mức đạt được trông như thế nào. Trong bài là rubric của Applied Workshop dùng để chấm bài nộp target-architecture proposal.","aka":["rubrics"]},{"t":"HVAC","vi":"Hệ thống sưởi, thông gió và điều hòa không khí của xe. Trong bài là một feature có thể chọn để mang xuyên suốt A.4 → A.5.","full":"Heating, Ventilation and Air Conditioning","cs":true},{"t":"voice","vi":"Giọng nói; ở đây là tính năng điều khiển/trợ lý bằng giọng nói trong cockpit. Là một feature gợi ý để chọn làm ví dụ xuyên suốt bài.","aka":["voice assistant"]},{"t":"independence","vi":"Sự độc lập. <b>Safety independence<\/b>: chức năng an toàn phải độc lập (phần cứng/partition riêng, không bị chức năng khác gây lỗi). Là một lý do chương trình thật thường là hybrid.","aka":["safety independence"]},{"t":"target-architecture","vi":"Kiến trúc đích: kiến trúc mong muốn đạt tới (so với kiến trúc hiện tại). Bài nộp của Unit là target-architecture proposal 8–10 slide cho một feature xe.","aka":["target architecture","Target architecture"]},{"t":"current-to-target","vi":"Từ hiện tại đến đích: mô tả kiến trúc hiện tại, kiến trúc đích và con đường chuyển đổi (migration) giữa hai cái."},{"t":"proposal","vi":"Đề xuất, bản đề án. Trong bài: bài nộp là một target-architecture proposal (8–10 slide) trình bày và bảo vệ trước người review.","aka":["proposals"]},{"t":"success","vi":"Thành công. <b>Success measures<\/b>: chỉ số đo được để biết giải pháp có đạt mục tiêu không — phải nêu trong phần context của bài nộp.","aka":["success measures","successful"]},{"t":"measures","vi":"Thước đo, biện pháp. Trong rubric, \"success measures\" là các chỉ số dùng để đánh giá thành công."},{"t":"placement","vi":"Sự bố trí, đặt chỗ. <b>Compute placement<\/b>: quyết định chức năng nào chạy ở đâu — zone, central compute, partition nào, hay cloud.","aka":["compute placement"]},{"t":"steps","vi":"Các bước. Trong rubric: rollout steps — các bước triển khai dần (theo nhóm xe/giai đoạn).","aka":["step"]},{"t":"named","vi":"Được đặt tên, chỉ rõ. Trong rubric: diagram phải có named interfaces/boundaries — interface và ranh giới được gọi tên cụ thể."},{"t":"other","vi":"Khác. Trong rubric: trace, test, analysis hoặc artifact khác làm bằng chứng cho quyết định chính.","aka":["others"]},{"t":"supporting","vi":"Hỗ trợ, làm chỗ dựa. Trong rubric: artifact supporting the key decision — bằng chứng (trace, test, analysis) đứng sau quyết định chính."},{"t":"principles","vi":"Nguyên tắc. Trong rubric, \"SDV principles &amp; lifecycle\" đánh giá việc áp dụng nguyên tắc SDV: platform reuse, OTA, diagnostics, operational ownership.","aka":["principle"]},{"t":"operational","vi":"Thuộc về vận hành. <b>Operational ownership<\/b>: ai chịu trách nhiệm vận hành, giám sát, xử lý sự cố của một thành phần sau khi đưa vào sử dụng (sau SOP).","aka":["operationally"]},{"t":"reasoning","vi":"Lập luận, suy luận. Trong rubric, \"safety reasoning\" đánh giá cách lập luận về criticality, isolation, fault containment và degraded mode."},{"t":"challenge","vi":"Thử thách; ở đây là câu hỏi chất vấn của người review. Trong rubric: \"response to challenge\" — cách bảo vệ, trả lời khi quyết định bị chất vấn.","aka":["challenges"]},{"t":"central-vs-domain","vi":"Trung tâm so với domain: ADR so sánh hai phương án đặt chức năng trên central compute hay trên domain controller, có validation plan đi kèm.","aka":["central vs domain"]},{"t":"signal-based","vi":"Dựa trên signal: kiểu giao tiếp truyền thống, giá trị được gửi theo chu kỳ trên bus (CAN/LIN) dù có ai cần hay không. Gateway/zone controller chuyển đổi nó sang service-based.","aka":["signal based"]},{"t":"service-based","vi":"Dựa trên service: consumer gọi hoặc subscribe service qua middleware (SOME/IP, DDS) trên Ethernet, chỉ nhận cái mình cần. Là kiểu giao tiếp của SOA.","aka":["service based"]},{"t":"menu","vi":"Trình đơn trên màn hình. Trong ví dụ của bài: nếu variant không có capability (như radar góc) thì feature không bật và không hiển thị menu tương ứng.","aka":["menus"]},{"t":"cover","vi":"Bao phủ. \"Test cover cả variant có và không có sensor\": bộ test phải chạy qua cả hai loại variant để chắc feature xử lý đúng khi thiếu phần cứng.","aka":["covers","covered"]},{"t":"implementation detail","vi":"Chi tiết hiện thực bên trong (cách làm cụ thể, không phải interface công khai). Trong bài: application không được phụ thuộc implementation detail của platform, để platform nâng cấp được mà không làm vỡ app.","aka":["implementation details"]},{"t":"expiry","vi":"Sự hết hạn. Trong bài, policy <b>drop/expiry<\/b>: dữ liệu chờ gửi quá lâu thì bị bỏ hoặc coi là hết hạn, thay vì tích vô hạn trong queue khi xe mất kết nối.","aka":["expire","expired","expiry date"]},{"t":"drop/expiry","vi":"Chính sách bỏ (drop) hoặc cho hết hạn (expiry) dữ liệu cũ trong queue khi mất kết nối, thay vì tích vô hạn làm đầy bộ nhớ. Bài nhấn mạnh: một queue không giới hạn là rủi ro, phải chốt policy này."},{"t":"actuator","vi":"Cơ cấu chấp hành: bộ phận biến lệnh điện thành chuyển động/tác động (mô-tơ cửa kính, van, đèn, phanh…). Cùng với sensor, là phần I/O mà zone controller quản lý.","aka":["actuators"]},{"t":"sensor/actuator","vi":"Cảm biến/cơ cấu chấp hành: hai đầu I/O của xe — sensor đo (tốc độ, nhiệt độ, radar), actuator tác động (mô-tơ, van, đèn). Trong zonal architecture, zone controller lo phần này.","aka":["sensors/actuators"]},{"t":"NPU","vi":"Bộ xử lý chuyên cho mạng nơ-ron/AI, chạy suy luận (inference) nhanh và tiết kiệm điện hơn CPU/GPU. Trên SoC xe, NPU phục vụ ADAS, nhận diện giọng nói, camera…","full":"Neural Processing Unit","cs":true},{"t":"CPU/GPU/NPU","vi":"Ba loại lõi xử lý trên một SoC: CPU (xử lý chung), GPU (đồ họa, tính toán song song), NPU (AI). Trong bài: SoC tích hợp CPU/GPU/NPU cho phép nhiều domain chạy chung qua hypervisor/partition.","cs":true},{"t":"ECU/VM/container/cloud","vi":"Các nơi một thành phần phần mềm có thể chạy: trên một ECU riêng, trong một VM (máy ảo trên hypervisor), trong container, hoặc trên cloud. Deployment view phải trả lời rõ thành phần chạy ở đâu."},{"t":"ECU/domain/cloud","vi":"Các tầng đặt phần mềm trong kiến trúc xe: ECU/zone (I/O, real-time), domain hoặc central compute (logic feature), cloud (phân tích, việc không real-time). Quyết định ranh giới giữa các tầng là việc cốt lõi của SA.","aka":["ECU/central/cloud","zone/central/cloud","ECU/zone/central/cloud"]},{"t":"ECU/zone","vi":"ECU hoặc zone controller — tầng sát phần cứng. Trong SDV, tầng này chủ yếu cung cấp I/O và chức năng real-time, còn logic feature dời lên central compute.","aka":["ECU/zone controller"]},{"t":"gateway/zone","vi":"Gateway hoặc zone controller: nơi mạng cũ và mới gặp nhau, chuyển đổi giữa signal-based (giá trị gửi theo chu kỳ trên CAN/LIN) và service-based (service trên Ethernet qua SOME/IP).","aka":["gateway/zone controller"]},{"t":"algorithm","vi":"Thuật toán: chuỗi bước xử lý để giải một bài toán. Trong bài: dữ liệu fleet giúp cải tiến model/algorithm (ví dụ nhận diện của ADAS), mỗi lần vẫn qua regression test và change control.","aka":["algorithms"]},{"t":"model/algorithm","vi":"Mô hình (thường là mô hình AI/ML) và thuật toán của một feature. Trong vòng continuous improvement, dữ liệu fleet được dùng để cải tiến chúng, rồi đi lại qua validation và OTA.","aka":["models/algorithms"]},{"t":"RT","vi":"Thời gian thực: phải phản hồi trong hạn thời gian xác định. Trong bài, partition RT/safety chạy RTOS cho chức năng cần thời gian xác định và an toàn (ví dụ cluster), tách khỏi partition AAOS/Linux.","aka":["RT/safety"],"full":"Real-Time","cs":true},{"t":"platform/application/service","vi":"Ba lớp tách phần mềm: platform (OS, middleware, driver dùng chung), service (capability dùng qua interface như vehicle speed, location, logging) và application (feature người dùng thấy). Application không phụ thuộc implementation detail của platform."},{"t":"hypervisor/partition","vi":"Hypervisor chia một SoC thành nhiều partition (máy ảo) cô lập, mỗi cái chạy OS riêng (RTOS, AAOS/Linux). Nhờ đó nhiều domain chạy chung chip, và boundary trở thành boundary về software, isolation, mức safety.","aka":["hypervisor/partitions"]},{"t":"CAN/Ethernet","vi":"CAN hoặc Ethernet — hai loại mạng trong xe: CAN băng thông thấp cho signal điều khiển, Automotive Ethernet băng thông cao cho dữ liệu lớn và SOA. Bài nhấn mạnh VSS mô tả signal độc lập với mạng vận chuyển."},{"t":"quality/validity","vi":"Chất lượng/độ hợp lệ của giá trị: dữ liệu có đáng tin không (sensor lỗi, đang khởi động, ngoài range). Là một nhóm bắt buộc trong interface contract tối thiểu."},{"t":"timeout/error","vi":"Hành vi khi quá hạn hoặc lỗi: consumer làm gì khi không nhận được giá trị đúng hạn hoặc nhận giá trị lỗi (giữ giá trị cũ, báo lỗi, chuyển degraded mode). Phải ghi trong interface contract."},{"t":"contract/version","vi":"Hợp đồng interface và phiên bản của nó. <b>Contract/version test<\/b> kiểm tra producer và consumer vẫn tương thích khi một bên đổi version — chặn lỗi trước khi lên xe.","aka":["contract/version test"]},{"t":"version/permission","vi":"Phiên bản và quyền truy cập của interface: đang dùng phiên bản nào, ai được đọc/ghi. Là một nhóm trong interface contract tối thiểu."},{"t":"source/owner","vi":"Nguồn dữ liệu và chủ sở hữu: dữ liệu đến từ đâu (ECU, sensor nào) và ai chịu trách nhiệm về nó. Nhóm đầu tiên của interface contract tối thiểu."},{"t":"schema/unit/range","vi":"Cấu trúc dữ liệu (schema), đơn vị (km/h hay m/s) và khoảng giá trị hợp lệ (range). Là nhóm trong interface contract chặn được lỗi kiểu cluster hiểu km/h còn audio hiểu m/s.","aka":["unit/range"]},{"t":"timestamp/freshness/update","vi":"Dấu thời gian lấy mẫu, độ tươi (bao lâu thì coi là cũ) và tần suất cập nhật của dữ liệu. Là nhóm trong interface contract tối thiểu.","aka":["timestamp/freshness/update rate"]},{"t":"valid/stale","vi":"Hợp lệ hay đã cũ: trạng thái cho biết giá trị còn dùng được hay đã quá hạn cập nhật. Interface contract của Vehicle.Speed phải nói rõ cách báo valid/stale."},{"t":"age/stale","vi":"Tuổi tối đa của dữ liệu và chính sách xử lý dữ liệu cũ (stale): quá bao lâu thì coi là cũ và consumer phải làm gì. Cần chốt khi chọn pub/sub cho vehicle signal.","aka":["max age/stale","max age/stale policy"]},{"t":"freshness/cache","vi":"Độ tươi của dữ liệu và cách lưu đệm (cache): giữ bản sao gần nhất bao lâu, khi nào phải lấy mới. Là một quyết định cần chốt cho vehicle-data service."},{"t":"interface/data","vi":"Hợp đồng interface/dữ liệu giữa các bên (producer–consumer, xe–cloud). Trong bài: đây là một dependency làm update rủi ro — đổi một bên mà bên kia chưa đổi thì vỡ.","aka":["interface/data contract","interface/data contracts"]},{"t":"organization/process","vi":"Tổ chức và quy trình: cơ cấu team, vai trò, cách làm việc. Trong comparison matrix có dòng \"Tác động organization/process\" — đổi kiến trúc kéo theo đổi tổ chức và quy trình."},{"t":"centralized/CDC","vi":"Kiến trúc tập trung, ví dụ CDC (Cockpit Domain Controller) hay central compute: compute mạnh phục vụ nhiều function; lợi reuse, update, resource pooling nhưng blast radius, thermal và isolation khó hơn."},{"t":"CDC/HPC","vi":"CDC hoặc HPC: máy tính trung tâm/miền cockpit chạy nhiều partition (AAOS/Linux, RTOS, vehicle services) và middleware SOA trong kiến trúc tham chiếu của bài.","cs":true},{"t":"cockpit/ADAS","vi":"Hai domain cần compute lớn: cockpit (cluster, IVI, âm thanh) và ADAS (hỗ trợ lái). Trong hybrid architecture, central compute thường phục vụ hai domain này."},{"t":"vehicle/edge","vi":"Phía xe (edge — biên mạng, nơi dữ liệu phát sinh), đối lại với cloud. Câu hỏi kiến trúc của bài: phần nào của feature chạy trên vehicle/edge, phần nào trên cloud."},{"t":"signal/service","vi":"Signal và service. Trong reference architecture: logical data model gồm cây signal/service chuẩn, unit, owner của từng nhóm data và nguồn sự thật (source of truth)."},{"t":"variant/configuration","vi":"Biến thể xe và cấu hình phần mềm tương ứng. Trong quality attribute scenario phải ghi variant/configuration áp dụng, vì cùng feature có thể hành xử khác trên variant khác."},{"t":"hardware/firmware","vi":"Phần cứng và firmware của từng xe. Trong bài: update phải khớp hardware/firmware variant và calibration, nếu không có thể lỗi trên một số xe; cần variant matrix và manifest.","aka":["hardware/firmware variant"]},{"t":"platform/library","vi":"Platform hoặc thư viện dùng chung (OS, middleware). Rủi ro update: đổi một platform/library dùng chung ảnh hưởng nhiều feature/domain cùng lúc (blast radius lớn).","aka":["shared platform/library"]},{"t":"feature/domain","vi":"Feature hoặc domain bị ảnh hưởng. Trong bài: update platform dùng chung có thể ảnh hưởng nhiều feature/domain — cần isolation, regression theo feature và staged rollout."},{"t":"backend/cloud","vi":"Hệ thống phía máy chủ/cloud phục vụ xe (API, feature management, OTA, data). Rủi ro trong bài: xe cũ không tương thích API mới, certificate hết hạn — cần versioning API và quản lý certificate.","aka":["cloud/backend","backend/cloud API"]},{"t":"behavior/fallback","vi":"Hành vi tại chỗ và phương án dự phòng khi mất kết nối cloud: service trên xe vẫn chạy được ở mức tối thiểu (dùng dữ liệu đã tải, queue giới hạn) thay vì hỏng.","aka":["local behavior/fallback"]},{"t":"crash/log","vi":"Log và crash dump: nhật ký hoạt động và bản kết xuất khi chương trình sập, gửi về backend để phân tích lỗi trong fleet (có consent và bảo vệ privacy).","aka":["log/crash","log/crash dump"]},{"t":"safety/regulatory","vi":"An toàn và quy định pháp lý. Impact analysis safety/regulatory: đánh giá update có làm mất hiệu lực safety argument hay homologation không, trước khi phát hành."},{"t":"register/bus","vi":"Thanh ghi phần cứng và bus giao tiếp — tầng thấp nhất. Trong bài: feature không nên truy cập register/bus trực tiếp mà dùng capability qua API chuẩn (hardware abstraction)."},{"t":"manifest/variant","vi":"Manifest (mô tả gói phần mềm cần gì) và variant matrix (variant nào có phần cứng/capability nào). Dùng để chặn kích hoạt feature trên variant không hỗ trợ.","aka":["manifest/variant matrix"]},{"t":"container runtime","vi":"Phần mềm khởi chạy và quản lý vòng đời các container (tạo, chạy, dừng, giới hạn tài nguyên). Trong bài là một ví dụ của lớp Runtime, bên cạnh Android Runtime và AUTOSAR Adaptive Execution Management."},{"t":"orchestration","vi":"“Điều phối”: phần mềm tự động quản lý start, restart, update và tài nguyên của nhiều service/container. Trong bài: orchestration trên xe vẫn phải tôn trọng deadline, boot order và degraded mode, không coi tài nguyên là vô hạn.","aka":["orchestrator"]},{"t":"cloud-native","vi":"Phong cách xây phần mềm sinh ra từ điện toán đám mây: chia nhỏ thành service, đóng container, triển khai và cập nhật tự động. Trong bài: đưa cloud-native vào xe (ví dụ SOAFEE) phải kèm ràng buộc timing, safety và tài nguyên giới hạn.","aka":["cloud native"]},{"t":"SOAFEE","vi":"Sáng kiến công nghiệp (do Arm khởi xướng cùng nhiều hãng) đưa cách làm cloud-native/container/orchestration vào máy tính nhúng trên xe. Trong bài: hữu ích cho service linh hoạt nhưng vẫn phải đáp ứng timing và safety.","aka":["Scalable Open Architecture For Embedded Edge"],"full":"Scalable Open Architecture For Embedded Edge","cs":true},{"t":"embedded edge","vi":"“Biên nhúng”: máy tính nhúng nằm ở rìa mạng, gần nơi sinh dữ liệu (ở đây là chính chiếc xe) thay vì trên cloud. Trong bài là môi trường mà SOAFEE nhắm tới."},{"t":"adaptive","vi":"“Thích ứng”. Trong bài thường là viết tắt của <b>AUTOSAR Adaptive<\/b> (Adaptive Platform): nền tảng AUTOSAR cho máy tính mạnh chạy POSIX OS, service-oriented, cấu hình và deployment động lúc runtime."},{"t":"classic","vi":"“Cổ điển”. Trong bài thường là viết tắt của <b>AUTOSAR Classic<\/b> (Classic Platform): nền tảng AUTOSAR cho ECU điều khiển tài nguyên hạn chế, cấu hình tĩnh lúc build, giao tiếp signal/PDU qua RTE/BSW."},{"t":"Adaptive Platform","vi":"Nền tảng AUTOSAR Adaptive: application dùng ARA (ara::com…) gồm các functional cluster, chạy trên POSIX OS, service-oriented. Hợp với compute mạnh và service lifecycle động trong CDC/HPC.","aka":["AUTOSAR Adaptive Platform"]},{"t":"Classic Platform","vi":"Nền tảng AUTOSAR Classic: SWC → RTE → BSW → microcontroller, cấu hình ARXML sinh code lúc build, chạy trên RTOS/OSEK. Hợp với control ECU tài nguyên hạn chế, cần thời gian dự đoán được.","aka":["AUTOSAR Classic Platform"]},{"t":"shutdown","vi":"“Tắt máy”: quá trình hệ thống dừng có kiểm soát. Trong bài: shutdown phải lưu dữ liệu quan trọng, flush log, đóng file system an toàn và hoàn tất/tạm dừng an toàn bản update; làm sai thì lỗi lộ ra ở lần boot sau.","aka":["shutdowns","shut down"]},{"t":"suspend","vi":"“Tạm ngưng”: đưa hệ thống vào trạng thái ngủ thay vì tắt hẳn để bật lại nhanh. Trong bài là một trong các power state cần thiết kế cùng shutdown và resume.","aka":["suspended"]},{"t":"suspend-to-RAM","vi":"Kiểu ngủ giữ RAM có điện (giữ nguyên trạng thái bộ nhớ), tắt phần còn lại; lần sau chỉ cần đánh thức nên khởi động rất nhanh. Trong bài: xe thường dùng cách này để màn hình/camera sẵn sàng sớm.","aka":["suspend to RAM"]},{"t":"resume","vi":"“Tiếp tục”: chạy lại từ chỗ đã dừng. Trong bài: cơ chế cho phép bản OTA đang ghi image bị cắt điện vẫn ghi tiếp được (cùng với A/B slot) để xe không bị “brick”; cũng là đánh thức sau suspend.","aka":["resumed","resuming"]},{"t":"standby","vi":"“Chờ”: trạng thái nguồn tiêu thụ ít điện, sẵn sàng bật nhanh. Trong bài là một trong các power state của xe (off, standby, accessory, running)."},{"t":"accessory","vi":"“Phụ kiện”; ở đây là trạng thái nguồn ACC của xe: bật điện cho thiết bị phụ (radio, màn hình) nhưng chưa nổ máy. Trong bài là một power state mà stack phải xử lý.","aka":["accessories"]},{"t":"power state","vi":"Các trạng thái nguồn của xe/ECU như off, standby, accessory, running, suspend. Trong bài: chuyển trạng thái sai (mất điện khi đang ghi) là nguồn lỗi chỉ lộ ra ở lần boot sau.","aka":["power states"]},{"t":"power-on","vi":"“Bật nguồn”: thời điểm cấp điện, mốc 0 để đo thời gian khởi động. Trong bài: chuỗi đo boot bắt đầu từ power-on → ROM boot → bootloader → … → first valid frame.","aka":["power on"]},{"t":"ROM","vi":"Bộ nhớ chỉ đọc, chứa đoạn mã khởi động đầu tiên do nhà sản xuất chip ghi sẵn. Trong bài: “ROM boot” là bước đầu tiên của chuỗi khởi động, nơi bắt đầu chuỗi secure boot.","aka":["ROM boot"],"full":"Read-Only Memory","cs":true},{"t":"flush","vi":"“Xả”: ghi hết dữ liệu đang nằm tạm trong bộ đệm xuống nơi lưu trữ thật. Trong bài: trước khi shutdown phải flush log để không mất bằng chứng cho lần điều tra sau.","aka":["flushed","flushing","flush log"]},{"t":"file system","vi":"Hệ thống tệp: cách OS tổ chức file và thư mục trên bộ nhớ lưu trữ. Trong bài: shutdown phải đóng file system an toàn; mất điện giữa chừng có thể làm hỏng dữ liệu.","aka":["file systems","filesystem"]},{"t":"logo","vi":"Biểu tượng thương hiệu hiện khi khởi động. Trong bài: lỗi dependency khởi động (service A chờ B vô hạn) làm màn hình kẹt ở logo."},{"t":"launcher","vi":"Màn hình chính/trình khởi chạy app của Android. Trong bài: “AAOS hiện launcher sau ~20 s” là mốc đo khởi động của IVI, khác với mốc cần cho camera lùi (giả định minh họa)."},{"t":"init","vi":"Viết tắt của initialization (khởi tạo); cũng là tiến trình đầu tiên Linux chạy để khởi động các service. Trong bài: thứ tự init quyết định partition/service nào lên trước."},{"t":"boot order","vi":"Thứ tự các thành phần/service được khởi động. Trong bài: orchestration và dependency khởi động phải tôn trọng boot order để chức năng quan trọng (camera lùi, cluster) lên sớm."},{"t":"boot time budget","vi":"Ngân sách thời gian khởi động: chia tổng thời gian cho phép (ví dụ camera lùi phải hiện trong vài giây) cho từng tầng và đo trên target. Trong bài: SA phải xác định ai sở hữu ngân sách này."},{"t":"early-camera path","vi":"Đường hiển thị camera “sớm”: một luồng riêng (thường trên RTOS partition hoặc bootloader) đưa hình camera lùi lên màn hình trước khi Android khởi động xong. Trong bài là lời giải cho mâu thuẫn boot của AAOS.","aka":["early camera path","early-camera"]},{"t":"early","vi":"“Sớm”. Trong bài dùng trong early-camera, early boot: các chức năng phải sẵn sàng sớm trong chuỗi khởi động."},{"t":"ready","vi":"“Sẵn sàng”. Trong bài: cần định nghĩa rõ “ready” nghĩa là gì (OS ready, frame đầu tiên, hay frame hợp lệ người lái thấy) thì mới đo và cam kết boot time được.","aka":["readiness state"]},{"t":"feature-ready","vi":"Sẵn sàng ở mức chức năng: người dùng thật sự dùng được tính năng, không chỉ là OS đã boot. Trong bài: chuỗi dependency khởi động được đo đến mốc feature-ready.","aka":["feature ready"]},{"t":"first valid frame","vi":"Khung hình hợp lệ đầu tiên: frame camera đầu tiên đúng, đủ để hiển thị cho người lái (không đen, không lỗi). Trong bài là mốc đo quan trọng hơn “OS ready”; test first-valid-frame phải chạy lại khi nâng kernel.","aka":["first-valid-frame"]},{"t":"first camera frame","vi":"Frame đầu tiên camera gửi lên sau khi bật, có thể chưa hợp lệ. Trong bài là một mốc trong chuỗi đo boot: power-on → OS ready → first camera frame → first valid frame → driver-visible confirmation."},{"t":"first","vi":"“Đầu tiên”. Trong bài dùng cho các mốc đo khởi động như first camera frame, first valid frame."},{"t":"driver-visible","vi":"“Người lái nhìn thấy được”. Trong bài: driver-visible confirmation là mốc cuối — hình/thông tin thật sự hiện trên màn hình cho người lái, dùng để so với deadline cấp feature.","aka":["driver visible"]},{"t":"confirmation","vi":"“Xác nhận”. Trong bài: driver-visible confirmation là bằng chứng chức năng đã thật sự đến tay người lái.","aka":["confirmations"]},{"t":"layered","vi":"“Phân lớp”: chia hệ thống thành các tầng chồng lên nhau, mỗi tầng chỉ dùng dịch vụ của tầng dưới qua interface. Trong bài: layered diagram/architecture là cách mô tả stack phần mềm xe.","aka":["layering","layered architecture"]},{"t":"layered diagram","vi":"Sơ đồ phân lớp: vẽ stack từ hardware lên application. Trong bài: sơ đồ chỉ có tên lớp mà không có interface, contract và owner ở từng ranh giới thì “chỉ là hình vẽ”; đây là đầu ra bắt buộc của Unit.","aka":["layered diagrams","layered architecture diagram","layered architecture","classic layered architecture"]},{"t":"integrator","vi":"“Người tích hợp”: team/đơn vị ghép các phần của nhiều bên thành sản phẩm chạy được và chịu trách nhiệm tổ hợp cuối. Trong bài: integrator sở hữu cấu hình và integration image, thường là incident owner khi sự cố xuyên lớp.","aka":["integrators","system integrator","system integrators"]},{"t":"integration image","vi":"Bản phần mềm tổng hợp cuối cùng (mọi lớp, mọi version) nạp vào ECU. Trong bài: phải có một owner chịu trách nhiệm “cả tòa nhà” này, kèm version manifest."},{"t":"integration model","vi":"Cách thức chuẩn để ghép các thành phần (ai cung cấp gì, cấu hình ra sao, giao tiếp thế nào). Trong bài: điểm mạnh của AUTOSAR là chuẩn hóa integration model giữa OEM và supplier."},{"t":"integration cost","vi":"Chi phí (công sức, thời gian, tiền) để tích hợp một nền tảng vào hệ thống. Trong bài là một trade-off khi chọn QNX: ecosystem nhỏ hơn, cần port driver/tool."},{"t":"version manifest","vi":"Danh sách version của mọi thành phần trong một image. Trong bài: cần cho reproducible build, cho việc điều tra sự cố (biết chính xác cái gì đang chạy) và cho compatibility.","aka":["version manifests"]},{"t":"incident owner","vi":"Người được giao điều phối một sự cố từ đầu đến cuối (không nhất thiết là người sửa). Trong bài: gán ngay từ đầu, thường là owner use case/feature hoặc system integrator, để sự cố xuyên lớp không bị đẩy qua đẩy lại.","aka":["incident owners"]},{"t":"update model","vi":"Mô hình cập nhật: phần mềm được cập nhật thế nào, bao lâu một lần, ai làm, có kéo theo phần khác không. Trong bài: IVI cập nhật thường xuyên còn cluster thì không được bị kéo theo, nên update model ảnh hưởng cách chia partition.","aka":["update models"]},{"t":"resource management","vi":"Quản lý tài nguyên: chia ngân sách chung (CPU, memory, GPU, I/O, bandwidth, power) giữa các workload và giới hạn chúng. Trong bài: real-time trên giấy vô nghĩa nếu lúc chạy một app khác ăn hết tài nguyên."},{"t":"resource policy","vi":"Chính sách tài nguyên: quy tắc ưu tiên/giới hạn tài nguyên cho app. Trong bài: Android dùng resource policy, Linux dùng cgroups/quota, hypervisor và AUTOSAR Classic phân bổ tĩnh.","aka":["resource policies"]},{"t":"memory contention","vi":"Tranh chấp bộ nhớ: nhiều workload cùng tranh memory, cache, bus nên làm nhau chậm dù không gọi nhau. Trong bài là lý do “nhanh trung bình” chưa chắc real-time khi chia sẻ compute."},{"t":"device interference","vi":"Ảnh hưởng chéo qua thiết bị dùng chung (GPU, storage, network…): workload này làm thiết bị bận khiến workload khác trễ. Trong bài là một yếu tố phải xét khi nhiều workload chia sẻ SoC."},{"t":"device sharing","vi":"Chia sẻ thiết bị phần cứng (GPU, display, network) giữa nhiều VM/partition. Trong bài là vấn đề chính của lớp hypervisor: thêm latency và interference."},{"t":"deterministic","vi":"“Tất định”: cùng đầu vào thì luôn cho kết quả và thời gian như nhau, dự đoán được. Trong bài: RTOS ưu tiên deterministic latency (độ trễ ổn định) thay vì nhanh trung bình.","aka":["deterministically"]},{"t":"deterministic latency","vi":"Độ trễ ổn định, có cận trên dự đoán được kể cả trường hợp xấu nhất. Trong bài: đây là điều RTOS/real-time cần, khác với throughput cao mà Linux thường tối ưu."},{"t":"determinism","vi":"Tính tất định: hành vi và thời gian dự đoán được. Trong bài là điểm mạnh của QNX/RTOS (cùng fault containment), đối lập với flexibility của Linux."},{"t":"flexibility","vi":"“Tính linh hoạt”: dễ thay đổi, mở rộng, tùy biến. Trong bài là điểm mạnh của Linux (cùng ecosystem, apps), đổi lại phải tự lo latency tuning, hardening, patch."},{"t":"POSIX","vi":"Bộ chuẩn API kiểu Unix (file, process, thread, socket…) để phần mềm dễ chuyển giữa các OS. Trong bài: Linux và QNX đều hỗ trợ POSIX; AUTOSAR Adaptive chạy trên POSIX OS.","aka":["Portable Operating System Interface","POSIX API","POSIX OS"],"full":"Portable Operating System Interface","cs":true},{"t":"POSIX-based","vi":"“Dựa trên POSIX”: OS hỗ trợ chuẩn API POSIX (Linux, QNX…). Trong bài: AUTOSAR Adaptive cần một POSIX-based OS, còn Classic chạy trên RTOS/OSEK.","aka":["POSIX based"]},{"t":"Unix","vi":"Họ hệ điều hành ra đời từ thập niên 1970, là khuôn mẫu cho Linux và chuẩn POSIX. Trong bài: POSIX là “bộ API chuẩn kiểu Unix” mà Linux và QNX đều hỗ trợ."},{"t":"system call","vi":"Lời gọi hệ thống: cách chương trình nhờ kernel làm việc đặc quyền (mở file, cấp memory, gửi dữ liệu). Trong bài là loại API thấp nhất mà lớp OS cung cấp cho lớp trên.","aka":["system calls","syscall","syscalls"]},{"t":"call","vi":"“Gọi”: một phần mềm yêu cầu phần khác thực hiện việc gì đó (gọi hàm, gọi API, gọi service). Trong bài: system call, call chain (chuỗi lời gọi xuyên lớp).","aka":["calls","called","calling"]},{"t":"Application Programming Interface","vi":"Tên đầy đủ của <b>API<\/b>: “menu món” mà lớp dưới công bố để lớp trên gọi, gồm hàm, tham số, kiểu dữ liệu và quy ước.","cs":true},{"t":"programming","vi":"“Lập trình”. Trong bài xuất hiện trong Application Programming Interface (API)."},{"t":"message passing","vi":"Truyền thông điệp: các tiến trình trao đổi bằng cách gửi/nhận message thay vì dùng chung bộ nhớ. Trong bài: là cơ chế nền tảng của QNX microkernel (driver, file system đều là process nói chuyện qua message)."},{"t":"passing","vi":"“Chuyển, truyền”. Trong bài xuất hiện trong message passing (truyền thông điệp) của QNX."},{"t":"message queue","vi":"Hàng đợi thông điệp: kênh IPC trong đó process gửi message vào hàng đợi và process khác lấy ra theo thứ tự. Trong bài là một cơ chế IPC trong một OS.","aka":["message queues"]},{"t":"socket","vi":"“Ổ cắm”: điểm đầu cuối để gửi/nhận dữ liệu qua mạng hoặc giữa các process. Trong bài là một cơ chế IPC trong OS, nền của TCP/UDP và SOME/IP.","aka":["sockets"]},{"t":"pipe","vi":"“Ống”: kênh IPC một chiều kiểu Unix, đầu ra của process này chảy vào đầu vào process khác. Trong bài là một cơ chế IPC trong một OS.","aka":["pipes"]},{"t":"Binder","vi":"Cơ chế IPC riêng của Android (driver trong kernel + thư viện) để app và service gọi nhau, kèm kiểm tra danh tính/permission. Trong bài: lớp middleware/IPC phía AAOS (Car API → CarService đi qua Binder)."},{"t":"virtual device","vi":"Thiết bị ảo do hypervisor giả lập cho VM (ví dụ qua VirtIO). Trong bài là một kênh giao tiếp giữa VM/partition, cùng với shared memory có kiểm soát và virtual network.","aka":["virtual devices"]},{"t":"virtual network","vi":"Mạng ảo do hypervisor tạo để các VM trên cùng SoC nói chuyện như qua Ethernet. Trong bài là một kênh IPC giữa VM/partition.","aka":["virtual networks"]},{"t":"FD","vi":"“Tốc độ dữ liệu linh hoạt”, phần đuôi trong CAN FD: cho phép truyền pha dữ liệu nhanh hơn và payload dài hơn CAN cổ điển.","full":"Flexible Data-rate","cs":true},{"t":"PDU","vi":"Đơn vị dữ liệu của giao thức: một gói dữ liệu trên bus (ví dụ khung CAN chứa nhiều signal). Trong bài: AUTOSAR Classic giao tiếp theo Signal/PDU qua RTE/BSW, khác với service của Adaptive.","aka":["PDUs","Protocol Data Unit"],"full":"Protocol Data Unit","cs":true},{"t":"RX","vi":"Chiều nhận dữ liệu (TX là chiều gửi). Trong bài: đếm counter interrupt/RX của network controller để xem driver có còn nhận frame không khi điều tra lỗi.","aka":["Rx"],"full":"Receive","cs":true},{"t":"network controller","vi":"Bộ điều khiển mạng: phần cứng nhận/gửi frame (CAN, Ethernet) và báo interrupt cho CPU. Trong bài: chặng Driver/BSP của luồng tốc độ bắt đầu ở đây.","aka":["network controllers"]},{"t":"interrupt coalescing","vi":"Gộp interrupt: card mạng chờ gom nhiều frame rồi mới báo một interrupt để tiết kiệm CPU, đổi lại tăng độ trễ. Trong bài: BSP đổi cấu hình này làm tốc độ trên cluster trễ dù test chức năng vẫn pass."},{"t":"coalescing","vi":"“Gộp lại”. Trong bài: interrupt coalescing — gộp nhiều sự kiện vào một interrupt để giảm tải CPU nhưng làm tăng latency."},{"t":"OOM","vi":"Hết bộ nhớ: khi RAM cạn, OS phải giết bớt process (OOM kill). Trong bài: biểu hiện ở lớp OS khi workload không bị giới hạn memory, có thể giết nhầm service quan trọng.","aka":["Out Of Memory","out of memory","OOM kill","OOM killer"],"full":"Out Of Memory","cs":true},{"t":"fragmentation","vi":"Phân mảnh: bộ nhớ bị chia vụn thành nhiều mẩu nhỏ rời rạc, tổng còn nhiều nhưng không cấp được khối lớn. Trong bài là rủi ro memory cần tránh khi chạy dài ngày.","aka":["fragmented"]},{"t":"flash wear","vi":"Mòn flash: bộ nhớ flash chỉ chịu được số lần ghi giới hạn, ghi quá nhiều (ví dụ log flood) sẽ hỏng sớm. Trong bài là một loại tài nguyên cần quản lý cùng storage I/O."},{"t":"storage I/O","vi":"Đọc/ghi bộ nhớ lưu trữ (eMMC, UFS, SSD). Trong bài là tài nguyên dùng chung: app log flood làm storage I/O nghẽn, kéo chậm cả kernel và các process khác."},{"t":"IO","vi":"Cách viết khác của I/O: vào/ra dữ liệu (đọc cảm biến, bus, storage). Trong bài: chuỗi câu hỏi workload → deadline/safety → data/IO → update model.","full":"Input/Output","cs":true},{"t":"cgroups","vi":"Cơ chế của Linux đặt giới hạn CPU/memory/I/O cho một nhóm process. Trong bài: đặt cgroup cho app bản đồ để nó không ăn hết CPU của vehicle-data service.","aka":["cgroup","control groups","control group"],"full":"control groups"},{"t":"CPU isolation","vi":"Cô lập CPU: dành riêng một số lõi CPU cho workload quan trọng, không cho tác vụ khác chạy chen. Trong bài là một biện pháp (cùng PREEMPT_RT, IRQ affinity) để Linux đạt latency tốt hơn."},{"t":"starvation","vi":"“Bỏ đói”: một tác vụ chờ mãi không được cấp CPU/tài nguyên vì tác vụ khác chiếm hết. Trong bài là một biểu hiện lỗi ở lớp OS cùng deadline miss và crash."},{"t":"throttling","vi":"“Bóp ga”: chip tự giảm xung nhịp khi quá nóng hoặc thiếu điện. Trong bài: biểu hiện ở lớp hardware/power/thermal làm UI giật, ảnh hưởng mọi lớp phía trên.","aka":["thermal throttling","throttled"]},{"t":"flicker","vi":"“Nhấp nháy”: hình ảnh chớp tắt bất thường. Trong bài: interrupt bị mất ở lớp driver có thể gây display flicker, camera đen.","aka":["flickering"]},{"t":"flood","vi":"“Lũ”: lượng lớn bất thường. Log flood là app ghi log ồ ạt, làm nghẽn storage I/O, mòn flash và kéo chậm cả partition — ví dụ lỗi lan truyền đi xuống trong bài.","aka":["log flood","log flooding","flooding","floods"]},{"t":"masking","vi":"“Che giấu”: lỗi bị lớp khác che đi (retry, cache, giá trị mặc định, nuốt error code) nên lộ ra muộn và ở chỗ khác. Trong bài là một kiểu error propagation khó triage.","aka":["masked","mask"]},{"t":"upward","vi":"“Đi lên”: kiểu lan truyền lỗi từ lớp dưới lên — lớp dưới trả dữ liệu sai/trễ, lớp trên chỉ thấy hậu quả. Ví dụ trong bài: triệu chứng ở application, nguyên nhân ở driver/BSP."},{"t":"downward","vi":"“Đi xuống”: kiểu lan truyền lỗi từ lớp trên xuống — lớp trên lạm dụng tài nguyên chung (log flood) làm lớp dưới “có vẻ” lỗi."},{"t":"lateral","vi":"“Ngang”: kiểu lan truyền lỗi giữa hai workload không gọi nhau nhưng chia sẻ CPU, cache, bus, GPU, device. Trong bài: chỉ thấy khi trace tài nguyên chung."},{"t":"propagation","vi":"“Lan truyền”. Trong bài: error/failure propagation — lỗi ở một lớp hoặc domain lan sang chỗ khác theo hướng lên, xuống hoặc ngang."},{"t":"cross-ECU","vi":"“Xuyên ECU”: liên quan tới nhiều ECU qua mạng xe. Trong bài: lỗi middleware/IPC có thể lộ ra cross-ECU (message trễ, mất, lệch version).","aka":["cross ECU"]},{"t":"microkernel","vi":"Kernel tối giản: chỉ giữ scheduling, IPC, quản lý memory; driver, file system, network chạy thành process riêng ngoài kernel. Trong bài: kiến trúc của QNX, giúp fault containment — driver lỗi có thể restart mà không sập cả hệ thống.","aka":["microkernels","micro-kernel"]},{"t":"reliability","vi":"“Độ tin cậy”: khả năng chạy đúng liên tục trong thời gian dài. Trong bài là một lý do chọn QNX, cùng latency dự đoán được và isolation."},{"t":"safety-certified","vi":"“Đã được chứng nhận an toàn” theo chuẩn như ISO 26262 (kèm bằng chứng, quy trình). Trong bài: Linux không tự động là safety-certified; QNX có bản chứng nhận nhưng evidence vẫn phụ thuộc toàn hệ thống.","aka":["safety certified"]},{"t":"hardening","vi":"“Gia cố”: tắt tính năng, cổng, service thừa và siết cấu hình để giảm bề mặt tấn công. Trong bài: trách nhiệm của người tích hợp khi dùng Linux.","aka":["harden","hardened"]},{"t":"mainline","vi":"Nhánh chính thức của Linux kernel do cộng đồng duy trì. Trong bài: PREEMPT_RT đã vào mainline từ kernel 6.12, không còn là bản patch ngoài.","aka":["upstream mainline"]},{"t":"WCET evidence","vi":"Bằng chứng về thời gian chạy xấu nhất (Worst-Case Execution Time) của tác vụ, từ phân tích hoặc đo. Trong bài: PREEMPT_RT giảm latency nhưng không tự tạo WCET evidence."},{"t":"soft","vi":"“Mềm”. Trong bài: soft real-time — trễ thỉnh thoảng chấp nhận được (ví dụ rớt một frame video), đối lập với hard real-time."},{"t":"taxi","vi":"Xe taxi. Trong bài là phép so sánh: taxi thường nhanh hơn xe buýt nhưng có hôm muộn 30 phút nên không “real-time”; real-time là dự đoán được, không phải nhanh."},{"t":"Android Auto","vi":"Tính năng của Google chạy trên <b>điện thoại<\/b> và chiếu giao diện lên màn hình xe. Trong bài: khác hẳn AAOS — AAOS là OS chạy trực tiếp trên phần cứng xe."},{"t":"auto","vi":"“Ô tô / tự động”. Trong bài xuất hiện trong Android Auto (chiếu điện thoại lên màn hình xe), không phải AAOS."},{"t":"Car API","vi":"Bộ API của Android Automotive cho app đọc/ghi dữ liệu xe (tốc độ, HVAC…). Trong bài: đường đi App → Car API → CarService → Vehicle HAL → mạng xe/ECU.","aka":["Car APIs"]},{"t":"car","vi":"“Xe ô tô”. Trong bài xuất hiện trong Car API, CarService của Android Automotive.","aka":["cars"]},{"t":"CarService","vi":"Service hệ thống của AAOS đứng giữa Car API và Vehicle HAL, kiểm tra app có permission đọc/ghi property xe hay không. Trong bài là một chặng của luồng vehicle data.","cs":true},{"t":"Vehicle HAL","vi":"Hardware Abstraction Layer cho dữ liệu xe trong AAOS: công bố property (tốc độ, số, nhiệt độ…) với unit, update rate, quyền truy cập. Trong bài: là boundary do OEM/Tier-1 hiện thực, nối Android với mạng xe/ECU.","aka":["Vehicle HALs"]},{"t":"VHAL","vi":"Viết tắt của Vehicle HAL trong Android Automotive: lớp chuẩn hóa property xe cho Android. Trong bài: freshness timeout của tốc độ trên VHAL là một câu hỏi phải chốt.","full":"Vehicle Hardware Abstraction Layer","cs":true},{"t":"Android Runtime","vi":"Môi trường chạy app của Android (thực thi bytecode, quản lý bộ nhớ, vòng đời app). Trong bài là ví dụ của lớp Runtime.","full":"ART"},{"t":"Android framework API","vi":"Bộ API Java/Kotlin mà framework Android cung cấp cho app (UI, permission, Car API…). Trong bài là một loại API giữa các lớp.","aka":["framework API","framework APIs"]},{"t":"API level","vi":"Số hiệu phiên bản API của Android; app khai báo API level tối thiểu/mục tiêu. Trong bài là ví dụ quy tắc version để biết thay đổi có tương thích không.","aka":["API levels"]},{"t":"BSW","vi":"Lớp phần mềm nền của AUTOSAR Classic: Services, ECU Abstraction, MCAL, Complex Drivers. Trong bài: BSW thường do vendor cung cấp, integrator cấu hình.","full":"Basic Software","cs":true},{"t":"Basic Software","vi":"Tên đầy đủ của BSW trong AUTOSAR Classic: các lớp dịch vụ (communication, memory, diagnostics), ECU Abstraction và MCAL nằm dưới RTE."},{"t":"basic","vi":"“Cơ bản”. Trong bài xuất hiện trong Basic Software (BSW) của AUTOSAR Classic."},{"t":"RTE","vi":"Lớp “tổng đài” của AUTOSAR Classic nối các SWC với nhau và với BSW; được sinh code tự động (RTE generator) từ cấu hình ARXML lúc build. SWC chỉ giao tiếp qua RTE.","aka":["Runtime Environment","RTE generator"],"full":"Runtime Environment","cs":true},{"t":"generator","vi":"“Bộ sinh”: công cụ tự sinh mã nguồn từ cấu hình. Trong bài: RTE generator của AUTOSAR thường do vendor cung cấp.","aka":["generators","code generator"]},{"t":"SWC","vi":"Thành phần phần mềm ứng dụng trong AUTOSAR Classic, chỉ giao tiếp qua RTE. Trong bài: SWC/application thường do OEM hoặc feature team sở hữu.","aka":["SWCs"],"full":"Software Component","cs":true},{"t":"MCAL","vi":"Lớp thấp nhất của BSW AUTOSAR Classic: driver sát vi điều khiển (ADC, CAN, GPIO…), giúp phần trên không phụ thuộc chip. Trong bài: thường do vendor chip cung cấp.","aka":["Microcontroller Abstraction Layer"],"full":"Microcontroller Abstraction Layer","cs":true},{"t":"Microcontroller Abstraction","vi":"Lớp trừu tượng vi điều khiển (MCAL) trong BSW: che giấu khác biệt phần cứng của MCU để lớp trên dùng giao diện chung."},{"t":"ECU Abstraction","vi":"Lớp trừu tượng ECU trong BSW AUTOSAR Classic: che giấu cách bo mạch ECU nối dây ngoại vi, để dịch vụ phía trên không phụ thuộc layout phần cứng cụ thể."},{"t":"Complex Drivers","vi":"Driver đặc biệt trong AUTOSAR Classic đi thẳng từ RTE xuống phần cứng, dùng cho chức năng yêu cầu timing chặt hoặc phần cứng không chuẩn.","aka":["Complex Device Drivers","Complex Driver"]},{"t":"complex","vi":"“Phức tạp”. Trong bài xuất hiện trong Complex Drivers của AUTOSAR Classic."},{"t":"OSEK","vi":"Chuẩn RTOS ô tô cũ (Đức, thập niên 1990) với task, event, scheduling tĩnh. Trong bài: AUTOSAR Classic chạy trên RTOS/OSEK.","aka":["OSEK/VDX"],"cs":true},{"t":"ARXML","vi":"File XML mô tả AUTOSAR: SWC, port, signal, cấu hình BSW. Trong bài: cấu hình ARXML được sinh code lúc build cho AUTOSAR Classic.","full":"AUTOSAR XML","cs":true},{"t":"XML","vi":"Ngôn ngữ đánh dấu dạng thẻ để lưu dữ liệu có cấu trúc. Trong bài: ARXML là file XML mô tả cấu hình AUTOSAR.","full":"eXtensible Markup Language","cs":true},{"t":"ARA","vi":"Bộ API chuẩn mà application AUTOSAR Adaptive dùng, chia thành các functional cluster (ara::com, Execution Management…).","aka":["AUTOSAR Runtime for Adaptive Applications"],"full":"AUTOSAR Runtime for Adaptive Applications","cs":true},{"t":"ara::com","vi":"API giao tiếp của AUTOSAR Adaptive (Communication Management): service, method, event, field, có thể chạy trên SOME/IP hoặc DDS. Trong bài là một ví dụ middleware/IPC.","cs":true},{"t":"functional cluster","vi":"Nhóm chức năng của AUTOSAR Adaptive Platform, mỗi nhóm cung cấp một phần API ARA: Communication Management, Execution Management, State Management, Log and Trace, Diagnostics, Update and Configuration Management…","aka":["functional clusters"]},{"t":"Communication Management","vi":"Functional cluster của AUTOSAR Adaptive lo giao tiếp service (ara::com): tìm service, gọi method, nhận event."},{"t":"Execution Management","vi":"Functional cluster của AUTOSAR Adaptive khởi chạy, dừng và giám sát các process ứng dụng theo cấu hình. Trong bài là ví dụ của lớp Runtime.","aka":["AUTOSAR Adaptive Execution Management"]},{"t":"State Management","vi":"Functional cluster của AUTOSAR Adaptive quản lý trạng thái máy/chức năng (startup, running, shutdown) và yêu cầu Execution Management chuyển trạng thái."},{"t":"ownership boundary","vi":"Ranh giới sở hữu: đường phân chia ai chịu trách nhiệm phần nào. Trong bài: AUTOSAR thường có SWC do OEM, BSW/MCAL/RTE generator do vendor, cấu hình do integrator.","aka":["ownership boundaries"]},{"t":"service lifecycle","vi":"Vòng đời service: khởi tạo, chạy, cập nhật, dừng, khởi động lại. Trong bài: Adaptive hợp với service lifecycle động (thêm/sửa service lúc runtime).","aka":["service lifecycles"]},{"t":"control ECU","vi":"ECU điều khiển chức năng vật lý (phanh, động cơ, thân xe) với tài nguyên hạn chế và timing chặt. Trong bài: AAOS không thay thế control ECU; AUTOSAR Classic hợp với loại ECU này.","aka":["control ECUs"]},{"t":"vehicle service","vi":"Dịch vụ cung cấp dữ liệu/chức năng xe (tốc độ, cửa, HVAC) qua interface chuẩn hóa. Trong bài: nên expose vehicle service thay vì cho app đọc raw bus signal.","aka":["vehicle services"]},{"t":"domain service","vi":"Service phục vụ một miền chức năng (body, energy, gateway…) chạy trên máy tính miền/trung tâm. Trong bài là loại workload hợp với Linux.","aka":["domain services"]},{"t":"device file","vi":"File đặc biệt (kiểu /dev/…) mà OS dùng để app truy cập driver trực tiếp. Trong bài: app IVI mở thẳng device file của CAN driver là cách sai — phụ thuộc implementation detail, đổi bus là hỏng.","aka":["device files"]},{"t":"detail","vi":"“Chi tiết”. Trong bài: implementation detail — chi tiết bên trong không nên bị lớp trên phụ thuộc.","aka":["details"]},{"t":"app isolation","vi":"Cô lập app: mỗi app chạy trong vùng riêng, không đọc/ghi dữ liệu hay làm hỏng app khác. Trong bài là một điểm phải kiểm tra khi đưa AAOS vào xe."},{"t":"driver availability","vi":"Mức sẵn có của driver cho phần cứng cụ thể trên một OS. Trong bài là trade-off của QNX: ít driver sẵn hơn Linux."},{"t":"use-case flow","vi":"Luồng use case: đường đi của một chức năng qua các lớp, kèm interface, budget và owner từng bước. Trong bài: là xương sống của đầu ra Unit, cùng với layered diagram.","aka":["use case flow","use-case flows"]},{"t":"feature flow","vi":"Luồng feature: lần theo một chức năng (ví dụ tốc độ lên cluster) đi xuyên stack từ sensor tới màn hình, với budget và version từng chặng.","aka":["feature flows"]},{"t":"feature-data-flow","vi":"Luồng dữ liệu của feature: sơ đồ dữ liệu của một chức năng đi qua các lớp/partition. Trong bài là một loại diagram phải có ownership tại mọi ranh giới.","aka":["feature data flow"]},{"t":"workload-to-OS","vi":"Ánh xạ workload sang OS/VM: quyết định mỗi workload chạy trên Linux, AAOS, QNX hay AUTOSAR, partition nào. Trong bài là nội dung “Platform choice” của rubric.","aka":["workload to OS"]},{"t":"system-software","vi":"Phần mềm hệ thống: các lớp nền (BSP, OS, hypervisor, middleware, runtime) nằm giữa phần cứng và application. Trong bài: bài nộp là một bản system-software design.","aka":["system software"]},{"t":"unavailable","vi":"“Không khả dụng”: dữ liệu/service chưa có hoặc không thể cung cấp. Trong bài: trạng thái valid/stale/unavailable của tín hiệu; chưa có dữ liệu đầu tiên thì báo unavailable, không gửi 0."},{"t":"available","vi":"“Khả dụng, sẵn có”. Trong bài: trạng thái available/unavailable của service là một phần của interface contract."},{"t":"method","vi":"“Phương thức”: một thao tác có thể gọi trên service (gửi yêu cầu, nhận kết quả). Trong bài: interface contract liệt kê operation/method/event của service.","aka":["methods"]},{"t":"float","vi":"Kiểu số thực dấu phẩy động. Trong bài: kiểu dữ liệu của event VehicleSpeed trong ví dụ interface contract.","aka":["floating-point"]},{"t":"async","vi":"Bất đồng bộ: gửi yêu cầu rồi làm việc khác, kết quả về sau (callback/event), không đứng chờ. Trong bài: contract phải nói rõ sync/async.","aka":["asynchronous"],"full":"asynchronous"},{"t":"client","vi":"“Bên dùng”: phần mềm gọi/nhận dịch vụ do service khác cung cấp. Trong bài: service VehicleSpeed phục vụ nhiều client qua SOME/IP.","aka":["clients"]},{"t":"minor","vi":"“Nhỏ”: số giữa trong version major.minor.patch, tăng khi thêm tính năng tương thích ngược. Trong bài: thêm field mới = minor; đổi unit = major."},{"t":"major.minor.patch","vi":"Cách đánh số semantic versioning: major (thay đổi phá tương thích), minor (thêm tính năng tương thích), patch (sửa lỗi). Trong bài là ví dụ quy tắc version cho interface."},{"t":"semantic versioning","vi":"Quy ước đánh version major.minor.patch để version tự nói lên mức tương thích của thay đổi. Trong bài là một quy tắc versioning cho API/interface.","aka":["SemVer"]},{"t":"linker","vi":"Công cụ ghép các file đối tượng và thư viện thành chương trình chạy được. Trong bài là một phần toolchain (compiler, linker, build tool) mà mọi lớp phụ thuộc.","aka":["linkers"]},{"t":"DLT","vi":"Chuẩn log/trace của AUTOSAR (thường dùng cả trên Linux trong xe), gửi log có timestamp, mức độ, ID ứng dụng tới công cụ đọc. Trong bài là cơ chế log/trace chuẩn để điều tra.","aka":["Diagnostic Log and Trace"],"full":"Diagnostic Log and Trace","cs":true},{"t":"UDS","vi":"Giao thức chẩn đoán chuẩn (ISO 14229) để công cụ xưởng đọc DTC, đọc dữ liệu, flash phần mềm vào ECU. Trong bài là phần Diagnostics của observability.","aka":["Unified Diagnostic Services"],"full":"Unified Diagnostic Services","cs":true},{"t":"unified","vi":"“Thống nhất”. Trong bài xuất hiện trong Unified Diagnostic Services (UDS)."},{"t":"diag","vi":"Viết tắt thông dụng của diagnostics (chẩn đoán). Trong bài: service diag thuộc lớp Service/framework cùng Vehicle HAL, vehicle-data, log.","aka":["diag service"]},{"t":"RPM","vi":"Số vòng quay mỗi phút, ở đây là vòng tua động cơ. Trong bài là một signal ví dụ (cùng speed, telltale) để lần theo từ MCU tới HMI.","full":"Revolutions Per Minute","cs":true},{"t":"passthrough","vi":"“Cho đi thẳng”: giao thẳng một thiết bị vật lý (GPU, card mạng) cho một VM dùng độc quyền, không giả lập. Trong bài: đối lập với chia sẻ GPU qua VirtIO.","aka":["pass-through","pass through"]},{"t":"normalization","vi":"“Chuẩn hóa”: đưa dữ liệu về định dạng, đơn vị, ý nghĩa thống nhất. Trong bài: vehicle service tập trung việc normalization tín hiệu thay vì mỗi app tự xử lý raw signal.","aka":["normalize","normalized"]},{"t":"experiment","vi":"“Thí nghiệm”: thử có kiểm soát để kiểm chứng giả thuyết (đổi một yếu tố, đo kết quả). Trong bài: dùng trace, metric hoặc controlled experiment để xác nhận root-cause hypothesis.","aka":["experiments"]},{"t":"validates","vi":"“Xác nhận đúng”: kiểm chứng bằng bằng chứng. Trong bài: experiment validates một giả thuyết nguyên nhân gốc."},{"t":"root-cause","vi":"Dạng gạch nối của root cause (nguyên nhân gốc), dùng như tính từ: root-cause hypothesis là giả thuyết về nguyên nhân gốc cần được kiểm chứng."},{"t":"failure injection","vi":"Cố ý gây lỗi (rút sensor, giết service, làm nghẽn bus) để xem hệ thống phát hiện, cô lập và phục hồi ra sao. Trong bài: bài nộp cần failure-injection hoặc stress-test plan với tiêu chí containment và recovery.","aka":["failure-injection"]},{"t":"stress-test","vi":"Dạng gạch nối của stress test: thử tải nặng/khắc nghiệt để tìm giới hạn. Trong bài: stress-test plan là một đầu ra của bài nộp."},{"t":"choice","vi":"“Lựa chọn”. Trong bài: Platform choice — chọn OS/VM cho từng workload kèm lý do.","aka":["choices"]},{"t":"every","vi":"“Mọi, mỗi”. Trong bài: ownership at every boundary — mọi ranh giới trên sơ đồ đều phải có owner."},{"t":"showing","vi":"“Thể hiện”. Trong bài: service contract showing versioning, timeout/freshness — contract phải ghi rõ các mục này."},{"t":"Deep Dive","vi":"“Lặn sâu”: phần đi sâu chi tiết vào một chủ đề. Trong bài là tên phần câu hỏi ôn tập System Software Stack Deep Dive.","aka":["deep-dive"]},{"t":"non-critical","vi":"Không quan trọng về an toàn. Trong bài là nhóm workload mà lỗi chỉ ảnh hưởng trải nghiệm (media, app bên thứ ba, analytics, UI phụ): được phép restart hoặc giảm tính năng, bị giới hạn (cap) tài nguyên và là nguồn interference chính cần kiểm soát.","aka":["non critical","noncritical"]},{"t":"mission-critical","vi":"Quan trọng cho nhiệm vụ chính. Trong bài là nhóm workload không trực tiếp gây hại cho người nhưng nếu mất thì mất chức năng chính, ảnh hưởng dịch vụ, tuân thủ hoặc kinh doanh (OTA agent, diagnostic, telematics, logging phục vụ RCA).","aka":["mission critical"]},{"t":"mission","vi":"Nhiệm vụ, sứ mệnh. Trong bài là cách gọi tắt nhóm <b>mission-critical<\/b> (nằm giữa safety và non-critical), ví dụ \"tính năng mission\" chỉ bị cắt sau khi đã cắt hết phần non-critical."},{"t":"cross-load","vi":"Tải chéo: cho workload bên này chạy quá tải trong khi đo bên kia. Trong bài, worst-case/P99 của phía critical phải được đo dưới cross-load từ phía non-critical thì mới là evidence về timing isolation.","aka":["cross load"]},{"t":"cross-load test","vi":"Bài test tải chéo: cố tình đẩy phía non-critical (AAOS, media…) lên quá tải rồi đo deadline, latency, recovery của phía critical. Là bằng chứng chính cho FFI về timing và tài nguyên.","aka":["cross-load tests"]},{"t":"vCPU","vi":"CPU ảo mà guest nhìn thấy. Hypervisor quyết định vCPU chạy trên core thật nào và lúc nào; có thể gán (pin) vCPU vào core riêng và đặt budget/period để giữ timing cho workload critical.","aka":["vCPUs","VCPU"],"full":"virtual CPU","cs":true},{"t":"IOMMU","vi":"Bộ quản lý địa chỉ bộ nhớ cho thiết bị (\"MMU dành cho device\"): giới hạn vùng memory mà một device được đọc/ghi qua DMA. Trong bài, thiếu IOMMU thì device của guest này có thể ghi vào memory của guest khác, phá spatial isolation.","full":"Input-Output Memory Management Unit","cs":true},{"t":"SMMU","vi":"Tên của IOMMU trên kiến trúc Arm. Hypervisor cấu hình SMMU để mỗi device chỉ DMA được vào vùng memory của guest sở hữu nó.","full":"System Memory Management Unit","cs":true},{"t":"MMU","vi":"Bộ quản lý bộ nhớ của CPU: dịch địa chỉ ảo sang địa chỉ thật và chặn truy cập trái phép. Trong bài: hàng rào memory dựng bằng MMU chỉ áp cho CPU; device dùng DMA đi vòng qua MMU nên cần thêm IOMMU/SMMU.","full":"Memory Management Unit","cs":true},{"t":"Direct Memory Access","vi":"Tên đầy đủ của DMA – truy cập bộ nhớ trực tiếp: thiết bị (card mạng, GPU, storage) tự đọc/ghi RAM không qua CPU/MMU. Trong bài, nếu không có IOMMU/SMMU giới hạn thì DMA là đường phá isolation giữa các guest."},{"t":"RT guest","vi":"Guest thời gian thực: VM/partition chạy RTOS (vd QNX) cho chức năng cần deadline. Bài yêu cầu chứng minh RT guest vẫn giữ deadline khi AAOS bên cạnh quá tải hoặc crash.","aka":["RT guests"]},{"t":"idle","vi":"Rảnh, không tải. Trong bài: đo latency lúc hệ thống idle là chưa đủ, vì rủi ro thật xuất hiện khi các guest khác đang tranh cache, bus, interrupt, queue."},{"t":"epoch","vi":"Kỷ nguyên/đời. Trong bài, <b>producer epoch<\/b> là số tăng mỗi lần bên ghi khởi động lại; ghép với sequence number để bên đọc phân biệt dữ liệu mới sau restart với dữ liệu cũ (stale).","aka":["epochs"]},{"t":"seq","vi":"Viết tắt của sequence number – số thứ tự tăng dần gắn vào mỗi message/bản ghi. Trong bài: nếu consumer chỉ xét seq thì sau khi producer restart (seq về 1) sẽ coi dữ liệu mới là cũ.","full":"sequence number"},{"t":"paravirtual","vi":"Ảo hóa \"biết mình là ảo\": guest dùng driver chuẩn (vd VirtIO) để nói chuyện hiệu quả với backend phía hypervisor thay vì giả lập phần cứng thật. Cân bằng giữa hiệu năng và khả năng chia sẻ.","aka":["paravirtualization","paravirtualized","para-virtual"]},{"t":"paravirtual device","vi":"Thiết bị ảo kiểu paravirtual: guest thấy một thiết bị chuẩn hóa (VirtIO block/net/gpu…) và giao tiếp với backend qua hàng đợi chia sẻ. Backend dùng chung là điểm interference cần budget và test.","aka":["paravirtual devices"]},{"t":"virtqueue","vi":"Hàng đợi VirtIO: vùng memory chia sẻ giữa driver trong guest và backend phía host/hypervisor, dùng để gửi yêu cầu và nhận kết quả I/O.","aka":["virtqueues"]},{"t":"knockout","vi":"Loại trực tiếp: tiêu chí bắt buộc, không đạt là loại ngay bất kể điểm khác cao. Trong bài, chọn hypervisor phải xét knockout trước (isolation/FFI, safety scope) rồi mới chấm điểm.","aka":["knock-out","knockout criteria","knockouts","knockout criterion"]},{"t":"ASIL","vi":"Mức toàn vẹn an toàn ô tô theo ISO 26262, từ A (thấp) đến D (cao). Trong bài, mức ASIL của workload quyết định nó thuộc nhóm safety, cần partition tĩnh và evidence FFI đến mức nào.","aka":["Automotive Safety Integrity Level"],"full":"Automotive Safety Integrity Level","cs":true},{"t":"QM","vi":"Mức \"chỉ cần quản lý chất lượng thông thường\" trong ISO 26262, tức không có yêu cầu safety riêng. Phần mềm QM (vd AAOS, media) chạy cạnh phần ASIL thì phải chứng minh FFI.","aka":["Quality Management"],"full":"Quality Management","cs":true},{"t":"hazard analysis","vi":"Phân tích mối nguy theo quy trình functional safety (ISO 26262): xác định chức năng nào lỗi thì gây nguy hiểm và mức ASIL. Là nguồn đúng để phân loại workload safety/mission/non-critical."},{"t":"utilization","vi":"Mức tận dụng tài nguyên (CPU, memory, GPU). Dynamic sharing cho utilization cao hơn nhưng khó chứng minh worst-case; đây là đánh đổi chính với determinism.","aka":["utilisation"]},{"t":"spatial","vi":"Thuộc về không gian. Trong bài, spatial isolation là cô lập về bộ nhớ/địa chỉ: guest này không đọc/ghi được memory của guest khác."},{"t":"spatial isolation","vi":"Cô lập không gian: mỗi partition có vùng memory riêng (stage-2 page table, IOMMU/SMMU cho DMA) để lỗi hoặc tấn công bên này không ghi đè dữ liệu bên kia."},{"t":"partitioning proposal","vi":"Bản đề xuất chia tài nguyên: workload nào chạy ở VM/partition nào, budget CPU/memory/I/O, đường chia sẻ, failure scenario và evidence cần có. Là bài nộp chính của Assignment 1."},{"t":"shedding","vi":"Cắt bớt tải: chủ động tắt/giảm tính năng ít quan trọng khi thiếu tài nguyên để giữ phần quan trọng.","aka":["load shedding"]},{"t":"shedding order","vi":"Thứ tự cắt tải đã thống nhất trước: tính năng nào bị giảm/tắt trước khi thiếu tài nguyên (tắt animation, giảm frame rate media, dừng analytics, rồi mới tới mission). Là một phần của contention policy."},{"t":"pKVM","vi":"KVM được bảo vệ của Android: hypervisor nhỏ chạy ở EL2, bảo vệ memory của protected VM khỏi host Android. Không tự cung cấp timing isolation hay chứng nhận automotive safety.","aka":["Protected KVM"],"full":"Protected KVM","cs":true},{"t":"KVM","vi":"Cơ chế ảo hóa có sẵn trong Linux kernel, biến Linux thành hypervisor. Là nền của pKVM trong hệ sinh thái Android.","aka":["Kernel-based Virtual Machine"],"full":"Kernel-based Virtual Machine","cs":true},{"t":"protected","vi":"Được bảo vệ. Trong bài xuất hiện trong pKVM (Protected KVM) và protected VM – VM mà host không đọc/sửa được memory."},{"t":"protected VM","vi":"VM được bảo vệ trong pKVM/AVF: memory của nó bị cách ly khỏi host Android (confidentiality/integrity). Cần xác minh hỗ trợ protected-VM trên Android version và target cụ thể.","aka":["protected VMs","protected-VM","pVM"]},{"t":"Android Virtualization Framework","vi":"Khung ảo hóa của Android, dựa trên pKVM, cho phép chạy protected VM tách khỏi Android. Trong bài là bối cảnh khi xét pKVM trên central compute.","aka":["AVF"]},{"t":"CrosVM","vi":"Một VMM (chương trình tạo và quản lý VM, cung cấp device ảo) mã nguồn mở, viết bằng Rust, dùng với KVM/pKVM. Trong bài là một vai khác với hypervisor: cần kiểm device model và backend nó cung cấp.","aka":["crosvm"],"cs":true},{"t":"VMM","vi":"Chương trình tạo, chạy và quản lý VM, cung cấp device ảo cho guest (vd CrosVM). Thường chạy ở user space phía host, khác với phần hypervisor chạy ở mức đặc quyền cao.","aka":["Virtual Machine Monitor"],"full":"Virtual Machine Monitor","cs":true},{"t":"QNX Hypervisor","vi":"Hypervisor của BlackBerry QNX cho hệ nhúng, chạy nhiều guest/partition (QNX, Linux, Android) trên một SoC. Trong bài cần xác minh safety scope, device model và evidence FFI trên target."},{"t":"EL2","vi":"Mức đặc quyền thứ 2 trên CPU Arm, dành cho hypervisor (EL0 app, EL1 kernel OS, EL3 firmware bảo mật). pKVM chạy phần lõi ở EL2 để kiểm soát memory của các VM.","full":"Exception Level 2","cs":true},{"t":"Arm","vi":"Kiến trúc CPU (và công ty thiết kế nó) phổ biến nhất trên SoC ô tô và điện thoại. Trong bài, các khái niệm SMMU, EL2, stage-2 page table là thuật ngữ của Arm.","aka":["ARM"],"cs":true},{"t":"type-1","vi":"Hypervisor loại 1: chạy trực tiếp trên phần cứng, không cần OS bên dưới. Phổ biến trong xe vì trusted base nhỏ, kiểm soát tốt timing và isolation.","aka":["Type 1","type-1 hypervisor","bare-metal hypervisor"]},{"t":"type-2","vi":"Hypervisor loại 2: chạy bên trên một host OS, như phần mềm máy ảo trên laptop. Ít dùng cho workload safety trong xe vì phụ thuộc host OS.","aka":["Type 2","type-2 hypervisor","hosted hypervisor"]},{"t":"pressure","vi":"Áp lực, sức ép. Trong bài chủ yếu là memory pressure: khi RAM gần cạn, OS phải thu hồi bộ nhớ (kill app nền), gây trễ hoặc mất tính năng."},{"t":"memory pressure","vi":"Tình trạng sắp hết RAM khiến OS phải thu hồi bộ nhớ (vd Android kill app nền). Trong bài, chính sách khi có memory pressure phải được định trước để không ảnh hưởng phần safety."},{"t":"inventory","vi":"Bản kiểm kê/danh mục. Trong bài là bước 1: liệt kê mọi workload kèm mức criticality, deadline, tài nguyên cần và owner.","aka":["inventories"]},{"t":"workload inventory","vi":"Danh mục workload: bảng liệt kê từng workload, mức criticality (safety/mission/non-critical), deadline, nhu cầu CPU/memory/I/O, device dùng và owner. Là đầu vào của partition và budget."},{"t":"agent","vi":"Tác tử: chương trình chạy nền thay mặt hệ thống làm một việc. Trong bài, OTA agent là thành phần nhận và cài bản cập nhật, thuộc nhóm mission-critical.","aka":["agents","AI agent","AI agents"]},{"t":"OTA agent","vi":"Thành phần phần mềm trên xe điều phối cập nhật OTA: tải, kiểm chữ ký, cài, báo kết quả, rollback. Không trực tiếp safety nhưng mất nó là mất khả năng vá lỗi nên xếp mission-critical."},{"t":"card","vi":"Card/thẻ thiết bị phần cứng, vd card mạng. Trong bài: SoC chỉ có một card mạng, một GPU, một storage mà nhiều guest cùng cần, nên phải chọn device model để chia.","aka":["network card","cards"]},{"t":"enforcement","vi":"Sự cưỡng chế, thi hành. Trong bài là cơ chế bắt buộc mỗi partition không dùng quá budget (throttle phần vượt), thay vì chỉ ghi budget trên giấy."},{"t":"budget enforcement","vi":"Cưỡng chế budget: hypervisor/OS chặn hoặc hãm (throttle) partition dùng vượt phần được cấp, không cho lấy từ budget của partition khác. Là một phần của contention policy."},{"t":"karaoke","vi":"Quán hát karaoke – dùng trong phép so sánh của bài: một tòa nhà có cả phòng cấp cứu và quán karaoke, phải xây tường, chia điện nước để karaoke ồn đến mấy phòng cấp cứu vẫn hoạt động (minh họa mixed criticality)."},{"t":"dynamic","vi":"Động, thay đổi lúc chạy. Trong bài, dynamic sharing là cấp tài nguyên theo nhu cầu runtime, trái với static partitioning."},{"t":"dynamic sharing","vi":"Chia sẻ động: hypervisor/OS phân bổ CPU, memory, GPU theo nhu cầu lúc chạy. Tận dụng tài nguyên tốt (utilization) nhưng khó chứng minh worst-case; hợp với workload non-critical."},{"t":"static partitioning","vi":"Chia tĩnh: core, memory region, device được gán cố định lúc build/boot, ít chia sẻ động. Cho determinism và dễ lập evidence, phù hợp workload safety.","aka":["static partition","static partitions"]},{"t":"manual","vi":"Sổ tay hướng dẫn. Trong bài chủ yếu là safety manual của supplier: tài liệu nêu điều kiện sử dụng để sản phẩm giữ được tính an toàn.","aka":["manuals"]},{"t":"safety manual","vi":"Sổ tay an toàn do supplier (hypervisor, OS, chip) cung cấp: phạm vi đã chứng nhận và assumption of use. Chỉ là đầu vào; dự án vẫn phải chứng minh trên cấu hình và target của mình."},{"t":"pinning","vi":"Ghim: gán cố định vCPU/thread vào một core vật lý nhất định để tránh bị tranh chấp và cho timing ổn định.","aka":["pinned"]},{"t":"CPU pinning","vi":"Ghim CPU: gán vCPU của guest critical vào core riêng (vd QNX trên core 0–1) để workload khác không chen vào, giúp phân tích worst-case dễ hơn."},{"t":"switch","vi":"Bộ chuyển mạch mạng. Trong bài, virtual switch/bridge trong hypervisor chuyển gói tin giữa các guest; cần rule, VLAN, QoS để guest này không làm nghẽn guest kia.","aka":["switches"]},{"t":"virtual switch","vi":"Bộ chuyển mạch ảo trong hypervisor/host nối mạng giữa các VM. Là tài nguyên dùng chung: cần VLAN, QoS, rate limit để ngăn flood và broadcast storm lan sang guest critical."},{"t":"bridge","vi":"Cầu nối mạng: nối nhiều giao diện mạng (của các guest) thành một mạng chung. Trong bài, network bridge/IPC là đường giao tiếp giữa partition cần kiểm soát.","aka":["bridges"]},{"t":"VLAN","vi":"Mạng LAN ảo: chia một mạng vật lý thành nhiều mạng logic tách biệt. Trong bài dùng để tách traffic của guest critical và non-critical.","aka":["VLANs"],"full":"Virtual LAN","cs":true},{"t":"broadcast","vi":"Phát tán: gửi một gói tin tới mọi máy trong mạng. Quá nhiều broadcast làm nghẽn mạng chung.","aka":["broadcasts"]},{"t":"broadcast storm","vi":"Bão broadcast: gói tin quảng bá bị nhân lên liên tục làm nghẽn toàn mạng. Trong bài là một failure của mạng ảo dùng chung có thể ảnh hưởng guest critical."},{"t":"allowlist","vi":"Danh sách cho phép: chỉ những đối tượng có trong danh sách mới được đi qua, mọi thứ khác bị chặn mặc định. Trong bài dùng cho traffic mạng giữa các guest.","aka":["allowlists"]},{"t":"corruption","vi":"Hỏng/sai lệch dữ liệu (bị ghi đè, ghi dở). Trong bài là một lỗi cần test trên shared memory/IPC, cùng với race, starvation, stale data và access violation."},{"t":"playlist","vi":"Danh sách phát nhạc. Trong bài là ví dụ dữ liệu non-critical: requirement nêu rõ AAOS restart có thể mất trạng thái playlist hiện tại.","aka":["playlists"]},{"t":"dependent","vi":"Phụ thuộc. Trong bài chủ yếu trong \"dependent failure\": các lỗi có chung nguyên nhân hoặc lan từ thành phần này sang thành phần khác."},{"t":"dependent failure analysis","vi":"Phân tích lỗi phụ thuộc (DFA) theo ISO 26262: tìm lỗi có nguyên nhân chung hoặc lỗi lan truyền qua tài nguyên dùng chung (cache, bus, device, IPC, DMA, lock). Là cơ sở để lập luận FFI.","aka":["DFA"]},{"t":"assurance","vi":"Mức bảo đảm: mức độ phải chứng minh hệ thống đáng tin (bao nhiêu phân tích, test, evidence). Mixed criticality là các workload có mức assurance khác nhau chạy trên cùng một hệ thống."},{"t":"stage-2","vi":"Giai đoạn 2 của việc dịch địa chỉ trên Arm: địa chỉ guest nghĩ là \"vật lý\" được hypervisor dịch tiếp sang địa chỉ RAM thật. Guest không sửa được, nên đây là hàng rào memory giữa các VM.","aka":["stage 2"]},{"t":"stage-2 page table","vi":"Bảng dịch địa chỉ do hypervisor kiểm soát, quyết định mỗi guest được thấy vùng RAM thật nào. Là cơ chế chính của spatial isolation cho CPU (DMA cần thêm IOMMU).","aka":["stage-2 page tables"]},{"t":"page table","vi":"Bảng trang: bảng ánh xạ địa chỉ ảo sang địa chỉ vật lý mà MMU dùng. Trong bài là stage-2 page table của hypervisor.","aka":["page tables"]},{"t":"page","vi":"Trang bộ nhớ: khối memory kích thước cố định (thường 4 KB) là đơn vị MMU quản lý và cấp phát.","aka":["pages"]},{"t":"table","vi":"Bảng. Trong bài xuất hiện trong page table (bảng ánh xạ địa chỉ bộ nhớ).","aka":["tables"]},{"t":"invalid-data","vi":"Dữ liệu không hợp lệ (sai khuôn dạng, ngoài khoảng, quá cũ). Trong bài, IPC contract phải định nghĩa invalid-data behavior: bên nhận làm gì khi gặp dữ liệu như vậy.","aka":["invalid data"]},{"t":"long-run","vi":"Chạy dài hạn. Long-run stress là test chạy tải nặng nhiều giờ/ngày trên target để bắt lỗi chỉ lộ ra theo thời gian (leak, phân mảnh, drift timing).","aka":["long run"]},{"t":"long-run stress","vi":"Test áp lực kéo dài: chạy tải cao liên tục trong thời gian dài và theo dõi worst-case/P99, recovery. Bắt các lỗi hiếm mà test ngắn không thấy.","aka":["long-run stress test"]},{"t":"upload","vi":"Tải lên: gửi dữ liệu từ xe lên cloud/server. Trong bài là ví dụ service upload dữ liệu xe – workload non-critical.","aka":["uploads","uploaded","uploading"]},{"t":"predictable","vi":"Dự đoán được. Predictable timing nghĩa là thời gian phản hồi ổn định, có giới hạn trên rõ – yêu cầu của workload real-time/control.","aka":["predictability"]},{"t":"panic","vi":"Kernel panic: lỗi nghiêm trọng khiến kernel OS dừng hẳn. Trong bài, AAOS kernel panic không được kéo theo device backend dùng chung hay guest khác.","aka":["kernel panic"]},{"t":"region","vi":"Vùng (bộ nhớ). Memory region là dải địa chỉ RAM được gán cố định cho một partition trong static partitioning.","aka":["regions","memory region","memory regions"]},{"t":"portable","vi":"Di động, dễ mang sang nền khác. Trong bài, emulation portable vì guest dùng driver của thiết bị giả lập quen thuộc, không phụ thuộc phần cứng thật."},{"t":"tick","vi":"Nhịp đồng hồ: ngắt định kỳ để scheduler chạy. Hypervisor tick là một nguồn interference nhỏ, khó thấy làm ngắt quãng guest critical.","aka":["ticks","hypervisor tick","ticked"]},{"t":"share","vi":"Chia sẻ, dùng chung. Trong bài: không share lock/state không cần thiết giữa partition, vì mỗi thứ dùng chung là một đường lỗi lan.","aka":["shares"]},{"t":"throttle","vi":"Hãm lại: giảm tốc độ được dùng tài nguyên khi vượt budget. Trong bài, partition dùng vượt budget bị throttle chứ không được lấy phần của partition khác.","aka":["throttled"]},{"t":"animation","vi":"Hiệu ứng chuyển động trên giao diện. Trong bài là thứ đầu tiên bị tắt trong shedding order khi thiếu tài nguyên.","aka":["animations"]},{"t":"violation","vi":"Vi phạm. Access violation là truy cập vùng memory/tài nguyên không được phép – lỗi cần test khi dùng shared memory.","aka":["violations","access violation"]},{"t":"breach","vi":"Sự xâm phạm. Security breach là bị tấn công thành công; trong bài, breach có thể phá timing hoặc inject lệnh vào workload safety, nên safety và security phải thiết kế cùng nhau.","aka":["breaches","security breach"]},{"t":"inject","vi":"Tiêm/chèn vào. Trong bài: kẻ tấn công inject command vào workload safety; hoặc tester inject lỗi (fault injection) để kiểm isolation.","aka":["injected","injecting"]},{"t":"trusted","vi":"Được tin cậy. Trusted base (trusted computing base) là phần mã mà an toàn/bảo mật của cả hệ thống phụ thuộc vào; càng nhỏ càng dễ phân tích và chứng nhận."},{"t":"trusted base","vi":"Phần mềm/phần cứng nền mà isolation dựa vào (hypervisor, firmware…). Trong bài: trusted base nhỏ + cấu hình tĩnh giúp certification dễ hơn.","aka":["trusted computing base","TCB"]},{"t":"notification","vi":"Thông báo. Trong bài là safety notification trên audio stack – âm báo/cảnh báo an toàn phải phát được dù AAOS gặp lỗi.","aka":["notifications"]},{"t":"per-resource","vi":"Theo từng tài nguyên. Per-resource budget là đặt budget riêng cho CPU, memory, cache/bandwidth, GPU, I/O, network thay vì một con số chung.","aka":["per resource"]},{"t":"under","vi":"Dưới, trong điều kiện. \"Under cross-load\" = đo khi đang có tải chéo từ guest khác."},{"t":"after","vi":"Sau. \"Evidence validity after change\" = evidence còn hiệu lực hay không sau khi thay đổi cấu hình, version."},{"t":"separation","vi":"Sự tách bạch. Fact/assumption separation là ghi rõ điều gì đã đo trên target (fact) và điều gì chỉ là giả định (assumption)."},{"t":"P99","vi":"Phân vị 99: giá trị mà 99% lần đo nằm dưới nó, đại diện cho \"đuôi\" chậm. Trong bài, latency critical phải đánh giá bằng P99/worst-case dưới cross-load, không dùng trung bình.","full":"99th percentile","cs":true},{"t":"BW","vi":"Viết tắt của bandwidth – băng thông (lượng dữ liệu truyền được mỗi giây). Trong bảng budget, \"Memory BW\" là băng thông bộ nhớ dùng chung giữa các guest.","full":"bandwidth","cs":true},{"t":"coloring","vi":"Tô màu cache (cache coloring): chia cache dùng chung thành các phần riêng bằng cách gán vùng memory sao cho mỗi partition chỉ dùng một nhóm cache set, giảm interference qua cache.","aka":["colouring","cache coloring","cache colouring","page coloring"]},{"t":"bandwidth regulation","vi":"Điều tiết băng thông bộ nhớ: giới hạn lượng truy cập memory của mỗi core/partition trong một chu kỳ, để guest non-critical không chiếm hết memory bus."},{"t":"lifetime","vi":"Vòng đời: dữ liệu/vùng nhớ tồn tại từ lúc nào đến lúc nào, ai tạo và ai giải phóng. Trong bài, ownership/lifetime của shared memory phải ghi trong contract.","aka":["lifetimes"]},{"t":"cap","vi":"Mức trần: giới hạn tối đa tài nguyên được dùng. Trong bài, workload non-critical bị cap (vd CPU, bandwidth) để không lấn sang phần critical; khác reserve là mức tối thiểu được bảo đảm.","aka":["caps","capped"]},{"t":"hang","vi":"Treo: chương trình không chết nhưng không phản hồi. Là một kiểu fault cần inject để kiểm watchdog và isolation.","aka":["hangs","hung"]},{"t":"device backend","vi":"Phần phía host/hypervisor thực sự điều khiển thiết bị thật và phục vụ yêu cầu từ driver ảo trong guest. Backend dùng chung bị treo hay nghẽn sẽ kéo mọi guest dùng nó, nên phải có owner và budget.","aka":["device backends"]},{"t":"device model","vi":"Cách cho guest dùng thiết bị: emulation (giả lập), paravirtual/VirtIO, hoặc passthrough (giao thẳng). Mỗi cách đánh đổi giữa hiệu năng, khả năng chia sẻ và isolation.","aka":["device models"]},{"t":"device assignment","vi":"Gán thiết bị: quy định rõ thiết bị nào thuộc guest nào (passthrough hoặc qua backend), cùng cấu hình IOMMU tương ứng."},{"t":"contention policy","vi":"Chính sách tranh chấp: luật định trước ai được ưu tiên khi tài nguyên thiếu – criticality, deadline/priority, budget enforcement, shedding order, admission control. Là sản phẩm của SA."},{"t":"priority policy","vi":"Chính sách ưu tiên: quy định workload nào được chạy/được phục vụ trước khi tranh chấp CPU, GPU, network."},{"t":"interrupt routing","vi":"Định tuyến ngắt: quy định interrupt của thiết bị nào được xử lý ở core nào, để ngắt của guest non-critical không làm gián đoạn core của guest critical."},{"t":"shared cache","vi":"Cache dùng chung giữa các core (vd L3). Guest này chiếm cache làm guest kia chậm – một đường interference khó thấy."},{"t":"memory bus","vi":"Đường truyền giữa CPU/GPU và RAM, dùng chung cho mọi core. Khi AAOS render 3D chiếm memory bus, tác vụ QNX có thể bị trễ dù có core riêng."},{"t":"memory map","vi":"Bản đồ bộ nhớ: phân chia dải địa chỉ cho từng partition/thiết bị. Trong bài: chỉ kiểm memory map của CPU là chưa đủ, còn đường DMA của device.","aka":["memory maps"]},{"t":"memory controller","vi":"Bộ điều khiển bộ nhớ trong SoC, quản lý truy cập RAM cho mọi core và device; là điểm tranh chấp băng thông dùng chung."},{"t":"failure scenario","vi":"Kịch bản lỗi: mô tả lỗi gì xảy ra ở đâu (crash, hang, flood, data sai), lan tới đâu, phát hiện thế nào, recovery ra sao và test nào chứng minh.","aka":["failure scenarios","failure scenario analysis"]},{"t":"fault boundary","vi":"Ranh giới chặn lỗi: giới hạn mà lỗi trong một partition không được vượt qua để ảnh hưởng partition khác.","aka":["fault boundaries"]},{"t":"data loss","vi":"Mất dữ liệu. Trong bài, requirement phải ghi lượng data loss chấp nhận được cho từng fault (vd mất trạng thái playlist), cùng recovery time."},{"t":"data integrity","vi":"Tính toàn vẹn dữ liệu: dữ liệu không bị sai/hỏng/sửa trái phép. Là yêu cầu của workload mission-critical như logging, OTA."},{"t":"open risk","vi":"Rủi ro còn mở: điều chưa được đo/chứng minh hoặc chưa có biện pháp. Evidence phải tách rõ fact, assumption và open risk.","aka":["open risks"]},{"t":"safety scope","vi":"Phạm vi an toàn: phần nào của sản phẩm (hypervisor, OS) đã được chứng nhận safety và với điều kiện nào. Là tiêu chí knockout khi chọn hypervisor."},{"t":"isolation evidence","vi":"Bằng chứng cô lập: kết quả test/phân tích trên target chứng minh FFI (spatial, temporal, resource, communication). Là tiêu chí chọn hypervisor và đầu ra của bài."},{"t":"evidence chain","vi":"Chuỗi bằng chứng: design → configuration → test → evidence, mỗi mắt xích truy được về requirement/hazard, để chứng minh isolation thật sự đạt trên target."},{"t":"native performance","vi":"Hiệu năng gần như chạy trực tiếp trên phần cứng, không qua lớp ảo hóa. Là ưu điểm của passthrough."},{"t":"health monitor","vi":"Bộ giám sát sức khỏe: theo dõi heartbeat, tài nguyên, lỗi của partition/service để phát hiện sớm và kích hoạt restart/degraded mode.","aka":["health monitors"]},{"t":"frame rate","vi":"Số khung hình mỗi giây (fps). Trong bài, giảm frame rate media là một bước trong shedding order."},{"t":"complexity","vi":"Độ <b>phức tạp<\/b>. Trong bài, complexity không đo bằng số dòng code mà bằng số phụ thuộc, variant, bên liên quan, công nghệ và vòng đời mà một thành phần phải gánh; SA phải nhận diện nguồn gốc và phân biệt phần cần thiết với phần có thể loại bỏ.","aka":["complexities"]},{"t":"essential complexity","vi":"Độ phức tạp <b>cần thiết<\/b>: đến từ chính bài toán (quy định, safety, physics/timing, nhu cầu thị trường thực), không xóa được, chỉ quản lý được. Ví dụ trong bài: yêu cầu safety cho cảnh báo, variant theo quy định từng vùng.","aka":["essential/accidental complexity"]},{"t":"accidental complexity","vi":"Độ phức tạp <b>có thể loại bỏ<\/b>: do cách ta làm chứ không do bài toán, như stack trùng lặp, feature flag chết, interface ad-hoc, workaround legacy. SA cần chỉ ra và lên kế hoạch gỡ bằng debt item có owner."},{"t":"essential","vi":"Cần thiết, cốt lõi. Trong bài dùng cho loại complexity <b>đến từ bài toán<\/b> (quy định, safety, timing), không thể bỏ mà chỉ quản lý được — như độ khó của chính món ăn."},{"t":"accidental","vi":"Ngẫu nhiên, phát sinh do cách làm. Trong bài dùng cho loại complexity <b>có thể loại bỏ<\/b> — như bếp bừa bộn: món vẫn ra nhưng tốn công vô ích (code trùng, interface tạm, workaround)."},{"t":"complexity driver","vi":"<b>Nguồn sinh ra độ phức tạp<\/b> của một hệ thống. Trong bài có năm nguồn: dependency, variant, stakeholder, technology, lifecycle; mỗi driver cần ghi nguồn, dấu hiệu đo được và phân loại cần thiết/có thể loại bỏ (Phần B của Assignment 1).","aka":["complexity drivers"]},{"t":"4F","vi":"Bộ <b>bốn câu hỏi<\/b> trong bài để đánh giá complexity của một thành phần: Feature (bao nhiêu capability/behavior), Fragmentation/flow (bao nhiêu interface, team, supplier), Failure/risk (hậu quả, blast radius), Future/lifecycle (variant, migration, OTA).","aka":["checklist 4F"],"cs":true},{"t":"future","vi":"Tương lai. Trong checklist 4F, Future/lifecycle hỏi thành phần sẽ phải chịu những thay đổi nào trong vòng đời xe: thêm variant, thị trường, đổi SoC, migration, OTA nhiều năm, gánh nặng bảo trì."},{"t":"physics","vi":"Vật lý. Trong bài, physics/timing là ràng buộc từ thế giới thực (quán tính, thời gian phản hồi, deadline real-time) — một nguồn complexity <b>cần thiết<\/b> không thể thương lượng bỏ đi."},{"t":"technology","vi":"Công nghệ (ngôn ngữ, OS, framework, giao thức, SoC). Trong bài là một trong năm nguồn complexity: nhiều stack/công nghệ song song làm tăng chi phí tích hợp, kỹ năng và bảo trì.","aka":["technologies"]},{"t":"LOC","vi":"Số <b>dòng mã nguồn<\/b>. Bài nhấn mạnh complexity <b>không<\/b> đo bằng LOC: một component nhỏ trên central platform vẫn có thể rất phức tạp vì nhiều domain phụ thuộc vào nó.","aka":["Lines of Code"],"full":"Lines of Code","cs":true},{"t":"lines","vi":"Dòng (dòng code, dòng sản phẩm). Trong bài xuất hiện trong LOC – Lines of Code (số dòng mã), thước đo mà bài cho là không phản ánh đúng complexity."},{"t":"RACI","vi":"Bảng phân vai cho mỗi quyết định/công việc: ai <b>làm<\/b> (R), ai <b>chịu trách nhiệm cuối và duyệt<\/b> (A, chỉ một người), ai <b>được hỏi ý kiến<\/b> (C), ai <b>được thông báo<\/b> (I). Trong bài, RACI chỉ là mẫu; authority chính thức theo organization matrix.","full":"Responsible, Accountable, Consulted, Informed","cs":true},{"t":"Responsible","vi":"Chữ R trong RACI: người <b>trực tiếp làm việc<\/b> (phân tích, viết, triển khai); có thể nhiều người. Ví dụ trong bài: SA là R cho đề xuất/phân tích kiến trúc."},{"t":"Accountable","vi":"Chịu trách nhiệm cuối cùng. Chữ A trong RACI: người <b>phê duyệt và chịu trách nhiệm<\/b> về kết quả; mỗi quyết định nên chỉ có một A. Bài cảnh báo lỗi hay gặp: ghi A = team hoặc hai người cùng là A."},{"t":"Consulted","vi":"Được hỏi ý kiến. Chữ C trong RACI: người phải được <b>tham vấn trước khi chốt<\/b>, trao đổi hai chiều. Ví dụ: SA là C cho quyết định safety/cyber và cost/commercial."},{"t":"Informed","vi":"Được thông báo. Chữ I trong RACI: người được <b>báo sau khi chốt<\/b>, chỉ một chiều, không tham gia quyết định."},{"t":"SA","vi":"<b>Kiến trúc sư giải pháp<\/b>: người biến nhu cầu và ràng buộc thành solution triển khai, vận hành và bảo trì được. Trong bài, SA sở hữu quyết định kiến trúc trong scope của mình, phân tích và đưa recommendation, nhưng không thay product, safety, cyber hay business owner.","aka":["Solution Architect","solution architect","SAs"],"full":"Solution Architect","cs":true},{"t":"solution","vi":"Giải pháp. Trong bài là thứ SA tạo ra: một thiết kế hệ thống có thể <b>triển khai, vận hành và bảo trì<\/b> được, không chỉ chạy được trên giấy; system/solution architect là vai thiết kế ở mức toàn hệ thống.","aka":["solutions"]},{"t":"DEV03","vi":"Mã <b>bậc năng lực kỹ sư nội bộ<\/b> (DEV03, DEV04 là hai bậc kế tiếp). Bài đặt mục tiêu ở mức DEV03→DEV04: tạo phân tích và recommendation đủ rõ, biết ranh giới authority và biết lúc nào cần escalate.","aka":["DEV04","DEV03→DEV04","DEV03/DEV04"],"cs":true},{"t":"escalate","vi":"<b>Đưa lên cấp có quyền<\/b> quyết định. Bài nhấn mạnh escalate không phải đẩy việc khó lên trên, mà là đưa decision tới đúng authority kèm phân tích, phương án và đề xuất.","aka":["escalated","escalating","escalates"]},{"t":"escalation path","vi":"<b>Đường leo thang<\/b>: ghi sẵn ai là người quyết định ở cấp tiếp theo khi team không tự chốt được (team → ARB → steering/business owner), để khi có xung đột không phải đi tìm người.","aka":["escalation paths"]},{"t":"organization matrix","vi":"<b>Ma trận tổ chức<\/b>: tài liệu chính thức của công ty quy định ai có quyền quyết định/phê duyệt loại việc nào. Trong bài, bảng RACI của bạn đúng hay sai được đo bằng việc khớp organization matrix."},{"t":"commercial","vi":"Thương mại (giá, hợp đồng, chi phí, lợi nhuận). Trong bài, quyết định cost/commercial thuộc business owner/steering; SA chỉ là C (được hỏi ý kiến), không tự quyết."},{"t":"steering","vi":"Ở đây không phải lái xe mà là <b>ban chỉ đạo<\/b> (steering committee): cấp lãnh đạo quyết các việc ảnh hưởng cost/commercial hoặc risk lớn. Trong bài là tầng quyết định cao nhất: team → ARB → steering.","aka":["steering committee","steering/business owner"]},{"t":"business owner","vi":"Người <b>chịu trách nhiệm về mặt kinh doanh<\/b> của sản phẩm/dự án: duyệt các quyết định về cost, commercial, ưu tiên thị trường. Trong bảng RACI của bài, business owner là A cho cost/commercial.","aka":["business owners"]},{"t":"product owner","vi":"Người <b>sở hữu sản phẩm<\/b>: quyết định tính năng nào làm, ưu tiên thế nào, theo nhu cầu người dùng và thị trường. Bài nhấn mạnh SA không thay product owner.","aka":["product owners"]},{"t":"product architecture owner","vi":"Người sở hữu kiến trúc của một dòng sản phẩm sau khi dự án kết thúc. Trong bài là một ứng viên làm owner sustaining, nhận bàn giao các ADR và quyết định kiến trúc còn hiệu lực trên xe."},{"t":"operations owner","vi":"Người chịu trách nhiệm <b>vận hành<\/b> hệ thống khi đã chạy thật (giám sát, sự cố, cập nhật). Bài liệt kê đây là một vai mà SA không thay thế.","aka":["operations owners"]},{"t":"platform architect","vi":"Kiến trúc sư của <b>platform<\/b> (phần nền dùng chung như vehicle-data service, OS, middleware). Trong bài, platform architect thường là owner sustaining: người quyết định kiến trúc sau release, ví dụ vá CVE qua OTA ngay hay chờ.","aka":["platform architects","platform architect sustaining"]},{"t":"lead architect","vi":"Kiến trúc sư trưởng của dự án/chương trình, điều phối các architect domain và thường tham gia ARB."},{"t":"domain lead","vi":"Trưởng nhóm của một domain (ví dụ cluster, IVI, ADAS). Trong bài là thành phần của ARB, đại diện cho domain bị ảnh hưởng bởi quyết định cross-domain.","aka":["domain leads"]},{"t":"sustaining","vi":"<b>Giai đoạn duy trì sau release<\/b>: xe đã bán, phần mềm vẫn phải vá lỗi, vá bảo mật, OTA nhiều năm. Trong bài, quyết định kiến trúc lúc này thuộc owner sustaining được bàn giao chính thức (thường là platform architect), không phải người viết ADR ban đầu.","aka":["sustaining engineering","owner sustaining","ownership sustaining"]},{"t":"runway","vi":"Nghĩa đen là <b>đường băng<\/b> máy bay. Trong bài là phần nền kỹ thuật đã có sẵn (platform service, interface, infrastructure, tooling) đủ để team làm feature sắp tới mà không phải thiết kế lại lớn; bị tiêu dần nên phải bổ sung có kế hoạch.","aka":["runways"]},{"t":"architecture runway","vi":"<b>Đường băng kiến trúc<\/b>: lượng nền kỹ thuật làm sẵn trước nhu cầu feature. Trong bài, runway được bổ sung bằng enabler work trong backlog; thiếu runway thì mỗi feature mới đều phải đập đi làm lại."},{"t":"enabler","vi":"Thứ tạo điều kiện, mở đường. Trong bài, enabler là hạng mục công việc chuẩn bị nền (platform, interface, tooling) không tạo feature trực tiếp cho người dùng nhưng giúp feature sau làm nhanh, an toàn.","aka":["enablers"]},{"t":"enabler work","vi":"<b>Việc chuẩn bị nền<\/b> được đưa vào backlog: không tạo tính năng trực tiếp cho người dùng nhưng bổ sung architecture runway (ví dụ chuẩn hóa API, thêm adapter, cải tiến tooling)."},{"t":"infrastructure","vi":"<b>Hạ tầng<\/b> kỹ thuật (server, pipeline CI/CD, công cụ, môi trường chạy, mạng). Trong bài là một phần của architecture runway mà team cần có sẵn để làm feature."},{"t":"canvas","vi":"Nghĩa đen là tấm vải vẽ; ở đây là <b>một trang mẫu chia ô<\/b> để điền thông tin có cấu trúc. Trong bài, Canvas là Architecture Governance Canvas với các ô từ scope đến ownership sau release."},{"t":"Architecture Governance Canvas","vi":"Mẫu một trang của khóa học gồm các ô: scope/context, interface/quality attribute, decision rights, governance gate/evidence, change/revisit trigger, debt/runway/migration, ownership sau release. Dùng để kiểm tra một quyết định kiến trúc đã đủ cơ chế quản trị chưa.","aka":["governance canvas"]},{"t":"lifecycle governance","vi":"<b>Quản trị kiến trúc suốt vòng đời<\/b>: không chỉ duyệt thiết kế lúc đầu mà giữ kiến trúc đúng qua thay đổi, release, OTA, sustaining — bằng ADR, gate, fitness function, risk register, owner được bàn giao."},{"t":"governance gate","vi":"<b>Mốc kiểm soát<\/b> trong lifecycle (concept, architecture baseline, design review, integration readiness, release readiness) có tiêu chí vào/ra và evidence bắt buộc trước khi đi tiếp.","aka":["governance gates"]},{"t":"architecture baseline","vi":"<b>Bản kiến trúc được chốt<\/b> làm mốc tham chiếu; mọi thay đổi sau đó phải qua quy trình change. Trong bài, architecture baseline review là một governance gate.","aka":["architecture baseline review"]},{"t":"integration readiness","vi":"Mức <b>sẵn sàng tích hợp<\/b>: các thành phần đã đủ evidence (interface đã chốt, test cơ bản đạt) để ghép lại với nhau. Trong bài là một governance gate, điểm đồng bộ giữa team agile và V-Model."},{"t":"agile","vi":"<b>Phát triển linh hoạt<\/b>: làm theo vòng lặp ngắn, giao từng phần, đón nhận thay đổi. Trong bài, agile hợp với phần requirement còn biến động cần feedback nhanh (UI/app), còn phần safety thường theo V-Model; kết hợp lại là hybrid."},{"t":"incremental","vi":"<b>Tăng dần<\/b>, từng phần một. Trong bài là chiến lược migration chuyển theo feature, variant hoặc dòng xe; phổ biến trong automotive vì xe đời cũ vẫn phải chạy trong lúc chuyển."},{"t":"big-bang","vi":"Chiến lược <b>chuyển toàn bộ một lần<\/b>. Trong bài: chỉ hợp khi scope nhỏ, ít phụ thuộc; rủi ro cao vì nếu lỗi thì hỏng tất cả cùng lúc."},{"t":"strangler","vi":"Mẫu migration <b>bọc dần<\/b> (lấy tên cây đa bóp nghẹt cây chủ): đặt adapter/facade giữ interface cũ, chuyển từng phần sang hệ mới, cuối cùng gỡ hệ cũ. Ví dụ trong bài: chuyển app từ đọc CAN trực tiếp sang vehicle-data service.","aka":["strangler pattern"]},{"t":"facade","vi":"Nghĩa đen là <b>mặt tiền<\/b>. Trong phần mềm là lớp trung gian cung cấp interface đơn giản/ổn định che phần bên trong; trong bài dùng cùng adapter để giữ interface cũ trong lúc migration kiểu strangler.","aka":["façade","facades"]},{"t":"parallel","vi":"Song song, chạy cùng lúc. Trong bài: giữ hai thế hệ song song khi migration, hoặc parallel run để so sánh hệ cũ và mới.","aka":["in parallel"]},{"t":"parallel run","vi":"<b>Chạy song song<\/b> hệ mới cạnh hệ cũ, so sánh output trước khi chuyển hẳn. Trong bài: hợp với chức năng cần chứng minh tương đương, nhưng tốn tài nguyên.","aka":["parallel runs"]},{"t":"shadow","vi":"Nghĩa đen là <b>cái bóng<\/b>. Shadow mode: hệ mới chạy ngầm nhận cùng dữ liệu nhưng output không được dùng thật, chỉ để so sánh với hệ cũ trước khi chuyển.","aka":["shadow mode"]},{"t":"fitness","vi":"Độ phù hợp, độ khỏe. Trong bài chỉ dùng trong fitness function: phép đo tự động xem kiến trúc còn \"khỏe\" theo quality attribute hay không."},{"t":"fitness function","vi":"<b>Hàm đo độ khỏe kiến trúc<\/b>: một kiểm tra tự động (thường chạy trong CI) đo một quality attribute như boot time, latency, dependency, và fail build khi vượt ngưỡng. Trong bài là cơ chế giữ kiến trúc không bị trôi sau mỗi release.","aka":["fitness functions"]},{"t":"conformance","vi":"Sự <b>tuân thủ<\/b> đúng thiết kế/quy tắc đã định. Trong bài, kiểm tra conformance giúp phát hiện code thực tế đi lệch kiến trúc (drift/erosion)."},{"t":"conformance check","vi":"<b>Kiểm tra tuân thủ kiến trúc<\/b> tự động: rule dependency giữa module, chặn gọi tắt qua layer, kiểm interface/schema version — chạy mỗi lần commit để phát hiện vi phạm sớm.","aka":["conformance checks"]},{"t":"erosion","vi":"Sự <b>xói mòn<\/b>. Architecture erosion (hay drift): code thực tế dần khác thiết kế, dependency mới xuất hiện ngoài kế hoạch. Bài chỉ ra tài liệu viết một lần không chống được, cần cơ chế liên tục."},{"t":"as-designed","vi":"<b>Theo thiết kế<\/b>: kiến trúc như trong tài liệu/model. Bài khuyên so sánh định kỳ as-designed với as-built để phát hiện drift và cập nhật view."},{"t":"as-built","vi":"<b>Theo thực tế đã xây<\/b>: kiến trúc như đang thật sự chạy trong code và trên xe. Đối chiếu với as-designed để tìm chỗ lệch."},{"t":"visible","vi":"<b>Ai cũng thấy được<\/b>. Trong bài là một trong ba tính chất của governance tốt: quyết định được ghi lại công khai (ADR, decision log) để mọi người biết và tra cứu."},{"t":"repeatable","vi":"<b>Lặp lại được<\/b> theo cùng một cách. Tính chất thứ hai của governance tốt: cùng loại quyết định luôn đi cùng một đường, không phụ thuộc người."},{"t":"decision log","vi":"<b>Nhật ký quyết định<\/b>: danh sách các quyết định (thường là ADR) kèm owner, trạng thái, ngày và lý do, đặt trong version control để ai cũng tra được.","aka":["decision logs"]},{"t":"ADR-0xx","vi":"Cách đặt <b>mã minh họa<\/b> cho một ADR (ADR-001, ADR-002…; \"0xx\" là số bất kỳ). Trong bài dùng để chỉ ADR mà owner sustaining phải nhận bàn giao.","cs":true},{"t":"proposed","vi":"<b>Được đề xuất<\/b>, chưa duyệt. Trạng thái đầu của một ADR; sau đó có thể thành accepted, rồi superseded hoặc deprecated."},{"t":"accepted","vi":"<b>Đã chấp nhận<\/b>. Trạng thái của ADR sau khi được duyệt; quyết định bắt đầu có hiệu lực cho tới khi bị superseded hoặc deprecated."},{"t":"irreversible","vi":"<b>Không đảo ngược được<\/b> (hoặc rất tốn kém để đảo). Trong bài, quyết định irreversible (chọn SoC, chốt public API) phải đi qua ARB thay vì team tự quyết."},{"t":"reversible","vi":"<b>Đảo ngược được<\/b> với chi phí thấp. Quyết định reversible nằm trong scope team có thể tự chốt và ghi ADR, không cần lên ARB."},{"t":"exception","vi":"<b>Ngoại lệ<\/b>. Trong bài, exception/waiver là cho phép tạm không tuân thủ một quy tắc/gate, có điều kiện, owner và thời hạn; loại này phải qua ARB.","aka":["exceptions"]},{"t":"non-safety","vi":"<b>Không liên quan an toàn<\/b> chức năng. Ranh giới safety/non-safety cần được vẽ rõ trong boundary để phần không an toàn không ảnh hưởng phần an toàn."},{"t":"public","vi":"<b>Công khai<\/b>, dùng được từ bên ngoài. Interface public là cái các team/consumer khác đang dùng nên phải giữ backward compatibility khi đổi."},{"t":"catalog","vi":"<b>Danh mục<\/b>. API/signal catalog: danh sách mọi API/tín hiệu kèm kiểu dữ liệu, đơn vị, chu kỳ, version, owner — tài liệu cho ô Interface của canvas.","aka":["catalogue","catalogs"]},{"t":"actor","vi":"<b>Tác nhân<\/b>: người hoặc hệ thống bên ngoài tương tác với hệ thống đang thiết kế (người lái, backend, supplier). Được vẽ trong context diagram.","aka":["actors"]},{"t":"context diagram","vi":"<b>Sơ đồ ngữ cảnh<\/b>: vẽ hệ thống như một khối ở giữa cùng các actor và hệ thống bên ngoài tương tác với nó, để chốt scope và boundary.","aka":["context diagrams"]},{"t":"scope statement","vi":"<b>Tuyên bố phạm vi<\/b>: văn bản ngắn nói rõ cái gì thuộc và không thuộc phạm vi hệ thống/dự án."},{"t":"list","vi":"<b>Danh sách<\/b>. Trong bài: stakeholder list (danh sách bên liên quan), assumption list (danh sách giả định) — tài liệu cho ô scope/context của canvas.","aka":["lists"]},{"t":"SKU","vi":"<b>Mã hàng<\/b> để phân biệt từng cấu hình sản phẩm. Trong bài, SKU phần cứng là mã cấu hình phần cứng; càng nhiều SKU thì phần mềm càng phải hỗ trợ nhiều variant.","aka":["SKUs"],"full":"Stock Keeping Unit","cs":true},{"t":"obsolete","vi":"<b>Lỗi thời, ngừng sản xuất<\/b>. Linh kiện obsolete buộc phải đổi chip/linh kiện giữa vòng đời xe — một nguồn complexity lifecycle.","aka":["obsolescence"]},{"t":"burden","vi":"<b>Gánh nặng<\/b>. Maintenance burden là chi phí và công sức bảo trì phải gánh lâu dài sau release.","aka":["burdens"]},{"t":"maintenance burden","vi":"<b>Gánh nặng bảo trì<\/b>: chi phí lâu dài để giữ hệ thống chạy (vá lỗi, backport, hỗ trợ nhiều version, OTA nhiều năm). Trong 4F thuộc câu hỏi Future/lifecycle."},{"t":"boot-time","vi":"Dạng gạch nối của boot time (<b>thời gian khởi động<\/b>). Boot-time budget: tổng thời gian khởi động được chia thành ngân sách cho từng tầng (bootloader, OS, service, app).","aka":["boot-time budget"]},{"t":"refactor","vi":"<b>Tái cấu trúc mã<\/b>: sửa cấu trúc bên trong mà không đổi hành vi bên ngoài. Trong bài: refactor nội bộ một service không đổi contract thì team tự quyết.","aka":["refactoring","refactored"]},{"t":"ad-hoc","vi":"<b>Làm tạm, tùy lúc<\/b>, không theo chuẩn chung. Interface ad-hoc là ví dụ accidental complexity trong bài.","aka":["ad hoc"]},{"t":"implement","vi":"<b>Triển khai, hiện thực<\/b> thành code/hệ thống chạy được. Trong vòng đời quyết định của bài: Proposal → Approval → Implement → Validate → Operate.","aka":["implemented","implementing","implements"]},{"t":"operate","vi":"<b>Vận hành<\/b>. Giai đoạn cuối của vòng đời quyết định: hệ thống chạy trên xe thật; ở đây có fitness function, ownership sustaining và revisit trigger.","aka":["operates"]},{"t":"needed","vi":"Cần có. Decision needed: <b>câu hỏi cụ thể<\/b> người duyệt phải trả lời, một mục bắt buộc trong recommendation/escalation."},{"t":"unresolved","vi":"<b>Chưa giải quyết<\/b>, còn mở. Assumptions/unresolved questions: các giả định và câu hỏi còn treo phải ghi rõ trong recommendation, không giấu sau thuật ngữ."},{"t":"contingency","vi":"<b>Phương án dự phòng<\/b> nếu risk thực sự xảy ra, khác mitigation (giảm khả năng/tác động trước). Mỗi risk entry trong bài nên có cả hai.","aka":["contingency plan"]},{"t":"risk entry","vi":"<b>Một dòng trong risk register<\/b>: mô tả risk, xác suất, tác động, owner, mitigation/contingency, trigger/indicator và ngày review.","aka":["risk entries"]},{"t":"debt item","vi":"<b>Một hạng mục nợ kiến trúc<\/b> được ghi lại: mô tả, nguyên nhân, chi phí nếu để lâu, owner, kế hoạch trả và deadline/trigger.","aka":["debt items"]},{"t":"debt backlog","vi":"<b>Danh sách nợ kiến trúc chờ xử lý<\/b>, được ưu tiên và lên lịch trả như công việc thường thay vì để mãi trong ghi chú."},{"t":"central platform","vi":"<b>Nền tảng trung tâm<\/b> dùng chung cho nhiều domain (ví dụ trên central compute). Bài lưu ý: thành phần nhỏ trên central platform vẫn rất phức tạp vì nhiều domain phụ thuộc."},{"t":"domain consumer","vi":"Domain <b>sử dụng<\/b> dữ liệu/dịch vụ của một thành phần (ví dụ cluster, IVI, ADAS cùng đọc vehicle-data service). Càng nhiều consumer thì blast radius càng lớn.","aka":["domain consumers"]},{"t":"supplier gateway","vi":"<b>Gateway do supplier cung cấp<\/b>: ECU/thành phần của nhà cung cấp làm cửa ngõ dữ liệu. Trong ví dụ của bài là một dependency ngoài team kiểm soát."},{"t":"Automotive SPICE","vi":"Mô hình đánh giá <b>năng lực quy trình phát triển<\/b> phần mềm/hệ thống ô tô, được OEM dùng để đánh giá supplier. Bài nhắc evidence và quality gate theo Automotive SPICE được đào sâu ở A.2.","aka":["SPICE"],"cs":true},{"t":"km","vi":"Ki-lô-mét, đơn vị đo quãng đường. Trong bài xuất hiện trong km/h (tốc độ) của ví dụ tín hiệu speed.","full":"kilometer","cs":true},{"t":"cost/commercial","vi":"Nhóm quyết định về <b>chi phí và thương mại<\/b> (giá thành, hợp đồng supplier, ưu tiên thị trường). Trong bài thuộc quyền business owner/steering; SA chỉ được hỏi ý kiến (C)."},{"t":"cost/schedule","vi":"<b>Chi phí và tiến độ<\/b>: một phần bắt buộc của recommendation, nêu mỗi phương án tốn bao nhiêu công/tiền và ảnh hưởng lịch thế nào."},{"t":"quality/risk","vi":"<b>Chất lượng và rủi ro<\/b>: một phần bắt buộc của recommendation, nêu mỗi phương án ảnh hưởng quality attribute nào và mang rủi ro gì."},{"t":"Fragmentation/flow","vi":"Chữ F thứ hai trong <b>checklist 4F<\/b>: thành phần dính tới bao nhiêu interface, team, supplier và dependency; dữ liệu/trách nhiệm phải chảy qua bao nhiêu bên."},{"t":"Failure/risk","vi":"Chữ F thứ ba trong <b>checklist 4F<\/b>: nếu thành phần hỏng thì hậu quả, safety/cyber impact và blast radius là gì (ví dụ service treo thì cluster và IVI cùng mất dữ liệu speed)."},{"t":"Future/lifecycle","vi":"Chữ F thứ tư trong <b>checklist 4F<\/b>: thành phần sẽ chịu những variant, migration, OTA và gánh nặng bảo trì nào trong suốt vòng đời xe."},{"t":"Complexity/Risk","vi":"Chặng <b>đánh giá độ phức tạp và rủi ro<\/b> trong vòng đời quyết định (Need → Options → Complexity/Risk → ADR → Approval → …); ở đây dùng checklist 4F."},{"t":"exception/waiver","vi":"<b>Ngoại lệ được phép<\/b> tạm không tuân thủ một quy tắc hoặc gate, có điều kiện, owner và thời hạn. Trong bài, mọi exception/waiver phải qua ARB và được ghi lại.","aka":["exceptions/waivers"]},{"t":"essential/accidental","vi":"Cặp phân loại complexity: <b>cần thiết<\/b> (đến từ bài toán, không bỏ được) và <b>có thể loại bỏ<\/b> (do cách làm, nên gỡ)."},{"t":"drift/erosion","vi":"<b>Kiến trúc trôi/xói mòn<\/b>: code thực tế dần khác thiết kế, dependency mới xuất hiện ngoài kế hoạch. Chống bằng cơ chế liên tục (ADR, conformance check, fitness function), không bằng tài liệu viết một lần."},{"t":"V-Model/agile/hybrid","vi":"Ba <b>nhịp phát triển<\/b> SA chọn theo risk và độ ổn định requirement: V-Model (tuần tự, nhiều evidence, hợp safety), agile (vòng lặp ngắn, hợp app/UI), hybrid (kết hợp, cần điểm đồng bộ integration/evidence)."},{"t":"agile/iterative","vi":"Phát triển <b>linh hoạt theo vòng lặp<\/b>: giao từng phần, lấy feedback, điều chỉnh. Hợp phần requirement còn biến động; rủi ro là mất evidence nếu thiếu kỷ luật."},{"t":"integration/evidence","vi":"<b>Điểm đồng bộ tích hợp và evidence<\/b> giữa các team chạy nhịp khác nhau (V-Model và agile): mốc chung nơi evidence của cả hai phải sẵn sàng — chính là governance gate."},{"t":"team/ARB/steering","vi":"<b>Thang phân tầng quyết định<\/b> trong bài: việc cục bộ, đảo ngược được thì team tự quyết; cross-domain hoặc irreversible lên ARB; ảnh hưởng cost/commercial hay risk lớn lên steering/business owner.","aka":["team, ARB, steering"],"cs":true},{"t":"debt/migration","vi":"<b>Nợ kiến trúc và kế hoạch chuyển đổi<\/b>: một ô của canvas, ghi các debt item có owner, runway và migration có ngày gỡ adapter."},{"t":"decision log/ADR","vi":"Nơi <b>ghi chính thức<\/b> quyết định và việc bàn giao ownership: decision log hoặc ADR. Bài yêu cầu bàn giao owner sustaining phải ghi ở đây, không mặc định \"vẫn là team cũ\"."},{"t":"latency/degraded mode","vi":"Evidence về <b>độ trễ<\/b> và <b>chế độ suy giảm có kiểm soát<\/b> (hệ vẫn chạy ở mức tối thiểu an toàn khi service lỗi). Trong case vehicle-data service, thiếu evidence này thì chỉ trình như đề xuất tạm thời."},{"t":"safety/non-safety","vi":"<b>Ranh giới an toàn/không an toàn<\/b>: phần nào thuộc chức năng an toàn (theo ISO 26262) và phần nào không; phải vẽ rõ trong boundary để phần không an toàn không làm hỏng phần an toàn."},{"t":"adapter/facade","vi":"<b>Lớp trung gian<\/b> giữ interface cũ cho consumer trong lúc hệ bên dưới được thay dần (mẫu strangler). Bài yêu cầu adapter có owner và kế hoạch gỡ."},{"t":"incremental/phased","vi":"Chiến lược migration <b>chuyển từng phần theo đợt<\/b> (theo feature, variant hoặc dòng xe); phổ biến trong automotive vì xe đời cũ vẫn phải chạy.","aka":["Incremental / phased"]},{"t":"reversible/irreversible","vi":"Phân loại quyết định <b>đảo ngược được/không đảo ngược được<\/b>. Quyết định khó đảo ngược phải qua ARB và ghi ADR kỹ hơn."},{"t":"trigger/indicator","vi":"<b>Ngưỡng kích hoạt/chỉ báo<\/b> trong risk entry: dấu hiệu đo được cho biết risk sắp xảy ra và lúc nào phải chạy contingency."},{"t":"Parallel run / shadow","vi":"Chiến lược migration <b>chạy hệ mới song song<\/b> (hoặc chạy ngầm) với hệ cũ, so sánh output trước khi chuyển hẳn; hợp chức năng cần chứng minh tương đương nhưng tốn tài nguyên."},{"t":"A8","vi":"Tên nền tảng kỹ thuật dùng chung (engineering platform) trong bài B.1: gom pipeline, môi trường test, signing, SBOM, artifact repository, OTA backend thành hạ tầng chung cho các team CDC, kèm golden path và quy định ai sở hữu dữ liệu nào.","aka":["A8 Platform","platform A8"],"cs":true},{"t":"digital continuity","vi":"<b>Continuity<\/b> = tính liên tục. Digital continuity là tính chất digital thread <b>không bị đứt<\/b> khi đi qua ranh giới giữa các tool, giữa OEM và supplier, và theo thời gian (đổi tool, đổi ID). Bài chỉ ra các điểm đứt hay gặp: export tay, Excel trung gian, PDF thay cho model.","aka":["continuity"]},{"t":"digital thread map","vi":"Bảng/sơ đồ mô tả digital thread của một phạm vi cụ thể: từng stage từ need tới operation, loại link giữa chúng, evidence, gate, owner và các điểm đứt. Là sản phẩm chính của assignment bài B.1.","aka":["thread map"]},{"t":"twin","vi":"Nghĩa đen: bản sao song sinh. Trong bài là cách gọi tắt của <b>digital twin<\/b>: bản sao số gắn với một asset/process cụ thể (một xe, một ECU) và được cập nhật từ dữ liệu thật, khác với một simulation chung chung.","aka":["twins"]},{"t":"SIL","vi":"Chạy phần mềm thật trong môi trường mô phỏng trên PC/server, không cần phần cứng ECU. Nhanh, rẻ, hợp để kiểm logic và flow sớm, nhưng không đại diện silicon timing, sensor, power… nên vẫn cần HIL/xe thật cho những rủi ro đó.","aka":["Software-in-the-Loop","software-in-the-loop","Software-in-the-loop"],"full":"Software-in-the-Loop","cs":true},{"t":"REQ-123","vi":"Mã định danh <b>minh họa<\/b> của một requirement (REQ = requirement, 123 = số thứ tự). Bài dùng nó làm ví dụ xuyên suốt: REQ-123 “cảnh báo pin thấp” được lần theo digital thread tới model, commit, test, build và cohort xe.","cs":true},{"t":"latest","vi":"Nghĩa: mới nhất. Trong build, khai báo dependency là “latest” nghĩa là luôn kéo bản mới nhất lúc build — input thay đổi theo thời gian nên hai lần build có thể khác nhau, phá reproducible build và traceability. Phải pin version cụ thể."},{"t":"simulated with","vi":"Loại link “được mô phỏng với”: nối một kết quả simulation với scenario và model version đã dùng, để trả lời câu hỏi kết quả mô phỏng dựa trên model nào, giả định nào.","aka":["simulated"]},{"t":"model-based engineering","vi":"Kỹ thuật dựa trên mô hình: <b>model là artifact chính<\/b>, tài liệu chỉ là view sinh ra từ model (SysML, Simulink, ARXML). Ngược với document-based. Lợi: một nguồn thông tin, dễ impact analysis; giá: tốn công xây model, cần kỹ năng modeling.","aka":["model-based","Model-Based (Systems) Engineering","model-based systems engineering"]},{"t":"MBE","vi":"Viết tắt của Model-Based Engineering — kỹ thuật dựa trên mô hình, trong đó model là nguồn thông tin chính, tài liệu sinh ra từ model.","full":"Model-Based Engineering","cs":true},{"t":"MBSE","vi":"Model-Based Systems Engineering — MBE áp dụng cho kỹ thuật hệ thống: kiến trúc, requirement, interface của cả hệ thống được mô hình hóa (thường bằng SysML) thay vì viết trong tài liệu Word/Excel.","full":"Model-Based Systems Engineering","cs":true},{"t":"document-based","vi":"Cách làm dựa trên tài liệu: mỗi tài liệu Word/Excel tự chứa thông tin và phải đồng bộ thủ công — sửa interface ở một chỗ thì phải nhớ sửa ở các tài liệu khác. Đối lập với model-based engineering."},{"t":"fidelity","vi":"Độ trung thực: môi trường ảo/model giống thật đến đâu. Bài tách bốn khía cạnh: logic, timing, physical, environmental — model đúng logic chưa chắc đúng timing. Fidelity luôn đi kèm validity domain."},{"t":"validity domain","vi":"Vùng hiệu lực: phạm vi điều kiện (tải, nhiệt độ, chế độ…) mà trong đó model/môi trường ảo đã được đo và chứng minh đại diện được target. Ra ngoài vùng này, kết quả virtual không còn là evidence đáng tin."},{"t":"correlate","vi":"Tương quan / khớp với nhau. “Model correlate với target” nghĩa là đã đo và thấy kết quả model khớp kết quả trên phần cứng thật — nhưng chỉ trong vùng đã đo (validity domain).","aka":["correlated","correlates"]},{"t":"correlation record","vi":"Bản ghi correlation: lưu điều kiện đo, kết quả so sánh virtual với target và validity domain đã được chứng minh. Là evidence để biết được dùng kết quả virtual tới đâu."},{"t":"correlation error","vi":"Sai lệch giữa kết quả trên môi trường ảo và trên target thật cho cùng một test. Bài dùng nó làm metric đo độ tin của evidence virtual.","aka":["virtual-target correlation error"]},{"t":"virtual-only","vi":"Chỉ test trên môi trường ảo, không kiểm chứng trên phần cứng/xe thật. Bài nhấn mạnh: virtual-first <b>không phải<\/b> virtual-only."},{"t":"virtual-target","vi":"Giữa môi trường ảo (virtual) và phần cứng đích (target). Thường gặp trong cụm virtual-target correlation: mức khớp giữa kết quả ảo và kết quả thật."},{"t":"virtual test","vi":"Test chạy trên môi trường ảo (SIL, virtual ECU, emulation) thay vì phần cứng thật. Rẻ và sớm, nhưng chỉ là evidence hợp lệ trong validity domain đã correlate.","aka":["virtual tests"]},{"t":"JSON","vi":"Định dạng dữ liệu dạng văn bản phổ biến. Trong ví dụ của bài là một thư viện xử lý JSON được khai báo “latest”, khiến hai lần build kéo về hai version khác nhau.","full":"JavaScript Object Notation","cs":true},{"t":"Word","vi":"Microsoft Word — phần mềm soạn văn bản. Trong bài, tài liệu Word/Excel đại diện cho cách làm document-based, phải đồng bộ thủ công.","cs":true},{"t":"PC","vi":"Máy tính cá nhân/máy trạm. SIL chạy phần mềm trên PC/server thay vì trên ECU thật.","full":"Personal Computer","cs":true},{"t":"WarningManager","vi":"Tên component <b>minh họa<\/b> trong bài: thành phần phần mềm quản lý hiển thị cảnh báo trên cluster, được link “satisfied by” với requirement REQ-123."},{"t":"truncated","vi":"Bị cắt cụt. Frame truncated là frame dữ liệu bị thiếu phần cuối; trong case của bài, parser đọc sai loại frame này trên 3 variant và 2 target."},{"t":"satisfied by","vi":"Loại link “được đáp ứng bởi”: nối requirement với component/design hiện thực nó. Ví dụ REQ-123 satisfied by WarningManager.","aka":["satisfied","satisfies","satisfy"]},{"t":"allocated to","vi":"Loại link “được phân bổ cho”: requirement được giao cho một model/design element hay component chịu trách nhiệm hiện thực.","aka":["allocated"]},{"t":"implemented by","vi":"Loại link “được hiện thực bởi”: nối design với code/config/commit cụ thể hiện thực thiết kế đó.","aka":["implemented","implements"]},{"t":"produced on","vi":"Loại link “được tạo ra trên”: kết quả test được tạo trên build X, môi trường Y nào — để biết requirement đã được chứng minh trên target/variant nào.","aka":["produced"]},{"t":"verified by","vi":"Loại link “được kiểm chứng bởi”: nối requirement/model/code với test case và kết quả test chứng minh nó đúng."},{"t":"deployed to","vi":"Loại link “được triển khai tới”: nối build/release với xe hoặc cohort đang chạy nó. Bản ghi rollout chính là link này của digital thread."},{"t":"observed in","vi":"Loại link “được quan sát thấy ở”: lỗi thực tế ngoài hiện trường được ghi nhận trên xe/cohort/build nào, để lần ngược về requirement, test, commit.","aka":["observed"]},{"t":"feeds back","vi":"Phản hồi ngược: dữ liệu vận hành (field data, incident) quay lại làm đầu vào cho defect, requirement hay cập nhật model — khép vòng digital thread.","aka":["feed back","feeds"]},{"t":"back","vi":"Quay lại / ngược về. Trong bài hay gặp trong “feeds back” (phản hồi ngược từ hiện trường) hoặc quay về bản cũ (rollback)."},{"t":"derives","vi":"Loại link “được suy ra từ”: requirement được suy ra từ một need (nhu cầu) của khách hàng/hệ thống.","aka":["derive"]},{"t":"refines","vi":"Loại link “làm chi tiết hóa”: requirement chi tiết hóa một need hoặc một requirement cấp trên.","aka":["refine","refined","refinement"]},{"t":"contains","vi":"Chứa. Loại link “chứa”: build/release chứa những artifact, SBOM, provenance, signature nào; release/vehicle config chứa build nào.","aka":["contained"]},{"t":"related to","vi":"“Có liên quan tới” — loại link chung chung không nói rõ quan hệ gì. Bài coi đây là link kém: biết hai thứ dính nhau nhưng không dùng được cho impact analysis.","aka":["related"]},{"t":"silicon timing","vi":"Timing thực của chip (silicon): độ trễ, tranh chấp bus/GPU/bộ nhớ trên phần cứng thật. SIL không có, nên rủi ro phụ thuộc silicon timing phải đo trên target."},{"t":"artifact repository","vi":"Kho lưu artifact đã build (binary, image, package) kèm version và metadata. Là capability dùng chung trên platform A8; release phải lấy đúng artifact đã qua gate từ đây."},{"t":"hotfix","vi":"Bản sửa nóng làm gấp. Trong bài, “hotfix thủ công sau build” bị cấm: sửa tay artifact sau khi build sẽ phá provenance; muốn sửa phải đi lại từ đầu dây chuyền.","aka":["hotfixes"]},{"t":"migrate","vi":"Di chuyển/chuyển đổi sang hệ mới: đổi tool (có thể làm đổi ID, đứt continuity) hoặc chuyển schema/persistent data trên xe sang định dạng mới — khiến bản cũ có thể không đọc được nữa khi rollback.","aka":["migrated","migrations","migrating"]},{"t":"EMC","vi":"Tương thích điện từ: thiết bị điện tử không gây nhiễu và không bị nhiễu bởi môi trường điện từ. Là loại rủi ro chỉ kiểm được trên hardware/xe thật, không qua SIL.","aka":["Electromagnetic Compatibility"],"full":"Electromagnetic Compatibility","cs":true},{"t":"electromagnetic","vi":"Điện từ (thuộc về trường điện và từ). Gặp trong EMC — Electromagnetic Compatibility."},{"t":"data residency","vi":"Nơi dữ liệu được lưu trữ về mặt địa lý (quốc gia/vùng nào). Khi đẩy build/test/analysis lên cloud phải kiểm soát data residency theo luật và hợp đồng."},{"t":"exception path","vi":"Đường ngoại lệ: thủ tục chính thức khi một thay đổi không đạt gate nhưng vẫn cần đi tiếp (waiver có lý do, mitigation, approver, expiry). Thiếu nó, người ta sẽ bypass."},{"t":"build farm","vi":"Cụm máy chủ dùng chung để chạy build/test song song cho nhiều team. Trên platform A8 là capability dùng chung thay vì mỗi team tự dựng."},{"t":"farm","vi":"Nghĩa đen: trang trại. Trong IT là một cụm nhiều máy cùng làm một việc, như build farm."},{"t":"engineer","vi":"Kỹ sư. Trong bài, ví dụ system engineer/requirement engineer là owner nội dung của requirement.","aka":["engineers"]},{"t":"system engineer","vi":"Kỹ sư hệ thống: người viết và sở hữu requirement cấp hệ thống, chịu trách nhiệm ý nghĩa, baseline và thay đổi của nó.","aka":["system engineers","systems engineer"]},{"t":"healthy","vi":"Khỏe, hoạt động bình thường. “95% xe healthy” chỉ có nghĩa khi biết mẫu số: xe chưa gửi báo cáo có được tính không."},{"t":"automation","vi":"Tự động hóa: để máy/script làm các bước thay người. Trong bài: AI/automation có thể hỗ trợ pipeline nhưng không được tự cấp waiver hay tự bypass gate."},{"t":"Intellectual Property","vi":"Sở hữu trí tuệ (IP): mã nguồn, model, thiết kế thuộc quyền của một bên. Trong CDC, IP của supplier ảnh hưởng tới việc chia sẻ model và dữ liệu qua digital thread.","aka":["intellectual"]},{"t":"versioned","vi":"Được quản lý version: mỗi thay đổi tạo một bản có số hiệu riêng, trỏ lại được. Artifact không versioned làm link dễ trỏ sai, tạo traceability giả."},{"t":"SysML","vi":"Ngôn ngữ mô hình hóa hệ thống (dạng sơ đồ chuẩn) dùng trong MBSE để mô tả requirement, kiến trúc, interface, behavior của hệ thống.","full":"Systems Modeling Language","cs":true},{"t":"Simulink","vi":"Công cụ của MathWorks để mô hình hóa và mô phỏng hệ thống động/điều khiển bằng sơ đồ khối, có thể sinh code. Trong bài dùng để mô tả behavior."},{"t":"OSLC","vi":"Bộ chuẩn mở để các tool lifecycle (requirement, test, change…) liên kết dữ liệu với nhau qua link thay vì copy. Dùng để nối digital thread giữa các tool.","aka":["Open Services for Lifecycle Collaboration"],"full":"Open Services for Lifecycle Collaboration","cs":true},{"t":"collaboration","vi":"Cộng tác, làm việc chung. Gặp trong OSLC — Open Services for Lifecycle Collaboration."},{"t":"env","vi":"Viết tắt của environment — môi trường chạy test (SIL, HIL, xe…). “Produced on build X, env Y” nghĩa là kết quả có được trên build và môi trường nào.","aka":["envs"]},{"t":"PR","vi":"Yêu cầu gộp một thay đổi code vào nhánh chính, kèm diff để người khác review trước khi merge. Trong bài, PR/diff/test là evidence của bước change.","aka":["PRs"],"full":"Pull Request","cs":true},{"t":"pull request","vi":"Đề nghị gộp thay đổi code (PR): gồm diff, mô tả và kết quả CI để review trước khi merge. Là một điểm lưu evidence trong digital thread.","aka":["pull requests"]},{"t":"pull","vi":"Kéo (về). Gặp trong “pull request” hoặc khi build tự kéo dependency từ ngoài vào."},{"t":"diff","vi":"Phần khác biệt giữa hai phiên bản code/file. Diff trong PR cho reviewer thấy chính xác dòng nào bị đổi.","aka":["diffs"]},{"t":"environmental","vi":"Thuộc về môi trường vận hành. Environmental fidelity: môi trường ảo có tái hiện đúng bus load, network fault, degraded mode hay không."},{"t":"normal load","vi":"Tải bình thường (bus, CPU…). Model correlate ở normal load không chứng minh được behavior khi bus overload — ngoài validity domain."},{"t":"normal","vi":"Bình thường. Trong bài: normal load (tải bình thường) — vùng điều kiện đã đo correlation."},{"t":"network fault","vi":"Lỗi mạng (mất gói, nghẽn, ngắt kết nối trên bus/Ethernet). Là một điều kiện environmental cần tái hiện khi đánh giá fidelity.","aka":["network faults"]},{"t":"representation","vi":"Sự biểu diễn / bản thể hiện. Digital twin là representation số của một asset/process cụ thể."},{"t":"human review","vi":"Người thật xem xét và duyệt. Trong bài, output của AI chỉ thành evidence sau khi được test và human review."},{"t":"human","vi":"Con người. Trong bài nhấn mạnh vai trò người duyệt (human review) với output của AI/automation."},{"t":"AI-generated","vi":"Do AI tạo ra. AI-generated test không tự chứng minh requirement coverage: phải map requirement và review oracle/expected result."},{"t":"expected result","vi":"Kết quả mong đợi của một test case (oracle). Nếu expected result do AI suy từ code hiện tại thì test chỉ xác nhận code đang làm gì, không chứng minh đúng requirement.","aka":["expected results"]},{"t":"correctness","vi":"Tính đúng đắn. Bài nhấn mạnh: số lượng test không đồng nghĩa correctness."},{"t":"install","vi":"Cài đặt. Trong flow OTA là bước ghi bản mới vào ECU; install/boot failure là metric để quyết pause hay rollback.","aka":["installation","installing","installs"]},{"t":"undo","vi":"Hoàn tác. Bài cảnh báo: rollback không phải nút “undo” — nếu schema/persistent data đã migrate, bản cũ có thể không quay về được."},{"t":"test harness","vi":"Bộ khung test: code/hạ tầng bao quanh phần mềm cần test để cấp input giả, stub, thu output. Virtual ECU/test harness là capability dùng chung trên platform.","aka":["harness"]},{"t":"backup","vi":"Bản sao lưu dự phòng. Evidence safety phải giữ lâu dài nên platform cần retention và backup.","aka":["backups"]},{"t":"flaky","vi":"Chập chờn: test lúc pass lúc fail mà code không đổi. Test flaky làm mất niềm tin vào gate và che lỗi thật."},{"t":"test pass rate","vi":"Tỷ lệ test pass trên tổng số test chạy. Là metric chất lượng nhưng phải biết rõ mẫu số, và nhiều test pass chưa chắc là đúng requirement.","aka":["pass rate"]},{"t":"deployment success","vi":"Tỷ lệ triển khai OTA thành công (cài xong, boot được, health OK) trên số xe nhận bản cập nhật. Metric vận hành trên xe."},{"t":"AI time saved","vi":"Thời gian AI tiết kiệm được — chỉ có ý nghĩa sau khi trừ thời gian verification/rework do output AI sai gây ra.","aka":["time saved"]},{"t":"saved","vi":"Được tiết kiệm / được lưu. Gặp trong “AI time saved”."},{"t":"export","vi":"Xuất dữ liệu ra khỏi một tool (file, bảng). Export/import thủ công giữa các tool là điểm đứt continuity điển hình.","aka":["exports","exported"]},{"t":"import","vi":"Nhập dữ liệu vào một tool từ file/nguồn ngoài. Nhập tay dễ làm đổi ID, mất link.","aka":["imports","imported"]},{"t":"admin","vi":"Quản trị viên (của tool/hệ thống). Bài nhấn mạnh câu hỏi traceability là trách nhiệm kiến trúc, không phải của admin tool.","aka":["administrator"]},{"t":"element","vi":"Phần tử. Design element là một thành phần trong model/thiết kế (block, component, interface) mà requirement được allocate tới.","aka":["elements"]},{"t":"modeling","vi":"Mô hình hóa: xây model mô tả hệ thống (SysML, Simulink…). Cần kỹ năng riêng; model kém chất lượng lan lỗi nhanh hơn tài liệu.","aka":["modelling"]},{"t":"answer","vi":"Trả lời / câu trả lời. Trong rubric: các câu hỏi impact mà map phải trả lời được.","aka":["answers"]},{"t":"identified","vi":"Được định danh (có ID rõ ràng). Artifact phải identified, versioned và owned thì link mới đáng tin."},{"t":"owned","vi":"Có chủ sở hữu (owner) rõ ràng chịu trách nhiệm duy trì."},{"t":"typed","vi":"Có loại xác định. Typed link là link mang nghĩa cụ thể (satisfied by, verified by…), không phải “related to” chung chung."},{"t":"directional","vi":"Có hướng. Link có hướng cho biết cái nào dẫn tới cái nào, nhờ đó đi được cả forward lẫn backward khi phân tích impact."},{"t":"both","vi":"Cả hai. “In both directions” — đi được cả hai chiều (forward và backward)."},{"t":"directions","vi":"Hướng, chiều. Impact analysis cần đi theo cả hai chiều của link.","aka":["direction"]},{"t":"break","vi":"Chỗ đứt / làm đứt. Break point là điểm digital thread bị đứt (qua tool, supplier hoặc theo thời gian), cần ghi vào map kèm hành động và owner.","aka":["breaks","break point","break points"]},{"t":"honest","vi":"Trung thực. Rubric đòi chỉ ra trung thực các link thủ công và điểm đứt, thay vì vẽ map “hoàn hảo”."},{"t":"content","vi":"Nội dung. Trên platform: “content ownership” (team sở hữu nội dung requirement/model) khác “service ownership” (platform team vận hành hạ tầng)."},{"t":"where","vi":"Ở đâu / chỗ nào. Ví dụ “where modelling pays off” — chỗ nào mô hình hóa đáng công."},{"t":"pays off","vi":"Đáng công, sinh lời: lợi ích lớn hơn chi phí bỏ ra. Rubric hỏi mô hình hóa đáng công ở chỗ nào.","aka":["pays","pay off"]},{"t":"model version","vi":"Phiên bản của model. Mọi kết quả simulation phải ghi model version để biết kết quả dựa trên model nào.","aka":["model versions"]},{"t":"CI pass","vi":"Pipeline CI chạy xanh (tất cả bước tự động pass). Bài nhắc: “CI pass” chỉ chứng minh phần đã được test, chưa đủ để lên xe nếu thiếu target validation, gate."},{"t":"pipeline template","vi":"Mẫu pipeline dựng sẵn trên platform để team dùng lại (thành phần của golden path), bảo đảm metadata, signing, SBOM được tạo thống nhất.","aka":["pipeline templates"]},{"t":"stale link","vi":"Link lỗi thời: trỏ tới bản cũ hoặc artifact đã xóa. Nhìn vẫn có link nhưng sai — tạo traceability giả. Số link stale là một metric của platform.","aka":["link stale","stale links"]},{"t":"configuration drift","vi":"Trôi cấu hình: cấu hình thực tế (trên xe, máy build, môi trường test) dần lệch khỏi cấu hình đã khai báo/đã kiểm chứng mà không ai ghi nhận."},{"t":"model drift","vi":"Model trôi: model/twin dần không còn khớp thực tế (do xe đổi phần cứng, phần mềm, điều kiện vận hành) nên phải re-validate."},{"t":"release record","vi":"Bản ghi phát hành: bản nào, artifact nào, qua gate nào, ai duyệt, đẩy tới cohort nào. Là evidence cho câu hỏi “đang chạy trên xe nào”.","aka":["release records"]},{"t":"gate record","vi":"Bản ghi gate: tiêu chí, evidence, kết quả, người duyệt (và waiver nếu có) của một quality gate. Giúp chứng minh vì sao bản đó được đi tiếp.","aka":["gate records"]},{"t":"OTA backend","vi":"Hệ thống phía server quản lý chiến dịch OTA: lưu artifact, chọn cohort, đẩy bản cập nhật, thu trạng thái và health từ xe."},{"t":"recovery evidence","vi":"Bằng chứng rằng xe có thể khôi phục (rollback, recovery mode) khi cập nhật lỗi — phải có trước khi rollout rộng."},{"t":"target validation","vi":"Kiểm chứng trên phần cứng đích (ECU/xe thật) sau test ảo — bước bắt buộc với các rủi ro phụ thuộc timing, sensor, power."},{"t":"change management","vi":"Quản lý thay đổi: quy trình đề xuất, đánh giá impact, duyệt và ghi nhận mọi thay đổi với requirement, design, code."},{"t":"platform reuse","vi":"Tái sử dụng nền tảng: các team dùng chung hạ tầng và capability của platform (pipeline, test env, signing…) thay vì tự dựng."},{"t":"platform service","vi":"Dịch vụ do platform team cung cấp và vận hành (build, signing, HIL scheduling…) cho các team sản phẩm dùng, có SLA/availability.","aka":["platform services"]},{"t":"field data","vi":"Dữ liệu thực tế từ xe đang chạy ngoài hiện trường (log, crash, telemetry). Là đầu vào của bước operation → feeds back trong digital thread."},{"t":"consistency check","vi":"Kiểm tra nhất quán: tự động phát hiện chỗ model, interface, tài liệu mâu thuẫn nhau. Là lợi ích chính của model-based engineering.","aka":["consistency checks"]},{"t":"decision boundary","vi":"Ranh giới quyết định: phạm vi mà một model/twin hay AI được dùng để ra quyết định; ngoài ranh giới đó phải có kiểm chứng thêm hoặc người quyết."},{"t":"data governance","vi":"Quản trị dữ liệu: quy định ai sở hữu, ai được đọc/sửa, chất lượng, lưu giữ bao lâu đối với dữ liệu kỹ thuật và dữ liệu xe."},{"t":"data owner","vi":"Người/nhóm sở hữu một loại dữ liệu: quyết định ý nghĩa, chất lượng và quyền truy cập của nó.","aka":["data owners"]},{"t":"interface governance","vi":"Quản trị interface: quy tắc version hóa, review, tương thích ngược và deprecation cho interface/schema của platform."},{"t":"stale telemetry","vi":"Telemetry cũ, không còn phản ánh trạng thái hiện tại của xe (xe offline, không gửi báo cáo). Dùng nó để cập nhật twin hay tính metric sẽ cho kết luận sai."},{"t":"service health","vi":"Tình trạng hoạt động của các service trên xe sau khi cập nhật (chạy, phản hồi, không crash). Là một health metric để quyết promote/pause/rollback."},{"t":"HIL scheduling","vi":"Lập lịch dùng bàn HIL (tài nguyên đắt, ít) cho các team. Là capability dùng chung trên platform A8."},{"t":"requirement review","vi":"Buổi/bước review requirement để đạt baseline: đúng, đủ, test được. Thường là gate của stage requirement."},{"t":"link semantics","vi":"Ngữ nghĩa của link: mỗi link mang loại và hướng rõ ràng (satisfied by, verified by…) để dùng được cho impact analysis."},{"t":"weight","vi":"<b>Trọng số<\/b>: con số thể hiện mức quan trọng của một tiêu chí khi chấm điểm. Trong weighted matrix, điểm từng tiêu chí nhân weight rồi cộng; vì weight mang tính chủ quan nên phải kèm sensitivity analysis (ví dụ 'tăng weight cost 0.1 thì kết quả có đảo không?').","aka":["weights"]},{"t":"weighted","vi":"<b>Có trọng số<\/b>: mỗi thành phần được nhân với một weight theo mức quan trọng trước khi cộng. Trong bài dùng cho cách chấm điểm các phương án kiến trúc theo nhiều tiêu chí.","aka":["weighted scoring","weighted score"]},{"t":"weighted matrix","vi":"<b>Ma trận chấm điểm có trọng số<\/b>: bảng hàng là phương án, cột là tiêu chí; điểm × weight rồi cộng tổng. Trong bài: chỉ dùng cho phần đánh đổi được (sau khi đã lọc knockout), không cộng lẫn đơn vị khác nhau và luôn kèm sensitivity analysis.","aka":["weighted matrices","weighted decision matrix"]},{"t":"summary","vi":"<b>Bản tóm tắt<\/b>. Trong case edge/cloud của bài, summary là dữ liệu đã được xe tổng hợp (không phải dữ liệu thô) gửi lên cloud để thấy xu hướng toàn đội xe, phải có format/version và không chứa dữ liệu bị data policy cấm.","aka":["summaries"]},{"t":"cloud summary","vi":"Phương án <b>edge + cloud summary<\/b>: xe tự phát hiện sự cố bằng detector local (vẫn chạy khi offline), chỉ gửi bản tóm tắt lên cloud để phân tích toàn đội xe. Đổi lại cần privacy rule, retention, bandwidth control và tốn CPU trên xe.","aka":["edge + cloud summary"]},{"t":"cloud-only","vi":"<b>Chỉ dùng cloud<\/b>: xe gửi dữ liệu thô lên server, mọi xử lý/phát hiện diễn ra trên cloud. Dễ cập nhật thuật toán nhưng mất mạng là không phát hiện kịp và gửi nhiều dữ liệu (tăng data exposure, bandwidth).","aka":["cloud only"]},{"t":"edge-only","vi":"<b>Chỉ xử lý trên xe (edge)<\/b>, không gửi gì lên cloud. Giảm data exposure nhưng fleet visibility thấp — khó thấy xu hướng lỗi trên toàn đội xe; trong bài bị loại vì lý do này.","aka":["edge only"]},{"t":"edge/cloud split","vi":"Pattern <b>chia việc giữa xe (edge) và cloud<\/b>: quyết định phần xử lý nào chạy trên xe, phần nào trên server. Các phương án cloud-only, edge + cloud summary, edge-only là các cách chia khác nhau, mỗi cách có trade-off đã biết.","aka":["edge-cloud split"]},{"t":"split","vi":"<b>Sự phân chia, tách<\/b>. Trong bài thường gặp ở 'edge/cloud split' — cách chia trách nhiệm xử lý giữa xe và cloud."},{"t":"preference","vi":"<b>Sở thích, ưu tiên chủ quan<\/b> (nhãn [P]). Trong bài: điều 'muốn có' như thích framework A hay tool B; chỉ đưa vào tiêu chí có weight thấp, <b>không<\/b> được biến thành constraint hay ghi như fact.","aka":["preferences"]},{"t":"F/A/P/R","vi":"Bộ <b>nhãn bốn loại<\/b> cho mỗi phát biểu trong phân tích: [F] fact có nguồn/đo được, [A] assumption chưa xác minh (cần owner, cách và hạn kiểm), [P] preference chủ quan, [R] risk có thể xảy ra. Gắn nhãn giúp người đọc biết kết luận chắc chắn đến đâu.","aka":["fact/assumption/preference/risk","Fact / assumption / preference / risk"],"full":"Fact / Assumption / Preference / Risk","cs":true},{"t":"reversibility","vi":"<b>Khả năng đảo ngược<\/b> một quyết định: đổi lại thì tốn bao nhiêu. Trong bài: quyết định khó đảo ngược (chọn SoC, hypervisor sau SOP, schema persistent data, public API) cần phân tích sâu; dễ đảo ngược (cấu hình, feature flag) thì quyết nhanh."},{"t":"last responsible moment","vi":"<b>Thời điểm chịu trách nhiệm cuối cùng<\/b>: lúc muộn nhất có thể chốt một quyết định mà chưa gây trễ dự án. Chờ đến đó để có thêm thông tin, nhất là với quyết định khó đảo ngược; quá mốc này thì việc 'chưa quyết' tự trở thành một quyết định tồi."},{"t":"last","vi":"<b>Cuối cùng<\/b>. Trong bài xuất hiện trong cụm 'last responsible moment' (thời điểm chịu trách nhiệm cuối cùng để chốt quyết định)."},{"t":"moment","vi":"<b>Thời điểm<\/b>. Trong bài xuất hiện trong cụm 'last responsible moment'."},{"t":"idle/contention/fault","vi":"Ba <b>điều kiện đo<\/b> trong bài: idle (không tải), contention (nhiều phần mềm tranh tài nguyên CPU/GPU/bộ nhớ) và fault injection (cố tình gây lỗi, ví dụ crash IVI). Đo đủ ba để phép đo có thể làm phương án trượt.","aka":["idle/contention/fault injection"]},{"t":"sensitivity point","vi":"Khái niệm của ATAM: một <b>tham số/quyết định mà một quality attribute phụ thuộc mạnh<\/b> vào nó. Ví dụ: kích thước time slice của hypervisor quyết định latency của cluster.","aka":["sensitivity points"]},{"t":"trade-off point","vi":"Khái niệm của ATAM: một tham số/quyết định ảnh hưởng tới <b>nhiều quality attribute theo hướng ngược nhau<\/b> — cải thiện cái này làm xấu cái kia. Ví dụ: thêm SecOC tăng security nhưng tăng latency và CPU.","aka":["trade-off points","tradeoff point","tradeoff points"]},{"t":"evaluation","vi":"<b>Sự đánh giá<\/b>. Trong bài chủ yếu ở cụm 'evaluation criteria' — các tiêu chí dùng để so sánh và chấm các phương án kiến trúc.","aka":["evaluations"]},{"t":"evaluation criteria","vi":"<b>Tiêu chí đánh giá<\/b> các phương án: mỗi tiêu chí có metric, thang đo, cách đo, weight (nếu dùng) và cờ knockout. Phải chốt <b>trước khi đo<\/b> để không ai chỉnh luật chơi theo hướng có lợi cho phương án mình thích.","aka":["evaluation criterion"]},{"t":"visibility","vi":"<b>Khả năng nhìn thấy, quan sát được<\/b>. Trong bài ở cụm 'fleet visibility' — mức cloud thấy được tình trạng và xu hướng của toàn đội xe."},{"t":"fleet visibility","vi":"<b>Tầm nhìn toàn đội xe<\/b>: khả năng phía cloud thấy xu hướng, sự cố lặp lại trên nhiều xe. Là một tiêu chí trong case edge/cloud; edge-only bị loại vì fleet visibility không đủ cho phân tích xu hướng."},{"t":"detector","vi":"<b>Bộ phát hiện<\/b>: phần mềm theo dõi tín hiệu/log để phát hiện bất thường. Trong bài là detector chạy local trên xe để phát hiện fleet issue kể cả khi offline; logic detector cập nhật được qua OTA và phải nằm trong CPU headroom.","aka":["detectors"]},{"t":"false positive","vi":"<b>Dương tính giả<\/b>: hệ thống báo có sự cố trong khi thực tế không có. Trong case edge/cloud, tỷ lệ báo nhầm của detector là một tiêu chí phải đạt requirement.","aka":["false-positive","false positives","false-positives","false positive/false negative"]},{"t":"false-positive rate","vi":"<b>Tỷ lệ báo nhầm<\/b>: phần trăm cảnh báo sai trên tổng số cảnh báo/lần kiểm. Trong bài là một evaluation criteria của detector local; phương án edge + cloud chỉ được chọn khi latency và false-positive rate đạt requirement.","aka":["false positive rate"]},{"t":"data policy","vi":"<b>Chính sách dữ liệu<\/b>: quy định dữ liệu nào được thu, gửi ra khỏi xe, lưu bao lâu (privacy, pháp lý). Trong bài là constraint (không gửi dữ liệu bị cấm) và là revisit trigger: data policy đổi thì phải mở lại quyết định.","aka":["data policies"]},{"t":"data exposure","vi":"<b>Mức phơi bày dữ liệu<\/b>: lượng dữ liệu (nhất là dữ liệu cá nhân) rời khỏi xe và có thể bị lộ. Gửi summary thay vì dữ liệu thô giúp giảm data exposure."},{"t":"offline queue","vi":"<b>Hàng đợi khi mất mạng<\/b>: xe lưu tạm các summary/sự kiện chưa gửi được để gửi lại khi có mạng. Trong bài phải <b>có giới hạn<\/b> (dung lượng, thời gian) để không tràn bộ nhớ, và được test với network loss, burst.","aka":["offline queues"]},{"t":"CPU headroom","vi":"<b>Phần CPU còn dư<\/b> sau khi trừ tải của các chức năng hiện có. Trong bài là assumption [A] cần đo trên target: detector chỉ được thêm vào nếu headroom đủ; headroom thấp hơn giả định là revisit trigger.","cs":true},{"t":"platform lead","vi":"<b>Trưởng nhóm platform<\/b>: người phụ trách nền tảng phần mềm/phần cứng của CDC. Trong bài thường là owner của các assumption về CPU, overhead hypervisor và chịu trách nhiệm xác minh bằng đo trên target."},{"t":"fleet issue","vi":"<b>Sự cố đội xe<\/b>: lỗi xuất hiện lặp lại trên nhiều xe cùng loại. Decision 2 của bài: phát hiện fleet issue ở edge + cloud summary.","aka":["fleet issues","fleet issue detection"]},{"t":"deadline safety","vi":"Cách viết tắt trong bài cho <b>deadline an toàn<\/b>: thời hạn tối đa mà telltale cảnh báo phải hiển thị theo safety requirement. Đây là tiêu chí knockout, kiểm trước khi chấm điểm."},{"t":"ATAM","vi":"Phương pháp <b>đánh giá kiến trúc theo quality scenario<\/b> do SEI (Carnegie Mellon) phát triển, thường làm dưới dạng workshop với stakeholder để tìm risk, sensitivity point và trade-off point. ATAM không tự tạo evidence — vẫn phải đo.","aka":["Architecture Tradeoff Analysis Method"],"full":"Architecture Tradeoff Analysis Method","cs":true},{"t":"ISO/IEC/IEEE 42010","vi":"Tiêu chuẩn quốc tế về <b>mô tả kiến trúc<\/b> (architecture description): xác định stakeholder, concern của họ, viewpoint và các view tương ứng. Trong bài là framework mô tả, không phải phương pháp ra quyết định.","aka":["ISO/IEC/IEEE"],"cs":true},{"t":"arc42","vi":"<b>Mẫu tài liệu kiến trúc<\/b> mã nguồn mở với các mục chuẩn (context, building block view, runtime view, deployment view, decisions, risks…). Trong bài là một lựa chọn, cùng C4, để trình bày view kiến trúc."},{"t":"goal","vi":"<b>Mục tiêu<\/b>. Trong bài: business goal (mục tiêu kinh doanh như giảm chi phí, ra mắt đúng hạn) là một decision driver định hướng lựa chọn kiến trúc.","aka":["goals"]},{"t":"business goal","vi":"<b>Mục tiêu kinh doanh<\/b> của dự án/sản phẩm (chi phí, thời điểm ra thị trường, tính năng bán hàng). Trong bài là một decision driver cùng với quality scenario ưu tiên, risk và concern của stakeholder.","aka":["business goals"]},{"t":"Nygard","vi":"Michael Nygard — người phổ biến định dạng <b>ADR ngắn<\/b> (Title, Status, Context, Decision, Consequences). 'Kiểu Nygard' trong bài là mẫu ADR tối giản theo cách này."},{"t":"MADR","vi":"<b>Mẫu ADR viết bằng Markdown<\/b>, có thêm các mục như decision drivers, considered options, pros/cons. Trong bài là một mẫu có thể dùng để ghi decision, cùng với kiểu Nygard.","full":"Markdown Architectural Decision Records","cs":true},{"t":"ADR-001","vi":"<b>Mã số ADR<\/b> minh họa: tiền tố ADR + số thứ tự tăng dần, không đánh lại số. ADR-xxx/ADR-yyy là chỗ điền số; 'Superseded by ADR-yyy' nghĩa là ADR này đã được thay bằng ADR mới mang số đó.","aka":["ADR-003","ADR-011","ADR-xxx","ADR-yyy"],"cs":true},{"t":"consequence","vi":"<b>Hệ quả<\/b> của quyết định. Trong ADR, mục Consequences ghi cả tích cực lẫn tiêu cực: dependency mới, test phải thêm, residual risk — ví dụ 'thêm offline queue có giới hạn, thêm test'."},{"t":"datasheet","vi":"<b>Tài liệu thông số kỹ thuật<\/b> do nhà cung cấp phát hành. Trong bài: số liệu từ datasheet (ví dụ overhead hypervisor dưới 5%) chỉ là assumption [A], phải đo trên target mới thành fact.","aka":["datasheets","data sheet"]},{"t":"person-month","vi":"<b>Người-tháng<\/b>: đơn vị công sức = một người làm trong một tháng. Trong bài dùng đo effort tích hợp; không được cộng thẳng với ms hay USD mà không quy đổi thang đo.","aka":["person-months","man-month","man-months"]},{"t":"USD","vi":"<b>Đô la Mỹ<\/b>, đơn vị tiền tệ. Trong bài là ví dụ đơn vị chi phí — không được cộng điểm trực tiếp với ms hay person-month.","full":"United States Dollar","cs":true},{"t":"corrupted","vi":"<b>Bị hỏng<\/b> (dữ liệu sai lệch, không đọc được). Trong bài: test với corrupted data là một test bắt buộc cho đường gửi summary và offline queue, cùng network loss, burst, rollback.","aka":["corrupted data"]},{"t":"start/end event","vi":"<b>Sự kiện bắt đầu/kết thúc<\/b> của phép đo: mốc thời gian đầu và cuối để tính latency (ví dụ từ lúc nhận frame đến lúc frame hiển thị). Mọi phương án phải đo cùng start/end event mới so sánh được.","aka":["start/end events","start/end"]},{"t":"P95/max","vi":"Các <b>điểm phân phối latency<\/b>: P50 (trung vị), P95 (95% lần đo nhỏ hơn hoặc bằng) và max (lần chậm nhất). Trong bài phải báo cả phân phối, không chỉ trung bình, vì rủi ro nằm ở phần đuôi.","aka":["P50/P95/max"]},{"t":"percentile","vi":"<b>Phân vị<\/b>: P95 = percentile 95, nghĩa là 95% lần đo nhỏ hơn hoặc bằng giá trị này. Trong bài dùng làm metric latency thay cho trung bình để bắt phần đuôi.","aka":["percentiles"]},{"t":"structure","vi":"<b>Cấu trúc<\/b>: cách hệ thống được chia thành thành phần và quan hệ giữa chúng. Một architecture decision là lựa chọn có chủ đích về structure, boundary hoặc mechanism.","aka":["structures"]},{"t":"scorecard","vi":"<b>Bảng điểm<\/b> chấm các phương án theo tiêu chí. Trong bài: không dùng scorecard để 'bù' một hard constraint bị vi phạm.","aka":["scorecards"]},{"t":"silicon","vi":"Nghĩa đen là <b>silic<\/b>; trong ngành chỉ <b>con chip phần cứng cụ thể<\/b> (SoC, bản revision). Trong bài: giữ cùng silicon cho mọi phương án khi đo để so sánh công bằng."},{"t":"SecOC","vi":"Module AUTOSAR <b>xác thực message trên mạng xe<\/b> (CAN, Ethernet…) bằng MAC và freshness value để phát hiện message giả mạo/phát lại. Trong bài là ví dụ trade-off: tăng security nhưng thêm byte MAC, CPU và latency.","aka":["Secure Onboard Communication"],"full":"Secure Onboard Communication","cs":true},{"t":"onboard","vi":"<b>Trên xe<\/b>, bên trong hệ thống của xe. Trong bài ở tên SecOC (Secure Onboard Communication) — giao tiếp an toàn giữa các ECU trên xe."},{"t":"MAC","vi":"<b>Mã xác thực message<\/b>: chuỗi byte tính từ nội dung message và khóa bí mật, giúp bên nhận phát hiện message bị giả mạo. Trong SecOC, MAC chiếm thêm vài byte trong frame và tốn CPU để tính.","full":"Message Authentication Code","cs":true},{"t":"authenticated","vi":"<b>Đã xác thực<\/b> danh tính. 'Authenticated diagnostic' là đường chẩn đoán chỉ mở cho tool/người đã được xác thực — cách giữ khả năng bảo trì mà không phá hardening.","aka":["authenticated diagnostic","authenticated diagnostics"]},{"t":"time slice","vi":"<b>Lát thời gian<\/b>: khoảng CPU được cấp cho mỗi VM/tác vụ trước khi bộ lập lịch chuyển sang cái khác. Trong bài là ví dụ sensitivity point: kích thước time slice của hypervisor quyết định latency của cluster.","aka":["time slices","slice"]},{"t":"inconsistency","vi":"<b>Sự không nhất quán, mâu thuẫn<\/b> (ví dụ hai tài liệu ghi số khác nhau). Trong bài: AI có thể giúp tìm inconsistency trong tài liệu, nhưng kỹ sư phải kiểm nguồn.","aka":["inconsistencies"]},{"t":"team-level","vi":"<b>Ở cấp nhóm<\/b>: quyết định do team tự chốt, không cần lên ARB hay các bên khác. Trong bài dành cho quyết định dễ đảo ngược, chỉ cần ghi ADR ngắn."},{"t":"spike","vi":"<b>Thử nghiệm kỹ thuật ngắn<\/b>, có giới hạn thời gian, để trả lời một câu hỏi cụ thể (ví dụ overhead hypervisor thực tế là bao nhiêu). Trong bài, prototype/spike là mức phân tích sâu cho quyết định khó đảo ngược.","aka":["spikes"]},{"t":"edge-AI","vi":"<b>AI chạy trên thiết bị biên<\/b> (ngay trên xe) thay vì trên cloud. Trong bài được nhắc là chủ đề đào sâu ở B.4.","aka":["edge AI"]},{"t":"measure","vi":"<b>Đo, phép đo<\/b>. Trong bài là chặng đo trên target theo cách có thể làm phương án trượt (falsifiable measurement).","aka":["measurements"]},{"t":"falsifiable","vi":"<b>Có thể bác bỏ<\/b>: phép đo được thiết kế sao cho kết quả có thể chứng minh phương án <b>không<\/b> đạt. Trong bài: evidence chỉ đáng tin khi phép đo có thể làm phương án trượt, không phải đo để xác nhận điều đã muốn."},{"t":"discipline","vi":"<b>Kỷ luật, thói quen làm đúng quy tắc<\/b>. 'Fact / assumption / risk discipline' trong bài là việc luôn gắn nhãn đúng [F]/[A]/[P]/[R] và mỗi assumption có owner, cách và hạn xác minh."},{"t":"decision framing","vi":"<b>Đặt khung quyết định<\/b>: nêu rõ quyết định cần chốt, owner, deadline, context, scope, variant và baseline hiện tại trước khi bàn phương án."},{"t":"trade-off matrix","vi":"<b>Bảng đánh đổi<\/b>: so sánh các phương án theo từng tiêu chí, ghi rõ mỗi phương án <b>được gì, mất gì<\/b> và evidence cần có. Khác weighted matrix ở chỗ không nhất thiết chấm điểm cộng tổng.","aka":["trade-off matrices","tradeoff matrix"]},{"t":"trade-off analysis","vi":"<b>Phân tích đánh đổi<\/b>: quy trình so sánh các phương án kiến trúc có hệ thống — chốt driver, constraint, criteria trước; đo trên target; ghi được/mất; gắn nhãn F/A/P/R; rồi ghi ADR.","aka":["tradeoff analysis"]},{"t":"decision driver","vi":"<b>Động lực quyết định<\/b>: yếu tố buộc phải quyết và định hướng lựa chọn — business goal, quality scenario ưu tiên, risk, concern của stakeholder.","aka":["decision drivers"]},{"t":"non-functional","vi":"Phi chức năng — thuộc về chất lượng (nhanh, ổn định, an toàn, bảo mật…) chứ không phải hành vi cụ thể. Trong bài là một trong ba loại requirement: functional, non-functional và constraint.","aka":["non functional","nonfunctional"]},{"t":"derived","vi":"Được suy ra / dẫn xuất từ một thứ ở cấp cao hơn. Trong bài, derived requirement là requirement cấp component sinh ra khi phân rã một system requirement."},{"t":"derived requirement","vi":"Requirement <b>dẫn xuất<\/b>: requirement cấp component (vd SW-STM-01) được tạo ra khi phân rã system requirement, có ID riêng và link ngược lên requirement gốc. Thiếu link ngược thì trace hai chiều bị đứt.","aka":["derived requirements"]},{"t":"SYS-01","vi":"Mã định danh <b>minh họa<\/b> trong bài: SYS-xx = system requirement, REQ-xx = requirement viết thử, SW-xx = software/derived requirement (PAR = parser, STM = state manager, DIA = diagnostic), TC-xx = test case. Mỗi mã giúp trace hai chiều need → requirement → component → test.","aka":["SYS-02","SYS-03","REQ-01","REQ-02","REQ-03","SW-PAR-03","SW-STM-01","SW-DIA-07","SW-xx","SW-05","TC-12"],"cs":true},{"t":"SpeedSample","vi":"Tên kiểu dữ liệu <b>ví dụ<\/b> trong bài: một mẫu tốc độ xe gồm value (km/h), quality/status và timestamp. Case mở đầu: bản OTA đổi field value sang m/s mà không đổi version — breaking change âm thầm."},{"t":"missing","vi":"Thiếu, không có. Trong bài: trạng thái dữ liệu không nhận được (frame không đến, timeout); không được biểu diễn missing bằng 0 nếu 0 là giá trị hợp lệ — dùng value + quality + timestamp."},{"t":"task","vi":"Tác vụ: một luồng thực thi được scheduler của RTOS/OS lập lịch chạy (theo chu kỳ hoặc theo sự kiện). Trong embedded architecture, behavior được phân bổ vào task cụ thể, có priority và timing budget riêng.","aka":["tasks"]},{"t":"periodic task","vi":"Tác vụ chạy <b>theo chu kỳ<\/b> cố định (vd mỗi 10 ms). Dễ phân tích timing, nhưng tốn CPU khi không có dữ liệu mới; chu kỳ phải khớp freshness requirement của signal.","aka":["periodic tasks"]},{"t":"atomic","vi":"Nguyên tử — không chia nhỏ hơn được, hoặc xảy ra trọn vẹn/không xảy ra. Trong bài có hai nghĩa: requirement atomic (mỗi câu một behavior) và ghi atomic (lưu dữ liệu không bị dở dang khi mất điện)."},{"t":"traceable","vi":"Truy nguyên được. Requirement traceable có ID, version, nguồn và link lên need, xuống component/test, nên biết được nó từ đâu ra và được kiểm bằng gì."},{"t":"set","vi":"Tập hợp, bộ. Trong bài “requirement set” là bộ requirement của một tính năng/unit, được viết ở bước 1–2 và là đầu vào cho allocation.","aka":["sets"]},{"t":"requirement set","vi":"Bộ requirement của một tính năng (vd speed signal), gồm functional, NFR và constraint, mỗi câu có ID, ngưỡng, owner và cách verify. Là phần đầu tiên của đầu ra unit B.3."},{"t":"elicitation","vi":"Khai thác / thu thập yêu cầu: hỏi đủ các bên liên quan (HMI, safety, diagnostic, OEM…) để lấy nhu cầu thật. Trong bài: không âm thầm chọn phe khi các bên mâu thuẫn mà ghi conflict và chờ owner chốt."},{"t":"primary","vi":"Chính, chủ yếu. Trong allocation matrix, P = primary là component chịu trách nhiệm chính cho một requirement; tránh tình trạng “mọi component cùng lo”."},{"t":"contributing","vi":"Đóng góp một phần. Trong allocation matrix, C = contributing là component tham gia thực hiện requirement nhưng không chịu trách nhiệm chính (P)."},{"t":"clear","vi":"Rõ ràng, chỉ có một nghĩa. Thuộc tính đầu tiên của requirement tốt: hai người đọc phải hiểu cùng một behavior; tránh từ mơ hồ như “nhanh”, “hợp lý”, “nếu cần”."},{"t":"complete","vi":"Đầy đủ. Requirement complete có điều kiện, variant, failure behavior, ngưỡng và owner — không chỉ mô tả happy path."},{"t":"consistent","vi":"Nhất quán, không mâu thuẫn. Requirement consistent không xung đột với requirement khác về giá trị, đơn vị, thuật ngữ (vd không có hai timeout khác nhau cho cùng một signal)."},{"t":"verifiable","vi":"Kiểm chứng được: có test, inspection, analysis hoặc demonstration cho kết quả pass/fail rõ ràng. Không có ngưỡng hoặc oracle thì requirement không verifiable."},{"t":"verifiability","vi":"Khả năng kiểm chứng: mức độ một requirement có thể được chứng minh đạt/không đạt bằng phép đo hoặc kiểm tra khách quan. Là tiêu chí chấm chất lượng requirement trong bài."},{"t":"current","vi":"Hiện tại, còn hiệu lực. Trong bài: HMI không được hiển thị dữ liệu stale (cũ) như thể là giá trị current (mới, đang đúng)."},{"t":"allocate","vi":"Phân bổ, giao cho. Allocate requirement là gán nó cho component chịu trách nhiệm (primary/contributing); allocate budget là chia ngưỡng latency/memory cho từng bước.","aka":["allocated","allocating"]},{"t":"allocation matrix","vi":"Bảng phân bổ: hàng là system requirement, cột là component (đánh P = primary, C = contributing), kèm derived requirement và phần budget. Cho thấy ai làm gì và requirement nào chưa có chủ.","aka":["allocation matrices"]},{"t":"requirement allocation","vi":"Việc gán từng requirement hệ thống cho component cụ thể, tạo derived requirement và chia budget. Là bước 3 trong tám bước của bài."},{"t":"closure","vi":"Sự đóng lại, khép kín. Trong bài “verification, validation và closure” là bước cuối: có evidence pass, link trace đầy đủ thì mới đóng requirement/issue."},{"t":"invalid","vi":"Không hợp lệ. Trong bài là một trạng thái của dữ liệu (Valid/Stale/Invalid): frame hỏng (sai CRC, ngoài range) phải chuyển sang Invalid, không được thành Valid."},{"t":"DB","vi":"Cơ sở dữ liệu: nơi lưu dữ liệu có cấu trúc. Trong bài là một lựa chọn persistence (RAM, flash, DB, cloud); embedded DB dùng cho config/state cần version và crash consistency.","full":"Database","cs":true},{"t":"KV","vi":"Khóa–giá trị: kiểu lưu trữ mỗi mục gồm một khóa và một giá trị. KV/embedded DB trong bài dùng lưu config/state có version trên ECU.","full":"Key-Value","cs":true},{"t":"key-value","vi":"Khóa–giá trị: dữ liệu được tra theo khóa (key) để lấy giá trị (value).","aka":["key value"]},{"t":"key-value store","vi":"Kho lưu khóa–giá trị: database đơn giản lưu cặp key → value, hay dùng trên ECU cho config/state. Rủi ro cần kiểm: crash consistency khi mất điện và migration khi schema đổi.","aka":["key-value stores","KV store"]},{"t":"persist","vi":"Lưu bền vững (vào flash/DB) để còn sau khi reboot. Trong bài: không persist giá trị speed cũ rồi khôi phục thành Valid sau reboot; chỉ persist khi có purpose và retention.","aka":["persisted","persisting","persists"]},{"t":"drop-oldest","vi":"Chính sách khi queue đầy: <b>bỏ phần tử cũ nhất<\/b> để nhận dữ liệu mới. Hợp với signal cần giá trị mới nhất như speed."},{"t":"drop-newest","vi":"Chính sách khi queue đầy: <b>bỏ phần tử mới đến<\/b>, giữ dữ liệu cũ trong hàng. Hợp khi thứ tự/đầy đủ các phần tử đầu quan trọng hơn độ mới."},{"t":"optional","vi":"Tùy chọn, không bắt buộc. Field optional có thể vắng mặt; khi thêm field mới thì nên là optional có giá trị mặc định rõ để giữ backward compatibility."},{"t":"mandatory","vi":"Bắt buộc. Field mandatory phải luôn có trong message; interface contract phải ghi rõ field nào mandatory, field nào optional."},{"t":"optional field","vi":"Trường dữ liệu không bắt buộc. Cách an toàn để mở rộng schema: thêm optional field có giá trị mặc định, consumer cũ bỏ qua được.","aka":["optional fields"]},{"t":"mandatory field","vi":"Trường dữ liệu bắt buộc phải có. Thêm hoặc xóa mandatory field thường là breaking change cần version mới và migration.","aka":["mandatory fields"]},{"t":"type","vi":"Kiểu dữ liệu (số nguyên, số thực, chuỗi, enum…). Trong data dictionary, mỗi field phải ghi type, unit, range, mandatory/optional và version.","aka":["types"]},{"t":"checksum","vi":"Giá trị kiểm tra tính toàn vẹn tính từ dữ liệu; đọc lại mà không khớp là dữ liệu hỏng. Trong bài dùng trong E2E protection trên bus và khi lưu dữ liệu.","aka":["checksums"]},{"t":"cyclic","vi":"Theo chu kỳ, vòng lặp. Xuất hiện trong CRC (Cyclic Redundancy Check) và trong message/task gửi hoặc chạy định kỳ."},{"t":"E2E","vi":"Bảo vệ đầu–cuối: thêm counter + checksum/CRC vào message để bên nhận phát hiện dữ liệu hỏng, mất, lặp hay cũ trên đường truyền. Trong bài là cơ chế integrity cho signal trên bus.","full":"End-to-End","cs":true},{"t":"reader","vi":"Bên đọc dữ liệu (consumer). Trong bài: “old/new reader × old/new data” là ma trận kiểm compatibility khi schema đổi.","aka":["readers"]},{"t":"writer","vi":"Bên ghi dữ liệu. Trong data dictionary, cột Owner (writer) chỉ component duy nhất được ghi field đó — single writer giúp tránh xung đột dữ liệu.","aka":["writers"]},{"t":"tolerant","vi":"Chịu được, khoan dung. Dùng trong “tolerant reader”: consumer bỏ qua field không biết thay vì lỗi."},{"t":"tolerant reader","vi":"Mẫu thiết kế: consumer <b>bỏ qua field không nhận ra<\/b> và chỉ dùng field mình cần, nhờ đó producer thêm field optional mà không làm hỏng consumer cũ (nếu protocol cho phép)."},{"t":"store","vi":"Lưu trữ; hoặc nơi lưu (kho). Trong bài: KV store, nơi lưu config/state trên ECU.","aka":["stores","stored","storing"]},{"t":"false","vi":"Sai, giả. Trong bài “false Valid” là dữ liệu bị đánh dấu Valid trong khi thực tế đã cũ hoặc hỏng — lỗi nguy hiểm vì HMI tin và hiển thị."},{"t":"duplicate","vi":"Trùng lặp: cùng một message/frame đến hai lần. Runtime view phải mô tả hệ thống xử lý duplicate thế nào (vd dùng counter để bỏ bản lặp).","aka":["duplicates","duplicated"]},{"t":"meaning","vi":"Ý nghĩa của một field (semantics). Đổi meaning của field — dù giữ nguyên tên và type — là breaking change cần version và migration."},{"t":"fuel","vi":"Nhiên liệu. Trong bài “fuel level” (mức nhiên liệu) là ví dụ signal khác để người học tự lặp lại tám bước."},{"t":"fuel level","vi":"Mức nhiên liệu trong bình, một signal hiển thị trên cluster. Bài gợi ý dùng nó làm bài luyện: áp lại tám bước như speed signal."},{"t":"sentinel","vi":"Giá trị đặc biệt quy ước nghĩa là “không có dữ liệu” (vd -1, 0xFFFF). Chỉ an toàn khi không trùng giá trị hợp lệ; dùng 0 cho speed sẽ lẫn “xe dừng” với “không biết tốc độ”.","aka":["sentinel value","sentinels"]},{"t":"event-driven","vi":"Hướng sự kiện: phần mềm chỉ chạy khi có message/interrupt đến. Tiết kiệm CPU nhưng burst có thể gây quá tải, nên cần queue có giới hạn và policy khi đầy.","aka":["event driven"]},{"t":"publish-subscribe","vi":"Mẫu xuất bản–đăng ký: một producer publish dữ liệu, nhiều consumer subscribe nhận. Contract và version phải rõ; consumer chậm không được làm chậm producer.","aka":["pub-sub"]},{"t":"append-only","vi":"Chỉ ghi thêm vào cuối, không sửa/xóa bản ghi cũ. Append-only log hợp cho diagnostic/audit; rủi ro cần kiểm: dung lượng, flash wear và privacy.","aka":["append-only log"]},{"t":"wear","vi":"Hao mòn. Flash wear: bộ nhớ flash chỉ chịu được số lần ghi/xóa giới hạn, ghi log quá nhiều sẽ làm mòn và hỏng sớm."},{"t":"corrupt","vi":"Hỏng, bị sai lệch (dữ liệu). Một kịch bản test bắt buộc: frame corrupt phải bị phát hiện (CRC/range) và chuyển Invalid."},{"t":"happy","vi":"Vui vẻ; trong “happy path” nghĩa là trường hợp mọi thứ đều chạy đúng, không lỗi."},{"t":"happy path","vi":"Đường chạy bình thường khi không có lỗi. Requirement chỉ mô tả happy path là chưa complete — thiếu hành vi khi timeout, lỗi, reboot.","aka":["happy paths"]},{"t":"demonstration","vi":"Trình diễn: phương pháp verification bằng cách vận hành hệ thống và quan sát kết quả. Là một trong bốn cách verify: test, inspection, analysis, demonstration."},{"t":"proof","vi":"Bằng chứng / chứng minh. Bài nhấn mạnh timing budget chỉ là phân bổ, không phải proof — phải đo trên target mới chứng minh được."},{"t":"high","vi":"Cao. “High load” = tải cao: điều kiện đo timing bắt buộc vì latency xấu nhất thường xuất hiện khi hệ thống bận."},{"t":"high load","vi":"Tải cao (CPU, bus, I/O bận). Là một điều kiện đo latency trên target; số đo khi rảnh không chứng minh được deadline."},{"t":"cold start","vi":"Khởi động nguội: bật hệ thống từ trạng thái tắt hoàn toàn, cache rỗng. Là kịch bản đo timing/boot time khó nhất, phải có trong phép đo trên target.","aka":["cold starts"]},{"t":"bus fault","vi":"Lỗi trên bus truyền thông (mất frame, nhiễu, bus-off). Phải đo/kiểm hành vi khi có bus fault, không chỉ khi bus khỏe.","aka":["bus faults"]},{"t":"bus overload","vi":"Quá tải bus: lượng message vượt khả năng truyền, gây trễ hoặc mất frame. Là kịch bản verify bắt buộc cho speed signal."},{"t":"double","vi":"Kép, gấp đôi. Trong “double buffer”: hai vùng đệm luân phiên."},{"t":"double buffer","vi":"Đệm kép: hai buffer, một bên ghi trong khi bên kia được đọc, rồi hoán đổi — giúp truyền dữ liệu giữa task/ISR không chặn và không đọc dữ liệu dở dang.","aka":["double buffering","double buffers"]},{"t":"ISR","vi":"Hàm xử lý ngắt: đoạn code chạy ngay khi phần cứng báo interrupt (vd frame CAN đến). ISR phải rất ngắn; dữ liệu chuyển sang task qua ring/double buffer.","aka":["ISRs"],"full":"Interrupt Service Routine","cs":true},{"t":"routine","vi":"Thủ tục, hàm (đoạn code thực hiện một việc). Trong bài xuất hiện trong ISR — Interrupt Service Routine.","aka":["routines"]},{"t":"dictionary","vi":"Từ điển. “Data dictionary” là bảng mô tả mọi field dữ liệu."},{"t":"data dictionary","vi":"Từ điển dữ liệu: bảng mô tả từng field — type, unit, range, mandatory/optional, owner (writer), consumer, timing, persistence, integrity, version. Là “nguồn sự thật” cho data design.","aka":["data dictionaries"]},{"t":"screen","vi":"Màn hình. “Screen freeze” (màn hình đứng hình) là case lỗi của Lesson 1 được nhắc lại trong bài.","aka":["screens"]},{"t":"state manager","vi":"Component quản lý trạng thái: duy nhất được quyết định và publish trạng thái của signal (Valid/Stale/Invalid); HMI chỉ đọc. Trong ví dụ, nó là primary cho requirement phát hiện timeout.","aka":["state managers"]},{"t":"data design","vi":"Thiết kế dữ liệu: định nghĩa schema, owner, timing, persistence, integrity và quy tắc version/compatibility cho dữ liệu đi qua hệ thống. Là một trụ cột của bài B.3."},{"t":"embedded architecture","vi":"Kiến trúc nhúng: phân bổ behavior vào CPU, memory, task, network, storage và failure boundary trên ECU/SoC thật, có ràng buộc timing và tài nguyên."},{"t":"embedded pattern","vi":"Mẫu thiết kế nhúng quen thuộc (periodic task, event-driven, state machine, publish-subscribe, ring/double buffer, watchdog/health monitor), mỗi mẫu có rủi ro riêng cần kiểm.","aka":["embedded patterns"]},{"t":"failure boundary","vi":"Ranh giới lỗi: vùng mà lỗi bên trong không được lan ra ngoài (process, VM, partition). Embedded architecture phải chỉ rõ failure boundary.","aka":["failure boundaries"]},{"t":"diagnostic event","vi":"Sự kiện chẩn đoán: bản ghi do module diagnostic tạo khi phát hiện bất thường (vd speed timeout), dùng cho DTC/log và điều tra sau.","aka":["diagnostic events"]},{"t":"diagnostic log","vi":"Nhật ký chẩn đoán, thường lưu append-only. Cần mục đích, thời hạn giữ và tối thiểu hóa dữ liệu để vừa debug được vừa tôn trọng privacy.","aka":["diagnostic logs"]},{"t":"host test","vi":"Test chạy trên máy phát triển (PC/CI), không phải trên ECU thật. Nhanh, rẻ nhưng không chứng minh được timing/tài nguyên trên target.","aka":["host tests"]},{"t":"target test","vi":"Test chạy trên phần cứng đích (ECU/SoC thật). Bắt buộc cho timing, memory và hành vi phần cứng; host pass chưa đủ.","aka":["target tests"]},{"t":"consumer test","vi":"Test viết từ phía consumer để kiểm producer vẫn đúng contract mà consumer cần. Case SpeedSample: test của producer đều xanh nhưng thiếu consumer test nên không bắt được đổi đơn vị.","aka":["consumer tests","consumer-driven contract test"]},{"t":"runtime state","vi":"Trạng thái lúc chạy (dữ liệu trong RAM, state machine hiện tại). Data design phải nói rõ runtime state nào mất khi reboot, cái nào được persist."},{"t":"schema migration","vi":"Chuyển dữ liệu đã lưu từ schema cũ sang schema mới (vd sau OTA). Trong bài: reboot/schema migration không được tạo ra false Valid.","aka":["schema migrations","reboot/schema migration"]},{"t":"data ownership","vi":"Quyền sở hữu dữ liệu: ai là writer duy nhất, ai duyệt thay đổi schema. Thiếu data ownership thì nhiều component cùng ghi và không ai chịu trách nhiệm."},{"t":"data lifecycle","vi":"Vòng đời dữ liệu: tạo ra, dùng, lưu, migrate, hết hạn và xóa. Data design phải định nghĩa lifecycle, đặc biệt qua reboot và OTA."},{"t":"crash consistency","vi":"Nhất quán sau sự cố: dữ liệu lưu vẫn đúng/khôi phục được khi mất điện hay crash giữa lúc ghi. Đạt được bằng ghi atomic, checksum, journal hoặc A/B copy."},{"t":"freshness requirement","vi":"Yêu cầu độ mới: dữ liệu phải không cũ hơn một ngưỡng (vd timeout đã baseline) khi được dùng. Chu kỳ task và timeout phải khớp requirement này.","aka":["freshness requirements"]},{"t":"open issue","vi":"Vấn đề còn mở, chưa được giải quyết/chốt. Requirement còn open issue (thiếu ngưỡng, có conflict) phải đánh dấu blocked thay vì tự đoán.","aka":["open issues"]},{"t":"over-the-air update","vi":"Cập nhật phần mềm qua mạng không dây (OTA). Trong bài, bản OTA đổi schema là nguồn rủi ro chính cho compatibility và migration dữ liệu.","aka":["over-the-air updates"]},{"t":"interface model","vi":"Mô hình interface: mô tả các message/API giữa component cùng schema, owner, timing và compatibility. Là đầu ra bước 5 của bài (data/interface model).","aka":["data/interface model"]},{"t":"verification method","vi":"Phương pháp kiểm chứng requirement: test, inspection, analysis hoặc demonstration. Mỗi requirement phải ghi rõ method và tiêu chí pass/fail.","aka":["verification methods","test/inspection/analysis"]},{"t":"raw frame","vi":"Frame thô, nguyên gốc nhận từ bus chưa giải mã. Bài cảnh báo không persist raw frame vô hạn nếu không có mục đích và thời hạn giữ.","aka":["raw frames"]},{"t":"old","vi":"Cũ. Trong bài “old/new reader × old/new data” là các tổ hợp phiên bản cũ/mới phải kiểm khi schema đổi."},{"t":"new","vi":"Mới. Dùng trong ma trận compatibility old/new reader × old/new data."},{"t":"purpose","vi":"Mục đích. Trong bài: dữ liệu chỉ được persist/log khi có purpose (lý do dùng) và retention (thời hạn giữ) rõ ràng."},{"t":"tag","vi":"Nhãn/mã định danh field trong schema (vd tag trong Protobuf). Không tái sử dụng ID/tag của field đã xóa vì consumer cũ sẽ hiểu sai.","aka":["tags","tagged"]},{"t":"encoding","vi":"Cách mã hóa giá trị thành bit/byte (scale, offset, endian, kiểu số). Interface contract phải ghi encoding/range/unit để hai bên hiểu cùng một giá trị.","aka":["encodings"]},{"t":"Valid/Stale/Invalid","vi":"Mô hình trạng thái chất lượng của một signal: <b>Unknown<\/b> (chưa có dữ liệu, vd sau boot), <b>Valid<\/b> (mới và hợp lệ), <b>Stale<\/b> (quá timeout, đã cũ), <b>Invalid<\/b> (hỏng: sai CRC/range). Trong bài do state manager quyết định; HMI hiển thị theo trạng thái này.","aka":["Unknown/Valid/Stale/Invalid"]},{"t":"timeout/error behavior","vi":"Hành vi khi dữ liệu không đến đúng hạn hoặc bị lỗi: bên nào phát hiện, sau bao lâu, báo trạng thái gì, consumer hiển thị gì. Bài coi đây là lỗ hổng hay gặp nhất của interface contract — hai bên đều “đúng spec” nhưng xử lý khác nhau.","aka":["timeout/error behaviour","timeout behavior"]},{"t":"mandatory/optional","vi":"Cột/thuộc tính trong schema và interface contract cho biết field nào bắt buộc phải có, field nào có thể vắng. Quyết định cách mở rộng schema mà không làm hỏng consumer cũ.","aka":["mandatory/optional field","mandatory/optional fields"]},{"t":"KV/embedded DB","vi":"Lưu trữ khóa–giá trị hoặc cơ sở dữ liệu nhúng chạy ngay trên ECU, dùng cho config/state cần version. Lưu bền qua reboot nhưng kéo theo yêu cầu crash consistency và migration.","aka":["KV/embedded DBs"]},{"t":"CRC/range","vi":"Hai phép kiểm integrity mà parser thực hiện khi nhận frame: CRC phát hiện bit bị hỏng trên đường truyền, range check loại giá trị nằm ngoài khoảng hợp lệ. Frame không qua được thì chuyển Invalid.","aka":["CRC/range check"]},{"t":"verification/validation","vi":"Kiểm chứng và thẩm định (V&amp;V). Verification: làm <i>đúng<\/i> spec chưa (test, inspection, analysis)? Validation: làm <i>đúng thứ người dùng cần<\/i> chưa (vd người lái có thấy số cũ như số hiện tại không)? Requirement chỉ closure khi đủ cả hai.","aka":["V&V"]},{"t":"old/new reader","vi":"Ma trận compatibility khi schema đổi: kiểm mọi tổ hợp reader (consumer) cũ/mới × data (producer hoặc dữ liệu đã lưu) cũ/mới, kể cả ô sau rollback. Ô nào ra kết quả sai là breaking change.","aka":["old/new data"]},{"t":"data/interface contract","vi":"Thỏa thuận chính thức về dữ liệu và interface giữa producer và consumer: field, type, unit/range, mandatory/optional, version, compatibility rule, timeout/error behavior, quality/status, permission. Trong bài thuộc phạm vi B.3; tầm cả xe ở A.4.","aka":["data/interface contracts"]},{"t":"logical/runtime/deployment view","vi":"Bộ ba góc nhìn kiến trúc trong bài: logical (component nào làm gì), runtime (timeout, duplicate, restart diễn ra theo thời gian thế nào), deployment (chạy ở ECU/VM, task, bus nào).","aka":["logical/runtime/deployment views"]},{"t":"baseline/build/variant","vi":"Bộ ba định danh cấu hình mà evidence phải khớp: baseline (bản requirement/thiết kế đã chốt), build (bản phần mềm cụ thể), variant (cấu hình xe/thị trường). Evidence không khớp bộ ba này thì không dùng để đóng requirement."},{"t":"latency/memory/CPU","vi":"Ba loại budget tài nguyên được chia cho từng component trong allocation matrix: thời gian trễ, bộ nhớ và tải CPU. Tổng phần chia phải còn margin so với budget hệ thống và được đo trên target.","aka":["memory/CPU budget","latency/memory/CPU budget"]},{"t":"wave","vi":"Đợt, làn sóng. Trong migration là <b>một đợt chuyển đổi<\/b> có phạm vi riêng (service, data domain, variant hoặc team), có entry/exit criteria, dependency và đường abort/rollback riêng.","aka":["waves"]},{"t":"wave migration","vi":"Migration chia theo đợt (wave). Bảng wave migration ghi mỗi wave/phase một dòng: scope, strategy, entry/exit criteria, gate/evidence, abort/rollback và owner."},{"t":"wave plan","vi":"Kế hoạch chia migration thành các wave: wave nào đi trước, phụ thuộc gì, điều kiện vào/ra của từng wave và cách dừng/lùi nếu wave đó lỗi.","aka":["wave plans"]},{"t":"wave/phase","vi":"Đợt/pha của migration: mỗi dòng trong bảng wave migration là một wave hoặc một phase (Discover, Pilot, Parallel, Cutover, Retire…) với điều kiện vào/ra riêng."},{"t":"coexistence","vi":"Cùng tồn tại. Chiến lược migration trong đó hệ cũ và hệ mới <b>chạy song song<\/b> một thời gian (“ở cả hai nhà”); cần chỉ định system of record, reconciliation định kỳ và ngày kết thúc coexistence."},{"t":"big bang","vi":"Chiến lược migration <b>chuyển toàn bộ một lần<\/b> trong một lần cutover. Hợp với hệ nhỏ, coupling chặt, chấp nhận được downtime; nhưng blast radius lớn, rollback khó nên cần rehearsal và go/no-go checklist. Dạng gộp liệt kê đủ bốn chiến lược: big bang, incremental, strangler, coexistence.","aka":["big bang/incremental/strangler/coexistence"]},{"t":"strangler fig","vi":"Cây đa bóp cổ: loài cây mọc bao quanh cây chủ rồi dần thay thế nó. Là nguồn gốc tên chiến lược migration <b>strangler<\/b>: hệ mới mọc quanh hệ cũ và thay dần từng phần."},{"t":"cutover","vi":"Thời điểm/bước <b>chuyển traffic và consumer chính sang hệ mới<\/b>. Copy dữ liệu xong chưa phải cutover thành công: phải kiểm mọi consumer đã đổi endpoint/token và cache không còn trỏ bản cũ.","aka":["cut-over","cutovers"]},{"t":"registry","vi":"Kho đăng ký có quản lý phiên bản. Trong bài thường là artifact registry/model registry: nơi lưu image, model, package đã build và ký để pipeline, OTA backend và xe lấy về.","aka":["registries"]},{"t":"artifact registry","vi":"Kho lưu artifact (image, package, model) đã build, có version, chữ ký và provenance. Chuyển artifact registry sang hệ mới là một migration: phải liệt kê mọi consumer của registry (pipeline, OTA backend…)."},{"t":"flaky test","vi":"Test lúc pass lúc fail dù code không đổi. Tầng càng gần phần cứng thật (HIL) càng hay gặp; cần phân loại nguyên nhân, giao owner, đánh dấu/quarantine có hạn, ghi trạng thái trong evidence.","aka":["flaky tests"]},{"t":"flaky rate","vi":"Tỷ lệ test flaky trong pipeline. Là một metric observability của pipeline: tăng lên nghĩa là evidence kém tin cậy và có thể đang che lỗi timing thật."},{"t":"verifier","vi":"Bộ/người kiểm chứng. Trong governance AI (AI-10), verifier ba tầng L1–L3 kiểm output của agent: tầng xác định (schema, build, test, exit code) → quy tắc nghiệp vụ/oracle → phán đoán; verifier tự đọc kết quả máy, không tin lời agent tự báo.","aka":["verifiers"]},{"t":"resilience","vi":"Khả năng chống chịu và phục hồi. Trong bài: khi backend chậm, lỗi hoặc mất vùng thì hệ xử lý thế nào — timeout, retry có backoff/jitter, circuit breaker, idempotency, bounded queue, store-and-forward, RTO/RPO."},{"t":"egress","vi":"Chiều dữ liệu đi ra. Phí egress là tiền cloud tính khi dữ liệu ra khỏi cloud/region; là khoản thường bị quên khi tính TCO và làm exit cost lớn."},{"t":"residency","vi":"Nơi lưu trú của dữ liệu: dữ liệu được phép nằm ở quốc gia/region nào theo luật và hợp đồng. Phải quyết định trước khi chọn region, tenant và pipeline cloud."},{"t":"dataset","vi":"Tập dữ liệu. Trong bài là dữ liệu dùng để phân tích hoặc huấn luyện/đánh giá model; phải biết lineage (model học từ dataset nào, version nào) và áp minimization/pseudonymization.","aka":["datasets","data set"]},{"t":"negative","vi":"Âm, phủ định. Trong bài thường đi trong <i>negative case<\/i> (input sai để chứng minh gate biết fail) và <i>false negative<\/i> (bỏ sót lỗi thật)."},{"t":"negative case","vi":"Trường hợp kiểm với input sai/không hợp lệ. Gate phải “đỏ được”: đã chứng minh nó fail với negative case (ví dụ artifact chữ ký sai); nếu không, gate chỉ là nghi thức.","aka":["negative cases"]},{"t":"positive","vi":"Dương, khẳng định. Trong bài dùng trong <i>false positive<\/i> (báo có lỗi nhưng thật ra không có)."},{"t":"false negative","vi":"Âm tính giả: hệ <b>bỏ sót lỗi/bất thường có thật<\/b>. Thường nguy hiểm hơn false positive với chức năng liên quan an toàn.","aka":["false negatives"]},{"t":"false alarm","vi":"Báo động nhầm. Trong rollout model display-anomaly, tỷ lệ false alarm được đo theo từng cohort cùng install, resource và telemetry coverage.","aka":["false alarms"]},{"t":"alarm","vi":"Báo động, cảnh báo. Trong bài: false alarm — model hoặc hệ giám sát báo bất thường khi không có.","aka":["alarms"]},{"t":"plane","vi":"Mặt phẳng/tầng logic. Trong kiến trúc chia data plane (đường dữ liệu runtime) và control plane (đường điều khiển/cấu hình) để quyết định đặt phần nào ở edge, phần nào ở cloud.","aka":["planes"]},{"t":"data plane","vi":"Tầng xử lý/chuyển dữ liệu lúc chạy. Ví dụ trong bài: upload trip summary lên cloud; luồng tín hiệu tốc độ đến cluster."},{"t":"control plane","vi":"Tầng điều khiển: cấu hình, chính sách, điều phối (ví dụ OTA campaign, feature flag). Không chuyển dữ liệu nghiệp vụ nhưng quyết định hệ chạy thế nào."},{"t":"safety boundary","vi":"Ranh giới an toàn: phần chức năng safety/real-time critical phải nằm ở edge và không được phụ thuộc cloud; cloud chỉ ở ngoài ranh giới này."},{"t":"automated","vi":"Được tự động hóa: chạy bằng máy/pipeline thay vì làm tay. Trong bài: automated test theo tầng trong CI/CD."},{"t":"automated test","vi":"Test chạy tự động trong pipeline. Bài chia theo tầng: unit/static mỗi commit, SIL/contract mỗi merge, HIL/target nightly hoặc release candidate; mỗi tầng trả lời một câu hỏi khác.","aka":["automated tests","automated testing"]},{"t":"utility tree","vi":"Cây tiện ích (kỹ thuật ATAM): đi từ quality attribute → sub-attribute → scenario cụ thể, rồi chấm business value và technical risk (H/M/L) để ưu tiên; scenario H/H xử lý trước.","aka":["utility trees"]},{"t":"utility","vi":"Tính hữu ích, giá trị sử dụng. Trong bài dùng trong <i>utility tree<\/i> — cây ưu tiên các quality attribute theo giá trị và rủi ro."},{"t":"tree","vi":"Cây (cấu trúc phân nhánh). Trong bài: utility tree — chia quality attribute thành nhánh nhỏ dần tới scenario cụ thể.","aka":["trees"]},{"t":"tenant","vi":"Người thuê: vùng tài nguyên riêng, tách biệt của một khách hàng/tổ chức trên cloud hoặc công cụ SaaS. Dữ liệu chỉ được đưa vào tenant/tool đã duyệt.","aka":["tenants"]},{"t":"tenant/tool","vi":"Tenant hoặc công cụ (AI) đã được duyệt: data boundary chỉ cho dữ liệu đi vào môi trường cloud/tool đã kiểm hợp đồng, quyền và retention."},{"t":"abort","vi":"Hủy, dừng giữa chừng. Trong migration/rollout là quyết định dừng bước đang chạy khi chạm trigger/threshold, rồi lùi về trạng thái an toàn.","aka":["aborted","aborts"]},{"t":"abort path","vi":"Đường dừng/lùi đã chuẩn bị sẵn cho mỗi pha migration hoặc rollout: điều kiện nào thì dừng, lùi về đâu, ai quyết. Tồn tại ở mọi pha cho tới trước Retire.","aka":["abort paths"]},{"t":"abort/rollback","vi":"Dừng và quay lui: đường abort/rollback chạy dọc mọi pha migration, cho phép dừng lại và trả về hệ cũ khi một exit criterion không đạt."},{"t":"token","vi":"Mã thông báo: chuỗi bí mật dùng để xác thực/ủy quyền gọi service. Sau cutover, consumer vẫn có thể dùng token cũ; token trong log (token debug) là dữ liệu nhạy cảm phải sanitize.","aka":["tokens"]},{"t":"lineage","vi":"Dòng gốc, phả hệ dữ liệu: dữ liệu/model đến từ đâu, qua các bước biến đổi nào, version nào. Cần để truy lỗi, xóa dữ liệu đúng quy định và tái tạo model.","aka":["data lineage"]},{"t":"model/data lineage","vi":"Lineage của model và dữ liệu: model được huấn luyện từ dataset nào, version nào, bằng code/config nào — phần bắt buộc khi quản model edge-AI như artifact phần mềm."},{"t":"retire","vi":"Cho nghỉ hưu, ngừng dùng. Pha cuối của migration: tắt hẳn hệ cũ sau khi mọi consumer đã chuyển; trước Retire luôn còn đường abort/rollback.","aka":["retired"]},{"t":"RTO","vi":"Mục tiêu thời gian phục hồi: hệ phải khôi phục trong bao lâu sau sự cố. Là tham số thiết kế resilience cho backend.","aka":["Recovery Time Objective"],"full":"Recovery Time Objective","cs":true},{"t":"RPO","vi":"Mục tiêu điểm phục hồi: chấp nhận mất tối đa bao nhiêu dữ liệu (tính theo thời gian) khi khôi phục sau sự cố.","aka":["Recovery Point Objective"],"full":"Recovery Point Objective","cs":true},{"t":"RTO/RPO","vi":"Cặp mục tiêu phục hồi của backend: RTO — khôi phục trong bao lâu; RPO — được mất tối đa bao nhiêu dữ liệu.","cs":true},{"t":"rerun","vi":"Chạy lại. Trong bài: bấm rerun đến khi test xanh rồi merge là sai, vì che mất instability thật (race, timing) sẽ lộ ra trên xe.","aka":["reruns","re-run"]},{"t":"retest","vi":"Kiểm lại sau khi sửa. Inspection record cần ghi retest để chứng minh finding đã được đóng đúng.","aka":["re-test"]},{"t":"human gate","vi":"Cổng người duyệt: điểm bắt buộc có người có thẩm quyền xem xét và ký trước khi đi tiếp; AI không được tự vượt qua hay tự cấp ngoại lệ.","aka":["human gates"]},{"t":"human oversight","vi":"Sự giám sát của con người (AI-12): xác định ai ký, ai chịu trách nhiệm cho các bước AI tham gia."},{"t":"oversight","vi":"Sự giám sát, theo dõi. Trong bài: human oversight — con người giám sát và chịu trách nhiệm cho quyết định có AI tham gia."},{"t":"human-in-the-loop","vi":"Người trong vòng lặp: con người <b>bắt buộc tham gia quyết định<\/b>, đặt tại mọi bước thuộc nhóm Người (release approval, waiver, ký image).","aka":["HITL"]},{"t":"delegation","vi":"Sự ủy quyền, giao việc. Trong bài: mức agent được tự làm tới đâu, ghi trong Delegation Map (AI-05)."},{"t":"Delegation Map","vi":"Bản đồ ủy quyền (AI-05): mỗi bước của use case thuộc Máy, Agent hay Người, và agent ở mức L0–L5 nào. Mức thật trong dự án theo Delegation Map và policy.","aka":["delegation maps"]},{"t":"AI-04","vi":"Mã topic <b>Data Boundaries<\/b> trong khóa AI Transformation: dữ liệu nào được đưa vào AI, vào tenant/tool nào, sanitize gì.","aka":["AI-04 Data Boundaries"],"cs":true},{"t":"AI-05","vi":"Mã topic <b>Delegation Map<\/b> trong khóa AI Transformation: tam phân Máy/Agent/Người và mức ủy quyền L0–L5.","aka":["AI-05 Delegation Map"],"cs":true},{"t":"AI-10","vi":"Mã topic <b>Verification &amp; Evaluation<\/b> trong khóa AI Transformation: verifier ba tầng L1–L3 và input isolation.","aka":["AI-10 Verification & Evaluation"],"cs":true},{"t":"AI-12","vi":"Mã topic <b>Deployment Governance<\/b> trong khóa AI Transformation: approval gate, human oversight, release manifest, kill switch, rollback cho AI workflow.","aka":["AI-12 Deployment Governance"],"cs":true},{"t":"AI Transformation","vi":"Tên khóa học về chuyển đổi cách làm việc bằng AI (dành cho SA/PTL). Bài B.4 dùng thống nhất thuật ngữ governance của khóa này."},{"t":"transformation","vi":"Sự chuyển đổi, biến đổi. Trong bài: khóa AI Transformation — chuyển đổi cách làm engineering có AI tham gia."},{"t":"CASAN","vi":"Tên khung trưởng thành/governance AI dùng trong khóa AI Transformation; định nghĩa thang ủy quyền L0–L5 và các cấp, ví dụ CASAN cấp 3 (Standard) = có Delegation Map + Governance + Human-in-the-loop.","cs":true},{"t":"Observe","vi":"Quan sát. Mức L0 của thang ủy quyền: agent chỉ đọc/tổng hợp, không tạo thay đổi."},{"t":"Recommend","vi":"Đề xuất. Mức L2: agent gợi ý (ví dụ nguyên nhân flaky), người/owner quyết định."},{"t":"Execute","vi":"Thực thi. Mức L3: agent được tự chạy hành động trong giới hạn; việc chạm dữ liệu nhạy cảm hoặc ghi vào hệ thống tối đa L3."},{"t":"Restricted","vi":"Bị hạn chế. Mức L5 của thang ủy quyền: không cấp cho agent trong bối cảnh bài."},{"t":"Standard","vi":"Tiêu chuẩn. Trong bài: CASAN cấp 3 (Standard) — mức trưởng thành khi đội có Delegation Map, Governance và Human-in-the-loop."},{"t":"AI-first","vi":"Lấy AI làm mặc định: đội vận hành mà AI tham gia sẵn trong quy trình — nhưng vẫn có Delegation Map, governance và người duyệt."},{"t":"GenAI","vi":"AI tạo sinh (sinh văn bản, code, test…). Trong bài: dùng GenAI trong pipeline engineering có kiểm soát — tam phân, mức L, data boundary, verifier, approval gate.","aka":["GenAI pipeline"],"full":"Generative AI","cs":true},{"t":"SA/PTL","vi":"Solution Architect / Project Technical Leader: hai vai trò kỹ thuật dẫn dắt dự án, đối tượng của khóa AI Transformation.","cs":true},{"t":"HIL/target","vi":"Tầng test trên phần cứng thật: HIL bench hoặc target (ECU/board thật). Chạy nightly hoặc release candidate để kiểm timing, resource, variant mà tầng thấp không bắt được.","aka":["target/HIL"]},{"t":"Software-in-the-Loop","vi":"Tên đầy đủ của SIL: test phần mềm trong vòng lặp với môi trường mô phỏng trên máy tính, không cần phần cứng thật.","aka":["software in the loop"]},{"t":"SIL/contract","vi":"Tầng test chạy mỗi merge: SIL và contract/integration test — các component nói chuyện đúng interface không."},{"t":"unit/contract/SIL/HIL","vi":"Chuỗi các tầng test phát hiện lỗi: unit → contract → SIL → HIL, càng lên càng gần hệ thật.","aka":["unit/contract/SIL/HIL test"]},{"t":"unit/contract","vi":"Unit test và contract test. Trong bài là use case AI: agent draft unit/contract test từ requirement, người giữ oracle và coverage.","aka":["unit/contract test"]},{"t":"unit/static","vi":"Tầng thấp nhất chạy mỗi commit: unit test (logic từng hàm) và static analysis (code có vi phạm rule không)."},{"t":"unit/static/security","vi":"Unit test, static analysis và security scan — tầng test thấp nhất chạy mỗi commit, kiểm logic từng hàm và vi phạm rule/lỗ hổng trong code."},{"t":"contract/integration","vi":"Contract test và integration test: kiểm các component nói chuyện đúng interface; chạy mỗi merge."},{"t":"offline/degraded","vi":"Hành vi khi mất mạng/giảm chức năng: xe làm gì khi mất cloud. Mọi cloud dependency phải ghi offline/degraded behavior và timeout rõ.","aka":["offline/degraded behavior"]},{"t":"store-and-forward","vi":"Lưu rồi chuyển tiếp: khi mất kết nối, dữ liệu được giữ trên xe (trong bounded queue) và gửi lên khi có mạng lại."},{"t":"reconciliation","vi":"Đối soát: định kỳ so dữ liệu giữa hệ cũ và hệ mới khi coexistence để phát hiện lệch; số bản ghi lệch vượt ngưỡng thì dừng wave."},{"t":"reconcile","vi":"Đối soát, làm khớp: so và sửa lệch dữ liệu giữa hệ cũ và hệ mới khi coexistence. Số bản ghi lệch vượt ngưỡng thì dừng wave và reconcile.","aka":["reconciled"]},{"t":"system of record","vi":"Hệ được coi là nguồn dữ liệu đúng duy nhất. Khi coexistence phải chỉ định rõ hệ nào là system of record để tránh hai nguồn sự thật.","aka":["systems of record"]},{"t":"locked","vi":"Đã khóa, ghim cố định. Trong bài: locked dependency — thư viện được ghim version cụ thể."},{"t":"locked dependency","vi":"Dependency được ghim version cụ thể (qua lock file), không dùng “latest”; là điều kiện để build reproducible.","aka":["locked dependencies"]},{"t":"lock file","vi":"File ghi chính xác version mọi dependency đã dùng để build; nằm trong provenance của Build ID.","aka":["lock files","dependency lock file"]},{"t":"backoff/jitter","vi":"Khi retry: backoff — chờ lâu dần giữa các lần thử; jitter — thêm độ trễ ngẫu nhiên để nhiều xe không cùng retry một lúc gây retry storm.","aka":["exponential backoff"]},{"t":"circuit breaker","vi":"Cầu dao ngắt mạch (mẫu thiết kế): khi service phụ thuộc lỗi liên tục, tạm ngừng gọi nó một thời gian thay vì dồn request, bảo vệ cả hai phía.","aka":["circuit breakers"]},{"t":"circuit","vi":"Mạch điện. Trong bài dùng trong <i>circuit breaker<\/i> — cơ chế ngắt gọi tới service đang lỗi."},{"t":"breaker","vi":"Cầu dao (thiết bị ngắt điện khi quá tải). Trong bài dùng trong <i>circuit breaker<\/i> — cơ chế tạm ngừng gọi service đang lỗi để bảo vệ hệ thống."},{"t":"idempotency","vi":"Tính lũy đẳng: gọi một thao tác nhiều lần cho cùng kết quả như gọi một lần. Cần để retry an toàn, không tạo bản ghi/lệnh trùng."},{"t":"bounded","vi":"Có giới hạn, có biên. Trong bài: bounded queue — hàng đợi có kích thước tối đa và drop policy, tránh làm cạn bộ nhớ xe."},{"t":"bounded queue","vi":"Hàng đợi có giới hạn và có drop policy (ví dụ tối đa 50 MB telemetry, bỏ event cũ/ít quan trọng trước). Queue không giới hạn có thể làm cạn flash/RAM của xe.","aka":["bounded queues"]},{"t":"drop policy","vi":"Chính sách bỏ dữ liệu khi queue đầy: bỏ event nào trước (cũ, ít quan trọng) để bảo vệ tài nguyên xe."},{"t":"objective","vi":"Mục tiêu. Trong bài: Recovery Time/Point Objective (RTO/RPO) và Service Level Objective (SLO).","aka":["objectives"]},{"t":"endpoint/token","vi":"Địa chỉ service và token xác thực: hai thứ consumer phải đổi sang hệ mới khi cutover."},{"t":"application/data/consumer","vi":"Ba thứ cần kiểm kê khi migration: ứng dụng, dữ liệu và consumer (ai đang dùng chúng)."},{"t":"migration/DevOps","vi":"Migration và DevOps. Deliverable của bài là quality strategy kèm migration/DevOps roadmap có risk control cho một hệ thống hoặc change thật.","aka":["migration/DevOps roadmap"]},{"t":"Cloud/Migration","vi":"Cloud và migration (chuyển hệ thống/dữ liệu sang cloud hoặc hệ mới) — một phần tên bài B.4, nói về quyết định đặt chức năng ở cloud/edge và cách chuyển đổi an toàn."},{"t":"quality strategy","vi":"Chiến lược chất lượng: tài liệu SA viết nối quality attribute ưu tiên → scenario → phòng ngừa/phát hiện → stage/gate → evidence → owner, kèm inspection và feedback loop.","aka":["quality strategies"]},{"t":"quality engineering","vi":"Kỹ thuật chất lượng: thiết kế chất lượng vào quy trình (phòng ngừa + phát hiện + phản hồi), không chỉ test cuối."},{"t":"quality claim","vi":"Tuyên bố về chất lượng (ví dụ “cluster hiển thị đúng tốc độ dưới load”). Mỗi claim phải chỉ được bảo vệ bởi scenario, gate, evidence nào và ai chịu trách nhiệm.","aka":["quality claims"]},{"t":"data classification","vi":"Phân loại dữ liệu theo mức nhạy cảm (công khai, nội bộ, cá nhân, bí mật…) để quyết định nơi lưu, ai đọc, có được đưa vào AI không."},{"t":"data gravity","vi":"Lực hút dữ liệu: dữ liệu càng lớn càng khó chuyển và kéo ứng dụng về gần nó — một yếu tố chọn migration strategy."},{"t":"gravity","vi":"Lực hấp dẫn. Trong bài dùng trong <i>data gravity<\/i> — dữ liệu càng lớn càng khó di chuyển và kéo ứng dụng về gần nó."},{"t":"approval gate","vi":"Cổng phê duyệt (AI-12): điểm mà người có thẩm quyền phải ký mới được đi tiếp. AI không giữ quyền approve/waiver/release.","aka":["approval gates"]},{"t":"release approval","vi":"Phê duyệt phát hành: quyết định cho một artifact ra xe. Thuộc nhóm Người; AI tối đa L0 (tổng hợp evidence).","aka":["release approvals"]},{"t":"release owner","vi":"Người chịu trách nhiệm một bản phát hành: quyết định go/pause/rollback dựa trên evidence.","aka":["release owners"]},{"t":"approve/waiver/release","vi":"Ba quyền phê duyệt, cấp waiver và phát hành. Luật của bài: AI không giữ các authority này."},{"t":"inspection record","vi":"Biên bản inspection/review: scenario ID, artifact revision, reviewer, finding, owner, retest và close authority — để còn dùng được về sau.","aka":["inspection records"]},{"t":"inspection/review","vi":"Kiểm tra/review: xác định artifact nào cần review, ai review, record ghi gì."},{"t":"close authority","vi":"Thẩm quyền đóng finding: người được phép xác nhận finding đã sửa xong và retest đạt. Phải ghi trong inspection record, không ai tự đóng finding của mình."},{"t":"OK","vi":"Được, ổn. Biên bản chỉ ghi “Đã review, OK” mà không ghi revision nào là không dùng được làm evidence.","cs":true},{"t":"outline","vi":"Dàn ý, khung mục lục của tài liệu (ví dụ outline quality strategy ở mục 9).","aka":["outlines"]},{"t":"risk control","vi":"Biện pháp kiểm soát rủi ro: prevent/detect, trigger/threshold kích hoạt hành động, response và owner — không chỉ ghi mức cao/thấp.","aka":["risk controls"]},{"t":"trip","vi":"Chuyến đi của xe từ lúc khởi động đến khi tắt máy. Trip summary là bản tóm tắt dữ liệu của một chuyến đi gửi lên cloud.","aka":["trips"]},{"t":"trip summary","vi":"Tóm tắt chuyến đi (quãng đường, thời gian, sự kiện…) được upload lên cloud — ví dụ của data plane."},{"t":"criterion","vi":"Tiêu chí (số ít của criteria). Ví dụ acceptance criterion, exit criterion."},{"t":"exit criterion","vi":"Tiêu chí ra: điều kiện phải đạt để được chuyển sang pha/wave sau; mỗi mũi tên giữa hai pha migration là một exit criterion."},{"t":"entry/exit criteria","vi":"Tiêu chí vào/ra của mỗi pha hoặc wave: điều kiện bắt đầu và điều kiện được coi là xong để đi tiếp."},{"t":"SBOM/signature","vi":"SBOM (danh sách thành phần phần mềm) và chữ ký số: giúp biết artifact gồm gì và để xe chỉ cài artifact được ký đúng."},{"t":"CD","vi":"Chữ “CD” trong CI/CD có hai nghĩa: Continuous Delivery (luôn sẵn sàng phát hành, có bước duyệt) và Continuous Deployment (tự động ra môi trường thật). Với OTA ô tô, “CD” không có nghĩa là tự đẩy lên xe.","full":"Continuous Delivery / Continuous Deployment","cs":true},{"t":"continuous deployment","vi":"Triển khai liên tục: mọi thay đổi qua pipeline được tự động đưa ra môi trường thật. Với xe, vẫn cần target/HIL evidence, security và release authority trước OTA."},{"t":"deployment gate","vi":"Cổng kiểm trước khi triển khai; phải “đỏ được” — đã chứng minh fail với negative case.","aka":["deployment gates"]},{"t":"nightly","vi":"Chạy hằng đêm: lịch chạy pipeline/test tốn thời gian (ví dụ HIL/target) mỗi đêm thay vì mỗi commit.","aka":["nightly build","nightlies"]},{"t":"release candidate","vi":"Ứng viên phát hành: bản build được chọn để test đầy đủ (gồm HIL/target) trước khi quyết định release.","aka":["release candidates"]},{"t":"candidate","vi":"Ứng viên. Trong bài: release candidate — bản build ứng viên để phát hành.","aka":["candidates"]},{"t":"All tests passed","vi":"“Mọi test đã pass” — lời agent tự báo. Verifier không được tin câu này mà phải tự đọc exit code/test report của pipeline (input isolation)."},{"t":"all","vi":"Tất cả. Trong bài thường gặp trong câu agent tự báo “All tests passed”."},{"t":"recover","vi":"Khôi phục. Bước cuối của vòng đời sự cố: rollback nếu state tương thích, nếu không thì forward fix.","aka":["recovered"]},{"t":"forward fix","vi":"Sửa tiến: phát hành bản mới sửa lỗi thay vì quay lui, dùng khi rollback không an toàn (ví dụ persistent data đã migrate).","aka":["forward fixes"]},{"t":"H/M/L","vi":"Thang chấm Cao/Trung bình/Thấp cho business value và technical risk trong utility tree.","full":"High/Medium/Low","cs":true},{"t":"H/H","vi":"Scenario có business value Cao và technical risk Cao — được xử lý trước trong utility tree.","cs":true},{"t":"scenario/test/gate","vi":"Bộ ba sau mỗi defect escape: thêm scenario, test hoặc gate nào để lỗi không lọt lần nữa."},{"t":"gate/evidence","vi":"Gate và evidence của nó: điểm kiểm cùng bằng chứng đạt; mỗi wave migration hay stage pipeline đều cần.","aka":["quality gate/evidence"]},{"t":"gate/waiver","vi":"Gate và waiver: điểm kiểm bắt buộc và ngoại lệ có kiểm soát (có risk, mitigation, approver, expiry)."},{"t":"gate/permission","vi":"Cấu hình gate và quyền truy cập trong pipeline: thứ agent bị cấm sửa khi viết/sửa CI script, để AI không tự hạ chuẩn hay tự cấp quyền."},{"t":"stage/gate","vi":"Giai đoạn pipeline và gate ở giai đoạn đó: mỗi scenario phải chỉ ra được kiểm ở stage nào, gate nào."},{"t":"fault/chaos test","vi":"Test cố tình gây lỗi (fault injection) hoặc gây hỗn loạn có kiểm soát (tắt service, cắt mạng) để kiểm resilience thật sự.","aka":["fault/chaos"]},{"t":"feature/team","vi":"Theo feature hoặc theo team: cách gắn tag chi phí cloud để biết ai/tính năng nào đang tiêu tiền."},{"t":"alert","vi":"Cảnh báo tự động khi metric vượt ngưỡng (ví dụ budget alert khi chi phí cloud tăng).","aka":["alerts","alerting"]},{"t":"budget alert","vi":"Cảnh báo ngân sách: báo khi chi phí cloud vượt mức dự kiến để xử lý sớm.","aka":["budget alerts"]},{"t":"pseudonymization","vi":"Giả danh hóa: thay định danh thật (VIN, tên) bằng mã thay thế/mã băm để phân tích mà không lộ danh tính trực tiếp.","aka":["pseudonymisation","pseudonymize"]},{"t":"pseudonymization/minimization","vi":"Giả danh hóa và tối thiểu hóa dữ liệu: thay định danh bằng mã và chỉ thu thập dữ liệu thật sự cần."},{"t":"Discover","vi":"Khám phá. Pha đầu của migration: kiểm kê thành phần, data, consumer, dependency, owner — có những gì, ai đang dùng."},{"t":"downtime","vi":"Thời gian ngừng dịch vụ. Big bang hợp khi có cửa sổ downtime được chấp nhận."},{"t":"rehearsal","vi":"Diễn tập: chạy thử toàn bộ quy trình cutover/rollback trước khi làm thật.","aka":["rehearsals"]},{"t":"go/no-go","vi":"Quyết định đi tiếp hay dừng tại một mốc, dựa trên checklist các điều kiện đã đạt.","aka":["go/no-go checklist"]},{"t":"batch","vi":"Lô, nhóm. Incremental migration cần chia được các batch tương đối độc lập.","aka":["batches"]},{"t":"facade/routing","vi":"Lớp facade kèm định tuyến: chuyển từng loại request sang hệ mới dần dần."},{"t":"bottleneck/single point of failure","vi":"Nút cổ chai/điểm hỏng đơn: thành phần mà mọi luồng phải đi qua, chậm hoặc chết là cả hệ chết.","aka":["bottleneck/single"]},{"t":"shadow traffic","vi":"Gửi bản sao request thật sang hệ mới và so kết quả với hệ cũ, không trả kết quả hệ mới cho người dùng — dùng để kiểm strangler/parallel.","aka":["shadow/compare traffic","shadow/compare"]},{"t":"install/boot","vi":"Cài đặt và khởi động: lỗi install/boot là metric fleet quan trọng khi rollout OTA.","aka":["install/boot failure"]},{"t":"completeness","vi":"Độ đầy đủ. Telemetry completeness: tỷ lệ dữ liệu telemetry mong đợi thực sự về tới."},{"t":"telemetry completeness","vi":"Tỷ lệ telemetry thực sự về so với mong đợi; thấp nghĩa là dashboard “healthy” có thể đang thiếu mẫu số."},{"t":"accuracy","vi":"Độ chính xác. “Accuracy 98% trên dataset” chưa phải evidence release: cần đánh giá trên target, theo variant, input envelope, false positive/negative."},{"t":"latency/memory/thermal","vi":"Độ trễ, bộ nhớ và nhiệt độ: ba ràng buộc khi chạy model trên target thật."},{"t":"display-anomaly","vi":"Tên model ví dụ trong bài: phát hiện bất thường hiển thị trên cluster/IVI; rollout lên xe như một product software artifact.","aka":["model display-anomaly"]},{"t":"connection","vi":"Kết nối. Ví dụ: edge service mất cloud connection dưới bus load cao vẫn không được block display.","aka":["connections","cloud connection"]},{"t":"ISO/IEC","vi":"Tiền tố của chuẩn do ISO (Tổ chức Tiêu chuẩn hóa Quốc tế) và IEC (Ủy ban Kỹ thuật Điện Quốc tế) cùng ban hành, ví dụ ISO/IEC 25010 về mô hình chất lượng phần mềm.","cs":true},{"t":"ISO/IEC 25010","vi":"Chuẩn mô hình chất lượng sản phẩm phần mềm (SQuaRE): mô hình tham chiếu phổ biến để đặt tên quality attribute.","cs":true},{"t":"correctness/safety","vi":"Tính đúng/an toàn: fault có ảnh hưởng function không — evidence là review/test theo process."},{"t":"latency/offline","vi":"Độ trễ và khả năng chạy khi mất mạng: tiêu chí mà edge mạnh (xử lý tại xe) còn cloud phụ thuộc network — lý do chức năng real-time phải ở edge."},{"t":"inference","vi":"Suy luận: chạy một model đã huấn luyện để cho ra kết quả (ví dụ phát hiện bất thường). Inference trên xe gọi là local inference, chạy được cả khi offline."},{"t":"local inference","vi":"Chạy model ngay trên xe (edge), không cần gửi lên cloud — nhanh và chạy được offline."},{"t":"MB","vi":"Đơn vị dung lượng ≈ 1 triệu byte. Ví dụ bounded queue giữ tối đa 50 MB telemetry.","full":"Megabyte","cs":true},{"t":"flash/RAM","vi":"Bộ nhớ flash (lưu lâu dài) và RAM (bộ nhớ làm việc) của ECU; queue không giới hạn có thể làm cạn."},{"t":"Total Cost of Ownership","vi":"Tên đầy đủ của TCO: tổng chi phí trong cả vòng đời (compute, storage, egress, vận hành, exit cost…), không chỉ chi phí ban đầu.","aka":["total cost"]},{"t":"Ops","vi":"Operations — vận hành. Trong DevOps là phần chạy, giám sát và hỗ trợ hệ thống sau khi phát hành."},{"t":"repo","vi":"Kho mã nguồn (repository) trong hệ quản lý version như Git. Ví dụ trong bài: mỗi commit vào repo cluster HMI chạy unit test và static analysis.","aka":["repos","repository"]},{"t":"correlation ID/build ID","vi":"Mã tương quan (nối một request qua nhiều service) và mã build — dùng để nối dữ liệu xe với backend và truy về đúng artifact.","aka":["ID/build"]},{"t":"build ID/log","vi":"Build ID và log gốc: tóm tắt do AI viết phải link về đây để người kiểm lại.","aka":["ID/log"]},{"t":"log/build ID","vi":"Log gốc và Build ID: khi agent tóm tắt log CI, bản tóm tắt phải link tới log/build ID gốc để người kiểm lại được, không chỉ tin tóm tắt.","aka":["log/build"]},{"t":"fleet/backend","vi":"Phía đội xe và backend: nhóm metric observability như install/boot failure, crash, service health, latency, rollback, telemetry completeness."},{"t":"SLI","vi":"Service Level Indicator — chỉ số mức dịch vụ đo được, ví dụ tỷ lệ request thành công hoặc độ trễ P99 của backend service.","full":"Service Level Indicator","cs":true},{"t":"SLO","vi":"Service Level Objective — mục tiêu mức dịch vụ: ngưỡng SLI phải đạt trong một khoảng thời gian; vi phạm SLO là tín hiệu để hành động.","full":"Service Level Objective","cs":true},{"t":"SLI/SLO","vi":"Cặp chỉ số dịch vụ: SLI là thứ đo được (tỷ lệ request thành công, độ trễ), SLO là mục tiêu cho chỉ số đó. Dùng để giám sát backend service phục vụ xe.","cs":true},{"t":"DORA","vi":"Nhóm nghiên cứu DevOps và bộ 4 chỉ số giao hàng: lead time for changes, deployment frequency, change failure rate, time to restore. Dùng theo dõi xu hướng, không dùng xếp hạng người.","aka":["DORA metrics"],"full":"DevOps Research and Assessment","cs":true},{"t":"lead time for changes","vi":"Thời gian từ commit đến khi thay đổi chạy ở môi trường thật — một chỉ số DORA."},{"t":"targeted","vi":"Được nhắm tới: trạng thái đầu phễu rollout — xe thuộc danh sách của campaign/cohort. Đây là mẫu số khi tính tỷ lệ healthy."},{"t":"contacted","vi":"Đã liên lạc được: trạng thái thứ hai của phễu rollout — xe đã kết nối và nhận thông tin campaign; xe chưa contacted thuộc nhóm offline/unknown."},{"t":"downloaded","vi":"Đã tải xong: trạng thái thứ ba của phễu rollout (targeted → contacted → downloaded → installed → booted → healthy) — xe đã tải đủ gói cập nhật nhưng chưa cài."},{"t":"installed","vi":"Đã cài: trạng thái trong phễu rollout sau downloaded — xe đã ghi xong bản cập nhật, còn phải boot được và báo healthy mới tính là thành công."},{"t":"offline/unknown","vi":"Không liên lạc được/không rõ trạng thái: nhóm xe tách riêng trong phễu rollout, không được tính là healthy.","aka":["unknown/offline"]},{"t":"input envelope","vi":"Phạm vi input mà model được thiết kế để xử lý (độ sáng, góc camera…); ngoài phạm vi thì kết quả không đáng tin.","aka":["input envelopes"]},{"t":"input isolation","vi":"Tách verifier khỏi lời tự khai của agent: verifier đọc kết quả máy đọc được, không đọc câu “đã pass”."},{"t":"system/change","vi":"Hệ thống hoặc thay đổi cụ thể mà quality strategy áp dụng — mục đầu tiên của outline (Scope: system/change, version, variant, stakeholder)."},{"t":"defect escape/field issue","vi":"Lỗi lọt qua các gate hoặc sự cố phát hiện ngoài thực địa — phải feedback về scenario, test hoặc gate.","aka":["escape/field"]},{"t":"pause/rollback","vi":"Tạm dừng hoặc quay lui rollout — quyết định mà observability metric phải dẫn tới."},{"t":"rollback/forward","vi":"Quay lui hoặc sửa tiến: hai cách phục hồi; phải kiểm tương thích binary và persistent data.","aka":["rollback/forward recovery"]},{"t":"cabin","vi":"Khoang cabin, nơi người lái và hành khách ngồi. Trong bài là ví dụ quality scenario đo được: “ở 100 km/h, tiếng ồn cabin dưới mức X dB” thay cho câu mơ hồ “xe chạy êm”."},{"t":"dB","vi":"Decibel — đơn vị đo mức âm thanh (thang logarit). Trong bài dùng để minh họa một yêu cầu chất lượng đo được, kiểm được bằng số.","full":"decibel","cs":true},{"t":"performance/timing","vi":"Hiệu năng và thời gian đáp ứng: hệ chạy nhanh, đúng deadline đến đâu. Evidence phải là đo deadline/jitter dưới load trên target thật, không phải trên PC."},{"t":"availability/reliability","vi":"Tính sẵn sàng (hệ có mặt khi cần) và độ tin cậy (chạy đúng liên tục). Câu hỏi trong bài: reboot/mất mạng thì sao — evidence là fault injection/recovery log."},{"t":"security/privacy","vi":"Bảo mật và quyền riêng tư: ai truy cập được, dữ liệu đi đâu. Evidence là threat model, kiểm permission và audit log."},{"t":"modifiability","vi":"Khả năng sửa đổi: thay đổi một phần (schema, interface, tính năng) dễ và ít ảnh hưởng chỗ khác. Thêm lớp abstraction tăng modifiability nhưng tốn footprint."},{"t":"modifiability/maintainability","vi":"Khả năng sửa đổi/bảo trì: nhóm quality attribute về chi phí thay đổi và giữ hệ thống chạy tốt suốt vòng đời xe; evidence là impact analysis và contract test."},{"t":"compatibility/interoperability","vi":"Tương thích và khả năng phối hợp: hệ chạy được cùng phiên bản/hệ khác và trao đổi dữ liệu đúng. Quan trọng khi đội xe có nhiều version phần mềm cùng lúc."},{"t":"interoperability","vi":"Khả năng liên tác: các hệ/thành phần khác nhau trao đổi và dùng được dữ liệu của nhau đúng cách — một quality attribute trong ISO/IEC 25010."},{"t":"usability","vi":"Tính dễ dùng: người dùng (lái xe, kỹ sư) dùng hệ thống hiệu quả, ít nhầm lẫn — một quality attribute."},{"t":"portability","vi":"Tính khả chuyển: phần mềm chuyển sang phần cứng/OS/nền tảng khác dễ đến đâu — một quality attribute, liên quan khi đổi SoC hoặc variant."},{"t":"deadline/jitter","vi":"Hạn chót phải xong và độ dao động thời gian giữa các lần chạy. Câu hỏi performance trong bài: dưới load, deadline/jitter còn đạt không — đo trên target."},{"t":"reboot/network","vi":"Khởi động lại hoặc mất mạng: hai sự kiện điển hình để kiểm availability; trả lời bằng fault injection và recovery log.","aka":["reboot/network loss"]},{"t":"threat model/permission/audit","vi":"Bộ evidence cho security/privacy: mô hình mối đe dọa (threat model), kiểm soát quyền (permission) và lưu vết (audit).","aka":["model/permission/audit"]},{"t":"schema/interface","vi":"Lược đồ dữ liệu hoặc giao diện giữa các thành phần. Câu hỏi modifiability: đổi schema/interface thì ảnh hưởng ai — trả lời bằng impact analysis và contract test."},{"t":"impact analysis/contract test","vi":"Phân tích ảnh hưởng của thay đổi kèm contract test kiểm interface — loại evidence cho modifiability: biết trước ai bị ảnh hưởng và chứng minh interface vẫn đúng.","aka":["analysis/contract","impact analysis/contract"]},{"t":"review/test","vi":"Review và test theo quy trình (ví dụ quy trình safety) — loại evidence cho correctness/safety: fault có ảnh hưởng function không."},{"t":"review/audit","vi":"Review hoặc audit: buổi xem xét/kiểm toán. Câu SA phải hỏi ở đó: “xanh cho artifact nào, ở điều kiện nào, mẫu số là gì, và ai ký?”."},{"t":"latency/CPU","vi":"Độ trễ và tải CPU: cái giá phải trả khi thêm mã hóa và xác thực để tăng security — ví dụ trade-off giữa các quality attribute."},{"t":"footprint","vi":"Dấu chân tài nguyên: lượng bộ nhớ/dung lượng mà phần mềm chiếm. Thêm lớp abstraction tăng modifiability nhưng làm tăng footprint.","aka":["memory footprint"]},{"t":"performance/soak test","vi":"Test hiệu năng và soak test (chạy liên tục nhiều giờ) để lộ rò rỉ bộ nhớ, suy giảm hiệu năng theo thời gian — thuộc nhóm control phát hiện lỗi.","aka":["performance/soak","performance/soak tests"]},{"t":"soak test","vi":"Test ngâm: chạy hệ thống liên tục thời gian dài dưới tải để lộ rò rỉ bộ nhớ, lỗi tích lũy và suy giảm mà test ngắn không thấy.","aka":["soak tests","soak testing"]},{"t":"configuration/evidence","vi":"Cấu hình đã kiểm và bằng chứng kèm theo. Checklist chỉ tick mà thiếu configuration/evidence (bản nào, kết quả ở đâu) thì chưa đủ làm evidence."},{"t":"roaming","vi":"Chuyển vùng mạng di động (sang nhà mạng/quốc gia khác) — cùng hầm xe và vùng sóng yếu là lý do kết nối của xe không được bảo đảm, nên chức năng quan trọng phải chạy được offline."},{"t":"transfer/retention","vi":"Truyền dữ liệu đi và lưu giữ dữ liệu: hai điểm cloud phải kiểm soát về privacy (dữ liệu rời xe đi đâu, giữ bao lâu), trong khi edge giữ dữ liệu tại xe."},{"t":"dependency list","vi":"Danh sách phụ thuộc: liệt kê theo feature mỗi chức năng cần service/cloud nào, để trả lời được câu “offline thì xe làm gì”."},{"t":"build minutes","vi":"Số phút máy build mà dịch vụ CI trên cloud tính tiền — một khoản trong TCO, tăng theo số commit, variant và tầng test."},{"t":"minutes","vi":"Phút. Trong bài dùng trong <i>build minutes<\/i> — thời gian máy build được nhà cung cấp cloud tính phí.","aka":["minute"]},{"t":"tagging","vi":"Gắn nhãn (tag) cho tài nguyên cloud theo feature/team để phân bổ chi phí: khi chi phí tăng thì biết ngay của ai và vì tính năng nào."},{"t":"retention/deletion","vi":"Lưu giữ và xóa dữ liệu: giữ bao lâu, khi nào xóa và xóa đủ mọi bản sao bằng cách nào — một phần của data governance."},{"t":"deletion","vi":"Việc xóa dữ liệu (khi hết hạn retention hoặc theo yêu cầu chủ dữ liệu). Cần lineage để biết và xóa đủ mọi bản sao, kể cả trong dataset huấn luyện."},{"t":"log/observability","vi":"Chi phí lưu log và hệ observability trên cloud — tăng dần theo số xe và số ngày, là khoản dễ bị quên khi tính TCO."},{"t":"traffic/consumer","vi":"Lưu lượng request và các consumer (bên đang dùng hệ). Ở bước cutover, traffic/consumer chính được chuyển sang hệ mới và phải kiểm từng consumer đã thật sự đổi."},{"t":"checksum/signature","vi":"Checksum (kiểm dữ liệu không bị thay đổi khi chuyển) và chữ ký số (kiểm đúng người ký) — bắt buộc trong migration plan cho artifact và dữ liệu."},{"t":"API/schema","vi":"API và schema dữ liệu của backend. Phải versioning API/schema và có deprecation policy để xe cũ nhiều năm chưa cập nhật vẫn chạy được.","aka":["API/schema versioning"]},{"t":"timing/variant","vi":"Timing và variant: loại evidence chỉ tầng target/HIL cung cấp được. Một nghìn unit test xanh không thay được evidence timing/variant của tầng target."},{"t":"instability","vi":"Sự bất ổn định. Instability thật (race condition, timing) sẽ bị che đi nếu cứ rerun cho test xanh, rồi lộ ra trên xe."},{"t":"timing/race","vi":"Lỗi thời gian và race condition (kết quả phụ thuộc thứ tự chạy của các luồng). Flaky trên HIL thường báo hiệu đúng loại lỗi này mà tầng thấp không bắt được."},{"t":"build/queue","vi":"Thời gian build và thời gian chờ trong hàng đợi của pipeline — metric observability của pipeline, cho biết dây chuyền có đang tắc không."},{"t":"deployment frequency","vi":"Tần suất triển khai lên môi trường thật — một chỉ số DORA, dùng để theo dõi xu hướng dòng chảy giao hàng."},{"t":"frequency","vi":"Tần suất, số lần trong một khoảng thời gian. Trong bài dùng trong <i>deployment frequency<\/i> (chỉ số DORA).","aka":["frequencies"]},{"t":"time to restore","vi":"Thời gian khôi phục dịch vụ sau sự cố — một chỉ số DORA, phản ánh khả năng phục hồi của quy trình."},{"t":"restore","vi":"Khôi phục về trạng thái hoạt động bình thường sau sự cố. Trong bài dùng trong <i>time to restore<\/i> (DORA).","aka":["restored","restoring","restores"]},{"t":"evidence/version","vi":"Bằng chứng gắn với phiên bản: gate đạt trên bản nào. Một mục bắt buộc của gate; thiếu version thì evidence không dùng được."},{"t":"dual-read","vi":"Đọc kép: bản mới đọc được cả format dữ liệu cũ và mới, để rollback/forward an toàn khi persistent data đã đổi format.","aka":["dual read"]},{"t":"quarantine","vi":"Cách ly: tạm tách test flaky khỏi gate để không chặn pipeline, nhưng phải có owner, hạn xử lý và ghi trạng thái trong evidence — không được bỏ quên.","aka":["quarantined"]},{"t":"quarantine/fix","vi":"Cách ly hay sửa ngay: quyết định thuộc owner với test flaky, sau khi agent tóm tắt log CI và gợi ý nguyên nhân."},{"t":"operational domain","vi":"Miền vận hành: các điều kiện mà model/chức năng được thiết kế để chạy (ánh sáng, thời tiết, tốc độ…). Đánh giá model phải tách theo miền này.","aka":["operational design domain"]},{"t":"ground truth","vi":"Sự thật nền: nhãn đúng đã được xác minh. Muốn kết luận model kém đi (drift) cần ground truth, không chỉ dựa vào tín hiệu bất thường."},{"t":"ground","vi":"Nền, mặt đất. Trong bài dùng trong <i>ground truth<\/i> — nhãn đúng đã được xác minh."},{"t":"push/merge/release","vi":"Đẩy code lên, gộp nhánh và phát hành: ba hành động agent không được tự làm; phải qua review và approval của người."},{"t":"requirement/source","vi":"Requirement và mã nguồn: dữ liệu được phép đưa vào tenant AI đã duyệt khi agent draft unit/contract test."},{"t":"requirement/data","vi":"Requirement và data model — đầu ra của bài B.3, được dùng làm đầu vào cho bài tập quality strategy của B.4.","aka":["requirement/data model"]},{"t":"branch","vi":"Nhánh mã nguồn trong Git. Agent chỉ được chạy lint/dry-run trên branch riêng; merge vào nhánh chính phải qua review người.","aka":["branches"]},{"t":"lint","vi":"Kiểm tra tĩnh mã/script theo quy tắc cú pháp và phong cách mà không cần chạy — bước verifier đầu tiên cho CI script.","aka":["linter","linting"]},{"t":"dry-run","vi":"Chạy thử khô: mô phỏng việc thực thi mà không gây tác dụng thật (không deploy, không ghi), để kiểm script an toàn.","aka":["dry run"]},{"t":"lint/dry-run","vi":"Lint và dry-run: verifier tầng 1 cho CI script do agent viết, chạy trên branch trước khi người review."},{"t":"release/risk authority","vi":"Quyền quyết định phát hành và chấp nhận rủi ro — thuộc nhóm Người; AI tối đa L0 (chỉ tổng hợp evidence).","aka":["release/risk"]},{"t":"exit code/test report","vi":"Mã thoát của tiến trình và báo cáo test do máy sinh ra. Verifier phải tự đọc chúng thay vì tin câu “All tests passed” của agent.","aka":["code/test"]},{"t":"exit code","vi":"Mã thoát: số mà chương trình trả về khi kết thúc (0 thường là thành công). Là kết quả máy đọc được mà verifier tầng 1 kiểm.","aka":["exit codes"]},{"t":"variant/target","vi":"Biến thể xe và phần cứng đích: test (kể cả test do AI sinh) phải chạy trên đúng variant/target mới có giá trị evidence."},{"t":"model/runtime/dependency","vi":"Model, runtime chạy model và các dependency — phải được pin version (ghim cố định) trong bước inventory trước khi rollout model lên xe."},{"t":"signer","vi":"Người/khóa ký artifact. Khi chuyển registry phải pin signer và kiểm gate chữ ký vẫn từ chối artifact ký sai.","aka":["signers"]},{"t":"hash/signature","vi":"Mã băm và chữ ký số: kiểm artifact không bị thay đổi và được ký đúng — bước kiểm trong pilot rollout model."},{"t":"state/config","vi":"Trạng thái và cấu hình đã lưu trên xe. Trước rollback phải hỏi: model cũ có đọc được state/config mà model mới đã ghi không."},{"t":"prevent","vi":"Ngăn ngừa: loại control chặn lỗi sinh ra từ đầu (design review, ADR, coding guideline, static analysis).","aka":["prevention"]},{"t":"detect","vi":"Phát hiện: loại control bắt lỗi đã có (test các tầng, fault injection, soak test, security test)."},{"t":"prevent/detect","vi":"Phòng ngừa/phát hiện: hai loại control ghi trong risk register — chặn lỗi sinh ra và bắt lỗi đã có."},{"t":"trigger/threshold","vi":"Điều kiện kích hoạt và ngưỡng: khi metric nào vượt mức nào thì phải hành động (pause, rollback, dừng wave)."},{"t":"control/trigger/response","vi":"Ba cột cốt lõi của một dòng risk register: biện pháp kiểm soát, điều kiện kích hoạt và hành động phản ứng."},{"t":"cost/TCO","vi":"Chi phí và tổng chi phí vòng đời (TCO): khía cạnh cost khi quyết định đặt chức năng ở cloud hay edge."},{"t":"cost/resilience","vi":"Chi phí và khả năng chống chịu: vendor lock-in là rủi ro ở cả hai mặt cùng lúc."},{"t":"policy/ownership","vi":"Chính sách và quyền sở hữu/trách nhiệm: ai đặt luật, ai chịu trách nhiệm cho từng bước có AI tham gia."},{"t":"provenance/reproducibility","vi":"Nguồn gốc artifact và khả năng build lại y hệt: hai điều kiện để truy được và tin được bản đang chạy trên xe."},{"t":"fault injection/recovery","vi":"Cố tình gây lỗi và ghi lại quá trình phục hồi — evidence cho availability.","aka":["injection/recovery","fault injection/recovery log"]},{"t":"ADR/trade-off","vi":"Architecture Decision Record và phân tích trade-off: ghi lại quyết định kiến trúc kèm đánh đổi — một control phòng ngừa."},{"t":"troubleshooting/RCA","vi":"Xử lý sự cố và phân tích nguyên nhân gốc (chủ đề B.5): không có provenance thì bắt đầu bằng phỏng đoán."},{"t":"stimulus/environment/response/metric/threshold","vi":"Năm phần của một quality scenario theo thứ tự sự kiện: kích thích, môi trường, phản hồi, metric và ngưỡng đạt."},{"t":"reliable","vi":"Đáng tin cậy. Trong bài là ví dụ câu yêu cầu mơ hồ không kiểm được; phải viết lại thành quality scenario 5 phần."},{"t":"envelope","vi":"Phong bì, vùng bao. Trong bài dùng trong <i>input envelope<\/i> — phạm vi điều kiện input mà model được thiết kế để xử lý."},{"t":"chaos test","vi":"Test hỗn loạn: cố ý gây sự cố ngẫu nhiên có kiểm soát (tắt service, cắt mạng, làm chậm) trên hệ đang chạy để kiểm resilience thật sự.","aka":["chaos tests","chaos testing","chaos engineering"]},{"t":"FTA","vi":"Phân tích cây lỗi: đi từ top event (sự cố cần phân tích) xuống qua cổng AND/OR tới các basic event, tìm minimal cut set. Trong bài dùng khi lỗi do tổ hợp điều kiện (ví dụ binary V1 + schema S2 + rollback) hoặc để kiểm redundancy có thật độc lập.","full":"Fault Tree Analysis","cs":true},{"t":"fault tree analysis","vi":"Tên đầy đủ của FTA: vẽ cây logic từ sự cố xấu ở đỉnh xuống các nguyên nhân cơ bản ở đáy, nối bằng cổng AND/OR. Hợp với lỗi cần nhiều điều kiện cùng lúc và hệ thống liên quan safety.","aka":["fault tree","fault trees"]},{"t":"VCS","vi":"Hệ thống quản lý phiên bản (ví dụ Git) lưu mọi thay đổi kèm ai sửa, lúc nào. Trong bài, tài liệu controlled phải nằm trong VCS/ALM để trả lời câu hỏi \"bản nào là bản đúng\", không nằm trong email.","full":"Version Control System","cs":true},{"t":"ALM","vi":"Công cụ quản lý vòng đời sản phẩm phần mềm: requirement, thay đổi, test, release, review và phê duyệt được liên kết với nhau. Trong bài là nơi giữ tài liệu controlled và trace từ incident tới CAPA.","full":"Application Lifecycle Management","cs":true},{"t":"application lifecycle management","vi":"Tên đầy đủ của ALM: quản lý toàn bộ vòng đời phần mềm (yêu cầu → thiết kế → test → phát hành → bảo trì) trên một công cụ có lịch sử và phê duyệt."},{"t":"Git","vi":"Hệ thống quản lý phiên bản phân tán phổ biến nhất. Trong bài là ví dụ VCS để lưu tài liệu kỹ thuật dưới dạng có lịch sử thay đổi và review."},{"t":"AND/OR","vi":"Hai loại cổng logic trong FTA: AND = cần tất cả điều kiện cùng xảy ra mới gây sự kiện phía trên; OR = chỉ một điều kiện là đủ. Phá một nhánh của cổng AND là đủ chặn top event.","aka":["AND","OR"],"cs":true},{"t":"effectiveness","vi":"Hiệu quả thực tế. Trong bài: bằng chứng CAPA <b>thật sự làm lỗi giảm/hết tái diễn<\/b> ngoài thực địa (metric trên cohort đã fix sau một khoảng thời gian), khác với \"test xanh\" trong lab.","aka":["effectiveness check"]},{"t":"verification of effectiveness","vi":"Kiểm chứng hiệu quả: bước chứng minh action đã giảm tái diễn, ví dụ theo dõi reset/rollback rate ở cohort đã fix trong thời gian quan sát định trước. Chưa có bước này thì CAPA chưa được đóng."},{"t":"effective","vi":"Có hiệu lực / có hiệu quả. Trong bài chủ yếu ở cụm <i>effective date<\/i> (ngày tài liệu bắt đầu có hiệu lực) và ở ý CAPA effective (thực sự làm lỗi hết)."},{"t":"effective date","vi":"Ngày hiệu lực: từ ngày này tài liệu (runbook, design note…) là bản chính thức phải dùng. Thiếu effective date thì người đọc không biết bản mình cầm còn hiệu lực hay đã bị thay."},{"t":"systemic","vi":"Thuộc về hệ thống / quy trình, không phải lỗi của một cá nhân. Trong bài: nguyên nhân sâu nằm ở process, gate, contract — sửa nó thì người khác cũng không lặp lại lỗi."},{"t":"systemic cause","vi":"Nguyên nhân hệ thống: lỗ hổng process/contract cho phép lỗi lọt, ví dụ OTA gate không bắt buộc rollback test cho service có persistent data. RCA phải đi tới tầng này thay vì dừng ở \"developer quên\".","aka":["systemic causes"]},{"t":"preventive","vi":"Phòng ngừa. Trong bài là nửa \"P\" của CAPA: hành động sửa gate/test/process để lỗi cùng loại không xảy ra nữa, kể cả ở service khác."},{"t":"preventive action","vi":"Hành động phòng ngừa: sửa nguyên nhân hệ thống (ví dụ thêm rollback test bắt buộc trong OTA gate cho mọi service có persistent data). \"Nhắc dev cẩn thận hơn\" không phải preventive action.","aka":["preventive actions"]},{"t":"corrective","vi":"Khắc phục. Trong bài là nửa \"C\" của CAPA: sửa chính lỗi / nguyên nhân đã gây sự cố."},{"t":"corrective action","vi":"Hành động khắc phục: loại bỏ nguyên nhân của lỗi đã xảy ra, ví dụ cho binary đọc được cả schema cũ và mới (dual-read) hoặc forward recovery. Khác preventive action là chặn lỗi tái diễn ở quy mô hệ thống.","aka":["corrective actions"]},{"t":"timeline","vi":"Dòng thời gian các sự kiện. Trong bài: dựng timeline sự cố theo <b>event time<\/b> (lúc xảy ra trên xe) và ghi clock domain, không theo lúc backend nhận dữ liệu, để không đảo nhầm nhân quả.","aka":["timelines"]},{"t":"incident timeline","vi":"Dòng thời gian của sự cố: OTA, rollback, crash, reset… xếp theo event time kèm nguồn và clock domain. Là nền cho giả thuyết; timeline sai thì giả thuyết đặt sai chỗ."},{"t":"factor","vi":"Yếu tố. Trong bài chủ yếu ở cụm <i>contributing factor<\/i> (yếu tố góp phần) và <i>causal factor<\/i> (yếu tố nhân quả trong causal analysis).","aka":["factors"]},{"t":"contributing factor","vi":"Yếu tố góp phần: điều kiện không tự gây lỗi nhưng làm lỗi xảy ra hoặc lọt qua, ví dụ thiếu power-loss test hay thiếu rollback test (barrier phát hiện bị thiếu).","aka":["contributing factors"]},{"t":"5 Whys","vi":"Kỹ thuật hỏi \"vì sao\" lặp lại nhiều lần để đi từ triệu chứng xuống nguyên nhân sâu. Trong bài: phải đi tới barrier/gate bị thủng, không dừng ở \"ai làm sai\"; số 5 không phải quy tắc cứng.","aka":["Whys","five whys"]},{"t":"controlled documentation","vi":"Tài liệu có kiểm soát: có ID, owner, version, trạng thái, người duyệt, effective date và change history, nằm trong VCS/ALM. Ai mở cũng biết bản nào là bản đúng và đã được duyệt — khác file \"final_v3\" trong email.","aka":["controlled document","controlled documents","controlled technical document","controlled technical documents"]},{"t":"document control","vi":"Kiểm soát tài liệu; <i>document control block<\/i> là bảng đầu tài liệu ghi Document ID, Title, Owner, Version, Status, Effective date, Access/retention và baseline/release liên quan.","aka":["document control block"]},{"t":"document system","vi":"Hệ thống quản lý tài liệu có lịch sử và phân quyền (ví dụ ALM, wiki có version, DMS). Trong bài là nơi tài liệu controlled nằm, thay vì email hay ổ chung.","aka":["document systems"]},{"t":"barrier","vi":"Rào chắn / lớp chặn. Trong bài: các lớp như review, test, gate lẽ ra phải chặn lỗi. RCA hỏi \"barrier nào thủng và vì sao\" thay vì \"ai làm sai\".","aka":["barriers"]},{"t":"causal","vi":"Thuộc về nhân quả. Trong bài ở <i>causal analysis<\/i>, <i>causal factor<\/i>: phân tích chuỗi nguyên nhân–kết quả dẫn tới sự cố."},{"t":"causal analysis","vi":"Phân tích nhân quả (timeline/causal factor chart): dựng timeline sự kiện và điều kiện, đánh dấu barrier/control nào lẽ ra phải chặn. Hợp với incident nhiều bên, nhiều hệ thống, có yếu tố tổ chức."},{"t":"causal factor","vi":"Yếu tố nhân quả: sự kiện/điều kiện góp phần vào sự cố, đặt trên timeline cùng các barrier liên quan. <i>Timeline/causal factor chart<\/i> là sơ đồ dùng trong causal analysis.","aka":["causal factors","causal factor chart","timeline/causal factor chart"]},{"t":"chart","vi":"Biểu đồ / sơ đồ. Trong bài ở cụm <i>timeline/causal factor chart<\/i> — sơ đồ sự kiện, điều kiện và barrier theo thời gian.","aka":["charts"]},{"t":"hash/immutable storage","vi":"Lưu evidence kèm hash trên nơi lưu không cho sửa/xóa (immutable). Giúp chứng minh bằng chứng gốc còn nguyên khi review RCA hay audit.","aka":["hash/immutable","immutable storage"]},{"t":"immutable","vi":"Bất biến, không sửa được sau khi ghi. Trong bài: nơi lưu evidence gốc phải immutable để không ai chỉnh sửa âm thầm."},{"t":"severity/priority","vi":"Cặp đánh giá sự cố: severity = nặng tới đâu; priority = xử lý trước hay sau, tính từ severity × phạm vi × xu hướng lan × deadline/cam kết. Báo cáo phải ghi cả hai kèm lý do."},{"t":"ingestion","vi":"Tiếp nhận / nạp dữ liệu vào hệ thống. Trong bài ở cụm <i>ingestion time<\/i>: lúc backend nhận dữ liệu từ xe."},{"t":"ingestion time","vi":"Thời điểm backend nhận được dữ liệu, có thể trễ nhiều ngày so với lúc sự kiện thật sự xảy ra (xe mất mạng). Xếp timeline theo ingestion time có thể làm crash trông như xảy ra sau OTA."},{"t":"event time","vi":"Thời điểm sự kiện thật sự xảy ra trên xe (theo đồng hồ của ECU/VM sinh ra nó). Timeline sự cố phải xếp theo event time, kèm clock domain."},{"t":"fishbone","vi":"Sơ đồ xương cá: đầu cá là symptom, mỗi xương là một nhóm nguyên nhân tiềm năng (requirement, design/code, tool/pipeline, process/review, environment/hardware, measurement). Dùng để mở rộng giả thuyết trong workshop.","aka":["fishbone diagram"]},{"t":"Ishikawa","vi":"Tên khác của sơ đồ fishbone, theo tên Kaoru Ishikawa — người phổ biến công cụ này trong quản lý chất lượng."},{"t":"bias","vi":"Thiên lệch: sai lệch có hệ thống trong số liệu hoặc trong suy nghĩ. Trong bài: telemetry thiếu tạo bias khi đếm xe lỗi; và các bias nhận thức như confirmation bias, hindsight bias khi điều tra.","aka":["biases"]},{"t":"confirmation bias","vi":"Thiên kiến xác nhận: xu hướng chỉ tìm bằng chứng ủng hộ điều mình đã tin. Trong bài: bám một giả thuyết duy nhất dẫn tới bias này; chống bằng nhiều hypothesis cạnh tranh có prediction ghi trước."},{"t":"hindsight bias","vi":"Thiên kiến nhìn lại: phán xét quyết định trước sự cố bằng thông tin chỉ có sau sự cố (\"lẽ ra phải biết\"). Trong bài là cái bẫy khiến RCA quy lỗi cá nhân thay vì tìm barrier."},{"t":"hindsight","vi":"Sự nhìn lại sau khi việc đã xảy ra. Trong bài ở <i>hindsight bias<\/i>."},{"t":"top event","vi":"Sự kiện đỉnh trong FTA: sự cố xấu cần phân tích, ví dụ \"CDC reboot loop sau rollback\". Cây được phân rã từ đây xuống các basic event.","aka":["top events"]},{"t":"top","vi":"Đỉnh / trên cùng. Trong bài ở cụm <i>top event<\/i> của FTA."},{"t":"basic event","vi":"Sự kiện cơ bản: điều kiện ở đáy cây FTA, không phân rã tiếp (ví dụ \"binary V1 không đọc được schema S2\").","aka":["basic events"]},{"t":"minimal cut set","vi":"Tổ hợp tối thiểu các basic event đủ gây top event. Nếu minimal cut set chỉ còn một phần tử chung cho hai nhánh thì redundancy không độc lập như tưởng.","aka":["minimal cut sets","cut set","cut sets"]},{"t":"proximate cause","vi":"Nguyên nhân trực tiếp: lỗi gần nhất gây sự cố, ví dụ binary V1 không parse được cache schema S2. Là tầng đầu trong ba tầng proximate → contributing → systemic.","aka":["proximate causes","proximate"]},{"t":"root cause confirmed","vi":"Câu kết luận \"đã xác nhận nguyên nhân gốc\". Bài khuyên không ghi câu này nếu chưa có test đối chứng; ghi \"được hỗ trợ trong phạm vi test\" kèm confidence và danh sách variant chưa test."},{"t":"confirmed","vi":"Đã xác nhận. Trong bài: chỉ được gọi confirmed khi có test đối chứng trên đủ variant; tái hiện trên một variant trong lab chưa đủ."},{"t":"custody","vi":"Sự lưu giữ, quản lý. Trong bài ở cụm <i>chain of custody<\/i>."},{"t":"chain of custody","vi":"Chuỗi lưu giữ bằng chứng: ghi ai lấy, lúc nào, từ đâu, hash và nơi lưu. Giúp chứng minh evidence không bị sửa; phân tích làm trên bản copy, không đụng bản gốc."},{"t":"evidence preservation","vi":"Giữ nguyên bằng chứng: lưu ngay log/trace/manifest/config, timestamp, clock domain, build ID, hash trước khi bị ghi đè hay mất. Mất ở bước này thì các bước sau không có gì để dựa.","aka":["preservation"]},{"t":"freeze evidence","vi":"\"Đóng băng\" bằng chứng: chụp và lưu giữ nguyên log, trace, manifest, config… tại thời điểm sự cố, trước khi restart hay rollback làm mất."},{"t":"fault isolation","vi":"Khoanh vùng lỗi: thu hẹp dần lỗi nằm ở thành phần, cohort, variant hay điều kiện nào bằng so sánh và thử nghiệm."},{"t":"reset reason","vi":"Lý do reset: mã ghi vì sao ECU/VM khởi động lại (watchdog, crash, mất nguồn…), gửi về sau mỗi lần boot. Trong case, effectiveness đo bằng việc không còn reset reason \"cache parse error\".","aka":["reset reasons","watchdog/reset reason"]},{"t":"actual impact","vi":"Ảnh hưởng thực tế: số xe có evidence là bị lỗi. Chỉ là \"sàn\", không phải toàn bộ phạm vi."},{"t":"potential","vi":"Tiềm năng, có thể xảy ra. Trong bài ở <i>potential impact<\/i> và \"nguyên nhân tiềm năng\" trong fishbone."},{"t":"potential impact","vi":"Ảnh hưởng tiềm năng: phạm vi xấu nhất hợp lý, ví dụ mọi xe đã cài V2 và có thể rollback. Dùng để quyết định containment."},{"t":"actual/potential/unknown","vi":"Ba con số impact phải báo tách riêng: actual (đã có evidence), potential (phạm vi xấu nhất hợp lý), unknown (telemetry/cohort chưa đủ để biết). Không gộp thành một tỷ lệ trên xe online.","aka":["actual / potential / unknown"]},{"t":"targeted/installed/reported/failed/unknown","vi":"Các con số trạng thái OTA cần ghi riêng: được nhắm, đã cài, đã báo về, lỗi, chưa rõ. Xe đang reboot loop có thể không gửi được telemetry nên nằm trong \"unknown\", không phải \"ổn\".","aka":["targeted/installed/failed/unknown"]},{"t":"causation","vi":"Quan hệ nhân quả (việc này gây ra việc kia). Trong bài: correlation (xảy ra cùng lúc) không phải causation — \"lỗi sau OTA\" chỉ là clue cho tới khi có timeline, so cohort và phép thử."},{"t":"clue","vi":"Manh mối: dấu hiệu gợi ý hướng điều tra nhưng chưa phải kết luận. Trong bài: thay đổi gần thời điểm lỗi chỉ là clue.","aka":["clues"]},{"t":"clock skew","vi":"Lệch đồng hồ giữa các ECU/VM. Có thể đảo thứ tự hai sự kiện trên timeline, nên khi ghép log phải ghi clock domain của từng nguồn.","aka":["skew"]},{"t":"peak memory","vi":"Mức dùng bộ nhớ cao nhất (đỉnh). Trong bài là prediction của giả thuyết \"thiếu RAM\": nếu đúng, crash phải trùng lúc peak memory.","aka":["peak"]},{"t":"cache header","vi":"Phần đầu file cache ghi metadata như phiên bản schema. Trong case, lưu cache header làm evidence để thấy cache do V2 ghi theo schema S2 mà V1 không đọc được.","aka":["header","headers"]},{"t":"wrap","vi":"Ghi đè vòng: buffer log đầy thì dữ liệu mới đè lên dữ liệu cũ nhất. Log bị wrap trước khi lấy vẫn có hash hoàn hảo nhưng đã mất đoạn quan trọng.","aka":["wrap buffer","wrapped"]},{"t":"dual-read/forward recovery","vi":"Hai lựa chọn CAPA trong case: dual-read (binary đọc được cả schema cũ và mới) hoặc forward recovery (sửa bằng cách tiến lên bản mới thay vì quay lui).","aka":["dual-read/forward"]},{"t":"power-loss","vi":"Mất nguồn đột ngột. <i>Power-loss test<\/i> kiểm phần mềm khi bị cắt điện giữa chừng (đang ghi file, đang cập nhật). Trong bài, thiếu test này là ví dụ contributing factor.","aka":["power-loss test","power loss test"]},{"t":"schema-rollback","vi":"Kiểm tra rollback khi schema dữ liệu đã đổi: bản cũ có đọc được dữ liệu bản mới ghi không. Trong bài, thiếu schema-rollback gate là systemic cause.","aka":["schema-rollback gate","schema-rollback test"]},{"t":"OTA gate","vi":"Cổng kiểm tra bắt buộc trước khi phát hành OTA. Trong case, preventive action là bắt OTA gate yêu cầu rollback test với persistent data cho mọi service có dữ liệu lưu.","aka":["OTA gates"],"cs":true},{"t":"negative test","vi":"Test ca xấu: cố ý đưa tình huống sai (ví dụ tổ hợp V1/S2) vào và kỳ vọng hệ thống/gate báo fail. Gate chưa từng đỏ thì chưa chứng minh được nó bắt được lỗi.","aka":["negative tests"]},{"t":"author","vi":"Tác giả, người viết/sửa tài liệu. Trong bài: reviewer và approver phải khác author; mỗi revision ghi author và mô tả thay đổi.","aka":["authors"]},{"t":"reviewer/approver","vi":"Người soát (review) và người duyệt (approve) tài liệu. Trong bài phải độc lập với author theo vai trò, và tên họ được ghi trong review record và change history."},{"t":"review/approval","vi":"Bước soát xét và phê duyệt chính thức trước khi tài liệu có hiệu lực. Mọi thay đổi sau approval phải qua review/approval lại trên revision mới.","aka":["review/approve"]},{"t":"comment","vi":"Ý kiến góp ý khi review tài liệu. Trong bài: comment và cách xử lý phải được lưu trong review record.","aka":["comments"]},{"t":"change history","vi":"Lịch sử thay đổi: mỗi revision ghi số, ngày, author, mô tả, lý do/CR, reviewer, approver. Chỉ có dòng \"bản đầu\" thì chưa chứng minh change control hoạt động."},{"t":"revision history","vi":"Bảng lịch sử các revision của tài liệu (Rev, ngày, author, thay đổi, lý do/CR/RCA ID, reviewer, approver). Cùng nghĩa với change history ở mức tài liệu."},{"t":"rev","vi":"Viết tắt của <i>revision<\/i> — số hiệu bản sửa của tài liệu (0.1 draft, 1.0 approved, 1.1…). \"Draft rev\" là bản nháp revision mới đang sửa.","aka":["Rev."]},{"t":"addendum","vi":"Phụ lục / phần bổ sung chính thức. Trong bài: khi RCA đã approved có evidence mới, tạo revision hoặc addendum có review lại, không sửa âm thầm bản cũ.","aka":["addenda"]},{"t":"revision/addendum","vi":"Hai cách hợp lệ để thay đổi tài liệu đã duyệt: tạo revision mới hoặc thêm addendum (phần bổ sung chính thức), cả hai đều qua review/approval."},{"t":"draft/approved/superseded","vi":"Các trạng thái của tài liệu controlled: draft (nháp, chưa dùng chính thức), approved (đã duyệt, có hiệu lực), superseded (đã bị revision mới thay thế nhưng vẫn lưu).","aka":["draft/approved"]},{"t":"Supersede/Archive","vi":"Bước cuối vòng đời tài liệu: bản cũ bị revision mới thay thế (supersede) và được lưu trữ (archive) — không xóa, vẫn tra được."},{"t":"archive","vi":"Lưu trữ. Trong bài: bản tài liệu cũ chuyển sang superseded và được lưu lại, không xóa, để còn truy vết.","aka":["archived","archive old"]},{"t":"notify","vi":"Thông báo. Trong bài: sau khi duyệt revision mới phải báo cho người dùng tài liệu biết bản nào đang có hiệu lực.","aka":["notify users"]},{"t":"edit","vi":"Chỉnh sửa. Trong bài: sửa trên bản nháp revision mới (draft rev), không sửa thẳng bản đã approved.","aka":["edits","edited"]},{"t":"title","vi":"Tiêu đề. Trong bài là một trường của document control block."},{"t":"auditor","vi":"Người kiểm toán/đánh giá độc lập, kiểm xem quy trình và hồ sơ có đúng quy định không. Trong bài: năm cơ chế giữ tài liệu trung thực tương ứng năm câu hỏi auditor sẽ hỏi.","aka":["auditors"]},{"t":"wiki","vi":"Trang tài liệu nội bộ ai cũng sửa được. Trong bài: \"thêm một dòng vào wiki\" là ví dụ preventive action yếu, không chặn được lỗi tái diễn.","aka":["wikis"]},{"t":"site","vi":"Địa điểm, văn phòng/chi nhánh. Trong bài: đồng nghiệp ở site khác mở một bản runbook khác — minh họa hậu quả không có tài liệu controlled.","aka":["sites"]},{"t":"conclusion","vi":"Kết luận. Trong bài: khi dùng AI tóm tắt, người phải kiểm timestamp, source, conclusion và data boundary; AI không tự xác nhận root cause.","aka":["conclusions"]},{"t":"confidence","vi":"Mức độ tin cậy của kết luận. Trong bài: giả thuyết được hỗ trợ thì ghi \"Keep + confidence\" kèm phạm vi đã test, thay vì tuyên bố chắc chắn."},{"t":"keep","vi":"Giữ lại. Trong bài: kết quả test hỗ trợ giả thuyết → <i>Keep + confidence<\/i> (giữ giả thuyết, ghi mức tin cậy và phạm vi đã test).","aka":["Keep + confidence"]},{"t":"rejected","vi":"Đã bị bác bỏ. Trạng thái giả thuyết có evidence chống lại; vẫn được lưu trong hồ sơ RCA."},{"t":"supported/rejected/open","vi":"Ba trạng thái kết luận của một giả thuyết: supported (được hỗ trợ trong phạm vi test, kèm confidence), rejected (bị bác bỏ, vẫn lưu), open (chưa kiểm được)."},{"t":"hypothesis-driven","vi":"Dẫn dắt bằng giả thuyết: viết nhiều giả thuyết cạnh tranh, ghi prediction trước, rồi chọn phép thử phân biệt chúng — thay vì đoán mò hay bám một ý.","aka":["hypothesis-driven troubleshooting","hypothesis-driven investigation"]},{"t":"contain","vi":"Khoanh lại, ngăn lan. Trong bài: chặn lỗi lan rộng (pause rollout, rollback, restart) trước khi biết root cause.","aka":["contained"]},{"t":"contain/fix/validate","vi":"Chuỗi ba bước xử lý sự cố: contain (chặn lan), fix (sửa), validate (kiểm bằng regression, target/variant test, staged rollout)."},{"t":"voltage","vi":"Điện áp. Trong bài là một yếu tố môi trường của xe (nguồn yếu, sụt áp) cần ghi khi thu evidence.","aka":["power/voltage"]},{"t":"n/m","vi":"Tỷ lệ tái hiện: lỗi xuất hiện n lần trên m lần thử. Ghi n/m cùng điều kiện lab cho thấy lỗi tái hiện ổn định hay chập chờn."},{"t":"design note","vi":"Ghi chú thiết kế: tài liệu ngắn mô tả một quyết định/giải pháp kỹ thuật. Trong bài là ví dụ tài liệu sinh ra từ CAPA cần được kiểm soát như runbook.","aka":["design notes"]},{"t":"RCA report","vi":"Báo cáo phân tích nguyên nhân gốc: tóm tắt, impact, timeline, giả thuyết, causal analysis, CAPA, traceability. Bản thân nó cũng là tài liệu controlled có ID, version, reviewer, approver.","aka":["RCA reports"],"cs":true},{"t":"RCA ID","vi":"Mã định danh của một bản RCA, dùng để trỏ từ CR, revision tài liệu và CAPA về đúng phân tích gốc.","aka":["RCA IDs"],"cs":true},{"t":"action item","vi":"Đầu việc cụ thể cần làm, có owner và hạn. Trong bài: mỗi CAPA được tách thành action item có thể kiểm.","aka":["action items"]},{"t":"ECU/VM","vi":"ECU hoặc máy ảo (VM) trên CDC — nơi sinh ra log/timestamp. Mỗi ECU/VM có thể có đồng hồ riêng, nên phải ghi clock domain khi ghép timeline.","cs":true},{"t":"access/retention","vi":"Hai thuộc tính của tài liệu/evidence: access (ai được đọc/sửa) và retention (giữ trong bao lâu). Ghi trong document control block.","aka":["access / retention"]},{"t":"boot log","vi":"Log ghi trong quá trình khởi động. Trong case reboot loop, boot log là evidence chính cho thấy hệ thống crash ở bước nào.","aka":["boot logs"]},{"t":"crash log","vi":"Log ghi lúc chương trình crash (lỗi, stack, trạng thái). Trong case dùng cùng cache header và binary ID để kiểm giả thuyết schema mismatch.","aka":["crash logs"]},{"t":"hardware revision","vi":"Phiên bản phần cứng của ECU/board. Là một chiều cần ghi khi so cohort, vì lỗi có thể chỉ xuất hiện ở một hardware revision.","aka":["hardware revisions"]},{"t":"baseline/release","vi":"Baseline hoặc release mà tài liệu/RCA đang mô tả: tổ hợp code/model/hardware/config đã chốt. Tài liệu controlled phải trỏ tới baseline/release liên quan, nếu không runbook có thể mô tả một build không còn tồn tại.","aka":["baseline / release"]},{"t":"cohort/build","vi":"Mắt xích trong chuỗi traceability của incident: nhóm xe bị ảnh hưởng (cohort) và bản build chúng đang chạy. Từ đây truy tiếp tới release, requirement/ADR, test, RCA và CAPA."},{"t":"Requirement/ADR","vi":"Mắt xích traceability: yêu cầu (requirement) hoặc quyết định kiến trúc (ADR) đứng sau release bị lỗi. Nối incident tới đây cho biết lỗi do yêu cầu/quyết định nào và cần sửa ở đâu."},{"t":"panel","vi":"Tấm màn hình vật lý (LCD/OLED) nơi pixel thật sự sáng lên. Trong bài, panel là chặng cuối của frame path: chỉ khi pixel đổi trên panel thì người lái mới thấy, nên latency của nội dung safety phải đo tới panel chứ không dừng ở GPU.","aka":["panels"]},{"t":"hardware plane","vi":"Plane phần cứng của DPU: layer được gán lên hardware plane sẽ được DPU ghép trực tiếp lúc quét, không qua GPU, nên nhanh và ít phụ thuộc. Trong bài hay dùng để giữ riêng một plane cho telltale/camera lùi của cluster.","aka":["hardware planes"]},{"t":"reserved plane","vi":"Hardware plane được dành riêng cho một nội dung quan trọng (ví dụ cảnh báo cluster, camera lùi) để nó không phải tranh GPU composition với domain khác. Là một lựa chọn khi kim/cảnh báo bị giật do GPU dùng chung.","aka":["reserved planes"]},{"t":"Surface Manager","vi":"Thành phần quản lý surface: gom surface thành layer, gán layer lên display, quyết định layout, z-order, focus và quyền overlay (control plane). Trong bài, Surface Manager phải là thành phần tin cậy để app/guest không chiếm được vùng safety.","aka":["Surface Managers"]},{"t":"Surface Manager/compositor","vi":"Cách viết gộp Surface Manager và compositor — cặp thành phần quyết định (policy) và thực thi việc ghép layer. Bài nhấn mạnh policy z-order/overlay phải được chính cặp này, khi là thành phần tin cậy, cưỡng chế.","aka":["Surface Manager/compositors"]},{"t":"surface queue","vi":"Hàng đợi buffer gắn với một surface: app lấy buffer trống từ đây để vẽ, vẽ xong thì queue lại cho compositor kèm acquire fence. Queue sâu giúp đỡ giật nhưng làm tăng frame age (nội dung cũ hơn).","aka":["surface queues","surface/buffer queue"]},{"t":"fence","vi":"Hàng rào đồng bộ: đối tượng do driver/kernel cấp, chuyển sang trạng thái signaled khi một việc xong (GPU ghi xong, display đọc xong). Nhờ fence, compositor/DPU biết chính xác lúc dùng được buffer; thiếu fence gây tearing, chờ sai fence gây deadlock/miss deadline.","aka":["fences"]},{"t":"acquire fence","vi":"Fence đi kèm buffer khi app queue cho compositor, báo lúc GPU đã ghi xong buffer đó. Compositor/DPU chỉ dùng buffer sau khi acquire fence signaled; chờ acquire fence quá lâu là dấu hiệu GPU chậm.","aka":["acquire fences"]},{"t":"release fence","vi":"Fence báo display đã đọc xong một buffer và trả buffer đó về cho producer để vẽ frame mới. Nếu release fence về muộn, producer thiếu buffer trống và phải chờ.","aka":["release fences"]},{"t":"present fence","vi":"Fence báo frame đã thực sự được đưa lên màn hình (tại vblank). Trong bài là mốc gần nhất với “người lái đã thấy” mà phần mềm đo được, gần hơn GPU completion; mốc thật nhất vẫn là glass-to-glass.","aka":["present fences"]},{"t":"acquire","vi":"Lấy được / giành quyền dùng. Trong bài thường gặp trong acquire fence: tín hiệu cho phép bên nhận (compositor/DPU) “lấy” buffer để dùng sau khi GPU ghi xong.","aka":["acquired","acquires"]},{"t":"signaled","vi":"Trạng thái “đã báo hiệu” của fence: việc mà fence theo dõi (GPU ghi, display đọc) đã xong, bên đang chờ có thể tiếp tục. Trước khi signaled, ai dùng buffer là có nguy cơ đọc dữ liệu dở.","aka":["signalled"]},{"t":"DPU","vi":"Khối phần cứng hiển thị trong SoC (còn gọi display controller): đọc buffer từ memory, ghép các plane, scale, chuyển màu và đẩy pixel ra link tới panel theo nhịp refresh. Trong bài, DPU là tài nguyên dùng chung giữa các display/domain.","aka":["DPUs"],"full":"Display Processing Unit","cs":true},{"t":"display controller","vi":"Bộ điều khiển hiển thị, chính là DPU: quét buffer theo nhịp vsync, ghép plane và xuất tín hiệu ra panel. Trên Linux được điều khiển qua DRM/KMS. Lỗi ở đây (underrun, thiếu plane) không phải lỗi GPU.","aka":["display controllers"]},{"t":"display controller/plane","vi":"Cách viết gộp: display controller (DPU) cùng các plane phần cứng của nó. Trong diagram của bài, đây là ô thể hiện chặng ghép phần cứng giữa compositor và link/panel."},{"t":"DPU/plane","vi":"Cách viết gộp DPU và các plane của nó — chặng phần cứng ghép và quét ảnh. Diagram trong bài phải có ô DPU/plane cùng owner của nó.","cs":true},{"t":"FPS","vi":"Số frame mỗi giây ra màn hình. Bài nhấn mạnh FPS cao không có nghĩa nội dung tươi: một cảnh báo vẫn có thể trễ dù FPS đẹp, nên với safety phải đo frame age/latency tới panel thay vì chỉ báo cáo FPS.","aka":["fps"],"full":"Frames Per Second","cs":true},{"t":"frames per second","vi":"Số frame mỗi giây — tên đầy đủ của FPS. Đo độ “mượt” về số lượng, không đo nội dung trên màn hình cũ hay mới."},{"t":"vsync","vi":"Vertical sync: tín hiệu nhịp của display, báo bắt đầu một chu kỳ quét (ví dụ mỗi 16,67 ms ở 60 Hz). Frame phải sẵn sàng trước mốc vsync, lỡ nhịp thì phải chờ chu kỳ sau — giống lỡ chuyến xe buýt.","aka":["v-sync","vsyncs"]},{"t":"missed vsync","vi":"Lỡ nhịp vsync: frame chưa sẵn sàng khi tới mốc quét nên màn hình giữ frame cũ thêm một chu kỳ. Là counter quan trọng để giám sát jank theo từng domain/display.","aka":["missed vsyncs","miss vsync"]},{"t":"vblank","vi":"Vertical blanking: khoảng nghỉ ngắn giữa hai lần quét màn hình. Đổi buffer (page flip) tại vblank thì panel không đọc nửa cũ nửa mới, tránh tearing. “Miss vblank” = lỡ nhịp, frame hiện trễ một chu kỳ.","aka":["vblanks","v-blank"],"full":"vertical blanking"},{"t":"miss vblank","vi":"Lỡ mốc vblank: frame hoặc commit chưa xong khi display tới lúc đổi buffer, nên frame bị đẩy sang chu kỳ sau (thêm ~16,67 ms ở 60 Hz). Trong bài là triệu chứng khi cảnh báo cluster tranh GPU với domain khác.","aka":["missed vblank","miss vblanks"]},{"t":"vblank event","vi":"Sự kiện mà driver (ví dụ DRM trên Linux) phát ra ở mỗi vblank, kèm timestamp. Dùng trong trace để biết chính xác frame nào được đưa lên màn hình lúc nào.","aka":["vblank events"]},{"t":"vsync/vblank","vi":"Cặp khái niệm nhịp hiển thị: vsync là tín hiệu nhịp mỗi chu kỳ quét, vblank là khoảng nghỉ giữa hai lần quét — thời điểm an toàn để đổi buffer."},{"t":"vsync/flip","vi":"Cấu hình đồng bộ vsync và page flip (đổi buffer tại vblank). Bài khuyên kiểm cấu hình vsync/flip đầu tiên khi thấy tearing."},{"t":"overlay","vi":"Lớp phủ: layer nằm đè lên layer khác (popup, cảnh báo, camera lùi). Ai được quyền đặt overlay, và ai cưỡng chế quyền đó, là câu hỏi trung tâm; app không tin cậy không được che vùng safety.","aka":["overlays"]},{"t":"overlay permission","vi":"Quyền được đặt overlay (lớp đè) lên một display. Display map trong bài phải ghi rõ overlay permission của từng producer và ai cưỡng chế nó.","aka":["overlay permissions"]},{"t":"overlay policy","vi":"Luật quy định layer nào được đè lên layer nào, ở display nào. Trong bài, overlay policy phải do thành phần tin cậy (compositor/Surface Manager) cưỡng chế, không dựa vào app tự giác.","aka":["overlay policies"]},{"t":"safety overlay","vi":"Lớp đè chứa nội dung an toàn (cảnh báo, telltale) phải luôn hiện trên cùng. Bài cảnh báo app thường không được tự ý che hay giả mạo safety overlay.","aka":["safety overlays"]},{"t":"DRAM","vi":"Bộ nhớ chính (RAM) của SoC. Trong bài, GPU, DPU, video decode và camera cùng đọc/ghi DRAM nên băng thông DRAM là tài nguyên dùng chung dễ nghẽn, gây underrun hoặc frame chậm ở domain khác.","full":"Dynamic Random-Access Memory","cs":true},{"t":"DRAM bandwidth","vi":"Băng thông bộ nhớ DRAM (GB/s) mà SoC cung cấp. Bài yêu cầu ước lượng bandwidth của mọi display (cận dưới + composition) rồi so với budget DRAM từ datasheet, có margin."},{"t":"composition","vi":"Sự ghép (compose) nhiều layer thành ảnh cuối cùng của một màn hình. Có hai cách: DPU ghép bằng hardware plane hoặc GPU composition (GPU vẽ gộp) — cách sau tốn GPU và băng thông.","aka":["compositions"]},{"t":"GPU composition","vi":"Dùng GPU để ghép các layer thành một buffer khi không đủ hardware plane hoặc layer cần hiệu ứng DPU không làm được. Tốn thêm GPU time và băng thông, và làm cluster phụ thuộc GPU dùng chung.","cs":true},{"t":"compose","vi":"Ghép, hợp thành. Trong bài là bước compositor lấy buffer mới nhất của mỗi layer theo nhịp vsync và ghép thành ảnh cuối — một mốc timestamp trong frame path.","aka":["composed","composing","composes"]},{"t":"Hz","vi":"Đơn vị tần số: số lần mỗi giây. Panel 60 Hz làm tươi 60 lần/giây, mỗi chu kỳ ≈ 16,67 ms — đó là frame budget, nhưng không phải bảo đảm latency end-to-end.","full":"Hertz","cs":true},{"t":"z-order","vi":"Thứ tự trên/dưới của các layer (trục z vuông góc màn hình): layer có z cao hiện đè lên layer thấp. Trong bài, ai quyết định z-order là câu hỏi safety: cảnh báo phải luôn ở trên.","aka":["z-orders","z order"]},{"t":"owner layout/z-order","vi":"Owner của layout và z-order — thành phần (thường Surface Manager) có quyền quyết định vị trí và thứ tự trên/dưới của layer. Diagram trong bài phải ghi rõ."},{"t":"scanout","vi":"Quá trình display controller đọc framebuffer từ memory theo từng dòng và đẩy pixel ra panel theo nhịp refresh. Một frame chỉ thật sự “hiện” khi đã được scanout.","aka":["scan-out","scanned out"]},{"t":"scanout/panel","vi":"Hai chặng cuối của frame path: DPU scanout (quét buffer) và panel hiển thị. Lỗi ở chặng này thường do thiếu hardware plane hoặc link/panel, không phải GPU."},{"t":"popup","vi":"Cửa sổ/thông báo bật lên đè lên nội dung đang có. Trong bài, popup cảnh báo là một layer riêng, và cần policy để popup của app thường không che telltale hay cảnh báo safety.","aka":["popups","pop-up","pop-ups"]},{"t":"passenger","vi":"Hành khách (ghế phụ/sau). Trong bài thường là passenger display — màn hình giải trí cho hành khách, ít quan trọng nhất về safety và là thứ bị hy sinh trước khi tài nguyên thiếu.","aka":["passengers"]},{"t":"passenger display","vi":"Màn hình cho hành khách ngồi ghế phụ/sau, chạy giải trí (video, game). Chia chung GPU/DPU/DRAM với cluster nên phải có budget và admission control, và hạ chất lượng trước khi cluster bị ảnh hưởng.","aka":["passenger displays"]},{"t":"head-up display","vi":"Màn hình hiển thị trên kính lái (HUD): chiếu tốc độ, dẫn đường lên kính chắn gió để người lái không phải cúi nhìn. Trong bài là một display safety-relevant cùng cluster, chia chung GPU/DPU với các màn hình khác.","aka":["head-up displays","head-up"]},{"t":"shader","vi":"Chương trình nhỏ chạy trên GPU để tính vị trí hoặc màu pixel. Shader nặng (blur, ánh sáng) nhân với resolution và số lớp chồng là nguyên nhân hay gặp của GPU-bound.","aka":["shaders"]},{"t":"fragment shader","vi":"Shader tính màu cho từng pixel (fragment). Chi phí ≈ resolution × số lớp chồng × độ nặng shader, nên là chỗ GPU hay nghẽn nhất với màn hình lớn và hiệu ứng trong suốt.","aka":["fragment shaders"]},{"t":"fragment","vi":"Mảnh/điểm ảnh ứng viên mà GPU tính màu trong bước rasterization. Trong bài, “GPU-bound ở fragment” nghĩa là GPU nghẽn vì tính màu quá nhiều pixel (overdraw, shader nặng).","aka":["fragments"]},{"t":"job","vi":"Công việc, tác vụ. Trong bài là một khối việc gửi cho GPU (ví dụ vẽ một frame của IVI). GPU khó preempt nhanh nên job của cluster có thể phải chờ job dài của domain khác chạy xong.","aka":["jobs"]},{"t":"refresh","vi":"Làm tươi: panel/display vẽ lại ảnh theo chu kỳ cố định. Nhịp refresh (ví dụ 60 Hz) quyết định frame budget và các mốc vsync.","aka":["refreshes","refreshing"]},{"t":"refresh rate","vi":"Tần số làm tươi: số lần màn hình cập nhật ảnh mỗi giây (ví dụ 60 Hz). Quyết định frame budget (16,67 ms ở 60 Hz) và là một phần của display state.","aka":["refresh rates"]},{"t":"resolution","vi":"Độ phân giải: số pixel ngang × dọc của màn hình hoặc buffer (ví dụ 1920×1080). Resolution tăng thì chi phí shader và băng thông tăng theo; giảm resolution là một cách degrade khi thiếu tài nguyên.","aka":["resolutions"]},{"t":"tearing","vi":"Hiện tượng hình bị “xé”: nửa trên frame cũ, nửa dưới frame mới, do display đọc buffer trong lúc buffer đang bị ghi/đổi. Nguyên nhân thường là thiếu vsync/fence hoặc single-buffer."},{"t":"triple buffering","vi":"Dùng ba buffer xoay vòng để app có thể vẽ tiếp khi hai buffer kia đang chờ/hiển thị, giảm jank. Đổi lại tốn thêm memory và có thể tăng frame age thêm một chu kỳ — trong bài là quyết định kiến trúc, không chỉ là tham số tuning."},{"t":"triple","vi":"Ba, gấp ba. Trong bài thường đi với triple buffering (ba buffer xoay vòng)."},{"t":"completion","vi":"Sự hoàn tất. Trong bài là GPU completion — mốc GPU vẽ xong frame; bài nhắc đó chưa phải lúc người lái thấy, vì sau đó còn compose, scanout và panel.","aka":["completions"]},{"t":"GPU completion","vi":"Mốc thời gian GPU vẽ xong một frame (fence của GPU signaled). Lỗi hay gặp là coi GPU completion là “người lái đã thấy”, trong khi frame còn phải chờ compose, vblank và panel.","cs":true},{"t":"jank","vi":"Hiện tượng giật/khựng do frame lỡ nhịp vsync (dropped frame) hoặc nhịp ra frame không đều. Người lái thấy kim tốc độ hay animation giật.","aka":["janky"]},{"t":"dropped frame","vi":"Frame bị bỏ/lỡ: một chặng (app, GPU, compositor) không kịp nhịp vsync nên màn hình giữ frame cũ. Biểu hiện là jank; nguyên nhân thường là vượt frame budget.","aka":["dropped frames"]},{"t":"dropped frame/jank","vi":"Cách viết gộp dropped frame và jank — cùng một hiện tượng nhìn từ hai phía: hệ thống lỡ frame, người lái thấy giật."},{"t":"dropped frame/tearing/latency","vi":"Ba loại lỗi thời gian chính của hiển thị: lỡ frame (giật), xé hình, và trễ. Mỗi loại có nguyên nhân và cách kiểm khác nhau."},{"t":"frame drop","vi":"Sự rớt frame — đồng nghĩa dropped frame: frame không kịp lên màn hình trong chu kỳ của nó.","aka":["frame drops"]},{"t":"glass-to-glass","vi":"Đo độ trễ từ “mặt kính” này đến “mặt kính” kia: từ sự kiện thật (ống kính camera, đèn tín hiệu) tới lúc pixel đổi trên mặt kính màn hình, bằng camera tốc độ cao hoặc cảm biến quang. Là bằng chứng latency đầu-cuối đáng tin nhất.","aka":["glass to glass"]},{"t":"pacing","vi":"Sự điều nhịp, giữ nhịp đều. Trong bài là frame pacing: các frame phải hiện cách đều nhau, không chỉ đủ số lượng."},{"t":"frame pacing","vi":"Nhịp ra frame: mỗi frame hiện đúng số chu kỳ đều nhau (ví dụ 30 fps trên panel 60 Hz thì mỗi frame đúng 2 vsync). FPS trung bình đủ mà pacing lệch (1-3-2-2) vẫn gây judder."},{"t":"frame budget","vi":"Ngân sách thời gian cho một frame — bằng một chu kỳ refresh (16,67 ms ở 60 Hz). Chặng nào vượt budget dù chỉ một chút thì frame lùi trọn một chu kỳ.","aka":["frame budgets"]},{"t":"frame time","vi":"Thời gian để tạo ra một frame (CPU + GPU). Cùng với GPU busy, frame time giúp phân biệt CPU-bound với GPU-bound; báo cáo theo phân bố p50/p95/p99/max chứ không chỉ trung bình.","aka":["frame times"]},{"t":"frame path","vi":"Đường đi của một frame từ event/state, app render, buffer/fence, compositor, display controller tới panel. Bài yêu cầu vẽ frame path có timestamp ở từng boundary trong research brief.","aka":["frame paths"]},{"t":"frame counter","vi":"Bộ đếm tăng mỗi khi có frame mới. Nếu counter đứng yên trong thời gian quy định thì nội dung đã bị đóng băng (frozen frame) — cơ chế giám sát rẻ cho display safety.","aka":["frame counters"]},{"t":"frozen","vi":"Bị đóng băng: màn hình vẫn hiện nhưng không cập nhật (frame cuối bị giữ lại). Nguy hiểm vì trông như còn sống — ví dụ kim tốc độ đứng yên khi xe đang chạy.","aka":["freezes"]},{"t":"frozen frame","vi":"Frame bị đóng băng: producer đã crash hoặc treo nhưng màn hình vẫn giữ frame cuối. Phát hiện bằng frame counter/heartbeat và timeout theo surface.","aka":["frozen frames"]},{"t":"frozen content","vi":"Nội dung đóng băng trên màn hình — surface mồ côi giữ frame cuối khi producer crash, trông như còn sống. Surface Manager cần timeout per surface để bắt."},{"t":"frozen/black","vi":"Đóng băng hoặc đen: hai dạng mất nội dung của một surface (giữ frame cũ, hoặc không còn gì). Cả hai cần được phát hiện, ví dụ bằng timeout per surface và placeholder."},{"t":"frozen/sai","vi":"Viết tắt nửa Anh nửa Việt: nội dung đóng băng (frozen) hoặc sai. Trong checklist, safety display phải phát hiện được cả hai và có degraded behavior đã test."},{"t":"GB/s","vi":"Gigabyte mỗi giây — đơn vị băng thông bộ nhớ. Ví dụ một display RGBA8888 1920×1080 ở 60 Hz cần ≈ 0,5 GB/s chỉ cho một lượt đọc.","full":"Gigabytes per second","cs":true},{"t":"texture","vi":"Ảnh nguồn mà GPU đọc khi vẽ (icon, hình nền, mặt đồng hồ). Texture lớn hoặc nhiều làm tăng băng thông đọc DRAM và tải GPU.","aka":["textures"]},{"t":"texture/render target/padding","vi":"Ba khoản bộ nhớ chưa tính trong ước lượng buffer: texture (ảnh nguồn), render target (đích vẽ trung gian) và padding (byte đệm căn lề dòng)."},{"t":"render target","vi":"Buffer đích mà GPU vẽ vào (có thể là buffer trung gian, không phải ảnh hiển thị cuối). Tốn thêm memory và băng thông ngoài các buffer hiển thị.","aka":["render targets"]},{"t":"bound","vi":"Bị giới hạn bởi (thường trong CPU-bound, GPU-bound). Cũng gặp trong lower bound — cận dưới của một ước lượng."},{"t":"CPU-bound","vi":"Bị giới hạn bởi CPU: GPU đứng chờ vì CPU chuẩn bị chậm (quá nhiều draw-call, driver nặng, scene preparation chậm). Khi đó GPU mạnh hơn cũng không làm frame nhanh hơn.","aka":["CPU bound"],"cs":true},{"t":"GPU-bound","vi":"Bị giới hạn bởi GPU: GPU luôn bận vì shader nặng, texture, fragment, resolution hay overdraw. Cách xử lý: giảm overdraw/shader hoặc đưa layer lên hardware plane.","aka":["GPU bound"],"cs":true},{"t":"CPU/GPU bound","vi":"Gộp hai chẩn đoán: frame chậm vì CPU (CPU-bound) hay vì GPU (GPU-bound). Phải xác định đúng loại trước khi tối ưu hay xin SoC mạnh hơn.","cs":true},{"t":"underrun","vi":"Thiếu dữ liệu: DPU đang quét mà không đọc kịp dữ liệu từ DRAM (do băng thông bị tranh), gây sọc/nháy trên panel. Counter underrun là dấu hiệu tranh chấp băng thông.","aka":["underruns"]},{"t":"submit","vi":"Gửi, nộp. Trong bài: driver submit command buffer cho GPU để vẽ — một mốc timestamp (render submit) trong frame path.","aka":["submits","submitted","submission"]},{"t":"command buffer","vi":"Bộ đệm lệnh: danh sách lệnh vẽ mà driver dịch từ graphics API và gửi cho GPU thực thi.","aka":["command buffers"]},{"t":"draw-call","vi":"Một lệnh vẽ app gửi qua graphics API. Mỗi draw-call tốn chi phí CPU/driver; quá nhiều draw-call làm frame CPU-bound.","aka":["draw call","draw-calls","draw calls"]},{"t":"draw","vi":"Vẽ. Trong bài: app ghi draw command (lệnh vẽ) qua graphics API, GPU thực thi để tạo pixel.","aka":["draws","drawing"]},{"t":"busy","vi":"Bận. Trong bài là GPU busy — tỷ lệ thời gian GPU đang làm việc; GPU busy gần 100% kèm frame time dài là dấu hiệu GPU-bound."},{"t":"GPU busy","vi":"Tỷ lệ thời gian GPU bận trong một khoảng đo. Theo dõi theo từng domain để biết ai đang chiếm GPU, và kết hợp frame time để chẩn đoán CPU- hay GPU-bound.","cs":true},{"t":"present","vi":"Trình hiện, đưa lên màn hình. Trong bài thường gặp trong present fence — tín hiệu frame đã thực sự hiện trên display.","aka":["presented"]},{"t":"game","vi":"Trò chơi. Trong bài, game 3D trên passenger display là ví dụ workload nặng tranh GPU với cluster, phải qua admission control trước khi được thêm.","aka":["games","gaming"]},{"t":"brief","vi":"Bản tóm lược. Trong bài là research brief — tài liệu nộp ở Assignment 3, nói “đã tìm hiểu gì và đề xuất gì”, kèm frame path, findings, phương án và rủi ro.","aka":["briefs"]},{"t":"multi-display","vi":"Nhiều màn hình (cluster, center, passenger, HUD) chạy trên cùng một SoC, chia chung GPU, DPU, DRAM. Test riêng từng màn hình có thể pass nhưng chạy chung thì tranh tài nguyên.","aka":["multi display"]},{"t":"color","vi":"Màu sắc. Trong bài gặp trong color space (không gian màu), color conversion (chuyển đổi màu) và color range; lỗi sai màu thường do chuyển đổi chứ không phải hiệu năng.","aka":["colors","colour","colours"]},{"t":"color space","vi":"Không gian màu — cách mã hóa màu (RGB, YUV, dải sRGB…). DPU/compositor phải chuyển color space đúng; sai thì hình lệch màu.","aka":["color spaces"]},{"t":"color space/format","vi":"Không gian màu và định dạng pixel của buffer (ví dụ RGBA8888, YUV) — một phần của display state."},{"t":"color/transform","vi":"Gộp hai thuộc tính hiển thị: định dạng/không gian màu và phép biến đổi hình (xoay, lật, scale)."},{"t":"color conversion","vi":"Chuyển đổi màu giữa các định dạng (ví dụ YUV của camera sang RGB của panel). Làm sai ma trận hoặc color range sẽ gây hình lệch màu.","aka":["color conversions"]},{"t":"conversion","vi":"Sự chuyển đổi. Trong bài là color conversion — đổi định dạng/không gian màu khi đưa ảnh camera/video lên màn hình.","aka":["conversions"]},{"t":"full range","vi":"Dải giá trị màu đầy đủ 0–255 cho mỗi kênh 8 bit. Nhầm với limited range làm ảnh bị nhạt hoặc tối/bết màu."},{"t":"limited range","vi":"Dải giá trị màu thu hẹp 16–235 (chuẩn video). Nếu pipeline hiểu nhầm là full range thì camera/video hiển thị sai độ tương phản và màu."},{"t":"limited","vi":"Bị giới hạn. Trong bài gặp ở limited range (dải màu 16–235)."},{"t":"overdraw","vi":"Vẽ đè: một pixel bị tô nhiều lần trong cùng frame do nhiều lớp chồng (nhất là lớp trong suốt). Overdraw nhân chi phí fragment shader, dễ gây GPU-bound."},{"t":"overdraw/shader","vi":"Gộp hai nguồn chi phí fragment: số lần vẽ đè và độ nặng shader. Khi GPU-bound ở fragment, giảm overdraw/shader là hướng xử lý đầu tiên."},{"t":"transform","vi":"Phép biến đổi hình: xoay, lật, scale, dịch. Khi đổi transform/layout mà quên cập nhật mapping touch, chạm vào nút này hệ thống lại nhận nút khác.","aka":["transforms"]},{"t":"orientation/transform","vi":"Hướng màn hình (ngang/dọc) và phép biến đổi (xoay/lật) — một phần của display state, phải đổi đồng bộ với layout và mapping touch."},{"t":"soak","vi":"Ngâm, chạy lâu. Thermal soak/soak test: chạy tải nặng liên tục đủ lâu cho chip nóng ổn định rồi mới đo, vì hiệu năng khi nóng (throttling) mới là thực tế."},{"t":"alpha","vi":"Kênh độ trong suốt của pixel (0 = trong suốt, max = đục). Blend theo alpha cho phép lớp trên nhìn xuyên xuống lớp dưới, nhưng tăng overdraw."},{"t":"blend","vi":"Trộn màu pixel lớp trên với lớp dưới theo alpha. DPU hoặc GPU làm việc này khi ghép layer.","aka":["blends","blended"]},{"t":"blending","vi":"Việc trộn màu các lớp chồng theo alpha. Hardware plane bị giới hạn kiểu blending hỗ trợ; vượt giới hạn thì phải fallback sang GPU composition."},{"t":"blend/depth","vi":"Bước cuối của pipeline GPU: trộn pixel mới với pixel đã có (blend) và kiểm tra độ sâu (depth) để biết lớp nào ở trước."},{"t":"flip","vi":"Lật, đổi. Trong bài là page flip — đổi con trỏ hiển thị sang buffer mới tại vblank.","aka":["flips","flipping"]},{"t":"page flip","vi":"Đổi buffer hiển thị bằng cách chuyển con trỏ sang buffer mới (không copy pixel), làm tại vblank để panel không đọc nửa cũ nửa mới — tránh tearing.","aka":["page flips","page flipping"]},{"t":"zoom","vi":"Phóng to/thu nhỏ. Ví dụ trong bài: zoom bản đồ ở IVI làm GPU bận, khiến kim cluster giật vì hai domain dùng chung GPU.","aka":["zooming","zoomed"]},{"t":"MIPI","vi":"Liên minh định chuẩn giao tiếp cho chip di động; trong bài gặp qua MIPI DSI — chuẩn link hiển thị từ SoC tới panel.","full":"Mobile Industry Processor Interface","cs":true},{"t":"MIPI DSI","vi":"Chuẩn giao tiếp nối tiếp tốc độ cao để truyền hình từ SoC tới panel, phổ biến cho màn hình gần SoC.","full":"MIPI Display Serial Interface","cs":true},{"t":"DSI","vi":"Giao tiếp hiển thị nối tiếp của MIPI, một loại link từ SoC/DPU tới panel.","full":"Display Serial Interface","cs":true},{"t":"eDP","vi":"Phiên bản DisplayPort dùng nội bộ thiết bị để nối SoC với panel; một lựa chọn link hiển thị trong xe.","full":"embedded DisplayPort","cs":true},{"t":"LVDS","vi":"Chuẩn truyền tín hiệu vi sai điện áp thấp, đời cũ nhưng còn phổ biến để nối SoC với panel trong ô tô.","full":"Low-Voltage Differential Signaling","cs":true},{"t":"DSI/eDP/LVDS","vi":"Ba loại link hiển thị từ SoC tới panel: MIPI DSI, eDP và LVDS.","cs":true},{"t":"SerDes","vi":"Cặp chip nén nhiều tín hiệu song song thành luồng nối tiếp (và giải ra ở đầu kia) để kéo cáp dài từ SoC tới màn hình ở xa trong xe.","full":"Serializer/Deserializer","cs":true},{"t":"serializer/deserializer","vi":"Bộ tuần tự hóa / giải tuần tự hóa — tên đầy đủ của SerDes: biến tín hiệu song song thành nối tiếp để truyền xa rồi giải ngược lại."},{"t":"TCON","vi":"Chip điều khiển định thời trên panel: nhận tín hiệu từ link và điều khiển từng hàng/cột pixel sáng đúng lúc.","full":"Timing Controller","cs":true},{"t":"timing controller","vi":"Bộ điều khiển định thời — tên đầy đủ của TCON, chip trên panel điều khiển pixel theo đúng nhịp."},{"t":"panel/TCON","vi":"Panel cùng chip TCON của nó — chặng cuối cùng nơi pixel được cập nhật; cộng thêm response time của panel.","aka":["Panel/TCON"],"cs":true},{"t":"touch","vi":"Chạm, cảm ứng. Trong bài, touch là input của màn hình; mapping tọa độ touch phải khớp với layout/transform hiện tại.","aka":["touches"]},{"t":"touch/rotary","vi":"Hai kiểu input: màn hình cảm ứng và núm xoay. Surface Manager quyết định surface nào nhận input loại này."},{"t":"blur","vi":"Làm mờ — hiệu ứng tốn nhiều fragment shader. Trong bài là ví dụ shader nặng làm GPU-bound."},{"t":"width","vi":"Chiều rộng (pixel). Dùng trong công thức bandwidth: bytes/frame = width × height × bytes_per_pixel."},{"t":"height","vi":"Chiều cao (pixel). Dùng trong công thức bandwidth: bytes/frame = width × height × bytes_per_pixel."},{"t":"visible frame","vi":"Frame đã thật sự hiện trên panel cho người lái thấy — mốc cuối của frame path, sau scanout và response time của panel.","aka":["visible frames"]},{"t":"wait","vi":"Chờ. Trong bài: compositor chờ fence, job chờ GPU; worst-case wait (thời gian chờ xấu nhất) phải được đo, không chỉ trung bình.","aka":["waits","waiting","waited"]},{"t":"worst-case wait","vi":"Thời gian chờ xấu nhất đo được (ví dụ job cluster chờ GPU). Governance yêu cầu đo và ghi lại con số này vì safety quan tâm max chứ không phải trung bình."},{"t":"placeholder","vi":"Nội dung giữ chỗ (ảnh/khung mặc định) hiển thị khi surface mất nội dung, thay vì để frame cũ đóng băng hoặc màn đen.","aka":["placeholders"]},{"t":"Wayland","vi":"Giao thức hiển thị hiện đại trên Linux giữa app và compositor (thay X11). Trong automotive thường kèm IVI shell/layer manager để quản lý surface → layer → screen."},{"t":"Linux/Wayland","vi":"Ngăn xếp hiển thị Linux dùng Wayland: compositor (ví dụ Weston) nhận surface của app và ghép, thường thêm IVI shell cho ô tô."},{"t":"Weston","vi":"Compositor tham chiếu (reference) của Wayland, hay dùng làm nền cho compositor trên Linux trong xe."},{"t":"wl_surface","vi":"Đối tượng surface trong giao thức Wayland — vùng vẽ của một app mà compositor quản lý."},{"t":"Wayland IVI Extension","vi":"Phần mở rộng Wayland của GENIVI/COVESA cho xe: thêm IVI shell/layer manager theo mô hình surface → layer → screen để quản lý layout nhiều màn hình."},{"t":"extension","vi":"Phần mở rộng. Trong bài là Wayland IVI Extension — bổ sung cho giao thức Wayland dành cho ô tô.","aka":["extensions"]},{"t":"IVI shell/layer manager","vi":"Thành phần thêm vào compositor Wayland trong xe để gom surface thành layer và gán lên screen — đóng vai Surface Manager."},{"t":"GENIVI/COVESA","vi":"GENIVI là liên minh phần mềm infotainment ô tô mã nguồn mở, nay đổi tên thành COVESA (Connected Vehicle Systems Alliance). Họ định nghĩa Wayland IVI Extension.","cs":true},{"t":"DRM/KMS","vi":"Framework trong Linux kernel để điều khiển GPU và display: DRM quản lý buffer/GPU, KMS đặt chế độ hiển thị (resolution, refresh, plane) và commit theo vblank.","full":"Direct Rendering Manager / Kernel Mode Setting","cs":true},{"t":"DRM","vi":"Phân hệ Linux kernel quản lý GPU và display; phát vblank event dùng được trong trace. (Trong bài không phải nghĩa “quản lý bản quyền số”.)","full":"Direct Rendering Manager","cs":true},{"t":"DRM/KMS/compositor","vi":"Chuỗi hiển thị trên Linux: compositor quyết định ghép, DRM/KMS gán layer lên plane và commit ra display.","cs":true},{"t":"Kernel Mode Setting","vi":"Cơ chế kernel Linux đặt chế độ hiển thị (resolution, refresh, plane) — chữ KMS trong DRM/KMS."},{"t":"HWC/KMS","vi":"HWC trên Android hoặc KMS trên Linux — lớp quyết định layer nào được map thẳng lên hardware plane, layer nào phải GPU ghép.","cs":true},{"t":"enforce","vi":"Cưỡng chế, bắt buộc tuân thủ. Trong bài: quyền overlay/z-order phải được enforce ở compositor/hardware plane do thành phần tin cậy điều khiển, không chỉ ghi trong tài liệu.","aka":["enforced","enforces","enforcing"]},{"t":"home","vi":"Nút Home (về màn hình chính). Ví dụ trong bài: đổi layout mà touch vẫn dùng mapping cũ, người dùng chạm “Home” nhưng hệ thống nhận nút bên cạnh."},{"t":"time-to-first-frame","vi":"Thời gian từ lúc bật nguồn tới khi frame đầu tiên hiện trên màn hình. Quan trọng với cluster và camera lùi vì có yêu cầu hiện sớm sau khởi động."},{"t":"OpenGL ES","vi":"Graphics API (giao diện lập trình đồ họa) chuẩn cho thiết bị nhúng/di động. App HMI dùng nó ra lệnh vẽ cho GPU; driver dịch thành command buffer.","aka":["OpenGL"],"full":"OpenGL for Embedded Systems","cs":true},{"t":"OpenGL ES/Vulkan","vi":"Hai graphics API phổ biến trong xe: OpenGL ES (lâu đời, dễ dùng) và Vulkan (mới hơn, ít overhead CPU, điều khiển chi tiết hơn).","cs":true},{"t":"Vulkan","vi":"Graphics API thế hệ mới của Khronos, ít overhead CPU hơn OpenGL ES và cho app điều khiển đồng bộ/memory chi tiết hơn."},{"t":"graphics API","vi":"Giao diện lập trình để app ra lệnh vẽ cho GPU (OpenGL ES, Vulkan). Là tầng giữa app/HMI engine và GPU driver trong graphics stack.","aka":["graphics APIs"]},{"t":"graphics stack","vi":"Chuỗi phần mềm/phần cứng từ app tới màn hình: app/HMI engine → graphics API → GPU driver → GPU → buffer queue → compositor → DPU → link → panel.","aka":["graphics stacks"]},{"t":"user-space","vi":"Không gian người dùng — vùng chạy chương trình thường, tách khỏi kernel. User-space GPU driver dịch lệnh graphics API thành lệnh GPU trước khi qua kernel driver.","aka":["user space","userspace"]},{"t":"atomic commit","vi":"Gói các thay đổi hiển thị (buffer, plane, vị trí…) được áp dụng cùng lúc tại một vblank, không có trạng thái nửa vời. Compositor chờ fence rồi gửi atomic commit cho DPU.","aka":["atomic commits"]},{"t":"fence/atomic commit","vi":"Fence và atomic commit — hai cơ chế đồng bộ ở chặng compositor → display: chờ buffer sẵn sàng rồi áp dụng thay đổi cùng lúc."},{"t":"judder","vi":"Chuyển động khựng, không đều dù FPS trung bình đủ — do frame hiện lệch số chu kỳ (ví dụ 1-3-2-2 thay vì 2-2-2-2). Là lỗi frame pacing."},{"t":"vertex","vi":"Đỉnh hình học. Bước đầu pipeline GPU tính vị trí các đỉnh của hình cần vẽ, trước rasterization và fragment.","aka":["vertices","vertexes"]},{"t":"rasterization","vi":"Bước GPU chia hình (tam giác) thành từng pixel/fragment để tính màu. Nằm giữa vertex và fragment shader trong pipeline.","aka":["rasterize","rasterizer"]},{"t":"guarantee","vi":"Bảo đảm, cam kết. Bài nhắc 16,67 ms ở 60 Hz chỉ là một chu kỳ danh nghĩa, không phải guarantee end-to-end latency; muốn có bảo đảm phải đo.","aka":["guarantees","guaranteed"]},{"t":"lower bound","vi":"Cận dưới — mức tối thiểu chắc chắn phải có. Bài bắt đầu ước lượng băng thông bằng lower bound: bytes/frame × fps, rồi cộng thêm composition, texture, overhead.","aka":["lower bounds"]},{"t":"lower","vi":"Thấp hơn, dưới. Trong bài chủ yếu gặp ở lower bound (cận dưới của ước lượng bandwidth)."},{"t":"para-virtualized","vi":"Ảo hóa song song: guest không chạm trực tiếp GPU mà gửi lệnh qua driver ảo tới backend ở host. Linh hoạt, host kiểm soát thứ tự và quyền, nhưng thêm overhead/latency và backend là điểm lỗi chung.","aka":["paravirtualized","para-virtualization","paravirtualization"]},{"t":"mediated pass-through","vi":"Cách chia GPU mà mỗi guest có “GPU ảo” truy cập gần trực tiếp phần cứng, còn việc nhạy cảm (lập lịch, cấp memory) vẫn qua host. Hiệu năng gần native nhưng cần GPU/driver hỗ trợ."},{"t":"mediated","vi":"Có trung gian. Trong bài: mediated pass-through — truy cập gần trực tiếp phần cứng nhưng một số thao tác vẫn qua host làm trung gian."},{"t":"GPU virtualization","vi":"Ảo hóa GPU — cho nhiều OS/VM cùng dùng một GPU vật lý (para-virtualized, mediated pass-through, hardware partitioning). Cách chia quyết định isolation và hiệu năng.","cs":true},{"t":"resource sharing/GPU virtualization","vi":"Bài toán nhiều OS/VM chia nhau GPU, DPU, DRAM trên cùng SoC, và cách ảo hóa GPU để làm việc đó."},{"t":"long-frame count","vi":"Số frame vượt frame budget trong một lần đo. Báo cáo con số này cùng phân bố frame time, vì vài frame dài cũng đủ làm cảnh báo trễ.","aka":["long-frame counts","long-frame"]},{"t":"framebuffer","vi":"Vùng nhớ chứa ảnh của một frame để display controller đọc ra panel. Kích thước = width × height × số byte mỗi pixel.","aka":["framebuffers","frame buffer"]},{"t":"engine","vi":"Bộ máy, phần mềm lõi. Trong bài là HMI engine — framework dựng giao diện HMI và gửi lệnh vẽ qua graphics API.","aka":["engines"]},{"t":"HMI engine","vi":"Phần mềm dựng giao diện người–máy (kim, menu, animation) trên cluster/IVI, nằm trên graphics API trong graphics stack.","cs":true},{"t":"space","vi":"Không gian. Gặp trong color space (không gian màu) và user-space (vùng chạy chương trình thường)."},{"t":"front","vi":"Phía trước. Trong double buffering, front là buffer đang được hiển thị; vẽ thẳng vào front-buffer gây tearing.","aka":["front buffer"]},{"t":"single/front-buffer rendering","vi":"Vẽ thẳng vào buffer đang hiển thị (chỉ một buffer). Ít trễ nhưng display có thể đọc lúc đang vẽ, gây tearing."},{"t":"handle","vi":"Tay cầm/tham chiếu tới một tài nguyên. Zero-copy chuyển handle của buffer giữa các thành phần thay vì copy pixel.","aka":["handles"]},{"t":"coherency","vi":"Tính nhất quán. Gặp trong cache coherency — dữ liệu trong cache CPU và memory phải khớp khi chia sẻ buffer."},{"t":"cache coherency","vi":"Nhất quán giữa cache và bộ nhớ chính: khi CPU, GPU, DPU cùng dùng một buffer, mỗi bên phải thấy dữ liệu mới nhất. Sai coherency gây hình rác hoặc frame cũ dù code “đúng”."},{"t":"GC","vi":"Thu gom rác — runtime tự dọn bộ nhớ không dùng; lúc dọn có thể dừng thread vài ms. GC trên UI thread là nguyên nhân hay gặp của dropped frame.","full":"Garbage Collection","cs":true},{"t":"garbage collection","vi":"Thu gom rác: cơ chế tự động giải phóng bộ nhớ của Java/Kotlin/JS… Có thể làm dừng UI thread, gây vượt frame budget."},{"t":"garbage","vi":"Rác. Gặp trong garbage collection — thu gom vùng nhớ không còn dùng."},{"t":"collection","vi":"Sự thu gom. Trong bài gặp ở garbage collection (GC).","aka":["collections"]},{"t":"UI thread","vi":"Luồng chính xử lý giao diện của app. Việc nặng (I/O chặn, GC) trên UI thread làm app không kịp tạo frame trước vsync.","aka":["UI threads"],"cs":true},{"t":"inversion","vi":"Sự đảo ngược. Gặp trong priority inversion — tác vụ ưu tiên cao phải chờ tác vụ ưu tiên thấp."},{"t":"priority inversion","vi":"Đảo ưu tiên: tác vụ ưu tiên cao bị chặn vì phải chờ tài nguyên đang bị tác vụ ưu tiên thấp giữ. Trong hiển thị có thể làm frame cluster trễ dù cluster có priority cao."},{"t":"post-processing","vi":"Xử lý sau: các bước biến đổi ảnh sau khi render (lọc, chỉnh màu) — ở display/panel có thể thêm độ trễ ẩn mà phần mềm không thấy."},{"t":"scene","vi":"Cảnh — toàn bộ nội dung cần vẽ của một frame. Scene preparation là CPU tính layout, animation trước khi gửi lệnh vẽ.","aka":["scenes"]},{"t":"scene preparation","vi":"Bước CPU chuẩn bị cảnh (tính layout, animation, danh sách lệnh vẽ). Chậm ở đây làm frame CPU-bound."},{"t":"preparation","vi":"Sự chuẩn bị. Trong bài là scene preparation — CPU chuẩn bị nội dung frame."},{"t":"observation","vi":"Sự quan sát. Panel observation là mốc đo cuối: quan sát thật trên panel (camera/cảm biến quang) lúc pixel đổi.","aka":["observations"]},{"t":"crop","vi":"Cắt bớt một phần ảnh. Là một thuộc tính layer (cùng scale, z-order, alpha) do Surface Manager quyết định.","aka":["cropping","cropped"]},{"t":"crop/scale","vi":"Cắt và phóng/thu ảnh của một layer — hai thuộc tính layout do Surface Manager quyết định theo policy HMI."},{"t":"focus","vi":"Tiêu điểm: layer/surface nào đang nhận input (touch, núm xoay). Sai focus thì chạm vào một chỗ nhưng app khác nhận.","aka":["focus owner"]},{"t":"input/focus","vi":"Định tuyến input và focus: surface nào nhận touch/rotary, mapping tọa độ theo transform hiện tại."},{"t":"ISP","vi":"Khối xử lý ảnh từ cảm biến camera (khử nhiễu, cân bằng màu…). Trong bài, buffer camera lùi đi từ ISP tới DPU là một đường cần đo.","full":"Image Signal Processor","cs":true},{"t":"composer","vi":"Bộ ghép. Trong bài là Hardware Composer (HWC) của Android.","aka":["composers"]},{"t":"Hardware Composer","vi":"HAL của Android (HWC) quyết định layer nào map lên hardware plane, layer nào để GPU ghép; do nhà cung cấp SoC hiện thực.","aka":["Hardware Composer HAL"]},{"t":"HWC","vi":"Hardware Composer — HAL của Android làm việc với SurfaceFlinger để giao layer cho hardware plane của DPU.","full":"Hardware Composer","cs":true},{"t":"SurfaceFlinger","vi":"Dịch vụ compositor của Android: quản lý surface/layer và composition, phối hợp với HWC để đưa layer lên display."},{"t":"SurfaceFlinger/HWC","vi":"Cặp compositor của Android: SurfaceFlinger ghép layer, HWC quyết định layer nào đi hardware plane."},{"t":"WindowManager","vi":"Dịch vụ Android quyết định policy cửa sổ: cửa sổ nào ở đâu, z-order, focus — tương ứng vai trò Surface Manager (control plane)."},{"t":"scaler","vi":"Khối phóng/thu ảnh (thường trong DPU). Đổi display mode thì scaler, layout và mapping touch phải đổi nhất quán.","aka":["scalers"]},{"t":"feed","vi":"Luồng dữ liệu đưa vào. Camera feed là luồng ảnh liên tục từ camera đưa lên màn hình.","aka":["feeds"]},{"t":"camera feed","vi":"Luồng ảnh từ camera (thường định dạng YUV) đưa lên màn hình. Sai màu camera feed thường do color range/ma trận chuyển đổi chứ không do hiệu năng.","aka":["camera feeds"]},{"t":"YUV","vi":"Định dạng màu tách độ sáng (Y) và màu (U, V), phổ biến cho camera/video. Phải chuyển sang RGB đúng ma trận và color range khi hiển thị.","cs":true},{"t":"opacity","vi":"Độ đục (ngược với trong suốt) của layer. Là thuộc tính layout do Surface Manager quản lý."},{"t":"stride","vi":"Số byte thực của một dòng ảnh trong memory, có thể lớn hơn width × bpp do căn lề. Phải tính khi ước lượng memory và băng thông.","aka":["strides"]},{"t":"bpp","vi":"Số byte (hoặc bit) mỗi pixel. Trong bài là byte mỗi pixel, ví dụ RGBA8888 = 4 byte/pixel.","full":"bytes (bits) per pixel"},{"t":"padding","vi":"Byte đệm thêm vào cuối dòng/buffer để căn lề theo yêu cầu phần cứng. Làm buffer thực tế lớn hơn width × height × bpp."},{"t":"RGBA8888","vi":"Định dạng pixel 4 kênh đỏ, xanh lá, xanh dương, alpha, mỗi kênh 8 bit = 4 byte/pixel. 1920×1080 RGBA8888 ≈ 8,29 MB mỗi buffer.","cs":true},{"t":"MB/buffer","vi":"Số megabyte cho mỗi buffer — dùng khi tính memory cho double/triple buffering.","cs":true},{"t":"bytes/frame","vi":"Số byte của một frame = width × height × bytes_per_pixel. Nhân với fps ra băng thông đọc tối thiểu."},{"t":"byte/pixel","vi":"Số byte mỗi pixel (bpp). RGBA8888 = 4 byte/pixel.","aka":["bytes/pixel"]},{"t":"full-screen","vi":"Toàn màn hình. Layer full-screen phủ cả display; GPU ghép ba layer full-screen thì băng thông đọc tăng gấp ba.","aka":["full screen","fullscreen"]},{"t":"carve-out","vi":"Vùng nhớ cắt riêng (dành trước) cho một domain, ví dụ memory carve-out cho cluster, để domain khác không chiếm được.","aka":["carve-outs","carveout"]},{"t":"memory carve-out","vi":"Vùng bộ nhớ dành riêng cho một domain/chức năng (ví dụ nội dung safety) để thiếu memory ở domain khác không ảnh hưởng nó.","aka":["memory carve-outs"]},{"t":"heartbeat","vi":"Nhịp tim: tín hiệu định kỳ chứng tỏ một thành phần còn sống. Heartbeat/counter dùng để phát hiện frozen frame hoặc guest treo.","aka":["heartbeats"]},{"t":"Perfetto","vi":"Công cụ trace hiệu năng của Android/Linux (Google), ghi sự kiện CPU, GPU, frame theo clock chung để ghép timeline."},{"t":"systrace","vi":"Công cụ trace đời trước của Android (nay được Perfetto thay thế), xem thời gian các thread và frame."},{"t":"Perfetto/systrace","vi":"Bộ công cụ trace trên Android dùng clock chung để thấy frame đi qua từng chặng."},{"t":"ftrace","vi":"Công cụ trace tích hợp trong Linux kernel, ghi sự kiện kernel (scheduler, driver, vblank) có timestamp."},{"t":"GPU timestamp query","vi":"Truy vấn để GPU tự ghi thời điểm bắt đầu/kết thúc một pass vẽ, cho thời gian GPU thật — kết hợp với CPU trace để tìm stage giới hạn.","aka":["GPU timestamp queries","GPU timestamp/query"],"cs":true},{"t":"backlight","vi":"Đèn nền của màn hình LCD. Panel đen chưa chắc là lỗi graphics — hãy kiểm backlight, link, power trước."},{"t":"setting","vi":"Thiết lập, cài đặt. Trong bài gặp trong Kernel Mode Setting (KMS).","aka":["settings"]},{"t":"processor","vi":"Bộ xử lý. Gặp trong image signal processor (ISP).","aka":["processors"]},{"t":"black","vi":"Màu đen, màn hình đen. Black screen là một symptom: có thể do graphics, nhưng cũng có thể do backlight, link hay power."},{"t":"diagnosis","vi":"Chẩn đoán. Trong rubric: artifact diagnosis — xác định nguyên nhân dropped frame, tearing, latency."},{"t":"safety display","vi":"Màn hình hiển thị thông tin liên quan an toàn (thường cluster/HUD: tốc độ, telltale). Phải phát hiện nội dung frozen/sai và có degraded behavior đã test.","aka":["safety displays"]},{"t":"display pipeline","vi":"Chuỗi xử lý phía hiển thị (DPU ghép plane, scale, chuyển màu, xuất link). Một số SoC tính CRC ở đây để kiểm nội dung đúng.","aka":["display pipelines"]},{"t":"display map","vi":"Bản đồ ai vẽ gì lên đâu: với từng display ghi producer/VM, compositor, panel, refresh, overlay permission và fallback. Là bước đầu khi phân tích multi-display.","aka":["display maps"]},{"t":"display state","vi":"Trạng thái của một display: mode (resolution, refresh), orientation/transform, color space/format. Đổi state thì layout, scaler, mapping touch phải đổi nhất quán.","aka":["display states"]},{"t":"display policy","vi":"Luật hiển thị của hệ thống: ai được vẽ lên display nào, z-order, overlay. Thuộc về hệ thống chứ không phải từng app.","aka":["display policies"]},{"t":"research topic","vi":"Chủ đề nghiên cứu: một deep-dive kỹ thuật trong khóa học để hỗ trợ một quyết định kiến trúc, kết quả là research brief.","aka":["research topics"]},{"t":"architecture diagram","vi":"Sơ đồ kiến trúc. Trong bài phải thể hiện domain/VM, producer, Surface Manager, compositor, GPU, DPU/plane, link, panel, owner và đường fence.","aka":["architecture diagrams"]},{"t":"governance record","vi":"Bản ghi quản trị tài nguyên dùng chung: owner, budget, priority, quyết định admission control. Là bằng chứng trong checklist.","aka":["governance records"]},{"t":"performance/risk checklist","vi":"Danh sách kiểm tra hiệu năng và rủi ro cho graphics/display, mỗi dòng có cách kiểm, evidence và owner — một sản phẩm nộp của Assignment.","aka":["performance/risk"]},{"t":"GPU hang/reset","vi":"GPU bị treo rồi phải reset. Lỗi chung ảnh hưởng mọi domain dùng GPU, kể cả cluster, nên nội dung safety cần đường fallback không phụ thuộc GPU.","aka":["hang/reset"],"cs":true},{"t":"off/on","vi":"Tắt/bật. Đo so sánh khi bật và tắt một yếu tố (ví dụ video off/on) để xem nó ảnh hưởng thế nào."},{"t":"event/state","vi":"Sự kiện/trạng thái đầu vào (tốc độ, touch, frame camera) — mốc đầu tiên của frame path."},{"t":"state/input","vi":"Trạng thái/đầu vào khởi đầu chuỗi frame: State/input → app render → buffer/fence → compositor → display."},{"t":"input/state","vi":"Đầu vào/trạng thái. Lấy mẫu input/state muộn là một nguồn latency ẩn."},{"t":"latency/jitter","vi":"Độ trễ và độ dao động của độ trễ. Màn hình safety cần cả latency thấp lẫn jitter nhỏ."},{"t":"buffer/fence","vi":"Buffer và fence — chặng chuyển giao dữ liệu ảnh kèm tín hiệu đồng bộ giữa app/GPU và compositor."},{"t":"buffer/fence/pixel","vi":"Ba thứ di chuyển trong data plane: buffer, fence và pixel."},{"t":"fence/queue","vi":"Fence và queue — cơ chế đồng bộ producer với consumer của buffer; queue sâu thì frame age tăng."},{"t":"buffer/queue depth","vi":"Số buffer và độ sâu hàng đợi — quyết định giữa mượt (nhiều buffer) và tươi (ít trễ).","aka":["buffer/queue"]},{"t":"buffer/vsync","vi":"Cấu hình buffer, vsync (và queue) — đánh đổi giữa mượt và độ trễ, phải chọn theo requirement từng display.","aka":["buffer/vsync/queue"]},{"t":"tearing/corruption","vi":"Xé hình hoặc hình rác — hậu quả của thiếu fence: display đọc buffer khi GPU chưa ghi xong."},{"t":"deadlock/miss deadline","vi":"Kẹt cứng hoặc lỡ deadline — hậu quả khi chờ sai fence hoặc các bên chờ lẫn nhau."},{"t":"decode/camera","vi":"Video decode và camera — hai pipeline có buffering riêng có thể thêm độ trễ ẩn."},{"t":"display/panel","vi":"Display và panel — chặng cuối, có thể thêm độ trễ ẩn (post-processing, response time)."},{"t":"display/screen","vi":"Display hay screen — màn hình đích mà layer được gán lên."},{"t":"compositor/hardware plane","vi":"Compositor hoặc hardware plane — nơi phải cưỡng chế quyền overlay, do thành phần tin cậy điều khiển."},{"t":"compositor/DPU","vi":"Compositor hoặc DPU — nơi làm color conversion; sai ma trận ở đây gây lệch màu."},{"t":"app/producer","vi":"App hay producer — bên tạo nội dung vẽ vào surface."},{"t":"app/scene","vi":"App và scene — chặng tạo nội dung UI/video (tính layout, góc kim)."},{"t":"app/sensor","vi":"App hoặc cảm biến — điểm bắt đầu của frame (ví dụ camera lùi bắt đầu từ cảm biến)."},{"t":"app/GPU","vi":"App và GPU — bên vẽ vào buffer."},{"t":"app/guest","vi":"App hoặc guest VM không tin cậy — không được chiếm vùng safety."},{"t":"UI/video","vi":"Nội dung giao diện hoặc video mà app tạo ra.","cs":true},{"t":"surface/layer","vi":"Surface và layer — đối tượng mà SurfaceFlinger/compositor quản lý trước khi ghép."},{"t":"surface/plane","vi":"Surface hoặc plane dùng chung giữa hai màn hình — khi đó bandwidth không đơn giản nhân đôi."},{"t":"producer/VM","vi":"Producer và VM chứa nó — chặng thứ hai trong display map: ai vẽ, chạy ở domain nào."},{"t":"domain/VM","vi":"Domain hoặc VM — đơn vị chia tài nguyên và cô lập trên CDC."},{"t":"VM/OS","vi":"Máy ảo/hệ điều hành — các domain khác nhau trên cùng SoC dùng chung GPU/DPU.","cs":true},{"t":"VM/RTOS","vi":"Máy ảo chạy RTOS — nơi thường đặt HMI cluster vì cần thời gian thực và tin cậy.","cs":true},{"t":"host/VM","vi":"Host hoặc VM điều khiển — nơi đặt backend GPU trong mô hình para-virtualized."},{"t":"GPU/VM","vi":"GPU và VM mà một display dùng — cột trong display map.","cs":true},{"t":"GPU/memory contention","vi":"Tranh chấp GPU và bộ nhớ giữa các domain — nguyên nhân hay gặp làm cluster trễ."},{"t":"GPU queue/memory contention","vi":"Tranh chấp hàng đợi GPU và bộ nhớ dùng chung — giả thuyết thường được kiểm khi cảnh báo miss vblank.","aka":["queue/memory contention"]},{"t":"GPU/display","vi":"Tài nguyên GPU và display dùng chung giữa nhiều domain, cần governance."},{"t":"GPU/driver","vi":"GPU và driver — mediated pass-through cần cả hai hỗ trợ."},{"t":"GPU/DPU/buffer","vi":"GPU, DPU và buffer — các tài nguyên cần chia giữa domain.","cs":true},{"t":"GPU/DPU/DRAM","vi":"Ba tài nguyên phần cứng dùng chung giữa các màn hình: GPU vẽ, DPU quét, DRAM chứa buffer.","cs":true},{"t":"driver/kernel","vi":"Driver và kernel — bên cấp và quản lý fence."},{"t":"graphics/display","vi":"Đồ họa và hiển thị — phạm vi của bài C.2."},{"t":"SoC/GPU","vi":"Loại SoC và GPU — giả định đầu tiên trong research brief."},{"t":"SoC/headroom","vi":"SoC và độ dư tài nguyên (headroom) — góc kinh tế khi chọn chip."},{"t":"SoC/OS/display","vi":"Bối cảnh SoC, OS và display trong research brief."},{"t":"supplier/BSP","vi":"Nhà cung cấp hoặc BSP của họ — nơi phải xác minh những điều chưa đo được."},{"t":"stack/BSP","vi":"Ngăn xếp phần mềm và BSP thật — phải xác minh tên/vai trò thành phần trên đó."},{"t":"QNX/hypervisor","vi":"QNX hoặc hypervisor — nền tảng thường dùng công cụ trace của vendor."},{"t":"QNX/vendor","vi":"Ngăn xếp QNX hoặc của vendor — tên thành phần khác Android/Linux."},{"t":"resolution/refresh","vi":"Độ phân giải và tần số làm tươi của từng display."},{"t":"resolution/fps","vi":"Độ phân giải và fps — budget có thể cấp hoặc hạ khi degrade."},{"t":"refresh/mode","vi":"Refresh và mode của panel — thông tin ghi trong display map."},{"t":"layout/mode","vi":"Layout và mode màn hình — đổi chúng mà quên mapping touch sẽ chạm sai vùng."},{"t":"layout/overlay","vi":"Policy bố cục và lớp đè — phải nằm ở thành phần tin cậy."},{"t":"window/display/pipeline","vi":"Ba đối tượng của QNX Screen: window, display, pipeline (tương ứng surface, màn hình, plane)."},{"t":"thermal/power","vi":"Ngân sách nhiệt và điện của từng display/SoC."},{"t":"cluster/HUD","vi":"Cluster hoặc HUD — nguồn chính của thông tin lái."},{"t":"cluster/center","vi":"Cluster và center display — case ví dụ trong bài."},{"t":"core/MCU","vi":"Core hoặc MCU riêng — đường độc lập cho nội dung safety."},{"t":"CRC/checksum","vi":"Mã kiểm tra tính từ dữ liệu pixel; nội dung đổi thì mã đổi — dùng phát hiện nội dung sai.","cs":true},{"t":"CRC/heartbeat","vi":"CRC để kiểm nội dung đúng và heartbeat để kiểm còn cập nhật — cặp cơ chế giám sát safety display.","cs":true},{"t":"counter/heartbeat","vi":"Bộ đếm frame hoặc nhịp tim — dùng phát hiện frozen frame.","aka":["heartbeat/counter"]},{"t":"link/panel","vi":"Link hoặc panel — mất một trong hai thì cần báo lỗi và chuyển thông tin quan trọng sang display khác."},{"t":"memory/buffer","vi":"Thiếu bộ nhớ hoặc buffer — nội dung safety cần bộ nhớ dự trữ."},{"t":"plane/pipe","vi":"Plane/pipe của display controller — có thể chia riêng cho từng domain.","aka":["pipe/plane"]},{"t":"plane/bandwidth","vi":"Giới hạn số plane và băng thông — mục findings trong brief."},{"t":"hardware plane/fallback","vi":"Hardware plane và đường fallback sang GPU composition khi thiếu plane."},{"t":"safety/degradation","vi":"Cơ chế safety và degradation (hy sinh theo thứ tự)."},{"t":"priority/preemption","vi":"Ưu tiên và preempt — phần của governance chia GPU."},{"t":"bandwidth/memory","vi":"Bảng ước lượng băng thông và bộ nhớ cho các display."},{"t":"camera/protected content","vi":"Nội dung camera hoặc nội dung được bảo vệ — không domain khác được đọc."},{"t":"camera/video","vi":"Nguồn camera hoặc video — thường dùng định dạng YUV."},{"t":"evidence/owner","vi":"Evidence và owner — mỗi dòng checklist phải có."},{"t":"role/criticality","vi":"Vai trò và mức quan trọng (safety) của mỗi display."},{"t":"overhead/latency","vi":"Chi phí phụ và độ trễ thêm — cái giá của para-virtualization."},{"t":"layer/crash","vi":"Test app cố che layer hoặc bị crash — kiểm compositor có cưỡng chế được không."},{"t":"guest crash/GPU reset","vi":"Guest bị crash hoặc GPU reset — không được kéo cluster theo."},{"t":"trace/glass-to-glass/video","vi":"Ba cách lấy evidence: software trace, đo glass-to-glass, quay video panel."},{"t":"p50/p95/p99/max","vi":"Các phân vị của phân bố: p50 là trung vị, p99 là mức mà 99% mẫu nhanh hơn, max là xấu nhất. Safety quan tâm đuôi (p99/max)."},{"t":"amplifier","vi":"Bộ <b>khuếch đại<\/b> (gọi tắt <i>amp<\/i>): biến tín hiệu âm thanh yếu thành công suất đủ đẩy loa. Trong xe, amp có thể nằm trên board head unit hoặc là ECU riêng; nó có trạng thái mute, gain, fault và nhận lệnh điều khiển — PCM đã tới HAL chưa chắc amp đã phát.","aka":["amplifiers","amp","amps"]},{"t":"external amplifier","vi":"Amp <b>ngoài<\/b>: bộ khuếch đại là một ECU riêng, nối với head unit qua audio bus (A2B), Ethernet AVB/TSN… Nó có nguồn, clock và lỗi riêng, nên cần interface dữ liệu + điều khiển + chẩn đoán rõ ràng và đường dự phòng khi mất link.","aka":["external amp","external amps","external amplifiers"]},{"t":"external","vi":"Bên ngoài. Trong bài chỉ thiết bị nằm ngoài head unit/SoC, ví dụ external amplifier là amp đặt ở ECU riêng, nối bằng bus hoặc mạng."},{"t":"multi-zone","vi":"Nhiều vùng nghe cùng lúc: mỗi zone phát nguồn riêng (lái nghe navigation, sau xem phim). Multi-zone làm focus, routing, volume và đồng bộ phức tạp hơn nhiều so với một focus chung cho cả xe.","aka":["multizone","multi zone"]},{"t":"audio focus","vi":"Cơ chế xin/nhả quyền phát âm thanh của framework (ví dụ Android Audio focus): app xin focus, policy quyết định cấp hay không và các nguồn khác phải duck/pause. Là một phần của control path."},{"t":"DSP","vi":"Bộ xử lý tín hiệu số: chip/lõi chuyên tính toán trên mẫu âm thanh (EQ, mix, lọc ồn, khử vọng, crossover, delay). Trong xe, DSP có thể nằm trong SoC, trong amp hoặc riêng; nó thêm group delay và có thể hang — cần heartbeat.","aka":["DSPs"],"full":"Digital Signal Processor","cs":true},{"t":"route","vi":"<b>Đường đi<\/b> của một nguồn âm tới loa/zone cụ thể (source → speaker). Trong bài, route sai làm âm phát nhầm zone; route phải được khôi phục sau power transition hay DSP restart.","aka":["routes","routed"]},{"t":"route ID","vi":"Mã định danh của một route ở HAL/driver, dùng để nối stream của framework với slot/kênh phần cứng. Ghi route ID trong log giúp lần ra âm đã đi đường nào.","aka":["route IDs"]},{"t":"mix","vi":"<b>Trộn<\/b> nhiều nguồn âm thành một luồng (cộng mẫu PCM). Trong bài, mix vừa là một hành vi policy (phát chồng chime lên nhạc) vừa là một chặng xử lý — phải chốt mix ở đâu (SoC hay DSP) và có headroom/limiter để không clip.","aka":["mixes","mixing"]},{"t":"mixer","vi":"Bộ trộn: thành phần (phần mềm trong framework hoặc khối trong DSP) cộng nhiều stream thành một. Mixer thường kèm resample, volume và limiter; vị trí mixer quyết định latency và ai sở hữu tổng gain.","aka":["mixers"]},{"t":"up/down-mix","vi":"Đổi số kênh: <i>up-mix<\/i> tăng (stereo → nhiều loa), <i>down-mix<\/i> giảm (5.1 → stereo). Tốn CPU và thêm delay nên cần biết làm ở chặng nào.","aka":["upmix","downmix","up-mix","down-mix"]},{"t":"PCM","vi":"Điều chế xung mã: dạng <b>số thô<\/b> của âm thanh — chuỗi mẫu biên độ lấy đều theo sample rate. Mọi nguồn (MP3, cuộc gọi, chime) cuối cùng thành PCM chạy trong data path; PCM tới HAL không chứng minh loa đã phát.","full":"Pulse-Code Modulation","cs":true},{"t":"Pulse-Code Modulation","vi":"Tên đầy đủ của PCM: cách số hóa âm thanh bằng việc lấy mẫu biên độ đều đặn rồi lượng tử hóa thành số. Là định dạng chung đi qua buffer, mixer, DSP tới DAC.","aka":["pulse-code"]},{"t":"speaker","vi":"Loa: điểm cuối của data path, biến tín hiệu điện thành âm. Trong xe có nhiều loa theo zone (trước, sau, headrest, bass/treble); lỗi loa gồm hở/chập mạch, ngược phase, sai kênh.","aka":["speakers"]},{"t":"overrun","vi":"<b>Tràn dữ liệu<\/b>: buffer đầy nên mẫu mới bị mất (thường ở phía capture/mic). Là mặt ngược của underrun trong trade-off kích thước buffer.","aka":["overruns"]},{"t":"gain","vi":"<b>Hệ số khuếch đại<\/b> (đo bằng dB): mức tăng/giảm tín hiệu ở một tầng. Tổng âm lượng là tổng gain của nhiều tầng (stream, mixer, DSP, amp); tăng amp gain để sửa lỗi ở tầng khác là cách sai.","aka":["gains"]},{"t":"gain staging","vi":"Phân bổ gain qua từng tầng của chuỗi âm thanh sao cho đủ to mà vẫn còn headroom, không clip và không quá nhỏ gây nhiễu. SA cần một bảng gain theo tầng để biết ai sở hữu mức âm cuối."},{"t":"call-end","vi":"Sự kiện <b>cuộc gọi kết thúc<\/b>. Trong bài, thứ tự call-end và chime-start (cái nào trước, gần đồng thời) là nơi dễ sinh race làm chime bị mute.","aka":["call end","call ends"]},{"t":"emergency call","vi":"Cuộc gọi khẩn cấp (ví dụ eCall khi tai nạn). Là nguồn âm ưu tiên rất cao, phải phát được kể cả khi hệ thống đang lỗi hay quá tải.","aka":["emergency calls"]},{"t":"emergency","vi":"Khẩn cấp. Trong bài xuất hiện trong <i>emergency call<\/i> — cuộc gọi khẩn cấp có ưu tiên cao nhất trong nhóm Communication."},{"t":"prompt","vi":"Câu nhắc/âm nhắc ngắn, ví dụ lời chỉ đường của navigation hay câu trả lời của trợ lý giọng nói. Prompt là nguồn transient: thường duck media rồi restore khi kết thúc.","aka":["prompts"]},{"t":"transport","vi":"Đường <b>truyền tải<\/b> mẫu âm giữa các chip/ECU: TDM/I2S trên board, A2B, Ethernet AVB/TSN, Bluetooth… Mỗi transport góp latency, có clock và kiểu lỗi riêng.","aka":["transports"]},{"t":"mute","vi":"<b>Tắt tiếng<\/b> (không xóa dữ liệu, chỉ chặn âm ra). Mute có thể nằm ở stream, zone hoặc amp; mute bị bỏ quên (không unmute) làm loa im dù mọi log nói OK.","aka":["muted","muting","mutes"]},{"t":"unmute","vi":"Bật lại tiếng sau khi mute. Unmute phải đến sau khi clock ổn định và kèm ramp để tránh tiếng pop; lệnh unmute mất hoặc đến muộn là lỗi hay gặp sau amp restart.","aka":["unmuted","unmuting"]},{"t":"duck","vi":"<b>Giảm nhỏ tạm thời<\/b> một nguồn (thường là nhạc) để nguồn quan trọng hơn nghe rõ, rồi trả lại mức cũ. Ví dụ media bị duck khi navigation prompt phát.","aka":["ducks","ducked","ducking"]},{"t":"unduck","vi":"Trả lại mức âm lượng cũ sau khi duck kết thúc. Phải có ramp và phải đúng lúc: ví dụ không unduck nhạc khi cuộc gọi vẫn còn.","aka":["unducked","unducking"]},{"t":"microphone","vi":"Micro thu âm (gọi tắt <i>mic<\/i>). Dùng cho cuộc gọi, trợ lý giọng nói, ANC; trong đo kiểm, mic trong cabin là cách duy nhất chứng minh âm thực sự ra loa và đo latency end-to-end.","aka":["microphones","mic","mics"]},{"t":"microphone array","vi":"Cụm nhiều micro đặt cạnh nhau để lọc hướng, khử ồn và tách giọng người nói theo ghế. Thường nối về DSP qua audio bus như A2B.","aka":["mic array","mic arrays"]},{"t":"interruption","vi":"<b>Sự ngắt quãng<\/b>: một nguồn đang phát bị nguồn khác chen vào (cuộc gọi, prompt, chime). Policy phải nói hành vi khi bị ngắt và cách restore sau đó, kể cả khi hai interruption chồng nhau.","aka":["interruptions"]},{"t":"click","vi":"Tiếng “tách” ngắn. Trong bài có hai nghĩa: (1) âm phản hồi khi chạm màn hình (touch feedback); (2) tiếng lỗi do underrun hoặc chuyển mức đột ngột không có ramp.","aka":["clicks"]},{"t":"pop","vi":"Tiếng “bụp” lỗi, thường khi bật/tắt amp, unmute hoặc đổi trạng thái đột ngột (DC offset, thiếu ramp). Là một tiêu chí chất lượng cần kiểm ở mọi power transition.","aka":["pops"]},{"t":"pop/click","vi":"Nhóm tiếng lỗi ngắn (bụp/tách) khi tín hiệu thay đổi đột ngột: mute/unmute không ramp, underrun, bật nguồn amp. Tránh bằng ramp, thứ tự startup đúng và buffer đủ.","aka":["pop-click","pops and clicks"]},{"t":"kHz","vi":"Kilohertz = 1.000 lần mỗi giây. Dùng cho sample rate (48 kHz = 48.000 mẫu/giây/kênh) và cho tần số âm thanh.","aka":["KHz"],"full":"kilohertz","cs":true},{"t":"group delay","vi":"<b>Độ trễ nhóm<\/b>: độ trễ do chính các bộ lọc/effect trong DSP gây ra (có thể khác nhau theo tần số). Nó cộng vào latency và làm lệch A/V hoặc lệch giữa các zone, nên phải đo trên target."},{"t":"group","vi":"Nhóm. Trong bài chủ yếu nằm trong cụm <i>group delay<\/i> (độ trễ do bộ lọc DSP); cũng dùng để chỉ nhóm nguồn âm cùng đặc tính.","aka":["groups"]},{"t":"clipping","vi":"<b>Xén đỉnh<\/b>: biên độ tín hiệu vượt mức tối đa (0 dBFS) nên bị cắt phẳng, nghe rè/méo. Hay xảy ra khi mix nhiều nguồn hoặc tăng gain thiếu headroom; amp có thể báo clipping detection."},{"t":"clip","vi":"Bị xén đỉnh: tín hiệu vượt full-scale và bị cắt, gây méo. 0 dBFS là mức tối đa trước khi clip.","aka":["clips","clipped"]},{"t":"loopback","vi":"<b>Bản sao vòng lại<\/b> của tín hiệu thực sự đi ra cuối chuỗi (sau DSP/amp), đưa ngược về để ghi/đo. Dùng làm bằng chứng âm đã phát, đo latency và làm tham chiếu cho echo cancellation.","aka":["loopbacks"]},{"t":"EQ","vi":"Bộ cân bằng âm: tăng/giảm từng dải tần (bass, mid, treble). Trong xe EQ được tune theo cabin và hệ loa, thường nằm trong DSP; ai sở hữu EQ/tuning file phải ghi rõ.","full":"Equalizer","cs":true},{"t":"equalizer","vi":"Bộ cân bằng âm (viết tắt EQ): chỉnh mức từng dải tần để âm hợp cabin và sở thích người nghe. Là một khối của chặng Post trong DSP.","aka":["equalizers","equaliser"]},{"t":"stereo","vi":"Âm thanh hai kênh trái/phải. Ví dụ định dạng quen thuộc trong xe: 48 kHz, 16 bit, stereo."},{"t":"mono","vi":"Âm thanh một kênh. Ví dụ prompt navigation hay giọng thoại thường là mono vì không cần tách trái/phải."},{"t":"surround","vi":"Âm vòm: phát nhiều kênh quanh người nghe để tạo cảm giác không gian. Tốn tài nguyên DSP; khi quá tải, policy có thể tắt surround trước để giữ chime và thoại."},{"t":"concurrency","vi":"<b>Đồng thời<\/b>: những nguồn nào được phát cùng lúc (mix) và ở zone nào. Khác với priority (ai thắng khi tranh nhau); hai câu hỏi phải trả lời riêng trong policy."},{"t":"echo cancellation","vi":"<b>Khử tiếng vọng<\/b>: trừ âm của loa bị mic thu lại để người đầu dây bên kia không nghe tiếng mình vọng. Cần tín hiệu tham chiếu (loopback) và clock playback/capture đồng bộ; latency lệch làm khử kém.","aka":["acoustic echo cancellation"]},{"t":"echo","vi":"Tiếng vọng: âm từ loa bị mic thu lại và gửi ngược về người gọi. Trong bài đi cùng <i>echo cancellation<\/i> cho cuộc gọi rảnh tay."},{"t":"cancellation","vi":"Sự khử/triệt tiêu. Trong bài là echo cancellation (khử vọng) và Active Noise Cancellation (khử ồn chủ động)."},{"t":"Active Noise Cancellation","vi":"Khử ồn chủ động (ANC): dùng mic đo tiếng ồn (động cơ, đường) rồi phát sóng ngược pha qua loa để triệt tiêu. Đòi hỏi latency rất thấp và thường chạy trong DSP/amp.","aka":["active noise control"]},{"t":"ANC","vi":"Khử ồn chủ động: phát âm ngược pha để triệt tiếng ồn trong cabin. Là nguồn thuộc nhóm vehicle sound, đòi hỏi đường xử lý nhanh, thường ở DSP/amp.","full":"Active Noise Cancellation","cs":true},{"t":"active","vi":"Chủ động/đang hoạt động. Trong bài: Active Noise Cancellation (khử ồn chủ động)."},{"t":"noise suppression","vi":"Lọc ồn: giảm tiếng nền (gió, đường) trong tín hiệu mic để giọng nói rõ hơn, dùng cho cuộc gọi và trợ lý giọng nói; thường chạy trong DSP."},{"t":"suppression","vi":"Sự triệt/giảm. Trong bài xuất hiện trong <i>noise suppression<\/i> — lọc ồn cho tín hiệu mic."},{"t":"noise floor","vi":"<b>Mức nhiễu nền<\/b>: mức nhiễu luôn có khi không phát gì. Noise floor thấp thì âm nhỏ vẫn rõ; là một chỉ tiêu chất lượng cùng SNR."},{"t":"safety notification","vi":"Âm báo an toàn (chime, cảnh báo dây an toàn, cảm biến đỗ): phải phát đúng lúc, đủ to, không bị media/volume/mute che, kể cả khi IVI đang bận, boot hay lỗi.","aka":["safety notifications"]},{"t":"safety chime","vi":"Âm chuông cảnh báo an toàn. Ưu tiên cao nhất trong policy; thường được thiết kế để vẫn phát khi IVI reboot (qua cluster/MCU hoặc chime input của amp).","aka":["safety chimes"]},{"t":"channel","vi":"<b>Kênh<\/b> âm thanh (trái, phải, loa sau…), hoặc kênh của amp/slot TDM. Số kênh là một tham số của định dạng PCM; sai mapping kênh làm loa phát sai vị trí.","aka":["channels"]},{"t":"channel layout","vi":"Cách sắp xếp kênh của một stream (stereo, 5.1…, thứ tự kênh). Các stream muốn mix phải cùng layout, nếu không cần up/down-mix.","aka":["channel layouts"]},{"t":"sound","vi":"Âm thanh. Trong bài: telltale sound, engine sound, vehicle sound, sound server.","aka":["sounds"]},{"t":"sound server","vi":"Tiến trình ở user-space nhận âm từ các app, mix và đưa xuống driver (ví dụ PipeWire, PulseAudio trên Linux).","aka":["sound servers"]},{"t":"engine sound","vi":"Âm động cơ tổng hợp hoặc tăng cường phát qua loa (đặc biệt ở xe điện). Thuộc nhóm vehicle sound do xe tạo ra."},{"t":"headphone","vi":"Tai nghe. Trong xe, headphone (thường ở hàng sau) là một zone riêng; cuộc gọi riêng tư có thể chỉ phát ở headphone.","aka":["headphones"]},{"t":"headrest","vi":"Tựa đầu ghế. Loa gắn ở headrest tạo zone nghe riêng cho người ngồi ghế đó.","aka":["headrests"]},{"t":"resample","vi":"<b>Đổi sample rate<\/b> của tín hiệu (ví dụ 44,1 kHz → 48 kHz) để mix chung. Tốn CPU, thêm delay và có thể gây aliasing nếu làm kém; nên chốt một điểm resample rõ ràng.","aka":["resampled","resampler","resamplers","resampling"]},{"t":"clock master","vi":"Thiết bị <b>cấp đồng hồ chuẩn<\/b> cho cả liên kết (ví dụ trên TDM/I2S hay A2B). Mọi bên phải biết ai là master; sai master hoặc hai master gây drift, click, lệch đồng bộ.","aka":["clock masters"]},{"t":"master","vi":"Bên chủ/điều khiển. Trong bài chủ yếu là <i>clock master<\/i> — thiết bị cấp nhịp đồng hồ cho các bên còn lại."},{"t":"warm","vi":"Ấm — hệ thống <b>đã chạy sẵn<\/b> (cache, driver, DSP đã khởi động). Đo latency ở trạng thái warm và cold cho kết quả khác nhau nên phải ghi rõ."},{"t":"TDM","vi":"Ghép kênh theo thời gian: một đường dây số mang nhiều kênh âm, mỗi kênh chiếm một slot. Dùng nối SoC ↔ codec/DSP/amp trên board; cần đúng slot mapping và clock master.","full":"Time-Division Multiplexing","cs":true},{"t":"I2S","vi":"Chuẩn nối tiếp truyền âm thanh số giữa các chip trên cùng board (thường 2 kênh). Cùng họ với TDM, cần đúng clock, độ rộng bit và thứ tự kênh.","full":"Inter-IC Sound","cs":true},{"t":"A2B","vi":"Bus âm thanh ô tô (của Analog Devices) nối amp, mic array, module ở xa bằng cáp xoắn, mang audio + control. Topology daisy-chain, latency cố định, có chẩn đoán link.","full":"Automotive Audio Bus","cs":true},{"t":"AVB","vi":"Nhóm chuẩn IEEE cho truyền audio/video đúng giờ trên Ethernet: đồng bộ clock (gPTP), dành băng thông, presentation time. Dùng nối âm thanh giữa các ECU.","full":"Audio Video Bridging","cs":true},{"t":"TSN","vi":"Mạng nhạy thời gian: thế hệ tiếp theo của AVB, các chuẩn Ethernet IEEE đảm bảo dữ liệu tới đúng giờ, latency có giới hạn. Dùng cho audio giữa ECU và các luồng điều khiển thời gian thực.","full":"Time-Sensitive Networking","cs":true},{"t":"Audio Video Bridging","vi":"Tên đầy đủ của AVB: bộ chuẩn Ethernet IEEE truyền audio/video có đồng bộ đồng hồ và dành trước băng thông."},{"t":"Time-Sensitive Networking","vi":"Tên đầy đủ của TSN: nhóm chuẩn Ethernet cho dữ liệu cần đúng giờ. <i>Time-sensitive<\/i> nghĩa là nhạy thời gian — đến trễ coi như hỏng."},{"t":"rear","vi":"Phía sau. Trong bài: rear zone — vùng nghe của hàng ghế sau, có thể nghe nguồn khác với driver zone."},{"t":"limiter","vi":"Bộ giới hạn: chặn tín hiệu không vượt quá một mức để tránh clip và bảo vệ loa. Đặt sau mix/EQ trong chuỗi DSP.","aka":["limiters"]},{"t":"slot","vi":"Khe thời gian trong khung TDM; mỗi slot mang một kênh âm. Sai slot làm âm ra sai loa/zone.","aka":["slots"]},{"t":"slot mapping","vi":"Bảng gán <b>kênh/zone ↔ slot TDM ↔ kênh amp<\/b>. Phải thống nhất giữa HAL, driver, DSP và amp theo từng variant; lỗi mapping là nguyên nhân hay gặp của loa sai zone.","aka":["slot/channel mapping","channel/slot mapping"]},{"t":"networked audio","vi":"Âm thanh truyền qua bus/mạng giữa các chip hoặc ECU (TDM/I2S, A2B, AVB/TSN) thay vì dây analog. Kéo theo câu hỏi về clock chung, time base, latency và lỗi mất link."},{"t":"networked","vi":"Được nối mạng. Trong bài: networked audio — âm thanh đi qua bus/mạng giữa các ECU."},{"t":"ramp","vi":"<b>Đổi mức từ từ<\/b> (tăng/giảm âm lượng trong vài chục ms) thay vì nhảy đột ngột. Dùng khi duck/unduck, mute/unmute để không tạo pop/click.","aka":["ramps","ramping","ramped"]},{"t":"transition ramp","vi":"Đoạn ramp khi chuyển trạng thái (duck, mute, đổi nguồn). Là một tham số của gain staging cần thống nhất giữa framework và DSP.","aka":["transition ramps"]},{"t":"presentation time","vi":"Thời điểm một mẫu/khung phải được phát ra. Trong AVB/TSN và A/V sync, presentation time giúp các ECU/zone phát cùng lúc dù dữ liệu đến lệch.","aka":["presentation times"]},{"t":"PTS","vi":"Mốc thời gian gắn với mẫu/khung, nói khi nào phải phát. Cùng clock master, PTS là nền của A/V sync (khớp tiếng với hình).","full":"Presentation Time Stamp","cs":true},{"t":"Presentation Time Stamp","vi":"Tên đầy đủ của PTS: dấu thời gian trình bày, cho biết thời điểm phát của một khung âm thanh/hình ảnh."},{"t":"presentation","vi":"Sự trình bày/phát ra. Trong bài nằm trong <i>presentation time<\/i> và PTS (thời điểm phát của mẫu)."},{"t":"A/V","vi":"Âm thanh/hình ảnh. <i>A/V sync<\/i> là đồng bộ tiếng với hình (ví dụ khi xem phim ở rear zone); lệch nhỏ tích lũy thành lip-sync drift.","aka":["A/V sync"],"full":"Audio/Video","cs":true},{"t":"lip-sync","vi":"Khớp khẩu hình: tiếng nói khớp với miệng nhân vật trên màn hình. Clock lệch nhỏ tích lũy thành lip-sync drift (môi lệch tiếng).","aka":["lip sync","lipsync"]},{"t":"assistant","vi":"Trợ lý. Trong bài là voice assistant; nhóm nguồn Guidance/assistant gồm navigation prompt, trợ lý, TTS.","aka":["assistants"]},{"t":"guidance","vi":"Sự dẫn đường/hướng dẫn. Nhóm nguồn Guidance/assistant: lời chỉ đường navigation, trợ lý giọng nói — ngắn, transient, phải nghe rõ trên nền media."},{"t":"crossover","vi":"Bộ phân tần: tách dải tần cho từng loại loa (bass vào loa trầm, treble vào loa tép). Là một khối tuning trong DSP, sai crossover làm mất âm hoặc méo.","aka":["crossovers"]},{"t":"time alignment","vi":"<b>Căn thời gian<\/b>: làm trễ từng loa để âm từ các loa tới tai người ngồi cùng lúc, vì khoảng cách tới mỗi loa khác nhau. Tune theo vị trí ghế."},{"t":"alignment","vi":"Sự căn chỉnh. Trong bài là <i>time alignment<\/i> — căn độ trễ từng loa theo vị trí ngồi."},{"t":"staging","vi":"Phân tầng/sắp đặt theo tầng. Trong bài là <i>gain staging<\/i> — phân bổ gain qua các tầng của chuỗi âm."},{"t":"dBFS","vi":"Mức tín hiệu số so với full-scale; 0 dBFS là mức tối đa trước khi clip, các mức khác là số âm (−12 dBFS…). Không cho biết loa to bao nhiêu ở tai.","full":"decibels relative to Full Scale","cs":true},{"t":"dB SPL","vi":"Mức áp suất âm thanh vật lý tại tai người nghe, đo bằng mic trong xe. Phụ thuộc gain amp, loa và cabin nên không suy ra được từ số dBFS trong file.","cs":true},{"t":"SPL","vi":"Mức áp suất âm (đo bằng dB SPL): độ to thực tế tại tai. Dùng khi tune âm lượng và kiểm chime đủ to.","full":"Sound Pressure Level","cs":true},{"t":"Sound Pressure Level","vi":"Tên đầy đủ của SPL: mức áp suất âm thanh vật lý, đơn vị dB SPL."},{"t":"decibel","vi":"Đơn vị dB, thang logarit đo tỉ lệ mức. Bài phân biệt hai loại decibel: dBFS (số) và dB SPL (âm thật).","aka":["decibels"]},{"t":"full-scale","vi":"<b>Mức tối đa<\/b> mà định dạng số biểu diễn được (0 dBFS). Mix nhiều nguồn có thể vượt full-scale gây clip, nên cần headroom hoặc limiter.","aka":["full scale"]},{"t":"reference level","vi":"Mức tham chiếu thống nhất cho các nguồn (ví dụ −18 dBFS cho hội thoại) để chuyển nguồn không bị to/nhỏ đột ngột. Một tham số của gain staging.","aka":["reference levels"]},{"t":"fault handling","vi":"Xử lý lỗi: phát hiện (diagnostics), phản ứng (mute có kiểm soát, fallback, restart, khôi phục route) và báo lỗi. SA phải giữ ranh giới: fallback không dùng chung tài nguyên với đường chính."},{"t":"fault behavior","vi":"Hành vi khi lỗi: hệ thống làm gì khi một thành phần hỏng (mute, chuyển đường dự phòng, báo DTC). Phải ghi cho từng route/nguồn, đặc biệt chime an toàn.","aka":["fault behaviour"]},{"t":"profile","vi":"Hồ sơ chức năng của Bluetooth: quy định một kiểu dùng cụ thể, ví dụ A2DP (phát nhạc stereo) và HFP (gọi rảnh tay).","aka":["profiles"]},{"t":"seatbelt reminder","vi":"Âm nhắc thắt dây an toàn. Là safety notification: ưu tiên cao, deadline chặt, có thể có yêu cầu pháp lý."},{"t":"seatbelt","vi":"Dây an toàn. Trong bài nằm trong <i>seatbelt reminder<\/i> — chime nhắc thắt dây.","aka":["seatbelts","seat belt"]},{"t":"reminder","vi":"Lời nhắc. Trong bài: seatbelt reminder (âm nhắc thắt dây an toàn).","aka":["reminders"]},{"t":"DAC","vi":"Bộ chuyển số sang tương tự: đổi mẫu PCM thành điện áp analog để khuếch đại ra loa. Nằm trong codec hoặc trong amp.","aka":["DACs"],"full":"Digital-to-Analog Converter","cs":true},{"t":"Digital-to-Analog Converter","vi":"Tên đầy đủ của DAC: bộ chuyển đổi tín hiệu số thành tín hiệu tương tự (điện áp).","aka":["digital-to-analog"]},{"t":"converter","vi":"Bộ chuyển đổi. Trong bài là DAC (Digital-to-Analog Converter).","aka":["converters"]},{"t":"convert","vi":"Chuyển đổi. Trong bài: format convert — đổi định dạng mẫu (bit depth, số kênh) ở chặng per-stream."},{"t":"analog","vi":"Tương tự (liên tục), trái với số. Tín hiệu analog là điện áp liên tục đi từ DAC tới amp và loa.","aka":["analogue"]},{"t":"codec","vi":"Có hai nghĩa: (1) chip <b>audio codec<\/b> chứa DAC/ADC nối SoC với amp/mic; (2) thuật toán nén/giải nén âm (SBC, AAC… trên Bluetooth). Ngữ cảnh trong bài cho biết nghĩa nào.","aka":["codecs"]},{"t":"gPTP","vi":"Giao thức đồng bộ đồng hồ trên Ethernet (IEEE 802.1AS), nền thời gian chung cho AVB/TSN để các ECU phát âm đúng cùng một lúc.","full":"generalized Precision Time Protocol","cs":true},{"t":"generalized Precision Time Protocol","vi":"Tên đầy đủ của gPTP: phiên bản PTP dùng trong AVB/TSN để đồng bộ đồng hồ giữa các node trong mạng."},{"t":"IEEE","vi":"Viện kỹ sư Điện và Điện tử — tổ chức ban hành nhiều chuẩn mạng, ví dụ IEEE 802.1AS (gPTP) và nhóm chuẩn AVB/TSN dùng cho audio trên Ethernet.","full":"Institute of Electrical and Electronics Engineers","cs":true},{"t":"bitrate","vi":"Tốc độ bit: số bit mỗi giây của luồng âm. PCM thô = sample rate × bit depth × số kênh (48.000 × 16 × 2 ≈ 1,536 Mbit/s).","aka":["bit rate","bitrates"]},{"t":"Mbit/s","vi":"Megabit mỗi giây (triệu bit/giây): đơn vị băng thông/tốc độ bit.","aka":["Mbps"],"cs":true},{"t":"transient","vi":"Tạm thời/ngắn. Interruption transient (ví dụ prompt ngắn) chỉ duck rồi restore, khác permanent."},{"t":"permanent","vi":"Lâu dài/vĩnh viễn. Interruption permanent: một app media khác chiếm hẳn, nguồn cũ pause và không tự resume."},{"t":"low voltage","vi":"Điện áp thấp/sụt áp (ví dụ khi khởi động máy). Amp và DSP có thể reset hoặc mute; cần test chime và route ở trạng thái này.","aka":["low-voltage"]},{"t":"started","vi":"Đã bắt đầu. Log framework “stream started” chỉ chứng minh stream được mở, không chứng minh âm đã ra loa."},{"t":"car audio service","vi":"Dịch vụ âm thanh của Android Automotive quản lý zone, focus và volume group cho xe, đứng trên AudioPolicy và Audio HAL.","aka":["CarAudioService"]},{"t":"attenuation","vi":"<b>Sự suy giảm mức<\/b> tín hiệu (gain âm). Khi âm quá nhỏ, phải tìm tầng đang bị attenuation và sửa ở đó thay vì tăng amp gain.","aka":["attenuate","attenuated"]},{"t":"mutex","vi":"Khóa loại trừ lẫn nhau: chỉ một thread giữ tại một thời điểm. Lấy mutex dùng chung với UI trong audio callback có thể làm callback trễ và gây underrun.","aka":["mutexes"],"full":"mutual exclusion"},{"t":"callback","vi":"Hàm được hệ thống gọi lại khi tới lúc; <i>audio callback<\/i> được gọi mỗi period để lấp buffer. Nó phải chạy nhanh và không chặn (không log nặng, không mutex dùng chung).","aka":["callbacks"]},{"t":"MOST","vi":"Bus đa phương tiện cũ trên ô tô (thường cáp quang) để truyền audio/video. Trong bài là ví dụ legacy bus còn trong thiết kế carry-over, cần gateway chuyển đổi.","full":"Media Oriented Systems Transport","cs":true},{"t":"touch feedback","vi":"Phản hồi khi chạm: âm click/rung ngay khi người dùng chạm màn hình. Latency cao làm cảm giác chậm, nhưng giảm buffer để sửa có thể gây underrun."},{"t":"MP3","vi":"Định dạng nén âm thanh phổ biến. Trong bài là ví dụ nguồn phải được decode thành PCM trước khi vào mixer.","full":"MPEG-1 Audio Layer III","cs":true},{"t":"AAC","vi":"Chuẩn nén âm thanh hiệu quả hơn MP3, dùng cho streaming và Bluetooth. Cũng phải decode thành PCM trước khi xử lý.","full":"Advanced Audio Coding","cs":true},{"t":"metadata","vi":"Siêu dữ liệu: dữ liệu mô tả dữ liệu (sample rate, số kênh, định dạng…). Metadata sai làm âm phát sai tốc độ hoặc sai kênh."},{"t":"effect","vi":"Hiệu ứng xử lý âm (EQ, surround, reverb…). Mỗi effect thêm group delay và tải CPU/DSP nên phải đo theo từng effect/route.","aka":["effects"]},{"t":"entertainment","vi":"Giải trí. Nhóm nguồn Entertainment (nhạc, radio, Bluetooth): chất lượng cao, chịu latency vừa, bị duck/pause khi có nguồn quan trọng."},{"t":"radio","vi":"Đài phát thanh (FM/AM/DAB). Là một nguồn entertainment trong xe.","aka":["radios"]},{"t":"A2DP","vi":"Profile Bluetooth phát nhạc stereo chất lượng cao từ điện thoại vào xe. Thuộc nhóm entertainment; latency lớn và thay đổi theo codec.","full":"Advanced Audio Distribution Profile","cs":true},{"t":"HFP","vi":"Profile Bluetooth cho gọi rảnh tay: âm hai chiều mic + loa qua xe. Cần echo cancellation và latency thấp.","full":"Hands-Free Profile","cs":true},{"t":"hands-free","vi":"Rảnh tay: gọi điện mà không cầm máy, qua mic và loa của xe (Bluetooth HFP).","aka":["hands free","handsfree"]},{"t":"VoIP","vi":"Gọi thoại qua mạng Internet (app gọi trên xe). Là nguồn Communication, cần echo cancellation và latency thấp.","full":"Voice over IP","cs":true},{"t":"TTS","vi":"Chuyển văn bản thành giọng nói, dùng cho prompt navigation và trợ lý giọng nói.","full":"Text-to-Speech","cs":true},{"t":"text-to-speech","vi":"Tổng hợp tiếng nói từ văn bản (TTS) — nguồn âm thuộc nhóm guidance/assistant.","aka":["text to speech"]},{"t":"parking sensor","vi":"Cảm biến đỗ xe: âm bíp nhanh dần khi xe gần vật cản. Là safety notification, deadline chặt.","aka":["parking sensors"]},{"t":"parking","vi":"Đỗ xe. Trong bài: parking sensor — cảm biến hỗ trợ đỗ xe phát âm cảnh báo."},{"t":"AudioFlinger","vi":"Dịch vụ âm thanh lõi của Android: chứa mixer/playback thread, trộn các stream rồi đưa xuống Audio HAL."},{"t":"AudioPolicy","vi":"Thành phần policy của Android audio: quyết định route, thiết bị ra và volume cho từng stream.","aka":["AudioPolicyManager"]},{"t":"Audio HAL","vi":"Lớp trừu tượng phần cứng âm thanh: giao diện giữa framework và driver — mở stream, chọn format/route, điều khiển device. Android Automotive định nghĩa Audio HAL chuẩn.","aka":["audio HALs"]},{"t":"audio framework","vi":"Tầng phần mềm âm thanh của hệ điều hành (policy, mixer, effect) nằm trên HAL — ví dụ Android audio, PipeWire trên Linux, io-audio trên QNX.","aka":["audio frameworks"]},{"t":"audio bus","vi":"Bus chuyên truyền âm thanh giữa các module (ví dụ A2B): mang audio + control trên cùng dây, latency cố định.","aka":["audio buses"]},{"t":"ALSA","vi":"Tầng âm thanh của Linux (driver kernel + thư viện user-space) mà sound server như PipeWire dùng để đưa âm ra phần cứng.","full":"Advanced Linux Sound Architecture","cs":true},{"t":"PipeWire","vi":"Sound server hiện đại trên Linux, quản lý luồng audio/video giữa app và ALSA; thay dần PulseAudio."},{"t":"PulseAudio","vi":"Sound server phổ biến trên Linux trước PipeWire: nhận âm từ app, mix và gửi xuống ALSA."},{"t":"io-audio","vi":"Framework/tiến trình quản lý âm thanh của QNX, tương đương sound server; ví dụ cho việc mỗi OS gọi tên thành phần khác nhau."},{"t":"bass","vi":"Âm trầm (tần số thấp). Loa bass nhận dải thấp qua crossover; ngược phase làm mất bass."},{"t":"treble","vi":"Âm cao (tần số cao). Loa treble (loa tép) nhận dải cao qua crossover."},{"t":"aliasing","vi":"Méo do lấy mẫu sai: tần số cao bị gấp thành âm lạ khi resample hoặc lấy mẫu không lọc đủ. Là tiêu chí chất lượng của resampler."},{"t":"head unit","vi":"Bộ điều khiển trung tâm giải trí (IVI) ở táp-lô. Amp có thể tích hợp trên board head unit hoặc là ECU ngoài.","aka":["head units"]},{"t":"bit width","vi":"Độ rộng bit của mỗi mẫu/slot trên TDM/I2S (16, 24, 32 bit). Hai đầu link phải khớp, nếu không âm méo hoặc sai mức."},{"t":"I2C","vi":"Bus nối tiếp 2 dây tốc độ thấp giữa các chip trên board; thường dùng để cấu hình/điều khiển amp, codec (mute, gain, đọc lỗi).","full":"Inter-Integrated Circuit","cs":true},{"t":"SPI","vi":"Bus nối tiếp tốc độ cao hơn I2C giữa chip trên board; cũng dùng làm control interface cho amp/DSP.","full":"Serial Peripheral Interface","cs":true},{"t":"source select","vi":"Lệnh chọn nguồn đầu vào cho amp (ví dụ kênh từ SoC hay chime input). Là một lệnh của control interface amp."},{"t":"select","vi":"Chọn. Trong bài: source select — lệnh chọn nguồn vào của amp."},{"t":"enable","vi":"Bật/kích hoạt. Trong power/startup sequence, thứ tự enable (nguồn, clock, amp) phải đúng để tránh pop và mất chime đầu.","aka":["enabled","enables"]},{"t":"chime trigger","vi":"Lệnh kích hoạt phát chime, ví dụ cluster/MCU gửi trigger tới amp để amp tự phát âm cảnh báo mà không cần IVI.","aka":["chime triggers"]},{"t":"loudness","vi":"Độ to cảm nhận. Loudness compensation tăng bass/treble khi âm lượng nhỏ; thuộc phần tuning do owner quản lý."},{"t":"polarity","vi":"Cực tính (+/−) của dây loa. Sai polarity làm loa ngược phase, triệt tiêu nhau và mất bass."},{"t":"QA","vi":"Đảm bảo chất lượng: nhóm/hoạt động kiểm thử và mở bug. Trong bài, QA mở bug vì latency “lúc nhanh lúc chậm” dù trung bình đạt.","full":"Quality Assurance","cs":true},{"t":"frequency response","vi":"<b>Đáp tuyến tần số<\/b>: mức âm ra theo từng tần số. Phẳng/đúng mục tiêu tuning thì âm trung thực; là một tiêu chí quality."},{"t":"SNR","vi":"Tỉ số tín hiệu trên nhiễu (dB): càng cao âm càng sạch. Là chỉ tiêu chất lượng của đường âm cùng noise floor.","full":"Signal-to-Noise Ratio","cs":true},{"t":"Signal-to-Noise Ratio","vi":"Tên đầy đủ của SNR: tỉ lệ giữa mức tín hiệu hữu ích và mức nhiễu nền.","aka":["signal-to-noise"]},{"t":"ratio","vi":"Tỉ số. Trong bài: Signal-to-Noise Ratio (SNR).","aka":["ratios"]},{"t":"distortion","vi":"Méo tiếng: tín hiệu ra khác hình dạng tín hiệu vào (do clip, amp quá tải, loa hỏng). Là tiêu chí quality.","aka":["distortions"]},{"t":"playback","vi":"Phát lại âm thanh (đường từ app ra loa), đối lập với capture (thu từ mic). Clock lệch giữa playback và capture làm echo cancellation kém."},{"t":"daisy-chain","vi":"Nối nối tiếp: các node nối thành chuỗi, node này nối tiếp node kia (topology của A2B). Ít dây nhưng một điểm đứt có thể ảnh hưởng các node phía sau.","aka":["daisy chain","daisy-chained"]},{"t":"wake","vi":"Thức dậy: thiết bị chuyển từ ngủ/suspend sang chạy. Sau wake, amp/DSP phải sẵn sàng, clock lock và route khôi phục trước khi unmute.","aka":["wake-up","wakeup","wakes"]},{"t":"IC","vi":"Mạch tích hợp (chip). Ví dụ IC amp tự cung cấp chẩn đoán: loa hở/chập, quá nhiệt, quá dòng, DC offset.","full":"Integrated Circuit","cs":true},{"t":"over-temperature","vi":"Quá nhiệt: chip/amp nóng vượt ngưỡng an toàn, thường tự giảm công suất hoặc tắt. Là một chẩn đoán phía amplifier.","aka":["overtemperature"]},{"t":"over-current","vi":"Quá dòng: dòng điện vượt ngưỡng (thường do chập loa). Amp bảo vệ bằng cách ngắt kênh và báo lỗi.","aka":["overcurrent"]},{"t":"DC","vi":"Dòng một chiều. <i>DC offset<\/i> là thành phần một chiều lọt vào tín hiệu âm, gây pop và có thể hại loa.","full":"Direct Current","cs":true},{"t":"DC offset","vi":"Độ lệch một chiều của tín hiệu so với mức 0; gây tiếng bụp khi bật/tắt và làm nóng loa. Amp thường phát hiện và báo lỗi này."},{"t":"offset","vi":"Độ lệch. Trong bài là DC offset — tín hiệu bị lệch khỏi mức 0.","aka":["offsets"]},{"t":"open/short","vi":"Hở mạch / chập mạch dây loa. Load detection của amp phát hiện để báo lỗi và tắt kênh hỏng.","aka":["open/short circuit"]},{"t":"load detection","vi":"Phát hiện tải: amp kiểm tra loa có được nối đúng không (hở, chập). Là một chẩn đoán phía amplifier."},{"t":"buzzer","vi":"Còi/bộ phát bíp đơn giản. Có thể dùng làm đường dự phòng cho chime quan trọng khi mất amp hoặc IVI.","aka":["buzzers"]},{"t":"granted","vi":"Được cấp. “focus granted” là thời điểm framework cấp audio focus cho stream — một mốc đo latency."},{"t":"user experience","vi":"Trải nghiệm người dùng (UX): chất lượng âm, chuyển cảnh mượt, latency thấp. Phải cân với safety notification và system resource."},{"t":"experience","vi":"Trải nghiệm. Trong bài là user experience — cảm nhận của người dùng về âm thanh.","aka":["experiences"]},{"t":"post","vi":"Sau. Chặng <b>Post<\/b> trong DSP là xử lý sau khi mix: EQ, loudness, crossover, time alignment, limiter."},{"t":"per-stream","vi":"Theo từng stream. Chặng Per-stream xử lý riêng mỗi luồng trước khi mix: decode, resample, format convert, volume/duck ramp."},{"t":"tune","vi":"Tinh chỉnh tham số (buffer, EQ, gain) cho kết quả tốt. SA không cần tự tune, nhưng phải phát hiện đề xuất tune nguy hiểm.","aka":["tuned"]},{"t":"tuning file","vi":"File tham số DSP/amp (EQ, crossover, delay, gain) cho từng variant xe/hệ loa. Phải có owner và version; sai tuning file có thể làm một kênh quá nhỏ.","aka":["tuning files"]},{"t":"Solution Architect","vi":"Kiến trúc sư giải pháp (SA): người nhìn cả hệ thống, chốt interface, owner và trade-off. Trong bài, SA giữ “bức tranh hai đường” data path/control path của âm thanh.","aka":["Solution Architects"]},{"t":"power transition","vi":"Chuyển trạng thái nguồn: cold/warm start, suspend/resume, sụt áp. Lúc này amp/DSP phải wake, clock lock, route khôi phục và mute/unmute đúng thứ tự.","aka":["power transitions"]},{"t":"stream open","vi":"Việc framework mở stream tới HAL. Stream open chỉ chứng minh đường dữ liệu được chuẩn bị, không chứng minh âm đã ra loa."},{"t":"stream reservation","vi":"Dành trước băng thông trên mạng cho luồng audio (trong AVB/TSN) để không bị dữ liệu khác chen làm trễ."},{"t":"driver zone","vi":"<b>Vùng nghe của ghế lái<\/b> (zone âm thanh, không phải zone controller). Navigation prompt, chime và cuộc gọi của người lái phát ở đây; amp zone của ghế lái bị kẹt mute là ví dụ lỗi mở đầu bài.","aka":["driver zones"]},{"t":"rear zone","vi":"<b>Vùng nghe hàng ghế sau<\/b>: có thể phát nguồn riêng (ví dụ xem phim) trong khi driver zone nghe navigation. Khi thiếu tài nguyên, policy có thể giảm hiệu ứng ở rear zone trước.","aka":["rear zones"]},{"t":"amp zone","vi":"Nhóm kênh của amplifier phục vụ một vùng nghe (zone âm thanh). Mỗi amp zone có trạng thái mute/gain riêng; zone vẫn MUTE từ cuộc gọi trước làm chime không phát dù PCM đã tới HAL.","aka":["amp zones"]},{"t":"current limit","vi":"Giới hạn <b>dòng điện<\/b> của amp: khi dòng vượt ngưỡng (ví dụ chập loa), amp giảm công suất hoặc ngắt kênh để tự bảo vệ và báo lỗi.","aka":["current limits"]},{"t":"physical fault","vi":"Lỗi phần cứng thật ở cuối chuỗi: loa hỏng, dây hở/chập, lắp sai vị trí hoặc sai zone. Phát hiện bằng load detection của amp hoặc đo bằng mic.","aka":["physical faults"]},{"t":"common-cause failure","vi":"<b>Lỗi chung nguyên nhân<\/b>: một sự cố làm hỏng cùng lúc cả đường chính và đường dự phòng vì chúng dùng chung tài nguyên (DSP, nguồn, SoC). Vì vậy fallback dùng chung DSP/power không phải redundancy thật.","aka":["common-cause failures","common cause failure","common-cause"]},{"t":"PCM-to-HAL","vi":"Mốc đo/log khi mẫu PCM được ghi tới Audio HAL. Chỉ chứng minh dữ liệu đã tới HAL — chưa chứng minh driver, DSP, amp đã phát ra loa; cần thêm amp state và loopback/mic.","cs":true},{"t":"clock_domain","vi":"Tên trường trong message mẫu: cho biết timestamp/sample_time được đo bằng đồng hồ nào (ví dụ monotonic clock của VM-A). Thiếu nó thì không trừ được thời gian giữa hai domain và không tính được freshness."},{"t":"t_display","vi":"Ký hiệu trong sequence diagram mẫu: thời điểm giá trị thực sự lên màn hình — mốc cuối để tính latency end-to-end từ CAN đến display."},{"t":"failure propagation","vi":"Lan truyền lỗi: một chỗ hỏng (chậm, mất, sai, restart) kéo theo lỗi ở các thành phần phụ thuộc. <b>Failure propagation analysis<\/b> đi theo dependency map, hỏi với mỗi node “nếu nó hỏng thì ai bị ảnh hưởng, chặn ở đâu”, rồi chứng minh điểm chặn bằng fault injection.","aka":["failure propagation analysis"]},{"t":"golden","vi":"Vàng / chuẩn mẫu. Trong kiểm thử, “golden” chỉ dữ liệu tham chiếu đã được kiểm là đúng, dùng để so kết quả mới với nó (golden test, golden fixture)."},{"t":"golden fixture","vi":"Bộ dữ liệu mẫu chuẩn: các cặp raw → value đã được kiểm đúng cho từng DBC/supplier/variant. Chạy trong CI của cả producer và consumer — cách rẻ nhất để bắt lỗi “đúng ID, sai số” (sai scale, endian) trước khi ra xe.","aka":["golden fixtures","golden test"]},{"t":"fixture","vi":"Dữ liệu/trạng thái chuẩn bị sẵn cho một bài test (đồ gá trong kiểm thử). Trong bài là các cặp raw frame → giá trị mong đợi dùng lặp lại trong test tự động.","aka":["fixtures"]},{"t":"raw-to-value","vi":"Từ dữ liệu thô sang giá trị: bước parser biến byte trên bus thành con số có đơn vị (theo bit position, endian, scale, offset). “Golden raw-to-value fixtures” là bộ mẫu kiểm đúng bước này."},{"t":"raw value","vi":"Giá trị thô: con số đọc thẳng từ các bit trong frame trước khi áp scale/offset/unit. Cùng raw value nhưng DBC khác (scale/endian khác) sẽ cho ra giá trị vật lý khác."},{"t":"raw capture","vi":"Bản ghi thô các frame trên bus (kèm timestamp) đúng như đã nhận, chưa qua parser. Dùng để so với giá trị decode, replay tái hiện lỗi và làm bằng chứng điều tra."},{"t":"vCPU pinning","vi":"Gắn cố định một vCPU vào một lõi CPU thật để VM quan trọng (như cluster) không bị VM khác chen ngang trên cùng lõi; giúp timing dễ dự đoán hơn.","cs":true},{"t":"arbitration","vi":"Phân xử khi nhiều bên tranh cùng tài nguyên: ai được dùng trước. Trên CAN, arbitration là cơ chế frame có ID ưu tiên cao thắng khi gửi cùng lúc; với CPU/GPU/bus/memory, bài yêu cầu luật “ai thắng” phải được thiết kế trước.","aka":["arbitrate","arbitrated"]},{"t":"resource arbitration","vi":"Phân xử tài nguyên dùng chung (CPU, GPU, bus, memory bandwidth, display) giữa các domain/VM: định nghĩa trước ai được ưu tiên, bao nhiêu, khi quá tải thì ai bị cắt — thay vì để “ai đến trước được trước”."},{"t":"VM-A","vi":"Tên minh họa trong bài cho hai máy ảo trên cùng SoC: VM-A chạy gateway/parser (nguồn dữ liệu tốc độ), VM-B chạy HMI (bên hiển thị). Dùng để minh họa signal vượt ranh giới inter-VM.","aka":["VM-B"],"cs":true},{"t":"DBC","vi":"File mô tả cơ sở dữ liệu CAN: mỗi frame ID chứa signal nào, ở bit nào, endian, scale, offset, unit. Parser dựa vào DBC để giải mã; dùng sai DBC/variant sẽ ra giá trị sai dù đúng ID.","full":"CAN Database (file .dbc)","cs":true},{"t":"LDF","vi":"File mô tả mạng LIN (tương đương DBC của CAN): các frame, signal, lịch truyền và node trên bus LIN.","full":"LIN Description File","cs":true},{"t":"ingress","vi":"Cửa vào / điểm dữ liệu đi vào hệ thống. <b>CAN ingress<\/b> trong bài là chặng frame CAN được nhận và parser biến byte thành giá trị đáng tin (kèm quality, freshness)."},{"t":"door","vi":"Cửa xe. Trong ví dụ của bài, trạng thái cửa (door state) và tốc độ đến từ hai nguồn, thời điểm khác nhau; ghép sai thời điểm sinh cảnh báo “cửa mở khi xe chạy” dù xe đã đứng yên."},{"t":"graph","vi":"Đồ thị: các node nối với nhau bằng cạnh phụ thuộc. <b>Boot graph<\/b> là đồ thị thứ tự/phụ thuộc khởi động giữa các thành phần."},{"t":"boot graph","vi":"Đồ thị phụ thuộc khi khởi động: thành phần nào chờ thành phần nào, chạy song song được không, và khi dependency chưa có thì làm gì (retry, placeholder, degraded, fail)."},{"t":"dependency map","vi":"Bản đồ phụ thuộc: liệt kê mỗi node (service, process, VM) phụ thuộc vào ai, qua contract/version nào, owner, timeout/unavailable behavior và tài nguyên dùng chung. Là đầu vào cho failure propagation analysis."},{"t":"boot dependency","vi":"Phụ thuộc khi khởi động: thành phần này chỉ chạy được khi thành phần kia đã sẵn sàng (ví dụ HMI cần parser, parser cần CAN driver). Chuỗi phụ thuộc quyết định thời gian tới “ready” thật.","aka":["boot dependencies"]},{"t":"boot loop","vi":"Vòng lặp khởi động: hệ thống/process khởi động, lỗi, rồi khởi động lại liên tục. Retry vô hạn không backoff có thể gây boot loop và chiếm CPU/bus."},{"t":"dynamic discovery","vi":"Tìm service lúc chạy (offer/find, announce) thay vì địa chỉ cố định: linh hoạt hơn nhưng tạo traffic, phụ thuộc thời gian và cần timeout. Hợp với chức năng không gấp như app IVI, không hợp với cluster cần lên nhanh."},{"t":"static configuration","vi":"Cấu hình tĩnh: địa chỉ/port của producer được ghi cố định trong manifest, không cần tìm lúc chạy. Boot nhanh và xác định, nhưng kém linh hoạt khi thay đổi."},{"t":"offer","vi":"Chào/công bố. Trong service discovery (ví dụ SOME/IP), producer gửi “offer” để báo service của mình đang có; cặp với “find” của consumer."},{"t":"find","vi":"Tìm. Trong service discovery, consumer gửi “find” để hỏi service cần dùng đang ở đâu; producer trả lời bằng offer."},{"t":"announce","vi":"Thông báo/công bố. Trong discovery: producer chủ động phát thông tin rằng service của mình đã sẵn sàng."},{"t":"snapshot","vi":"Ảnh chụp trạng thái tại một thời điểm. Trong bài: dùng snapshot có cùng sample time để các signal ghép với nhau (speed, gear, door) nhất quán về thời gian.","aka":["snapshots"]},{"t":"SpeedSignal","vi":"Tên contract minh họa trong bài cho message tốc độ xe (ví dụ SpeedSignal v2 gồm value, unit, quality, seq, epoch) đi từ parser ở VM-A sang HMI ở VM-B.","cs":true},{"t":"occupancy","vi":"Mức chiếm dụng: bao nhiêu ô của queue/ring buffer đang có dữ liệu. Theo dõi ring/queue occupancy cho biết sắp đầy, đang dồn hàng hay mất dữ liệu."},{"t":"cascading","vi":"Dây chuyền, lan từng tầng. <b>Cascading restart<\/b>: một thành phần restart làm các thành phần phụ thuộc mất kết nối và restart theo."},{"t":"cascading restart","vi":"Restart dây chuyền: watchdog restart A làm B, C mất subscription và restart theo, có thể lan rộng cả hệ. Chặn bằng restart budget, backoff, epoch và quality rõ ràng."},{"t":"lifeline","vi":"Đường sống trong sequence diagram: cột dọc đại diện một thành phần (Body ECU, Gateway, Parser, HMI…), message vẽ thành mũi tên giữa các lifeline theo thời gian.","aka":["lifelines"]},{"t":"sequence diagram","vi":"Sơ đồ tuần tự: thể hiện các message giữa các thành phần theo trục thời gian. Bài yêu cầu sequence diagram xuyên domain có contract/version, timestamp, clock domain, luồng bình thường và luồng lỗi.","aka":["cross-domain sequence diagram"]},{"t":"multiplexing","vi":"Ghép kênh. Trong CAN: một frame mang các signal khác nhau tùy giá trị của một trường chọn (multiplexor); parser phải đọc trường này trước mới biết cách giải mã.","aka":["multiplexed"]},{"t":"endian","vi":"Thứ tự byte của một số nhiều byte: big-endian (byte cao trước) hay little-endian (byte thấp trước). Đọc sai endian cho ra giá trị sai hoàn toàn dù đúng frame ID.","aka":["endianness"]},{"t":"bit position","vi":"Vị trí bit bắt đầu (và độ dài) của một signal trong frame CAN, theo khai báo trong DBC."},{"t":"starting","vi":"Đang khởi động — trạng thái trong vòng đời service, chưa được coi là dữ liệu dùng được."},{"t":"stopping","vi":"Đang dừng — trạng thái trong vòng đời service khi tắt có kiểm soát; consumer phải biết để không chờ hoặc dùng dữ liệu cũ."},{"t":"negotiation","vi":"Thương lượng. <b>Version negotiation<\/b>: khi kết nối, hai bên trao đổi schema/interface version để quyết định dùng compatibility path hay từ chối."},{"t":"compatibility path","vi":"Đường xử lý tương thích: nhánh code cho phép bên mới vẫn làm việc với bên phiên bản cũ (ví dụ chuyển đổi format) khi version hai bên lệch."},{"t":"widget","vi":"Thành phần giao diện nhỏ trên màn hình (ví dụ ô hiển thị tốc độ). Trong bài, HMI speed widget là consumer cuối của signal tốc độ.","aka":["widgets"]},{"t":"chassis","vi":"Khung gầm. <b>Chassis domain<\/b> là miền chức năng phanh, lái, treo… — một trong các domain chức năng mà signal có thể phải vượt ranh giới."},{"t":"backoff","vi":"Lùi lại: sau mỗi lần thử thất bại thì chờ lâu dần (thường kèm jitter ngẫu nhiên) trước khi thử lại, để tránh retry storm và boot loop."},{"t":"position","vi":"Vị trí. Trong bài dùng trong bit position — vị trí bit của signal trong frame."},{"t":"logger","vi":"Thiết bị/phần mềm ghi log. <b>Bus logger<\/b> ghi lại frame trên bus kèm timestamp phần cứng, dùng làm đồng hồ chung để đo latency end-to-end."},{"t":"bus logger","vi":"Thiết bị ghi lưu lượng trên bus (CAN, Ethernet) kèm timestamp chính xác; dùng làm mốc thời gian độc lập để đo và điều tra lỗi."},{"t":"hardware timestamp","vi":"Dấu thời gian do phần cứng (controller/logger) gán ngay khi frame đến, chính xác hơn timestamp phần mềm vốn bị trễ do interrupt và scheduling."},{"t":"IRQ","vi":"Yêu cầu ngắt: tín hiệu phần cứng buộc CPU tạm dừng việc đang làm để xử lý sự kiện. IRQ dồn dập là một nguồn làm task ưu tiên cao miss deadline.","full":"Interrupt Request","cs":true},{"t":"domino","vi":"Quân domino: hình ảnh bài dùng cho lỗi lan truyền — một quân đổ kéo các quân sau; phải biết lỗi lan theo đường nào và đặt “quân chặn” ở đâu."},{"t":"eventual","vi":"Rốt cuộc / sau cùng. Trong bài dùng trong cụm <b>eventual consistency<\/b> — nhất quán sau một khoảng ngắn."},{"t":"eventual consistency","vi":"Nhất quán sau cùng: các bản sao dữ liệu có thể lệch nhau tạm thời nhưng sẽ khớp sau một khoảng ngắn. Chấp nhận được nếu ghi rõ hệ quả và khoảng lệch tối đa."},{"t":"data consistency","vi":"Tính nhất quán dữ liệu: các giá trị được dùng cùng nhau phải thuộc cùng thời điểm/cùng phiên bản. Hai giá trị đúng nhưng lệch thời điểm ghép lại vẫn cho kết luận sai."},{"t":"fail-fast","vi":"Thất bại nhanh: phát hiện lỗi thì báo lỗi ngay thay vì chờ lâu hoặc treo. Trong bài là cách chặn timeout chain — tầng trong timeout ngắn hơn và trả lỗi sớm."},{"t":"timeout chain","vi":"Chuỗi timeout: A chờ B, B chờ C… một chỗ chậm làm cả chuỗi treo. Chặn bằng timeout tầng trong ngắn hơn tầng ngoài, fail-fast và degraded response."},{"t":"degraded response","vi":"Phản hồi suy giảm: khi dependency lỗi, service vẫn trả lời nhưng ở mức kém hơn (giá trị cũ có đánh dấu, “--”, chức năng rút gọn) thay vì treo."},{"t":"struct","vi":"Cấu trúc dữ liệu trong C/C++ (các trường xếp liền trong bộ nhớ). Bài cảnh báo HMI đọc thẳng struct nội bộ của parser trong shared memory: parser đổi layout là HMI đọc sai.","aka":["structs"]},{"t":"mutable","vi":"Có thể thay đổi. “Shared mutable state” là trạng thái dùng chung mà nhiều bên cùng ghi/đọc — khó kiểm soát; bài yêu cầu giao tiếp qua contract có version thay vì vậy."},{"t":"independent","vi":"Độc lập. <b>Independent evolution<\/b>: mỗi tầng/domain tự thay đổi và release mà không buộc tầng khác release theo."},{"t":"independent evolution","vi":"Tiến hóa độc lập: mỗi domain/tầng (runtime, middleware, platform, application) phát triển và release riêng, nhờ chỉ giao tiếp qua contract có version và chính sách tương thích."},{"t":"warm restart","vi":"Khởi động lại “ấm”: một phần hệ thống vẫn chạy, cache có thể còn. Nguy cơ: dùng nhầm giá trị cache cũ như Valid nếu không kiểm epoch."},{"t":"first boot","vi":"Lần khởi động đầu tiên. <b>OTA first boot<\/b>: lần boot đầu sau cập nhật, khi phần mềm và cấu hình mới gặp nhau lần đầu — dễ lộ lỗi tương thích, migration, cache cũ."},{"t":"brownout","vi":"Sụt áp tạm thời (điện áp giảm nhưng không mất hẳn) làm hệ thống reset giữa chừng. Là một kịch bản khởi động bài yêu cầu tính tới."},{"t":"time-to-first-valid","vi":"Thời gian từ power-on đến khi giá trị Valid đầu tiên hiển thị. Chỉ số “ready” đúng nghĩa mà bài đề xuất, đo riêng cho cold, warm và OTA boot."},{"t":"data-centric","vi":"Lấy dữ liệu làm trung tâm: kiểu publish/subscribe theo topic (như DDS), bên nhận đăng ký dữ liệu chứ không gọi service. Cần kiểm QoS và discovery traffic."},{"t":"gRPC-like","vi":"Giống gRPC — framework gọi hàm từ xa (RPC) của Google. Trong bài là kiểu IPC service-oriented: request/response có định nghĩa interface rõ.","aka":["gRPC"],"cs":true},{"t":"Binder","vi":"Cơ chế IPC chính của Android: các process gọi service của nhau qua driver Binder trong kernel.","cs":true},{"t":"AIDL","vi":"Ngôn ngữ định nghĩa interface của Android, dùng sinh code cho các lời gọi qua Binder giữa các process.","full":"Android Interface Definition Language","cs":true},{"t":"inter-VM","vi":"Giữa các máy ảo: giao tiếp vượt ranh giới hypervisor (ví dụ shared memory + doorbell, virtio, vsock). Cần kiểm ownership, permission, timing của cả hai phía.","aka":["Inter-VM"],"cs":true},{"t":"inter-core","vi":"Giữa các lõi xử lý: giao tiếp giữa các core (hoặc giữa SoC và MCU) qua shared memory, mailbox, ngắt."},{"t":"doorbell","vi":"Chuông cửa: cơ chế ngắt báo cho bên kia “có dữ liệu mới” trong shared memory, để không phải polling liên tục."},{"t":"vsock","vi":"Socket ảo cho giao tiếp giữa VM và host/VM khác qua hypervisor, dùng như socket mạng nhưng không cần mạng thật.","full":"virtual socket"},{"t":"mailbox","vi":"Hộp thư phần cứng: khối thanh ghi + ngắt để các lõi/chip (SoC và MCU) gửi thông điệp ngắn cho nhau."},{"t":"clock uncertainty","vi":"Độ bất định của đồng hồ: sai số khi so thời gian giữa hai clock. Khi uncertainty gần bằng margin, phép đo không đủ kết luận đạt/không đạt."},{"t":"clock mapping","vi":"Ánh xạ đồng hồ: cách quy đổi timestamp của clock này sang clock kia (offset, drift) để trừ được thời gian giữa hai domain."},{"t":"monotonic","vi":"Đơn điệu: chỉ tăng, không bao giờ lùi. Dùng trong <b>monotonic clock<\/b>."},{"t":"monotonic clock","vi":"Đồng hồ đơn điệu: chỉ tăng đều, không bị chỉnh lùi như giờ hệ thống. Dùng để đo khoảng thời gian/timeout; trong bài là clock của VM-A cho timestamp."},{"t":"sample time","vi":"Thời điểm lấy mẫu giá trị ở nguồn. Tuổi dữ liệu tính từ sample time theo clock đã khai báo, không phải từ lúc consumer nhận."},{"t":"class","vi":"Lớp/hạng. “Priority/RT class” là lớp lập lịch (ví dụ real-time hay thường) và mức ưu tiên của một thread trong OS."},{"t":"time partition","vi":"Phân vùng thời gian: hypervisor/OS chia khung thời gian CPU cố định cho từng VM/partition, để domain này không lấn thời gian của domain kia.","aka":["time partitioning"]},{"t":"scheduling interference","vi":"Nhiễu do lập lịch: task/VM khác chiếm CPU, cache, bus làm task của mình chạy chậm hơn dự kiến. Là nguồn chính khiến latency xuyên domain khó đoán."},{"t":"Adaptive","vi":"Ở đây là AUTOSAR Adaptive Platform — nền tảng AUTOSAR cho máy tính hiệu năng cao chạy POSIX, giao tiếp service-oriented; đối lập với AUTOSAR Classic cho ECU nhỏ.","cs":true},{"t":"seq","vi":"Viết tắt của sequence number: số thứ tự tăng dần của message, giúp consumer phát hiện mất, trùng hoặc sai thứ tự.","full":"sequence number","cs":true},{"t":"ts","vi":"Viết tắt timestamp trong sơ đồ: dấu thời gian gán cho frame/message.","full":"timestamp","cs":true},{"t":"shm","vi":"Viết tắt của shared memory: vùng nhớ dùng chung giữa process/VM để trao đổi dữ liệu lớn ít copy.","full":"shared memory"},{"t":"at-most-once","vi":"Giao nhiều nhất một lần: message không bao giờ trùng nhưng có thể mất. Một kiểu delivery semantics."},{"t":"at-least-once","vi":"Giao ít nhất một lần: không mất nhưng có thể trùng (do gửi lại), nên consumer phải idempotent hoặc lọc trùng."},{"t":"delivery semantics","vi":"Cam kết giao nhận của một kênh/event: at-most-once, at-least-once, có thứ tự hay không, cần ack hay không. Bài yêu cầu ghi rõ cho từng event.","aka":["event delivery semantics"]},{"t":"idempotent","vi":"Lũy đẳng: xử lý một message hai lần cho kết quả như một lần. Bắt buộc với consumer khi kênh là at-least-once."},{"t":"ack","vi":"Xác nhận đã nhận: bên nhận báo lại cho bên gửi. Event quan trọng cần ack để bên gửi biết có phải gửi lại không.","aka":["acks"],"full":"acknowledgement"},{"t":"opened","vi":"Đã mở. Ví dụ event “door opened” (sự kiện cửa vừa mở) — mất là mất, khác với state “door = open” có thể đọc lại."},{"t":"event flow","vi":"Dòng sự kiện: cách các event đi qua hệ thống — có thể mất, trùng hay sai thứ tự không, và delivery semantics là gì."},{"t":"vehicle mode","vi":"Chế độ xe (ví dụ đỗ, lái, sạc, vận chuyển): state dùng chung giữa nhiều domain, cần một nguồn gốc duy nhất."},{"t":"single source of truth","vi":"Nguồn sự thật duy nhất: một nơi giữ bản gốc của state, các nơi khác chỉ là bản sao và resync từ đó sau restart."},{"t":"resync","vi":"Đồng bộ lại: sau restart, bản sao state lấy lại giá trị từ nguồn gốc duy nhất để không lệch nhau."},{"t":"consumer-driven","vi":"Do bên tiêu thụ dẫn dắt: yêu cầu xuất phát từ những gì consumer thực sự cần."},{"t":"decoded","vi":"Đã giải mã: giá trị parser đã biến từ byte thô thành con số có đơn vị. Đặt decoded field cạnh raw frame để tìm chỗ sai."},{"t":"bus-off","vi":"Trạng thái node CAN tự ngắt khỏi bus do đếm lỗi vượt ngưỡng; node không gửi/nhận được nữa. Trong bài là luồng lỗi mẫu dẫn tới timeout → Stale → “--”."},{"t":"show","vi":"Hiển thị. Trong sơ đồ: “show --” là HMI hiện dấu “--” khi dữ liệu Stale."},{"t":"cycle time","vi":"Chu kỳ gửi của một signal/frame (ví dụ mỗi 10 ms). Consumer dựa vào cycle time để đặt timeout và phát hiện mất frame."},{"t":"cycle","vi":"Chu kỳ: khoảng lặp lại đều đặn của một việc (gửi frame, chạy task).","aka":["cycles"]},{"t":"full policy","vi":"Chính sách khi đầy: ring buffer/queue đầy thì làm gì — drop-oldest, drop-newest hay backpressure. Chọn theo semantics của dữ liệu."},{"t":"fresh","vi":"Còn mới: dữ liệu chưa quá tuổi tối đa tính từ sample time. Frame đến muộn không tự trở thành fresh chỉ vì parser vừa nhận."},{"t":"payload","vi":"Phần dữ liệu thực mang trong message/frame (không tính header). Payload lớn hợp shared memory; nhỏ hợp message passing.","aka":["payloads"]},{"t":"worked","vi":"Đã giải sẵn. “Worked trace / worked example” là ví dụ được làm mẫu từng bước để người học theo."},{"t":"deprecation policy","vi":"Chính sách loại bỏ dần: producer mới vẫn phục vụ consumer cũ trong thời gian đã hứa, báo trước rồi mới bỏ interface cũ."},{"t":"authority boundary","vi":"Ranh giới quyền hạn: giữa các bên có quyền khác nhau (ví dụ app bên thứ ba và dịch vụ xe). Một trong bốn loại ranh giới mà dữ liệu đi qua."},{"t":"hop","vi":"Chặng: một bước dữ liệu đi qua giữa hai thành phần (ví dụ Gateway → Parser). Bài yêu cầu mỗi hop có owner, schema, version, clock, timeout, permission, evidence.","aka":["hops"]},{"t":"p99","vi":"Phân vị 99: 99% số lần đo nhỏ hơn giá trị này. Bài dùng p99/max thay cho trung bình để thấy lần chậm nhất."},{"t":"queue delay","vi":"Thời gian dữ liệu nằm chờ trong hàng đợi trước khi được xử lý — một phần của latency, tăng mạnh khi có burst."},{"t":"end-to-end latency","vi":"Độ trễ đầu-cuối: từ lúc giá trị được đo ở nguồn đến khi lên màn hình. Phải đo cùng clock, ở tải xấu nhất, không cộng trung bình từng chặng."},{"t":"worst-case latency","vi":"Độ trễ trong trường hợp xấu nhất — cận trên của latency, cần cho yêu cầu an toàn/real-time; không suy ra được từ bitrate hay trung bình."},{"t":"abc","vi":"Chuỗi giả thay cho mã commit (hash) trong ví dụ. Trong bài: “Build ID 1234 = commit abc + toolchain X + lock file Y” — mỗi bản build phải truy được về đúng commit, toolchain và dependency đã dùng.","cs":true},{"t":"ablation","vi":"Thử nghiệm <b>cắt bỏ<\/b>: tắt lần lượt từng thành phần để xem kết quả thay đổi ra sao. Trong khóa AI: tắt/bật từng mảnh context (system prompt, skill, tool…) bằng công tắc để đo đóng góp thật của mỗi mảnh, thay vì đoán.","aka":["ablation study","ablations","lab ablation"]},{"t":"academy","vi":"Học viện, trung tâm đào tạo. Trong lịch học: “BSI Training Academy” là đơn vị biên soạn khóa Automotive Cybersecurity with ISO/SAE 21434 trên Coursera.","aka":["Training Academy"]},{"t":"across","vi":"Xuyên qua, trải khắp. Trong learning outcome: “frame an ambiguous architecture problem across multiple domains or teams” — xác định bài toán kiến trúc trải qua nhiều miền/nhóm."},{"t":"Act","vi":"Đạo luật. Trong glossary khóa AI: Personal Information Protection Act (luật bảo vệ thông tin cá nhân, như PIPA Hàn Quốc), EU AI Act — các luật chi phối việc đưa dữ liệu vào AI và nghĩa vụ minh bạch.","aka":["Acts"],"cs":true},{"t":"EU AI Act","vi":"Đạo luật Trí tuệ nhân tạo của Liên minh châu Âu, phân loại hệ thống AI theo mức rủi ro và đặt nghĩa vụ (ví dụ minh bạch khi dùng AI). Trong glossary D8: nguồn tra cứu khi xác định ranh giới tuyên bố (claims boundary) với khách hàng.","cs":true},{"t":"active-tool-discovery","vi":"Tên lab/kỹ thuật: để agent <b>tự tìm tool<\/b> khi cần thay vì nạp sẵn toàn bộ schema của mọi tool vào context. Giảm tool bloat và tiết kiệm token (D3).","aka":["active tool discovery"]},{"t":"active-tool-selection","vi":"Tên lab D3: luyện thiết kế tool để agent <b>chọn đúng tool<\/b> — tên trực quan, tham số có ví dụ, lỗi trả về có cấu trúc — và thấy độ chính xác chọn tool giảm khi gắn quá nhiều tool.","aka":["active tool selection"]},{"t":"activity","vi":"Hoạt động, mức độ bận rộn. Trong khóa thường đi trong cụm <b>activity metric<\/b> — đo “làm nhiều” chứ không đo “làm được gì”; dễ nhầm với impact."},{"t":"activity metric","vi":"Chỉ số <b>hoạt động<\/b>: số prompt, số token, số người mở tool, số dòng code AI sinh… Cho biết AI được dùng nhiều, không chứng minh giá trị. Khóa yêu cầu chứng minh impact bằng <b>outcome metric<\/b> (giờ thật, lỗi lọt giảm).","aka":["activity metrics"]},{"t":"adding","vi":"Thêm vào (dạng V-ing của add). Trong lịch học D4: “extend a coding agent by adding one CDC-domain tool” — mở rộng coding agent bằng cách thêm một tool thuộc miền CDC."},{"t":"additive","vi":"Có tính <b>cộng thêm<\/b>. Trong khóa: claude.md chỉ <i>thêm thông tin<\/i> vào context (gợi ý, agent thường tuân theo nhưng không bắt buộc), khác với permission/managed settings là ràng buộc cứng."},{"t":"adoption","vi":"Sự áp dụng, đưa vào dùng. Trong syllabus: “adoption recommendations” (khuyến nghị áp dụng công nghệ/kiến trúc) và đo hiệu quả “before and after AI adoption” — trước và sau khi đưa AI vào quy trình."},{"t":"ADR-002","vi":"Mã của một ADR (Architecture Decision Record) minh họa, đánh số tuần tự ADR-001, ADR-002… Mỗi ADR ghi một quyết định kiến trúc, phương án, tiêu chí và trạng thái để người khác tự kiểm lại.","cs":true},{"t":"advancement","vi":"Sự thăng tiến. Trong mục tiêu khóa: chuẩn bị cho kỹ sư senior “advancement to the next job rank” — lên bậc nghề nghiệp tiếp theo (hướng tới vai trò SA)."},{"t":"agency","vi":"Ủy nhiệm — một trong ba chế độ cộng tác với AI (Automation, Augmentation, Agency): AI hành động thay bạn trong phạm vi được giao, tự chạy nhiều bước. Đòi hỏi ranh giới, quyền và cơ chế kiểm chứng rõ nhất."},{"t":"Agent-Computer Interface","vi":"Giao diện giữa agent và máy tính: cách tool, lệnh, đầu ra được thiết kế để <b>agent<\/b> (không phải người) hiểu và dùng đúng. Tương tự UX cho người dùng, ACI tốt giúp agent ít chọn nhầm tool, ít gọi sai tham số.","aka":["agent-computer"]},{"t":"ACI","vi":"Giao diện agent–máy tính: thiết kế tool, tham số, thông báo lỗi sao cho agent đọc hiểu và không dùng sai. Trong khóa là nền tảng của bậc “Xây ACI” và nguyên tắc Clear Interface.","full":"Agent-Computer Interface","cs":true},{"t":"agent-cost-analysis","vi":"Tên lab D6: ghi lại từng bước của một lần chạy agent để <b>bóc chi phí và độ trễ theo bước<\/b> (token, thời gian), từ đó biết bước nào đắt và có đáng tối ưu không."},{"t":"Agent Skills","vi":"Tri thức miền (quy trình, quy ước, ví dụ) được <b>đóng gói<\/b> thành thư mục skill để agent nạp theo nhu cầu, theo kiểu bộc lộ tiệm tiến: mục lục mỏng ở gốc, chi tiết nạp khi task cần. Là chủ đề D2 và tên lab labs/agent-skills.","aka":["agent-skills","agent skill"]},{"t":"agent-skills-ppt","vi":"Tên lab D2 (labs/agent-skills-ppt): đóng gói tri thức miền thành skill nhiều file có cấu trúc nạp được, minh họa bằng việc sinh tài liệu trình chiếu theo quy ước."},{"t":"agentic","vi":"Mang tính agent — AI tự quyết và tự hành động qua nhiều bước (gọi tool, đọc kết quả, lặp lại) thay vì chỉ trả lời một lượt. Thường đi trong cụm agentic loop, agentic system, agentic design pattern."},{"t":"agentic loop","vi":"Vòng lặp lõi của agent: gọi model → gọi tool → quan sát kết quả → lặp lại đến khi xong. Hiểu vòng lặp này để biết chỗ nào chèn context, rule, skill, hook hay điểm duyệt."},{"t":"Agentic System","vi":"Hệ thống xây quanh agent AI: model + tool + context + ràng buộc + kiểm chứng, vận hành nhiều bước có kiểm soát. Khóa dạy các nguyên lý đã kiểm chứng để thiết kế hệ như vậy cho dự án thật.","aka":["agentic systems"]},{"t":"Agentic Design Pattern","vi":"Các mẫu thiết kế cho hệ agent: prompt chaining, routing, reflection, planning, multi-agent, parallelization, RAG, A2A… Trong khóa là phần nâng cao sau tốt nghiệp.","aka":["Agentic Design Patterns"]},{"t":"AgentOps","vi":"Vận hành hệ agent (giống DevOps/MLOps cho agent): theo dõi chi phí, chất lượng, lỗi, độ trễ của agent khi chạy thật. Thiếu AgentOps là một “điểm mù” trong đánh giá CASAN, được xử lý ở D6–D7."},{"t":"AI-01","vi":"Mã unit của khóa AI Transformation (AI-01 → AI-12, Unit D.1–D.12): AI-01/02/03 = Bài 0A/0B/0C (khái niệm nền, cộng tác AI, Claude Code cơ bản); AI-04…AI-12 = buổi D0…D8 (AI-06 Context &amp; Skills, AI-07 Rules into Code, AI-08 Coding Agent, AI-09 Kiến trúc, AI-11 Đo lường giá trị).","aka":["AI-02","AI-03","AI-06","AI-07","AI-08","AI-09","AI-11"],"cs":true},{"t":"AI-assisted","vi":"Có AI <b>hỗ trợ<\/b> — người vẫn làm chủ và chịu trách nhiệm, AI giúp một phần. “AI-assisted engineering” là năng lực cốt lõi của khóa: dùng AI có quản trị (ranh giới dữ liệu, ủy quyền, kiểm chứng) và có evidence phần AI làm/phần mình sửa.","aka":["AI-assisted engineering","governed AI-assisted engineering"]},{"t":"AI-enabled","vi":"Được AI hỗ trợ/vận hành nhờ AI. Trong LO6: “AI-enabled engineering” — quy trình kỹ thuật có AI tham gia, cần quy trình kiểm chứng, đo lường và triển khai dưới governance."},{"t":"AI-native","vi":"“Thuần AI” — quy trình được thiết kế từ đầu quanh AI. Trong thang CASAN là Cấp 5: AI là lõi vận hành toàn vòng đời ở quy mô tổ chức; khóa chỉ nhắm cấp 3–4 vì kiểm chứng và trách nhiệm."},{"t":"aligned","vi":"Phù hợp, khớp với. Trong OJT: “CDC topic aligned to target rank” — đề tài phải đúng mảng CDC và có độ khó tương xứng bậc mục tiêu, được duyệt trước khi làm.","aka":["aligned to","aligned with"]},{"t":"allow","vi":"Cho phép. Trong Claude Code là một trong ba mức permission <b>allow/ask/deny<\/b>: hành động ở mức allow chạy không hỏi — dành cho lệnh đọc/kiểm an toàn, chạy thường xuyên (pytest, git status)."},{"t":"allowManagedHooksOnly","vi":"Thiết lập trong managed policy settings của Claude Code: chỉ cho chạy các hook do quản trị tổ chức cấp, chặn hook cá nhân tự thêm. Giúp áp ranh giới cho hàng trăm người mà không dựa vào tự giác."},{"t":"Anthropic","vi":"Công ty AI phát triển các model Claude và công cụ Claude Code. Trong khóa: nguồn của khung 4D (Delegation…) mà tam phân Máy/Agent/Người của chương trình mở rộng thêm."},{"t":"AOSP","vi":"Mã nguồn mở của Android do Google công bố. Trong phân loại dữ liệu khóa AI: tài liệu AOSP là dữ liệu công khai (mức M1/Public), được dùng tự do với công cụ AI.","full":"Android Open Source Project","cs":true},{"t":"api","vi":"Giao diện lập trình (viết thường của API): điểm để chương trình/agent gọi chức năng của hệ khác. Trong khóa: agent gọi api như một hành động; “không đổi api công khai” là ràng buộc hay gặp khi giao task.","full":"Application Programming Interface","cs":true},{"t":"AppG","vi":"Viết tắt “Appendix G” — phụ lục G của tài liệu đọc chính, được trích theo trang (tr.404-409) trong glossary khóa AI làm nguồn đọc cho khái niệm vòng lặp agent.","cs":true},{"t":"apply","vi":"Áp dụng. Trong syllabus là động từ của learning outcome (mức Bloom “Apply”, B3) và trong câu “colleagues can apply successfully” — đồng nghiệp dùng lại được artifact thành công."},{"t":"approach","vi":"Cách tiếp cận, phương án. Trong bài: so sánh các Pattern/Approach theo tiêu chí; “validation approaches” — cách kiểm chứng giải pháp.","aka":["approaches"]},{"t":"appropriately","vi":"Một cách phù hợp, đúng mức. Trong syllabus: “escalating cross-domain decisions appropriately” — đẩy quyết định liên miền lên đúng người, đúng lúc."},{"t":"architectural","vi":"Thuộc về kiến trúc. “Architectural decisions” = các quyết định kiến trúc mà học viên phải bảo vệ và biện minh trước SA/BUL (LO7)."},{"t":"ask","vi":"Hỏi. Trong Claude Code là mức permission <b>ask<\/b>: agent phải xin người duyệt trước khi chạy — dành cho hành động đổi trạng thái nhưng đảo ngược được (git commit, git checkout)."},{"t":"ASR","vi":"Tỷ lệ tấn công thành công: phần trăm lần tấn công (vd. prompt injection) đạt mục tiêu. Là chỉ số lab injection báo cáo để so trước/sau khi thêm lớp phòng vệ.","aka":["asr"],"full":"Attack Success Rate","cs":true},{"t":"attack success rate","vi":"Tỷ lệ lần tấn công đạt được mục tiêu (viết tắt ASR). Dùng để đo độ chống chịu của agent trước prompt injection: phòng vệ tốt thì ASR giảm."},{"t":"assert","vi":"Câu lệnh khẳng định trong test: nếu điều kiện sai thì test fail. Trong khóa: agent đề xuất <b>xóa assert<\/b> để test “xanh” là dấu hiệu phải dừng và báo người.","aka":["asserts","assertion"]},{"t":"assign","vi":"Giao, phân công. Trong lịch học Bài 0B: “decompose work, assign responsibilities and verify AI outputs” — chia việc, phân trách nhiệm giữa người và AI, rồi kiểm chứng đầu ra."},{"t":"Assignment1","vi":"Assignment 1 — bài tập lớn thứ nhất (Unit A.8): Architecture Context &amp; Foundation, phân tích bối cảnh, ràng buộc, rủi ro kiến trúc của một chủ đề CDC.","aka":["Assignment 1"]},{"t":"attendance","vi":"Sự tham dự, điểm danh. Điều kiện qua khóa: <b>attendance ≥ 80%<\/b> các buổi (kèm GPA ≥ 7/10); với review/OJT là tham gia ít nhất 80% buổi review."},{"t":"audience","vi":"Đối tượng, người nghe. Trong syllabus: “Target Training Audience” — đối tượng học viên của khóa (vị trí, bậc nghề nghiệp)."},{"t":"augmentation","vi":"Tăng cường — chế độ cộng tác trong đó bạn và AI cùng làm, trao đổi qua lại (khác Automation: AI làm trọn việc rõ ràng; Agency: AI tự hành động thay bạn). Hợp với việc cần phán đoán: viết quan trọng, thiết kế."},{"t":"augmented","vi":"Được tăng cường. Trong thang CASAN là Cấp 2 “Augmented”: AI tăng cường việc cá nhân/một nhóm. Cũng gặp trong RAG (Retrieval Augmented Generation) — sinh câu trả lời có bổ sung thông tin truy xuất."},{"t":"authoritative","vi":"Có thẩm quyền, đáng tin cậy làm chuẩn. Trong syllabus: “authoritative architecture sharing” — chia sẻ kiến trúc đủ uy tín để định hướng kỹ thuật cho dự án/đơn vị."},{"t":"AutoGen","vi":"Framework mã nguồn mở của Microsoft để xây hệ nhiều agent hội thoại với nhau. Được nhắc như một lựa chọn bên cạnh LangGraph, CrewAI, Google ADK; khóa dùng Claude Code để thực hành."},{"t":"ADK","vi":"Google ADK: bộ công cụ của Google để xây agent và hệ nhiều agent. Trong khóa chỉ được liệt kê như một framework tham khảo.","full":"Agent Development Kit","cs":true},{"t":"automotive's","vi":"Sở hữu cách của “automotive” — “của ngành ô tô”. Trong syllabus: “automotive's CDC systems” — các hệ CDC của ngành ô tô."},{"t":"autonomous","vi":"Tự chủ, tự quyết. Trong khóa đối lập với <b>workflow<\/b>: workflow = luồng bước định sẵn, dễ kiểm soát; autonomous = giao mục tiêu, agent tự chọn các bước. Chọn autonomous chỉ khi cần và đủ kiểm chứng."},{"t":"AutoSAR","vi":"Cách viết khác của AUTOSAR (trong tên khóa Coursera “Introduction to AutoSAR”): chuẩn kiến trúc phần mềm ECU ô tô với các lớp, interface và công cụ cấu hình chuẩn hóa.","full":"AUTomotive Open System ARchitecture","cs":true},{"t":"balance","vi":"Sự cân bằng. Trong syllabus: “Current–Future Balance” — tỷ lệ thời gian học cho nhu cầu hiện tại (70%) và nhu cầu tương lai (30%)."},{"t":"bare","vi":"Trần, không có gì thêm. “Bare model” trong lab ablation: model chạy khi đã tắt hết context/skill/tool phụ — làm <b>mốc ban đầu<\/b> để đo mỗi thành phần đóng góp bao nhiêu.","aka":["bare model"]},{"t":"based","vi":"Dựa trên, căn cứ vào. Trong syllabus: “compare architecture alternatives based on complexity, risk, cost…” — so sánh phương án kiến trúc dựa trên độ phức tạp, rủi ro, chi phí, chất lượng.","aka":["based on"]},{"t":"baselining","vi":"Việc chốt baseline (mốc chuẩn). “Requirement baselining” = đóng băng một bộ yêu cầu đã duyệt làm mốc; sau đó mọi thay đổi phải qua kiểm soát thay đổi."},{"t":"Bash","vi":"Shell dòng lệnh phổ biến trên Linux/macOS. Trong khóa: điều kiện đầu vào là viết được script Bash/Python; coding agent dùng tool “chạy bash” để thực thi lệnh — nhóm rủi ro Thực thi."},{"t":"before","vi":"Trước, trước mặt. Trong syllabus: “defend it before the SA/BUL” — bảo vệ trước hội đồng SA/BUL; “before and after AI adoption” — trước và sau khi áp dụng AI."},{"t":"beginner","vi":"Người mới bắt đầu; mức độ khóa học cơ bản. Trong lịch học là nhãn độ khó của khóa Coursera (vd. Overview of Automotive SPICE, beginner)."},{"t":"best-effort","vi":"“Cố gắng hết mức nhưng không bảo đảm”. Trong khóa: <b>hook là best-effort<\/b>, không phải security boundary tuyệt đối; ranh giới thật sự là permission/managed settings."},{"t":"bidirectional","vi":"Hai chiều. Thường gặp trong <b>bidirectional traceability<\/b> — truy vết được cả xuôi (yêu cầu → thiết kế → test) lẫn ngược (test → yêu cầu)."},{"t":"bidirectional traceability","vi":"Truy vết hai chiều giữa yêu cầu, thiết kế, code và test: từ yêu cầu tìm được test, từ test tìm ngược về yêu cầu. Là yêu cầu của Automotive SPICE; trong khóa AI áp cho cả artifact do agent sinh."},{"t":"bloat","vi":"Phình to quá mức. “Tool bloat” = gắn quá nhiều tool cho agent khiến nó khó chọn đúng và tốn context; nguyên tắc là ít tool nhưng thiết kế tốt.","aka":["tool bloat"]},{"t":"blocker","vi":"Vấn đề đang chặn tiến độ, phải gỡ mới làm tiếp được. Trong buổi review: mentee nêu ngắn tiến độ và các blocker để mentor/SA hỗ trợ.","aka":["blockers"]},{"t":"Bloom","vi":"Thang Bloom phân cấp mức nhận thức của mục tiêu học tập (Nhớ, Hiểu, Áp dụng, Phân tích, Đánh giá, Sáng tạo). Trong syllabus mỗi LO có Bloom Level, vd. B3 Apply, B4 Analyze, B5 Evaluate.","aka":["Bloom Level","Bloom's taxonomy"]},{"t":"book","vi":"Sách, sổ. Trong khóa AI chủ yếu là <b>Dev Book<\/b> (nhật ký review output AI); cũng gặp trong tên sách tham khảo (Google SRE Book) và lab book-translation.","aka":["books"]},{"t":"Dev Book","vi":"Nhật ký phát triển (BT-8): ghi mỗi lần agent làm sai, bạn phát hiện và sửa thế nào, mảnh context nào có giá trị. Dùng để trả lời vấn đáp tốt nghiệp “chỗ nào AI sai và bạn sửa thế nào”; Dev Book trống = trượt."},{"t":"book-translation","vi":"Tên lab D5 (dịch sách): so sánh đơn agent với mô hình manager–worker nhiều agent bằng <b>token thật<\/b>, áp tiêu chí information gain trước khi quyết định tách agent."},{"t":"brainstorm","vi":"Động não, nghĩ ra nhiều ý tưởng. Trong khóa là việc hợp giao cho AI (agent): brainstorm ca biên, ca kiểm thử, phương án — tính ngẫu nhiên của model thành ưu điểm.","aka":["brainstorming"]},{"t":"briefing","vi":"Giao việc kèm bối cảnh, bản tóm lược nhiệm vụ. Trong khóa: cách briefing AI theo khung <b>C-T-R<\/b> (Context, Task, Rules) để AI hiểu đúng việc."},{"t":"BSI","vi":"Viện Tiêu chuẩn Anh — tổ chức tiêu chuẩn và đào tạo. Trong lịch học: BSI Training Academy biên soạn khóa Automotive Cybersecurity with ISO/SAE 21434 trên Coursera.","full":"British Standards Institution","cs":true},{"t":"BT-0","vi":"Mã bài tập (BT) khóa AI: BT-0 baseline đo thời gian hiện tại; BT-1 tam phân một quy trình; BT-2 task thật + danh sách lỗi; BT-3 một quy tắc thành code; BT-4 project workflow; BT-5 bộ đánh giá phân tầng; BT-6 tìm chỗ sai; BT-7 kế hoạch triển khai; BT-8 Dev Book.","aka":["BT-1","BT-2","BT-3","BT-4","BT-5","BT-6","BT-7","BT-8"],"cs":true},{"t":"bug-to-fix","vi":"Khoảng thời gian từ khi phát hiện bug tới khi xác nhận bản sửa. Trong bài Digital Engineering: đo bug-to-fix trước/sau khi chuyển vòng lặp sang môi trường virtual để thuyết phục đầu tư.","aka":["bug-to-fix confirmation"]},{"t":"BUL","vi":"Lãnh đạo đơn vị kinh doanh (BU). Trong khóa: học viên bảo vệ quyết định kiến trúc và kết quả OJT “trước SA/BUL” — hội đồng gồm Solution Architect và lãnh đạo BU.","full":"Business Unit Leader","cs":true},{"t":"bullet","vi":"Gạch đầu dòng. Trong C-T-R, phần Rules có thể quy định định dạng đầu ra của AI: dạng bullet, bảng, độ dài.","aka":["bullets","bullet point"]},{"t":"C-T-R","vi":"Khung briefing tối thiểu khi giao việc cho AI: <b>Context<\/b> (bối cảnh), <b>Task<\/b> (việc cụ thể, động từ rõ), <b>Rules<\/b> (ràng buộc: định dạng, phạm vi, điều cấm). Việc quan trọng cần thêm tiêu chí chấp nhận.","full":"Context – Task – Rules","cs":true},{"t":"calibration.py","vi":"Script lab D6: đo mức đồng thuận của LLM judge với nhãn do người chấm, trước khi tin dùng judge để chấm tự động."},{"t":"can-mapping","vi":"Tên skill minh họa (ánh xạ tín hiệu CAN). Ví dụ trong câu hỏi ôn: đổi skill can-mapping lên v1.4 và đổi model cùng tuần thì phải chạy eval từng tổ hợp mới biết lỗi do đâu."},{"t":"capstone","vi":"Dự án/bài tổng kết cuối khóa, gom các kỹ năng đã học. Trong syllabus: “capstone scenario package” — bộ tình huống dùng cho bài tổng kết."},{"t":"cash-flow impact","vi":"Tác động lên dòng tiền: tiền chi ra/thu vào theo thời gian. Trong bài: đầu tư phòng ngừa lỗi phải chi trước, lợi ích về sau; lỗi phát hiện muộn làm trễ doanh thu và kéo theo chi phí lớn.","aka":["cash-flow"]},{"t":"category","vi":"Loại, hạng mục. Trong bảng giả định/rủi ro của Assignment 1: mỗi giả định ghi category (loại), hậu quả nếu sai, likelihood và cách xác minh.","aka":["categories"]},{"t":"CDC-domain","vi":"Thuộc miền CDC (Cockpit Domain Controller). Trong lịch D4: thêm “one CDC-domain tool” — một tool chuyên cho nghiệp vụ CDC (vd. kiểm VHAL, ánh xạ CAN) vào coding agent."},{"t":"Celsius","vi":"Độ C — đơn vị nhiệt độ. Ví dụ lỗi L1 trong khóa: spec lưu nhiệt độ là Celsius×10 nhưng code đọc như Celsius, giá trị lệch 10 lần mà vẫn qua range check."},{"t":"CGI","vi":"Hình ảnh/đồ họa do máy tính dựng (vd. mô hình xe 3D, hoạt ảnh trên cluster). Trong mục tối ưu thời gian khởi động: một phụ thuộc cần nạp (cùng IDC, H.264, SOME-IP) phải xem xét thứ tự.","full":"Computer-Generated Imagery","cs":true},{"t":"ch","vi":"Viết tắt “chapter” — chương sách. Trong glossary khóa AI dùng để trỏ nguồn đọc, vd. “ch.3” = chương 3, “Ch8” = chương 8 của tài liệu đọc.","aka":["ch.1","ch.3","Ch5","Ch8"]},{"t":"chain-of-thought","vi":"Chuỗi suy luận: model suy nghĩ từng bước trước khi trả lời. Trong khóa: cho agent thêm bước/thời gian suy luận tường minh giúp cải thiện chất lượng ở việc phức tạp, đổi lại tốn token và thời gian."},{"t":"chaining","vi":"Nối chuỗi. <b>Prompt chaining<\/b>: chia việc thành các bước tuần tự, output bước trước là input bước sau, có thể kiểm giữa các bước. Bậc đơn giản thứ hai trong thang kiến trúc agent (sau một agent).","aka":["prompt chaining"]},{"t":"chapter","vi":"Chương, phần. Trong lịch học: cột “Training Unit/Chapter” — đơn vị/chương của chương trình đào tạo."},{"t":"chatbot","vi":"Phần mềm trò chuyện, trả lời từng lượt hỏi. Trong khóa phân biệt với agent: chatbot chỉ trả lời, agent hành động thật (sửa file, chạy test); dùng chatbot cho quy trình cũ mà không thiết kế lại là một điểm yếu CASAN.","aka":["chatbots"]},{"t":"checker","vi":"Bộ kiểm tra tự động (code kiểm một quy tắc). Trong khóa: checker phải có cách xử lý xác định cho mọi ca (biên, thiếu field); phần chưa chốt ngưỡng thì chưa viết checker, không để AI tự chọn số.","aka":["checkers"]},{"t":"checkout","vi":"Lệnh git chuyển nhánh hoặc khôi phục file. Trong bảng permission: git checkout đổi trạng thái nhưng đảo ngược được nên đặt mức <b>ask<\/b>.","aka":["git checkout"]},{"t":"chime-start","vi":"Thời điểm bắt đầu phát chuông/âm báo. Trong bài audio: so call-end/chime-start (kết thúc cuộc gọi và bắt đầu chime) ở các điều kiện amp warm/cold, CPU load, low voltage để bắt race condition."},{"t":"classify","vi":"Phân loại. Trong D0: “Classify project data” — phân loại dữ liệu dự án theo mức nhạy cảm để quyết định AI được truy cập, xử lý hay không được nhận."},{"t":"Claude","vi":"Họ model AI của Anthropic, dùng làm trợ lý chat và nền của Claude Code. Trong khóa: công cụ AI chính để cộng tác (Projects, Artifacts) và chạy agent; gõ lệnh claude trong terminal để mở một phiên."},{"t":"Claude Code","vi":"Công cụ agent lập trình của Anthropic chạy trong terminal: đọc repo, sửa file, chạy lệnh/test ngay trong dự án. Là công cụ thực hành chính của khóa (Bài 0C, BT-3/BT-4), có claude.md, permission, hook, managed settings."},{"t":"CLAUDE.md","vi":"File hướng dẫn cho dự án mà Claude Code tự nạp mỗi phiên: quy ước, điều cấm, bản đồ thuật ngữ/module. Chỉ là <b>gợi ý<\/b> (additive); ràng buộc cứng phải đặt ở permission/managed settings. Phải cập nhật cùng PR khi dự án đổi."},{"t":"CLI","vi":"Giao diện dòng lệnh: thao tác bằng lệnh gõ trong terminal. Điều kiện đầu vào khóa AI: dùng Git và CLI thành thạo, vì Claude Code chạy trong terminal.","full":"Command-Line Interface","cs":true},{"t":"client-server","vi":"Mô hình khách–chủ: client gửi yêu cầu, server phục vụ. Trong khóa: MCP theo mô hình client-server (một server dùng lại cho nhiều agent), khác function calling gắn 1-1 với một ứng dụng."},{"t":"climate","vi":"Khí hậu; trên xe là hệ điều hòa (climate control, HVAC). Ví dụ trong khóa: module hvac/ đổi tên thành climate/ mà CLAUDE.md chưa sửa → agent tìm vào thư mục không còn tồn tại."},{"t":"coach","vi":"Người hướng dẫn, huấn luyện. Trong khóa AI: Coach hỏi vấn đáp “vì sao?” ở buổi bảo vệ D8; học viên tốt nghiệp có thể làm vai trò Coach cho khóa sau.","aka":["coaches"]},{"t":"coaching","vi":"Việc kèm cặp, huấn luyện người khác. Trong mô tả bậc nghề nghiệp: hướng dẫn kỹ thuật và coaching đồng nghiệp dưới sự chỉ đạo của SA/technical lead."},{"t":"coding-agent","vi":"Agent chuyên viết/sửa code (như Claude Code): dùng vài tool tổng quát (đọc, ghi file, chạy bash) và ghép linh hoạt. Lab D4 coding-agent mổ xẻ vòng lặp chính và định nghĩa tool để mở rộng, không coi nó là hộp đen.","aka":["coding agent","coding agents"]},{"t":"coherent","vi":"Mạch lạc, nhất quán. Trong Assignment 3: “Present a coherent architecture view” — trình bày góc nhìn kiến trúc thống nhất, các phần ăn khớp với nhau."},{"t":"colleagues","vi":"Đồng nghiệp. Trong D2: artifact context/skill phải đủ tốt để <b>đồng nghiệp dùng lại thành công<\/b> — mốc kiểm chứng tuần 5.","aka":["colleague"]},{"t":"comfort","vi":"Tiện nghi. Trong phân loại mức quan trọng chức năng xe: comfort (tiện nghi, vd. ghế, điều hòa) xếp dưới safety-related và mission-critical, trên/ngang entertainment."},{"t":"commitment","vi":"Cam kết. “Training Commitment” là bản cam kết đào tạo học viên ký khi bắt đầu khóa (tuần W1).","aka":["Training Commitment"]},{"t":"communicate","vi":"Truyền đạt, trao đổi. Trong yêu cầu assignment: “Communicate findings with evidence” — trình bày kết quả kèm bằng chứng và trả lời câu hỏi review."},{"t":"compact","vi":"Nén gọn. Trong Claude Code: khi phiên chạm trần context, công cụ tự <b>compact<\/b> — tóm tắt phần cũ, chi tiết bị mất là chi tiết bạn không chọn; nên chủ động ghi điều quan trọng vào file."},{"t":"compression","vi":"Nén. <b>Context compression<\/b>: giảm kích thước context mà vẫn giữ thông tin cần cho quyết định, giúp phiên dài không mất quyết định quan trọng (lab D2 context-compression).","aka":["context compression"]},{"t":"computing","vi":"Tính toán, điện toán. “Centralized Computing” là xu hướng gom chức năng từ nhiều ECU phân tán về vài máy tính trung tâm mạnh (domain/zone controller, HPC).","aka":["Centralized Computing"]},{"t":"confidential","vi":"Bí mật, mật. Một trong năm nhãn dữ liệu (public, internal, confidential, personal, regulated): dữ liệu mật của dự án/khách hàng, chỉ được đưa vào công cụ AI đã duyệt theo hợp đồng."},{"t":"conflicting","vi":"Mâu thuẫn, xung đột nhau. Trong syllabus: “Resolve conflicting constraints” — giải quyết các ràng buộc mâu thuẫn (chi phí, hiệu năng, an toàn…) để ra giải pháp cân bằng."},{"t":"confounding","vi":"Gây nhiễu. <b>Confounding variable<\/b>: yếu tố không kiểm soát có thể giải thích kết quả thay cho yếu tố đang đo — vd. đổi model và skill cùng lúc thì không biết cái nào gây thay đổi.","aka":["confounding variable","confounding variables"]},{"t":"connected","vi":"Kết nối. Trong bài kinh tế ô tô: “Connected” là một trong bốn lực định hình ngành — xe kết nối mạng (OTA, cloud) nên an ninh mạng thành nghĩa vụ pháp lý."},{"t":"considerations","vi":"Các điểm cần cân nhắc. Trong syllabus: “lifecycle considerations” — các yếu tố vòng đời (bảo trì, cập nhật, ngừng hỗ trợ) phải tính khi thiết kế kiến trúc."},{"t":"constants.json","vi":"File hằng số minh họa, sinh tự động từ spec. Trong khóa: artifact context phải <b>trỏ<\/b> tới nguồn sự thật như constants.json chứ không chép giá trị, để khỏi lệch khi spec đổi."},{"t":"Constrain","vi":"Ràng buộc — một trong các chức năng vận hành agent: xác định cái agent tuyệt đối không được làm và cưỡng chế bằng permission, hook, code thay vì chỉ dặn trong prompt (nguyên tắc Fail-Safe Defaults)."},{"t":"construction","vi":"Xây dựng, kiến tạo. Trong glossary: tên sách Meyer “Object-Oriented Software Construction” — nguồn tra khái niệm Design by Contract."},{"t":"context-compression","vi":"Nén context: rút gọn lịch sử hội thoại/dữ liệu đã nạp để agent làm việc lâu mà không tràn cửa sổ context, nhưng vẫn giữ các quyết định quan trọng. Trong khóa là tên một lab (labs/context-compression) ở buổi D2, đi cùng lab kv-cache về chi phí.","aka":["context compression"]},{"t":"contribution","vi":"Sự đóng góp. Trong khóa: phần đóng góp đo được của mỗi người (hoặc của AI) vào kết quả dự án — ví dụ ‘measurable contribution’ là bằng chứng cho thấy việc dùng AI thực sự tạo ra giá trị cụ thể.","aka":["contributions"]},{"t":"copy-paste","vi":"Sao chép rồi dán. Trong khóa dùng để chỉ cách dùng AI thủ công: dán lại bối cảnh hay code vào chat mỗi lần; Project và Claude Code giúp tránh việc này vì tự giữ/đọc bối cảnh.","aka":["copy paste","copy-pasting"]},{"t":"correct","vi":"Sửa cho đúng (động từ) hoặc đúng (tính từ). Trong chuỗi xử lý sự cố Contain → Analyse → Correct → Verify, Correct là bước áp dụng bản sửa nhỏ nhất mà vẫn an toàn sau khi đã tìm ra root cause.","aka":["corrects","corrected"]},{"t":"cost-analysis","vi":"Phân tích chi phí. Trong khóa AI là tên lab (labs/cost-analysis, agent-cost-analysis) ở buổi D6: bóc tách chi phí token và độ trễ của từng bước trong một lần chạy agent để biết tiền và thời gian đi đâu.","aka":["cost analysis"]},{"t":"course","vi":"Khóa học. Trong trang lịch học: khóa đào tạo Fast-track CDC/SDV nói chung, hoặc một khóa tự học cụ thể (ví dụ khóa trên Coursera, khóa AI Transformation) mà học viên phải theo.","aka":["courses"]},{"t":"Coursera","vi":"Nền tảng học trực tuyến có các khóa của trường đại học và doanh nghiệp. Trong chương trình, FPT cấp license Coursera để học viên tự học các khóa nền như SDV 101, Automotive SPICE, AUTOSAR theo lịch từng module."},{"t":"courseware","vi":"Học liệu: toàn bộ tài liệu dạy học của một khóa (slide, bài đọc, bài tập, video). Trong syllabus: Content Owner dựa vào syllabus để soạn courseware và storyboard cho khóa."},{"t":"covering","vi":"Bao quát, bao gồm. Trong mục tiêu học tập: kiến trúc CDC/SDV phải bao quát đủ platform, data, interface, deployment và quản trị vòng đời.","aka":["covers"]},{"t":"create","vi":"Tạo ra. Trong lịch học: mục tiêu buổi học dạng hành động, ví dụ ‘Create a Delegation Map’ — tự lập bản đồ phân việc giữa người và AI.","aka":["creates","created"]},{"t":"CS","vi":"Khoa học máy tính. Trong glossary của khóa AI: các khái niệm như Hoare logic, precondition/postcondition được gọi là kiến thức CS cơ bản, tra được trong giáo trình lập trình.","full":"Computer Science","cs":true},{"t":"Curious","vi":"Tò mò. Trong khung CASAN của FPT là cấp 1: dùng AI lẻ tẻ, cá nhân, chưa đo được hiệu suất hay hiệu quả; các cấp tiếp theo là Augmented, Standard, Automated, Native."},{"t":"custom","vi":"Tùy chỉnh, làm riêng theo nhu cầu. Trong khóa AI hay đi trong cụm custom instructions — chỉ dẫn cố định do người dùng tự đặt cho AI.","aka":["customized","customised"]},{"t":"custom instructions","vi":"Chỉ dẫn tùy chỉnh: đoạn hướng dẫn cố định đặt trong một Project của Claude, tự áp vào mọi hội thoại trong Project đó (ví dụ quy ước, vai trò, định dạng trả lời), khỏi phải nhắc lại mỗi lần."},{"t":"daily","vi":"Hằng ngày. Trong bảng đánh giá của syllabus: Daily quiz là bài kiểm tra ngắn hằng ngày (đợt này không bắt buộc)."},{"t":"data-flow","vi":"Luồng dữ liệu (dạng có gạch nối dùng như tính từ): dữ liệu đi từ đâu, qua thành phần nào, tới đâu. Trong syllabus: các ca data-flow mẫu của xe dùng làm tài liệu thực hành kiến trúc.","aka":["data-flows","vehicle data-flow"]},{"t":"Dec","vi":"Viết tắt của December — tháng 12. Trong trang OJT: mốc 25-Dec là ngày kết thúc OJT và đánh giá.","aka":["December"]},{"t":"deck","vi":"Bộ slide trình chiếu. Trong khóa: slide deck của giảng viên, hoặc deck nhập môn phải đọc trước buổi học.","aka":["decks","slide deck"]},{"t":"decompose","vi":"Phân rã: chia một việc lớn thành các bước/việc nhỏ hơn. Trong khóa AI: phân rã công việc để quyết định bước nào giao Máy, Agent hay Người và kiểm được từng bước.","aka":["decomposes","decomposed"]},{"t":"dedicate","vi":"Dành riêng (thời gian, công sức). Trong syllabus: học viên phải dành ít nhất 9 giờ mỗi tuần cho việc học.","aka":["dedicates"]},{"t":"Fail-Safe Defaults","vi":"Mặc định an toàn: nguyên lý bảo mật kinh điển — khi chưa được cho phép rõ ràng thì mọi quyền đều tắt. Trong khóa AI: mọi năng lực của agent tắt mặc định, chỉ bật từng quyền cần thiết và cưỡng chế bằng hạ tầng (permission, hook) chứ không bằng lời dặn.","aka":["fail-safe default"]},{"t":"defaults","vi":"Giá trị/thiết lập mặc định — trạng thái áp dụng khi không ai cấu hình gì. Trong khóa AI chủ yếu ở cụm Fail-Safe Defaults: mặc định phải là trạng thái an toàn (tắt quyền)."},{"t":"defend","vi":"Bảo vệ, biện hộ. Trong chương trình: trình bày và bảo vệ kết luận/quyết định kiến trúc trước mentor, SA/BUL bằng lập luận và bằng chứng, trả lời được câu hỏi phản biện.","aka":["defends","defended","defending"]},{"t":"defense-in-depth","vi":"Phòng thủ nhiều lớp: xếp chồng nhiều lớp bảo vệ độc lập để một lớp hỏng không làm sập cả hệ. Trong khóa AI: chống prompt injection bằng lọc đầu vào, permission, hook, sandbox, review… — giảm rủi ro chứ không đưa về 0.","aka":["defence-in-depth","defence in depth"]},{"t":"define","vi":"Xác định, định nghĩa. Trong lịch học: tên buổi/mục tiêu như ‘Define Data Boundaries’ (xác định ranh giới dữ liệu được đưa cho AI) hay ‘defining human, AI and shared responsibilities’.","aka":["defines","defined","defining"]},{"t":"Software Defined Vehicle","vi":"Cách viết không gạch nối của Software-Defined Vehicle (SDV): xe mà tính năng chủ yếu do phần mềm quyết định và cập nhật được sau khi bán. Xuất hiện trong tên khóa Coursera ‘SDV 101: Introduction to Software Defined Vehicles’.","aka":["Software Defined Vehicles"]},{"t":"delegable","vi":"Có thể ủy quyền/giao cho người khác (ở đây là cho AI agent). Trong khóa đi trong cụm Delegable judgment.","aka":["delegatable"]},{"t":"Delegable judgment","vi":"Phán đoán giao được: loại việc thứ 2 trong tam phân Máy/Agent/Người — cần suy luận, nhưng nếu sai thì phát hiện được nên có thể giao cho Agent kèm bước kiểm chứng.","aka":["delegable judgement"]},{"t":"deliver","vi":"Bàn giao, chuyển giao kết quả. Trong OJT: phải nộp một bản chạy được hoặc bản mẫu đã kiểm chứng, kèm bằng chứng kiến trúc.","aka":["delivers","delivered","delivering"]},{"t":"DeMillo","vi":"Richard DeMillo — nhà khoa học máy tính, đồng tác giả (với Lipton và Sayward, 1978) bài báo nền tảng về mutation testing. Glossary của khóa dẫn tên này làm nguồn tra cứu cho khái niệm mutation testing."},{"t":"demonstrate","vi":"Chứng minh, trình diễn. Trong chương trình: phải chứng minh bằng sản phẩm chạy thật (demo) và bằng chứng, ví dụ ‘Demonstrate CASAN Level 3’; demonstration là buổi/bài trình diễn trên môi trường lab.","aka":["demonstrates","demonstrated","demonstrations"]},{"t":"deny","vi":"Từ chối, chặn. Trong Claude Code: mức quyền deny trong permission — thao tác bị cấm cứng (ví dụ đọc .env, rm -rf), agent không thể làm dù prompt nói gì; khác với gợi ý trong CLAUDE.md.","aka":["denied","denies"]},{"t":"allow/ask/deny","vi":"Ba mức quyền trong permission của Claude Code: allow (tự làm không hỏi), ask (phải hỏi người duyệt trước), deny (cấm hẳn). Đây là cách biến chính sách ủy quyền thành ràng buộc cứng do hạ tầng cưỡng chế.","aka":["allow / ask / deny"]},{"t":"denylist","vi":"Danh sách chặn: liệt kê những thứ bị cấm, còn lại được phép. Trong khóa AI so với allowlist: denylist dễ bỏ sót trường hợp mới, nên mặc định an toàn hơn là allowlist.","aka":["deny-list","deny list","blocklist","blacklist"]},{"t":"Description","vi":"Mô tả. Trong khung 4D của Anthropic (Delegation · Description · Discernment · Diligence) là chữ D thứ hai: giao tiếp rõ bối cảnh, mục tiêu, ràng buộc cho AI vì AI không đọc được ý nghĩ. Ở trang lịch học còn là ô mô tả (ví dụ mô tả đối tượng học).","aka":["descriptions"]},{"t":"designing","vi":"Đang thiết kế / việc thiết kế. Xuất hiện trong tên khóa tự học như ‘AI Orchestration: Designing the Prototype Architecture and Data Strategy’.","aka":["designs"]},{"t":"determine","vi":"Xác định, quyết định. Trong learning outcome: phân tích yêu cầu để xác định giải pháp khả thi cho nền tảng xe hiện đại.","aka":["determines","determined"]},{"t":"DEV05","vi":"Mã bậc năng lực kỹ sư nội bộ FPT (Dev3/DEV03 → DEV04 → DEV05, số càng cao càng cao cấp; Dev4+ là từ bậc 4 trở lên). Syllabus mô tả kỳ vọng khi lên mỗi bậc; DEV05 đòi tự định khung vấn đề kiến trúc mơ hồ, nhiều miền.","aka":["Dev3","Dev4","Dev4+","DEV3","DEV4","DEV5"],"cs":true},{"t":"diagramming","vi":"Việc vẽ sơ đồ. Trong yêu cầu kỹ thuật của khóa: cần một công cụ vẽ sơ đồ (diagramming tool) để vẽ kiến trúc, context diagram, luồng dữ liệu.","aka":["diagramming tool"]},{"t":"digital.auto","vi":"Sáng kiến/cộng đồng mở về SDV (phát triển ứng dụng xe theo chuẩn mở, prototyping nhanh). Trong syllabus là đơn vị cung cấp khóa ‘SDV 101: Introduction to Software Defined Vehicles’ trên Coursera."},{"t":"Diligence","vi":"Cẩn trọng, tận tâm. Chữ D thứ tư trong khung 4D của Anthropic: trách nhiệm cuối cùng về đạo đức, an toàn và tính đúng của sản phẩm luôn thuộc về con người, kể cả khi AI làm phần lớn."},{"t":"disableAllHooks","vi":"Thiết lập trong Claude Code để tắt mọi hook. Bài đọc nhấn mạnh: hook đặt trong managed settings (cấp tổ chức) không bị disableAllHooks của cá nhân vô hiệu hóa, nên dùng được làm hàng rào bắt buộc."},{"t":"Discernment","vi":"Thẩm định, phân định. Chữ D thứ ba trong khung 4D của Anthropic: đánh giá chất lượng và logic của output AI (đọc diff, kiểm test) — viết mượt không có nghĩa là đúng."},{"t":"docs","vi":"Viết tắt của documentation — tài liệu chính thức. Trong glossary của khóa: ‘docs Claude Code’ là tài liệu chính thức của Claude Code, một nguồn tra cứu cho từng thuật ngữ.","aka":["doc"]},{"t":"Dolphin+","vi":"Tên dòng SoC ô tô của hãng Telechips (họ TCC803x), dùng cho cockpit/IVI. Trên trang chủ là nền tảng của đề tài phân tích quá trình boot tới khung hình 3D đầu tiên.","aka":["Telechips Dolphin+"]},{"t":"domain-specific","vi":"Đặc thù theo lĩnh vực, chuyên ngành. Trong syllabus: kiến thức chuyên ngành ô tô/nhúng; trong khóa AI: tool và context xây riêng cho miền nghiệp vụ của dự án."},{"t":"Domain-specific tooling","vi":"Tool chuyên miền: công cụ xây riêng cho codebase/miền nghiệp vụ của bạn (ví dụ tool kiểm property VHAL). Glossary nhấn mạnh việc này quan trọng hơn việc chọn framework agent nào."},{"t":"Done","vi":"Xong — trạng thái hoàn thành của một việc trên bảng công việc. Trong khóa AI: khi bước đang chờ người duyệt thì AI không được tự đánh dấu Done."},{"t":"DPA","vi":"Thỏa thuận xử lý dữ liệu giữa bên sở hữu dữ liệu và nhà cung cấp dịch vụ. Trong khóa AI: chỉ gửi dữ liệu mức ‘có kiểm soát’ tới nhà cung cấp AI có DPA và cam kết zero-retention, qua endpoint đã duyệt.","aka":["DPAs"],"full":"Data Processing Agreement","cs":true},{"t":"driven","vi":"Được dẫn dắt/định hướng bởi (thường đứng sau danh từ: X-driven). Trong syllabus: Quality Attribute Driven Design — thiết kế lấy thuộc tính chất lượng làm động lực chính."},{"t":"Quality Attribute Driven Design","vi":"Thiết kế dẫn dắt bởi thuộc tính chất lượng: chọn cấu trúc và quyết định kiến trúc xuất phát từ các yêu cầu latency, safety, security, availability… thay vì từ chức năng. Là một chủ đề ví dụ cho Assignment trong syllabus."},{"t":"duration","vi":"Thời lượng. Trong bảng lịch học: cột Duration (mins) ghi số phút dành cho mỗi nội dung.","aka":["durations"]},{"t":"duty","vi":"Nghĩa vụ, bổn phận. Trong bài: evidence duties — nghĩa vụ cung cấp bằng chứng; thiếu nó thì không chứng minh được đã đạt yêu cầu.","aka":["duties"]},{"t":"each","vi":"Mỗi, từng. Trong syllabus: nộp bản suy ngẫm học tập (learning reflection) cho từng topic."},{"t":"Eclipse","vi":"Eclipse Foundation — tổ chức nguồn mở quản lý nhiều dự án phần mềm (IDE Eclipse, các working group). Trong syllabus xuất hiện qua Eclipse SDV."},{"t":"Eclipse SDV","vi":"Nhóm làm việc nguồn mở của Eclipse Foundation về Software-Defined Vehicle, phát triển các thành phần phần mềm xe dùng chung. Tài liệu của Eclipse SDV là một nguồn tham khảo trong syllabus."},{"t":"editing","vi":"Chỉnh sửa. Trong khóa AI: file editing là năng lực ghi/sửa file của coding agent — cần giới hạn thư mục được ghi, chặn file sinh tự động và review diff."},{"t":"file editing","vi":"Sửa file: một trong các năng lực của coding agent (cùng tool calling, terminal, search, test). Kiểm soát bằng cách chỉ cho ghi trong thư mục được giao, deny file sinh tự động và bắt buộc review diff."},{"t":"EDUCBA","vi":"Nhà cung cấp khóa học trực tuyến có nhiều khóa trên Coursera. Trong syllabus là đơn vị dạy các khóa tự học như Overview of Automotive SPICE và Introduction to AutoSAR.","cs":true},{"t":"effectively","vi":"Một cách hiệu quả. Xuất hiện trong tên sách Working Effectively with Legacy Code của Michael Feathers."},{"t":"Working Effectively with Legacy Code","vi":"Sách của Michael Feathers (2004) về cách sửa code cũ an toàn: trước hết bọc bằng test (characterization test) rồi mới refactor. Glossary của khóa dẫn chương 1 làm nguồn cho ý: không có test thì refactor legacy là vùng đỏ."},{"t":"if/else","vi":"Câu lệnh rẽ nhánh: nếu điều kiện đúng làm A, ngược lại làm B. Trong bài định tuyến agent: phân loại bằng luật if/else là cách rẻ và nhanh nhất, nên dùng trước khi nghĩ tới LLM.","aka":["if-else"]},{"t":"embedding","vi":"Vector số biểu diễn ý nghĩa của văn bản, để đo độ giống nhau về nghĩa. Trong khóa AI: một trong 4 kiểu routing (so embedding của yêu cầu với các nhóm mẫu) và là nền của tìm kiếm trong RAG.","aka":["embeddings"]},{"t":"enum","vi":"Kiểu liệt kê: tham số chỉ nhận một tập giá trị cố định. Trong khóa AI: ràng buộc ở tham số tool bằng enum để agent không thể truyền giá trị ngoài danh sách — chắc hơn lời dặn trong prompt.","aka":["enums","enumeration"]},{"t":"erp-agent","vi":"Tên lab ở buổi D4 (labs/erp-agent): agent truy vấn dữ liệu kiểu ERP bằng cách sinh sản phẩm trung gian (ví dụ câu truy vấn) thay vì tự bê dữ liệu vào context — rẻ hơn và chính xác hơn.","aka":["ERP agent"]},{"t":"esspecialy","vi":"Lỗi chính tả của especially — đặc biệt là. Trong syllabus: năng lực nền tảng ô tô, đặc biệt là CDC.","aka":["especially"]},{"t":"establish","vi":"Thiết lập, xây dựng nền. Trong syllabus: thiết lập tư duy AI-first, quy tắc sandbox; ‘established governance’ là khung quản trị đã được thiết lập sẵn.","aka":["establishes","established"]},{"t":"EV","vi":"Xe điện. Trong bài kinh tế ngành ô tô: miền EV (quản lý pin, nhiệt) có yêu cầu an toàn và độ tin cậy cao, nhịp phát triển khác miền UX.","aka":["EVs"],"full":"Electric Vehicle","cs":true},{"t":"eval","vi":"Viết tắt của evaluation — bộ đánh giá có hệ thống chất lượng output của AI/agent (golden set, rubric, LLM-judge, thống kê). Trong khóa AI (D6): xây eval 3 tầng chạy trong CI thay cho kiểm thử bằng cảm giác.","aka":["evals"]},{"t":"evaluate","vi":"Đánh giá. Trong syllabus: mức Bloom ‘Evaluate’ (đánh giá, so sánh phương án) và các mục tiêu như đánh giá phương án khả thi.","aka":["evaluates","evaluated","evaluating"]},{"t":"evaluator-optimizer","vi":"Mẫu workflow agent: một bộ sinh tạo kết quả, một bộ chấm riêng biệt đánh giá và gửi nhận xét để bộ sinh sửa, lặp đến khi đạt. Tốt hơn self-review vì có tín hiệu kiểm chứng độc lập.","aka":["evaluator optimizer"]},{"t":"evidence-based","vi":"Dựa trên bằng chứng: kết luận phải có dữ liệu, log, đo đạc chống lưng chứ không dựa cảm tính. Trong syllabus: evidence-based RCA."},{"t":"exam","vi":"Bài thi. Trong syllabus: phần Exam gồm Pre-Test và Final Topic Test (90 phút); ở giai đoạn đánh giá là buổi phỏng vấn/bảo vệ.","aka":["exams"]},{"t":"example","vi":"Ví dụ. Trong syllabus: Example topics là các đề tài gợi ý; trong khóa AI hay đi trong cụm golden example.","aka":["examples"]},{"t":"golden example","vi":"Ví dụ chuẩn: cặp đầu vào và đầu ra đã được chuyên gia xác nhận là đúng/tốt, dùng làm mốc so sánh khi đánh giá output AI. Nhiều golden example gộp lại thành golden set.","aka":["golden examples"]},{"t":"executable","vi":"Chạy được, thực thi được. Trong khóa AI: biến quy tắc kỹ thuật thành ràng buộc bằng code chạy được và check trong CI (fail khi vi phạm), thay vì chỉ ghi bằng lời."},{"t":"expectation","vi":"Kỳ vọng. Trong kiểm thử: giá trị mong đợi mà test so sánh. Khóa AI cảnh báo agent có thể sửa expectation, xóa hay skip test để ‘xanh’ — phải đọc diff test.","aka":["expectations"]},{"t":"expertise","vi":"Chuyên môn sâu. Trong khóa AI: domain expertise là vũ khí — hiểu biết miền của kỹ sư (đưa vào context, rule, review) là thứ làm agent chạy đúng trong dự án."},{"t":"domain expertise","vi":"Chuyên môn miền: hiểu biết sâu về nghiệp vụ/kỹ thuật của lĩnh vực (ở đây là ô tô, AAOS, VHAL…). Khóa AI coi đây là lợi thế chính của kỹ sư khi làm việc với agent."},{"t":"explain","vi":"Giải thích. Trong Assignment 3: giải thích được thành phần, interface, luồng dữ liệu, mối quan tâm và thách thức triển khai của chủ đề tự nghiên cứu.","aka":["explains","explained"]},{"t":"Exploration","vi":"Khám phá. Trong khóa AI là tên một mẫu thiết kế agent nâng cao (agent tự tìm hiểu không gian chưa biết); nằm trong nhóm mẫu vượt quá phạm vi cấp 3 của khóa."},{"t":"extend","vi":"Mở rộng. Trong lịch học D4: mở rộng một coding agent bằng cách thêm một tool chuyên miền CDC và kiểm chứng hành vi của nó.","aka":["extends","extended"]},{"t":"externalize","vi":"Ngoại hóa: đưa tri thức đang nằm trong đầu người ra thành tài liệu/artifact. Trong khóa AI (D2): biến tri thức dự án thành context và skill tái sử dụng để agent và đồng nghiệp dùng chung.","aka":["externalise","externalized","externalizes"]},{"t":"FA","vi":"Viết tắt tên đơn vị nội bộ trong FPT (thường hiểu là khối FPT Automotive). Trong tài liệu: tiền tố mã khóa học (FA.CDC-…) và ‘quy ước code FA’ — tài liệu nội bộ, xếp mức dữ liệu M2.","cs":true},{"t":"FA.CDC-SA-AUTO-EXPERT-001","vi":"Mã khóa học (Topic Code) của chương trình Automotive Senior Fastrack Training (CDC/SDV) trong syllabus: tiền tố đơn vị, mảng CDC, hướng SA, lĩnh vực ô tô, trình độ expert, số thứ tự.","cs":true},{"t":"fail-closed","vi":"Lỗi thì chặn: khi bộ kiểm tra gặp lỗi hoặc không chắc, hệ thống từ chối/dừng thay vì cho qua. Trong khóa AI là nguyên tắc cho validator, hook và cửa ra dữ liệu: lỗi parse → chặn và báo người.","aka":["fail closed"]},{"t":"fail-open","vi":"Lỗi thì cho qua: khi bộ kiểm tra hỏng, hệ thống vẫn để mọi thứ đi tiếp. Khóa AI coi đây là lỗi thiết kế nguy hiểm — ví dụ validator im lặng bỏ qua ca biên, hay agent gặp lỗi vẫn báo ‘hoàn thành’.","aka":["fail open"]},{"t":"fan","vi":"Quạt. Trong ví dụ VHAL: fan speed là tốc độ quạt của hệ HVAC."},{"t":"fan speed","vi":"Tốc độ quạt gió điều hòa (property HVAC). Ví dụ trong bài verifier: auto mode và fan speed từng cái hợp lệ nhưng tổ hợp vô nghĩa — cần kiểm phụ thuộc giữa các property."},{"t":"fast-track","vi":"Lộ trình rút gọn/tăng tốc. Tên chương trình Automotive Senior Fastrack Training (CDC/SDV): đào tạo nhanh kỹ sư senior lên vai trò kiến trúc; Fast-track Evaluation là giai đoạn đánh giá cuối.","aka":["Fastrack","Fasttrack","fast track","fastrack","fasttrack"]},{"t":"feasible","vi":"Khả thi: làm được trong ràng buộc thực tế (kỹ thuật, chi phí, thời gian). Trong syllabus: đánh giá các phương án khả thi cho một module/subsystem."},{"t":"Feathers","vi":"Michael Feathers — tác giả sách Working Effectively with Legacy Code (2004), nổi tiếng với định nghĩa legacy code là code không có test. Glossary của khóa dẫn sách này làm nguồn.","aka":["Michael Feathers"]},{"t":"few-shot","vi":"Kỹ thuật prompt đưa kèm vài (1–5) cặp ví dụ đầu vào → đầu ra mẫu để model bắt chước định dạng và cách làm. Một trong các kỹ thuật prompt chuẩn hóa trong bài 2.","aka":["few-shot prompting"]},{"t":"filter","vi":"Bộ lọc; lọc. Trong bảng kỹ năng của syllabus: ‘Select a filter’ là chọn giá trị từ danh sách lọc của file Excel gốc.","aka":["filters"]},{"t":"final","vi":"Cuối cùng, bản chính thức. Trong chương trình: Assignment final (bản nộp sau khi sửa theo review), Final Topic Test, Final OJT — đề tài cuối được duyệt và bảo vệ trước SA/BUL."},{"t":"final_v3","vi":"Kiểu đặt tên file tự phát (final, final_v2, final_v3…) — phản ví dụ trong bài tài liệu có kiểm soát: tên như vậy không cho biết bản nào đã được duyệt, ai sửa, sửa gì. Cần mã tài liệu, số revision và trạng thái approval rõ ràng.","aka":["final_v2","final_final"]},{"t":"focuses","vi":"Tập trung vào. Trong syllabus: 70% thời gian học tập trung vào nhu cầu hiện tại, 30% vào nhu cầu tương lai.","aka":["focused"]},{"t":"folder","vi":"Thư mục. Trên trang chủ: kiểm tra folder tài liệu chung của khóa ở tuần khởi động.","aka":["folders"]},{"t":"follow","vi":"Theo, làm theo. Trong lịch học: ‘Follow the course’ — theo học khóa (ví dụ AI Transformation for Automotive Senior Engineers) song song với các unit.","aka":["follows"]},{"t":"follow-up","vi":"Theo dõi tiếp sau. Trong Assignment 2: follow-up metrics là các chỉ số để theo dõi sau khi quyết định được áp dụng, xem nó có đạt kết quả mong muốn không.","aka":["follow up","follow-ups"]},{"t":"force","vi":"Ép buộc. Trong git, push --force ghi đè lịch sử nhánh trên remote — lệnh phá hủy nên bị deny trong permission của agent.","aka":["--force"]},{"t":"push --force","vi":"Lệnh git đẩy code lên remote bằng cách ghi đè lịch sử hiện có, có thể làm mất commit của người khác. Trong khóa AI nằm trong danh sách lệnh phá hủy bị chặn bằng permission/hook.","aka":["git push --force"]},{"t":"foundation","vi":"Nền tảng. Trong chương trình: Phase 1 Foundation (học nền), Assignment 1 Architecture Context &amp; Foundation; bên khóa AI: Lesson 0A Foundational Concepts — khái niệm nền.","aka":["foundations","foundational"]},{"t":"FPT","vi":"Tập đoàn công nghệ Việt Nam, nơi tổ chức chương trình đào tạo này. Trong khóa AI: khung năng lực AI 5 cấp CASAN là chuẩn chung toàn FPT; dữ liệu nội bộ chỉ được xử lý trong hạ tầng/endpoint FPT đã duyệt.","cs":true},{"t":"FSA","vi":"Đơn vị đào tạo của FPT Software. Trong syllabus: ‘FSA Link’ là đường dẫn tới module học trên hệ thống của FSA (hiện ghi TBD — chưa có).","full":"FPT Software Academy","cs":true},{"t":"fundamentals","vi":"Kiến thức cơ bản, nền tảng. Ví dụ Lesson 0C · Claude Code Fundamentals: các thao tác và cơ chế cơ bản của Claude Code.","aka":["fundamental"]},{"t":"FUSA","vi":"An toàn chức năng: tránh rủi ro không chấp nhận được do lỗi hệ thống điện/điện tử, theo ISO 26262 trong ô tô. Trong syllabus là một nhóm tiêu chuẩn kỹ sư nền tảng ô tô phải nắm.","aka":["FuSa"],"full":"Functional Safety","cs":true},{"t":"GAIA","vi":"Benchmark đánh giá trợ lý AI (General AI Assistants) với các câu hỏi chia 3 mức khó Level 1/2/3. Trong khóa AI: cách phân tầng task L1/L2/L3 kiểu GAIA dùng làm nền để chẩn đoán agent."},{"t":"GB","vi":"Đơn vị dung lượng bộ nhớ (khoảng 1 tỷ byte). Trong bài ảo hóa: chia RAM cho từng VM, ví dụ dành 2 GB cho phía safety và tối đa 12 GB cho AAOS.","full":"Gigabyte","cs":true},{"t":"GDPR","vi":"Quy định bảo vệ dữ liệu cá nhân của Liên minh châu Âu. Trong khóa AI: ví dụ về luật buộc dữ liệu ở lại trong vùng tài phán (data residency) — dữ liệu chịu GDPR xếp mức nghiêm ngặt nhất khi dùng AI.","aka":["gdpr"],"full":"General Data Protection Regulation","cs":true},{"t":"generation","vi":"Sự sinh ra, tạo ra (nội dung). Trong khóa AI xuất hiện trong RAG — Retrieval Augmented Generation."},{"t":"Retrieval Augmented Generation","vi":"Tên đầy đủ của RAG: model truy xuất tài liệu liên quan từ nguồn ngoài (tài liệu dự án, spec) rồi dùng chúng để sinh câu trả lời, giúp trả lời đúng thông tin riêng/mới mà model không học sẵn.","aka":["Retrieval-Augmented Generation"]},{"t":"generative","vi":"Có khả năng sinh ra (nội dung mới). Trong khóa AI đi trong cụm generative AI."},{"t":"generative AI","vi":"AI tạo sinh: nhánh machine learning sinh nội dung mới (văn bản, code, ảnh) thay vì chỉ phân loại/gán nhãn. LLM như Claude là một dạng generative AI.","aka":["GenAI"]},{"t":"glob","vi":"Mẫu tên file có ký tự đại diện (ví dụ src/**/*.kt) để liệt kê file. Coding agent dùng glob theo tên file và grep theo từ khóa để tìm đúng chỗ trong repo lớn trước khi đọc.","aka":["globs","glob pattern"]},{"t":"glossary","vi":"Bảng thuật ngữ. Khóa AI có trang Glossary tra cứu nhanh các thuật ngữ lõi kèm buổi học và nguồn đọc thêm; thiết lập glossary chung cũng là mục tiêu buổi đầu.","aka":["glossaries"]},{"t":"golden-set","vi":"Cách viết có gạch nối của golden set: bộ ca mẫu có đáp án chuẩn đã được người làm tốt/xác nhận, dùng để so output AI và phát hiện suy giảm chất lượng. Trong khóa: bài golden-set cuối Tập 0B dùng lại ở D6."},{"t":"Goldratt","vi":"Eliyahu Goldratt — tác giả tiểu thuyết quản trị The Goal (1984) và lý thuyết ràng buộc (Theory of Constraints). Glossary dẫn ông cho ý: bước nghẽn quyết định thông lượng toàn hệ.","aka":["Eliyahu Goldratt"]},{"t":"Google","vi":"Công ty công nghệ Mỹ (tìm kiếm, Android, AI). Trong khóa AI: được nhắc như cách dùng AI kiểu ‘Google thông minh hơn’ (hỏi–đáp một lần), và là tác giả Google ADK, giao thức A2A."},{"t":"govern","vi":"Quản trị, điều hành có quy tắc. Trong lịch học D8: triển khai và quản trị workflow AI (quyền, giám sát, audit) rồi bảo vệ bằng bằng chứng.","aka":["governs"]},{"t":"GPA","vi":"Điểm trung bình chung. Trong syllabus: điều kiện đạt khóa là GPA ≥ 7/10 và tham dự ≥ 80%.","full":"Grade Point Average","cs":true},{"t":"grade","vi":"Cấp, hạng (chất lượng/tiêu chuẩn). Trong syllabus xuất hiện trong tên Automotive Grade Linux — Linux đạt cấp dùng cho ô tô."},{"t":"Automotive Grade Linux","vi":"Dự án Linux nguồn mở cho ô tô thuộc Linux Foundation, cung cấp nền tảng chung cho IVI và các ứng dụng xe. Tài liệu AGL là một nguồn tham khảo kiến trúc CDC/SDV trong syllabus.","aka":["AGL"]},{"t":"grep","vi":"Công cụ tìm chuỗi/regex trong file. Coding agent như Claude Code grep theo từ khóa để định vị code liên quan; nếu CLAUDE.md trỏ sai thư mục, agent grep nhầm chỗ và tốn vòng thăm dò."},{"t":"GSN","vi":"Ký pháp đồ họa để trình bày lập luận an toàn (safety case): mục tiêu → chiến lược → bằng chứng. Glossary gợi ý tra ‘safety case gsn’ để hiểu cách lập luận một hệ là đủ an toàn.","aka":["gsn"],"full":"Goal Structuring Notation","cs":true},{"t":"guardrail","vi":"Lan can bảo vệ: cơ chế ràng buộc hành vi agent (kiểm đầu vào/ra, permission, hook, validator) để chặn hành động sai hoặc nguy hiểm. Khóa AI phân biệt guardrail cứng do hạ tầng cưỡng chế với lời dặn trong prompt.","aka":["guardrails"]},{"t":"guide","vi":"Hướng dẫn; tài liệu hướng dẫn. Trong syllabus: Guides/Review là hoạt động mentor hướng dẫn và review bài tập, OJT; Assignment guides là tài liệu hướng dẫn làm bài.","aka":["guides"]},{"t":"hallucination","vi":"Ảo giác của AI: model tạo ra nội dung nghe rất đúng nhưng sai hoặc bịa (API không tồn tại, số liệu sai). Là rủi ro lõi của khóa AI — phải kiểm chứng bằng nguồn, test, verifier thay vì tin văn mượt.","aka":["hallucinations","hallucinate"]},{"t":"handoff","vi":"Bàn giao: chuyển việc và bối cảnh từ agent/bước này sang agent/bước khác (hoặc sang người). Trong hệ đa agent, handoff phải mang đủ context cần thiết, nếu không bước sau làm sai.","aka":["handoffs","hand-off"]},{"t":"hands-on","vi":"Thực hành trực tiếp, tự tay làm. Trong syllabus: yêu cầu học viên có kinh nghiệm thực tế phát triển CDC/SDV."},{"t":"hard-gate","vi":"Cổng chặn cứng: điểm kiểm soát do máy cưỡng chế (script, hook, CI, permission), vi phạm là bị chặn, không phụ thuộc agent có nghe lời hay không. Khóa AI nhấn mạnh hard-gate phải là code, không phải quy tắc trong prompt.","aka":["hardgate"]},{"t":"hash-chain","vi":"Chuỗi băm: mỗi bản ghi chứa hash của bản ghi trước, nên sửa lùi một bản ghi sẽ làm gãy chuỗi và bị phát hiện.","aka":["hash chain"]},{"t":"hash-chain audit log","vi":"Nhật ký audit nối bằng hash: mỗi dòng log chứa hash của dòng trước để phát hiện việc sửa/xóa lùi. Trong khóa AI (D8) dùng để lưu vết hành động của agent một cách đáng tin cho kiểm toán."},{"t":"Haystack","vi":"Framework nguồn mở (của deepset) để xây ứng dụng LLM, mạnh về RAG và tìm kiếm tài liệu. Được nhắc trong danh sách framework agent đáng biết bên cạnh LlamaIndex."},{"t":"CrewAI","vi":"Framework nguồn mở để dựng đội nhiều agent, mỗi agent một vai (role) cùng hợp tác. Được nhắc trong danh sách framework agent đáng biết; khóa dùng Claude Code để thực hành."},{"t":"HBR","vi":"Tạp chí quản trị của Đại học Harvard. Glossary dẫn bài HBR ‘Leading Change’ (Kotter, 1995) làm nguồn đọc về quản lý thay đổi khi đưa AI vào tổ chức.","aka":["hbr"],"full":"Harvard Business Review","cs":true},{"t":"high-complexity","vi":"Độ phức tạp cao. Trong kỳ vọng bậc cao hơn: định hướng kiến trúc và nguyên tắc quản trị cho phạm vi có độ phức tạp cao."},{"t":"high-impact","vi":"Tác động lớn. Trong syllabus: chịu trách nhiệm các quyết định kỹ thuật có ảnh hưởng lớn và truyền đạt hệ quả của chúng với tổ chức."},{"t":"high-value","vi":"Giá trị cao. Trong lịch học D7: chọn một use case giá trị cao để đo hiệu suất workflow trước và sau khi áp dụng AI."},{"t":"creep","vi":"Bò, trườn dần. Trong quản lý dự án đi trong cụm scope creep — phạm vi phình dần."},{"t":"scope creep","vi":"Phình phạm vi: yêu cầu cứ được thêm dần mà không điều chỉnh thời gian/nguồn lực/phê duyệt. Glossary của khóa AI dẫn khái niệm này (PMBOK) khi bàn về stage-gate cho dự án chuyển đổi AI."},{"t":"system hints","vi":"Các <b>tín hiệu nhỏ hệ thống chèn vào<\/b> vòng lặp của coding agent (dấu thời gian, số lượt gọi tool đã dùng, thông báo lỗi chi tiết). Trong khóa AI: chúng định hình cách agent tiếp cận code và đổi hành vi nhiều hơn ta tưởng.","aka":["system hint"]},{"t":"hints","vi":"Gợi ý, tín hiệu nhắc. Trong khóa AI thường đi trong cụm <i>system hints<\/i>: thông tin nền được chèn vào context để định hướng hành vi của agent.","aka":["hint"]},{"t":"example_with_system_hints.py","vi":"File ví dụ (Python) trong lab của khóa AI, minh họa cách chèn <i>system hints<\/i> (dấu thời gian, đếm lượt gọi tool, lỗi chi tiết) vào vòng lặp agent và hành vi agent thay đổi ra sao."},{"t":"cache hit rate","vi":"Tỷ lệ request được phục vụ từ cache thay vì tính lại. Với LLM, prefix prompt giữ nguyên thì trúng KV cache, rẻ và nhanh hơn; hit rate ảnh hưởng trực tiếp tới chi phí khi scale agent.","aka":["hit rate"]},{"t":"hit","vi":"Lần trúng (tìm thấy trong cache). Trong khóa AI dùng trong <i>cache hit rate<\/i>: phần prompt trùng prefix cũ được lấy từ cache nên rẻ và nhanh hơn.","aka":["hits"]},{"t":"HLD","vi":"Tài liệu <b>thiết kế mức cao<\/b>: các khối chính, interface, luồng dữ liệu, triển khai, chưa đi vào chi tiết code. Trong lịch học, HLD template là một mẫu tài liệu dùng cho assignment/capstone.","aka":["HLDs"],"full":"High-Level Design","cs":true},{"t":"Hoare logic","vi":"Hệ logic do Tony Hoare đề xuất để chứng minh chương trình đúng bằng bộ ba {tiền điều kiện} lệnh {hậu điều kiện}. Glossary khóa AI gợi ý tra để hiểu <i>invariant<\/i>, precondition/postcondition trong context artifact.","aka":["Hoare"]},{"t":"KILOMETERS_PER_HOUR","vi":"Hằng số đơn vị km/h trong VHAL (Android Automotive). Ví dụ trong bài: validation rule bắt property tốc độ phải có unit == KILOMETERS_PER_HOUR, kiểm được bằng máy chứ không bằng cảm tính.","cs":true},{"t":"hours","vi":"Giờ (đơn vị thời gian). Trang lịch học: yêu cầu dành ít nhất 9 giờ mỗi tuần để học.","aka":["hour"]},{"t":"how","vi":"Như thế nào, cách làm. Trong bài: “học chữ why, không chỉ chữ how” — hiểu vì sao cách làm đúng, không chỉ thuộc thao tác."},{"t":"hvac","vi":"Tên thư mục/module HVAC (điều hòa, sưởi, thông gió) trong repo ví dụ của khóa AI, như <i>hvac/<\/i>, <i>hal/hvac/<\/i>. Dùng để minh họa việc ghi bản đồ module vào CLAUDE.md giúp agent tìm đúng chỗ.","cs":true},{"t":"VENDOR_HVAC_SEAT_TEMP_LV","vi":"Tên một vendor property VHAL ví dụ (mức nhiệt ghế của module HVAC), đặt theo quy ước VENDOR_*. Bài dùng nó để minh họa: với người là “một chữ” nhưng tokenizer cắt thành nhiều token; và để review đúng quy ước đặt tên.","aka":["_HVAC"],"cs":true},{"t":"trace id","vi":"<b>Mã vết<\/b> gắn cho mỗi yêu cầu gốc và đi xuyên suốt mọi bước/agent/log. Trong khóa AI: điều kiện tối thiểu cho observability của workflow nhiều agent, giúp lọc và replay đúng luồng bị hỏng.","aka":["trace-id"]},{"t":"IDC","vi":"Tên viết tắt một thành phần/dịch vụ trong hệ thống của đề tài OJT boot trên SoC Telechips (trang không ghi tên đầy đủ). Trong bài: một phụ thuộc trong trình tự boot cần phân tích, cùng với H.264, CGI, SOME/IP.","cs":true},{"t":"identify","vi":"Xác định, nhận diện. Trang syllabus: mục đích của syllabus là thiết kế topic, xác định mục tiêu, lịch và cách đánh giá.","aka":["identifies"]},{"t":"ignore previous instructions","vi":"“Bỏ qua các chỉ dẫn trước đó” — câu kinh điển của <b>prompt injection<\/b>. Ví dụ trong bài: dòng này nằm trong file Excel spec của đối tác; agent đọc phải được giới hạn quyền để không làm theo."},{"t":"ignore","vi":"Bỏ qua, phớt lờ. Trong bài thường gặp trong câu tấn công prompt injection “ignore previous instructions…”.","aka":["ignores","ignored"]},{"t":"implementable","vi":"Khả thi để triển khai, làm được trong thực tế. Syllabus: đề xuất phương án implementable, phù hợp chuẩn và governance của dự án."},{"t":"implication","vi":"Hệ quả, ý nghĩa rút ra. Trong Assignment 3/review C.6: implication là điều bạn sẽ làm khác trong dự án nhờ kết quả nghiên cứu, phải cụ thể (ví dụ thêm một phép đo).","aka":["implications"]},{"t":"incentive misalignment","vi":"<b>Lệch động cơ<\/b>: làm điều đúng lại gây thiệt cho người ra quyết định (ví dụ bị đánh giá kém hơn). Glossary khóa AI xem đây là một dạng kháng cự khi chuyển đổi AI cần xử lý bằng cách đổi thước đo."},{"t":"incentive","vi":"Động cơ khuyến khích (thưởng, đánh giá, lợi ích). Trong khóa AI đi trong cụm <i>incentive misalignment<\/i>.","aka":["incentives"]},{"t":"increment","vi":"Phần tăng thêm, bước làm nhỏ. Trong OJT F.2: làm từng increment nhỏ → đo lại → ghi nhật ký → điều chỉnh; viết sẵn điều kiện dừng (ví dụ sau 2 increment không cải thiện thì dừng).","aka":["increments"]},{"t":"independently","vi":"Một cách độc lập, tự làm không cần dẫn dắt. Trong outcome: tự nghiên cứu, tự đóng khung một bài toán kiến trúc mơ hồ."},{"t":"indirect prompt injection","vi":"Chỉ thị độc hại <b>nằm trong nội dung agent đọc<\/b> (spec, PDF, README, email bên thứ ba) chứ không do người dùng gõ. Trong khóa AI: loại nguy hiểm nhất với dự án ô tô vì agent đọc file đối tác hằng ngày."},{"t":"indirect","vi":"Gián tiếp. Trong khóa AI đi trong cụm <i>indirect prompt injection<\/i>: tấn công qua nội dung agent đọc."},{"t":"influence","vi":"Ảnh hưởng, tác động tới người khác. Syllabus: thuyết phục stakeholder và bảo vệ khuyến nghị bằng evidence.","aka":["influences"]},{"t":"innovation","vi":"Đổi mới, sáng tạo. Xuất hiện trong tên khóa tự học “Industry Primer for Automotive: Technology, Innovation and AI”."},{"t":"instruction","vi":"Chỉ dẫn, hướng dẫn. Trong khóa AI: lời dặn viết cho agent (CLAUDE.md, skill, custom instructions) — chỉ là gợi ý, không phải ràng buộc cứng như permission/hook.","aka":["instructions"]},{"t":"instructor","vi":"Giảng viên. Syllabus: “Instructor slide deck” là bộ slide của giảng viên.","aka":["instructors"]},{"t":"instructor-led","vi":"Có giảng viên dẫn dắt (khác tự học). Ghi chú cho khóa “Introduction to Automotive SPICE v4.0” trong lịch học."},{"t":"instrument cluster","vi":"<b>Cụm đồng hồ<\/b> sau vô-lăng hiển thị tốc độ, cảnh báo… Ví dụ trong khóa AI: thêm signal tốc độ xe lên instrument cluster như một nhiệm vụ cộng tác với AI."},{"t":"instrument","vi":"Dụng cụ đo; trong ô tô thường là <i>instrument cluster<\/i> (cụm đồng hồ).","aka":["instruments"]},{"t":"integrating","vi":"Tích hợp, ghép nối. Syllabus: phân tích luồng runtime đầu-cuối tích hợp boot, IPC/shared memory, xử lý CAN và evidence hiệu năng.","aka":["integrate","integrates"]},{"t":"stakeholder intent","vi":"<b>Ý định/nhu cầu thật của stakeholder<\/b>: bối cảnh xe, nhu cầu, điều kiện vận hành và giới hạn — tầng trên cùng trước khi viết system requirement."},{"t":"intent","vi":"Ý định, mục đích. Trong bài: <i>stakeholder intent<\/i> — điều stakeholder thật sự cần, làm gốc để truy vết requirement.","aka":["intents"]},{"t":"inter-rater agreement","vi":"<b>Mức nhất quán giữa các người chấm độc lập<\/b> (người hoặc model). Trong khóa AI: dùng để kiểm LLM-judge có chấm giống người review không trước khi tin điểm của nó.","aka":["inter-rater reliability"]},{"t":"inter-rater","vi":"Giữa các người chấm. Đi trong cụm <i>inter-rater agreement<\/i>: độ đồng thuận giữa các người chấm."},{"t":"intermediate","vi":"Trung cấp (giữa beginner và advanced). Syllabus: mức kỹ năng Level 2: Intermediate."},{"t":"interpretation","vi":"Diễn giải, suy luận của bạn dựa trên fact. Trong Assignment 3/C.6: mỗi câu kết luận phải gắn nhãn fact (có nguồn) hoặc interpretation (kèm lập luận và mức chắc chắn).","aka":["interpretations"]},{"t":"confidence interval","vi":"<b>Khoảng tin cậy<\/b>: khoảng giá trị hợp lý cho giá trị thật, tính từ mẫu. Trong khóa AI: chênh 3% trên 20 mẫu thường nằm trong khoảng này nên chưa kết luận được gì.","aka":["confidence intervals"]},{"t":"interval","vi":"Khoảng (giá trị hoặc thời gian). Trong khóa AI đi trong cụm <i>confidence interval<\/i>.","aka":["intervals"]},{"t":"interview","vi":"Phỏng vấn, vấn đáp. Trong OJT/lịch học: buổi vấn đáp 60 phút cuối khóa (F.3, Day 71) chấm theo LO7.","aka":["interviews"]},{"t":"introduction","vi":"Giới thiệu, nhập môn. Thường đứng đầu tên bài/khóa, ví dụ “Introduction to AI Collaboration”, “SDV 101: Introduction to Software Defined Vehicles”."},{"t":"invariant","vi":"<b>Bất biến<\/b>: tính chất luôn phải đúng ở mọi thời điểm. Glossary khóa AI: mục hay bị thiếu nhất trong context artifact — phải ghi rõ để agent không phá vỡ.","aka":["invariants"]},{"t":"involve","vi":"Bao gồm, đòi hỏi tham gia. Syllabus: kỹ năng nền tảng ô tô đòi hỏi làm chủ thực hành (hands-on mastery).","aka":["involves","involved"]},{"t":"interrupt service routine","vi":"<b>Hàm xử lý ngắt<\/b>: chạy khi phần cứng báo ngắt, phải ngắn và không chặn. Glossary khóa AI xếp vào vùng ĐỎ (agent không tự quyết), cần chuyên gia embedded.","aka":["isr"]},{"t":"json","vi":"JSON viết thường: định dạng dữ liệu có cấu trúc dạng khóa–giá trị. Trong khóa AI: đầu ra máy đọc được (json, exit code, kết quả test) mới là thứ verifier tự động kiểm được.","cs":true},{"t":"JSON schema","vi":"Bản mô tả cấu trúc hợp lệ của dữ liệu JSON (field bắt buộc, kiểu, enum). Trong khóa AI: guardrail hiệu quả là kiểm tra output theo schema và fail đóng khi parse lỗi."},{"t":"judge","vi":"Người/model chấm điểm. Trong khóa AI thường là <i>LLM-judge<\/i>: dùng model để chấm output theo rubric.","aka":["judges"]},{"t":"LLM-judge","vi":"Dùng <b>một LLM để chấm<\/b> output của agent theo rubric. Khóa AI: chỉ dùng ở tầng 3 (điều không kiểm được bằng máy), phải hiệu chỉnh với người review; bắt đầu bằng LLM-judge là sai.","aka":["LLM judge","LLM-judges"]},{"t":"LLM-as-a-judge","vi":"Kỹ thuật dùng model chấm output theo rubric (cùng nghĩa LLM-judge). Khóa AI dạy cả cách dùng lẫn giới hạn: judge có thể sai, thiên vị, nên chỉ hữu ích ở tầng 3 của eval."},{"t":"junior","vi":"Kỹ sư mới, ít kinh nghiệm. Khóa AI: junior chưa có phán đoán kiến trúc để ngoại hóa tri thức cho agent, nên khóa nhắm SA/PTL đã có kinh nghiệm domain.","aka":["juniors"]},{"t":"justify","vi":"Biện minh, chứng minh là hợp lý bằng lập luận và evidence. LO7: bảo vệ và lý giải quyết định kiến trúc.","aka":["justified"]},{"t":"kick off","vi":"Khởi động, buổi mở đầu (cùng nghĩa kick-off). Lịch học: Day 0 là buổi Kick off – Leader sharing về vai trò senior trong mảng CDC."},{"t":"domain knowledge","vi":"<b>Kiến thức nghiệp vụ/chuyên ngành<\/b> (ô tô, VHAL, spec OEM…). Khóa AI: chính người có domain knowledge mới tinh chỉnh được business rule và đóng gói nó thành context nạp cho agent."},{"t":"knowledge base","vi":"<b>Kho tài liệu nền<\/b> mà trợ lý AI được nạp để tham khảo (ví dụ trong một Project). Khóa AI: phân biệt với custom instructions và lịch sử hội thoại."},{"t":"knowledge","vi":"Kiến thức, tri thức. Trong khóa thường đi trong <i>domain knowledge<\/i> (kiến thức nghiệp vụ) và <i>knowledge base<\/i>."},{"t":"Kotter","vi":"John Kotter, giáo sư Harvard, tác giả <i>Leading Change<\/i> (1996) với mô hình 8 bước dẫn dắt thay đổi. Glossary khóa AI dẫn để đọc về kháng cự khi chuyển đổi AI."},{"t":"Leading Change","vi":"Sách/bài báo của John Kotter về dẫn dắt thay đổi tổ chức. Khóa AI gợi ý đọc để hiểu kháng cự và cách đưa AI vào team."},{"t":"KPI","vi":"<b>Chỉ số hiệu quả chính<\/b>. Khóa AI cảnh báo: KPI đếm token/prompt/giấy phép là đo hoạt động, không phải outcome; phải đo kết quả (thời gian, lỗi sót, chất lượng).","aka":["KPIs"],"full":"Key Performance Indicator","cs":true},{"t":"KV cache","vi":"Bộ nhớ đệm khóa–giá trị (key/value) của LLM, lưu tính toán cho phần đầu prompt không đổi. Prefix đổi một dòng là vỡ cache, chi phí tăng; lab kv-cache trong khóa AI minh họa điều này.","aka":["kv-cache","KV-cache"]},{"t":"lab3","vi":"Các <b>bài lab đánh số<\/b> trong khóa AI (lab1 = ablation context, lab3 = test cho rule nhỏ, lab6 = verifier…), mỗi lab gắn với một bài tập BT. Tên như lab1_ablation là thư mục/code của lab.","aka":["lab1","lab2","lab4","lab5","lab6","lab7","lab1_ablation","lab6_verifier"]},{"t":"leading vs lagging indicator","vi":"Phân biệt <b>chỉ số dự báo<\/b> (leading, báo trước vấn đề) và <b>chỉ số trễ<\/b> (lagging, ghi nhận khi đã xảy ra). Khóa AI và bài quality governance: cần cả hai để điều chỉnh kịp.","aka":["leading vs lagging indicators"]},{"t":"lagging indicator","vi":"<b>Chỉ số trễ<\/b>: đo kết quả đã xảy ra (lỗi ngoài hiện trường, số xe bị ảnh hưởng, thời gian khắc phục). Chính xác nhưng biết thì đã muộn, nên phải đi kèm leading indicator.","aka":["lagging indicators"]},{"t":"lagging","vi":"Trễ, đi sau. Trong bài: <i>lagging indicator<\/i> — chỉ số chỉ biết khi sự việc đã xảy ra."},{"t":"LangChain","vi":"Framework mã nguồn mở để xây ứng dụng LLM bằng cách nối chuỗi (chain) model, prompt, tool. Khóa AI nêu như tên đáng biết khi chọn framework; khóa dùng Claude Code làm công cụ chính."},{"t":"LangGraph","vi":"Thư viện cùng hệ LangChain, mô tả workflow agent dưới dạng đồ thị trạng thái (node, cạnh, vòng lặp). Được nhắc trong khóa AI khi so sánh framework multi-agent."},{"t":"LlamaIndex","vi":"Framework thiên về RAG: nạp, đánh chỉ mục và truy xuất tài liệu cho LLM. Khóa AI nhắc cùng Haystack như lựa chọn khi bài toán chủ yếu là tra cứu tài liệu."},{"t":"language","vi":"Ngôn ngữ. Syllabus: điều kiện ngoại ngữ là một tiêu chí xét lên rank, đánh giá riêng ngoài khóa.","aka":["languages"]},{"t":"lazy loading","vi":"<b>Nạp lười<\/b>: hoãn việc lấy dữ liệu tới đúng lúc cần. Khóa AI áp vào context: chỉ nạp tài liệu/skill khi task cần, để context gọn và rẻ."},{"t":"lazy","vi":"Lười, trì hoãn. Đi trong cụm <i>lazy loading<\/i>: chỉ nạp khi cần."},{"t":"loading","vi":"Việc nạp/tải dữ liệu. Trong khóa AI đi trong <i>lazy loading<\/i>."},{"t":"leader","vi":"Người lãnh đạo, trưởng nhóm. Lịch học: buổi “Kickoff Leader sharing” — lãnh đạo chia sẻ mục tiêu chương trình và kỳ vọng với vai trò senior.","aka":["leaders"]},{"t":"leadership","vi":"Khả năng/lớp lãnh đạo. Trong bài vừa là kỳ vọng về technical leadership của senior, vừa chỉ ban lãnh đạo nhận báo cáo (nói quá con số là mất lòng tin)."},{"t":"leak","vi":"Rò rỉ. Trong bài ô tô thường là memory leak (bộ nhớ cấp phát không trả lại, app chậm dần rồi treo); sửa leak cần kèm memory budget và ranh giới trách nhiệm.","aka":["leaks"]},{"t":"data leakage","vi":"<b>Rò rỉ dữ liệu<\/b>: dữ liệu nhạy cảm (code OEM, spec đối tác, log có VIN) đi ra khỏi môi trường kiểm soát, kể cả qua prompt hoặc log. Một trong các rủi ro chính khi dùng AI."},{"t":"leakage","vi":"Sự rò rỉ. Trong khóa AI đi trong cụm <i>data leakage<\/i>: dữ liệu nhạy cảm lọt ra ngoài."},{"t":"Lean Startup","vi":"Sách của Eric Ries (2011) về thử nghiệm nhanh và đo đúng. Khóa AI dẫn chương về <i>vanity metrics<\/i>: con số đẹp (số token, số người mở tool) nhưng không đo kết quả.","aka":["The Lean Startup"]},{"t":"lean","vi":"Tinh gọn, bỏ lãng phí (triết lý Lean từ sản xuất Toyota). Glossary khóa AI dẫn sách Lean để học đo đúng và tìm nút thắt."},{"t":"LeanEnterprise","vi":"Lean Enterprise Institute — tổ chức phổ biến phương pháp Lean. Glossary khóa AI gợi ý tra “value stream mapping” trên trang này.","aka":["Lean Enterprise Institute"]},{"t":"learners","vi":"Người học, học viên. Syllabus: học viên củng cố thiết kế giải pháp, đánh giá công nghệ, prototyping…","aka":["learner"]},{"t":"lecture","vi":"Bài giảng lý thuyết trên lớp. Syllabus: mục Concept/Lecture trong phân bổ thời gian (ở khóa này 0%, chủ yếu tự học).","aka":["lectures"]},{"t":"legal","vi":"Pháp chế, bộ phận pháp lý. Khóa AI: câu hỏi IP, hợp đồng, NDA khi dùng AI thuộc legal/compliance (FPT) quyết định, kỹ sư không tự quyết."},{"t":"Level-3 gate","vi":"<b>Ba cổng đạt Cấp 3<\/b> của khóa AI: tuần 5 đồng nghiệp dùng lại được artifact; tuần 11 người ngoài nhóm chạy được workflow từ runbook; tuần 12 bảo vệ triển khai, metric có dashboard, qua vấn đáp.","aka":["Level-3 gates","Level-3"]},{"t":"licensed","vi":"Có bản quyền/giấy phép. Lịch học: “Self-study (Coursera – licensed)” là khóa Coursera công ty đã mua license cho học viên."},{"t":"lifecycle-aware","vi":"Có tính tới toàn vòng đời (phát triển, bảo trì, cập nhật, hết hỗ trợ). Syllabus: đề xuất giải pháp mở rộng được và lifecycle-aware."},{"t":"limitation","vi":"Giới hạn, hạn chế. Trong OJT: ghi limitation trung thực (ví dụ “chỉ hỗ trợ định dạng mới”) kèm điều kiện dùng, không che giấu.","aka":["limitations"]},{"t":"LinkedIn","vi":"Mạng xã hội nghề nghiệp; LinkedIn Learning là nền tảng khóa học trực tuyến. Lịch học có khóa tự học qua Viva Learning / LinkedIn.","aka":["LinkedIn Learning"]},{"t":"Lipton","vi":"Richard Lipton, đồng tác giả (DeMillo, Lipton &amp; Sayward, 1978) bài báo đặt nền cho <i>mutation testing<\/i>. Glossary khóa AI dẫn nguồn này."},{"t":"LL-02","vi":"Mã đánh số <b>lesson learned<\/b> (LL-01, LL-02…) trong nhật ký OJT. Mỗi mục ghi sự kiện, nguyên nhân đã kiểm chứng, bài học và hành động đã chuyển thành (ví dụ thêm phiên bản SDK vào context AI).","aka":["LL-01","LL-03","LL-04"],"cs":true},{"t":"LLM","vi":"<b>Mô hình ngôn ngữ lớn<\/b> (như Claude) sinh văn bản bằng cách đoán token tiếp theo. Trong khóa AI: Agent = LLM + Context + Tools; LLM là phần đắt, không tất định, nên luật kiểm được thì giao cho máy.","aka":["LLMs","Llm"],"full":"Large Language Model","cs":true},{"t":"OWASP LLM Top 10","vi":"Danh sách 10 rủi ro bảo mật hàng đầu cho ứng dụng LLM do OWASP công bố (miễn phí). Mục LLM01 là prompt injection; glossary khóa AI dẫn làm tài liệu đọc.","aka":["OWASP Top 10 for LLM"]},{"t":"LLM01","vi":"Mục số 1 trong OWASP LLM Top 10: <b>Prompt Injection<\/b> — chỉ thị độc hại chèn vào input hoặc nội dung agent đọc để điều khiển model.","cs":true},{"t":"LO1","vi":"Mã <b>kết quả học tập<\/b> trong syllabus: LO1 phân tích ràng buộc nghiệp vụ/lifecycle/an ninh; LO2 thiết kế kiến trúc CDC/SDV; LO3 so sánh phương án; LO4 ảo hóa, mixed-criticality; LO5 dùng AI có quản trị; LO6 verification/đo/triển khai AI; LO7 bảo vệ quyết định trước hội đồng.","aka":["LO2","LO3","LO4","LO5","LO6","LO7"],"full":"Learning Outcome","cs":true},{"t":"log sanitization","vi":"<b>Làm sạch log<\/b>: lọc bỏ dữ liệu nhạy cảm (VIN, key, đường dẫn nội bộ) trước khi log rời máy. Khóa AI: bắt buộc vì log gửi cho agent/cloud là kênh rò rỉ hay bị quên.","aka":["log-sanitization"]},{"t":"main","vi":"Chính, chủ yếu. Ví dụ: “defend the main conclusions” — bảo vệ các kết luận chính."},{"t":"make","vi":"Làm, tạo ra. Syllabus: “make schedule” — lập lịch.","aka":["makes"]},{"t":"managed settings","vi":"Cấu hình do <b>tổ chức quản lý tập trung<\/b> cho Claude Code (permission, hook…), người dùng không ghi đè được. Khóa AI: dùng để cưỡng chế chính sách cho cả team thay vì lời dặn CLAUDE.md.","aka":["managed setting"]},{"t":"managed policy settings","vi":"Tên đầy đủ của cơ chế managed settings: file chính sách do quản trị viên đặt ở cấp máy/tổ chức, có hiệu lực cao nhất. Một lớp cưỡng chế bằng hạ tầng cùng hook và permission."},{"t":"managed","vi":"Được quản lý. Trong khóa AI đi trong <i>managed settings<\/i> — cấu hình do tổ chức áp xuống, không phải từng người tự đặt."},{"t":"managing","vi":"Quản lý, điều hành. Syllabus: chuyên môn phát triển và quản lý nền tảng ô tô, đặc biệt CDC.","aka":["manage","manages"]},{"t":"marking","vi":"Chấm điểm. Syllabus: mục “Marking” trong phần quy định đánh giá (ở đây n/a)."},{"t":"mastery","vi":"Sự thành thạo, làm chủ. Syllabus: “hands-on mastery” — làm chủ bằng thực hành."},{"t":"matcher","vi":"Bộ lọc khớp. Trong Claude Code hook: matcher chọn lời gọi tool nào (ví dụ Bash, Edit) thì hook được áp dụng.","aka":["matchers"]},{"t":"maturity","vi":"Độ trưởng thành, mức chín muồi. Syllabus: đánh giá maturity của hệ sinh thái công nghệ trước khi chọn."},{"t":"min_spec","vi":"Giới hạn dưới/trên lấy từ spec đã duyệt. Validation rule trong bài: min_spec ≤ min ≤ max ≤ max_spec — dải giá trị không tự đặt mà lấy từ spec.","aka":["max_spec"]},{"t":"min","vi":"Viết tắt minimum — giá trị nhỏ nhất. Trong khóa AI: quy tắc cảm tính phải đổi thành regex, enum, min/max kiểm được bằng máy."},{"t":"MCP","vi":"Giao thức mở để kết nối agent với tool và nguồn dữ liệu bên ngoài qua <b>MCP server<\/b>. Khóa AI: một nhóm tool cần thiết kế và quản quyền; phiên bản MCP server cũng phải ghi lại.","aka":["MCP server","MCP servers"],"full":"Model Context Protocol","cs":true},{"t":"medium-complexity","vi":"Độ phức tạp trung bình. Trong OJT/syllabus: đề tài và việc kỹ thuật ở mức medium-complexity, phạm vi khoảng một module, có quyết định kiến trúc thật."},{"t":"members","vi":"Thành viên. Syllabus: chuẩn bị cho senior members lên rank tiếp theo.","aka":["member"]},{"t":"memory-based injection","vi":"Chỉ thị độc hại <b>được lưu vào bộ nhớ của agent<\/b> và kích hoạt ở phiên sau. Một trong ba loại prompt injection trong khóa AI."},{"t":"memory-based","vi":"Dựa trên bộ nhớ. Đi trong cụm <i>memory-based injection<\/i>."},{"t":"mentee","vi":"Người được kèm cặp (đối lại mentor). Trong khóa: học viên báo cáo tiến độ, trình bày kết quả và nhận phản biện ở các buổi Mentor–Mentee review.","aka":["mentees"]},{"t":"Meyer","vi":"Bertrand Meyer, tác giả <i>Object-Oriented Software Construction<\/i> và khái niệm Design by Contract. Glossary khóa AI dẫn để học precondition/postcondition."},{"t":"mindset","vi":"Tư duy, cách nghĩ. Syllabus: xây “AI-first engineering mindset”."},{"t":"minimal","vi":"Tối giản, nhỏ nhất có thể. Ví dụ: chọn kiến trúc agent minimal; minimal cut set trong FTA."},{"t":"minimum viable architecture","vi":"<b>Kiến trúc tối thiểu khả dụng<\/b>: cấu trúc đơn giản nhất còn giải quyết được bài toán. Khóa AI: bắt đầu từ đây, chỉ leo thang lên multi-agent khi có số đo chứng minh."},{"t":"minimum","vi":"Tối thiểu. Đi trong <i>minimum viable architecture<\/i>."},{"t":"mins","vi":"Viết tắt minutes — phút. Syllabus ghi thời lượng theo phút, ví dụ Duration (mins), 90mins.","aka":["0mins","30mins","90mins","180mins","390mins","4920mins"]},{"t":"misalignment","vi":"Sự lệch, không đồng hướng. Đi trong <i>incentive misalignment<\/i>."},{"t":"ML","vi":"<b>Học máy<\/b>: máy học quy luật từ dữ liệu thay vì viết luật bằng tay. Khóa AI: AI → ML → generative AI → LLM → agent; routing có thể dùng một model ML nhỏ thay LLM.","full":"Machine Learning","cs":true},{"t":"model benchmark","vi":"Đo so sánh các model trên cùng bộ việc (chất lượng, độ trễ, chi phí). Lab model-benchmark trong khóa AI: chênh 3% trên 20 mẫu chưa đủ kết luận.","aka":["model-benchmark"]},{"t":"MR-01","vi":"Mã dòng trong <b>maintenance risk register<\/b> (MR-01, MR-02…) của bài Cybersecurity &amp; long-term maintenance. Mỗi dòng: component, hạn hỗ trợ, rủi ro, chiến lược, owner, ngày review, evidence.","aka":["MR-02","MR-03"],"cs":true},{"t":"10ms","vi":"10 mili giây. Ví dụ trong khóa AI: hai service ghi cùng property trong cửa sổ 10ms — bài toán nhiều ràng buộc đan xen.","cs":true},{"t":"multi-agent","vi":"Kiến trúc <b>nhiều agent phối hợp<\/b>. Khóa AI: bậc cao nhất trên thang kiến trúc, chỉ đáng dùng khi cộng tác tạo ra thông tin một agent không tự lấy được; đừng chọn vì “oai”.","aka":["multi-agents","multi agent"]},{"t":"multiple","vi":"Nhiều. Syllabus: bài toán trải trên nhiều domain hoặc nhiều team."},{"t":"mutation testing","vi":"<b>Kiểm thử đột biến<\/b>: cố tình chèn lỗi vào code để xác nhận bộ test thật sự phát hiện được. Khóa AI dùng để chứng minh verifier/gate có thể đỏ."},{"t":"mutation","vi":"Đột biến, thay đổi cố ý. Đi trong <i>mutation testing<\/i>.","aka":["mutations","mutant"]},{"t":"NAME_PATTERN","vi":"Hằng regex quy ước tên vendor property VHAL trong validator ví dụ. Skill review kiểm tên theo NAME_PATTERN trước, rồi unit, access mode.","cs":true},{"t":"name","vi":"Tên. Syllabus: Topic Name — tên khóa/chủ đề.","aka":["names"]},{"t":"NDA","vi":"<b>Thỏa thuận bảo mật<\/b>. Khóa AI: file từ Tier-1 supplier chịu NDA riêng, không được tự ý đưa vào tool AI ngoài phạm vi; hỏi legal khi chưa rõ.","aka":["NDAs"],"full":"Non-Disclosure Agreement","cs":true},{"t":"never","vi":"Không bao giờ. Syllabus: xác định dữ liệu AI tuyệt đối không được nhận."},{"t":"next token prediction","vi":"<b>Đoán token tiếp theo<\/b> dựa trên xác suất — cơ chế sinh văn bản của LLM. Vừa tạo sáng tạo vừa là gốc của hallucination."},{"t":"next","vi":"Tiếp theo. Ví dụ: next job rank (bậc kế tiếp), next token prediction."},{"t":"NL2SQL","vi":"Dịch câu hỏi ngôn ngữ tự nhiên thành truy vấn SQL (text-to-SQL). Glossary khóa AI dùng làm ví dụ kinh điển của agent truy vấn dữ liệu (lab erp-agent).","full":"Natural Language to SQL","cs":true},{"t":"Node.js","vi":"Môi trường chạy JavaScript ngoài trình duyệt. Là yêu cầu để cài Claude Code theo hướng dẫn chính thức."},{"t":"non-delegable judgment","vi":"<b>Phán đoán không ủy quyền được<\/b> — loại 3 trong tam phân Máy/Agent/Người: hậu quả sai không phát hiện kịp hoặc trách nhiệm không chuyển được, nên người phải quyết."},{"t":"non-delegable","vi":"Không thể ủy quyền. Đi trong <i>non-delegable judgment<\/i> — việc người phải tự quyết."},{"t":"non-vacuous test","vi":"Test/cổng <b>đã được chứng minh là có thể đỏ<\/b>. Khóa AI: cổng không bao giờ đỏ là cổng vô nghĩa; chứng minh bằng mutation hoặc ca sai cố ý.","aka":["non-vacuous tests"]},{"t":"non-vacuous","vi":"Không rỗng nghĩa, kiểm tra thật. Đi trong <i>non-vacuous test<\/i>."},{"t":"none","vi":"Không có. Ví dụ: “Unit Detail: None” — trang không có chi tiết cho unit đó."},{"t":"Nov","vi":"Tháng 11 (viết tắt của November).","aka":["November"]},{"t":"null","vi":"Giá trị rỗng/không có trong lập trình. Ví dụ task rõ ràng cho agent: “thêm kiểm tra null cho tham số đầu vào của hàm parse, kèm test”."},{"t":"Object-Oriented Software Construction","vi":"Sách kinh điển của Bertrand Meyer về thiết kế hướng đối tượng và Design by Contract. Glossary khóa AI dẫn để học precondition/postcondition."},{"t":"object-oriented","vi":"Hướng đối tượng (lập trình theo class/object)."},{"t":"objectivity","vi":"Tính khách quan. Khóa AI: Verifiability &amp; Objectivity — kiểm tra phải dựa trên dữ liệu có cấu trúc, không dựa cảm giác."},{"t":"obligations","vi":"Nghĩa vụ. Glossary khóa AI: “EU AI Act transparency obligations” — nghĩa vụ minh bạch khi dùng AI (điều 50).","aka":["obligation"]},{"t":"obtain","vi":"Đạt được, xin được. Syllabus: “Obtain approval for the capstone topic” — được duyệt đề tài capstone.","aka":["obtains","obtained"]},{"t":"Oct","vi":"Tháng 10 (viết tắt của October).","aka":["October"]},{"t":"ODC","vi":"Trung tâm phát triển phần mềm ở nước ngoài (offshore) làm riêng cho một khách hàng theo hợp đồng dài hạn. Trong khóa: nhiều dự án FPT là ODC cho OEM/Tier-1, nên quy định dữ liệu và việc dùng AI là điều khoản hợp đồng — vi phạm có thể chấm dứt cả hợp đồng ODC.","aka":["ODCs"],"full":"Offshore Development Center","cs":true},{"t":"official","vi":"Chính thức (do tổ chức ban hành, không phải bản nháp). Trong trang Kickoff: <i>Official Roadmap<\/i> là lộ trình chính thức của khóa, nguồn để đối chiếu yêu cầu từng Milestone."},{"t":"OpenTelemetry","vi":"Bộ chuẩn và thư viện mã nguồn mở để thu thập trace, metric, log từ phần mềm. Trong khóa (D6): tài liệu đọc ngoài để đo chi phí và độ trễ (p50/p95) theo từng bước chạy của agent."},{"t":"orchestrate","vi":"Điều phối: sắp xếp nhiều bước, nhiều tác nhân phối hợp thành một luồng. Trong khóa, Orchestrate là một trong năm chức năng vận hành agent (Context, Tools, Constrain, Verify, Orchestrate): quyết định bước nào cố định (workflow), bước nào để agent tự quyết.","aka":["orchestrates","orchestrating","orchestrated"]},{"t":"orchestrator-worker","vi":"Mẫu thiết kế multi-agent: một agent điều phối (orchestrator, còn gọi manager) chia việc con cho các agent thợ (worker) rồi gom kết quả. Hợp với việc chia nhỏ được, nhưng tốn token và khó debug hơn một agent đơn (D5).","aka":["orchestrator-worker pattern"]},{"t":"organizational","vi":"Thuộc về tổ chức (organisational là cách viết Anh-Anh). Ví dụ <i>organizational implications<\/i> = hệ quả đối với tổ chức (con người, quy trình, chi phí) của một quyết định kỹ thuật.","aka":["organisational"]},{"t":"organisational governance","vi":"Quản trị ở cấp tổ chức: cưỡng chế chính sách dùng AI bằng cấu hình tập trung (managed settings, permission, hook) áp cho mọi người, thay vì trông vào kỷ luật từng cá nhân. Chủ đề buổi D8 của khóa.","aka":["organizational governance"]},{"t":"out","vi":"Ra ngoài, nằm ngoài. Hay gặp trong cụm: <i>out of scope<\/i> (ngoài phạm vi), <i>fan-out<\/i> (một nguồn tỏa ra nhiều nơi nhận), <i>carve-out<\/i> (phần được cắt riêng ra)."},{"t":"out of scope","vi":"Ngoài phạm vi: những gì bài/dự án cố ý KHÔNG làm. Ghi rõ out of scope giúp khoanh vùng kiến trúc, người review biết ranh giới và tránh phình phạm vi (scope creep).","aka":["out-of-scope"]},{"t":"in scope","vi":"Trong phạm vi: phần việc được cam kết làm và sẽ được đánh giá. Trong assignment, ghi in scope / out of scope cụ thể (ví dụ: workload cockpit trên một SoC) thay vì “toàn bộ kiến trúc xe”.","aka":["in-scope"]},{"t":"outcome-based","vi":"Dựa trên kết quả (outcome) thay vì công sức bỏ ra. Trong khóa: đánh giá/hợp đồng outcome-based buộc định nghĩa rõ thế nào là “xong”, làm nguồn sự thật duy nhất cho agent và cho người nghiệm thu."},{"t":"outcome-based pricing","vi":"Cách tính giá theo kết quả bàn giao, đối lập với T&amp;M (Time &amp; Materials — tính theo người-tháng). Khóa (D7) so sánh hai cách vì năng suất nhờ AI có lợi cho bên nào phụ thuộc vào kiểu hợp đồng."},{"t":"outside","vi":"Bên ngoài. Trong syllabus: <i>assessed outside this course<\/i> = được đánh giá ở quy trình khác, không thuộc khóa này (ví dụ chứng chỉ cần cho thăng hạng)."},{"t":"over-claim","vi":"Tuyên bố quá mức: nói năng lực hay kết quả của AI lớn hơn bằng chứng đang có. Trong khóa đây là rủi ro hợp đồng thật, không phải chuyện văn phong — mọi tuyên bố về AI trong deliverable phải kèm bằng chứng kiểm chứng được.","aka":["over-claiming","over-claims","overclaim","overclaiming"]},{"t":"over-refusal","vi":"Từ chối quá mức: AI/agent từ chối một yêu cầu hợp lệ vì quá thận trọng. Là lớp lỗi mà nhiều bộ eval bỏ quên; bộ đánh giá tốt cần cả ca PHẢI từ chối lẫn ca KHÔNG được từ chối.","aka":["over-refusals"]},{"t":"overview","vi":"Tổng quan, cái nhìn bao quát. Trong bài: <i>overview diagram<\/i> là sơ đồ tổng thể trước khi vào component/flow chi tiết; tên khóa “Overview of …” là khóa giới thiệu tổng quan.","aka":["overviews"]},{"t":"OWASP","vi":"Tổ chức cộng đồng phi lợi nhuận về bảo mật phần mềm. <i>OWASP Top 10 for LLM<\/i> là danh sách 10 rủi ro hàng đầu của ứng dụng LLM (mục LLM01 là prompt injection) — tài liệu đọc miễn phí của buổi D0.","aka":["Owasp","OWASP LLM Top 10","Owasp Llm Top 10"],"full":"Open Worldwide Application Security Project","cs":true},{"t":"own","vi":"Sở hữu; (động từ) đứng ra chịu trách nhiệm chính. Trong learning outcome: <i>Own high-impact technical decisions<\/i> = tự quyết và chịu trách nhiệm cho các quyết định kỹ thuật có tác động lớn."},{"t":"pain point","vi":"Điểm đau: vấn đề cụ thể gây tốn thời gian, lỗi hay chi phí trong công việc thật. Đề tài OJT phải có pain point đo được (kèm baseline), không phải mục tiêu chung chung như “dùng AI cho nhanh hơn”.","aka":["pain points","pain-point"]},{"t":"pain","vi":"Nỗi đau, chỗ khó chịu. Trong khóa thường đi trong cụm <i>pain point<\/i> — vấn đề thực tế đo được mà đề tài cần giải quyết."},{"t":"PAM","vi":"Mô hình đánh giá quy trình của Automotive SPICE (bản v3.1 do VDA phát hành): mô tả các process, base practice và work product để chấm mức năng lực quy trình. Khóa dẫn làm tài liệu tham chiếu.","aka":["Pam"],"full":"Process Assessment Model","cs":true},{"t":"parallelization","vi":"Song song hóa: chạy nhiều tác vụ con độc lập cùng lúc rồi gộp kết quả. Là một mẫu trong Agentic Design Patterns (phần nâng cao sau khóa) — rút ngắn thời gian nhưng tăng chi phí token và độ phức tạp khi gộp.","aka":["parallelisation"]},{"t":"participation","vi":"Sự tham gia. Trong Kickoff: <i>Preparation &amp; participation<\/i> = chuẩn bị trước và góp ý tích cực trong thảo luận, là tiêu chí đạt của buổi."},{"t":"PDF","vi":"Portable Document Format — định dạng tài liệu giữ nguyên bố cục. Trong khóa: một loại nguồn đọc; lưu ý tài liệu PDF từ bên ngoài (spec, datasheet) mà agent đọc vào có thể chứa prompt injection gián tiếp."},{"t":"personal","vi":"Cá nhân. Trong năm nhãn dữ liệu của khách hàng (public, internal, confidential, personal, regulated), <i>personal<\/i> là dữ liệu cá nhân định danh được người, phải redaction trước khi đưa cho AI."},{"t":"perspectives","vi":"Góc nhìn. Trong syllabus: phân tích chủ đề từ góc nhìn business, engineering và Solution Architect.","aka":["perspective"]},{"t":"PII","vi":"Thông tin định danh cá nhân: dữ liệu đủ để nhận ra một người (tên, email, số điện thoại, VIN gắn chủ xe, vị trí…). Trong khóa: PII phải được xóa/che (redaction) trước khi dữ liệu rời máy hoặc tới dịch vụ AI.","aka":["Pii","pii"],"full":"Personally Identifiable Information","cs":true},{"t":"PII redaction","vi":"Xóa hoặc che thông tin định danh cá nhân khỏi log, tài liệu trước khi đưa cho AI hay dịch vụ bên ngoài. Nên làm bằng script tự động (việc của Máy) chứ không trông vào trí nhớ người.","aka":["Pii redaction"],"cs":true},{"t":"PIPA","vi":"Luật bảo vệ thông tin cá nhân của Hàn Quốc. Cùng GDPR (EU), là ví dụ luật ràng buộc data residency: dữ liệu nhóm regulated không được tùy tiện chuyển ra khỏi vùng tài phán, kể cả cho dịch vụ AI.","aka":["pipa","Pipa","Personal Information Protection Act"],"full":"Personal Information Protection Act","cs":true},{"t":"PMBOK","vi":"Bộ kiến thức chuẩn về quản lý dự án của PMI. Trong khóa (D7): tài liệu tra các khái niệm stage-gate, scope creep khi đưa AI vào dự án như một thay đổi có kiểm soát.","aka":["Pmbok","pmbok"],"full":"Project Management Body of Knowledge","cs":true},{"t":"context pollution","vi":"Context nhiễu: thông tin không liên quan hoặc đã lỗi thời chiếm chỗ trong cửa sổ context, làm agent mất tập trung, dùng sai quy ước hoặc bỏ sót chỉ dẫn quan trọng. Đối lập với relevant context."},{"t":"pollution","vi":"Ô nhiễm, làm bẩn. Trong khóa dùng trong cụm <i>context pollution<\/i>: cửa sổ context bị lẫn thông tin nhiễu, lỗi thời."},{"t":"post-training","vi":"Huấn luyện sau: huấn luyện tiếp một model có sẵn (ví dụ SFT, RL) trên dữ liệu riêng. Khóa chỉ giới thiệu để biết nó tồn tại — đây là việc của đội ML chuyên trách; khóa tập trung làm việc VỚI model có sẵn.","aka":["post training","posttraining"]},{"t":"precondition","vi":"Tiền điều kiện: điều phải đúng TRƯỚC khi một bước/hàm bắt đầu. Trong khóa (D1): context artifact nên ghi rõ precondition/postcondition của từng bước — mục hay bị thiếu nhất.","aka":["preconditions","pre-condition"]},{"t":"postcondition","vi":"Hậu điều kiện: điều phải đúng SAU khi bước/hàm chạy xong — dùng làm tiêu chí kiểm chứng kết quả. Khái niệm gốc từ Hoare logic trong khoa học máy tính.","aka":["postconditions","post-condition"]},{"t":"PreToolUse","vi":"Sự kiện hook của Claude Code chạy TRƯỚC khi agent dùng một tool. Là loại hook duy nhất chặn được hành động: script hook trả exit code 2 thì lời gọi tool bị chặn. Dùng để cưỡng chế luật cứng (cấm đọc .env, cấm push --force…).","aka":["Pretooluse"],"cs":true},{"t":"PostToolUse","vi":"Sự kiện hook của Claude Code chạy SAU khi tool đã chạy xong. Chỉ hợp để format, lint, ghi log — không chặn được vì hành động đã xảy ra; muốn chặn phải dùng PreToolUse.","aka":["Posttooluse"],"cs":true},{"t":"practice","vi":"Thực hành; cũng có nghĩa “thông lệ”. Trong lịch học: <i>Final Test – Practice<\/i> là bài thi cuối phần thực hành (khác <i>Final Test – Theory<\/i> là lý thuyết).","aka":["practices"]},{"t":"pre-read","vi":"Tài liệu gửi trước để người dự đọc trước buổi họp. Trong Mentor Review: mentee gửi pre-read cho mentor trước buổi, để thời gian buổi review dành cho phản biện chứ không phải đọc tại chỗ.","aka":["pre-reads","preread"]},{"t":"pre-test","vi":"Bài kiểm tra đầu vào làm trước khi học để đo mức xuất phát; so với Final Topic Test để thấy tiến bộ.","aka":["pretest","pre-tests"]},{"t":"pre-work","vi":"Phần chuẩn bị phải làm trước buổi học. Trong khóa AI: gói pre-work tuần 5 về Claude Code (repo mẫu có hook chặn file cấm, permission, quản trị tập trung) chuẩn bị cho lab D3–D4.","aka":["prework","pre-works"]},{"t":"precision","vi":"Độ chính xác của các lần báo dương: trong số ca hệ thống báo “có lỗi”, bao nhiêu ca đúng là lỗi thật. Ví dụ trong bài: báo 12, đúng 9 → precision 75%. Luôn xem cùng recall và ghi kèm mẫu số."},{"t":"prefix","vi":"Tiền tố, phần đứng đầu. Trong khóa có hai nghĩa: phần đầu tên property (ví dụ VENDOR_ trong VHAL) và phần đầu prompt không đổi được cache lại (prefix caching).","aka":["prefixes"]},{"t":"prefix caching","vi":"Tái dùng phần tính toán (KV cache) cho đoạn đầu prompt giống hệt lần trước, giúp rẻ và nhanh hơn. Đổi một chi tiết ở đầu là cache vỡ — nên phần cố định (system prompt, quy ước) đặt trước, phần thay đổi đặt sau.","aka":["prefix cache"]},{"t":"prepare","vi":"Chuẩn bị. Trong syllabus: <i>prepare senior members for advancement<\/i> = chuẩn bị cho kỹ sư senior lên rank tiếp theo; <i>preparing for promotion to DEV04<\/i> = đang chuẩn bị thăng hạng DEV04.","aka":["preparing","prepared","prepares"]},{"t":"previous","vi":"Trước đó. Câu “ignore previous instructions” (bỏ qua mọi chỉ dẫn trước) là mẫu prompt injection kinh điển, hay được giấu trong tài liệu mà agent đọc vào."},{"t":"pricing","vi":"Cách định giá, tính tiền. Trong khóa: so sánh T&amp;M (tính theo người-tháng) với outcome-based pricing (tính theo kết quả); cũng dùng khi tính giá dùng model theo token."},{"t":"primer","vi":"Tài liệu nhập môn ngắn giúp nắm nền tảng nhanh. Ví dụ khóa <i>Industry Primer for Automotive: Core Foundations<\/i> trong danh sách tự học.","aka":["primers"]},{"t":"principal-agent problem","vi":"Vấn đề người ủy quyền – người thừa hành (kinh tế học tổ chức): người làm thay có động cơ khác người giao việc. Trong khóa (D7): giải thích vì sao đội có thể âm thầm kháng cự AI khi lợi ích của họ lệch với mục tiêu tổ chức.","aka":["principal-agent"]},{"t":"process-driven prompt","vi":"Prompt viết theo quy trình (dạng SOP: bước 1, bước 2…) thay vì liệt kê các luật rời rạc. Khóa nhấn mạnh cách này giúp agent làm ổn định và dễ kiểm hơn.","aka":["process-driven"]},{"t":"process_data","vi":"Ví dụ tên tool tồi trong bài: tên và mô tả mơ hồ (“xử lý dữ liệu”) khiến agent gọi lung tung hoặc bỏ qua. Tool cần tên, mô tả nói rõ làm gì và khi nào dùng."},{"t":"produce","vi":"Tạo ra, đưa ra. Trong learning outcome: <i>Produce a clear… recommendation<\/i> = đưa ra khuyến nghị rõ ràng, có cơ sở kỹ thuật.","aka":["produces","produced"]},{"t":"progress","vi":"Tiến độ, sự tiến triển. Trong khóa thường gặp trong <i>Progress Tracker<\/i> — bảng theo dõi tiến độ học viên."},{"t":"Progress Tracker","vi":"Bảng theo dõi tiến độ của học viên: mỗi buổi/assignment một dòng kèm link evidence. Mentor dựa vào đây để xác nhận đã hoàn thành và gom bằng chứng cho Milestone."},{"t":"progressive disclosure","vi":"Bộc lộ tiệm tiến: chỉ đặt mục lục mỏng ở gốc (CLAUDE.md), nạp chi tiết (skill, tài liệu) khi task cần đến. Giữ context gọn, tránh context pollution — nguyên tắc thiết kế context/skill trong Claude Code."},{"t":"progressive","vi":"Tăng dần, từng bước. Trong khóa gặp trong cụm <i>progressive disclosure<\/i> — đưa thông tin cho agent đúng lúc cần, không đổ hết một lần."},{"t":"project-ready","vi":"Sẵn sàng dùng trong dự án thật, không chỉ là bài tập. Trong syllabus: <i>project-ready AI-first artifacts<\/i> = sản phẩm AI-first đủ chất lượng để áp vào dự án."},{"t":"project-specific","vi":"Đặc thù riêng của dự án. Ví dụ <i>project-specific CDC/SDV architecture standards<\/i> = chuẩn kiến trúc riêng của từng dự án, bổ sung cho chuẩn chung."},{"t":"promise-action mismatch","vi":"Lệch giữa lời báo và hành động: agent nói đã làm (ví dụ “đã thêm test”) nhưng diff/log không có. Phát hiện bằng verifier đọc dữ liệu có cấu trúc (diff, exit code), không đọc lời agent kể.","aka":["promise-action"]},{"t":"prompt engineering","vi":"Kỹ thuật viết prompt: thiết kế chỉ dẫn, ví dụ, cấu trúc để model làm đúng. Trong khóa: viết system prompt dạng SOP, sắp phần cố định/thay đổi theo cache boundary; cũng là tên lab Labs/prompt-engineering.","aka":["prompt-engineering"]},{"t":"prompt injection","vi":"Tấn công chèn chỉ thị độc hại để chiếm quyền điều khiển model/agent: trực tiếp (người dùng gõ vào) hoặc gián tiếp (giấu trong spec, pdf, readme agent đọc). Phòng thủ nhiều lớp giảm rủi ro nhưng không về 0.","aka":["prompt-injection","prompt injections"]},{"t":"prompting","vi":"Việc viết và đưa prompt cho model. Trong danh sách Agentic Design Patterns (D2), Prompting là nhóm kỹ thuật cấu trúc chỉ dẫn: vai trò, ví dụ, các bước làm."},{"t":"prop","vi":"Viết tắt của property trong code (tên tham số). Ví dụ <i>check_range(prop)<\/i>: hàm kiểm dải giá trị của một property VHAL."},{"t":"check_range(prop)","vi":"Hàm kiểm tra tự động trong validate_vhal.py: kiểm min/max của property nằm trong dải spec cho phép; vi phạm trả Finding R4_RANGE FAIL và chặn PR trong CI. Ví dụ luật nghiệp vụ viết thành code.","aka":["check_range()","check_range"]},{"t":"R4_RANGE","vi":"Mã luật số 4 (kiểm dải giá trị) trong validator VHAL của khóa: check_range() trả Finding R4_RANGE FAIL khi min/max hoặc đơn vị property không khớp spec. Ví dụ luật có mã, owner và nguồn spec rõ ràng.","cs":true},{"t":"propose","vi":"Đề xuất. Trong OJT: <i>Propose an assignment topic<\/i> = tự đề xuất đề tài phù hợp rank mục tiêu rồi xin duyệt.","aka":["proposes"]},{"t":"protect","vi":"Bảo vệ. Trong bài ảo hóa, Protect là một bước của chuỗi thiết kế (cùng Partition, Recover, Prove): giải thích vì sao Android quá tải hay lỗi không làm đói, làm hỏng phần cluster an toàn."},{"t":"prove","vi":"Chứng minh. Trong bài ảo hóa, Prove là bước đưa bằng chứng (đo đạc, test, log) cho thấy cluster vẫn phản hồi và phục hồi có kiểm soát khi phía Android gặp sự cố."},{"t":"provide","vi":"Cung cấp. Trong learning outcome: <i>Provide working results<\/i> = nộp kết quả chạy được kèm bằng chứng đo được về dự án và việc dùng AI.","aka":["provides","provided"]},{"t":"PTL","vi":"Trưởng nhóm kỹ thuật dự án: người chịu trách nhiệm kỹ thuật chính của dự án/nhóm. Khóa AI Transformation nhắm tới SA/PTL — những người thiết kế luồng làm việc và quyết định cách cả đội dùng AI.","full":"Project Technical Leader","cs":true},{"t":"push","vi":"Đẩy commit từ máy lên kho chung (git push). Trong khóa: một trong ba luật cứng — AI không tự push/merge/release; quyền này luôn ở phía người.","aka":["pushes","git push"]},{"t":"pytest","vi":"Framework kiểm thử phổ biến cho Python. Trong khóa: lệnh chạy test được đặt allow (chỉ kiểm, an toàn); kết quả pytest là bằng chứng có cấu trúc để verifier/người đọc, thay vì tin agent báo “đã pass”."},{"t":"Python","vi":"Ngôn ngữ lập trình phổ biến cho script, tự động hóa và AI. Điều kiện đầu vào của khóa AI: viết được script Bash/Python, dùng Git và CLI thành thạo."},{"t":"QnA","vi":"Hỏi – đáp. Trong lịch học: <i>Review &amp; QnA<\/i> là buổi mentor–mentee duyệt bài và giải đáp thắc mắc.","aka":["QNA"],"full":"Questions and Answers","cs":true},{"t":"qualified","vi":"Đủ điều kiện, đủ năng lực. Trong syllabus: trainer là SA hoặc mentor đủ chuẩn từ DEV04 trở lên (<i>qualified Dev4+ mentor<\/i>)."},{"t":"quiz","vi":"Bài kiểm tra ngắn. Trong syllabus: <i>Daily quiz<\/i> là bài kiểm tra hằng ngày, không bắt buộc và không tính điểm, dùng để tự kiểm tra.","aka":["quizzes","Daily quiz"]},{"t":"race-condition","vi":"Lỗi tranh chấp (race condition): kết quả sai chỉ khi hai luồng/service truy cập cùng dữ liệu theo một thứ tự thời gian nhất định, nên rất khó tái hiện. Bài 8 dùng làm ví dụ loại bug đáng trả tiền cho model suy luận từng bước."},{"t":"RAG","vi":"Kỹ thuật cho model truy xuất tài liệu liên quan (kho spec, tài liệu nội bộ) rồi đưa vào context trước khi trả lời, để bù tri thức model không có. Trong khóa là một Agentic Design Pattern, ví dụ RAG trên kho spec để trả lời câu hỏi spec.","aka":["Retrieval Augmented Generation","Retrieval-Augmented Generation"],"full":"Retrieval-Augmented Generation","cs":true},{"t":"retrieval","vi":"Truy xuất: tìm và lấy đúng tài liệu/đoạn liên quan từ kho dữ liệu. Là chữ R trong RAG."},{"t":"rank","vi":"Cấp bậc nghề nghiệp (job rank), ví dụ DEV03 → DEV04. Khóa chuẩn bị cho học viên lên rank tiếp theo; đề tài OJT phải có độ khó phù hợp <i>target rank<\/i> (rank mục tiêu).","aka":["ranks","job rank","target rank"]},{"t":"rank-appropriate","vi":"Phù hợp với rank mục tiêu: đề tài có độ phức tạp tương xứng cấp DEV04, không quá dễ cũng không quá lớn."},{"t":"README","vi":"File giới thiệu ở gốc một repo: dự án là gì, cách cài, cách chạy. Trong khóa: README open-source thuộc mức dữ liệu công khai; README của bên thứ ba mà agent đọc vào có thể chứa prompt injection gián tiếp.","aka":["README.md"]},{"t":"real","vi":"Thật, thực tế. Trong OJT: <i>real CDC project problem<\/i> = bài toán thật từ dự án CDC, không phải đề giả lập."},{"t":"rear-seat","vi":"Hàng ghế sau; thường chỉ màn hình giải trí hàng ghế sau. Trong bài: tải đồ họa rear-seat có thể chiếm GPU làm cluster trễ khung hình, nên cần quota GPU và đường hiển thị riêng cho cluster.","aka":["rear seat"]},{"t":"receive","vi":"Nhận. Trong learning outcome: xác định dữ liệu nào AI được truy cập, xử lý, hay <i>must never receive<\/i> — tuyệt đối không được nhận.","aka":["receives","received"]},{"t":"red","vi":"Đỏ — trạng thái test/cổng kiểm tra báo FAIL. Gặp trong <i>red lines<\/i> (điều cấm tuyệt đối) và <i>red-able gate<\/i> (cổng có thể báo đỏ)."},{"t":"red lines","vi":"Lằn ranh đỏ: những điều tuyệt đối không được làm. Trong context artifact/skill, mục red lines liệt kê điều cấm — nhưng đó chỉ là gợi ý; điều cấm thật phải cưỡng chế bằng deny/hook.","aka":["red line"]},{"t":"red-able gate","vi":"Cổng kiểm tra đã được chứng minh là CÓ THỂ báo đỏ khi có lỗi thật. Cổng không bao giờ đỏ thì không chứng minh gì; cách kiểm: cố ý chèn lỗi xem cổng có bắt được không (D6).","aka":["red-able","red-able gates"]},{"t":"redaction","vi":"Che/xóa thông tin nhạy cảm (danh tính, VIN, khóa, bí mật OEM) khỏi dữ liệu trước khi chia sẻ hay đưa cho AI. Trong khóa: biện pháp chính chống rò rỉ dữ liệu, nên làm bằng script tự động.","aka":["redact","redacted","redacting"]},{"t":"REFUSE","vi":"Nhãn ca đánh giá “phải từ chối”: yêu cầu mà agent PHẢI từ chối (vượt quyền, chạm dữ liệu cấm). Bộ đánh giá trong khóa bắt buộc có ca REFUSE để kiểm agent biết từ chối đúng lúc.","cs":true},{"t":"regex","vi":"Biểu thức chính quy: cú pháp mô tả mẫu chuỗi để kiểm/tìm văn bản. Trong khóa: biến tiêu chí cảm tính (“tên hợp lý”) thành regex, enum, min/max để máy kiểm được.","aka":["regexes","regular expression","regular expressions"]},{"t":"regulated","vi":"Chịu sự quản lý của pháp luật. Trong năm nhãn dữ liệu của khách hàng, <i>regulated<\/i> là mức nghiêm ngặt nhất: dữ liệu chịu data residency (GDPR, PIPA), khóa ký firmware, chứng chỉ — kèm ràng buộc pháp lý."},{"t":"Reinertsen","vi":"Donald Reinertsen, tác giả sách <i>The Principles of Product Development Flow<\/i> (2009). Khóa (D7) dẫn chương 3 về hàng đợi để hiểu lead time gồm cả thời gian chờ.","aka":["reinertsen"],"cs":true},{"t":"relevance","vi":"Mức độ liên quan, đúng trọng tâm. Trong tiêu chí chấm Final: <i>Problem relevance<\/i> = bài toán có thật sự liên quan, có giá trị với dự án không."},{"t":"relevant","vi":"Liên quan. <i>Relevant context<\/i> = đúng thông tin agent cần; <i>safety-relevant<\/i> = liên quan tới an toàn."},{"t":"relevant context","vi":"Context liên quan: đúng những gì agent cần cho quyết định hiện tại (quy ước, file liên quan, nguồn sự thật, ví dụ chuẩn). Cửa sổ context có hạn nên mỗi token phải “đáng chỗ”; đối lập với context pollution."},{"t":"required","vi":"Bắt buộc, cần có. Trong syllabus: <i>required assignments<\/i> = bài bắt buộc; trong khóa AI, <i>required judgment<\/i> là một trong bốn yếu tố chọn mức ủy quyền."},{"t":"required judgment","vi":"Mức phán đoán cần có: bước đó đòi kinh nghiệm miền hay người chịu trách nhiệm tới đâu. Cùng risk, reversibility, ambiguity là bốn câu hỏi để xếp bước vào Máy / Agent / Người và chọn mức L."},{"t":"requiring","vi":"Đòi hỏi, cần đến. Ví dụ <i>requiring domain-specific knowledge<\/i> = đòi hỏi kiến thức chuyên ngành."},{"t":"resistance","vi":"Sự kháng cự. Trong khóa gặp trong cụm <i>change resistance<\/i> — kháng cự với thay đổi khi đưa AI vào đội."},{"t":"change resistance","vi":"Kháng cự thay đổi: người trong đội chống lại cách làm mới vì cảm thấy giá trị nghề nghiệp bị đe dọa, thường diễn ra âm thầm. Trong khóa (D7) là rủi ro khi triển khai AI, cần xử lý bằng quản trị thay đổi."},{"t":"resolve","vi":"Giải quyết. Trong learning outcome: <i>Resolve conflicting constraints<\/i> = cân bằng các ràng buộc mâu thuẫn để chọn giải pháp.","aka":["resolves","resolved"]},{"t":"resource-aware","vi":"Biết tính tài nguyên: chọn model, số bước, lượng context theo ngân sách token, chi phí và độ trễ. Là một Agentic Design Pattern (Resource-Aware Optimization) trong chương trình D2."},{"t":"respond","vi":"Phản hồi, trả lời. <i>Respond to review questions<\/i> = trả lời câu hỏi phản biện khi trình bày, bảo vệ bài.","aka":["responds"]},{"t":"revert","vi":"Hoàn tác một thay đổi (git revert). Trong khóa: thay đổi revert được nhanh và rẻ thì có thể giao agent mức cao hơn; không đảo ngược được (release, gửi khách) thì phải giữ ở người.","aka":["reverted","reverting","reverts"]},{"t":"rig","vi":"Bàn thử phần cứng: bộ thiết bị thật (ECU, màn hình, nguồn, mô phỏng tín hiệu) để chạy HIL. Rig đắt và ít nên lịch chờ dài; chuyển phần lặp sang môi trường virtual rút từ ngày xuống giờ.","aka":["rigs","HIL rig","test rig"]},{"t":"RL","vi":"Học tăng cường: huấn luyện model bằng tín hiệu thưởng/phạt theo kết quả. Trong khóa chỉ nhắc như một cách post-training (cùng SFT), thuộc việc của đội ML chuyên trách.","full":"Reinforcement Learning","cs":true},{"t":"rm -rf","vi":"Lệnh Linux xóa file/thư mục đệ quy, không hỏi lại. Lệnh phá hủy kinh điển — trong settings.json của repo mẫu luôn bị deny với agent.","aka":["rm"]},{"t":"road","vi":"Đường bộ. Gặp trong tên các chuẩn ISO ô tô: <i>Road Vehicles<\/i>."},{"t":"Road Vehicles","vi":"Phương tiện giao thông đường bộ — phần tên các chuẩn ISO ô tô, ví dụ <i>ISO 26262 Road Vehicles – Functional Safety<\/i>, <i>ISO/SAE 21434 Road Vehicles – Cybersecurity Engineering<\/i>."},{"t":"Rother & Shook","vi":"Mike Rother và John Shook, tác giả <i>Learning to See<\/i> (1999) — sách kinh điển về value stream mapping. Khóa (D7) dẫn để vẽ dòng giá trị và tìm ràng buộc thật trước khi áp AI.","aka":["Rother","Shook"]},{"t":"Learning to See","vi":"Sách của Rother &amp; Shook (1999) hướng dẫn vẽ value stream map (bản đồ dòng giá trị) trong Lean: lần theo từng bước từ lúc nhận yêu cầu tới lúc giao để thấy chỗ chờ, chỗ tắc. Tài liệu đọc ngoài của D7."},{"t":"Ries","vi":"Eric Ries, tác giả <i>The Lean Startup<\/i> (2011). Khóa (D7) dẫn phần vanity metrics: con số trông đẹp (số dòng code AI sinh, số token, số người mở tool) nhưng không nói lên giá trị thật.","cs":true},{"t":"row","vi":"Hàng (trong bảng). Ví dụ <i>row 13<\/i> = hàng 13 của bảng syllabus.","aka":["rows"]},{"t":"ruff","vi":"Công cụ lint và format rất nhanh cho Python. Trong khóa: lệnh chỉ kiểm, không đổi trạng thái nên được đặt allow trong permission để agent chạy thoải mái."},{"t":"rule-based","vi":"Dựa trên luật: xử lý bằng điều kiện if/else rõ ràng. Trong bài định tuyến (routing), rule-based là cách rẻ và nhanh nhất — dùng khi tiêu chí phân loại rõ, trước khi nghĩ tới embedding, model nhỏ hay LLM."},{"t":"rules-as-code","vi":"Luật thành code: diễn đạt chính sách thành một kiểm tra chạy được (script, validator, hook) thay vì câu chữ trong tài liệu. Chủ đề D3 “Turn Rules into Code”: luật có mã, owner, nguồn và test đỏ chứng minh."},{"t":"runner","vi":"Bộ chạy: chương trình hay máy thực thi việc tự động, thường là test runner (chạy bộ test) hoặc CI runner (chạy job CI).","aka":["runners"]},{"t":"test runner","vi":"Trình chạy test (ví dụ pytest) — thực thi bộ test và trả exit code. Verifier tốt đọc exit code thật của test runner và file kết quả có cấu trúc, không đọc lời agent báo.","aka":["test runners"]},{"t":"SaaS","vi":"Phần mềm dùng qua internet dạng thuê bao, chạy trên hạ tầng của nhà cung cấp. Trong khóa: dữ liệu mức cấm ra ngoài (như source OEM) không được đưa vào AI SaaS — chỉ dùng agent chạy trong môi trường khách hàng.","full":"Software as a Service","cs":true},{"t":"same","vi":"Giống nhau, cùng. <i>Same skill list in row 13<\/i> = cùng danh sách kỹ năng như ở hàng 13."},{"t":"DeMillo, Lipton & Sayward","vi":"Ba tác giả bài báo năm 1978 đặt nền móng cho mutation testing (kiểm thử đột biến): cố ý chèn lỗi vào code để xem bộ test có phát hiện không. Khóa (D6) dẫn để kiểm cổng có thật sự “đỏ được”.","aka":["Sayward"]},{"t":"scheme","vi":"Sơ đồ, cơ chế. <i>Assessment Scheme<\/i> = cơ cấu đánh giá của khóa: các thành phần (quiz, assignment, test), tỷ trọng và điều kiện đạt."},{"t":"search","vi":"Tìm kiếm. Với coding agent, search (grep, đọc file) là tool đọc: cần deny đọc file bí mật, và coi nội dung tìm được là dữ liệu chứ không phải lệnh.","aka":["searching","searches"]},{"t":"SEAT","vi":"Nhóm property ghế trong cách đặt tên vendor property VHAL, ví dụ VENDOR_HVAC_SEAT_TEMP_LV; là một trong các nhóm hợp lệ HVAC|SEAT|DOOR|ADAS của NAME_PATTERN.","aka":["_SEAT"],"cs":true},{"t":"SeatTempLevel","vi":"Ví dụ tên property đặt SAI chuẩn (thiếu tiền tố VENDOR_, sai kiểu chữ), đối lập với VENDOR_HVAC_SEAT_TEMP_LV; validator theo NAME_PATTERN sẽ loại ngay.","cs":true},{"t":"seat_thermal","vi":"Tên module ví dụ (nhiệt độ ghế) trong repo mẫu. Bài minh họa: hỏi “nhiệt độ ghế” mà code đặt tên seat_thermal thì agent tìm “temperature” trượt — cần bản đồ thuật ngữ trong CLAUDE.md và giữ nó cập nhật."},{"t":"secondary","vi":"Phụ, thứ yếu. Trong bảng kỹ năng syllabus: <i>Secondary<\/i> = kỹ năng bổ trợ, phân biệt với kỹ năng chính (Primary) của rank mục tiêu."},{"t":"security.md","vi":"File quy tắc bảo mật (rules/security.md) trong repo mẫu, nạp vào context làm chỉ dẫn cho agent. Minh họa: nó chỉ là GỢI Ý (“đừng đọc .env”), còn deny trong settings.json mới là ràng buộc cứng.","aka":["rules/security.md"]},{"t":"selected","vi":"Được chọn. <i>selected CDC problem<\/i> = bài toán CDC đã chọn và được duyệt, đem bảo vệ ở Milestone 2."},{"t":"self-consistency","vi":"Tự nhất quán: cho model giải cùng một câu hỏi nhiều lần rồi lấy đáp án đa số. Đáng tin hơn một lần chạy nhưng đắt — chỉ dùng cho quyết định quan trọng."},{"t":"self-correct","vi":"Tự sửa: agent phát hiện lỗi (test đỏ, output sai) và tự sửa/chạy lại. Là một đường recovery trong xử lý ngoại lệ, cùng rollback và escalate lên người.","aka":["self-correction","self-correcting"]},{"t":"self-critique","vi":"Tự phê bình: yêu cầu model tự review output của chính nó (mẫu Reflection). Là tín hiệu yếu hơn kiểm tra độc lập vì cùng một model không tạo ra thông tin mới."},{"t":"self-learning","vi":"Tự học: hình thức chiếm phần lớn thời lượng khóa (88% theo syllabus) — học viên tự đọc tài liệu, học khóa Coursera/Viva Learning và làm bài theo hướng dẫn."},{"t":"self-research","vi":"Tự nghiên cứu: buổi học viên tự tìm hiểu một chủ đề (ví dụ Graphics &amp; Display Architecture) rồi tổng hợp thành tài liệu, assignment."},{"t":"self-study","vi":"Tự học theo khóa có sẵn, ví dụ <i>Self-study (Coursera – licensed)<\/i>: khóa trực tuyến có license do công ty cấp."},{"t":"self-review","vi":"Tự review: agent/model kiểm lại output của chính nó. Khóa nhấn mạnh: self-review bằng cùng một model không thêm thông tin mới nên vô ích hoặc gây hại — cần verifier độc lập hoặc người."},{"t":"seminar","vi":"Hội thảo, buổi trao đổi chuyên đề. Trong lịch: Seminar/Workshop là buổi gặp trực tiếp (ví dụ mentor review &amp; QnA), chiếm khoảng 3% thời lượng.","aka":["seminars"]},{"t":"senior","vi":"Cấp cao, giàu kinh nghiệm. Khóa dành cho Senior Software Engineer (DEV03) chuẩn bị lên DEV04; bài AI nhắc: người senior thật sự dám chọn kiến trúc đơn giản khi nó đủ dùng.","aka":["seniors"]},{"t":"sep","vi":"Viết tắt tháng Chín (September) trong lịch học, ví dụ 15 Sep 2026.","aka":["Sept"]},{"t":"session","vi":"Phiên làm việc. Trong Claude Code, mỗi session có bộ nhớ riêng: mọi lời trao đổi và kết quả tool đều nằm trong context phiên đó; phiên mới bắt đầu lại từ đầu.","aka":["sessions"]},{"t":"settings.json","vi":"File cấu hình của Claude Code (permission allow/ask/deny, hook…). Là ràng buộc CỨNG do hạ tầng cưỡng chế — khác CLAUDE.md chỉ là gợi ý cho model."},{"t":"setup","vi":"Cách bố trí, cấu hình hiện có (môi trường, công cụ, quy trình). <i>Setup hiện tại của bạn<\/i> = cấu hình agent/repo bạn đang dùng.","aka":["set-up","setups"]},{"t":"SFT","vi":"Tinh chỉnh có giám sát: huấn luyện tiếp một model có sẵn bằng các cặp đầu vào – đáp án mẫu. Trong khóa, SFT thuộc tầng <i>post-training<\/i> — việc của đội ML chuyên trách, chỉ đáng làm khi context, tool và verifier đã khai thác hết mà vẫn thiếu.","full":"Supervised Fine-Tuning","cs":true},{"t":"shape","vi":"Định hình, tạo nên hình dạng. Trong syllabus: các ràng buộc (vòng đời, chất lượng, an ninh mạng, bảo trì) <i>shape<\/i> — chi phối, định hình — quyết định kiến trúc CDC/SDV.","aka":["shapes","shaping"]},{"t":"shell","vi":"Vỏ: chương trình nhận lệnh gõ và chạy chúng (bash, PowerShell…). Trong khóa AI là nơi agent chạy lệnh; ở bài đồ họa, <i>IVI shell<\/i> là lớp vỏ giao diện quản lý cửa sổ/layer trên màn hình IVI.","aka":["shells"]},{"t":"Persistent shell session","vi":"Phiên shell bền: shell giữ nguyên trạng thái (thư mục hiện tại, biến môi trường) qua nhiều lần agent gọi tool, nên lệnh sau dùng được kết quả lệnh trước như người gõ trong terminal.","aka":["persistent shell"]},{"t":"shift-left","vi":"Dời sang trái (sớm hơn) trên dòng thời gian dự án: phát hiện lỗi ngay ở giai đoạn yêu cầu, thiết kế, kiểm thử ảo (SIL) thay vì đợi HIL hay xe thật. Lỗi càng phát hiện muộn càng tốn kém và ảnh hưởng nhiều xe.","aka":["shift left","shifting left"]},{"t":"Statistical significance","vi":"Ý nghĩa thống kê: khác biệt quan sát được (ví dụ điểm eval tăng 3%) có thật sự khác nhiễu ngẫu nhiên không. Trong khóa: chênh lệch trên vài chục mẫu thường chưa đủ để kết luận cấu hình agent nào tốt hơn.","aka":["statistically significant","significance","statistical"]},{"t":"Silent failure","vi":"Lỗi im lặng: output sai nhưng không phát ra tín hiệu lỗi nào (không exception, không cảnh báo). Kiểu lỗi nguy hiểm nhất với agent vì báo cáo vẫn trông “xanh”; phải có verifier/test để bắt.","aka":["silent failures","silent"]},{"t":"silo","vi":"Ốc đảo: mỗi nhóm/quy trình làm riêng, không chia sẻ dữ liệu với nhau. Trong bài: làm evidence theo silo cho từng chuẩn khiến công việc trùng lặp, số liệu lệch nhau, audit qua nhưng rủi ro thật vẫn lọt.","aka":["silos","siloed"]},{"t":"vector similarity","vi":"Độ tương đồng vector: đo hai đoạn văn gần nghĩa đến đâu bằng khoảng cách/góc giữa hai vector embedding của chúng. Nền tảng của tìm kiếm ngữ nghĩa và RAG; khóa gợi ý tra cứu khi Pha 2 thêm RAG.","aka":["similarity","vector"]},{"t":"Keep it simple","vi":"Giữ đơn giản: nguyên lý xây hệ agent — bắt đầu bằng giải pháp đơn giản nhất (một lời gọi model, workflow cố định), chỉ thêm agent, routing, multi-agent khi đo được là cần.","aka":["simple"]},{"t":"Effect size","vi":"Độ lớn hiệu ứng: khác biệt giữa hai phương án lớn đến mức nào, độc lập với cỡ mẫu. Có ý nghĩa thống kê chưa chắc đã đáng kể về thực tế — cần xem cả effect size khi so cấu hình agent.","aka":["size"]},{"t":"skill","vi":"Kỹ năng. Trong khóa AI: một <b>mô-đun quy trình đóng gói<\/b> (file SKILL.md kèm hướng dẫn, ví dụ, script) để agent gọi theo tên và nạp khi cần — đóng gói khi đã copy cùng một prompt lần thứ ba. Ở syllabus, <i>skill<\/i> là năng lực trong khung đánh giá nhân sự.","aka":["skills"]},{"t":"SKILL.md","vi":"File mô tả chính của một skill trong Claude Code: tên, khi nào dùng, các bước, ví dụ, file phụ trợ. Agent chỉ đọc phần tóm tắt trước, nạp toàn bộ khi tình huống cần (progressive disclosure). Khóa dạy viết theo khung 6 mục."},{"t":"skip","vi":"Bỏ qua. Trong kiểm thử: đánh dấu test không chạy. Khóa cảnh báo agent có thể skip, xóa hoặc sửa expectation của test cũ để báo “xanh” — phải tự đọc output thật (số test chạy, bị skip).","aka":["skipped","skipping"]},{"t":"sli/slo","vi":"SLI (Service Level Indicator) là chỉ số đo được như tỷ lệ request thành công, độ trễ p95; SLO (Service Level Objective) là mục tiêu đặt cho chỉ số đó. Khái niệm từ SRE, dùng để đặt ngưỡng độ trễ/độ tin cậy cho agent và service.","cs":true},{"t":"SRE","vi":"Kỹ thuật độ tin cậy hệ thống: cách Google vận hành dịch vụ bằng phương pháp kỹ sư phần mềm — đo SLI/SLO, error budget, xử lý sự cố. Khóa dẫn tới sách SRE của Google khi nói về độ trễ và phần trăm vị.","aka":["sre"],"full":"Site Reliability Engineering","cs":true},{"t":"Google SRE Book","vi":"Sách <i>Site Reliability Engineering<\/i> của Google (đọc miễn phí online) — tài liệu tham khảo về SLI/SLO và latency percentile (p50, p95) cho buổi D5 khi đo hiệu năng agent."},{"t":"small-model-codified-rules","vi":"Tên một lab của khóa (D3): chuyển quy tắc từ prompt sang code (validator), đo tỷ lệ tuân thủ, rồi chạy lại với model mạnh hơn. Bài học: model mạnh hơn không xóa được khoảng cách — prompt là gợi ý, code mới là ràng buộc.","aka":["labs/small-model-codified-rules"]},{"t":"solid","vi":"Vững chắc, chắc chắn. Trong syllabus: <i>solid hands-on experience<\/i> = kinh nghiệm thực hành vững về phát triển CDC/SDV — điều kiện đầu vào của học viên DEV03."},{"t":"solve","vi":"Giải quyết. Trong syllabus/OJT: <i>Solve and defend<\/i> — giải quyết một bài toán thật của dự án CDC và bảo vệ được giải pháp trước SA/BUL.","aka":["solves","solved","solving"]},{"t":"SOME-IP","vi":"Cách viết khác của SOME/IP: giao thức middleware hướng dịch vụ chạy trên Ethernet trong ô tô (gọi hàm, gửi event giữa các ECU). Trong dự án boot: một phụ thuộc cần phân tích thứ tự khởi động.","full":"Scalable service-Oriented MiddlewarE over IP","cs":true},{"t":"spam","vi":"Thư rác. Khóa dùng “lọc spam” làm ví dụ AI phân loại (machine learning gán nhãn có/không) để phân biệt với generative AI — model sinh nội dung mới như LLM."},{"t":"span","vi":"Một đoạn trong trace: ghi lại một bước của lần chạy (một lời gọi model, một tool) kèm thời gian bắt đầu/kết thúc, chi phí. Gom các span lại để bóc chi phí và độ trễ theo từng bước của agent.","aka":["spans","Tracing / span"]},{"t":"specialist agent","vi":"Agent chuyên trách: agent con được giao một mảng việc hẹp (review bảo mật, tra spec…) dưới sự điều phối của orchestrator. Chỉ đáng tách khi nó mang lại thông tin mà một agent đơn không tự lấy được.","aka":["specialist agents","specialist"]},{"t":"Universal vs specialized tools","vi":"Tool tổng quát (trình thông dịch code, shell) so với tool chuyên dụng (máy tính bỏ túi). Luận điểm của khóa: code là tool phổ quát — ưu tiên tool tổng quát ghép được với nhau thay vì gắn thật nhiều tool hẹp.","aka":["universal","specialized"]},{"t":"specific","vi":"Cụ thể, đặc thù. Trong syllabus: công nghệ/nền tảng <i>specific to<\/i> CDC — đặc thù cho hệ thống buồng lái ô tô; <i>domain-specific<\/i> = riêng cho một miền nghiệp vụ.","aka":["specifically"]},{"t":"Automotive Spice Pam","vi":"Automotive SPICE PAM (Process Assessment Model) — mô hình đánh giá năng lực quy trình phần mềm ô tô do VDA ban hành (bản v3.1 được trích). Khóa dẫn tới đây cho các khái niệm work product, traceability, audit trail.","aka":["Automotive Spice"],"cs":true},{"t":"SQL","vi":"Ngôn ngữ truy vấn cơ sở dữ liệu. Trong khóa: ví dụ của <i>artifact pattern<\/i> — cho agent sinh câu SQL (sản phẩm trung gian) để chạy, thay vì để agent tự đọc và bê dữ liệu; rẻ và chính xác hơn.","aka":["sql"],"full":"Structured Query Language","cs":true},{"t":"stage-gate","vi":"Quy trình giai đoạn – cổng: dự án chia thành các giai đoạn, cuối mỗi giai đoạn có cổng quyết định đi tiếp, sửa hay dừng. Khóa gợi ý tra khi học stop/kill criteria cho thử nghiệm AI.","aka":["stage gate"]},{"t":"staged-system-prompt","vi":"Tên lab D5: agent đổi system prompt và bộ tool theo từng giai đoạn (phân tích → thiết kế → code → review), dùng chung ngữ cảnh, review trượt thì lùi lại. Khuôn mẫu sát nhất với quy trình phát triển thật.","aka":["labs/staged-system-prompt"]},{"t":"standards","vi":"Tiêu chuẩn. Trong syllabus: các chuẩn ngành ô tô (ISO 26262/FuSa, an ninh mạng, ASPICE…) và quy chuẩn dự án mà học viên phải biết áp dụng (<i>standards application<\/i>)."},{"t":"stdin","vi":"Luồng nhập chuẩn của một chương trình. Trong Claude Code, hook nhận thông tin tool sắp chạy (tên tool, tham số) qua stdin dạng JSON, kiểm tra rồi trả exit code — 2 nghĩa là chặn.","full":"standard input"},{"t":"step-back","vi":"Lùi một bước: kỹ thuật prompt hỏi model về nguyên tắc chung trước, rồi mới áp vào ca cụ thể. Hợp với review kiến trúc, nơi cần soi theo nguyên lý thay vì sa vào chi tiết.","aka":["step back","Step-back prompting"]},{"t":"Stop criteria","vi":"Tiêu chí dừng: điều kiện để kết thúc một thử nghiệm (ví dụ pilot AI không đạt ngưỡng sau N tuần). Phải viết trước khi bắt đầu, nếu không sẽ không ai chịu dừng.","aka":["stop criterion","kill criteria","stop"]},{"t":"storyboarding","vi":"Dựng kịch bản phân cảnh: phác trình tự nội dung bài giảng trước khi làm. Trong syllabus: dựa vào syllabus, người phụ trách nội dung soạn courseware và storyboard.","aka":["storyboard","storyboards"]},{"t":"strategic","vi":"Mang tính chiến lược, ảnh hưởng dài hạn. Trong bài: <i>strategic impact<\/i> (trễ SOP, mất hợp đồng, niềm tin thương hiệu) và <i>strategic trade-offs<\/i> — đánh đổi ở tầm định hướng kiến trúc.","aka":["strategically"]},{"t":"strengthen","vi":"Củng cố, làm mạnh hơn. Trong syllabus: học viên sẽ củng cố năng lực thiết kế giải pháp, đánh giá công nghệ, làm prototype…","aka":["strengthens"]},{"t":"string","vi":"Chuỗi ký tự. Trong ví dụ của khóa: <i>string HMI / string resource<\/i> là các file chứa câu chữ hiển thị trên giao diện, cần dịch sang nhiều ngôn ngữ — việc độc lập nên hợp chạy song song.","aka":["strings","string resource"]},{"t":"structured","vi":"Có cấu trúc, theo khuôn định sẵn. Trong khóa: dữ liệu/đầu ra có cấu trúc (JSON, bảng) thì code kiểm được; ở syllabus: <i>structured diagnosis<\/i> — chẩn đoán sự cố theo trình tự có phương pháp.","aka":["unstructured"]},{"t":"Structured output","vi":"Đầu ra có cấu trúc: ép model trả kết quả theo schema (JSON, bảng cột cố định) thay vì văn tự do. Nhờ vậy validator/verifier đọc và kiểm được tự động.","aka":["structured outputs"]},{"t":"style","vi":"Phong cách, văn phong. Trong code: <i>code style<\/i> — cách đặt tên, định dạng, cấu trúc. Khóa nhắc ràng buộc “giữ style hiện tại” và cảnh báo prompt mơ hồ khiến AI chỉ nhận xét chung chung về style."},{"t":"subagent","vi":"Agent con: agent chính giao một tác vụ phụ cho agent riêng chạy trong context riêng, chỉ nhận lại kết quả tóm tắt — giữ context chính sạch. Dùng có chừng mực vì tốn token điều phối.","aka":["subagents","sub-agent","sub-agents"]},{"t":"successfully","vi":"Thành công. Trong syllabus: <i>successfully defend<\/i> — bảo vệ thành công giải pháp capstone trước SA/BUL."},{"t":"such","vi":"Như, chẳng hạn. <i>such as<\/i> = ví dụ như (liệt kê ví dụ).","aka":["such as"]},{"t":"Information Sufficiency","vi":"Đủ thông tin: nguyên lý của khóa — chất lượng output của agent bằng mức đầy đủ, rõ ràng của context bạn đưa vào. Thiếu context thì model đoán; đó là gốc của nhiều lỗi “bịa”.","aka":["sufficiency"]},{"t":"summarize","vi":"Tóm tắt. Trong syllabus: tóm tắt phát hiện nghiên cứu qua bài thuyết trình và video chia sẻ kỹ thuật.","aka":["summarise","summarized"]},{"t":"SUP-xxx","vi":"Mã requirement giả định do supplier tự đánh số lại (SUP-001…). Ví dụ trong bài: đổi ID của OEM sang SUP-xxx làm đứt traceability — OEM không biết thay đổi ảnh hưởng requirement/test nào.","cs":true},{"t":"supplementary","vi":"Bổ sung, đọc thêm. Trong syllabus: khóa học <i>Supplementary<\/i> là tài liệu tự học thêm, không bắt buộc.","aka":["supplemental"]},{"t":"sustainable","vi":"Bền vững, duy trì được lâu. <i>Sustainable Software Architecture<\/i>: kiến trúc giữ được khả năng thay đổi theo thời gian, kiểm soát nợ kỹ thuật.","aka":["sustainability"]},{"t":"svc","vi":"Tên viết tắt mơ hồ (svc) dùng làm ví dụ xấu khi đặt tên tool: agent chọn tool theo tên và mô tả, nên <i>search_vehicle_config<\/i> rõ nghĩa hơn svc nhiều."},{"t":"search_vehicle_config","vi":"Ví dụ tên tool tốt: đọc là hiểu tool tra cấu hình xe. Khóa so với tên mơ hồ “svc” để nhấn mạnh agent chọn tool dựa vào tên và mô tả."},{"t":"syllabus","vi":"Đề cương khóa học: danh sách học phần, mục tiêu (LO), lịch, tài liệu, tiêu chí đánh giá. Ở đây là file syllabus chính thức của chương trình Automotive Senior Fast Track (CDC/SDV).","aka":["syllabi"]},{"t":"synthesis","vi":"Tổng hợp: gom nhiều nguồn, phát hiện thành một kết luận mạch lạc. <i>Research Synthesis<\/i> (Assignment 3) — nghiên cứu một miền kỹ thuật và tổng hợp phát hiện đáng tin.","aka":["syntheses"]},{"t":"synthesize","vi":"Tổng hợp (động từ): rút kết luận chung từ nhiều nguồn tài liệu, số liệu. Yêu cầu của Assignment 3: tự nghiên cứu một miền và tổng hợp phát hiện có nguồn kiểm chứng.","aka":["synthesise","synthesizes","synthesizing"]},{"t":"systemd","vi":"Trình khởi động và quản lý dịch vụ chuẩn trên Linux: quyết định thứ tự và phụ thuộc giữa các service khi boot. Trong dự án boot-time: phân tích thứ tự systemd để cắt phụ thuộc thừa."},{"t":"T&M","vi":"Hợp đồng tính tiền theo thời gian và nguồn lực (người-tháng). Khóa so với <i>outcome-based pricing<\/i> (tính theo kết quả): dưới T&amp;M, AI làm năng suất tăng lại làm doanh thu giảm.","full":"Time and Materials","cs":true},{"t":"take","vi":"Nhận, đảm nhận. <i>take ownership<\/i> = nhận trách nhiệm làm chủ một phần việc.","aka":["takes","taking"]},{"t":"target-rank","vi":"Bậc mục tiêu: cấp bậc nghề nghiệp học viên hướng tới (DEV04). <i>Target-rank complexity<\/i> — độ khó bài toán OJT phải tương xứng bậc DEV04.","aka":["target rank"]},{"t":"TBD","vi":"Chưa xác định, sẽ bổ sung sau. Trong syllabus: đường link tài liệu còn TBD.","full":"To Be Determined","cs":true},{"t":"TCC803x","vi":"Dòng SoC Dolphin+ của hãng Telechips dùng cho IVI/cụm đồng hồ ô tô. Nền phần cứng của dự án tối ưu thời gian từ boot đến khung hình 3D đầu tiên.","aka":["tcc803x"],"cs":true},{"t":"technical-lead","vi":"Trưởng nhóm kỹ thuật: người dẫn dắt quyết định kỹ thuật của đội. Trong syllabus: học viên làm việc dưới sự hướng dẫn của SA hoặc technical lead.","aka":["technical lead","tech lead"]},{"t":"technically","vi":"Về mặt kỹ thuật. <i>technically sound recommendation<\/i> = khuyến nghị vững chắc về kỹ thuật."},{"t":"Telechips","vi":"Hãng bán dẫn Hàn Quốc chuyên SoC cho xe (IVI, cụm đồng hồ). SoC Dolphin+ (TCC803x) của Telechips là phần cứng đích trong dự án boot-time."},{"t":"VENDOR_*","vi":"Quy ước tên property VHAL riêng của hãng: phải bắt đầu bằng tiền tố VENDOR_. Khi review PR VHAL, kiểm tên đúng quy ước VENDOR_* là bước đầu, và agent hay bịa property VENDOR_* không có trong spec.","aka":["VENDOR_ADAS_*","VENDOR_","vendor_*"],"cs":true},{"t":"temperature","vi":"Nhiệt độ. Trong LLM: tham số điều chỉnh độ ngẫu nhiên khi chọn token — thấp thì bám lựa chọn xác suất cao nhất, cao thì đa dạng hơn. Trong ví dụ HVAC: từ khóa agent grep trượt vì code đặt tên seat_thermal."},{"t":"term","vi":"Thuật ngữ. Trong trang glossary: cột <i>Term<\/i> là thuật ngữ tiếng Anh, kèm giải thích tiếng Việt và nguồn đọc.","aka":["terms"]},{"t":"terminal","vi":"Cửa sổ dòng lệnh để gõ và chạy lệnh. Claude Code chạy trong terminal, thao tác trực tiếp trên thư mục mã nguồn; lệnh terminal của agent được phân quyền allow/ask/deny.","aka":["terminals"]},{"t":"text","vi":"Văn bản, chữ. Trong khóa: <i>text model sinh<\/i> là văn bản tự do do model viết ra — không dùng làm đầu vào kiểm tra (Input Isolation), chỉ kiểm dữ liệu có cấu trúc.","aka":["texts"]},{"t":"Text-to-SQL","vi":"Dịch câu hỏi ngôn ngữ tự nhiên thành câu truy vấn SQL. Ví dụ kinh điển của artifact pattern: agent sinh SQL để hệ thống chạy, thay vì tự đọc dữ liệu."},{"t":"theory","vi":"Lý thuyết. Trong syllabus: phần học khái niệm/lý thuyết và bài <i>Final Test – Theory<\/i> (thi lý thuyết, tách với thi thực hành).","aka":["theories","theoretical"]},{"t":"Theory of constraints","vi":"Lý thuyết ràng buộc (Goldratt, sách <i>The Goal<\/i>): hệ thống chỉ nhanh bằng điểm thắt cổ chai; cải thiện chỗ khác không làm cả luồng nhanh hơn. Khóa dùng để chọn đúng chỗ đưa AI vào value stream."},{"t":"chain of thought","vi":"Chuỗi suy luận: yêu cầu model trình bày từng bước trước khi kết luận. Cải thiện bài toán nhiều bước nhưng tốn token và thời gian — không dùng cho việc đơn giản.","aka":["thought"]},{"t":"Three-tier verification","vi":"Kiểm chứng ba tầng: (1) kết quả — sự thật môi trường như test chạy; (2) quá trình — quy tắc chương trình trên diff/trajectory; (3) chất lượng — rubric. Chỉ tầng trên cùng dùng LLM chấm.","aka":["three-tier"]},{"t":"through","vi":"Qua, thông qua. <i>through<\/i> = bằng cách, nhờ vào (ví dụ: chứng minh CASAN Level 3 thông qua sản phẩm thật)."},{"t":"timing-critical","vi":"Phụ thuộc chặt vào thời gian: code mà tính đúng đắn phụ thuộc ràng buộc thời gian thực (ngắt, deadline điều khiển). Thuộc vùng Người trong tam phân — kỹ sư viết và ký, không ủy quyền cho agent.","aka":["timing-critical code","timing critical"]},{"t":"tr.404-409","vi":"Viết tắt “trang 404–409” — vị trí đoạn đọc về agentic loop trong phụ lục G (AppG) của sách tham khảo."},{"t":"track","vi":"Lộ trình, nhánh học; cũng là theo dõi. <i>Fast Track<\/i> là lộ trình rút gọn của chương trình đào tạo Senior CDC/SDV (xem Fast_Track_CDC_Weekly_Checklist.xlsx).","aka":["tracks"]},{"t":"Fast_Track_CDC_Weekly_Checklist.xlsx","vi":"File Excel lịch theo tuần (W1–W11) của chương trình Fast Track CDC — nguồn ngày giờ cho thư viện bài và trang chủ đề cương."},{"t":"tracking","vi":"Theo dõi. <i>Bug tracking<\/i>: hệ thống ghi và theo dõi lỗi (Jira…). Khóa yêu cầu lấy số đo từ nguồn như log, CI, bug tracking, audit log — không lấy từ trí nhớ.","aka":["bug tracking"]},{"t":"audit trail","vi":"Dấu vết kiểm toán: bản ghi khó giả mạo về ai đã làm gì, khi nào, bằng công cụ nào. Với agent: log hành động, phiên bản model/prompt, người duyệt — bằng chứng khi audit hay điều tra sự cố.","aka":["audit trails","trail"]},{"t":"trainee","vi":"Học viên được đào tạo. Trong syllabus: học viên là kỹ sư Dev3.","aka":["trainees"]},{"t":"trainer","vi":"Người đào tạo, giảng viên. Trong syllabus: trainer là SA hoặc mentor từ Dev4 trở lên đủ điều kiện.","aka":["trainers"]},{"t":"Trainer-of-trainers","vi":"Đào tạo giảng viên: xây đội giảng viên nội bộ để chương trình nhân rộng mà không phụ thuộc một người dạy. Liên quan vai trò Coach ở lộ trình sau tốt nghiệp.","aka":["train-the-trainer","train the trainer"]},{"t":"training","vi":"Đào tạo. Trong syllabus là chương trình/khóa học (<i>Automotive Senior Fastrack Training<\/i>). Trong ngữ cảnh AI còn có nghĩa huấn luyện model trên dữ liệu — khóa không yêu cầu kinh nghiệm training model.","aka":["trainings"]},{"t":"trajectory","vi":"Quỹ đạo, vết chạy: chuỗi bước agent đã làm trong một lần chạy (đọc file nào, gọi tool gì, kết quả). Đọc trajectory để kiểm hành vi — có chạm file cấm, bỏ bước, lời báo cáo có khớp hành động không.","aka":["trajectories"]},{"t":"trajectory-verifier","vi":"Tên lab D6: dựng verifier ba tầng chạy được trên trajectory của agent và hiểu vì sao phân tầng nhiệm vụ L1/L2/L3 giúp chẩn đoán lỗi nằm ở tầng nào.","aka":["labs/trajectory-verifier"]},{"t":"transcript","vi":"Bản ghi đầy đủ một phiên làm việc (lời nhắn, lệnh, output của agent). Có thể chứa dữ liệu nhạy cảm nên cũng phải có hạn xóa như file tạm và log.","aka":["transcripts"]},{"t":"transparency","vi":"Minh bạch. Trong khóa: nghĩa vụ công khai AI được dùng ở đâu, thế nào (ví dụ điều 50 EU AI Act) và không tuyên bố quá mức đóng góp của AI với khách hàng."},{"t":"trend","vi":"Xu hướng, trào lưu. Trong khóa: cảnh báo chọn kiến trúc agent theo trend (ví dụ multi-agent) thay vì phán đoán theo bài toán.","aka":["trends","trending"]},{"t":"TTFT","vi":"Độ trễ tới token đầu tiên: thời gian từ lúc gửi yêu cầu đến khi model trả token đầu tiên. Quyết định cảm giác “nhanh/chậm” của người dùng; đo cùng p50/p95 khi phân tích chi phí – độ trễ.","aka":["ttft","Ttft"],"full":"Time To First Token","cs":true},{"t":"tts-quality-eval","vi":"Tên lab D6: dùng LLM-as-a-judge chấm chất lượng theo rubric và đo mức đồng thuận với nhãn người — để biết judge sai ở đâu bằng số, không bằng cảm giác.","aka":["labs/tts-quality-eval"]},{"t":"turn","vi":"Biến, chuyển thành; cũng là lượt (một lượt hỏi – đáp với model). <i>Turn rules into code<\/i> = biến quy tắc thành code kiểm tra được.","aka":["turns"]},{"t":"Turn Rules into Code","vi":"Tên buổi D3 (AI-07): chuyển quy tắc kỹ thuật từ lời dặn trong prompt thành validator, hook, permission chạy được — vì prompt chỉ là gợi ý, code mới là ràng buộc."},{"t":"types.hal","vi":"File định nghĩa kiểu dữ liệu và property của VHAL (Android). Khóa dùng làm ví dụ: file 2.000 dòng tốn 25–35 nghìn token context, và là nguồn để validator đối chiếu tên property."},{"t":"UL Solutions","vi":"Công ty chứng nhận/kiểm định an toàn quốc tế (trước là Underwriters Laboratories), có đào tạo về Automotive SPICE. Trong syllabus là đơn vị cung cấp khóa nhập môn Automotive SPICE v4.0.","aka":["UL"],"cs":true},{"t":"UN-R155","vi":"Quy chuẩn UNECE số 155 về an ninh mạng cho xe: hãng xe phải có CSMS (hệ thống quản lý an ninh mạng) và bằng chứng để được phê duyệt kiểu xe. Học ở A.3 cùng SBOM, CVE.","cs":true},{"t":"unit-level","vi":"Ở cấp đơn vị tổ chức (bộ phận/đơn vị kinh doanh). Trong syllabus: ảnh hưởng định hướng kỹ thuật ở cấp dự án hoặc cấp đơn vị.","aka":["unit level"]},{"t":"unknown unknowns","vi":"Những điều chưa biết mà ta không biết là mình chưa biết. Mẫu agent khám phá (exploration) chủ động dò vùng chưa quen để lộ ra loại rủi ro/khả năng này.","aka":["unknowns"]},{"t":"used","vi":"Được dùng. <i>standards used in the automotive industry<\/i> = các tiêu chuẩn được dùng trong ngành ô tô."},{"t":"usefulness","vi":"Tính hữu ích: người nhận có dùng được ngay kết quả không. Một trong năm chiều đánh giá output của khóa (correctness, completeness, consistency, safety, usefulness), kiểm ở tầng 3 bằng rubric.","aka":["useful"]},{"t":"using","vi":"Sử dụng, bằng cách dùng. Trong syllabus: <i>using AI<\/i> — thực hiện giải pháp có dùng AI."},{"t":"validate_vhal.py","vi":"Script validator của lab 3: kiểm property VHAL theo các quy tắc (tên đúng regex quy ước, đơn vị, access mode, dải giá trị so spec), chạy trong CI, trả đạt/không-đạt một cách xác định."},{"t":"validating","vi":"Kiểm chứng, xác nhận đúng như yêu cầu. Trong syllabus: thêm một tool miền CDC cho coding agent và kiểm chứng hành vi của nó."},{"t":"validation-plan","vi":"Kế hoạch kiểm chứng: liệt kê cần kiểm gì, bằng phương pháp/môi trường nào (SIL, HIL, xe), tiêu chí đạt và ai chịu trách nhiệm. Trong syllabus là một template bàn giao.","aka":["validation plan"]},{"t":"validator","vi":"Bộ kiểm tra tự động: script/code đối chiếu output với quy tắc (tên, dải, định dạng) và trả đạt/không-đạt xác định. Trong khóa: biến quy tắc thành validator chạy trong CI — ổn định hơn để model lớn tự phán đoán.","aka":["validators"]},{"t":"value-stream","vi":"Chuỗi giá trị: toàn bộ các bước từ lúc nhận yêu cầu tới lúc giao giá trị cho khách. Khóa chọn bài toán đưa AI vào theo value stream có số liệu, đúng chỗ thắt cổ chai, không theo cảm tính.","aka":["value stream","value streams"]},{"t":"Value-stream map","vi":"Bản đồ chuỗi giá trị: sơ đồ các bước, thời gian làm và thời gian chờ của một luồng công việc. Dùng để lấy mốc ban đầu và tìm ràng buộc thật trước khi đưa AI vào.","aka":["value stream map","value stream mapping","value-stream mapping","VSM"]},{"t":"Vanity metrics","vi":"Chỉ số phù phiếm: dễ tăng nhưng không phản ánh giá trị — số dòng code AI sinh, số người mở tool, điểm hài lòng. Khóa yêu cầu đo bằng chỉ số gắn kết quả thật.","aka":["vanity metric","vanity"]},{"t":"various","vi":"Nhiều, khác nhau. <i>various standards<\/i> = nhiều tiêu chuẩn khác nhau."},{"t":"VDA","vi":"Hiệp hội Công nghiệp Ô tô Đức — đơn vị (qua VDA QMC) ban hành và duy trì Automotive SPICE. Trong khóa: nguồn của Automotive SPICE PAM v3.1.","aka":["vda"],"full":"Verband der Automobilindustrie","cs":true},{"t":"vendor-specific","vi":"Riêng của từng nhà cung cấp, không theo chuẩn chung. Khóa so MCP (chuẩn mở) với function calling (mỗi vendor model một kiểu).","aka":["vendor specific"]},{"t":"verifier.py","vi":"File code verifier trong lab 6: đầu file ghi “tuyên ngôn” ba tầng (kết quả → quá trình → chất lượng) — thứ tự kiểm cả bài muốn học viên nhớ."},{"t":"vhal/","vi":"Thư mục adapter VHAL trong repo ví dụ: quy ước kiến trúc là mọi thay đổi VHAL phải đi qua lớp adapter này; agent không tự thấy quy ước ngầm nên phải ghi rõ trong CLAUDE.md/prompt.","cs":true},{"t":"check_vhal","vi":"Tên tool ví dụ: <i>check_vhal(prop)<\/i> kiểm một property VHAL theo bộ quy tắc và trả danh sách vi phạm. Khóa dùng để minh họa: agent chọn tool bằng cách đọc mô tả, nên mô tả phải rõ."},{"t":"viable","vi":"Khả thi, dùng được trong thực tế. Trong syllabus: xác định giải pháp khả thi cho nền tảng xe hiện đại.","aka":["viability"]},{"t":"vibe coding","vi":"Code theo cảm hứng: để agent sinh nhanh bản nháp từ mô tả thô, ít kiểm soát. Hợp để khám phá/prototype; code vào nhánh chính vẫn phải qua đủ hàng rào kiểm tra — “vibe cho khám phá, kỷ luật cho bàn giao”.","aka":["vibe","vibe-coding"]},{"t":"vibe-code","vi":"Viết bằng vibe coding: prototype vibe-code không cần chỉn chu, nhưng không được đưa thẳng vào nhánh chính khi chưa qua review, test, validator.","aka":["vibe-coded"]},{"t":"vitual","vi":"Lỗi chính tả của <i>virtual<\/i> (trực tuyến) trong syllabus: hình thức học/đánh giá trực tuyến."},{"t":"Viva Learning","vi":"Microsoft Viva Learning — nền tảng học trực tuyến nội bộ (tổng hợp khóa LinkedIn Learning…). Syllabus dùng để chỉ nguồn các khóa tự học bổ sung.","aka":["Viva"]},{"t":"web","vi":"Mạng web, internet. Trong khóa: agent có thể dùng tool tìm web; nội dung web cũng là nguồn prompt injection. <i>Chat trên web<\/i> khác Claude Code chạy trong dự án."},{"t":"week","vi":"Tuần. <i>30-Week Timeline<\/i> là lịch tổng 30 tuần của chương trình.","aka":["weeks"]},{"t":"30-Week Timeline","vi":"Lịch tổng của chương trình đánh số tuần 1–30. Khác với Weekly Checklist (lịch nén W1–W11); hai lịch có thể lệch nhau, theo lịch mentor chốt.","aka":["30-Week"]},{"t":"weekly","vi":"Hằng tuần. <i>Weekly Checklist<\/i> là danh sách việc theo từng tuần của chương trình Fast Track."},{"t":"Weekly Checklist","vi":"Lịch nén theo tuần W1–W11 (W1 = 29/09) ghi các việc phải xong mỗi tuần; khác với 30-Week Timeline. Các trang bài dẫn mốc nộp bài theo cả hai lịch.","aka":["Weekly Checklists"]},{"t":"what","vi":"Cái gì, điều gì. <i>define what AI may access<\/i> = xác định AI được truy cập những gì."},{"t":"which","vi":"Mà, cái mà (đại từ quan hệ). <i>CDC, which involves…<\/i> = CDC, lĩnh vực đòi hỏi…"},{"t":"while","vi":"Trong khi, đồng thời. <i>while escalating…<\/i> = đồng thời chuyển các quyết định liên miền lên cấp phù hợp."},{"t":"why","vi":"Tại sao. Khóa nói “học chữ <i>why<\/i>, không chỉ chữ <i>how<\/i>” — hiểu vì sao model hoạt động như vậy để biết khi nào tin và khi nào không."},{"t":"Wikipedia","vi":"Bách khoa toàn thư mở trên mạng. Trang glossary gợi ý tra Wikipedia cho các khái niệm nền (thống kê, mutation testing…) khi chưa quen."},{"t":"workbook","vi":"File Excel gồm nhiều sheet. Ở đây là workbook gốc của syllabus/lịch (file .xlsx) mà trang đề cương chép lại.","aka":["workbooks"]},{"t":"working","vi":"Đang chạy được, hoạt động thật. <i>working implementation<\/i> = bản cài đặt chạy được thật (khác bản mô tả trên giấy) — đầu ra bắt buộc của OJT."},{"t":"xlsx","vi":"Định dạng file bảng tính Excel. Syllabus và Weekly Checklist gốc là file .xlsx.","aka":[".xlsx"]},{"t":"zero","vi":"Số không. <i>Customer Zero<\/i>: tự làm khách hàng đầu tiên; <i>zero-retention<\/i>: không lưu dữ liệu."},{"t":"Customer Zero","vi":"Khách hàng số 0: tinh thần FPT tự áp dụng giải pháp AI lên dự án của chính mình trước, chứng minh hiệu quả bằng số trước khi đem cam kết với khách hàng."},{"t":"zero-retention","vi":"Cam kết không lưu: nhà cung cấp AI không lưu trữ dữ liệu prompt/output sau khi xử lý. Cùng DPA, là điều kiện để dữ liệu mức “có kiểm soát” được gửi qua endpoint đã duyệt.","aka":["zero retention","ZDR","zero data retention"]},{"t":"VENDOR_HVAC_FAN_SPEED","vi":"Ví dụ tên property VHAL theo quy ước VENDOR_ + miền (HVAC) + thuộc tính (tốc độ quạt). Dùng khi minh họa kiểm tên property theo quy ước VENDOR_* của dự án.","cs":true},{"t":"FA_CDC_Senior_Fasttrack_Syllabus_v1.1_Dev3","vi":"Tên file Excel gốc của syllabus chương trình Automotive Senior Fast Track CDC (phiên bản v1.1, dành cho học viên Dev3); trang lịch học được chép từ workbook này."},{"t":"FPS","vi":"Số khung hình vẽ ra màn hình mỗi giây; càng cao thì hình chuyển động càng mượt. Trong bài, \"cluster vẽ kim 120 fps\" là ví dụ một đề xuất kỹ thuật hấp dẫn nhưng cần SoC/GPU mạnh hơn, nên phải cân với chi phí BOM và giá trị thực cho người dùng.","u":["A.1"],"full":"Frames Per Second","cs":true},{"t":"SBOM/CVE","vi":"Cặp việc <b>SBOM<\/b> (danh sách mọi thành phần phần mềm trong một bản build) và theo dõi <b>CVE<\/b> (lỗ hổng bảo mật công khai). Trong bài là một phần chi phí bảo trì dài hạn sau SOP; nội dung chi tiết được đào sâu ở bài A.3.","u":["A.1"]},{"t":"present","vi":"Hiện tại (thời điểm bây giờ). Trong bài xuất hiện trong <b>Net Present Value<\/b> (NPV) / present value: quy dòng tiền tương lai về giá trị tương đương ở thời điểm hiện tại để so sánh các phương án.","u":["A.1"]},{"t":"cloud/OTA","vi":"Nhóm dịch vụ cloud và hạ tầng cập nhật OTA của hãng xe. Trong bài là một tầng trong chuỗi giá trị (sau Tier 1, OEM), góp phần vào chi phí vận hành và cùng chia trách nhiệm sau khi xe đã bán.","u":["A.1"]},{"t":"BOM","vi":"Danh sách thành phần tạo nên một sản phẩm. Trong bài xuất hiện trong <b>SBOM<\/b> (Software Bill of Materials): danh sách mọi thành phần phần mềm, kể cả thư viện mã nguồn mở, trong một bản release — một evidence cần có khi phát hành.","u":["A.2"],"full":"Bill of Materials","cs":true},{"t":"prototype","vi":"Mẫu thử: phiên bản sớm, làm nhanh để thử ý tưởng. Trong bài, prototype/mock-up dùng để <b>validate requirement sớm<\/b> với người dùng/stakeholder trước khi phát triển thật, tránh phát hiện requirement sai khi sửa đã rất đắt.","u":["A.2"]},{"t":"exit code/test report","vi":"Ở trang này cụm \"code/test\" (trong design/code/test) chỉ <b>mã nguồn và test<\/b>: phần supplier tự giữ trong tool riêng, trong khi OEM giữ requirement — nơi traceability dễ bị đứt ở ranh giới tổ chức.","u":["A.2"]},{"t":"Patch/OTA","vi":"Bản vá phần mềm phát hành sau SOP, thường gửi qua OTA. Trong bài: mỗi patch/OTA phải đi lại một vòng lifecycle thu nhỏ requirement → change → verification → release, có evidence như bản phát hành chính.","u":["A.2"]},{"t":"approval gate","vi":"Cổng phê duyệt: điểm trong lifecycle mà người có thẩm quyền phải xem evidence và ký duyệt thì mới được đi tiếp (ví dụ trước release). Trong bài là một trong các lớp evidence chạy dọc mọi giai đoạn, cùng traceability, review và test.","u":["A.2"],"aka":["approval gates"]},{"t":"evidence chain","vi":"Chuỗi bằng chứng nối liền requirement → design → code → test → kết quả, mỗi mắt xích truy được về nhau qua traceability. Trong bài, chuỗi này cho phép chứng minh với auditor/khách hàng (và khi điều tra lỗi sau SOP) rằng mỗi requirement đã được làm và kiểm chứng.","u":["A.2"]},{"t":"DoS","vi":"Tấn công từ chối dịch vụ: làm một dịch vụ không dùng được (treo, quá tải, cạn tài nguyên). Trong bài là một loại threat lên tính sẵn sàng (availability), ví dụ làm treo service hiển thị cảnh báo trên cluster.","u":["A.3"],"full":"Denial of Service","cs":true},{"t":"OSS","vi":"Phần mềm mã nguồn mở. Trong bài, OSS là third-party component: xe <b>kế thừa lỗ hổng<\/b> của nó, upstream thường ngừng hỗ trợ sớm hơn đời xe, nên phải có SBOM, theo dõi CVE và owner vá lỗi như mọi supplied part.","u":["A.3"],"full":"Open-Source Software","cs":true},{"t":"BOM","vi":"Danh sách thành phần tạo nên một sản phẩm. Trong bài xuất hiện trong <b>SBOM<\/b> (Software Bill of Materials): danh sách thành phần phần mềm và version của từng build, giúp biết ngay xe nào bị ảnh hưởng khi có CVE mới.","u":["A.3"],"full":"Bill of Materials","cs":true},{"t":"flashing","vi":"Nạp (ghi) phần mềm vào bộ nhớ ECU. Trong bài, diagnostic flashing (nạp qua cổng chẩn đoán) là một entry point tấn công: kẻ xấu có thể cài image giả mạo nếu không có secure boot, ký số và xác thực.","u":["A.3"]},{"t":"black-box","vi":"Hộp đen: thành phần chỉ có binary, không thấy mã nguồn bên trong. Trong bài: component black-box của supplier rất khó tự kiểm tra lỗ hổng, nên phải dựa vào SBOM, vulnerability monitoring và điều khoản SLA vá lỗi với supplier.","u":["A.3"]},{"t":"compliance","vi":"Tuân thủ quy định, tiêu chuẩn, luật. Trong bài là việc đáp ứng UN R155/R156, ISO/SAE 21434 để được phê duyệt bán xe; yêu cầu chính thức phải theo compliance process nội bộ, còn engineering chuẩn bị evidence.","u":["A.3"]},{"t":"build reproducible","vi":"Build tái lập được: dựng lại đúng binary của một baseline cũ (cùng source, toolchain, config). Trong bài là điều kiện để làm patch cho bản phần mềm đang chạy trên xe nhiều năm sau SOP và test regression chính xác.","u":["A.3"]},{"t":"feasibility","vi":"Tính khả thi. Trong bài là <b>attack feasibility<\/b> trong TARA: kẻ tấn công thực hiện được một threat dễ hay khó (cần chuyên môn, thời gian, thiết bị, quyền truy cập gì); kết hợp với impact để xếp mức rủi ro.","u":["A.3"]},{"t":"liability","vi":"Trách nhiệm pháp lý/gánh nặng phải chịu khi có sự cố. Trong bài, \"open-source liability\": dùng open source thì OEM tự chịu trách nhiệm vá lỗ hổng và hậu quả, vì upstream không cam kết hỗ trợ suốt đời xe.","u":["A.3"]},{"t":"walkthrough","vi":"Đi qua từng bước một quy trình hoặc tình huống để hiểu và kiểm tra. Trong bài là bài tập đi qua triage một CVE theo tám bước (mục 7) và ghi lại kết luận, ví dụ VEX: bị ảnh hưởng hay không, vì sao.","u":["A.3"]},{"t":"ECU/VM","vi":"ECU hoặc máy ảo (VM – Virtual Machine): nơi một thành phần phần mềm được triển khai. Trong bài, deployment view trả lời component chạy ở ECU/VM/container/cloud nào, ví dụ speed producer trên partition RTOS, cloud uploader trên partition AAOS.","u":["A.4"],"cs":true},{"t":"E/E","vi":"Điện/điện tử. <b>E/E architecture<\/b> là kiến trúc điện–điện tử của xe: các ECU/compute, mạng (CAN, LIN, Ethernet), dây điện, nguồn và cách bố trí chúng (distributed, domain, zonal, centralized).","u":["A.4"],"aka":["E/E architecture"],"full":"Electrical/Electronic","cs":true},{"t":"fleet issue","vi":"Sự cố đội xe: lỗi lặp lại trên nhiều xe cùng loại ngoài thực tế. Trong bài chỉ được nhắc như tình huống của B.2: phát hiện fleet issue nên làm ở edge (trên xe) hay cloud, với đầy đủ trade-off.","u":["A.4"],"aka":["fleet issues","fleet issue detection"]},{"t":"database","vi":"Cơ sở dữ liệu. Trong bài: trên CAN, \"interface\" là một frame định nghĩa trong database (file mô tả CAN như DBC); với service, interface là một API có owner, version và consumer.","u":["A.4"],"aka":["databases","vulnerability database","vulnerability databases"]},{"t":"vehicle program","vi":"Dự án phát triển một dòng xe hay đời xe cụ thể (có SOP, ngân sách, supplier, variant riêng). Kiến trúc của mỗi vehicle program được dẫn xuất từ reference architecture và chỉ ghi phần khác biệt.","u":["A.4"],"aka":["vehicle programs"]},{"t":"firmware","vi":"Phần mềm nhúng chạy sát phần cứng (trong ECU, cảm biến, modem). Trong bài: bản update phải khớp hardware/firmware variant và calibration của từng xe, nếu không có thể lỗi trên một số xe.","u":["A.4"]},{"t":"usage","vi":"Mức/cách sử dụng. <b>Usage data<\/b>: dữ liệu người dùng dùng feature nào, bao nhiêu, gửi về backend (có consent) để hiểu cách dùng và ưu tiên phát triển.","u":["A.4"]},{"t":"BOM","vi":"Danh mục vật tư và chi phí linh kiện của một sản phẩm. Trong bài: số ECU, dây điện và BOM là một tiêu chí so sánh kiến trúc — zonal thường giảm dây và BOM.","u":["A.4"],"aka":["Bill of Materials","BOMs"],"full":"Bill of Materials","cs":true},{"t":"platform service","vi":"Dịch vụ nền tảng dùng chung trên xe (ví dụ cập nhật, chẩn đoán, logging, cung cấp vehicle data) mà platform đưa ra cho feature/app dùng qua interface chuẩn. Trong bài là một lớp building block của reference architecture, cạnh zone, central compute, partition và cloud service.","u":["A.4"],"aka":["platform services"]},{"t":"platform reuse","vi":"Tái sử dụng nền tảng: dùng lại cùng phần cứng/phần mềm nền (compute, OS, middleware, service, interface chuẩn) cho nhiều vehicle program và feature thay vì làm lại từng dự án. Là một nguyên lý SDV trong bài, đi cùng OTA, diagnostics và operational ownership.","u":["A.4"]},{"t":"BOM","vi":"Bill of Materials – danh mục thành phần tạo nên một sản phẩm. Trong bài xuất hiện qua SBOM (Software Bill of Materials): danh sách mọi thành phần phần mềm trong image, kể cả thư viện bên thứ ba, để theo dõi version và vá lỗ hổng.","u":["A.5"],"aka":["Bill of Materials","BOMs"],"full":"Bill of Materials","cs":true},{"t":"driver/kernel","vi":"Driver (trình điều khiển thiết bị) và kernel (lõi hệ điều hành): lớp thấp của software stack, sát phần cứng. Trong bài: application không nên phụ thuộc chi tiết của driver/kernel (như mở trực tiếp device file) mà nên đi qua API/service chuẩn.","u":["A.5"]},{"t":"menu","vi":"Trình đơn. Ở đây dùng như ẩn dụ: API giống “menu món” mà lớp dưới đưa ra để lớp trên chọn gọi — lớp trên chỉ cần biết món nào có, không cần biết bếp nấu thế nào.","u":["A.5"],"aka":["menus"]},{"t":"portable","vi":"Di động, dễ mang sang nền khác. Trong bài xuất hiện trong tên POSIX (Portable Operating System Interface): bộ API chuẩn kiểu Unix giúp code chạy được trên cả Linux và QNX mà ít phải sửa.","u":["A.5"],"aka":["portability"]},{"t":"mechanism","vi":"“Cơ chế”: cách kỹ thuật để đạt một mục tiêu. Trong bài: workload có deadline nghiêm ngặt cần mechanism (PREEMPT_RT, CPU isolation…) và evidence bổ sung.","u":["A.5"],"aka":["mechanisms"]},{"t":"algorithm","vi":"“Thuật toán”: cách tính toán trong code. Trong bài: “response chậm” có thể do algorithm, queue, scheduler, IPC, driver hay network — cần observability để khoanh vùng.","u":["A.5"],"aka":["algorithms"]},{"t":"expose","vi":"“Phơi ra, công bố”: cung cấp một chức năng/dữ liệu qua interface cho bên khác dùng. Trong bài: expose vehicle service chuẩn hóa thay vì raw bus signal.","u":["A.5"],"aka":["exposed","exposes"]},{"t":"scalable","vi":"Có khả năng mở rộng. Trong bài xuất hiện trong tên SOAFEE (Scalable Open Architecture For Embedded Edge): kiến trúc mở cho máy tính nhúng trên xe, có thể mở rộng số service/container.","u":["A.5"]},{"t":"slot","vi":"Khe, ngăn chứa. Trong bài là <b>A/B slot<\/b>: hai vùng lưu image phần mềm; OTA ghi bản mới vào slot đang không chạy, nếu lỗi hay mất điện giữa chừng xe vẫn boot lại từ slot cũ.","u":["A.5"],"aka":["slots"]},{"t":"rubric","vi":"Bảng tiêu chí chấm điểm, mô tả mỗi mức đạt được trông như thế nào. Trong bài, workshop của A.5 được làm và chấm theo khung và rubric Lesson 2 (A.5 Workshop Rubric).","u":["A.5"],"aka":["rubrics"]},{"t":"safety/availability","vi":"An toàn và tính sẵn sàng. Trong bài: feature requirement phải ghi rõ nếu feature trễ hoặc hỏng thì ảnh hưởng safety/availability thế nào và hậu quả của failure là gì.","u":["A.5"]},{"t":"consequences","vi":"Hệ quả. Trong bài: <i>failure consequence<\/i> — hậu quả khi feature trễ hạn hoặc hỏng (ví dụ cluster hiển thị sai tốc độ), dùng để đánh giá mức nghiêm trọng và lượng isolation/evidence cần có.","u":["A.5"],"aka":["consequence","Consequences"]},{"t":"emulation","vi":"Giả lập: hypervisor mô phỏng một thiết bị bằng phần mềm để guest dùng như thiết bị thật. Portable, dễ tách, nhưng tốn overhead và tăng latency.","u":["A.6"],"aka":["emulator","emulators"]},{"t":"flexibility","vi":"Tính linh hoạt: dễ thay đổi, mở rộng, chia lại tài nguyên theo nhu cầu. Trong bài là ưu điểm của dynamic sharing/workload non-critical, đánh đổi với determinism và evidence.","u":["A.6"]},{"t":"capacity","vi":"Dung lượng/năng lực tối đa của tài nguyên (số core, RAM, băng thông). Trong bài: tổng budget đã reserve không được vượt capacity, và cần chừa headroom.","u":["A.6"]},{"t":"proposal","vi":"Bản đề xuất. Trong bài là tài liệu kiến trúc SA đưa ra để duyệt, vd partitioning proposal gồm inventory, budget, policy, failure scenario, lựa chọn hypervisor và kế hoạch test.","u":["A.6"],"aka":["proposals"]},{"t":"choice","vi":"Sự lựa chọn. Trong bài: device model choice – chọn emulation, VirtIO hay passthrough cho từng thiết bị.","u":["A.6"],"aka":["choices"]},{"t":"selection","vi":"Sự lựa chọn, tuyển chọn. Hypervisor selection criteria là bộ tiêu chí (knockout + chấm điểm) để chọn hypervisor.","u":["A.6"]},{"t":"mechanism","vi":"Cơ chế. Isolation mechanisms là các biện pháp kỹ thuật thực thi cô lập: CPU pinning, stage-2 page table, IOMMU, VLAN, quota…","u":["A.6"],"aka":["mechanisms"]},{"t":"allow-list","vi":"Danh sách cho phép: chỉ cho qua những gì đã khai báo hợp lệ, còn lại bị chặn. Trong bài: virtual switch/firewall dùng allowlist giới hạn traffic mỗi VM được gửi, để guest không critical không làm nghẽn mạng dùng chung.","u":["A.6"],"aka":["allowlist","allow list","whitelist"]},{"t":"throttling","vi":"Hãm lại, giới hạn tốc độ dùng tài nguyên. Trong bài: budget enforcement — partition dùng vượt budget thì bị throttle (bị hãm lại) chứ không được lấy phần budget của partition khác.","u":["A.6"],"aka":["thermal throttling","throttle","throttled"]},{"t":"fault isolation","vi":"Cô lập lỗi: lỗi trong một partition/VM (crash, treo, kernel panic) bị giữ bên trong, không lan sang workload khác. Trong bài là một kiểu isolation của FFI, cùng spatial, temporal, resource isolation, phải chứng minh bằng fault injection trên target.","u":["A.6"]},{"t":"recommendation","vi":"Khuyến nghị: đề xuất có lý do mà SA đưa cho người có thẩm quyền. Trong bài: SA phân tích phương án, trade-off, rủi ro rồi đưa recommendation; quyết định cuối thuộc owner/ARB theo phân tầng quyền quyết định, SA không thay product, safety hay business owner.","u":["A.7"]},{"t":"compliance","vi":"Tuân thủ quy định, tiêu chuẩn, luật (ví dụ ISO 26262, UNECE R155). Trong bài: quyết định có ảnh hưởng safety/cyber/compliance là một điều kiện phải <b>escalate<\/b> lên cấp có thẩm quyền (ARB), không để team tự chốt.","u":["A.7"]},{"t":"line","vi":"Dòng. Trong bài xuất hiện trong LOC (Lines of Code – số dòng code): bài nhấn mạnh complexity không đo bằng số dòng code mà bằng số interface, consumer, variant, stakeholder và version phải hỗ trợ.","u":["A.7"]},{"t":"evidence link","vi":"Liên kết tới bằng chứng thật (review record, kết quả đo, test report) của một quyết định. Trong bài: mỗi quyết định trong ADR/decision log cần evidence link để người sau kiểm được vì sao chốt như vậy, chứ không chỉ ghi kết luận.","u":["A.7"]},{"t":"stability","vi":"Độ ổn định. Trong bài: <b>requirement stability<\/b> — requirement đã ổn định hay còn thay đổi nhiều; là một yếu tố để chọn V-Model, agile hay hybrid (requirement càng hay đổi càng cần vòng phản hồi ngắn).","u":["A.7"]},{"t":"agent","vi":"Tác tử AI: chương trình dùng LLM chạy vòng lặp nhận context → chọn và gọi tool → đọc kết quả → làm tiếp cho tới khi xong việc (Agent = LLM + Context + Tools). Trong khóa, agent (như Claude Code) chỉ được làm trong mức ủy quyền L0–L5 ghi ở Delegation Map, bị chặn bằng hook/permission và kiểm bằng verifier.","u":["AI"]},{"t":"tool","vi":"Công cụ mà agent được phép gọi để hành động: đọc/sửa file, chạy lệnh, tìm kiếm, gọi API hay server MCP. Trong khóa: tool phải có interface rõ (ACI) để agent không dùng sai, phân biệt tool chỉ-đọc với tool có quyền ghi, và giới hạn bằng permission.","u":["AI"]},{"t":"context","vi":"Ngữ cảnh: toàn bộ thông tin đưa vào model trong một lần gọi — chỉ dẫn, file, lịch sử hội thoại, kết quả tool — bị giới hạn bởi context window. Trong khóa: chất lượng output phụ thuộc context đủ và sạch; context quá dài làm giảm chất lượng; tri thức dự án được ngoại hóa thành context artifact (ví dụ CLAUDE.md).","u":["AI"]},{"t":"model","vi":"Mô hình AI, chủ yếu là mô hình ngôn ngữ lớn (LLM) như Claude: nhận prompt/context và sinh văn bản trả lời. Trong khóa: chọn model theo việc và chi phí; model có thể bịa (hallucinate) nên output phải được kiểm; dữ liệu khách chỉ đưa vào model/endpoint đúng mức phân loại.","u":["AI"]},{"t":"prompt","vi":"Lời nhắc/câu lệnh gửi cho model AI để giao việc. Trong khóa: prompt tốt theo khung C-T-R (bối cảnh – nhiệm vụ – yêu cầu) có ràng buộc và acceptance criteria; prompt chỉ là gợi ý, quy tắc cứng phải cưỡng chế bằng hook/permission/validator.","u":["AI"]},{"t":"lab","vi":"Bài thực hành có repo/môi trường dựng sẵn để làm và chứng minh một nguyên lý (ví dụ lab prompt injection, lab log-sanitization, lab verifier). Trong khóa, tốt nghiệp đòi demo lab trực tiếp chứ không chỉ nộp tài liệu.","u":["AI"]},{"t":"workflow","vi":"Luồng công việc gồm các bước có thứ tự, mỗi bước có đầu ra kiểm được. Trong khóa: workflow được phân rã thành bước Máy/Agent/Người với mức L; workflow (luồng định sẵn bằng code) được phân biệt với agent tự quyết (autonomous) — chọn ở mức kiến trúc.","u":["AI"]},{"t":"token","vi":"Đơn vị văn bản nhỏ (mẩu từ) mà LLM đọc và sinh ra; độ dài context, giới hạn và chi phí đều tính theo token. Trong khóa: số token usage chỉ đo chi phí, không phải outcome — KPI phải đo kết quả công việc thật.","u":["AI"]},{"t":"hook","vi":"Móc kiểm tra: script do Claude Code/agent tự chạy tại các thời điểm cố định (trước/sau khi gọi tool, khi kết thúc) để kiểm tra, chặn hoặc báo lỗi. Trong khóa, hook là cách cưỡng chế bằng code (ví dụ hook chặn sửa file cấm), khác lời dặn trong CLAUDE.md mà agent có thể bỏ qua.","u":["AI"]},{"t":"artifact","vi":"Sản phẩm công việc lưu lại được và dùng chung: Delegation Map, context artifact (CLAUDE.md, skill), rules, runbook… giúp tri thức không phụ thuộc người viết. <i>Artifacts<\/i> còn là tính năng của Claude chat hiển thị tài liệu/code sinh ra trong một khung riêng.","u":["AI"]},{"t":"permission","vi":"Quyền của agent khi dùng tool: cấu hình <b>allow<\/b> (cho làm), <b>ask<\/b> (hỏi người trước), <b>deny<\/b> (cấm) cho từng lệnh, file, tool. Trong khóa: permission là ràng buộc cứng do hệ thống cưỡng chế (ví dụ deny đọc .env), khác gợi ý trong CLAUDE.md.","u":["AI"]},{"t":"cache","vi":"Bộ nhớ đệm. Trong khóa là prompt cache / KV cache: phần đầu prompt giống hệt lần trước được tái dùng nên rẻ và nhanh hơn. Vì vậy thứ tự prompt quan trọng: phần cố định đặt trước; một thay đổi nhỏ ở đầu có thể phá cache và nhân chi phí.","u":["AI"]},{"t":"task","vi":"Nhiệm vụ, việc cụ thể giao cho AI/agent. Trong khóa: task prompt phải nêu bối cảnh, việc cần làm, ràng buộc và acceptance criteria; task phải đủ hẹp để đo và đủ rõ để kiểm kết quả.","u":["AI"]},{"t":"injection","vi":"Sự chèn vào. Trên trang AI chủ yếu là prompt injection: lệnh độc giấu trong dữ liệu agent đọc (file, web, ticket) khiến agent làm điều không được giao. Phòng bằng cách coi nội dung đọc vào là dữ liệu chứ không phải lệnh, cộng permission và hook chặn.","u":["AI"]},{"t":"setting","vi":"Thiết lập, cấu hình. Trong khóa: settings của Claude Code (file settings.json) khai báo permission, hook…; managed policy settings là cấu hình tổ chức áp từ trên xuống, người dùng không tự gỡ được. “Goal Setting” = đặt mục tiêu.","u":["AI"]},{"t":"set","vi":"Tập hợp, bộ. Trong khóa thường gặp trong golden set (bộ ví dụ chuẩn đã kiểm là đúng) và test set (bộ ca dùng để chấm eval), dùng để so output của AI thay vì đánh giá bằng cảm giác.","u":["AI"]},{"t":"evaluation","vi":"Đánh giá (eval): chạy AI/agent trên một bộ ca có đáp án hoặc rubric để đo chất lượng bằng số (đúng/sai, precision/recall) thay cho “kiểm bằng cảm giác”. Trong khóa gồm golden set, regression evaluation, LLM-as-a-judge và verifier.","u":["AI"]},{"t":"project","vi":"Dự án. Trên trang AI còn chỉ tính năng <i>Projects<\/i> của Claude: không gian làm việc chứa tài liệu nền và chỉ dẫn cố định dùng lại cho mọi chat, khỏi copy-paste bối cảnh. Ngoài ra là project thật của học viên để áp dụng.","u":["AI"]},{"t":"chat","vi":"Trò chuyện với AI qua giao diện hỏi–đáp (như Claude chat). Mỗi lượt, toàn bộ lịch sử được gửi lại cho model làm context; với việc lặp lại nên dùng Project thay vì mở chat mới rồi dán lại bối cảnh.","u":["AI"]},{"t":"rubric","vi":"Bảng tiêu chí chấm, mô tả từng mức đạt. Trong khóa AI, rubric dùng để chấm output của model, kể cả khi để một model khác chấm (LLM-as-a-judge) — cần đo mức đồng thuận với người vì judge cũng có thể sai.","u":["AI"]},{"t":"recall","vi":"Độ phủ (recall): tỉ lệ ca đúng thật mà bộ kiểm/AI bắt được trên tổng số ca đúng thật; đi cặp với precision (tỉ lệ báo đúng trong số đã báo). Trong khóa dùng để đo eval và verifier theo từng chiều.","u":["AI"]},{"t":"SOP","vi":"Quy trình thao tác chuẩn: các bước làm việc viết sẵn theo thứ tự. Trong khóa: prompt dạng SOP (process-driven prompt) mô tả quy trình từng bước cho agent, tốt hơn nhồi các luật rời rạc và không phụ thuộc người viết.","u":["AI"],"full":"Standard Operating Procedure","cs":true},{"t":"handling","vi":"Sự xử lý. Trong khóa là error handling của agent: phát hiện lỗi (tool lỗi, API 404/500, phản hồi chậm, output vô nghĩa) → xử lý (log, retry có giới hạn) → phục hồi (rollback, tự sửa, escalate).","u":["AI"]},{"t":"stream","vi":"Dòng chảy. Trên trang AI gặp trong value-stream (chuỗi giá trị): toàn bộ các bước một công việc đi qua để tạo ra giá trị; value-stream map giúp chọn đúng bước đáng đưa AI vào và đo mốc trước–sau.","u":["AI"]},{"t":"machine","vi":"Máy. Trong tam phân Máy/Agent/Người, Máy là bước làm bằng chương trình xác định (script, validator, CI): cùng input luôn cho cùng kết quả, không cần model. Nguyên tắc: phần đúng/sai xác định để máy kiểm, phần phán đoán để người.","u":["AI"]},{"t":"verify","vi":"Kiểm chứng, xác minh có đúng không. Trong khóa: Verify là chức năng kiểm output của agent bằng verifier/test/eval — tự đọc kết quả máy (exit code, test log) chứ không tin lời agent báo “đã xong”; đi cặp với Constrain (giới hạn trước khi chạy).","u":["AI"]},{"t":"routing","vi":"Định tuyến: phân loại yêu cầu rồi chuyển tới nhánh, prompt hay model phù hợp. Trong khóa là một mẫu agentic (Routing), có thể làm bằng LLM, embedding, rule hay ML truyền thống.","u":["AI"]},{"t":"orchestration","vi":"Điều phối nhiều agent/bước: một orchestrator chia việc, giao cho các specialist agent, gom kết quả và quyết định bước tiếp. Trong khóa: việc có phụ thuộc thì chạy tuần tự, độc lập mới song song.","u":["AI"]},{"t":"pattern","vi":"Mẫu thiết kế: cách giải đã đặt tên cho bài toán lặp lại. Trong khóa là agentic design pattern như prompt chaining, routing, reflection, planning, multi-agent; nguyên tắc “keep it simple” — chỉ dùng pattern phức tạp khi đo thấy cần.","u":["AI"]},{"t":"endpoint","vi":"Điểm cuối dịch vụ: địa chỉ API của một dịch vụ/model AI mà công cụ gọi tới. Trong khóa: dữ liệu chỉ được gửi tới endpoint đã duyệt đúng mức phân loại (endpoint trong hạ tầng FPT, nhà cung cấp có DPA, zero-retention).","u":["AI"]},{"t":"reflection","vi":"Tự phản tỉnh: mẫu agentic trong đó model xem lại, phê bình output của chính nó (hoặc để model khác chấm) rồi sửa trước khi trả kết quả. Tăng chất lượng nhưng tốn thêm lượt gọi và không thay được verifier.","u":["AI"]},{"t":"usage","vi":"Mức sử dụng. Trong khóa: token usage (lượng token tiêu thụ → chi phí) và AI usage (mức AI tham gia công việc). Bài cảnh báo: đo usage không phải đo outcome; tuyên bố AI usage với khách phải đúng mức hợp đồng.","u":["AI"]},{"t":"env","vi":"Viết tắt của environment. Trên trang AI chủ yếu là file .env chứa biến môi trường và bí mật (API key, mật khẩu): luật cứng là AI không được đọc/đụng tới, thường chặn bằng permission deny.","u":["AI"]},{"t":"ambiguity","vi":"Sự mơ hồ, có thể hiểu nhiều cách. Trong khóa là một trong bốn câu hỏi xếp bước vào Máy/Agent/Người: đúng/sai có tiêu chí rõ, kiểm được bằng chương trình thì giao Máy; càng mơ hồ càng cần người phán đoán.","u":["AI"]},{"t":"framework","vi":"Khung. Trên trang AI: (1) agent framework — thư viện dựng sẵn để xây agent/multi-agent; (2) khung tư duy như CASAN, khung 4D. Nên hiểu cơ chế bên dưới trước khi dựa vào framework.","u":["AI"]},{"t":"mode","vi":"Chế độ. Trên trang AI: chế độ làm việc của agent, ví dụ plan mode (agent trình kế hoạch, người duyệt rồi mới làm); access mode của property VHAL; failure mode (kiểu hỏng).","u":["AI"]},{"t":"plan","vi":"Kế hoạch. Trên trang AI: Planning là mẫu agentic trong đó agent lập kế hoạch nhiều bước trước khi làm; plan mode cho người duyệt kế hoạch trước khi agent sửa code.","u":["AI"]},{"t":"fail-safe","vi":"An toàn khi hỏng / mặc định an toàn. Trong khóa là nguyên tắc <b>Fail-Safe Defaults<\/b>: mọi năng lực, quyền của agent tắt sẵn, chỉ bật khi được cấp rõ; cưỡng chế bằng hạ tầng (permission, hook), khi nghi ngờ hoặc lỗi thì chặn (fail-closed).","u":["AI"]},{"t":"disclosure","vi":"Sự tiết lộ/công bố. Trong khóa chủ yếu là <b>progressive disclosure<\/b>: nạp thông tin vào context dần dần — ban đầu agent chỉ thấy mô tả ngắn (của skill, tài liệu), khi cần mới đọc chi tiết, để tiết kiệm context.","u":["AI"]},{"t":"server","vi":"Máy chủ: chương trình/dịch vụ cung cấp chức năng cho bên khác (client) gọi tới. Trong khóa chủ yếu là <b>MCP server<\/b>: chương trình cung cấp tool và nguồn dữ liệu cho agent qua chuẩn MCP, viết một lần dùng lại cho nhiều agent.","u":["AI"]},{"t":"active","vi":"Chủ động. Trong khóa: <b>active tool selection/discovery<\/b> — agent chủ động tìm và chọn tool phù hợp trong danh sách lớn thay vì nạp sẵn mọi tool vào context (quá nhiều tool làm agent chọn sai); cũng là tên một lab.","u":["AI"]},{"t":"use","vi":"Dùng, sử dụng. Trong khóa: <b>Tool Use<\/b> — mẫu thiết kế agent gọi tool (hàm như đọc file, chạy test, query) để hành động thay vì chỉ trả lời bằng chữ; còn có AI usage (mức dùng AI) trong dự án.","u":["AI"]},{"t":"learning","vi":"Việc học. Trong khóa: <b>Learning Plan<\/b> (kế hoạch học, nguồn các câu hỏi/tiêu chí của từng unit) và <b>Learning<\/b> — một mẫu Agentic Design Pattern nâng cao, nơi agent học/thích nghi từ phản hồi và kết quả trước đó.","u":["AI"]},{"t":"window","vi":"Cửa sổ. Trong khóa chủ yếu là <b>context window<\/b>: lượng token tối đa model đọc được trong một lần gọi (prompt, file, lịch sử, kết quả tool). Đầy cửa sổ hoặc nhồi thông tin thừa thì agent bỏ sót và trả lời kém.","u":["AI"]},{"t":"factor","vi":"Hệ số / yếu tố. Trong khóa: <b>factor/offset<\/b> trong DBC — hệ số nhân để đổi giá trị raw của signal CAN thành giá trị vật lý (raw × factor + offset); và <b>bus factor<\/b> — bao nhiêu người rời đi thì công việc đứng lại.","u":["AI"]},{"t":"stack","vi":"Chồng/ngăn xếp. Trong khóa chủ yếu là <b>stack trace<\/b>: danh sách các hàm đang gọi nhau tại lúc lỗi xảy ra, in ra khi chương trình crash — dùng đối chiếu root cause; tool nên trả lỗi dễ hiểu cho agent thay vì stack trace thô.","u":["AI"]},{"t":"deterministic","vi":"Tất định: cùng đầu vào thì luôn cùng kết quả (code, script, validator). Trong khóa đây là đặc trưng của nhóm <b>Máy<\/b>, đối lập với model/agent mang tính xác suất (cùng prompt có thể ra khác nhau) — việc cần đúng 100% thì giao cho thứ deterministic.","u":["AI"]},{"t":"JSON","vi":"Định dạng dữ liệu văn bản có cấu trúc (khóa–giá trị, mảng). Trong khóa: yêu cầu model/agent trả kết quả dạng JSON theo schema để code (verifier, validator) kiểm được tự động, thay vì đọc văn bản tự do; parse lỗi thì chặn (fail-closed).","u":["AI"],"full":"JavaScript Object Notation","cs":true},{"t":"recommended","vi":"Đề xuất/khuyến nghị. Trong khóa là mức <b>L2 · Recommend<\/b> của thang ủy quyền: agent đưa 2–3 phương án kèm trade-off, người quyết định chọn phương án nào.","u":["AI"]},{"t":"information","vi":"Thông tin. Trong khóa: <b>Information Sufficiency<\/b> — chất lượng output phụ thuộc độ đầy đủ, rõ ràng của thông tin trong context; <b>information gain<\/b> — nhiều agent chỉ đáng khi cộng tác tạo ra thông tin mới.","u":["AI"]},{"t":"policy","vi":"Chính sách/quy định được viết ra để hệ thống tuân theo. Trong khóa: <b>managed policy settings<\/b> của Claude Code — cấu hình cấp tổ chức (permission, hook…) mà user, project, local settings không ghi đè được; dùng cưỡng chế luật cho agent bằng hạ tầng.","u":["AI"]},{"t":"staged","vi":"Theo từng giai đoạn. Trong khóa: <b>staged system prompt<\/b> — một agent đổi chỉ dẫn và bộ tool theo từng giai đoạn công việc (ví dụ thiết kế → code → review), review trượt thì lùi lại giai đoạn trước; cũng là tên một lab.","u":["AI"]},{"t":"exception","vi":"Ngoại lệ. Trong khóa: <b>Exception Handling<\/b> — mẫu thiết kế agent phát hiện lỗi (tool lỗi, timeout, output vô nghĩa), xử lý (log, retry) và phục hồi (rollback, escalate); và exception khi đưa quy tắc thành code — miễn trừ ghi rõ quy tắc, lý do, người duyệt, hạn hiệu lực.","u":["AI"]},{"t":"completion","vi":"Phần hoàn thành. Trong khóa: <b>completion<\/b> là văn bản model sinh trả lại sau khi nhận prompt (một lần hỏi–đáp = một lần gọi); là một dạng model output phải được kiểm (evaluation) trước khi chấp nhận.","u":["AI"]},{"t":"bias","vi":"Thiên lệch: sai lệch có hệ thống. Trong khóa là rủi ro của model: output nghiêng theo mẫu phổ biến trong dữ liệu huấn luyện (ví dụ gợi ý code kiểu thông dụng thay vì đúng quy ước dự án), hoặc model chấm thiên vị — cần kiểm bằng verifier và người.","u":["AI"]},{"t":"internal","vi":"Nội bộ. Trong khóa là một nhãn phân loại dữ liệu (public, <b>internal<\/b>, confidential, personal, regulated): tài liệu nội bộ công ty như quy ước code, template — chỉ đưa vào công cụ AI ở mức được duyệt cho dữ liệu nội bộ.","u":["AI"]},{"t":"replay","vi":"Phát lại / chạy lại. Trong khóa: workflow AI cần <b>replay được<\/b> — có trace id, log có cấu trúc và đầu vào lưu lại để chạy lại đúng một lần chạy cũ khi điều tra lỗi hoặc so sánh sau khi đổi model/prompt.","u":["AI"]},{"t":"change management","vi":"Quản lý thay đổi tổ chức: giúp con người chấp nhận và làm theo cách làm mới (truyền đạt lý do, đào tạo, xử lý kháng cự). Trong khóa là một trong ba thứ (cùng training, continuous improvement) giúp workflow AI sống lâu sau khi triển khai.","u":["AI"]},{"t":"chain","vi":"Chuỗi. Trong khóa: <b>chain of thought<\/b> — model trình bày từng bước suy luận trước khi kết luận; <b>prompt chaining<\/b> — chia việc thành chuỗi lời gọi model, đầu ra bước trước là đầu vào bước sau, có kiểm ở giữa.","u":["AI"]},{"t":"native","vi":"Gốc, nguyên bản. Trong khóa: <b>AI-native<\/b> — cấp 5 của CASAN: quy trình được thiết kế quanh AI từ đầu trên toàn vòng đời, AI là lõi vận hành ở quy mô tổ chức, người chỉ duyệt ngoại lệ/rủi ro cao.","u":["AI"]},{"t":"bounded","vi":"Có giới hạn, có biên. Trong khóa: <b>L3 · Execute (bounded)<\/b> — agent được tự thực thi nhưng chỉ trong phạm vi đã khoanh (thư mục, tool, quyền, loại việc rủi ro thấp); ra ngoài biên thì phải dừng hỏi người.","u":["AI"]},{"t":"escalation path","vi":"Đường chuyển cấp: ghi sẵn khi nào agent phải dừng (requirement mơ hồ, validator lỗi, chạm dữ liệu vượt mức, vùng đỏ), chuyển cho ai và kèm thông tin gì — để agent không tự đoán khi gặp tình huống ngoài phạm vi.","u":["AI"]},{"t":"clear","vi":"Rõ ràng. Trong khóa: <b>Clear Interface<\/b> — tool phải được thiết kế để agent hiểu và khó dùng sai: tên trực quan, tham số có ví dụ và kiểu chặt (enum, schema), lỗi trả về có cấu trúc.","u":["AI"]},{"t":"KV","vi":"Khóa–giá trị. Trong khóa là <b>KV cache<\/b>: bộ nhớ đệm model giữ lại phần tính toán cho đoạn đầu prompt đã gặp; phần đầu prompt giữ ổn định thì được dùng lại, giảm chi phí và độ trễ — vì vậy thứ tự sắp xếp prompt quan trọng.","u":["AI"],"full":"Key-Value","cs":true},{"t":"selection","vi":"Sự lựa chọn. Trong khóa: <b>tool selection<\/b> — agent chọn tool nào để gọi dựa trên tên, mô tả, tham số; quá nhiều tool hoặc mô tả mơ hồ làm độ chính xác chọn tool giảm.","u":["AI"]},{"t":"cost","vi":"Chi phí. Trong khóa là chi phí chạy AI: token (đầu vào/đầu ra), số lời gọi, thời gian, chi phí chạy eval và công người review; đo đầu-cuối theo từng bước để so sánh phương án (ví dụ đơn agent vs nhiều agent).","u":["AI"]},{"t":"goal","vi":"Mục tiêu. Trong khóa: <b>Goal Setting &amp; Monitoring<\/b> — mẫu thiết kế agent có mục tiêu và tiêu chí xong đo được, tự theo dõi tiến độ và dừng/điều chỉnh khi lệch.","u":["AI"]},{"t":"package","vi":"Gói. Trong khóa: <b>context package<\/b> — bộ tài liệu đóng gói sẵn cho agent làm một loại việc lặp lại (mục tiêu, quy tắc, nguồn, ví dụ, cách kiểm…), có phiên bản và đổi cùng code.","u":["AI"]},{"t":"feedback loop","vi":"Vòng phản hồi. Trong khóa là vòng agent làm → chạy test/build/lint → đọc kết quả → tự sửa, lặp đến khi đạt; không có test tự động thì không có vòng phản hồi, agent chỉ đoán là xong.","u":["AI"]},{"t":"complete","vi":"Đầy đủ, hoàn tất. Trong khóa: <b>completeness<\/b> là một chiều kiểm output AI — có đủ mọi phần được yêu cầu, không bỏ sót ca nào — cạnh correctness, consistency, safety, usefulness.","u":["AI"]},{"t":"rework","vi":"Làm lại: sửa lại công việc đã làm vì chưa đạt. Trong khóa là một chỉ số đo workflow AI: bao nhiêu output của agent phải sửa/làm lại sau review — nhanh mà rework nhiều thì không có lợi thật.","u":["AI"]},{"t":"proxy","vi":"Đại diện/trung gian. Trong khóa là <b>proxy metric<\/b>: chỉ số thay thế dễ đo nhưng không phản ánh kết quả thật (như số prompt, số token); đo workflow AI phải bằng kết quả thật của từng lần chạy.","u":["AI"]},{"t":"bus","vi":"Đường truyền dùng chung (CAN bus…). Trong khóa còn có <b>bus factor<\/b>: bao nhiêu người rời đi thì công việc đứng lại — bus factor bằng 1 (chỉ một người hiểu workflow AI) là một lỗi, sửa bằng runbook và context dùng chung.","u":["AI"]},{"t":"database","vi":"Cơ sở dữ liệu. Trong khóa là ví dụ tool của agent: query database (chỉ-đọc là rủi ro thấp, ghi là rủi ro cao hơn) — quyền của tool phải khớp mức nhạy cảm của dữ liệu nó chạm được.","u":["AI"]},{"t":"email","vi":"Thư điện tử. Trong khóa: email là một nguồn dữ liệu agent đọc có thể chứa prompt injection, và là sự kiện có thể đánh thức agent tự chạy (agent phản ứng khi email đến).","u":["AI"]},{"t":"gap","vi":"Khoảng trống, khoảng cách. Trong khóa: <b>Gap Analysis<\/b> — đánh giá khoảng cách giữa năng lực hiện tại của SA/PTL và level 3 CASAN; test coverage gap — phần code không có test tự động.","u":["AI"]},{"t":"level","vi":"Mức, cấp độ. Trong khóa: các <b>cấp CASAN<\/b> (khóa đưa SA/PTL tới level 3 — vận hành workflow AI-first có kiểm chứng) và các mức ủy quyền L0–L5 cho agent.","u":["AI"]},{"t":"loop","vi":"Vòng lặp. Trong khóa: <b>agentic loop<\/b> — vòng agent suy nghĩ → gọi tool → đọc kết quả → quyết định bước tiếp, lặp đến khi xong hoặc dừng; human-in-the-loop — người nằm trong vòng để duyệt.","u":["AI"]},{"t":"operate","vi":"Vận hành. Trong khóa là mức <b>L4 · Operate workflow<\/b>: agent vận hành cả luồng công việc có hàng rào, audit và xử lý ngoại lệ; người duyệt các hạng mục an toàn/ngoại lệ.","u":["AI"]},{"t":"function","vi":"Hàm / chức năng. Trong khóa: <b>function calling<\/b> — cơ chế model trả về lời gọi hàm có tên và tham số theo khai báo để chương trình thực thi (cách agent dùng tool); MCP là chuẩn mở, tổng quát hơn function calling riêng của từng hãng.","u":["AI"]},{"t":"client","vi":"Bên dùng dịch vụ. Trong khóa: <b>MCP client<\/b> — phía agent/ứng dụng AI kết nối tới MCP server để lấy tool và dữ liệu (mô hình client-server, khác function calling khai báo 1-1).","u":["AI"]},{"t":"switch","vi":"Công tắc. Trong khóa: <b>master switch<\/b> trong lab ablation — công tắc tắt từng thành phần (context, tool, skill) để có 'bare model' làm mốc so sánh; và kill switch — công tắc tắt ngay workflow AI khi có sự cố.","u":["AI"]},{"t":"manager","vi":"Người/bộ phận quản lý. Trong khóa: <b>manager pattern<\/b> (orchestrator-worker) — một agent điều phối chia việc con cho các agent thợ rồi gom kết quả; tốn token hơn nên chỉ đáng khi tạo thông tin mới.","u":["AI"]},{"t":"memory","vi":"Bộ nhớ. Trong khóa là bộ nhớ của agent: <b>Memory Management<\/b> — quyết định giữ gì trong context, gì lưu ra ngoài (file, CLAUDE.md) giữa các phiên; memory-based injection — chỉ thị độc lưu vào bộ nhớ agent.","u":["AI"]},{"t":"resource","vi":"Tài nguyên. Trong khóa: <b>Resource-Aware<\/b> — mẫu thiết kế agent biết cân đối tài nguyên (token, context, thời gian, chi phí, chọn model mạnh hay rẻ) theo độ khó của việc.","u":["AI"]},{"t":"reasoning","vi":"Lập luận, suy luận. Trong khóa: khả năng model suy luận từng bước trước khi trả lời (reasoning, chain of thought), và <b>Reasoning<\/b> — một mẫu Agentic Design Pattern nâng cao.","u":["AI"]},{"t":"A/B","vi":"Hai phương án A và B. Trong khóa: khi spec mâu thuẫn, agent đưa phương án A/B cho người quyết, không tự chọn; cũng gặp khi so sánh A/B hai cấu hình model/prompt.","u":["AI"],"cs":true},{"t":"exit","vi":"Thoát / lối ra. Trong khóa: <b>exit code<\/b> — mã số một lệnh trả về khi kết thúc (0 = thành công), là đầu ra có cấu trúc mà verifier kiểm được; hook PreToolUse trả exit code 2 thì chặn lời gọi tool.","u":["AI"]},{"t":"offset","vi":"Độ lệch. Trong khóa: <b>factor/offset<\/b> trong DBC — giá trị cộng thêm khi đổi raw của signal CAN sang giá trị vật lý (raw × factor + offset); agent sửa ánh xạ CAN phải khớp đúng factor/offset.","u":["AI"]},{"t":"continuous improvement","vi":"Cải tiến liên tục: đo kết quả đều đặn rồi sửa. Trong khóa là cách giữ workflow AI tốt dần: theo dõi lỗi lọt, lần can thiệp, sửa context/quy tắc hằng tuần rồi chạy lại eval.","u":["AI"]},{"t":"deployment","vi":"Triển khai: đưa vào dùng thật. Trong khóa là triển khai workflow AI vào dự án: cần deployment and governance plan (release manifest, người có thẩm quyền, monitoring, kill switch, rollback) để người khác chạy được.","u":["AI"]},{"t":"assistant","vi":"Trợ lý. Trong khóa: <b>AI assistant<\/b> — model + giao diện chat + chỉ dẫn hành xử; chỉ trả lời bằng chữ, chưa tự hành động như agent (có tool, chạy vòng lặp).","u":["AI"]},{"t":"egress","vi":"Chiều dữ liệu đi ra. Trong khóa: <b>data egress<\/b> — dữ liệu nhạy cảm đi ra khỏi môi trường kiểm soát (dán log có VIN, spec mật vào chat AI công cộng); chặn bằng phân loại dữ liệu, redaction, công cụ AI được duyệt.","u":["AI"]},{"t":"on-board","vi":"Onboard: đưa người mới vào làm quen dự án. Trên trang AI: \"onboard\" agent giống onboard nhân viên mới — cấp context có chọn lọc, có cấu trúc (CLAUDE.md, quy ước, ví dụ) và kiểm chứng được agent đã hiểu đúng.","u":["AI"]},{"t":"return","vi":"Trả về: giá trị/mã thoát (exit code) mà một chương trình trả lại khi chạy xong. Trên trang AI là mã thoát của hook Claude Code: return 2 mới chặn hành động của agent; return 1 chỉ báo lỗi hook, hành động vẫn chạy.","u":["AI"]},{"t":"marketing","vi":"Tiếp thị, quảng bá. Trên trang AI, \"kiểu marketing\" là lời lẽ quảng cáo chung chung (\"AI hỗ trợ toàn diện\") — tránh khi viết tuyên bố AI usage; phải nêu deliverable, phạm vi, nguồn dữ liệu và tiêu chí nghiệm thu cụ thể.","u":["AI"]},{"t":"post","vi":"Sau (tiền tố post-). Trên trang AI gặp trong <b>post-training<\/b>: giai đoạn huấn luyện thêm sau khi model đã được huấn luyện nền (fine-tuning, học từ phản hồi người…) — tầng nằm ngoài phạm vi khóa, vốn chỉ làm việc VỚI model có sẵn.","u":["AI"]},{"t":"EU","vi":"Liên minh châu Âu. Trên trang AI xuất hiện trong bối cảnh pháp lý dữ liệu: GDPR của EU là luật bảo vệ dữ liệu cá nhân, ràng buộc việc đưa dữ liệu (log, VIN, thông tin người) vào tool AI và nơi lưu dữ liệu.","u":["AI"],"full":"European Union","cs":true},{"t":"allow-list","vi":"Danh sách cho phép: chỉ những gì ghi rõ mới được làm, còn lại bị chặn hoặc phải hỏi. Trên trang AI là allowlist trong permission của agent: lệnh/tool an toàn (pytest, git status) được cho qua; đi cặp với denylist (danh sách cấm).","u":["AI"]},{"t":"study","vi":"Nghiên cứu, khảo sát. Trên trang AI gặp trong <b>ablation study<\/b>: tắt/bỏ từng thành phần (prompt, tool, skill, verifier…) một, giữ nguyên phần còn lại, để đo đóng góp thật của thành phần đó.","u":["AI"]},{"t":"discovery","vi":"Khám phá, tìm ra. Trên trang AI: tool discovery — agent tự tìm tool phù hợp khi cần thay vì nạp sẵn toàn bộ schema tool vào context (nạp nhiều làm tốn token và giảm độ chính xác khi chọn tool).","u":["AI"]},{"t":"calibration","vi":"Hiệu chuẩn. Trên trang AI là calibration của judge: đo mức đồng thuận giữa điểm do model/LLM judge chấm với nhãn của người trên cùng một bộ mẫu trước khi tin dùng judge đó trong eval.","u":["AI"]},{"t":"variable","vi":"Biến: đại lượng có thể thay đổi. Trên trang AI gặp trong thí nghiệm đo hiệu quả AI: confounding variable (biến gây nhiễu) — yếu tố không kiểm soát có thể giải thích kết quả thay cho thứ đang được thử.","u":["AI"]},{"t":"cycle time","vi":"Thời gian chu trình: thời gian thực sự làm một việc, từ lúc bắt tay đến lúc xong. Khác lead time (tính cả thời gian chờ). Trên trang AI dùng khi đo hiệu quả workflow AI — báo cáo nhầm hai số này sẽ cho kết luận ngược.","u":["AI"]},{"t":"transform","vi":"Chuyển đổi. Trên trang AI gặp trong AI Transformation / vai trò \"AI Transform\": người có quyền thay đổi cách làm việc của dự án bằng AI agent có kiểm soát.","u":["AI"]},{"t":"manual","vi":"Thủ công, làm bằng tay (tính từ). Trên trang AI: review manual bằng mắt — khi lượng output AI tăng, review thủ công thành nút thắt, nên phải đẩy phần kiểm được sang máy (validator, hook, test).","u":["AI"]},{"t":"customer","vi":"Khách hàng. Trên trang AI gặp trong tinh thần <b>Customer Zero<\/b>: tự làm \"khách hàng đầu tiên\" — áp dụng và chứng minh cách làm AI trên dự án của chính mình trước khi đề xuất cho khách (OEM).","u":["AI"]},{"t":"refines","vi":"Refine/refinement: tinh chỉnh, làm rõ dần. Trên trang AI: business rule refinement — chuốt lại các quy tắc nghiệp vụ thành dạng rõ ràng, kiểm được, thường viết theo quy trình (SOP) thay vì luật rời rạc trong prompt.","u":["AI"]},{"t":"computer","vi":"Máy tính. Trên trang AI gặp trong ACI (Agent-Computer Interface): giao diện giữa agent và máy — tool, lệnh, định dạng input/output — thiết kế rõ ràng và an toàn mặc định để agent dùng đúng, ít lỗi.","u":["AI"]},{"t":"dynamic discovery","vi":"Tìm động lúc chạy. Trong MCP: client hỏi server đang có tool/nguồn dữ liệu nào lúc kết nối, thay vì khai báo cố định sẵn trong code — một điểm khác MCP với function calling thông thường.","u":["AI"]},{"t":"keep","vi":"Giữ. Trên trang AI gặp trong nguyên tắc <b>Keep it simple<\/b>: chọn cấu trúc agent đơn giản nhất đủ giải bài toán (một prompt, một agent) trước khi thêm điều phối nhiều bước hay nhiều agent.","u":["AI"]},{"t":"verifiability","vi":"Khả năng kiểm chứng: một tiêu chí có thể được kiểm đạt/không đạt một cách khách quan. Trên trang AI là nguyên tắc thiết kế verifier/guardrail: chỉ kiểm tin cậy được thứ có cấu trúc (JSON schema, quy tắc), không dựa vào cảm giác.","u":["AI"]},{"t":"production","vi":"Vận hành thật (production): môi trường dùng thật, khác thử nghiệm/demo. Trên trang AI: đưa agent vào production cần \"hợp đồng\" rõ — outcome, tiêu chí nghiệm thu, giới hạn quyền — thay cho kỳ vọng mơ hồ.","u":["AI"]},{"t":"single source of truth","vi":"Nguồn sự thật duy nhất: một nơi giữ bản gốc được mọi bên tham chiếu, tránh nhiều phiên bản mâu thuẫn. Trên trang AI: đặc tả outcome (kết quả cần đạt) làm nguồn duy nhất để agent, reviewer và khách cùng đối chiếu.","u":["AI"]},{"t":"signing","vi":"Sign: ký. Trên trang AI là ký duyệt của người (human sign): ở tầng phán đoán cao nhất, người có thẩm quyền ký xác nhận kết quả — agent không tự ký thay; khác chữ ký số mật mã.","u":["AI"]},{"t":"sandbox","vi":"Hộp cát: môi trường thử bị giới hạn quyền, tách khỏi hệ thống thật. Trên trang AI: nơi học viên/agent chạy thử Claude Code, lệnh và tool an toàn — lỗi trong sandbox không chạm repo, dữ liệu hay hệ thống của dự án.","u":["AI"]},{"t":"master","vi":"Chính, điều khiển chung. Trên trang AI: master switch — công tắc tổng trong lab ablation, tắt/bật từng thành phần (prompt, tool, skill…) để tạo bản \"bare model\" làm mốc so sánh.","u":["AI"]},{"t":"gain","vi":"Lợi ích thu thêm. Trên trang AI gặp trong <b>information gain<\/b>: lượng thông tin mới hữu ích một bước/agent đóng góp; thêm bước hay thêm agent mà không tạo thông tin mới là vô ích hoặc có hại (tốn token).","u":["AI"]},{"t":"transport","vi":"Kênh truyền. Trong MCP, transport là cách client và server trao đổi message (ví dụ qua stdio của tiến trình cục bộ hoặc qua HTTP) — phần nâng cao của chuẩn MCP.","u":["AI"]},{"t":"sample","vi":"Mẫu / lấy mẫu. Trên trang AI: <b>sampling<\/b> trong MCP — tính năng cho phép server nhờ client gọi model sinh nội dung; ngoài ra \"mẫu\" còn là các ca dùng để chấm/eval output.","u":["AI"]},{"t":"notification","vi":"Thông báo. Trong MCP, notifications là message một chiều (không chờ trả lời) giữa client và server, ví dụ báo danh sách tool vừa thay đổi hoặc tiến độ một việc dài.","u":["AI"]},{"t":"AI Transformation","vi":"Tên chính khóa học này: chuyển đổi cách làm việc của SA/PTL sang dùng AI agent (Claude Code) có kiểm soát — CASAN, tam phân Máy/Agent/Người, thang ủy quyền L0–L5, verifier và eval.","u":["AI"]},{"t":"collaboration","vi":"Cộng tác. Trên trang AI: AI collaboration workflow — quy trình người và AI cùng làm một nhiệm vụ kỹ thuật cụ thể: ai làm bước nào, input/context gì, kiểm chứng ra sao, ai quyết định cuối.","u":["AI"]},{"t":"table","vi":"Bảng. Trên trang AI: data classification table — bảng phân loại dữ liệu theo mức nhạy cảm (M1–M3…) để quyết định loại nào được đưa vào tool AI nào.","u":["AI"]},{"t":"edit","vi":"Sửa. Trong Claude Code, <b>Edit<\/b> là tool sửa file của agent; permission có thể deny Edit trên các đường dẫn ngoài scope để chặn agent sửa chỗ không được phép.","u":["AI"]},{"t":"build ID/log","vi":"ID/log: mã định danh (trace id, build ID) và log gốc của một lần chạy. Trên trang AI: mỗi lần chạy agent cần trace id/log để truy vết, replay và để người kiểm lại tóm tắt do AI viết.","u":["AI"]},{"t":"base","vi":"Nền, cơ sở. Trên trang AI gặp trong knowledge base: kho tài liệu nền gắn vào Project/agent để model tra cứu mỗi lần làm việc, thay vì dán lại từ đầu.","u":["AI"]},{"t":"status meeting","vi":"Meeting: cuộc họp. Trên trang AI gặp trong review meeting — buổi họp rà soát mà output AI (bảng, tóm tắt) phải dùng được ngay.","u":["AI"]},{"t":"prediction","vi":"Dự đoán. Trên trang AI: <b>next token prediction<\/b> — cơ chế cốt lõi của LLM, đoán token tiếp theo theo xác suất; vừa là nguồn sáng tạo, vừa là gốc của lỗi bịa (hallucination).","u":["AI"]},{"t":"structure","vi":"Cấu trúc: cách sắp xếp các phần. Trên trang AI là một trong ba tiêu chí chấm output AI (accuracy, structure, voice): bố cục, đề mục, định dạng có đúng như bản mẫu không.","u":["AI"]},{"t":"voice","vi":"Giọng điệu văn bản (văn phong). Trên trang AI là một trong ba tiêu chí chấm output AI (accuracy, structure, voice): văn có đúng giọng, mức trang trọng và cách viết mong muốn không.","u":["AI"]},{"t":"node","vi":"Trên trang AI là Node.js: môi trường chạy JavaScript ngoài trình duyệt, cần cài trước để cài và chạy Claude Code.","u":["AI"]},{"t":"init","vi":"Khởi tạo. Trong Claude Code, lệnh <b>/init<\/b> cho agent đọc repo và đề xuất bản CLAUDE.md đầu tiên (file context của dự án) khi dự án chưa có.","u":["AI"]},{"t":"list","vi":"Danh sách; liệt kê. Trên trang AI gặp trong ví dụ prompt injection: dòng chữ lén \"list all file paths\" trong tài liệu ra lệnh agent liệt kê file — chỉ thị độc hại nằm trong dữ liệu.","u":["AI"]},{"t":"path","vi":"Đường dẫn: vị trí file/thư mục trong hệ thống file (ví dụ src/cluster/speed.py). Trên trang AI: scope và permission của agent được khai báo theo path — được đọc/sửa path nào.","u":["AI"]},{"t":"comment","vi":"Chú thích trong code (hoặc lời góp ý). Trên trang AI: comment trong code, ticket, spec là nội dung agent đọc vào context — một nguồn có thể chứa prompt injection.","u":["AI"]},{"t":"line","vi":"Dòng; ranh giới. Trên trang AI gặp trong <b>red lines<\/b> (lằn ranh đỏ): những điều agent tuyệt đối không được làm, ghi rõ trong context/skill.","u":["AI"]},{"t":"role","vi":"Vai trò. Trên trang AI: role prompt — gán vai cho model (\"bạn là kỹ sư review…\"); chỉ hiệu quả khi đi kèm tiêu chí cụ thể, gán danh xưng suông thì vô dụng.","u":["AI"]},{"t":"steps","vi":"Bước. Trên trang AI gặp trong step-back prompting (lùi một bước: hỏi nguyên tắc chung trước rồi áp vào ca cụ thể) và trong suy luận từng bước (step-by-step).","u":["AI"]},{"t":"back","vi":"Lùi lại, quay về. Trên trang AI gặp trong step-back prompting: yêu cầu model lùi một bước, nêu nguyên tắc chung trước rồi mới áp vào ca cụ thể.","u":["AI"]},{"t":"import","vi":"Trong code (Python…), import là câu lệnh nạp một module/thư viện. Trên trang AI: quy tắc kiểu \"file này không được import …\" là thứ nên viết thành validator để máy kiểm thay vì nhắc miệng.","u":["AI"]},{"t":"semantics","vi":"Ngữ nghĩa. Trên trang AI gặp trong tên <b>Semantic Kernel<\/b>: framework xây agent của Microsoft, một lựa chọn bên cạnh LangGraph, CrewAI, AutoGen.","u":["AI"]},{"t":"kernel","vi":"Nhân, lõi. Trên trang AI gặp trong tên <b>Semantic Kernel<\/b>: framework xây AI agent của Microsoft — không phải kernel hệ điều hành.","u":["AI"]},{"t":"auto","vi":"Tự động. Trên trang AI gặp trong ví dụ verify property HVAC: auto mode (điều hòa tự chỉnh) phải nhất quán với fan speed — từng property hợp lệ nhưng tổ hợp có thể vô nghĩa.","u":["AI"]},{"t":"message","vi":"Thông điệp. Trên trang AI: commit message (dòng mô tả một commit Git, phải giải thích được thay đổi) và message trao đổi giữa người, agent, tool.","u":["AI"]},{"t":"unknown","vi":"Chưa biết. Trên trang AI gặp trong <b>unknown unknowns<\/b>: những điều mình không biết là mình không biết — mục tiêu của pattern Exploration là phát hiện chúng.","u":["AI"]},{"t":"QA","vi":"Đảm bảo chất lượng: các hoạt động kiểm thử, review, đo lỗi để sản phẩm đạt chuẩn. Trên trang AI dùng khi đo tác động của AI lên chất lượng (defect escape rate, review effort).","u":["AI"],"full":"Quality Assurance","cs":true},{"t":"direct","vi":"Trực tiếp. Trên trang AI: <b>direct prompt injection<\/b> — người dùng gõ thẳng chỉ thị độc hại vào prompt; khác indirect injection (chỉ thị giấu trong tài liệu, web, code mà agent đọc).","u":["AI"]},{"t":"test harness","vi":"Harness: bộ khung bao quanh. Trên trang AI là <b>harness engineering<\/b>: mọi thứ kỹ thuật xây quanh model — tool, context, kiểm chứng, guardrail, permission — quyết định agent làm được gì và an toàn đến đâu.","u":["AI"]},{"t":"utilization","vi":"Mức sử dụng. Trên trang AI: context window utilisation — tỷ lệ cửa sổ context của model thực sự được dùng; quá đầy làm chậm, đắt và dễ \"lạc\" thông tin.","u":["AI"]},{"t":"user","vi":"Người dùng. Trong Claude Code, <b>user settings<\/b> là cấu hình cấp cá nhân (áp cho mọi dự án của một người), xếp dưới managed policy settings của tổ chức.","u":["AI"]},{"t":"local","vi":"Cục bộ. Trong Claude Code, <b>local settings<\/b> là cấu hình riêng trên máy một người cho một dự án (không commit chung); không ghi đè được managed policy.","u":["AI"]},{"t":"definition","vi":"Định nghĩa. Trên trang AI: <b>tool definitions<\/b> — mô tả tên, tham số, công dụng của các tool cấp cho agent; viết rõ thì agent chọn và gọi tool đúng.","u":["AI"]},{"t":"persistent","vi":"Lưu bền, giữ nguyên qua nhiều lần. Trên trang AI: persistent shell session — shell giữ trạng thái (thư mục, biến môi trường) qua nhiều lời gọi tool của agent; persistent memory là bộ nhớ agent qua các phiên.","u":["AI"]},{"t":"isolation","vi":"Cách ly. Trên trang AI: context isolation (ngữ cảnh việc con không làm nhiễu việc khác, ví dụ dùng subagent) và input isolation (tầng kiểm chỉ đánh giá dữ liệu có cấu trúc, không đọc lời lẽ của agent).","u":["AI"]},{"t":"tier","vi":"Tầng, bậc. Trên trang AI: three-tier verification — kiểm chứng ba tầng: kết quả (sự thật môi trường), quá trình (quy tắc chương trình), phán đoán (model/người); chỉ tầng trên cùng dùng LLM.","u":["AI"]},{"t":"top","vi":"Đứng đầu. Trên trang AI gặp trong <b>OWASP LLM Top 10<\/b>: danh sách 10 rủi ro bảo mật hàng đầu của ứng dụng LLM (mục LLM01 là prompt injection).","u":["AI"]},{"t":"net","vi":"Lưới. Trên trang AI gặp trong <b>regression safety net<\/b>: bộ test tự động như lưới an toàn giúp refactor (kể cả do agent làm) mà không âm thầm làm hỏng hành vi cũ.","u":["AI"]},{"t":"agreement","vi":"Sự đồng thuận. Trên trang AI: inter-rater agreement — mức nhất quán giữa các người chấm (hoặc model judge) độc lập trên cùng mẫu; thấp nghĩa là rubric chưa rõ, điểm eval chưa tin được.","u":["AI"]},{"t":"confidence","vi":"Độ tin cậy. Trên trang AI gặp trong confidence interval (khoảng tin cậy): khoảng giá trị hợp lý cho giá trị thật suy ra từ mẫu đo — dùng khi báo cáo kết quả eval/thí nghiệm.","u":["AI"]},{"t":"effect","vi":"Hiệu ứng, tác động. Trên trang AI gặp trong <b>effect size<\/b>: độ lớn của khác biệt giữa hai phương án, độc lập với cỡ mẫu — cho biết cải thiện có đáng kể không.","u":["AI"]},{"t":"startup","vi":"Công ty khởi nghiệp. Trên trang AI gặp trong tên sách <i>The Lean Startup<\/i> (Ries), nguồn tham khảo về vanity metrics — chỉ số đẹp mà không giúp ra quyết định.","u":["AI"]},{"t":"kill","vi":"Dừng hẳn, loại bỏ. Trên trang AI: kill criteria (stop criteria) — điều kiện kết thúc một thử nghiệm AI, viết sẵn trước khi bắt đầu để không ai cố kéo dài việc đang thất bại.","u":["AI"]},{"t":"BOM","vi":"Bill of Materials – danh sách thành phần. Trong bài xuất hiện trong <b>SBOM<\/b> (Software Bill of Materials): danh sách mọi thư viện, thành phần phần mềm và version trong một build — là evidence của bước build, không phải chi phí linh kiện phần cứng.","u":["B.1"],"full":"Bill of Materials","cs":true},{"t":"Git","vi":"Hệ thống quản lý phiên bản phân tán phổ biến nhất. Trong bài: nơi lưu code/config kèm lịch sử commit — một mắt xích của digital thread; có Git chưa đủ nếu commit không được link tới requirement, test, build và release.","u":["B.1"]},{"t":"metadata","vi":"Siêu dữ liệu: dữ liệu mô tả dữ liệu khác. Trong bài: thông tin pipeline ghi kèm mỗi artifact (commit, version, tool, model đầu vào, kết quả test, người duyệt…) để sau này truy ngược artifact ra từ đâu — nền của digital thread.","u":["B.1"]},{"t":"bus overload","vi":"Quá tải bus: lượng message vượt khả năng truyền, gây trễ hoặc mất frame. Trong bài: ví dụ về giới hạn validity domain — model chỉ correlate ở tải bình thường thì không chứng minh được hành vi khi bus overload; phải correlate thêm hoặc test trên HIL/target.","u":["B.1"]},{"t":"exception","vi":"Ngoại lệ. Trong bài: trường hợp được phép tạm không qua một gate của pipeline; phải đi bằng <b>waiver<\/b> chính thức (lý do, residual risk, mitigation, approver có thẩm quyền, expiry), khác với bypass là vượt gate không theo thủ tục.","u":["B.1"]},{"t":"expiry","vi":"Sự hết hạn. Trong bài: hạn hết hiệu lực của một waiver; quá hạn thì ngoại lệ không còn giá trị, phải xử lý xong hoặc xin duyệt lại. Waiver không có expiry sẽ thành bypass vĩnh viễn.","u":["B.1"]},{"t":"rework","vi":"Làm lại, sửa lại công việc chưa đạt. Trong bài: công sửa lại output do AI tạo (code, test, tài liệu) sau khi review phát hiện sai; phải trừ đi khi tính AI time saved thì mới biết AI có thật sự tiết kiệm thời gian không.","u":["B.1"]},{"t":"silicon","vi":"Nghĩa đen là silic; trong ngành chỉ con chip phần cứng thật (SoC cụ thể, bản revision). Trong bài: timing và memory phụ thuộc silicon là loại kết quả môi trường virtual không đại diện được, nên vẫn phải đo trên target/HIL.","u":["B.1"]},{"t":"mandatory","vi":"Bắt buộc. Trong bài: <b>mandatory gate<\/b> là điểm kiểm trong pipeline không được bỏ qua; chỉ được ngoại lệ qua waiver có approver đúng thẩm quyền, không ai tự bypass (kể cả AI tool).","u":["B.1"]},{"t":"every","vi":"“Mọi, mỗi”. Trong bài (rubric): <i>every stage from need to operation<\/i> — mọi bước của digital thread, từ need tới operation, đều phải có artifact được định danh, có version và có owner.","u":["B.1"]},{"t":"manual","vi":"Thủ công, làm bằng tay. Trong bài: <b>manual link<\/b> là liên kết giữa các artifact/tool được điền tay chứ không do pipeline tự sinh; đây là điểm dễ đứt nhất của digital thread nên phải được chỉ ra, có owner và kế hoạch xử lý.","u":["B.1"]},{"t":"km","vi":"Ki-lô-mét, đơn vị đo quãng đường. Trong bài xuất hiện trong ví dụ đời thường về quality scenario: “dưới 6 lít/100 km khi chạy đường trường 90 km/h” — có số và điều kiện nên so sánh được, khác câu chung chung “xe phải tiết kiệm xăng”.","u":["B.2"],"full":"kilometer","cs":true},{"t":"mechanism","vi":"Cơ chế: cách một phần của hệ thống vận hành để đạt mục tiêu (ví dụ cơ chế isolation, failover, xác thực message). Trong bài: quyết định kiến trúc là lựa chọn có chủ đích về structure, boundary hoặc mechanism của hệ thống, kèm lý do và hệ quả.","u":["B.2"]},{"t":"hardening","vi":"“Gia cố”: tắt tính năng, cổng, service thừa và siết cấu hình để giảm bề mặt tấn công. Trong bài: một vế của trade-off Security ↔ Maintainability — khóa debug port, hardening làm việc chẩn đoán lỗi ngoài field khó hơn.","u":["B.2"]},{"t":"on-board","vi":"Trên xe, bên trong xe. Trong bài xuất hiện trong SecOC (Secure Onboard Communication): xác thực message truyền giữa các ECU bên trong xe để phát hiện message giả, đổi lại tốn thêm payload, CPU và latency.","u":["B.2"]},{"t":"method","vi":"Phương pháp, cách làm có hệ thống. Trong bài xuất hiện trong ATAM (Architecture Tradeoff Analysis Method): phương pháp đánh giá kiến trúc dựa trên quality scenario để tìm sensitivity point, trade-off point và rủi ro.","u":["B.2"]},{"t":"measures","vi":"Đo, phép đo. Trong bài: bước <b>Measure<\/b> của khung quyết định — đo trên target theo cách có thể cho kết quả trượt (bác bỏ được phương án), thay vì dựa vào datasheet, diagram hay cảm nhận.","u":["B.2"]},{"t":"V&V","vi":"Verification (kiểm “làm đúng spec chưa”) và validation (kiểm “làm đúng thứ người dùng cần chưa”). Trong bài, mỗi requirement phải verifiable và được trace tới test/inspection chứng minh nó; trace này là nền cho V&amp;V và audit.","u":["B.3"],"full":"Verification and Validation","cs":true},{"t":"ECU/VM","vi":"ECU hoặc máy ảo (VM) trên CDC. Trong bài thuộc deployment view: task/component được triển khai chạy ở ECU/VM nào, dùng bus, storage và tài nguyên nào.","u":["B.3"],"cs":true},{"t":"exception","vi":"Ngoại lệ, trường hợp bất thường lúc chạy (mất tín hiệu, timeout, dữ liệu lỗi…). Requirement phải mô tả exception/failure behavior (hệ thống làm gì khi lỗi) chứ không chỉ happy path.","u":["B.3"]},{"t":"implement","vi":"Hiện thực, viết code cho một thiết kế/requirement. Trong change control của bài, implement đứng sau impact analysis, approve và update baseline, rồi mới tới verify.","u":["B.3"]},{"t":"derives","vi":"Suy ra (derived): requirement cấp dưới được phân rã/suy ra từ một requirement cấp trên hoặc từ quyết định thiết kế. Ví dụ trong bài: requirement “speed timeout” được phân rã thành các requirement software derived như SW-PAR-03 cho parser.","u":["B.3"]},{"t":"corrupted","vi":"Bị hỏng: dữ liệu sai lệch, sai checksum hoặc không đọc được. Trong bài, frame/dữ liệu corrupt là một kịch bản bắt buộc khi verification trên target, cùng duplicate, missing, clock drift, reboot, power loss.","u":["B.3"]},{"t":"km","vi":"Ki-lô-mét, đơn vị đo quãng đường; km/h là tốc độ. Trong bài xuất hiện ở ví dụ quality scenario “ở 100 km/h, tiếng ồn cabin dưới mức X dB” — điều kiện đo cụ thể làm yêu cầu kiểm được.","u":["B.4"],"full":"kilometer","cs":true},{"t":"BOM","vi":"Danh sách các thành phần tạo nên một sản phẩm. Trong bài xuất hiện qua SBOM (Software Bill of Materials): danh sách mọi thư viện/thành phần và version có trong một software artifact, dùng cho provenance và tra lỗ hổng.","u":["B.4"],"full":"Bill of Materials","cs":true},{"t":"strangler","vi":"Chiến lược migration “bóp nghẹt dần”: đặt facade/routing trước hệ cũ rồi chuyển dần từng chức năng sang hệ mới cho đến khi hệ cũ không còn việc gì và được retire. Rủi ro: facade thành bottleneck, hai implementation lệch behavior.","u":["B.4"]},{"t":"edge-AI","vi":"AI chạy ngay trên thiết bị biên (trên xe) thay vì trên cloud. Trong bài, model edge-AI là <b>product software artifact<\/b>: phải quản version, lineage, input envelope, đánh giá trên target, ký và rollout như phần mềm.","u":["B.4"]},{"t":"portable","vi":"Di động, dễ chuyển sang môi trường khác (portability). Trong bài là một đặc tính chất lượng theo ISO/IEC 25010: phần mềm cài/chạy được trên nền, phần cứng hoặc cloud khác mà ít phải sửa.","u":["B.4"]},{"t":"tick","vi":"Đánh dấu ✓ vào ô. Trong bài: checklist chỉ tick mà thiếu configuration/evidence là chưa đủ để chứng minh chất lượng.","u":["B.4"]},{"t":"tag","vi":"Nhãn gắn vào tài nguyên hoặc artifact (ví dụ tag chi phí theo feature/team, tag version) để lọc, theo dõi và phân bổ. Trong bài: cost cloud phải gắn tag và có budget alert để biết feature nào làm chi phí tăng.","u":["B.4"]},{"t":"export","vi":"Xuất dữ liệu ra khỏi hệ thống/nhà cung cấp. Exit plan phải ghi format dữ liệu, cách export và thời gian chuyển ngay từ đầu để giảm vendor lock-in và exit cost.","u":["B.4"]},{"t":"region","vi":"Vùng: khu vực địa lý đặt trung tâm dữ liệu của nhà cung cấp cloud. Chọn region bị ràng buộc bởi data residency; mất cả một vùng là một kịch bản resilience.","u":["B.4"]},{"t":"fleet issue","vi":"Sự cố đội xe: lỗi xuất hiện lặp lại trên nhiều xe cùng loại. Trong bài được nhắc lại từ B.2 — case chọn phát hiện fleet issue ở edge hay cloud — làm ví dụ cho quyết định cloud/edge placement.","u":["B.4"]},{"t":"inventory","vi":"Kiểm kê, danh mục. Bước đầu của migration: liệt kê application/data/consumer (ai đang dùng), dependency, owner, contract, cost và cách recovery, trước khi chọn chiến lược chuyển.","u":["B.4"]},{"t":"endpoint","vi":"Điểm cuối: địa chỉ (URL/host) mà consumer gọi tới service. Trong migration, “copy thành công” chưa đủ — sau cutover phải kiểm consumer không còn trỏ endpoint cũ.","u":["B.4"]},{"t":"dependency map","vi":"Bản đồ phụ thuộc: ai/hệ nào phụ thuộc vào ai, qua contract/version nào. Trong bài là đầu vào để chia migration thành các wave và xác định entry/exit criteria cho từng wave.","u":["B.4"]},{"t":"expiry","vi":"Ngày hết hạn. Mỗi waiver phải có expiry: sau ngày đó rủi ro phải được xử lý hoặc duyệt lại, không được thành ngoại lệ vĩnh viễn.","u":["B.4"]},{"t":"evaluation","vi":"Đánh giá: kiểm output của AI/model có đúng, đủ tốt không. Với model edge-AI, đánh giá theo variant, target và điều kiện vận hành (false positive/negative, drift, latency/memory).","u":["B.4"]},{"t":"model version","vi":"Phiên bản của model AI/ML (ví dụ model edge-AI chạy trên xe). Ngoài model version còn phải quản lineage (huấn luyện từ dataset nào), input envelope và kết quả đánh giá trên target.","u":["B.4"]},{"t":"deterministic","vi":"Tất định: cùng input luôn cho cùng output, đúng/sai kiểm được bằng chương trình. Trong bài, bước deterministic thuộc nhóm Máy trong tam phân Máy/Agent/Người.","u":["B.4"]},{"t":"agent","vi":"Tác nhân AI: chương trình dùng AI có thể tự lập kế hoạch và gọi công cụ để làm việc. Trong tam phân Máy/Agent/Người, Agent làm phần phán đoán <b>ủy quyền được<\/b> (sai thì phát hiện kịp), trong giới hạn mức L0–L5.","u":["B.4"]},{"t":"recommended","vi":"Đề xuất, khuyến nghị. Trong bài, L2 Recommend là một mức ủy quyền cho AI agent: agent đưa ra đề xuất, còn người quyết định và thực hiện.","u":["B.4"]},{"t":"operate","vi":"Vận hành. Trong bài, L4 Operate workflow là mức ủy quyền cao cho AI agent: được tự vận hành cả một workflow, nhưng phải có hàng rào (guardrail) và audit.","u":["B.4"]},{"t":"CAPA","vi":"Hành động <b>khắc phục<\/b> (sửa lỗi đã xảy ra) và <b>phòng ngừa<\/b> (sửa gate/test/process để lỗi không tái diễn). Trong bài, CAPA chỉ được đóng khi có owner, hạn và bằng chứng effectiveness đo trên cohort thật, không chỉ \"test xanh\".","u":["B.5"],"full":"Corrective and Preventive Action","cs":true},{"t":"actual","vi":"Thực tế, đã xảy ra. Trong bài ở <i>actual impact<\/i>: số xe chứng minh được là đang bị lỗi — tách riêng với potential (có thể bị) và unknown (chưa biết).","u":["B.5"]},{"t":"reason","vi":"Lý do. Trong bài chủ yếu ở <i>reset reason<\/i>: mã lý do ECU/hệ thống tự khởi động lại (ví dụ \"cache parse error\"), gửi về qua telemetry.","u":["B.5"]},{"t":"runbook","vi":"Sổ tay vận hành: các bước cụ thể để xử lý một tình huống (ví dụ reboot loop). Trong bài, runbook sinh ra từ CAPA phải là tài liệu controlled, nếu không mỗi người cầm một bản khác nhau.","u":["B.5"]},{"t":"minor","vi":"Nhỏ. Trong đánh số version tài liệu: tăng số minor (1.0 → 1.1) khi sửa biên tập, tăng major (1.x → 2.0) khi đổi nội dung có impact.","u":["B.5"]},{"t":"purpose","vi":"Mục đích. Trong bài là phần đầu tài liệu controlled: purpose / scope / người dùng tài liệu.","u":["B.5"]},{"t":"reject","vi":"Bác bỏ. Trong bài: test không hỗ trợ giả thuyết → Reject, nhưng vẫn lưu lại kết quả để người sau không thử lại.","u":["B.5"]},{"t":"new","vi":"Mới. Trong bài ở bước \"New baseline/revision\": tạo baseline/revision mới (ví dụ 1.1 hoặc 2.0) sau khi duyệt.","u":["B.5"]},{"t":"MB","vi":"Megabyte — đơn vị dung lượng bộ nhớ (≈ một triệu byte). Trong bài dùng để ước lượng frame buffer: một buffer 1920×1080 RGBA8888 ≈ 8,29 MB, triple buffering ≈ 24,9 MB.","u":["C.2"],"full":"Megabyte","cs":true},{"t":"Deep Dive","vi":"“Lặn sâu”: phần đi sâu chi tiết vào một chủ đề kỹ thuật. Trong bài, Research Topic là một deep-dive kỹ thuật để hỗ trợ một architecture decision, không phải hướng dẫn cấu hình.","u":["C.2"],"aka":["deep-dive"]},{"t":"surface","vi":"Bề mặt vẽ (dịch sát: mặt) của một app/producer — vùng vẽ có buffer queue riêng. App vẽ vào surface; Surface Manager gom surface thành layer, gán lên display/screen và quyết định vị trí, z-order, quyền overlay.","u":["C.2"],"aka":["surfaces"]},{"t":"plane","vi":"Một lớp phần cứng của display controller (DPU): mỗi plane đọc một buffer riêng, DPU tự ghép các plane khi scanout mà không tốn GPU. Số plane có hạn và giới hạn về format/scale; thiếu plane thì layer phải để GPU ghép (fallback).","u":["C.2"],"aka":["planes"]},{"t":"visible","vi":"Nhìn thấy được. Trong bài, Visible là chặng cuối của frame path: panel/TCON đã cập nhật pixel và người lái thật sự thấy frame (visible frame) — khác với lúc GPU báo vẽ xong.","u":["C.2"]},{"t":"double buffer","vi":"Đệm kép (double buffering) trong hiển thị: hai buffer, một đang hiển thị (front), một đang được vẽ (back); đến vblank thì đổi vai bằng page flip, nên panel không đọc frame vẽ dở và không bị tearing.","u":["C.2"],"aka":["double buffering","double buffers"]},{"t":"back","vi":"Phía sau. Trong double buffering, back (back buffer) là buffer app đang vẽ; đến vblank thì đổi vai với front (buffer đang hiển thị).","u":["C.2"]},{"t":"animation","vi":"Hoạt ảnh — chuyển động trên giao diện (kim quay, chuyển màn hình). Animation cần frame pacing đều; animation chạy qua hai màn hình (center → cluster) phải xử lý lệch pha vsync, nếu không sẽ thấy giật.","u":["C.2"],"aka":["animations"]},{"t":"demo","vi":"Buổi trình diễn chạy thử. Bài cảnh báo kiểu tắt vsync để “giảm trễ” trong demo rồi quên bật lại, hoặc dùng FPS để khoe thay cho latency.","u":["C.2"],"aka":["demos"]},{"t":"query","vi":"Truy vấn. Trong bài: GPU timestamp query — yêu cầu GPU ghi lại thời điểm bắt đầu/kết thúc một đoạn việc để biết thời gian GPU thực, dùng cùng CPU trace để tìm stage giới hạn.","u":["C.2"],"aka":["queries"]},{"t":"control plane","vi":"Mặt điều khiển của hệ hiển thị: phần ra quyết định (ai được tạo surface, đổi z-order, đặt overlay, lên display nào). Lỗi control plane là hiện sai chỗ/sai quyền, khác lỗi thời gian của data plane.","u":["C.2"]},{"t":"data plane","vi":"Mặt dữ liệu của hệ hiển thị: phần vận chuyển buffer/fence/pixel qua các chặng render → compose → scanout và thời gian của nó. Lỗi data plane là lỗi thời gian/hiệu năng (trễ, giật, tearing).","u":["C.2"]},{"t":"screen","vi":"Màn hình. Trong bài, screen là đích cuối trong mô hình surface → layer → screen : mỗi layer được gán lên một screen (màn hình vật lý), và Surface Manager quyết định surface lên screen nào.","u":["C.2"],"aka":["screens"]},{"t":"visibility","vi":"Trạng thái hiện/ẩn của một layer. Trong bài, visibility (cùng vị trí, z-order, opacity) do policy HMI quyết định; app không được tự ẩn hay che cảnh báo.","u":["C.2"]},{"t":"share","vi":"Chia sẻ, dùng chung. Trong bài: hai màn hình share surface/plane thì băng thông không đơn giản nhân đôi; GPU/DRAM dùng chung là nguồn tranh chấp giữa các domain.","u":["C.2"],"aka":["shares"]},{"t":"datasheet","vi":"Tài liệu thông số kỹ thuật của chip do nhà cung cấp phát hành. Trong bài: budget DRAM của SoC lấy từ datasheet, dùng có margin chứ không coi là con số chạy được thật — số thật phải đo.","u":["C.2"],"aka":["datasheets","data sheet"]},{"t":"feature/domain","vi":"Feature hoặc domain mới muốn dùng GPU/display. Trong bài phải qua admission control: chứng minh nằm trong budget ở kịch bản đồng thời xấu nhất trước khi được thêm vào.","u":["C.2"]},{"t":"checksum","vi":"Giá trị kiểm tra tính toàn vẹn tính từ dữ liệu; dữ liệu đổi thì checksum đổi. Trong bài, một số SoC tính CRC/checksum trên vùng pixel ở display pipeline để giám sát output, phát hiện nội dung hiển thị sai.","u":["C.2"],"aka":["checksums"]},{"t":"recover","vi":"Phục hồi. Trong bài: sau GPU hang/reset, các domain khác phải recover trong thời hạn quy định, còn nội dung safety đi đường fallback.","u":["C.2"],"aka":["recovered"]},{"t":"finding","vi":"Phát hiện, kết quả tìm hiểu. Trong research brief, Findings là mục ghi những gì đã tìm ra: bottleneck, giới hạn plane/bandwidth, cơ chế sharing và safety.","u":["C.2"],"aka":["findings"]},{"t":"SoC/BSP","vi":"Chip SoC và BSP (board support package – gói driver/kernel/cấu hình của nhà cung cấp cho board cụ thể). Trong bài, tài liệu SoC/BSP là nguồn thông tin chính cho research brief.","u":["C.2"]},{"t":"dB","vi":"Decibel — đơn vị đo mức tín hiệu/âm thanh theo thang logarit. Trong bài dùng cho gain và ducking (ví dụ stream bị duck −12 dB ở framework) và mức âm lượng đo bằng microphone trong xe.","u":["C.3"],"full":"decibel","cs":true},{"t":"focus","vi":"Audio focus — quyền phát âm thanh tại một thời điểm. Nguồn ưu tiên cao hơn (cuộc gọi, navigation prompt) giành focus thì media bị duck/pause, và được restore khi focus được trả lại.","u":["C.3"]},{"t":"zone","vi":"Vùng nghe trong cabin (driver, passenger, rear, headrest, headphone): mỗi zone có route, amp và loa riêng nên có thể phát nguồn khác nhau. Trong bài, amp của một zone còn mute làm loa im dù data path đúng.","u":["C.3"],"aka":["zones"]},{"t":"underrun","vi":"Thiếu dữ liệu: buffer âm thanh cạn vì thread audio không ghi kịp trước khi phần cứng cần đọc, gây tiếng ngắt/lụp bụp. Buffer nhỏ giảm latency nhưng dễ underrun khi scheduler jitter; theo dõi bằng underrun counter.","u":["C.3"],"aka":["underruns"]},{"t":"call","vi":"Cuộc gọi điện thoại (thường qua Bluetooth). Trong bài, call là nguồn âm ưu tiên cao: call bắt đầu thì duck/mute media, call kết thúc thì restore; cần latency thấp và echo cancellation.","u":["C.3"],"aka":["calls"]},{"t":"Bluetooth","vi":"Chuẩn kết nối không dây tầm ngắn. Trong bài, Bluetooth là nguồn âm từ điện thoại: phát nhạc qua A2DP và gọi điện; codec làm latency không cố định và có thể mất kết nối.","u":["C.3"]},{"t":"voice","vi":"Giọng nói. Trong bài: nhóm âm thanh voice (cuộc gọi, voice assistant, TTS) có route và gain riêng; ví dụ tuning file đặt gain kênh voice thấp làm tiếng nghe nhỏ.","u":["C.3"],"aka":["voice assistant"]},{"t":"passenger","vi":"Hành khách. Trong bài, passenger là một zone nghe trong cabin (ghế phụ), có thể phát nguồn âm khác với zone driver.","u":["C.3"],"aka":["passengers"]},{"t":"restore","vi":"Khôi phục. Trong bài: khi interruption kết thúc (call, prompt), hệ thống phải restore trạng thái âm thanh trước đó — unduck media, khôi phục volume/route — kể cả khi hai interruption chồng nhau.","u":["C.3"],"aka":["restored"]},{"t":"resume","vi":"“Tiếp tục”: phát lại từ chỗ đã dừng. Trong bài: mất focus tạm thời (call, prompt) thì media được resume sau đó; mất focus vĩnh viễn (app media khác chiếm) thì pause và không tự resume.","u":["C.3"],"aka":["resumed","resuming"]},{"t":"Direct Memory Access","vi":"Tên đầy đủ của DMA – truy cập bộ nhớ trực tiếp: phần cứng tự chép dữ liệu giữa RAM và thiết bị mà CPU không phải chép từng mẫu. Trong bài, driver audio dùng DMA đẩy ring buffer PCM ra cổng TDM/I2S.","u":["C.3"]},{"t":"processor","vi":"Bộ xử lý. Trong bài gặp trong DSP (Digital Signal Processor) – bộ xử lý chuyên xử lý tín hiệu âm thanh: EQ, mix, lọc ồn, khử vọng.","u":["C.3"],"aka":["processors"]},{"t":"user-space","vi":"Không gian người dùng — vùng chạy chương trình thường, tách khỏi kernel. Trong bài, trên Linux ALSA có phần ở kernel và phần ở user-space; sound server (PipeWire/PulseAudio) và audio policy chạy ở user-space.","u":["C.3"],"aka":["user space","userspace"]},{"t":"peak","vi":"Đỉnh: mức biên độ cao nhất của tín hiệu âm thanh. Trong bài, đo peak/level để phát hiện clipping và kiểm headroom — khác underrun, vốn đo bằng buffer level/timing.","u":["C.3"]},{"t":"cabin","vi":"Khoang cabin, nơi người lái và hành khách ngồi. Trong bài, âm học cabin cùng gain của amp và speaker quyết định âm lượng người nghe thật sự nhận được, nên tuning phải đo bằng microphone trong xe.","u":["C.3"]},{"t":"Wi-Fi","vi":"Mạng không dây cục bộ. Trong bài, Wi-Fi (cùng Bluetooth) là đường truyền âm tới/từ điện thoại, headphone: phải kiểm codec, latency không cố định, mất kết nối và privacy.","u":["C.3"],"aka":["WiFi","wifi"]},{"t":"Bluetooth/Wi-Fi","vi":"Kết nối không dây tới điện thoại, headphone. Trong bài là một loại audio transport: latency không cố định, có thể mất kết nối, cần kiểm codec và privacy.","u":["C.3"]},{"t":"all","vi":"Tất cả. Trong bảng use-case của bài, zone All nghĩa là áp dụng cho mọi zone nghe — ví dụ safety chime phải được mix ra tất cả zone, không bị mute.","u":["C.3"]},{"t":"hop","vi":"Chặng: một bước tín hiệu đi qua giữa hai thành phần. Trong bài, khi kiểm routing thì ghi expected state và số đo theo từng hop trên đường source → HAL → DSP → amp → speaker.","u":["C.3"],"aka":["hops"]},{"t":"repo","vi":"Kho mã nguồn (repository) trong hệ quản lý version như Git. Trong bài: sơ đồ module trong repo chỉ cho thấy cấu trúc code lúc build, không cho biết runtime — process nào khởi động trước, ai chờ ai.","u":["C.4"],"aka":["repos","repository"]},{"t":"placeholder","vi":"Nội dung giữ chỗ hiển thị tạm khi chưa có dữ liệu hợp lệ, ví dụ \"--\" thay cho tốc độ. Trong bài là một lựa chọn khi dependency chưa sẵn sàng, bên cạnh retry và degraded mode.","u":["C.4"],"aka":["placeholders"]},{"t":"message passing","vi":"Truyền thông điệp: process/VM trao đổi bằng cách gửi bản sao message thay vì dùng chung bộ nhớ. Trong bài ví như gửi thư: ranh giới rõ ràng nhưng tốn copy — đối lập với shared memory.","u":["C.4"]},{"t":"reliability","vi":"Độ tin cậy. Trong bài là một QoS policy theo topic của DDS (cùng history, deadline): chọn reliable (bảo đảm tới nơi) hay best-effort (có thể mất) tùy ý nghĩa dữ liệu.","u":["C.4"]},{"t":"offset","vi":"Độ lệch. Trong bài là clock offset: độ lệch giữa đồng hồ của hai domain/VM; phải đo cùng clock hoặc ghi offset/uncertainty thì phép đo end-to-end mới có nghĩa.","u":["C.4"],"aka":["offsets"]},{"t":"accuracy","vi":"Độ chính xác. Trong bài: sync accuracy — sai số khi đồng bộ đồng hồ giữa các domain, phải ghi kèm điều kiện đo khi báo cáo latency xuyên domain.","u":["C.4"]},{"t":"bound","vi":"Biên/cận được chứng minh. Trong bài: hard real-time cần analysis/bound — cận trên của thời gian chạy tính bằng phân tích (như WCET), vì max của 100 lần đo không phải trường hợp xấu nhất.","u":["C.4"]},{"t":"bitrate","vi":"Tốc độ bit của bus (bit/s). Trong bài: bitrate danh nghĩa của CAN không đủ để tính worst-case latency, vì còn arbitration (frame ID ưu tiên cao thắng, frame ưu tiên thấp phải chờ) và bus load.","u":["C.4"],"aka":["bit rate","bitrates"]},{"t":"notify","vi":"Thông báo/đánh thức bên nhận. Trong bài: notify delay là thời gian từ lúc producer báo có dữ liệu mới qua IPC/inter-VM đến lúc consumer được đánh thức để đọc.","u":["C.4"]},{"t":"profile","vi":"Hồ sơ. Trong bài: profile người dùng (cài đặt cá nhân của người lái) là state được nhân bản giữa nhiều domain, nên phải chỉ định single source of truth.","u":["C.4"],"aka":["profiles"]},{"t":"replay","vi":"Phát lại. Trong bài: replay capture — phát lại bản ghi bus/trace đã thu để tái hiện lỗi có kiểm soát, cùng với test hai variant, restart gateway và schema mismatch.","u":["C.4"],"aka":["replays"]},{"t":"DRAM bandwidth","vi":"Băng thông bộ nhớ DRAM (GB/s) của SoC. Trong bài là tài nguyên dùng chung giữa cluster và IVI: GPU/DRAM bị IVI tranh chấp có thể làm giá trị tốc độ hiển thị trễ.","u":["C.4"]},{"t":"build/test/OTA","vi":"Chuỗi build → test → phát hành OTA. Trong bài: mỗi domain phải build/test/OTA được độc lập, có compatibility matrix và feature flag/capability negotiation, không buộc cập nhật đồng loạt.","u":["C.4"]},{"t":"SA Role","vi":"Vai trò kiến trúc sư hệ thống/giải pháp: chịu trách nhiệm quyết định kiến trúc trong phạm vi được giao, phân tích trade-off và đưa recommendation. Với CDC, SA Role thường nối giữa team cluster, IVI, hypervisor và các supplier."},{"t":"Conway's law","aka":["Conway’s law","Conway's Law"],"vi":"Nhận xét của Melvin Conway (1968): hệ thống có xu hướng mang cấu trúc giao tiếp của tổ chức làm ra nó. Trong CDC, ranh giới giữa team cluster, team IVI và các supplier thường hiện ra thành ranh giới module và interface."},{"t":"architecture drift","aka":["architecture erosion","Architecture drift / erosion"],"vi":"Hiện tượng code và hệ thống thực tế dần lệch khỏi kiến trúc đã thiết kế (erosion khi còn vi phạm cả nguyên tắc kiến trúc). Phát hiện bằng kiểm tra dependency tự động và review model so với code."},{"t":"SysML v1","vi":"Phiên bản đầu của Systems Modeling Language, xây dựng như một profile của UML và làm việc chủ yếu qua sơ đồ. Nhiều model hệ thống ô tô hiện có vẫn ở SysML v1."},{"t":"SysML v2","vi":"Thế hệ mới của SysML do OMG phát triển, không còn dựa trên UML, có cú pháp dạng text bên cạnh sơ đồ và API chuẩn để tool truy cập model. Giúp đưa model vào CI và traceability tự động dễ hơn."},{"t":"data steward","aka":["data stewards"],"vi":"Người chịu trách nhiệm chất lượng dữ liệu hằng ngày: ID đúng quy ước, link trace không stale, metadata đầy đủ. Khác owner (quyết định nội dung) và custodian (vận hành nơi lưu trữ)."},{"t":"custodian","aka":["custodians"],"vi":"Bên vận hành hạ tầng lưu trữ dữ liệu hoặc artifact (backup, quyền truy cập, uptime) nhưng không quyết định nội dung. Platform team thường là custodian của gần như mọi thứ, nhưng chỉ là owner của dịch vụ và template."},{"t":"architecturally significant","vi":"Một requirement hay quyết định có ý nghĩa kiến trúc khi nó ảnh hưởng tới cấu trúc, quality attribute hoặc khó đảo ngược. Những quyết định như vậy nên được ghi thành ADR."},{"t":"one-way door","aka":["one-way doors"],"vi":"Quyết định Type 1 theo cách gọi của Jeff Bezos: gần như không quay lại được, nên quyết chậm, kỹ, có người đủ thẩm quyền. Ví dụ trong CDC: chọn SoC hay hypervisor trước HW freeze."},{"t":"two-way door","aka":["two-way doors"],"vi":"Quyết định Type 2: sai thì quay lại được với chi phí thấp, nên quyết nhanh ở nhóm nhỏ. Ví dụ: chọn thư viện log nội bộ có abstraction bao bên ngoài."},{"t":"cost of reversal","vi":"Chi phí, thời gian và rủi ro phải trả nếu muốn đảo ngược một quyết định, thường tăng mạnh sau SOP. Nhân với xác suất phải đổi để ước lượng rủi ro của phương án."},{"t":"EARS","full":"Easy Approach to Requirements Syntax","cs":true,"vi":"Bộ mẫu câu viết requirement (Ubiquitous, Event-driven, State-driven, Unwanted behavior, Optional feature) giúp requirement rõ nghĩa và test được. Mẫu Unwanted đặc biệt hữu ích để viết hành vi khi lỗi."},{"t":"AUTOSAR E2E protection","vi":"Thư viện E2E của AUTOSAR gói CRC, counter, Data ID và kiểm tra timeout thành các profile chuẩn. Receiver nhận về trạng thái kiểm tra (OK, lặp, sai thứ tự, không có dữ liệu…) để quyết định hiển thị hay chuyển degraded."},{"t":"forward compatible","aka":["forward-compatible","forward compatibility"],"vi":"Thuộc tính khi consumer phiên bản cũ vẫn xử lý được dữ liệu do producer phiên bản mới tạo ra, thường nhờ bỏ qua field lạ. Kết hợp với backward compatible để OTA và rollback không làm gãy fleet."},{"t":"error budget","aka":["error budgets"],"vi":"Lượng lỗi hoặc downtime được phép, bằng 100% trừ SLO; ví dụ SLO 99,9% thì budget là 0,1%. Khi budget cạn, ưu tiên ổn định thay vì phát hành tính năng mới."},{"t":"human-on-the-loop","vi":"Mô hình tự động hóa trong đó hệ thống (ví dụ AI agent) tự hành động, con người giám sát và có thể dừng hoặc can thiệp. Khác human-in-the-loop, nơi người phải duyệt từng bước."},{"t":"problem statement","aka":["problem statements"],"vi":"Mô tả vấn đề rõ ràng: cái gì, ở đâu, khi nào, mức độ, kèm ranh giới is / is-not. Là bước đầu của phân tích nguyên nhân gốc, giúp tránh nhảy vào giả thuyết quá sớm."},{"t":"failure mode","aka":["failure modes"],"vi":"Cách thức mà một phần tử hoặc chức năng có thể hỏng, ví dụ treo, trả giá trị sai, chậm. Là đơn vị phân tích trong FMEA và trong phân tích sự cố."},{"t":"escape point","aka":["escape points"],"vi":"Bước trong quy trình (review, test, gate) lẽ ra phải phát hiện lỗi nhưng đã để lọt. Phân tích escape point bổ sung cho phân tích nguyên nhân xảy ra (occurrence)."},{"t":"rule of three","vi":"Quy tắc thống kê: nếu n lần thử độc lập không thấy lỗi nào thì cận trên tỷ lệ lỗi ở độ tin cậy 95% xấp xỉ 3/n. Dùng để ước lượng cần chạy bao nhiêu lần để chứng minh lỗi hiếm đã hết."},{"t":"blameless postmortem","aka":["blameless postmortems"],"vi":"Phân tích sau sự cố tập trung vào hệ thống và quy trình, không quy lỗi cho cá nhân đã hành động thiện chí. Giúp mọi người dám báo cáo đầy đủ sự thật."},{"t":"Display Architecture","vi":"Kiến trúc chuỗi hiển thị trong CDC: app, toolkit, graphics API, driver, GPU, buffer queue, compositor, display controller tới màn hình. Quyết định cluster và IVI chia sẻ hay tách đường hiển thị thế nào."},{"t":"tile-based","aka":["tile-based rendering"],"vi":"Kiểu GPU chia màn hình thành các ô nhỏ và vẽ từng ô trong bộ nhớ on-chip, giảm băng thông DRAM; phổ biến ở GPU di động và SoC xe. Thao tác làm vỡ cơ chế này có thể làm tăng mạnh thời gian frame."},{"t":"UMD","full":"User-Mode Driver","cs":true,"vi":"Phần driver GPU chạy trong không gian người dùng, cài đặt API như OpenGL ES/Vulkan: biên dịch shader và dựng command buffer. Đi cặp với KMD trong kernel."},{"t":"KMD","full":"Kernel-Mode Driver","cs":true,"vi":"Phần driver GPU chạy trong kernel: quản lý bộ nhớ GPU, nhận job submit từ UMD và lập lịch trên phần cứng. Lỗi hoặc hang ở KMD có thể ảnh hưởng mọi client dùng chung GPU."},{"t":"dma-buf","aka":["dma-bufs"],"vi":"Cơ chế của kernel Linux để chia sẻ buffer giữa các thiết bị (GPU, DPU, VPU, camera) qua file descriptor mà không copy pixel. Đi kèm fence để đồng bộ khi nào buffer sẵn sàng."},{"t":"Audio System","vi":"Toàn bộ chuỗi âm thanh trong xe: nguồn (media, navigation, cuộc gọi, chime), framework, DSP, amplifier, loa và mic. Trong CDC phải phối hợp giữa Android Automotive, cluster và ECU/amp riêng."},{"t":"audio zone","aka":["audio zones"],"vi":"Vùng nghe độc lập trong xe, ví dụ ghế lái, ghế phụ, hàng sau hoặc tai nghe, mỗi vùng có nguồn và âm lượng riêng. Android Automotive quản lý audio zone qua CarAudioService."},{"t":"eCall","vi":"Cuộc gọi khẩn cấp tự động (hoặc bấm tay) tới trung tâm cứu hộ khi xe gặp tai nạn, bắt buộc với xe mới tại EU. Âm thanh eCall có ưu tiên cao nhất và không được bị cắt để nhường cho tiện nghi."},{"t":"AVAS","full":"Acoustic Vehicle Alerting System","cs":true,"vi":"Hệ thống phát âm thanh ra ngoài khi xe điện chạy ở tốc độ thấp để cảnh báo người đi bộ, theo UN R138 hoặc FMVSS 141. Thường dùng loa ngoài và amp/ECU riêng."},{"t":"audio context","aka":["audio contexts"],"vi":"Nhóm logic gom nhiều usage âm thanh trong Android Automotive, ví dụ MUSIC, NAVIGATION, CALL, ALARM, SAFETY. Audio focus và định tuyến được quyết định theo context."},{"t":"RNC","full":"Road Noise Cancellation","cs":true,"vi":"Kỹ thuật dùng cảm biến rung và mic để phát âm đối pha, giảm tiếng ồn mặt đường trong cabin. Chạy trên DSP, cần latency rất thấp và ổn định."},{"t":"ICC","aka":["In-Car Communication"],"full":"In-Car Communication","cs":true,"vi":"Chức năng thu giọng người lái qua mic và phát qua loa hàng sau để hành khách nghe rõ. Cần latency thấp và xử lý echo để không gây hú."},{"t":"ASRC","full":"Asynchronous Sample Rate Converter","cs":true,"vi":"Bộ chuyển tần số lấy mẫu giữa hai clock domain không đồng bộ, bù chênh lệch nhỏ giữa hai đồng hồ để tránh drift, glitch. Cần ở mỗi ranh giới clock domain nếu không có time base chung."},{"t":"focus interaction matrix","vi":"Bảng trong Android Automotive quyết định khi một audio context xin focus trong lúc context khác đang giữ: reject, exclusive hay concurrent (kèm duck). Có thể cấu hình theo từng audio zone."},{"t":"AudioControl HAL","aka":["AudioControl"],"vi":"HAL của Android Automotive cho phép CarAudioService gửi thông tin focus, ducking, gain tới DSP/amp của xe và nhận yêu cầu ngược lại. Là ranh giới giữa framework Android và phần âm thanh do OEM/Tier 1 sở hữu."},{"t":"Runtime Architecture","vi":"Góc nhìn kiến trúc về những gì xảy ra khi hệ thống chạy: process, partition, giao tiếp, lifecycle, scheduling, health và isolation. Trong CDC trải qua hypervisor, AUTOSAR Adaptive/Classic và Android Automotive."},{"t":"signal-to-service gateway","aka":["Signal-to-service gateway","signal-to-service gateways"],"vi":"Thành phần chuyển signal trên CAN/LIN (từ zone/ECU cũ) thành service hoặc event trên SOME/IP, DDS cho phía central compute. Giúp app không phụ thuộc trực tiếp vào bố cục signal."},{"t":"PHM","aka":["Platform Health Management"],"full":"Platform Health Management","cs":true,"vi":"Functional cluster của AUTOSAR Adaptive giám sát process qua alive, deadline và logical supervision, báo vi phạm cho State Management để chọn restart hay degraded. Tương ứng WdgM ở AUTOSAR Classic."},{"t":"anti-corruption layer","aka":["Anti-corruption layer","anti-corruption layers"],"vi":"Mẫu từ Domain-Driven Design: lớp adapter dịch mô hình và interface của hệ thống khác sang mô hình của mình, để thay đổi bên kia không lan vào code. Hữu ích khi tích hợp legacy signal hoặc API của supplier."},{"t":"Automotive Software Lifecycle","vi":"Toàn bộ vòng đời phần mềm trên xe: từ concept, phát triển, tích hợp, phát hành, sản xuất tới vận hành, OTA và end-of-support. Kéo dài 10–15 năm, lâu hơn nhiều so với phần mềm di động."},{"t":"UNECE R155/R156","vi":"Hai quy định của UNECE WP.29: R155 yêu cầu hệ thống quản lý cybersecurity (CSMS), R156 yêu cầu hệ thống quản lý software update (SUMS). Áp dụng cho type approval ở các thị trường tham gia."},{"t":"VDA scope","vi":"Tập process ASPICE mà hiệp hội ô tô Đức VDA khuyến nghị đưa vào assessment, gồm các nhóm SYS, SWE và SUP chính. OEM thường yêu cầu supplier đạt mức capability trên phạm vi này."},{"t":"ISO 24089","vi":"Chuẩn ISO về software update engineering cho phương tiện: tổ chức, dự án và quy trình cập nhật phần mềm, kể cả OTA. Thường dùng làm cơ sở để đáp ứng UN R156."},{"t":"CCB","full":"Change Control Board","cs":true,"vi":"Nhóm có thẩm quyền xem xét và duyệt change request dựa trên impact về safety, security, chi phí và lịch. Với CDC thường có đại diện cluster, IVI, safety, security và supplier."},{"t":"safety case","aka":["safety cases"],"vi":"Lập luận có cấu trúc, kèm evidence, chứng minh item hoặc hệ thống đạt mức an toàn yêu cầu theo ISO 26262. Thay đổi phần mềm sau release phải đánh giá ảnh hưởng tới safety case."},{"t":"hardware root of trust","vi":"Khóa và logic gốc nằm trong phần cứng (ROM, fuse, HSM) mà phần mềm không sửa được, là điểm bắt đầu cho secure boot và chuỗi tin cậy. Mọi kiểm tra chữ ký sau đó đều dựa vào nó."},{"t":"VSOC","full":"Vehicle Security Operations Center","cs":true,"vi":"Trung tâm giám sát an ninh cho đội xe: thu log và cảnh báo bảo mật từ xe và backend, phát hiện tấn công và điều phối phản ứng. Hỗ trợ yêu cầu giám sát sau sản xuất của UN R155."},{"t":"SCA","full":"Software Composition Analysis","cs":true,"vi":"Kỹ thuật và tool quét thành phần open source và bên thứ ba trong phần mềm để phát hiện CVE và vấn đề license. Thường chạy trong CI cùng việc sinh SBOM."},{"t":"CAL","full":"Cybersecurity Assurance Level","cs":true,"vi":"Mức đảm bảo cybersecurity CAL1–CAL4 theo ISO/SAE 21434, quyết định độ chặt của hoạt động phát triển và kiểm chứng cho một thành phần. Thường gán theo impact và đường tấn công."},{"t":"Modern Vehicle Architecture","vi":"Kiến trúc điện/điện tử xe thế hệ mới: chuyển từ nhiều ECU phân tán sang domain/zonal và central compute, giao tiếp hướng dịch vụ và cập nhật OTA. CDC là một phần của kiến trúc này."},{"t":"DoIP","full":"Diagnostics over Internet Protocol","cs":true,"vi":"Giao thức chạy chẩn đoán UDS qua Ethernet/IP theo ISO 13400, nhanh hơn chẩn đoán qua CAN khi flash hoặc đọc dữ liệu lớn. CDC thường có diagnostic entity hỗ trợ DoIP."},{"t":"ABI","full":"Application Binary Interface","cs":true,"vi":"Giao kèo ở mức binary giữa các module: layout struct, calling convention, tên symbol. Đổi thư viện mà giữ API nhưng vỡ ABI vẫn làm binary cũ hỏng."},{"t":"Mixed Criticality System","aka":["Mixed Criticality Systems","mixed-criticality system","mixed-criticality systems"],"vi":"Hệ thống chạy chung trên một phần cứng các chức năng có mức quan trọng khác nhau, ví dụ cluster ASIL và IVI QM trên cùng SoC. Yêu cầu chứng minh freedom from interference giữa chúng."},{"t":"consolidation","vi":"Xu hướng gộp chức năng của nhiều ECU vào ít máy tính mạnh hơn, ví dụ cluster và IVI vào một CDC. Giảm chi phí, dây và cho phép OTA tập trung, nhưng đòi hỏi isolation tốt."},{"t":"coexistence of elements","vi":"Tiêu chí trong ISO 26262-9 cho phép phần tử có ASIL khác nhau (hoặc QM) cùng nằm trong một hệ thống nếu chứng minh được freedom from interference. Là cơ sở để cluster và IVI cùng chạy trên CDC."},{"t":"lock-holder preemption","vi":"Hiện tượng hypervisor preempt vCPU đang giữ spinlock, làm các vCPU khác phải quay chờ vô ích. Có thể gây latency bất thường cho VM, kể cả VM chứa cluster."},{"t":"stage-2 translation","vi":"Tầng dịch địa chỉ thứ hai trên Arm: địa chỉ vật lý của guest được hypervisor dịch sang địa chỉ vật lý thật. Guest không sửa được bảng này, nhờ đó VM không truy cập được bộ nhớ của VM khác."},{"t":"LLC","full":"Last-Level Cache","cs":true,"vi":"Cache cấp cuối dùng chung giữa nhiều lõi CPU (và đôi khi GPU). Workload IVI nặng có thể đẩy dữ liệu cluster ra khỏi LLC, tạo can nhiễu thời gian; giảm bằng cache coloring hoặc MPAM."},{"t":"MPAM","full":"Memory System Resource Partitioning and Monitoring","cs":true,"vi":"Tính năng của kiến trúc Arm cho phép chia và giám sát tài nguyên bộ nhớ dùng chung như cache và băng thông theo partition. Giúp giảm can nhiễu giữa VM cluster và VM IVI."},{"t":"HARA","full":"Hazard Analysis and Risk Assessment","cs":true,"vi":"Bước trong ISO 26262-3 phân tích mối nguy của item và đánh giá rủi ro theo severity, exposure, controllability để gán ASIL và safety goal. Mức ASIL của telltale hay camera lùi lấy từ HARA."},{"t":"WCRT","aka":["worst-case response time"],"full":"Worst-Case Response Time","cs":true,"vi":"Thời gian xấu nhất từ lúc tác vụ sẵn sàng tới lúc xong, gồm cả thời gian chờ và bị preempt. Trong CDC, đo WCRT của task cluster khi IVI chạy tải nặng để chứng minh deadline."},{"t":"FTTI","full":"Fault Tolerant Time Interval","cs":true,"vi":"Khoảng thời gian từ lúc lỗi xảy ra tới khi có thể gây mối nguy nếu không có safety mechanism phản ứng (ISO 26262). Phát hiện lỗi và chuyển sang safe state phải xong trong FTTI."},{"t":"safety island","aka":["safety islands"],"vi":"Vùng trong SoC gồm lõi lockstep, bộ nhớ và ngoại vi riêng, đạt ASIL cao và độc lập với phần ứng dụng hiệu năng cao. Thường chạy RTOS giám sát hệ thống hoặc giữ đường hiển thị telltale."},{"t":"ASIL decomposition","vi":"Kỹ thuật ISO 26262-9 chia một safety requirement thành hai requirement dư thừa trên hai phần tử đủ độc lập, mỗi phần có ASIL thấp hơn, ví dụ ASIL B(D) + ASIL B(D). Phải chứng minh độc lập bằng phân tích dependent failure."},{"t":"SEooC","full":"Safety Element out of Context","cs":true,"vi":"Phần tử safety (ví dụ hypervisor, RTOS) được phát triển theo ISO 26262 dựa trên giả định, khi chưa biết hệ thống đích. Dự án dùng nó phải kiểm từng assumption of use."},{"t":"FinOps","vi":"Thực hành quản lý chi phí cloud: gắn chi phí với feature, team và mỗi xe, theo dõi và tối ưu liên tục. Với xe kết nối, chi phí tăng theo số xe × số năm × lượng dữ liệu."},{"t":"CAN","full":"Controller Area Network","cs":true,"vi":"Bus truyền thông nối tiếp phổ biến nhất trên xe, nối các ECU và truyền signal như tốc độ, trạng thái cửa. CDC thường nhận signal CAN qua MCU hoặc gateway thay vì để IVI đọc trực tiếp."},{"t":"eMMC","aka":["eMMCs"],"full":"embedded MultiMediaCard","vi":"Bộ nhớ flash NAND kèm controller, hàn trên bo mạch, dùng làm storage cho nhiều ECU và CDC. Tốc độ đọc eMMC lúc boot ảnh hưởng trực tiếp thời gian hiện cluster và camera lùi."},{"t":"P95","full":"95th percentile","cs":true,"vi":"Phân vị 95: 95% mẫu đo nằm dưới giá trị này. Dùng thay giá trị trung bình khi đặt và kiểm latency, ví dụ P95 thời gian từ nhận tín hiệu đến hiển thị."},{"t":"P50","full":"50th percentile","cs":true,"vi":"Phân vị 50, tức trung vị: một nửa mẫu đo nằm dưới giá trị này. Chỉ mô tả trường hợp điển hình, phải đi cùng P95/P99 và max khi đánh giá latency."},{"t":"RXSWIN","full":"RX Software Identification Number","cs":true,"vi":"Mã định danh phần mềm gắn với type approval theo UN R156; khi cập nhật phần mềm liên quan tới quy định, RXSWIN phải được quản lý và cập nhật tương ứng. OEM cần biết mỗi release ảnh hưởng RXSWIN nào."},{"t":"piece price","vi":"Giá OEM trả Tier 1 cho mỗi đơn vị phần cứng giao, ví dụ mỗi CDC. Thường đi cùng NRE và đôi khi license phần mềm hoặc royalty."},{"t":"SM","full":"State Management","cs":true,"vi":"Functional cluster của AUTOSAR Adaptive quyết định trạng thái máy và function group (ví dụ Parking, Driving, OTA). Nhận vi phạm từ PHM và chọn restart cục bộ hay chuyển degraded."},{"t":"EM","full":"Execution Management","cs":true,"vi":"Functional cluster của AUTOSAR Adaptive khởi động, dừng và giám sát process theo manifest và trạng thái do SM yêu cầu. Thực hiện startup ordering và graceful shutdown."},{"t":"suspect","aka":["suspect link","suspect links"],"vi":"Trạng thái tool ALM gắn cho link trace khi requirement, test hay thiết kế ở một đầu thay đổi. Link suspect phải được người chịu trách nhiệm review và xác nhận lại."},{"t":"qualification","aka":["qualify"],"vi":"Hoạt động chứng minh một tool hay hệ thống đáp ứng yêu cầu: tool qualification theo ISO 26262-8 khi tool tạo evidence safety, hoặc system qualification test trong ASPICE. Cần tính chi phí khi đổi version tool."},{"t":"default","aka":["default value","default values"],"vi":"Giá trị được định nghĩa sẵn dùng khi field không có trong dữ liệu hoặc không có bản lưu hợp lệ. Field optional mới phải có default để consumer cũ và mới hoạt động đúng."},{"t":"AEC","full":"Acoustic Echo Cancellation","cs":true,"vi":"Xử lý trên DSP loại tiếng từ loa bị mic thu lại, cần cho cuộc gọi rảnh tay, voice assistant và ICC. Thường đi cùng NR (giảm ồn)."},{"t":"NR","full":"Noise Reduction","cs":true,"vi":"Xử lý trên DSP giảm tiếng ồn nền (động cơ, gió, mặt đường) trong tín hiệu mic để thoại và nhận giọng nói rõ hơn. Thường ghi cùng AEC thành AEC/NR."},{"t":"instance","aka":["instances"],"vi":"Một thể hiện cụ thể của service hay component khi chạy; một service interface có thể có nhiều instance, phân biệt bằng instance ID. Trong SOME/IP, địa chỉ, port và instance có thể cố định trong manifest."},{"t":"TTL","full":"Time To Live","cs":true,"vi":"Thời hạn hiệu lực của dữ liệu hoặc bản tin; trong SOME/IP-SD, offer service hết TTL mà không được làm mới thì consumer coi service đã mất. Chọn TTL là trade-off giữa phát hiện nhanh và tải mạng."},{"t":"purchasing","vi":"Bộ phận mua hàng của OEM, chịu trách nhiệm chọn supplier, đàm phán giá, license và hợp đồng. Quan tâm chi phí mỗi xe, ví dụ license hypervisor hay giá SoC."},{"t":"RFQ","full":"Request for Quotation","cs":true,"vi":"Yêu cầu báo giá OEM gửi các supplier, kèm specification, sản lượng và lịch. Kết quả RFQ dẫn tới nomination supplier."},{"t":"EOP","full":"End of Production","cs":true,"vi":"Mốc ngừng sản xuất một mẫu xe hoặc linh kiện. Sau EOP vẫn có nghĩa vụ hỗ trợ phần mềm, bản vá và phụ tùng trong nhiều năm."},{"t":"IATF 16949","aka":["IATF"],"vi":"Chuẩn hệ thống quản lý chất lượng cho sản xuất ô tô và phụ tùng, xây trên ISO 9001, do International Automotive Task Force ban hành. Yêu cầu kiểm soát tài liệu, thay đổi và đi kèm APQP/PPAP."},{"t":"toolkit","aka":["UI toolkit","toolkits"],"vi":"Bộ thư viện dựng UI (ví dụ Android View, Qt Quick, Kanzi) mô tả cảnh cần vẽ, rồi gọi graphics API như OpenGL ES/Vulkan. Là chặng đầu trong chuỗi app → toolkit → API → driver → GPU."},{"t":"EGL","cs":true,"vi":"API của Khronos nối OpenGL ES với hệ thống cửa sổ và buffer của nền tảng: tạo context, surface và swap buffer. Trên Android, QNX Screen hay Wayland đều có cài đặt EGL."},{"t":"BufferQueue","cs":true,"vi":"Cơ chế Android chuyển buffer đồ họa giữa producer (app, camera) và consumer (SurfaceFlinger, encoder) theo dequeue/queue/acquire/release. Độ sâu hàng đợi ảnh hưởng độ mượt và latency."},{"t":"FMVSS","full":"Federal Motor Vehicle Safety Standards","cs":true,"vi":"Bộ tiêu chuẩn an toàn xe bắt buộc tại Mỹ do NHTSA ban hành. Ví dụ FMVSS 111 yêu cầu hình camera lùi trong 2,0 s sau khi vào số lùi; FMVSS 141 về âm cảnh báo của xe điện."},{"t":"shaper","aka":["credit-based shaper","TSN shaper","shapers"],"vi":"Cơ chế điều tiết thời điểm gửi gói để giữ băng thông và latency, ví dụ credit-based shaper của AVB/TSN. Giúp luồng audio, video không bị luồng khác chen mất."},{"t":"TCU","full":"Telematics Control Unit","cs":true,"vi":"ECU quản lý kết nối cellular, GNSS và đôi khi Wi-Fi/V2X, là cầu nối giữa xe và backend. Là entry point từ xa quan trọng nên cần phân vùng mạng kỹ."},{"t":"persistency","vi":"Khả năng và dịch vụ lưu dữ liệu bền vững qua reboot và mất điện; AUTOSAR Adaptive có functional cluster Persistency. Cần ghi atomic và có bản sao để không hỏng khi mất điện giữa chừng."},{"t":"GKI","full":"Generic Kernel Image","cs":true,"vi":"Mô hình kernel của Android: một kernel image chung do Google duy trì, driver của vendor build thành module nạp qua KMI ổn định. Giúp cập nhật kernel bảo mật dễ hơn."},{"t":"KMI","full":"Kernel Module Interface","cs":true,"vi":"Tập symbol và interface kernel GKI cam kết giữ ổn định để module driver của vendor không phải build lại mỗi lần cập nhật kernel. Thuộc mô hình GKI của Android."},{"t":"TCL","full":"Tool Confidence Level","cs":true,"vi":"Mức TCL1–TCL3 phân loại tool theo khả năng gây hoặc bỏ sót lỗi trong sản phẩm safety, quyết định tool có cần qualification hay không. Đổi version compiler có thể buộc đánh giá lại."},{"t":"HW freeze","aka":["hardware freeze"],"vi":"Mốc sau đó thiết kế phần cứng (SoC, bộ nhớ, bo mạch) không được đổi nữa nếu không chịu chi phí lớn. Quyết định cần thay đổi phần cứng phải xong trước HW freeze."},{"t":"FW","full":"Firmware","cs":true,"vi":"Phần mềm nhúng chạy trực tiếp trên ECU, MCU hoặc thiết bị ngoại vi. Phiên bản FW của zone ECU phải nằm trong compatibility matrix với CDC và backend."},{"t":"Unwanted","aka":["Unwanted behavior","Unwanted behaviour"],"vi":"Mẫu câu EARS cho hành vi khi lỗi: If <điều kiện không mong muốn>, then the <system> shall <phản ứng>. Thường bị quên nhất, nên requirement chỉ có happy path."},{"t":"NVM","full":"Non-Volatile Memory","cs":true,"vi":"Bộ nhớ giữ dữ liệu khi mất điện như flash, EEPROM, eMMC. Ghi NVM cần atomic, có bản sao dự phòng và tính đến số lần ghi (wear)."},{"t":"shall","vi":"Từ khóa trong requirement thể hiện nghĩa vụ bắt buộc và kiểm chứng được, ví dụ “cluster shall hiển thị mph”. Khác should (khuyến nghị) và may (tùy chọn)."},{"t":"interaction capability","vi":"Đặc tính chất lượng trong ISO/IEC 25010:2023 (trước gọi là usability): mức người dùng học, thao tác và tránh lỗi khi dùng sản phẩm. Với CDC gồm thao tác được khi đang lái và đọc HMI dễ."},{"t":"monolith","aka":["monoliths"],"vi":"Ứng dụng mà mọi chức năng build và triển khai thành một khối. Có thể tách dần thành service theo mẫu strangler mà không dừng hệ thống."},{"t":"retain","vi":"Trong risk treatment: chấp nhận rủi ro có phê duyệt của người có thẩm quyền. Trong chiến lược cloud “R”: giữ nguyên hệ thống chưa di chuyển."},{"t":"reduce","vi":"Lựa chọn risk treatment theo ISO/SAE 21434: thêm control kỹ thuật hoặc quy trình để giảm khả năng hoặc mức tác động của rủi ro. Các lựa chọn khác là avoid, share, retain."},{"t":"risk treatment","aka":["treatment"],"vi":"Bước quyết định cách xử lý mỗi rủi ro sau đánh giá: tránh, giảm, chia sẻ hoặc chấp nhận. Mỗi quyết định cần owner, cybersecurity goal hoặc claim tương ứng."},{"t":"royalty","aka":["royalties"],"vi":"Phí bản quyền tính theo mỗi xe hoặc mỗi thiết bị, ví dụ Tier 1 trả royalty hypervisor cho vendor. Cộng dồn qua sản lượng nên ảnh hưởng lớn tới chi phí mỗi xe."},{"t":"flagship","vi":"Dòng sản phẩm mạnh và đắt nhất của một hãng, ví dụ SoC flagship. Chỉ đáng chọn khi roadmap tính năng thật sự cần đến hiệu năng đó."},{"t":"marker","aka":["markers","boot timing marker","sync marker"],"vi":"Điểm đánh dấu ghi vào log hoặc trace để đo thời gian hoặc căn chỉnh nhiều nguồn log, ví dụ boot timing marker hay sync marker ghi đồng thời vào các log."},{"t":"occurrence","vi":"Nhánh phân tích nguyên nhân giải thích vì sao lỗi xảy ra, đi song song với nhánh escape (vì sao không bị phát hiện). Mỗi bước trong chuỗi nhân quả phải có evidence."},{"t":"interconnect","aka":["interconnects"],"vi":"Mạng bus nội bộ SoC nối CPU, GPU, DPU, các khối khác với bộ điều khiển DRAM. Interconnect thường có QoS ưu tiên luồng đọc của DPU để màn hình không bị sọc, nháy."},{"t":"HWUI","cs":true,"vi":"Thư viện render UI của Android, dùng Skia trên OpenGL ES/Vulkan để vẽ View với GPU. Là chặng giữa toolkit và graphics API trong pipeline hiển thị Android."},{"t":"shader compile","aka":["shader compilation"],"vi":"Bước biên dịch shader thành mã chạy trên GPU; nếu diễn ra lúc chạy sẽ gây giật ở lần đầu hiển thị. Giảm bằng biên dịch trước hoặc cache shader."},{"t":"connector","aka":["connectors"],"vi":"Trong DRM/KMS, connector là object đại diện đầu ra vật lý tới màn hình, cuối chuỗi plane → CRTC → encoder → connector. Trên bench, connector còn là đầu nối dây có thể rút để giả lập lỗi."},{"t":"FIFO","full":"First In, First Out","cs":true,"vi":"Hàng đợi vào trước ra trước. Là present mode của Vulkan: frame được xếp hàng và chỉ lật ở vblank, không tearing nhưng có thể thêm latency."},{"t":"frontend","aka":["frontend driver","frontends"],"vi":"Trong ảo hóa kiểu VirtIO, driver frontend chạy trong guest và gửi command tới backend ở host hoặc service VM, nơi truy cập thiết bị thật như GPU."},{"t":"profiler","aka":["Profiler","profilers"],"vi":"Công cụ đo thời gian và tài nguyên của chương trình hoặc GPU, ví dụ QNX System Profiler, Snapdragon Profiler, Android GPU Inspector. Chỉ ra chỗ cần sửa, còn tổng latency phải đo ngoài."},{"t":"photodiode","aka":["photodiodes"],"vi":"Cảm biến quang dán lên màn hình để ghi chính xác thời điểm điểm ảnh đổi độ sáng. Cùng camera tốc độ cao, là cách đo latency end-to-end từ nguồn tới màn hình."},{"t":"latch","vi":"Thời điểm compositor (như SurfaceFlinger) lấy buffer mới nhất của mỗi layer để ghép vào frame kế tiếp. Buffer tới sau latch phải chờ thêm một chu kỳ vsync."},{"t":"xrun","aka":["xruns","glitch/xrun"],"vi":"Sự cố buffer audio bị underrun (cạn) hoặc overrun (tràn) khi bên ghi/đọc không kịp, nghe thành tiếng giật hoặc lụp bụp. Số xrun mỗi giờ ở tải xấu nhất là một metric chất lượng audio."},{"t":"glitch","aka":["glitches"],"vi":"Lỗi âm thanh ngắn như giật, click, mất vài mẫu, thường do xrun, đổi clock hoặc chuyển trạng thái không mượt."},{"t":"binding","aka":["bindings"],"vi":"Lớp ánh xạ API giao tiếp chung (như ara::com) xuống giao thức cụ thể như SOME/IP, DDS hay IPC nội bộ, chọn lúc deployment. Nhờ đó cùng mã ứng dụng chạy được trên nhiều transport."},{"t":"StopOfferService","cs":true,"vi":"Thông báo service không còn được cung cấp (SOME/IP-SD stop offer, hay hàm ara::com tương ứng). Gửi khi shutdown có kiểm soát để consumer chuyển trạng thái ngay thay vì chờ hết TTL."},{"t":"VAL.1","cs":true,"vi":"Process Validation trong Automotive SPICE 4.0, tách validation khỏi các process verification. Kiểm sản phẩm có đáp ứng nhu cầu sử dụng thực tế hay không."},{"t":"SELinux","full":"Security-Enhanced Linux","vi":"Cơ chế kiểm soát truy cập bắt buộc của kernel Linux, giới hạn mỗi process chỉ truy cập tài nguyên được policy cho phép. Android dùng SELinux để thực thi least privilege cho app và service."},{"t":"IDL","full":"Interface Definition Language","cs":true,"vi":"Ngôn ngữ mô tả interface độc lập ngôn ngữ lập trình, ví dụ Franca IDL, OMG IDL cho DDS, AIDL. Chỉ mô tả kiểu dữ liệu và method; freshness, owner, timing phải ghi ở contract."},{"t":"RVC","full":"Rear View Camera","cs":true,"vi":"Camera lùi hiển thị phía sau xe khi vào số lùi. Thời gian hiện frame RVC hợp lệ đầu tiên sau boot là mốc quan trọng, có thể bị ràng buộc pháp lý như FMVSS 111."},{"t":"variation point","aka":["variation points"],"vi":"Điểm trong kiến trúc hoặc code nơi các variant khác nhau (màn hình, thị trường, SoC) được chọn qua cấu hình. Quản lý variation point có chủ đích giúp giữ một codebase thay vì fork."},{"t":"federated","aka":["federated data"],"vi":"Mô hình dữ liệu phân tán: mỗi loại artifact có đúng một nguồn có thẩm quyền, liên kết với nhau qua ID và version. Hợp với CDC nhiều supplier, mỗi bên giữ tool riêng."},{"t":"regression suite","aka":["regression suites"],"vi":"Bộ test chạy lại sau mỗi thay đổi để bảo đảm chức năng cũ không hỏng. Mỗi lỗi field đã phân tích nên để lại một scenario mới trong regression suite."},{"t":"dual publish","vi":"Producer phát đồng thời field hoặc version cũ và mới trong deprecation window để consumer chuyển dần. Chỉ ngừng bản cũ khi điều kiện đo được đã đạt."},{"t":"installability","vi":"Đặc tính con của flexibility trong ISO/IEC 25010: mức sản phẩm được cài đặt và gỡ bỏ hiệu quả trong môi trường đích. Với CDC, gồm khả năng cài qua OTA."},{"t":"MISRA","full":"Motor Industry Software Reliability Association","cs":true,"vi":"Bộ coding guideline MISRA C/C++ hạn chế các cấu trúc ngôn ngữ dễ gây lỗi, dùng rộng rãi cho code safety như cluster. Thường kiểm bằng static analysis."},{"t":"graceful degradation","vi":"Khi một phụ thuộc hỏng, hệ thống giảm chức năng có kiểm soát thay vì sập toàn bộ, ví dụ navigation vẫn dùng bản đồ offline, chỉ ẩn live traffic. Hành vi degraded nên được viết thành requirement."},{"t":"graceful shutdown","vi":"Dừng hệ thống có thứ tự: báo consumer, flush log, ghi persistency, dừng ngược thứ tự dependency, có timeout cứng. Tránh mất dữ liệu khi tắt xe."},{"t":"PPAP","full":"Production Part Approval Process","cs":true,"vi":"Quy trình supplier nộp hồ sơ chứng minh linh kiện sản xuất đạt yêu cầu trước khi giao hàng loạt. Software version trong PPAP phải khớp baseline release."},{"t":"APQP","full":"Advanced Product Quality Planning","cs":true,"vi":"Khung lập kế hoạch chất lượng theo giai đoạn cho phát triển sản phẩm ô tô, kết thúc bằng PPAP. Gate phần mềm nên khớp mốc APQP để tránh hai lịch song song."},{"t":"nomination","vi":"Quyết định OEM chọn supplier sau RFQ, khóa quan hệ cho chương trình xe. Trước nomination là lúc OEM có đòn bẩy lớn nhất để đưa yêu cầu vào hợp đồng."},{"t":"is / is-not","aka":["is-not"],"vi":"Kỹ thuật mô tả vấn đề bằng hai cột: lỗi xảy ra ở đâu, khi nào (is) và ở đâu lẽ ra có thể nhưng không xảy ra (is-not). Mỗi khác biệt giữa hai cột là manh mối để đặt giả thuyết."},{"t":"logcat","vi":"Hệ thống log của Android và lệnh để đọc nó. Trong CDC cần gom logcat cùng log QNX, hypervisor và DLT từ MCU về một timeline chung."},{"t":"D6","cs":true,"vi":"Bước 6 của phương pháp 8D: triển khai hành động khắc phục lâu dài và xác nhận bằng evidence là hiệu quả. Ticket chỉ đóng khi D6 và D7 có evidence."},{"t":"D7","cs":true,"vi":"Bước 7 của phương pháp 8D: ngăn lỗi tái diễn bằng cách sửa quy trình, requirement, test, checklist gate để lỗi tương tự không xảy ra hoặc không lọt nữa."},{"t":"SUP.8","cs":true,"vi":"Process quản lý cấu hình trong Automotive SPICE: định danh, baseline, kiểm soát và truy vết các configuration item."},{"t":"SUP.9","cs":true,"vi":"Process quản lý giải quyết vấn đề trong Automotive SPICE: ghi nhận, phân tích nguyên nhân và impact, theo dõi tới khi đóng, phân tích xu hướng."},{"t":"SUP.10","cs":true,"vi":"Process quản lý change request trong Automotive SPICE: ghi nhận, phân tích impact, duyệt, theo dõi thực hiện và kiểm chứng thay đổi."},{"t":"SYS.1","cs":true,"vi":"Process thu thập và quản lý yêu cầu của stakeholder trong Automotive SPICE, là đầu vào cho system requirements."},{"t":"SYS.2","cs":true,"vi":"Process phân tích và viết system requirement trong Automotive SPICE, kiểm chứng bằng SYS.5 ở nhánh phải chữ V."},{"t":"SYS.3","cs":true,"vi":"Process thiết kế kiến trúc hệ thống trong Automotive SPICE: phân rã thành element, interface và phân bổ requirement; tương ứng SYS.4 tích hợp."},{"t":"SYS.5","cs":true,"vi":"Process kiểm thử hệ thống tích hợp so với system requirement (System Qualification Test; ASPICE 4.0 gọi là System Verification). Đạt SYS.5 chưa chứng minh sản phẩm đúng nhu cầu sử dụng."},{"t":"SWE.1","cs":true,"vi":"Process phân tích và viết software requirement từ system requirement trong Automotive SPICE, kiểm chứng tương ứng ở SWE.6."},{"t":"SWE.2","cs":true,"vi":"Process thiết kế kiến trúc phần mềm trong Automotive SPICE: component, interface, hành vi động và budget tài nguyên; tương ứng SWE.5 tích hợp."},{"t":"Mali","cs":true,"vi":"Dòng GPU của Arm có trong nhiều SoC, kể cả SoC xe, dùng kiến trúc tile-based. Hỗ trợ format nén AFBC để giảm băng thông bộ nhớ."},{"t":"Skia","cs":true,"vi":"Thư viện đồ họa 2D mã nguồn mở của Google, được HWUI của Android dùng để vẽ trên OpenGL ES hoặc Vulkan."},{"t":"gralloc","vi":"HAL cấp phát bộ nhớ đồ họa của Android, trả về handle buffer chia sẻ được giữa GPU, camera, display. Thứ được chuyển giữa các chặng là handle kèm fence, không phải pixel."},{"t":"Choreographer","cs":true,"vi":"Lớp của Android nhận tín hiệu vsync và đánh thức UI thread xử lý input, animation, layout và vẽ frame đúng nhịp màn hình."},{"t":"swap interval","vi":"Số chu kỳ vblank chờ trước khi lật buffer mới lên màn hình; swap interval 0 nghĩa là lật ngay, giảm latency nhưng có thể gây tearing."},{"t":"deadlock","aka":["deadlocks"],"vi":"Tình trạng hai hay nhiều thread, process chờ tài nguyên của nhau vô hạn nên không ai tiến được. Có thể xảy ra qua fence chờ sai chỗ hoặc backend dùng chung giữa VM."},{"t":"immediate","vi":"Present mode của Vulkan đưa frame lên màn hình ngay không chờ vblank: latency thấp nhất nhưng có thể gây tearing. Không phù hợp cho telltale và đồng hồ cluster."},{"t":"time slicing","vi":"Chia tài nguyên như CPU, GPU theo các lát thời gian luân phiên giữa nhiều VM hoặc context, thường kèm priority. Khả năng giữ deadline của cluster phụ thuộc độ dài lát và khả năng preempt."},{"t":"tuner","aka":["tuners"],"vi":"Khối thu sóng radio phát thanh FM, AM hoặc DAB, là một nguồn âm thanh của hệ thống infotainment."},{"t":"MIPS","full":"Million Instructions Per Second","cs":true,"vi":"Đơn vị đo năng lực xử lý, dùng để chia ngân sách tính toán của DSP audio giữa EQ, AEC, RNC, ICC… Tài nguyên MIPS hữu hạn nên thêm chức năng phải đánh đổi."},{"t":"exclusive","vi":"Kết quả trong focus interaction matrix: context mới nhận focus và context đang giữ phải dừng hoặc tạm ngưng phát."},{"t":"concurrent","vi":"Kết quả trong focus interaction matrix: context mới và context đang giữ cùng phát, thường hạ âm lượng nguồn kém ưu tiên (duck)."},{"t":"short to ground","aka":["short to battery","short to ground/battery"],"vi":"Lỗi điện khi dây tín hiệu hoặc loa chập xuống mass; tương tự short to battery là chập lên nguồn. Cùng open circuit là các lỗi phần cứng cần phát hiện và báo DTC."},{"t":"V2X","full":"Vehicle-to-Everything","cs":true,"vi":"Giao tiếp không dây giữa xe với xe, hạ tầng, người đi bộ và mạng. Là một entry point tấn công từ xa cần đưa vào phân tích threat."},{"t":"Xen","cs":true,"vi":"Hypervisor type-1 mã nguồn mở, có biến thể và hoạt động hướng tới ô tô và safety. Là một lựa chọn bên cạnh QNX Hypervisor, PikeOS, COQOS cho CDC."},{"t":"communication fabric","aka":["fabric"],"vi":"Hạ tầng giao tiếp chung của runtime: middleware, transport và cơ chế IPC giữa VM, process và ECU. Là một trong các thành phần của runtime architecture."},{"t":"EcuM","full":"ECU State Manager","cs":true,"vi":"Module AUTOSAR Classic quản lý khởi động, shutdown, sleep và wakeup của ECU. Tương ứng một phần Execution/State Management ở Adaptive."},{"t":"BswM","full":"Basic Software Mode Manager","cs":true,"vi":"Module AUTOSAR Classic điều phối mode của basic software theo rule, ví dụ bật tắt communication khi đổi trạng thái ECU."},{"t":"notifier","aka":["notifiers"],"vi":"Phần event của một field trong SOME/IP/ara::com, gửi giá trị mới khi field thay đổi. App nên dựa vào notifier thay vì tự suy trạng thái từ lệnh đã gửi."},{"t":"ara::exec","cs":true,"vi":"Namespace API của AUTOSAR Adaptive để process báo trạng thái cho Execution Management, ví dụ báo đã chạy xong init."},{"t":"SD","full":"Service Discovery","cs":true,"vi":"Phần SOME/IP-SD dùng OfferService, FindService, Subscribe và TTL để service và consumer tìm thấy nhau. Sự kiện SD như stop offer, hết TTL là dữ liệu quan trọng khi debug."},{"t":"APPENDABLE","cs":true,"vi":"Kiểu extensibility của DDS XTypes cho phép thêm member mới vào cuối kiểu dữ liệu mà vẫn tương thích. Khác FINAL (không đổi) và MUTABLE (thêm, bớt tự do hơn)."},{"t":"expand–migrate–contract","aka":["expand → migrate → contract","expand/contract"],"vi":"Quy trình đổi contract breaking mà không làm gãy fleet: thêm cái mới song song (expand), chuyển consumer sang (migrate), rồi mới bỏ cái cũ (contract)."},{"t":"cellular","vi":"Kết nối mạng di động như LTE, 5G qua TCU hoặc head unit. Là entry point từ xa, cho phép tấn công nhiều xe cùng lúc nếu có lỗ hổng."},{"t":"ADB","full":"Android Debug Bridge","cs":true,"vi":"Công cụ dòng lệnh để debug, cài app, mở shell trên thiết bị Android. Trên xe production phải tắt hoặc chỉ bật ở build engineering, không mở qua mạng."},{"t":"Uptane","cs":true,"vi":"Khung bảo mật mở cho OTA trên xe, dùng nhiều vai trò khóa và metadata ký số để chống giả mạo, rollback ngay cả khi một phần backend bị chiếm."},{"t":"security bulletin","aka":["security bulletins","bulletin"],"vi":"Bản tin định kỳ của vendor, ví dụ Android Security Bulletin hằng tháng, liệt kê lỗ hổng và bản vá. Khi phiên bản hết hỗ trợ, OEM phải tự backport."},{"t":"severe","vi":"Mức tác động cao nhất trong thang severe / major / moderate / negligible của ISO/SAE 21434, đánh giá cho safety, financial, operational, privacy."},{"t":"canary","vi":"Phát hành cho một nhóm nhỏ xe trước, theo dõi health metric với ngưỡng dừng rõ, rồi mới mở rộng dần cho fleet."},{"t":"ART","full":"Android Runtime","cs":true,"vi":"Môi trường chạy ứng dụng Android, biên dịch và thực thi bytecode của app. Là execution environment của phần Android trong CDC."},{"t":"diagnostic entity","aka":["diagnostic entities"],"vi":"Thực thể chẩn đoán mà tester nhìn thấy như một ECU, gom DTC từ QNX, Android và MCU. Ai sở hữu nó là một quyết định owner quan trọng trong CDC."},{"t":"alive supervision","aka":["alive monitoring","alive"],"vi":"Kiểu giám sát của WdgM/PHM kiểm tra tác vụ báo checkpoint đủ số lần trong một chu kỳ. Đi cùng deadline và logical supervision."},{"t":"MY","full":"Model Year","cs":true,"vi":"Năm mẫu dùng để đặt tên phiên bản dòng xe, ví dụ MY27. Lịch phần mềm thường bám theo SOP của từng MY."},{"t":"hysteresis","vi":"Dùng ngưỡng kích hoạt và khôi phục khác nhau để trạng thái không bật tắt liên tục quanh một ngưỡng. Cần cho load shedding và chuyển degraded."},{"t":"gold-plating","vi":"Thêm tính năng, abstraction hoặc độ hoàn thiện vượt nhu cầu thực tế. Ví dụ: enabler không có feature tương lai cụ thể sẽ dùng."},{"t":"technical debt quadrant","vi":"Mô hình của Martin Fowler phân loại nợ kỹ thuật theo hai trục reckless/prudent và deliberate/inadvertent, giúp quyết định cách xử lý mỗi khoản nợ."},{"t":"reckless","vi":"Trong technical debt quadrant: nợ sinh ra do cẩu thả, không cân nhắc hậu quả."},{"t":"prudent","vi":"Trong technical debt quadrant: nợ được chấp nhận sau khi cân nhắc, có hiểu biết về hậu quả."},{"t":"deliberate","vi":"Trong technical debt quadrant: nợ được tạo ra có chủ đích, biết rõ đang đi tắt."},{"t":"inadvertent","vi":"Trong technical debt quadrant: nợ sinh ra không chủ đích, thường chỉ nhận ra sau khi hiểu vấn đề rõ hơn."},{"t":"No Silver Bullet","vi":"Bài luận của Fred Brooks (1986) cho rằng không có công nghệ đơn lẻ nào tăng năng suất phần mềm gấp bội, và chia complexity thành essential và accidental."},{"t":"Localization","aka":["localization"],"vi":"Điều chỉnh phần mềm theo thị trường: ngôn ngữ, đơn vị đo, định dạng. Nên tách khỏi code thành dữ liệu cấu hình để thêm thị trường không cần sửa code."},{"t":"fork","aka":["Fork","forks"],"vi":"Tách codebase thành bản riêng phát triển độc lập, ví dụ fork theo SoC. Dễ lúc đầu nhưng chi phí merge và bảo trì tăng dần."},{"t":"anchoring","vi":"Thiên kiến nhận thức khi người quyết định bám vào con số hay phương án nghe đầu tiên. Giảm bằng chuẩn bị tiêu chí và thang đo trước khi xem phương án."},{"t":"sunk cost","aka":["sunk costs","sunk cost fallacy"],"vi":"Chi phí đã chi và không lấy lại được; không nên dùng làm lý do tiếp tục một phương án. Quyết định chỉ nên dựa trên chi phí và lợi ích từ nay về sau."},{"t":"do nothing","vi":"Phương án giữ nguyên hiện trạng, luôn đưa vào so sánh. Phương án mới phải thắng cả chi phí chuyển đổi so với do nothing."},{"t":"SEI","full":"Software Engineering Institute","cs":true,"vi":"Viện nghiên cứu kỹ nghệ phần mềm tại Carnegie Mellon University, nổi với quality attribute scenario và phương pháp đánh giá kiến trúc ATAM."},{"t":"considered options","aka":["Considered options"],"vi":"Mục trong ADR (ví dụ mẫu MADR) liệt kê các phương án đã cân nhắc kèm ưu, nhược điểm, giúp người sau hiểu vì sao phương án được chọn."},{"t":"what would change our mind","vi":"Câu hỏi ghi trong ADR: evidence hay điều kiện nào sẽ khiến nhóm xem lại quyết định. Giúp quyết định không bị giữ chỉ vì đã lỡ chọn."},{"t":"FMEA","full":"Failure Mode and Effects Analysis","cs":true,"vi":"Phân tích từ dưới lên: mỗi failure mode của phần tử gây tác động gì, mức nghiêm trọng ra sao và đã có biện pháp gì. Bổ sung cho FTA đi từ trên xuống."},{"t":"odometer","aka":["Odometer"],"vi":"Giá trị tổng quãng đường xe đã chạy, hiển thị trên cluster và có ý nghĩa pháp lý. Phải ghi vào NVM sao cho không mất hoặc lùi khi mất điện đột ngột."},{"t":"unambiguous","aka":["Unambiguous"],"vi":"Đặc tính requirement tốt theo ISO/IEC/IEEE 29148: chỉ có một cách hiểu. Tránh từ mơ hồ như “nhanh”, “hợp lý”, “v.v.”."},{"t":"necessary","vi":"Đặc tính requirement tốt theo ISO/IEC/IEEE 29148: bỏ đi thì sản phẩm thiếu khả năng hoặc đặc tính cần có."},{"t":"singular","vi":"Đặc tính requirement tốt theo ISO/IEC/IEEE 29148: mỗi requirement chỉ nêu một khả năng hoặc ràng buộc, không gộp bằng “và/hoặc”."},{"t":"conforming","vi":"Đặc tính requirement tốt theo ISO/IEC/IEEE 29148: viết theo mẫu, cấu trúc và quy ước đã thống nhất của dự án."},{"t":"steady state","vi":"Trạng thái hệ thống chạy ổn định sau boot, phân biệt với cold boot và peak. Budget tài nguyên nên được đặt và đo riêng cho từng trạng thái."},{"t":"low-memory killer","aka":["LMK"],"vi":"Cơ chế Android chọn và dừng process ít quan trọng khi bộ nhớ thấp. Trên CDC phải cấu hình theo memory budget để không giết nhầm service quan trọng."},{"t":"single writer","aka":["Single writer"],"vi":"Nguyên tắc chỉ một component được ghi một dữ liệu, các bên khác chỉ đọc. Tránh xung đột và giúp xác định owner khi dữ liệu sai."},{"t":"rolling counter","aka":["rolling counters"],"vi":"Bộ đếm tăng theo mỗi bản tin và quay vòng khi đạt max, giúp receiver phát hiện bản tin mất, lặp hoặc sai thứ tự. Là thành phần của E2E protection."},{"t":"masquerade","vi":"Lỗi khi bản tin từ nguồn khác bị nhận như bản tin hợp lệ, ví dụ do cấu hình sai ID. E2E dùng Data ID để phát hiện."},{"t":"telemetry ingest","aka":["ingest"],"vi":"Dịch vụ backend nhận, kiểm tra và lưu dữ liệu telemetry gửi từ fleet. Cần chịu được tải khi nhiều xe gửi lại cùng lúc."},{"t":"functional suitability","vi":"Đặc tính chất lượng ISO/IEC 25010: chức năng có đầy đủ, đúng và phù hợp với nhiệm vụ của người dùng (completeness, correctness, appropriateness)."},{"t":"appropriateness","vi":"Đặc tính con của functional suitability trong ISO/IEC 25010: chức năng giúp hoàn thành nhiệm vụ và mục tiêu của người dùng."},{"t":"performance efficiency","vi":"Đặc tính chất lượng ISO/IEC 25010 về thời gian đáp ứng, mức dùng tài nguyên và capacity. Với CDC gồm boot time, latency hiển thị, CPU/GPU/memory."},{"t":"co-existence","vi":"Đặc tính con của compatibility trong ISO/IEC 25010: sản phẩm chạy chung môi trường, tài nguyên với sản phẩm khác mà không gây ảnh hưởng xấu."},{"t":"learnability","vi":"Đặc tính con của interaction capability trong ISO/IEC 25010: người dùng học được cách dùng hiệu quả trong thời gian hợp lý."},{"t":"operability","vi":"Đặc tính con của interaction capability trong ISO/IEC 25010: sản phẩm dễ thao tác và điều khiển. Với HMI xe gồm thao tác được khi đang lái."},{"t":"faultlessness","vi":"Đặc tính con của reliability trong ISO/IEC 25010:2023 (trước gọi là maturity): sản phẩm thực hiện chức năng không lỗi khi vận hành bình thường."},{"t":"recoverability","vi":"Đặc tính con của reliability trong ISO/IEC 25010: sau sự cố, sản phẩm khôi phục được dữ liệu và trạng thái mong muốn."},{"t":"accountability","vi":"Đặc tính con của security trong ISO/IEC 25010: hành động của một chủ thể truy vết được về chính chủ thể đó, ví dụ qua log có xác thực."},{"t":"modularity","vi":"Đặc tính con của maintainability trong ISO/IEC 25010: hệ thống gồm các thành phần rời, thay đổi một phần ít ảnh hưởng phần khác."},{"t":"reusability","vi":"Đặc tính con của maintainability trong ISO/IEC 25010: thành phần dùng được cho nhiều hệ thống hoặc dự án khác."},{"t":"code assist","vi":"Công cụ AI gợi ý và sinh code, test, tóm tắt log ngay trong môi trường phát triển. Output vẫn phải qua review và gate như code thường."},{"t":"IT","full":"Information Technology","cs":true,"vi":"Hệ thống công nghệ thông tin thông thường như máy chủ, điện thoại, ứng dụng văn phòng. Bảo mật xe khó hơn IT vì phải hỗ trợ 10–15 năm."},{"t":"Driving","cs":true,"vi":"Một vehicle mode, ví dụ bên cạnh Parking và OTA; State Management chuyển function group theo mode này để quyết định process nào chạy."},{"t":"cost per vehicle","vi":"Chi phí phân bổ cho mỗi xe, ví dụ cloud, license, data. Phải tính cả egress và exit cost, và nhân theo số năm vận hành của fleet."},{"t":"analysability","aka":["analyzability"],"vi":"Đặc tính con của maintainability trong ISO/IEC 25010: mức độ dễ chẩn đoán lỗi, tìm nguyên nhân hoặc xác định phần cần sửa. Với CDC, log, trace và kiến trúc rõ ràng làm tăng analysability."},{"t":"testability","vi":"Đặc tính con của maintainability trong ISO/IEC 25010: mức độ dễ đặt tiêu chí kiểm thử và thực hiện test cho một thành phần. Interface tách bạch, có thể mock và chạy trên host làm tăng testability."},{"t":"adaptability","vi":"Đặc tính chất lượng trong ISO/IEC 25010 (nhóm portability/flexibility): phần mềm có thể chuyển sang phần cứng, OS hoặc môi trường vận hành khác với công sức hợp lý, ví dụ đổi SoC hay biến thể xe."},{"t":"replaceability","vi":"Đặc tính chất lượng trong ISO/IEC 25010: mức độ một sản phẩm/thành phần có thể thay cho thành phần khác cùng mục đích trong cùng môi trường, ví dụ đổi một stack Bluetooth hay map engine mà không sửa phần còn lại."},{"t":"hazard warning","vi":"Cảnh báo về một mối nguy (hazard) được đưa ra cho người dùng để họ tránh hoặc giảm rủi ro; trong bối cảnh an toàn, đây là một biện pháp giảm thiểu bên cạnh fail safe và ràng buộc vận hành."},{"t":"single point of failure","vi":"Thành phần mà nếu hỏng thì cả hệ thống ngừng hoạt động vì không có dự phòng. Ví dụ facade của strangler fig trở thành single point of failure nếu không có HA."},{"t":"rehost","vi":"Một trong các chiến lược \"R\" khi di chuyển hệ thống lên cloud: đưa ứng dụng sang hạ tầng mới gần như nguyên trạng (lift-and-shift), không sửa kiến trúc."},{"t":"replatform","vi":"Chiến lược \"R\" khi di chuyển lên cloud: chuyển ứng dụng sang nền tảng mới kèm một số tối ưu nhỏ (ví dụ dùng database dịch vụ quản lý) nhưng không viết lại kiến trúc."},{"t":"repurchase","vi":"Chiến lược \"R\" khi di chuyển lên cloud: bỏ ứng dụng tự xây và chuyển sang sản phẩm thương mại có sẵn, thường dưới dạng SaaS."},{"t":"HA","full":"High Availability","cs":true,"vi":"Thiết kế để dịch vụ tiếp tục chạy khi một node hoặc thành phần hỏng, nhờ dự phòng và chuyển đổi tự động. Ví dụ facade đứng trước monolith phải có HA vì mọi request đều đi qua nó."},{"t":"cross-compile","aka":["cross-compilation","cross-compiler"],"vi":"Biên dịch mã trên máy phát triển (thường x86) để tạo binary chạy trên kiến trúc đích khác như ARM của SoC hoặc MCU. Toolchain cross-compile phải được version và lưu trữ để có thể build lại sau nhiều năm."},{"t":"RC","full":"Release Candidate","cs":true,"vi":"Bản build đã đóng tính năng, được đưa vào kiểm thử cuối; nếu không có lỗi chặn thì chính bản này được phát hành."},{"t":"evidence bundle","vi":"Tập tài liệu và kết quả đi kèm một release (test report, traceability, kết quả phân tích, phê duyệt) để chứng minh bản phát hành đáp ứng yêu cầu, phục vụ audit, assessment hay homologation."},{"t":"POI","full":"Point of Interest","cs":true,"vi":"Địa điểm có ý nghĩa với người dùng trên bản đồ dẫn đường như trạm sạc, nhà hàng, bãi đỗ; thường lấy qua API cloud nên cần xử lý timeout và cache."},{"t":"live traffic","vi":"Dữ liệu tình trạng giao thông cập nhật liên tục qua kết nối mạng, hiển thị trên bản đồ và dùng để tính tuyến; khi mất kết nối, navigation vẫn chạy offline và chỉ ẩn live traffic."},{"t":"NIST","full":"National Institute of Standards and Technology","cs":true,"vi":"Viện Tiêu chuẩn và Công nghệ Quốc gia Hoa Kỳ, ban hành nhiều khung tham chiếu về an ninh mạng và AI như NIST CSF hay NIST AI RMF."},{"t":"NIST AI RMF","aka":["AI RMF"],"full":"NIST AI Risk Management Framework","vi":"AI Risk Management Framework do NIST công bố năm 2023, tổ chức việc quản lý rủi ro AI theo bốn chức năng Govern, Map, Measure, Manage."},{"t":"wafer","vi":"Tấm silicon mỏng trên đó các chip được chế tạo hàng loạt trước khi cắt và đóng gói; năng lực sản xuất wafer ở đầu chuỗi cung ứng quyết định nguồn cung SoC/MCU cho xe."},{"t":"RFI","full":"Request for Information","cs":true,"vi":"Bước đầu của sourcing: OEM gửi cho các nhà cung cấp tiềm năng để thu thập thông tin năng lực, công nghệ, lộ trình trước khi phát RFQ báo giá."},{"t":"sourcing","vi":"Quá trình mua hàng của OEM để tìm, đánh giá và chọn nhà cung cấp (RFI, RFQ, đánh giá kỹ thuật/thương mại) cho một linh kiện hay hệ thống."},{"t":"premium","vi":"Biến thể cấu hình cao của một dòng xe với nhiều tính năng hơn, ví dụ cluster lớn hơn và có HUD; phần mềm CDC phải hỗ trợ cả bản base và premium từ cùng một nền tảng."},{"t":"longevity program","vi":"Chương trình của nhà sản xuất chip cam kết tiếp tục sản xuất và hỗ trợ một linh kiện trong thời gian dài (thường 10–15 năm), quan trọng với vòng đời xe."},{"t":"TTM","full":"Time To Market","cs":true,"vi":"Khoảng thời gian từ khi bắt đầu phát triển đến khi sản phẩm được bán; nền tảng và interface chuẩn hóa giúp rút ngắn TTM cho chương trình xe sau."},{"t":"nice-to-have","vi":"Tính năng hoặc yêu cầu mong muốn nhưng không bắt buộc cho mốc phát hành; là ứng viên đầu tiên bị cắt hoặc dời sau SOP khi thiếu nguồn lực."},{"t":"MoSCoW","full":"Must have, Should have, Could have, Won't have","cs":true,"vi":"Kỹ thuật ưu tiên chia yêu cầu thành Must have, Should have, Could have, Won't have (this time), dùng để tách phạm vi SOP và sau SOP."},{"t":"Is/Is-not","aka":["Is-not","Is / Is-not"],"cs":true,"vi":"Kỹ thuật khoanh vùng vấn đề (dùng trong 8D, Kepner-Tregoe): mô tả lỗi IS ở đâu, khi nào, bao nhiêu và đối chiếu với IS NOT – nơi lẽ ra có thể có lỗi nhưng không có – để thu hẹp nguyên nhân."},{"t":"6M","cs":true,"vi":"Sáu nhóm nguyên nhân gốc của biểu đồ fishbone trong sản xuất; khi áp dụng cho phần mềm CDC thường được đổi thành các nhóm như code, cấu hình, build, môi trường, dữ liệu, con người."},{"t":"interim containment action","aka":["ICA"],"vi":"Biện pháp tạm thời (bước D3 của 8D) để bảo vệ khách hàng khỏi lỗi trong khi chưa tìm ra nguyên nhân gốc; phải được kiểm chứng là có hiệu quả."},{"t":"tombstone","vi":"File Android ghi khi một tiến trình native crash, gồm signal, backtrace, thanh ghi và bản đồ bộ nhớ; là bằng chứng quan trọng khi điều tra lỗi trên CDC."},{"t":"crank","aka":["cranking"],"vi":"Lúc khởi động động cơ, motor đề kéo dòng lớn làm điện áp nguồn 12 V sụt sâu trong thời gian ngắn; ECU như CDC phải chịu được hoặc reset đúng cách theo profile crank."},{"t":"climate chamber","vi":"Buồng thử nghiệm điều khiển nhiệt độ (và độ ẩm) để chạy thiết bị ở điều kiện cực nóng/lạnh, dùng để tái hiện lỗi phụ thuộc nhiệt độ của CDC."},{"t":"postmortem","aka":["post-mortem"],"vi":"Buổi/tài liệu phân tích sau sự cố: diễn biến, tác động, nguyên nhân gốc và hành động cải tiến."},{"t":"assessor","vi":"Người đánh giá độc lập (ví dụ ASPICE assessor hoặc functional safety assessor theo ISO 26262) kiểm tra quy trình và bằng chứng để chấm mức năng lực hoặc kết luận về sự tuân thủ."},{"t":"Adreno","vi":"Họ GPU tích hợp trong SoC Qualcomm Snapdragon, bao gồm các SoC cockpit dùng cho CDC."},{"t":"VPU","full":"Video Processing Unit","cs":true,"vi":"Khối phần cứng chuyên giải mã/mã hóa video trong SoC, giảm tải cho CPU/GPU khi phát media hoặc xử lý luồng camera."},{"t":"Mesa","vi":"Dự án mã nguồn mở hiện thực OpenGL, OpenGL ES, Vulkan cho nhiều GPU trên Linux; là lựa chọn thay cho driver độc quyền của vendor."},{"t":"AHardwareBuffer","vi":"Đối tượng buffer của Android NDK, cấp phát qua gralloc, có thể chia sẻ giữa CPU, GPU, camera, codec và tiến trình mà không phải copy."},{"t":"GBM","full":"Generic Buffer Management","cs":true,"vi":"API (thuộc Mesa) để cấp phát buffer có thể render bằng GPU và scanout bằng DRM/KMS, thường dùng khi chạy EGL không có hệ thống cửa sổ."},{"t":"pmem","vi":"Driver/cơ chế cấp phát bộ nhớ vật lý liền kề kiểu cũ trên một số nền tảng Android vendor, dùng cho buffer màn hình, camera; nay phần lớn được thay bằng ION/DMA-BUF heap."},{"t":"Kanzi","vi":"Bộ công cụ và runtime HMI của Rightware, phổ biến để xây cluster và giao diện 3D trên xe."},{"t":"Qt Quick","vi":"Framework UI của Qt viết bằng QML, được tăng tốc GPU, thường dùng cho HMI cluster và IVI trên Linux/QNX."},{"t":"Unity/Unreal","vi":"Hai game engine thương mại (Unity, Unreal Engine) được dùng để dựng HMI 3D như mô phỏng xe hay bản đồ; cần lưu ý chi phí GPU, bộ nhớ và thời gian khởi động."},{"t":"Jetpack Compose","vi":"Toolkit UI khai báo hiện đại của Android viết bằng Kotlin, thay cho Android View truyền thống; vẫn render qua HWUI."},{"t":"glFinish","vi":"Lệnh OpenGL buộc CPU chờ đến khi mọi lệnh GPU trước đó hoàn tất; gọi không cần thiết sẽ phá song song CPU–GPU và gây mất frame."},{"t":"vkQueueWaitIdle","vi":"Hàm Vulkan chặn CPU đến khi mọi công việc đã gửi vào queue hoàn tất; nên thay bằng fence/semaphore để đồng bộ chi tiết hơn."},{"t":"gamma","vi":"Đường cong ánh xạ giá trị màu sang độ sáng hiển thị; DPU thường có bảng gamma/LUT để hiệu chỉnh màu theo tấm màn hình."},{"t":"LCD","full":"Liquid Crystal Display","cs":true,"vi":"Công nghệ màn hình dùng tinh thể lỏng và đèn nền (backlight), phổ biến cho cluster và màn hình trung tâm."},{"t":"OLED","full":"Organic Light-Emitting Diode","cs":true,"vi":"Công nghệ màn hình mỗi điểm ảnh tự phát sáng, không cần backlight, cho màu đen sâu; cần chú ý hiện tượng burn-in với nội dung tĩnh như telltale."},{"t":"modifier","vi":"Trong DRM/KMS, modifier đi kèm pixel format để mô tả cách bố trí bộ nhớ của buffer (linear, tiled, nén như AFBC); producer và consumer phải thống nhất modifier."},{"t":"RGB565","cs":true,"vi":"Định dạng màu 16 bit (5 bit đỏ, 6 bit xanh lá, 5 bit xanh dương), tốn một nửa băng thông so với RGBA8888 nhưng ít màu hơn và không có alpha."},{"t":"NV12","cs":true,"vi":"Định dạng YUV 4:2:0 với một mặt phẳng Y và một mặt phẳng UV xen kẽ, trung bình 1,5 byte mỗi pixel; là định dạng đầu ra phổ biến của decoder video và camera."},{"t":"tiled","vi":"Kiểu bố trí pixel theo các khối ô nhỏ thay vì từng dòng tuyến tính, giúp GPU truy cập cache hiệu quả hơn; consumer phải hiểu được layout này."},{"t":"AFBC","full":"Arm Frame Buffer Compression","cs":true,"vi":"Định dạng nén không mất dữ liệu của Arm cho framebuffer, dùng trên GPU Mali và DPU hỗ trợ, giảm băng thông DRAM nhưng mọi bên đọc/ghi phải hỗ trợ."},{"t":"contiguous","vi":"Vùng bộ nhớ có địa chỉ vật lý liên tục, cần cho thiết bị không có IOMMU; nếu có IOMMU thì buffer có thể phân mảnh vật lý nhưng liền kề trong không gian địa chỉ của thiết bị."},{"t":"CRTC","full":"Cathode Ray Tube Controller","cs":true,"vi":"Trong DRM/KMS, CRTC là khối trộn các plane và sinh luồng pixel cùng timing (vsync) đưa tới encoder rồi connector; tên gốc từ Cathode Ray Tube Controller."},{"t":"encoder","vi":"Trong DRM/KMS, encoder chuyển luồng pixel từ CRTC thành tín hiệu cho loại kết nối cụ thể như DSI, LVDS, HDMI, eDP trước khi tới connector."},{"t":"semaphore","vi":"Cơ chế đồng bộ; trong Vulkan, semaphore đồng bộ giữa các queue GPU (ví dụ render xong mới present), còn fence dùng để CPU chờ GPU."},{"t":"motion-to-photon","vi":"Độ trễ đầu-cuối từ lúc người dùng thao tác hoặc chuyển động xảy ra đến khi photon thay đổi trên màn hình; quan trọng với cảm giác phản hồi touch, rotary và HUD AR."},{"t":"rotary","vi":"Bộ điều khiển dạng núm xoay/nhấn trên console để thao tác HMI mà không chạm màn hình; độ trễ phản hồi của nó ảnh hưởng trực tiếp đến cảm nhận người dùng."},{"t":"AR","full":"Augmented Reality","cs":true,"vi":"Chồng thông tin đồ họa lên cảnh thật, ví dụ HUD AR vẽ mũi tên dẫn đường đúng vị trí trên mặt đường; đòi hỏi độ trễ thấp và ổn định."},{"t":"e-mirror","vi":"Hệ thống thay gương chiếu hậu bằng camera và màn hình; là chức năng liên quan an toàn với yêu cầu chặt về độ trễ và khả dụng của hình ảnh."},{"t":"raster","vi":"Giai đoạn rasterization trong pipeline GPU: chuyển tam giác sau xử lý vertex thành các fragment ứng với pixel trên màn hình."},{"t":"primitive","vi":"Đơn vị hình học cơ bản GPU xử lý (điểm, đường, tam giác); mức primitive là một mức chi tiết GPU có thể ngắt để preemption."},{"t":"tile","vi":"Vùng nhỏ của màn hình mà GPU kiến trúc tile-based (như Mali, Adreno, PowerVR) render lần lượt trong bộ nhớ on-chip; ranh giới tile là một mức preemption."},{"t":"PV","full":"Para-Virtualization","cs":true,"vi":"Kỹ thuật ảo hóa trong đó guest dùng driver/giao tiếp được sửa để làm việc trực tiếp với hypervisor hoặc backend (ví dụ VirtIO) thay vì giả lập phần cứng đầy đủ."},{"t":"FrameTimeline","vi":"Tính năng của Android/Perfetto ghi thời điểm dự kiến và thực tế của từng frame qua app và SurfaceFlinger, tự phân loại jank và nguyên nhân."},{"t":"Snapdragon Profiler","vi":"Công cụ của Qualcomm để đo hiệu năng CPU, GPU, bộ nhớ và chụp frame trên SoC Snapdragon."},{"t":"Arm Mobile Studio","vi":"Bộ công cụ của Arm (Streamline, Performance Advisor…) để phân tích hiệu năng CPU và GPU Mali."},{"t":"RenderDoc","vi":"Frame debugger mã nguồn mở cho Vulkan/OpenGL ES, cho phép chụp một frame và xem từng draw call, texture, trạng thái pipeline."},{"t":"RenderThread","vi":"Luồng riêng của mỗi app Android (HWUI) nhận display list từ UI thread, ghi lệnh GPU và gửi buffer cho SurfaceFlinger."},{"t":"dequeue","aka":["dequeueBuffer"],"vi":"Thao tác producer lấy một buffer rảnh từ BufferQueue để render vào; nếu mọi buffer đang bị giữ, producer phải chờ và gây trễ frame."},{"t":"queueBuffer","vi":"Thao tác producer gửi buffer đã render (kèm fence) vào BufferQueue để consumer như SurfaceFlinger lấy ra compose và hiển thị."},{"t":"partial update","vi":"Kỹ thuật chỉ render/gửi lại vùng thay đổi của frame để giảm tải; nếu đồng bộ sai có thể gây hiển thị lẫn nội dung cũ và mới."},{"t":"DAB","full":"Digital Audio Broadcasting","cs":true,"vi":"Chuẩn phát thanh kỹ thuật số dùng rộng rãi ở châu Âu, là một nguồn tuner bên cạnh FM trong hệ thống audio của CDC."},{"t":"beamforming","vi":"Kỹ thuật kết hợp tín hiệu nhiều micro để tăng độ nhạy theo hướng người nói và giảm âm từ hướng khác, ví dụ phân biệt người lái với hành khách."},{"t":"impedance","vi":"Trở kháng của loa hoặc mạch audio (ohm); amplifier và loa phải khớp trở kháng để đúng công suất và tránh quá tải."},{"t":"ITU-T","full":"International Telecommunication Union – Telecommunication Standardization Sector","cs":true,"vi":"Bộ phận tiêu chuẩn viễn thông của Liên minh Viễn thông Quốc tế, ban hành các khuyến nghị như P.1100/P.1110 về chất lượng gọi hands-free trên xe."},{"t":"P.1100/P.1110","aka":["P.1100","P.1110"],"cs":true,"vi":"Khuyến nghị ITU-T về yêu cầu và phương pháp đo chất lượng thoại hands-free trong xe: P.1100 cho băng hẹp, P.1110 cho băng rộng."},{"t":"AVTP","full":"Audio Video Transport Protocol","cs":true,"vi":"Giao thức IEEE 1722 đóng gói luồng audio/video trên Ethernet kèm presentation time để phát đồng bộ, dùng trong AVB/TSN."},{"t":"SRP","full":"Stream Reservation Protocol","cs":true,"vi":"Giao thức IEEE 802.1Qat của AVB để đăng ký và giữ trước băng thông qua các switch cho luồng audio/video, kết hợp với credit-based shaper."},{"t":"UN R16","aka":["R16"],"cs":true,"vi":"Quy định UNECE về dây an toàn và hệ thống giữ người, bao gồm yêu cầu cảnh báo nhắc thắt dây bằng âm thanh và hình ảnh."},{"t":"UN R138","aka":["R138"],"cs":true,"vi":"Quy định UNECE yêu cầu xe điện/hybrid phát âm thanh cảnh báo người đi đường khi chạy ở tốc độ thấp (AVAS)."},{"t":"UN R144","aka":["R144"],"cs":true,"vi":"Quy định UNECE về hệ thống gọi khẩn cấp sau tai nạn (AECS, tương ứng eCall), có yêu cầu riêng về micro, loa và nguồn điện."},{"t":"perception","vi":"Khối xử lý của ADAS dùng dữ liệu camera, radar, lidar để phát hiện và phân loại vật thể, làn đường, biển báo quanh xe."},{"t":"park assist","vi":"Chức năng ADAS hỗ trợ hoặc tự động thực hiện đỗ xe bằng cảm biến siêu âm và camera; thường hiển thị hình ảnh và cảnh báo trên màn hình của CDC."},{"t":"BMS","full":"Battery Management System","cs":true,"vi":"ECU giám sát và điều khiển pin cao áp của xe điện (điện áp, nhiệt độ, SOC, cân bằng cell), thuộc miền an toàn cao, tách khỏi CDC."},{"t":"COQOS","cs":true,"vi":"Sản phẩm hypervisor/nền tảng ảo hóa của OpenSynergy dùng cho cockpit, cho phép chạy Android và hệ điều hành khác trên cùng SoC."},{"t":"PikeOS","vi":"Hệ điều hành thời gian thực kiêm hypervisor phân vùng của SYSGO, có gói chứng nhận an toàn, dùng trong ô tô, hàng không, đường sắt."},{"t":"ACRN","cs":true,"vi":"Hypervisor type-1 mã nguồn mở thuộc Linux Foundation, hướng đến IoT và hệ nhúng, có kịch bản cho cockpit ô tô."},{"t":"getter","vi":"Trong SOME/IP và ara::com, field gồm getter (đọc giá trị hiện tại), setter và notifier (event khi giá trị đổi)."},{"t":"OfferService","aka":["StopOfferService"],"vi":"Entry của SOME/IP Service Discovery do server gửi để thông báo service instance đang được cung cấp, kèm TTL."},{"t":"FindService","vi":"Entry của SOME/IP Service Discovery do client gửi (thường multicast) để tìm service instance cần dùng."},{"t":"SubscribeEventgroup","vi":"Entry SOME/IP-SD client gửi để đăng ký nhận các event/field của một eventgroup; server trả Ack hoặc Nack."},{"t":"eventgroup","vi":"Nhóm logic các event và field của một service SOME/IP; client đăng ký theo eventgroup chứ không theo từng event."},{"t":"multicast","vi":"Cách gửi một gói tới một nhóm địa chỉ để nhiều node cùng nhận, dùng cho discovery của SOME/IP-SD và DDS."},{"t":"SPDP","full":"Simple Participant Discovery Protocol","cs":true,"vi":"Giao thức DDSI-RTPS để các DomainParticipant tự phát hiện nhau qua multicast định kỳ."},{"t":"SEDP","full":"Simple Endpoint Discovery Protocol","cs":true,"vi":"Giao thức DDSI-RTPS trao đổi thông tin DataReader/DataWriter giữa các participant để khớp topic, kiểu dữ liệu và QoS."},{"t":"DDSI-RTPS","full":"DDS Interoperability Wire Protocol – Real-Time Publish-Subscribe","cs":true,"vi":"Đặc tả OMG định nghĩa giao thức truyền trên mạng của DDS (Real-Time Publish-Subscribe), giúp các implementation DDS khác hãng giao tiếp được với nhau."},{"t":"participant","vi":"Trong DDS, DomainParticipant là điểm vào của ứng dụng vào một domain, chứa các publisher, subscriber, topic; được phát hiện qua SPDP."},{"t":"LIFESPAN","cs":true,"vi":"QoS của DDS quy định thời gian một mẫu dữ liệu còn hợp lệ; quá hạn thì bị bỏ, tránh consumer dùng dữ liệu cũ."},{"t":"liveliness","vi":"QoS của DDS để reader biết writer còn sống; nếu không nhận tín hiệu trong thời hạn, writer bị coi là mất và ứng dụng phải chuyển trạng thái."},{"t":"XTypes","vi":"Đặc tả OMG DDS-XTypes cho phép kiểu dữ liệu tiến hóa giữa các phiên bản với các kiểu extensibility FINAL, APPENDABLE, MUTABLE."},{"t":"extensibility","vi":"Thuộc tính của kiểu trong DDS XTypes: FINAL không đổi được, APPENDABLE chỉ thêm member ở cuối, MUTABLE thêm/bớt/đổi thứ tự member."},{"t":"TLV","full":"Tag-Length-Value","cs":true,"vi":"Kiểu serialization mỗi phần tử mang tag và độ dài, cho phép bên nhận bỏ qua member không biết; SOME/IP hỗ trợ TLV để thêm member optional mà vẫn tương thích."},{"t":"ACL","full":"Access Control List","cs":true,"vi":"Danh sách quy định chủ thể nào được làm gì với tài nguyên nào, ví dụ chỉ endpoint được cấp quyền mới được offer hoặc subscribe service."},{"t":"TLS","full":"Transport Layer Security","cs":true,"vi":"Giao thức bảo mật kênh truyền trên TCP, cung cấp mã hóa, toàn vẹn và xác thực bằng chứng chỉ; nền tảng của HTTPS và kết nối xe–cloud."},{"t":"DTLS","full":"Datagram Transport Layer Security","cs":true,"vi":"Biến thể của TLS cho giao thức datagram như UDP, dùng bảo vệ các kênh như SOME/IP qua UDP."},{"t":"IPsec","full":"Internet Protocol Security","cs":true,"vi":"Bộ giao thức xác thực và mã hóa gói tin ở tầng IP, bảo vệ mọi lưu lượng giữa hai nút bất kể giao thức tầng trên."},{"t":"MACsec","full":"Media Access Control Security","cs":true,"vi":"Chuẩn IEEE 802.1AE xác thực và mã hóa frame Ethernet giữa hai thiết bị kề nhau, phù hợp cho mạng Ethernet trong xe."},{"t":"HTTPS","full":"Hypertext Transfer Protocol Secure","cs":true,"vi":"HTTP được bảo vệ bằng TLS, dùng cho API cloud, tải gói OTA và telemetry từ xe."},{"t":"Jeep Cherokee","vi":"Năm 2015, Charlie Miller và Chris Valasek tấn công từ xa một chiếc Jeep Cherokee qua kết nối cellular của head unit rồi sang mạng CAN; FCA triệu hồi khoảng 1,4 triệu xe."},{"t":"FCA","full":"Fiat Chrysler Automobiles","cs":true,"vi":"Tập đoàn ô tô Fiat Chrysler Automobiles, sở hữu thương hiệu Jeep; năm 2021 sáp nhập với PSA thành Stellantis."},{"t":"continual activities","vi":"Nhóm hoạt động cybersecurity liên tục trong ISO/SAE 21434 (theo dõi, đánh giá sự kiện, phân tích và quản lý lỗ hổng) diễn ra suốt vòng đời, kể cả sau SOP."},{"t":"key fob","vi":"Thiết bị chìa khóa không dây dùng để mở khóa/khởi động xe; là một điểm vào tấn công tầm gần (relay attack)."},{"t":"OBD","full":"On-Board Diagnostics","cs":true,"vi":"Hệ thống và cổng chẩn đoán chuẩn trên xe (OBD-II), cho phép công cụ ngoài đọc lỗi và giao tiếp với ECU; là điểm vào tấn công vật lý."},{"t":"supply chain","vi":"Toàn bộ nhà cung cấp, thư viện, công cụ và quy trình tạo ra sản phẩm; tấn công supply chain cài mã độc hoặc lỗ hổng qua thành phần bên thứ ba."},{"t":"log hygiene","vi":"Thực hành ghi log không chứa khóa, mật khẩu, dữ liệu cá nhân, đồng thời đủ thông tin cho điều tra; quan trọng khi log CDC được gửi về cloud."},{"t":"BT","full":"Bluetooth","cs":true,"vi":"Viết tắt của Bluetooth; stack BT xử lý dữ liệu từ thiết bị bên ngoài nên là bề mặt tấn công tầm gần quan trọng của CDC."},{"t":"SecurityAccess","vi":"Dịch vụ UDS 0x27: tester xin seed, tính key và gửi lại để mở khóa các chức năng chẩn đoán được bảo vệ như ghi dữ liệu hay flash."},{"t":"UART","full":"Universal Asynchronous Receiver-Transmitter","cs":true,"vi":"Giao tiếp nối tiếp đơn giản thường dùng làm cổng console/debug; trên xe production phải khóa hoặc chỉ mở bằng quy trình có xác thực."},{"t":"SPDX","full":"Software Package Data Exchange","cs":true,"vi":"Định dạng chuẩn mở (Linux Foundation, ISO/IEC 5962) mô tả thành phần, license và nguồn gốc phần mềm, dùng làm SBOM."},{"t":"CycloneDX","vi":"Định dạng SBOM do OWASP phát triển, mô tả thành phần phần mềm, phụ thuộc và lỗ hổng, dùng trao đổi giữa OEM và supplier."},{"t":"SLTS","full":"Super Long-Term Support","cs":true,"vi":"Nhánh kernel Linux được CIP duy trì khoảng 10 năm trở lên, phù hợp vòng đời dài của sản phẩm công nghiệp và xe."},{"t":"CIP","full":"Civil Infrastructure Platform","cs":true,"vi":"Dự án thuộc Linux Foundation duy trì kernel SLTS và gói nền cho hệ thống công nghiệp cần hỗ trợ hàng chục năm."},{"t":"Android Security Bulletin","vi":"Bản tin Google phát hành hằng tháng liệt kê lỗ hổng và bản vá của Android; là một nguồn theo dõi lỗ hổng bắt buộc cho CDC chạy Android Automotive."},{"t":"C/I/A","full":"Confidentiality, Integrity, Availability","cs":true,"vi":"Ba thuộc tính an ninh thông tin cần bảo vệ của một tài sản; trong TARA dùng để xác định loại tác động khi tài sản bị tấn công."},{"t":"impact rating","vi":"Bước trong TARA của ISO/SAE 21434 đánh giá mức tác động của damage scenario theo nhóm S/F/O/P với các mức severe, major, moderate, negligible."},{"t":"S/F/O/P","full":"Safety, Financial, Operational, Privacy","cs":true,"vi":"Bốn nhóm tác động trong ISO/SAE 21434 dùng để đánh giá damage scenario: an toàn, tài chính, vận hành, quyền riêng tư; mỗi nhóm có mức severe/major/moderate/negligible."},{"t":"window of opportunity","vi":"Một yếu tố của attack potential trong ISO/SAE 21434: mức dễ dàng và thời gian kẻ tấn công có thể tiếp cận mục tiêu, cùng với thời gian, chuyên môn, hiểu biết và thiết bị."},{"t":"damage scenario","vi":"Trong TARA của ISO/SAE 21434, mô tả hậu quả bất lợi cho người dùng xe hoặc bên liên quan khi một thuộc tính an ninh của tài sản bị xâm phạm."},{"t":"discoverable","vi":"Trạng thái Bluetooth cho phép thiết bị khác quét thấy và ghép đôi; chỉ nên bật khi người dùng chủ động ghép đôi để giảm bề mặt tấn công."},{"t":"DevSecOps","vi":"Cách làm đưa các hoạt động bảo mật (quét mã, SBOM, quét lỗ hổng, ký build) vào pipeline CI/CD thay vì làm riêng ở cuối dự án."},{"t":"I/O aggregation","vi":"Trong kiến trúc zonal, zone controller gom cảm biến, chấp hành và tín hiệu I/O ở vùng gần nó rồi gửi lên central compute qua Ethernet, giảm dây dẫn."},{"t":"re-certify","aka":["recertify","re-certification"],"vi":"Thực hiện lại đánh giá/chứng nhận (an toàn, homologation, bảo mật) cho thành phần sau khi bị thay đổi; tốn kém nên tránh động vào phần đang ổn định."},{"t":"10BASE-T1S","vi":"Chuẩn Ethernet IEEE 802.3cg 10 Mbit/s trên một đôi dây, hỗ trợ bus đa điểm, nhắm thay CAN/LIN ở các nút nhỏ trong kiến trúc zonal."},{"t":"Franca IDL","vi":"Ngôn ngữ mô tả interface (IDL) từ cộng đồng GENIVI/COVESA, thường dùng với CommonAPI để sinh code cho SOME/IP hoặc D-Bus."},{"t":"OMG IDL","vi":"Interface Definition Language do Object Management Group chuẩn hóa, dùng mô tả kiểu dữ liệu và topic cho DDS."},{"t":"QNX Neutrino","vi":"Hệ điều hành thời gian thực kiến trúc microkernel của BlackBerry QNX, giao tiếp chủ yếu qua message passing; phổ biến cho cluster và hypervisor host."},{"t":"UFS","full":"Universal Flash Storage","cs":true,"vi":"Chuẩn lưu trữ flash tốc độ cao của JEDEC, thay eMMC trên SoC cockpit hiện đại; ảnh hưởng thời gian boot và độ bền ghi."},{"t":"bytecode","vi":"Mã trung gian không phải mã máy, được runtime thông dịch hoặc biên dịch; trên Android, ART chạy bytecode DEX của ứng dụng."},{"t":"MsgSend/MsgReceive","vi":"Cặp hàm IPC của QNX Neutrino: client gọi MsgSend và bị chặn đến khi server MsgReceive rồi MsgReply; server chậm sẽ làm client send-blocked."},{"t":"transaction","vi":"Trong Android Binder, transaction là một lần gọi IPC mang dữ liệu qua buffer có giới hạn kích thước; dữ liệu lớn phải truyền bằng shared memory."},{"t":"lmkd","vi":"Low Memory Killer Daemon của Android, theo dõi áp lực bộ nhớ và kill app nền theo mức ưu tiên khi thiếu RAM."},{"t":"RSS","full":"Resident Set Size","cs":true,"vi":"Lượng RAM vật lý một tiến trình đang chiếm thực tế, dùng theo dõi tiêu thụ bộ nhớ và phát hiện rò rỉ."},{"t":"mount","vi":"Thao tác gắn một file system (phân vùng, image) vào cây thư mục để truy cập; thứ tự mount là một bước trong chuỗi boot."},{"t":"Zygote","vi":"Tiến trình Android nạp sẵn runtime và thư viện framework, rồi fork ra tiến trình cho từng app để khởi động nhanh."},{"t":"CarPowerManagementService","vi":"Service của Android Automotive nhận trạng thái nguồn từ VHAL (do MCU điều phối) và điều phối suspend, shutdown, resume cho các thành phần Android."},{"t":"WdgM","full":"Watchdog Manager","cs":true,"vi":"Module AUTOSAR Classic giám sát alive, deadline và logical supervision của các entity phần mềm, kích hoạt phản ứng khi phát hiện lỗi."},{"t":"slog2","vi":"Hệ thống system logger của QNX, ghi log vào buffer bộ nhớ; cần gom cùng log Android và DLT để phân tích chung."},{"t":"R19-11","aka":["R20-11","R22-11"],"cs":true,"vi":"Cách đặt tên release AUTOSAR theo năm-tháng (R19-11 là tháng 11/2019); các stack ghép với nhau phải khớp release đặc tả."},{"t":"SW","full":"Software","cs":true,"vi":"Viết tắt của software, phần mềm."},{"t":"COM","aka":["Com"],"cs":true,"vi":"Module BSW của AUTOSAR Classic đóng gói tín hiệu vào PDU và ngược lại, xử lý timeout, lọc, gateway tín hiệu."},{"t":"Dem","full":"Diagnostic Event Manager","cs":true,"vi":"Module AUTOSAR Classic quản lý sự kiện lỗi, lưu DTC kèm dữ liệu môi trường và cung cấp cho chẩn đoán."},{"t":"TX","full":"Transmit","cs":true,"vi":"Viết tắt chiều truyền đi; counter TX đếm số khung/gói đã gửi, đối chiếu với RX bên nhận để tìm chỗ mất dữ liệu."},{"t":"Annex D","vi":"Phụ lục của ISO 26262-6 liệt kê các loại can nhiễu giữa phần tử phần mềm: timing và thực thi, bộ nhớ, trao đổi thông tin."},{"t":"API remoting","vi":"Kỹ thuật ảo hóa GPU trong đó guest không truy cập GPU trực tiếp mà gửi lời gọi API/lệnh tới server ở VM sở hữu GPU, ví dụ VirtIO-GPU."},{"t":"preemption granularity","vi":"Mức mà GPU có thể ngắt job đang chạy (draw call, primitive, tile, pixel); càng thô thì job ưu tiên cao như cluster chờ càng lâu."},{"t":"namespace","vi":"Cơ chế kernel Linux cho mỗi nhóm tiến trình một góc nhìn riêng về PID, mạng, mount, user…; cùng cgroups là nền của container."},{"t":"ARINC 653","vi":"Chuẩn hàng không định nghĩa phân vùng tĩnh về bộ nhớ và cửa sổ thời gian cố định cho từng partition; là hình mẫu cho phân vùng chặt trong hypervisor."},{"t":"trap","vi":"Khi guest thực hiện lệnh hoặc truy cập cần can thiệp, CPU trap sang hypervisor xử lý rồi quay lại; trap thường xuyên gây trễ cho VM."},{"t":"descriptor","vi":"Cấu trúc mô tả địa chỉ, độ dài và cờ của buffer trong hàng đợi (ví dụ virtqueue VirtIO); backend phải kiểm tra descriptor từ guest trước khi dùng."},{"t":"cache thrash","aka":["cache thrashing","thrashing"],"vi":"Hiện tượng dữ liệu trong cache bị đẩy ra liên tục do tranh chấp, khiến hầu hết truy cập phải đi ra DRAM; dùng để stress test can nhiễu giữa VM."},{"t":"regulate","vi":"Giới hạn lượng tài nguyên (ví dụ băng thông DRAM, GPU) một VM được dùng, để phần quan trọng như cluster giữ được phần đã reserve."},{"t":"PCP","full":"Priority Code Point","cs":true,"vi":"Trường 3 bit trong VLAN tag IEEE 802.1Q xác định mức ưu tiên của frame Ethernet, dùng cho QoS và TSN trên mạng xe."},{"t":"StbM","full":"Synchronized Time-Base Manager","cs":true,"vi":"Module AUTOSAR Classic cung cấp time base đồng bộ cho các thành phần phần mềm, nhận thời gian từ các module time sync như gPTP/CAN."},{"t":"ara::tsync","vi":"Functional cluster Time Synchronization của AUTOSAR Adaptive, cung cấp time base đồng bộ cho ứng dụng."},{"t":"EM/SM","full":"Execution Management / State Management","cs":true,"vi":"Cặp functional cluster của AUTOSAR Adaptive: EM khởi động/dừng process, SM quyết định trạng thái máy và function group cần chạy."},{"t":"W3C","full":"World Wide Web Consortium","cs":true,"vi":"Tổ chức chuẩn hóa web, ban hành W3C Trace Context để truyền trace ID qua các hop trong hệ phân tán."},{"t":"DLT Viewer","vi":"Công cụ mã nguồn mở (COVESA) để xem, lọc log DLT theo ECU ID, Application ID, Context ID và timestamp."},{"t":"priority inheritance","aka":["priority inheritance/ceiling"],"vi":"Giao thức trong đó task giữ mutex tạm được nâng lên ưu tiên của task cao nhất đang chờ, tránh priority inversion."},{"t":"priority ceiling","vi":"Giao thức gán cho mutex một mức trần ưu tiên; task giữ mutex chạy ở mức trần, tránh priority inversion và deadlock."},{"t":"SYS.4","cs":true,"vi":"Process ASPICE tích hợp các phần tử hệ thống và kiểm thử tích hợp, đối ứng với SYS.3 kiến trúc hệ thống trên V-model."},{"t":"SWE.3","cs":true,"vi":"Process ASPICE về thiết kế chi tiết phần mềm và viết unit, đối ứng với SWE.4 kiểm chứng unit."},{"t":"SWE.4","cs":true,"vi":"Process ASPICE kiểm chứng unit phần mềm (unit test, static analysis, review) so với thiết kế chi tiết SWE.3."},{"t":"SWE.5","cs":true,"vi":"Process ASPICE tích hợp phần mềm và kiểm thử tích hợp, đối ứng với SWE.2 kiến trúc phần mềm."},{"t":"SWE.6","cs":true,"vi":"Process ASPICE kiểm thử phần mềm hoàn chỉnh so với software requirement, đối ứng với SWE.1."},{"t":"detailed design","vi":"Mức thiết kế mô tả bên trong từng unit/component (thuật toán, dữ liệu, interface nội bộ), là đầu vào cho code và unit test."},{"t":"structural coverage","vi":"Độ phủ đo trên cấu trúc mã (statement, branch, MC/DC); ISO 26262-6 khuyến nghị mức phủ tăng dần theo ASIL."},{"t":"ageing","vi":"Độ tuổi của một mục mở (risk, lỗi, yêu cầu) tính từ khi tạo; theo dõi ageing giúp phát hiện risk cao bị bỏ quên."},{"t":"parent ID","vi":"Định danh yêu cầu gốc (thường của OEM) mà yêu cầu cấp dưới truy vết về, giữ traceability hai chiều giữa OEM và supplier."},{"t":"program sponsor","vi":"Người lãnh đạo cấp cao bảo trợ chương trình, nắm ngân sách và ra quyết định cuối khi có xung đột phạm vi, tiến độ, chi phí."}];
